window.LWA_DATA={"papers":[{"id":"c25s1","year":2025,"stage":"Tier-I","short":"Tier-I 2025 · 18 September S1","title":"SSC CGL 2025 Tier-I, 18 September 2025, Shift 1","notif":"Shift 1 (9:00 AM) · SSC key","held":"18 September 2025","fmt":"mcq","slug":"ssc-cgl-2025-tier-1-18-september-shift-1-question-paper-with-answers","blurb":"Tier-I: General Intelligence & Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, 25 questions each: 100 questions, 200 marks, 60 minutes, −0.50 for a wrong answer.","count":100,"key":"SSC's answer key as marked on the candidate's response sheet","alt":"Prelims","hi_paper":"टियर-1 (18 September, पाली 1)","kwname":"SSC CGL 2025 Tier 1 (18 September Shift 1)","mins":60,"pdf":"","kw":"SSC CGL 2025 Tier 1 (18 September Shift 1) (Prelims)"},{"id":"c25s2","year":2025,"stage":"Tier-I","short":"Tier-I 2025 · 18 September S2","title":"SSC CGL 2025 Tier-I, 18 September 2025, Shift 2","notif":"Shift 2 (12:30 PM) · SSC key","held":"18 September 2025","fmt":"mcq","slug":"ssc-cgl-2025-tier-1-18-september-shift-2-question-paper-with-answers","blurb":"Tier-I: General Intelligence & Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, 25 questions each: 100 questions, 200 marks, 60 minutes, −0.50 for a wrong answer.","count":100,"key":"SSC's answer key as marked on the candidate's response sheet","alt":"Prelims","hi_paper":"टियर-1 (18 September, पाली 2)","kwname":"SSC CGL 2025 Tier 1 (18 September Shift 2)","mins":60,"pdf":"","kw":"SSC CGL 2025 Tier 1 (18 September Shift 2) (Prelims)"},{"id":"c25s3","year":2025,"stage":"Tier-I","short":"Tier-I 2025 · 18 September S3","title":"SSC CGL 2025 Tier-I, 18 September 2025, Shift 3","notif":"Shift 3 (4:00 PM) · SSC key","held":"18 September 2025","fmt":"mcq","slug":"ssc-cgl-2025-tier-1-18-september-shift-3-question-paper-with-answers","blurb":"Tier-I: General Intelligence & Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, 25 questions each: 100 questions, 200 marks, 60 minutes, −0.50 for a wrong answer.","count":100,"key":"SSC's answer key as marked on the candidate's response sheet","alt":"Prelims","hi_paper":"टियर-1 (18 September, पाली 3)","kwname":"SSC CGL 2025 Tier 1 (18 September Shift 3)","mins":60,"pdf":"","kw":"SSC CGL 2025 Tier 1 (18 September Shift 3) (Prelims)"},{"id":"c24s1","year":2024,"stage":"Tier-I","short":"Tier-I 2024 · 9 September S1","title":"SSC CGL 2024 Tier-I, 9 September 2024, Shift 1","notif":"Shift 1 (9:00 AM) · SSC key","held":"9 September 2024","fmt":"mcq","slug":"ssc-cgl-2024-tier-1-9-september-shift-1-question-paper-with-answers","blurb":"Tier-I: General Intelligence & Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, 25 questions each: 100 questions, 200 marks, 60 minutes, −0.50 for a wrong answer.","count":100,"key":"SSC's answer key as marked on the candidate's response sheet","alt":"Prelims","hi_paper":"टियर-1 (9 September, पाली 1)","kwname":"SSC CGL 2024 Tier 1 (9 September Shift 1)","mins":60,"pdf":"","kw":"SSC CGL 2024 Tier 1 (9 September Shift 1) (Prelims)"},{"id":"c23s1","year":2023,"stage":"Tier-I","short":"Tier-I 2023 · 14 July S1","title":"SSC CGL 2023 Tier-I, 14 July 2023, Shift 1","notif":"Shift 1 (9:00 AM) · SSC key","held":"14 July 2023","fmt":"mcq","slug":"ssc-cgl-2023-tier-1-14-july-shift-1-question-paper-with-answers","blurb":"Tier-I: General Intelligence & Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, 25 questions each: 100 questions, 200 marks, 60 minutes, −0.50 for a wrong answer.","count":100,"key":"SSC's answer key as marked on the candidate's response sheet","alt":"Prelims","hi_paper":"टियर-1 (14 July, पाली 1)","kwname":"SSC CGL 2023 Tier 1 (14 July Shift 1)","mins":60,"pdf":"","kw":"SSC CGL 2023 Tier 1 (14 July Shift 1) (Prelims)"},{"id":"c24s2","year":2024,"stage":"Tier-I","short":"Tier-I 2024 · 9 September S2","title":"SSC CGL 2024 Tier-I, 9 September 2024, Shift 2","notif":"Shift 2 (12:30 PM) · SSC key","held":"9 September 2024","fmt":"mcq","slug":"ssc-cgl-2024-tier-1-9-september-shift-2-question-paper-with-answers","blurb":"Tier-I: General Intelligence & Reasoning, General Awareness, Quantitative Aptitude and English Comprehension, 25 questions each: 100 questions, 200 marks, 60 minutes, −0.50 for a wrong answer.","count":100,"key":"SSC's answer key as marked on the candidate's response sheet","alt":"Prelims","hi_paper":"टियर-1 (9 September, पाली 2)","kwname":"SSC CGL 2024 Tier 1 (9 September Shift 2)","mins":60,"pdf":"","kw":"SSC CGL 2024 Tier 1 (9 September Shift 2) (Prelims)"}],"subjects":[{"id":"rea","name":"General Intelligence & Reasoning","slug":"reasoning","topics":["Analogy & Classification","Series","Coding-Decoding","Blood Relations & Directions","Arrangement & Puzzles","Syllogism & Statements","Mathematical Operations","Non-verbal Reasoning","Miscellaneous Reasoning"]},{"id":"qa","name":"Quantitative Aptitude","slug":"quantitative-aptitude","topics":["Number System & Simplification","Percentage, Profit & Interest","Ratio, Average & Mixtures","Time, Work, Speed & Distance","Algebra","Geometry","Mensuration","Trigonometry & Heights","Data Interpretation & Statistics"]},{"id":"eng","name":"English Comprehension","slug":"english","topics":["Vocabulary","Idioms & One-word Substitution","Spelling","Error Spotting & Sentence Improvement","Fill in the Blanks & Cloze Test","Voice & Narration","Sentence Arrangement","Reading Comprehension"]},{"id":"ih","name":"History & Culture","slug":"history","topics":["Ancient India","Medieval India","Modern India","Art & Culture"]},{"id":"pol","name":"Indian Polity","slug":"polity","topics":["Constitution & Rights","Government & Parliament","Judiciary & Constitutional Bodies","Local Government & Governance"]},{"id":"geo","name":"Geography","slug":"geography","topics":["Indian Geography","World & Physical Geography","Environment & Ecology"]},{"id":"eco","name":"Indian Economy","slug":"economy","topics":["Planning, Growth & Budget","Money, Banking & Finance","Agriculture, Industry & Trade","Schemes & Welfare"]},{"id":"sci","name":"General Science","slug":"general-science","topics":["Physics","Chemistry","Biology","Science & Technology"]},{"id":"cur","name":"Current Affairs & Static GK","slug":"current-affairs-static-gk","topics":["National","International","Sports","Awards, Books & Persons","Static GK & Culture"]},{"id":"comp","name":"Computer Knowledge","slug":"computer-knowledge","topics":["Computer Basics & Hardware","Software & Operating Systems","Internet, Networking & Security","MS Office & Applications"]}],"questions":[{"id":"c25s1-1","p":"c25s1","n":1,"s":"rea","t":"Series","q":"Select the letter-cluster from among the given options that can replace the question mark (?) in the following series.\nCFJ, FIM, ILP, ?","w":"Each letter of a cluster moves 3 places forward in the next cluster. First letters: C, F, I, L (+3 each). Second letters: F, I, L, O (+3 each). Third letters: J, M, P, S (+3 each). So the missing cluster is LOS. Within each cluster the gaps are also constant (+3, +4: C→F→J, F→I→M, I→L→P, L→O→S), which confirms LOS; LKN, NHS and KIS break this pattern.","o":["LKN","LOS","NHS","KIS"],"a":[1],"qt":"दिए गए विकल्पों में से उस अक्षर-समूह का चयन करें जो निम्नलिखित श्रृंखला में प्रश्न चिह्न (?) के स्थान पर आ सकता है।\nCFJ, FIM, ILP, ?","ot":["LKN","LOS","NHS","KIS"],"wt":"प्रत्येक समूह का हर अक्षर अगले समूह में 3 स्थान आगे बढ़ता है। पहले अक्षर: C, F, I, L (प्रत्येक +3)। दूसरे अक्षर: F, I, L, O (प्रत्येक +3)। तीसरे अक्षर: J, M, P, S (प्रत्येक +3)। अतः लुप्त समूह LOS है। प्रत्येक समूह के भीतर अंतर भी समान है (+3, +4: C→F→J, F→I→M, I→L→P, L→O→S), जो LOS की पुष्टि करता है; LKN, NHS और KIS इस पैटर्न को तोड़ते हैं।"},{"id":"c25s1-2","p":"c25s1","n":2,"s":"rea","t":"Syllogism & Statements","q":"A statement is given followed by two conclusions. Find which conclusion is TRUE based on the given statement.\nStatement:\nC ≥ T ; A = D ≥ O; G ≥ D < S; T ≥ A\nConclusions:\nI: A ≤ O\nII: C ≥ G","w":"Combine the statements: C ≥ T ≥ A = D ≥ O, and G ≥ D. Conclusion I: we know A ≥ O, so A ≤ O is not definitely true (it holds only if A = O). Conclusion II: C ≥ D and G ≥ D, but both are only compared with D, so no definite relation exists between C and G. Neither conclusion is definitely true. \"Either I or II\" does not apply because the two conclusions are about different pairs.","o":["Either I or II","Only II","Only I","Neither I nor II"],"a":[3],"qt":"एक कथन के बाद दो निष्कर्ष दिए गए हैं। दिए गए कथन के आधार पर ज्ञात कीजिए कि कौन सा निष्कर्ष सत्य है।\nकथन: C ≥ T ; A = D ≥ O; G ≥ D < S; T ≥ A\nनिष्कर्ष:\nI: A ≤ O\nII: C ≥ G","ot":["या तो I या II","केवल II","केवल I","न तो I और न ही II"],"wt":"कथनों को जोड़ने पर: C ≥ T ≥ A = D ≥ O तथा G ≥ D। निष्कर्ष I: हम जानते हैं कि A ≥ O, अतः A ≤ O निश्चित रूप से सत्य नहीं है (यह केवल A = O होने पर ही सही होगा)। निष्कर्ष II: C ≥ D और G ≥ D, परंतु दोनों की तुलना केवल D से है, इसलिए C और G के बीच कोई निश्चित संबंध नहीं है। कोई भी निष्कर्ष निश्चित रूप से सत्य नहीं है। \"या तो I या II\" लागू नहीं होता, क्योंकि दोनों निष्कर्ष अलग-अलग युग्मों के बारे में हैं।"},{"id":"c25s1-3","p":"c25s1","n":3,"s":"rea","t":"Blood Relations & Directions","q":"A is the wife of B. B is the son of C. D is the daughter of A. How is D related to C?","w":"B is the son of C, and A is B's wife, so A is C's daughter-in-law. D is the daughter of A; taking A and B as D's parents, D is the daughter of C's son, that is, C's granddaughter. D is two generations below C, so \"Daughter\" (one generation below) and \"Sister\" (same generation) are wrong, and \"Niece\" would need D to be the daughter of C's brother or sister.","o":["Granddaughter","Daughter","Sister","Niece"],"a":[0],"qt":"A, B की पत्नी है। B, C का पुत्र है। D, A की पुत्री है। D का C से क्या संबंध है?","ot":["पोती","पुत्री","बहन","भतीजी"],"wt":"B, C का पुत्र है और A, B की पत्नी है, अतः A, C की पुत्रवधू है। D, A की पुत्री है; A और B को D के माता-पिता मानने पर D, C के पुत्र की पुत्री अर्थात C की पोती है। D, C से दो पीढ़ी नीचे है, इसलिए \"पुत्री\" (एक पीढ़ी नीचे) और \"बहन\" (समान पीढ़ी) गलत हैं, और \"भतीजी\" के लिए D को C के भाई या बहन की पुत्री होना चाहिए।"},{"id":"c25s1-4","p":"c25s1","n":4,"s":"rea","t":"Analogy & Classification","q":"Solve:\nLEAF : ? :: TIME : EMIT","w":"EMIT is TIME written in reverse order (T-I-M-E becomes E-M-I-T). Applying the same rule to LEAF: L-E-A-F reversed gives F-A-E-L, so the answer is FAEL. FEAL looks close but keeps E and A in their original order, so it is not the reverse of LEAF; LFAE and FELA are random rearrangements.","o":["FEAL","FAEL","LFAE","FELA"],"a":[1],"qt":"हल करें :\nLEAF : ? :: TIME : EMIT","ot":["FEAL","FAEL","LFAE","FELA"],"wt":"EMIT, TIME को उल्टे क्रम में लिखने से बना है (T-I-M-E से E-M-I-T)। यही नियम LEAF पर लगाने पर L-E-A-F उल्टा होकर F-A-E-L बनता है, अतः उत्तर FAEL है। FEAL मिलता-जुलता लगता है, परंतु इसमें E और A अपने मूल क्रम में ही हैं, इसलिए यह LEAF का उल्टा नहीं है; LFAE और FELA केवल अक्षरों की मनमानी पुनर्व्यवस्थाएँ हैं।"},{"id":"c25s1-5","p":"c25s1","n":5,"s":"rea","t":"Series","q":"What comes next: 1, 2, 6, 24, 120, ?","w":"Each term is the previous term multiplied by the next whole number: 1 × 2 = 2, 2 × 3 = 6, 6 × 4 = 24, 24 × 5 = 120, so the next term is 120 × 6 = 720. These are the factorials 1!, 2!, 3!, 4!, 5!, and the missing term is 6! = 720.","o":["720","504","840","600"],"a":[0],"qt":"इसके बाद क्या आएगा: 1, 2, 6, 24, 120, ?","ot":["720","504","840","600"],"wt":"प्रत्येक पद पिछले पद को अगली पूर्ण संख्या से गुणा करके प्राप्त होता है: 1 × 2 = 2, 2 × 3 = 6, 6 × 4 = 24, 24 × 5 = 120, अतः अगला पद 120 × 6 = 720 है। ये क्रमगुणित (फैक्टोरियल) 1!, 2!, 3!, 4!, 5! हैं, और लुप्त पद 6! = 720 है।"},{"id":"c25s1-6","p":"c25s1","n":6,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement: All citizens must abide by traffic laws.\nConclusion I: Citizens who disobey traffic laws must be punished.\nConclusion II: Obeying traffic laws shows civic responsibility.","w":"The word \"must\" makes obeying traffic laws a compulsory duty of every citizen. Fulfilling such a duty is an act of civic responsibility, so Conclusion II follows. A compulsory law implies enforcement, so those who break it are liable to penalty, which is the basis for Conclusion I. Hence the key takes both conclusions as following. Strictly, the statement says nothing about punishment, so many solvers would accept only II. (SSC key; some sources differ.)","o":["Only I","Only II","Both follow","Neither follows"],"a":[2],"qt":"निम्नलिखित कथन को ध्यान से पढ़ें और निष्कर्ष निकालें।\nकथन: सभी नागरिकों को ट्रैफिक नियमों का पालन करना चाहिए।\nनिष्कर्ष I: ट्रैफिक नियमों का उल्लंघन करने वाले नागरिकों को दंडित किया जाना चाहिए।\nनिष्कर्ष II: ट्रैफिक नियमों का पालन करना नागरिक जिम्मेदारी दर्शाता है।","ot":["केवल I","केवल II","दोनों अनुसरण करते हैं","कोई भी अनुसरण नहीं करता"],"wt":"कथन में \"करना चाहिए\" (must) ट्रैफिक नियमों के पालन को प्रत्येक नागरिक का अनिवार्य कर्तव्य बनाता है। ऐसे कर्तव्य का पालन नागरिक जिम्मेदारी का कार्य है, अतः निष्कर्ष II अनुसरण करता है। अनिवार्य नियम के साथ उसका प्रवर्तन भी जुड़ा होता है, इसलिए नियम तोड़ने वाले दंड के भागी हैं; यही निष्कर्ष I का आधार है। इसलिए कुंजी दोनों निष्कर्षों को अनुसरण करता हुआ मानती है। सख्ती से देखें तो कथन दंड के बारे में कुछ नहीं कहता, इसलिए अनेक अभ्यर्थी केवल II को सही मानेंगे। (SSC कुंजी; कुछ स्रोतों में भिन्न उत्तर।)"},{"id":"c25s1-7","p":"c25s1","n":7,"s":"rea","t":"Syllogism & Statements","q":"Instruction: Identify the assumptions that must hold for the statement to be valid, then choose the correct option.\nStatement: To reduce traffic congestion in urban areas, cities should invest in public transportation infrastructure, even though it requires significant initial investments.\nAssumptions:\nI. Public transportation can effectively reduce traffic congestion.\nII. The initial cost of building transportation infrastructure is high.\nIII. People are willing to shift from private vehicles to public transportation.","w":"The advice to invest in public transport \"to reduce traffic congestion\" makes sense only if public transport can reduce congestion, so I is implicit. The phrase \"even though it requires significant initial investments\" takes for granted that the initial cost is high, so II is implicit. The statement says nothing about people's present willingness to leave private vehicles; better infrastructure may itself attract riders, so III is not a necessary assumption.","o":["Only I and II are implicit","Only II and III are implicit","All I, II and III are implicit","Only I is implicit"],"a":[0],"qt":"निर्देश: कथन को मान्य बनाने के लिए आवश्यक मान्यताओं की पहचान करें, फिर सही विकल्प चुनें।\nकथन: शहरी क्षेत्रों में यातायात की भीड़ को कम करने के लिए, शहरों को सार्वजनिक परिवहन बुनियादी ढांचे में निवेश करना चाहिए, भले ही इसके लिए महत्वपूर्ण प्रारंभिक निवेश की आवश्यकता हो।\nमान्यताएँ:\nI. सार्वजनिक परिवहन यातायात की भीड़ को प्रभावी ढंग से कम कर सकता है।\nII. परिवहन बुनियादी ढांचे के निर्माण की प्रारंभिक लागत अधिक है।\nIII. लोग निजी वाहनों से सार्वजनिक परिवहन में जाने के लिए तैयार हैं।","ot":["केवल I और II निहित हैं","केवल II और III निहित हैं","सभी I, II और III निहित हैं","केवल I निहित है"],"wt":"सार्वजनिक परिवहन में निवेश की सलाह \"यातायात की भीड़ कम करने के लिए\" तभी अर्थपूर्ण है जब सार्वजनिक परिवहन भीड़ कम कर सके, अतः I निहित है। \"भले ही इसके लिए महत्वपूर्ण प्रारंभिक निवेश की आवश्यकता हो\" वाक्यांश यह मानकर चलता है कि प्रारंभिक लागत अधिक है, अतः II निहित है। कथन लोगों की निजी वाहन छोड़ने की वर्तमान इच्छा के बारे में कुछ नहीं कहता; बेहतर बुनियादी ढांचा स्वयं यात्रियों को आकर्षित कर सकता है, इसलिए III आवश्यक मान्यता नहीं है।"},{"id":"c25s1-8","p":"c25s1","n":8,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement: Thousands of students appeared for the entrance exam conducted across the country.\nConclusions:\nI. The exam is popular and competitive.\nII. All students who appeared will get admission.","w":"Thousands of candidates taking a nationwide entrance exam shows that the exam is popular, and so many applicants for limited seats make it competitive, so Conclusion I follows. An entrance exam is meant to select candidates; nothing in the statement suggests that every candidate will be admitted, so Conclusion II does not follow. Hence only Conclusion I follows.","o":["Only Conclusion I follows","Only Conclusion II follows","Both I and II follow","Neither I nor II follows"],"a":[0],"qt":"निम्नलिखित कथन को ध्यानपूर्वक पढ़ें और निष्कर्ष निकालें।\nकथन: देश भर में आयोजित प्रवेश परीक्षा में हजारों छात्र शामिल हुए।\nनिष्कर्ष:\nI. यह परीक्षा लोकप्रिय और प्रतिस्पर्धी है।\nII. इसमें शामिल होने वाले सभी छात्रों को प्रवेश मिलेगा।","ot":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"wt":"देश भर में आयोजित प्रवेश परीक्षा में हजारों अभ्यर्थियों का शामिल होना दर्शाता है कि परीक्षा लोकप्रिय है, और सीमित सीटों के लिए इतने अधिक आवेदक इसे प्रतिस्पर्धी बनाते हैं, अतः निष्कर्ष I अनुसरण करता है। प्रवेश परीक्षा का उद्देश्य अभ्यर्थियों का चयन करना है; कथन में ऐसा कुछ नहीं है जिससे लगे कि सभी अभ्यर्थियों को प्रवेश मिलेगा, अतः निष्कर्ष II अनुसरण नहीं करता। इसलिए केवल निष्कर्ष I अनुसरण करता है।"},{"id":"c25s1-9","p":"c25s1","n":9,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement:\nAll circles are shapes. Some shapes are squares. All squares are polygons.\nConclusions:\nI. Some shapes are polygons.\nII. Some polygons are circles.","w":"\"Some shapes are squares\" and \"All squares are polygons\" give \"Some shapes are polygons\" (Some + All = Some), so Conclusion I follows. Circles are linked only to shapes, and the shapes that are squares need not include any circle, so there is no definite link between circles and polygons. Conclusion II is only a possibility, so it does not follow. Hence only I follows.","o":["Only I follows","Only II follows","Both I and II follow","Neither I nor II follows"],"a":[0],"qt":"निम्नलिखित कथन को ध्यानपूर्वक पढ़ें और निष्कर्ष निकालें।\nकथन:\nसभी वृत्त आकृतियाँ हैं। कुछ आकृतियाँ वर्ग हैं। सभी वर्ग बहुभुज हैं।\nनिष्कर्ष:\nI. कुछ आकृतियाँ बहुभुज हैं।\nII. कुछ बहुभुज वृत्त हैं।","ot":["केवल I अनुसरण करता है","केवल II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"wt":"\"कुछ आकृतियाँ वर्ग हैं\" और \"सभी वर्ग बहुभुज हैं\" से \"कुछ आकृतियाँ बहुभुज हैं\" प्राप्त होता है (कुछ + सभी = कुछ), अतः निष्कर्ष I अनुसरण करता है। वृत्त केवल आकृतियों से जुड़े हैं, और जो आकृतियाँ वर्ग हैं उनमें किसी वृत्त का होना आवश्यक नहीं, इसलिए वृत्तों और बहुभुजों के बीच कोई निश्चित संबंध नहीं है। निष्कर्ष II केवल एक संभावना है, अतः अनुसरण नहीं करता। इसलिए केवल I अनुसरण करता है।"},{"id":"c25s1-10","p":"c25s1","n":10,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out:\nRose, Lotus, Sunflower, Oak, Tulip","w":"Rose, Lotus, Sunflower and Tulip are all flowers. Oak is a large tree, valued for its hard timber and not grown for its flowers. Hence Oak is the odd one out. Lotus is an aquatic plant, but it is still a flower like the others, so it is not the odd one.","o":["Rose","Lotus","Oak","Tulip"],"a":[2],"qt":"इनमें से विषम चुनें:\nगुलाब, कमल, सूरजमुखी, ओक, ट्यूलिप","ot":["गुलाब","कमल","ओक","ट्यूलिप"],"wt":"गुलाब, कमल, सूरजमुखी और ट्यूलिप सभी फूल हैं। ओक एक बड़ा वृक्ष है, जो अपनी कठोर लकड़ी के लिए जाना जाता है और फूलों के लिए नहीं उगाया जाता। अतः ओक विषम है। कमल एक जलीय पौधा है, परंतु यह भी अन्य की तरह फूल ही है, इसलिए यह विषम नहीं है।"},{"id":"c25s1-11","p":"c25s1","n":11,"s":"rea","t":"Analogy & Classification","q":"In each of the following questions, the second word is formed by applying a specific rearrangement or transformation to the first. Identify the same pattern and apply it to the third word to find the correct answer from the given alternatives. FLOWER : REWOLF :: FRUITS : ?","w":"REWOLF is FLOWER written backwards (F-L-O-W-E-R reversed gives R-E-W-O-L-F). Reversing FRUITS letter by letter: F-R-U-I-T-S becomes S-T-I-U-R-F, so the answer is STIURF. STUIRF looks similar but has U and I in the wrong order, and STUIFR and STRUIF are not reversals at all.","o":["STUIRF","STIURF","STUIFR","STRUIF"],"a":[1],"qt":"निम्नलिखित प्रत्येक प्रश्न में, दूसरा शब्द पहले शब्द में एक विशिष्ट पुनर्व्यवस्था या परिवर्तन लागू करके बनाया गया है। दिए गए विकल्पों में से सही उत्तर खोजने के लिए उसी पैटर्न को पहचानिए और इसे तीसरे शब्द पर लागू कीजिए।\nFLOWER : REWOLF :: FRUITS : ?","ot":["STUIRF","STIURF","STUIFR","STRUIF"],"wt":"REWOLF, FLOWER को उल्टा लिखने से बना है (F-L-O-W-E-R उल्टा करने पर R-E-W-O-L-F)। FRUITS को अक्षरशः उल्टा करने पर F-R-U-I-T-S से S-T-I-U-R-F बनता है, अतः उत्तर STIURF है। STUIRF मिलता-जुलता लगता है, पर इसमें U और I का क्रम गलत है, तथा STUIFR और STRUIF उल्टे क्रम में हैं ही नहीं।"},{"id":"c25s1-12","p":"c25s1","n":12,"s":"rea","t":"Coding-Decoding","q":"If LEMON is coded as KDNLN, how is MANGO written?","w":"Compare LEMON with KDNLN letter by letter: L−1 = K, E−1 = D, M+1 = N, O−3 = L, N+0 = N. These shifts (−1, −1, +1, −3, 0) follow no regular pattern, so simply apply the same shift at each position of MANGO: M−1 = L, A−1 = Z (going back from A wraps round to Z), N+1 = O, G−3 = D, O+0 = O, giving LZODO. This matches the key, and LZODO is the only option with O in the third place.","o":["LZODO","LZLFP","LZMFQ","LZLFO"],"a":[0],"qt":"अगर LEMON को KDNLN के रूप में कोड किया जाता है, तो MANGO को कैसे लिखा जाएगा?","ot":["LZODO","LZLFP","LZMFQ","LZLFO"],"wt":"LEMON और KDNLN की अक्षरशः तुलना करें: L−1 = K, E−1 = D, M+1 = N, O−3 = L, N+0 = N। ये विस्थापन (−1, −1, +1, −3, 0) किसी नियमित पैटर्न का पालन नहीं करते, इसलिए MANGO के प्रत्येक स्थान पर वही विस्थापन लगाएँ: M−1 = L, A−1 = Z (A से पीछे जाने पर Z आता है), N+1 = O, G−3 = D, O+0 = O, जिससे LZODO मिलता है। यह कुंजी से मेल खाता है, और तीसरे स्थान पर O वाला एकमात्र विकल्प LZODO ही है।"},{"id":"c25s1-13","p":"c25s1","n":13,"s":"rea","t":"Miscellaneous Reasoning","q":"Rearrange the letters of the word \"LOVE\" to form the name of an animal.","w":"The letters L, O, V and E can be rearranged as VOLE. A vole is a small, mouse-like rodent with a short tail and rounded body that lives in fields and grasslands. VEOL, VLEO and OLEV use the same letters but are not meaningful English words, so VOLE is the only animal name.","o":["VOLE","VEOL","VLEO","OLEV"],"a":[0],"qt":"\"LOVE\" शब्द के अक्षरों को पुनर्व्यवस्थित करके किसी जानवर का नाम बनाइए।","ot":["VOLE","VEOL","VLEO","OLEV"],"wt":"L, O, V और E अक्षरों को पुनर्व्यवस्थित करके VOLE बनता है। वोल (vole) एक छोटा, चूहे जैसा कृंतक है, जिसकी पूँछ छोटी और शरीर गोल होता है तथा जो खेतों और घास के मैदानों में रहता है। VEOL, VLEO और OLEV में वही अक्षर हैं, पर ये अंग्रेज़ी के सार्थक शब्द नहीं हैं, इसलिए केवल VOLE ही जानवर का नाम है।"},{"id":"c25s1-14","p":"c25s1","n":14,"s":"rea","t":"Series","q":"Complete the series.\n3, 5, 10, 12, 24, 26, ?","w":"The series alternately adds 2 and multiplies by 2: 3 + 2 = 5, 5 × 2 = 10, 10 + 2 = 12, 12 × 2 = 24, 24 + 2 = 26. The next step is multiplication by 2, so the missing term is 26 × 2 = 52. The other options (54, 53, 50) do not fit this alternating +2, ×2 pattern; for example, 54 would need 26 × 2 + 2, two steps at once.","o":["52","54","53","50"],"a":[0],"qt":"निम्नलिखित श्रृंखला में प्रश्न चिह्न के स्थान पर कौन सा विकल्प आएगा?\n3, 5, 10, 12, 24, 26, ?","ot":["52","54","53","50"],"wt":"श्रृंखला में बारी-बारी से 2 जोड़ा जाता है और 2 से गुणा किया जाता है: 3 + 2 = 5, 5 × 2 = 10, 10 + 2 = 12, 12 × 2 = 24, 24 + 2 = 26। अगला चरण 2 से गुणा है, अतः लुप्त पद 26 × 2 = 52 है। अन्य विकल्प (54, 53, 50) इस बारी-बारी वाले +2, ×2 पैटर्न में नहीं बैठते; उदाहरण के लिए 54 के लिए 26 × 2 + 2, अर्थात एक साथ दो चरण, लगाने पड़ेंगे।"},{"id":"c25s1-15","p":"c25s1","n":15,"s":"rea","t":"Series","q":"What comes next?\nMOA, NPB, OQC, PRD, ?","w":"Each letter position moves one place forward in the alphabet. First letters: M, N, O, P, so next is Q. Second letters: O, P, Q, R, so next is S. Third letters: A, B, C, D, so next is E. The next term is therefore QSE. QRE repeats R in the middle position and QTE skips S, so both break the pattern.","o":["QRE","QTE","RST","QSE"],"a":[3],"qt":"निम्नलिखित श्रृंखला में अगले स्थान पर कौन सा विकल्प आएगा?\nMOA, NPB, OQC, PRD, ?","ot":["QRE","QTE","RST","QSE"],"wt":"प्रत्येक स्थान का अक्षर वर्णमाला में एक स्थान आगे बढ़ता है। पहले अक्षर: M, N, O, P, अतः अगला Q। दूसरे अक्षर: O, P, Q, R, अतः अगला S। तीसरे अक्षर: A, B, C, D, अतः अगला E। इसलिए अगला पद QSE है। QRE में बीच का R दोहराया गया है और QTE में S छूट गया है, इसलिए दोनों पैटर्न को तोड़ते हैं।"},{"id":"c25s1-16","p":"c25s1","n":16,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out from the given alternatives","w":"Lothal (Gujarat), Harappa and Mohenjodaro (both now in Pakistan) are sites of the Harappan or Indus Valley Civilisation of the Bronze Age. Nalanda in Bihar is the site of a famous ancient Buddhist mahavihara (centre of learning) that flourished from the Gupta period, about the 5th century CE. Hence Nalanda is the odd one out.","o":["Lothal","Harappa","Mohenjodaro","Nalanda"],"a":[3],"qt":"दिए गए विकल्पों में से बेमेल विकल्प चुनिए","ot":["लोथल","हड़प्पा","मोहनजोदड़ो","नालंदा"],"wt":"लोथल (गुजरात), हड़प्पा और मोहनजोदड़ो (दोनों अब पाकिस्तान में) कांस्य युग की हड़प्पा या सिंधु घाटी सभ्यता के स्थल हैं। बिहार स्थित नालंदा एक प्रसिद्ध प्राचीन बौद्ध महाविहार (शिक्षा केंद्र) का स्थल है, जो गुप्त काल, लगभग 5वीं शताब्दी ईस्वी से फला-फूला। अतः नालंदा बेमेल है।"},{"id":"c25s1-17","p":"c25s1","n":17,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out from the given alternatives.","w":"Tabla, Mridangam and Pakhawaj are percussion instruments (avanaddha vadya) played by striking a stretched skin membrane with the hands. Tabla and Pakhawaj are used in Hindustani music and Mridangam in Carnatic music. The Sitar is a plucked string instrument (tata vadya). Hence Sitar is the odd one out.","o":["Tabla","Mridangam","Pakhawaj","Sitar"],"a":[3],"qt":"दिए गए विकल्पों में से विषम विकल्प को चुनिए।","ot":["तबला","मृदंगम","पखावज","सितार"],"wt":"तबला, मृदंगम और पखावज ताल वाद्य (अवनद्ध वाद्य) हैं, जिन्हें तनी हुई चमड़े की झिल्ली पर हाथों से आघात करके बजाया जाता है। तबला और पखावज हिंदुस्तानी संगीत में तथा मृदंगम कर्नाटक संगीत में प्रयुक्त होता है। सितार तारों को छेड़कर बजाया जाने वाला तंतु वाद्य (तत वाद्य) है। अतः सितार विषम है।"},{"id":"c25s1-18","p":"c25s1","n":18,"s":"rea","t":"Analogy & Classification","q":"Which of the following groups does not follow the same arithmetic rule?","w":"In 5, 15, 45; 2, 6, 18 and 3, 9, 27 each number is 3 times the previous one (5 × 3 = 15, 15 × 3 = 45; 2 × 3 = 6, 6 × 3 = 18; 3 × 3 = 9, 9 × 3 = 27). In 10, 20, 40 each number is only 2 times the previous one (10 × 2 = 20, 20 × 2 = 40). So 10, 20, 40 does not follow the rule.","o":["10, 20, 40","5, 15, 45","2, 6, 18","3, 9, 27"],"a":[0],"qt":"निम्नलिखित में से कौन सा समूह समान अंकगणितीय नियम का पालन नहीं करता है?","ot":["10, 20, 40","5, 15, 45","2, 6, 18","3, 9, 27"],"wt":"5, 15, 45; 2, 6, 18 और 3, 9, 27 में प्रत्येक संख्या पिछली संख्या की 3 गुनी है (5 × 3 = 15, 15 × 3 = 45; 2 × 3 = 6, 6 × 3 = 18; 3 × 3 = 9, 9 × 3 = 27)। 10, 20, 40 में प्रत्येक संख्या पिछली की केवल 2 गुनी है (10 × 2 = 20, 20 × 2 = 40)। अतः 10, 20, 40 इस नियम का पालन नहीं करता।"},{"id":"c25s1-19","p":"c25s1","n":19,"s":"rea","t":"Mathematical Operations","q":"If 8 * 2 = 20 and 6 * 3 = 27, then what is 5 * 4 = ?","w":"The rule is a * b = (a + b) × b. Check: 8 * 2 = (8 + 2) × 2 = 20 and 6 * 3 = (6 + 3) × 3 = 27. Therefore 5 * 4 = (5 + 4) × 4 = 9 × 4 = 36. The same rule can also be read as a × b + b²: 16 + 4 = 20, 18 + 9 = 27, and 20 + 16 = 36.","o":["32","24","36","22"],"a":[2],"qt":"यदि 8 * 2 = 20 और 6 * 3 = 27 है, तो 5 * 4 = क्या है?","ot":["32","24","36","22"],"wt":"नियम है a * b = (a + b) × b। जाँच: 8 * 2 = (8 + 2) × 2 = 20 और 6 * 3 = (6 + 3) × 3 = 27। अतः 5 * 4 = (5 + 4) × 4 = 9 × 4 = 36। इसी नियम को a × b + b² के रूप में भी पढ़ा जा सकता है: 16 + 4 = 20, 18 + 9 = 27 और 20 + 16 = 36।"},{"id":"c25s1-20","p":"c25s1","n":20,"s":"rea","t":"Coding-Decoding","q":"Instruction: In a code language, “The tree grows tall” is coded as “so mo no lo”, “The tree grows short” is coded as “so mo po lo”, “The plant grows tall” is coded as “to mo no lo”.\nQuestion: What is the code for “The plant grows short”?","w":"Sentences 1 and 2 differ only in tall/short and in no/po, so tall = no and short = po. Sentences 1 and 3 differ only in tree/plant and in so/to, so tree = so and plant = to. The common words \"The\" and \"grows\" are coded as mo and lo. Hence \"The plant grows short\" = to + mo + lo + po, that is, \"to mo lo po\" (order of codes does not matter).","o":["to mo lo po","so lo to fo","po ko go jo","no ko mo no"],"a":[0],"qt":"निर्देश: एक कूट भाषा में, “The tree grows tall” को “so mo no lo” के रूप में कूटबद्ध किया जाता है, “The tree grows short” को “so mo po lo” के रूप में कूटबद्ध किया जाता है, “The plant grows tall” को “to mo no lo” के रूप में कूटबद्ध किया जाता है।\nप्रश्न: “The plant grows short” के लिए कूट क्या है?","ot":["to mo lo po","so lo to fo","po ko go jo","no ko mo no"],"wt":"वाक्य 1 और 2 में केवल tall/short तथा no/po का अंतर है, अतः tall = no और short = po। वाक्य 1 और 3 में केवल tree/plant तथा so/to का अंतर है, अतः tree = so और plant = to। उभयनिष्ठ शब्दों \"The\" और \"grows\" के कूट mo और lo हैं। अतः \"The plant grows short\" = to + mo + lo + po, अर्थात \"to mo lo po\" (कूटों का क्रम महत्वपूर्ण नहीं है)।"},{"id":"c25s1-21","p":"c25s1","n":21,"s":"rea","t":"Miscellaneous Reasoning","q":"A boat travels 60 kilometers upstream in 3 hours and covers the same distance of 60 kilometers downstream in 2 hours. What is the speed of the boat in still water?","w":"Upstream speed = 60 ÷ 3 = 20 km/h and downstream speed = 60 ÷ 2 = 30 km/h. Speed of the boat in still water = (downstream speed + upstream speed) ÷ 2 = (30 + 20) ÷ 2 = 25 km/h. The speed of the stream is (30 − 20) ÷ 2 = 5 km/h. Option 20 km/h is only the upstream speed.","o":["20 km/h","18 km/h","25 km/h","15 km/h"],"a":[2],"qt":"एक नाव धारा के प्रतिकूल 60 किलोमीटर की दूरी 3 घंटे में तय करती है और धारा के अनुकूल 60 किलोमीटर की समान दूरी 2 घंटे में तय करती है। स्थिर जल में नाव की गति क्या है?","ot":["20 किमी/घंटा","18 किमी/घंटा","25 किमी/घंटा","15 किमी/घंटा"],"wt":"धारा के प्रतिकूल गति = 60 ÷ 3 = 20 किमी/घंटा और धारा के अनुकूल गति = 60 ÷ 2 = 30 किमी/घंटा। स्थिर जल में नाव की गति = (अनुकूल गति + प्रतिकूल गति) ÷ 2 = (30 + 20) ÷ 2 = 25 किमी/घंटा। धारा की गति = (30 − 20) ÷ 2 = 5 किमी/घंटा। विकल्प 20 किमी/घंटा केवल प्रतिकूल गति है।"},{"id":"c25s1-22","p":"c25s1","n":22,"s":"rea","t":"Blood Relations & Directions","q":"A man says, “The son of my wife's brother is my ______.","w":"The man's wife's brother is his brother-in-law. In English, a nephew is the son of one's brother or sister, or of one's spouse's brother or sister, so the son of the wife's brother is the man's nephew. The boy would be a cousin only to the man's own children, and a son-in-law is a daughter's husband, so those options are wrong.","o":["Brother-in-law","Nephew","Cousin","Son-in-law"],"a":[1],"qt":"एक आदमी कहता है, “मेरी पत्नी के भाई का बेटा मेरा ______ है।","ot":["साला","भतीजा","चचेरा","दामाद"],"wt":"व्यक्ति की पत्नी का भाई उसका साला (brother-in-law) है। अंग्रेज़ी में nephew का अर्थ है अपने भाई या बहन का पुत्र, अथवा पति/पत्नी के भाई या बहन का पुत्र; अतः पत्नी के भाई का बेटा उस व्यक्ति का nephew है, जिसके लिए विकल्प में \"भतीजा\" दिया गया है (शुद्ध हिंदी में इसे साले का बेटा कहते हैं)। वह लड़का व्यक्ति के अपने बच्चों का ममेरा भाई (cousin) होगा, और दामाद पुत्री का पति होता है, इसलिए ये विकल्प गलत हैं।"},{"id":"c25s1-23","p":"c25s1","n":23,"s":"rea","t":"Mathematical Operations","q":"If '×' means '−', '−' means '+', '+' means '÷', then 12 + 6 × 2 − 4 = ?","w":"Replace the signs as given: + becomes ÷, × becomes −, and − becomes +. So 12 + 6 × 2 − 4 becomes 12 ÷ 6 − 2 + 4. Following BODMAS, division first: 12 ÷ 6 = 2. Then 2 − 2 + 4 = 4. Hence the answer is 4. Always make all the substitutions first and only then apply BODMAS to the new expression.","o":["4","8","6","10"],"a":[0],"qt":"यदि '×' का अर्थ '−' है, '−' का अर्थ '+' है, '+' का अर्थ '÷' है, तो 12 + 6 × 2 − 4 = ?","ot":["4","8","6","10"],"wt":"चिह्नों को दिए अनुसार बदलें: + को ÷, × को − और − को +। तब 12 + 6 × 2 − 4 बन जाता है 12 ÷ 6 − 2 + 4। BODMAS के अनुसार पहले भाग: 12 ÷ 6 = 2। फिर 2 − 2 + 4 = 4। अतः उत्तर 4 है। हमेशा पहले सभी चिह्न बदलें और उसके बाद ही नए व्यंजक पर BODMAS लगाएँ।"},{"id":"c25s1-24","p":"c25s1","n":24,"s":"rea","t":"Mathematical Operations","q":"If the sum of 31 and 19 is multiplied by 9, what is the result?","w":"First find the sum: 31 + 19 = 50. Then multiply by 9: 50 × 9 = 450. A quick check: since the sum is a multiple of 10, the product must end in 0, which rules out 423, 432 and 441 at once. Hence the result is 450.","o":["423","432","441","450"],"a":[3],"qt":"यदि 31 और 19 के योग को 9 से गुणा किया जाए तो परिणाम क्या होगा?","ot":["423","432","441","450"],"wt":"पहले योग ज्ञात करें: 31 + 19 = 50। फिर 9 से गुणा करें: 50 × 9 = 450। त्वरित जाँच: योग 10 का गुणज है, इसलिए गुणनफल का अंतिम अंक 0 होना चाहिए, जिससे 423, 432 और 441 तुरंत बाहर हो जाते हैं। अतः परिणाम 450 है।"},{"id":"c25s1-25","p":"c25s1","n":25,"s":"rea","t":"Series","q":"The series given below contains a sequence of numbers. Accordingly identify the incorrect combination 4, 5, 14, 14, 34, 36, 74, 68","w":"The series is two alternating series. Odd places: 4, 14, 34, 74, each term × 2 + 6 (4 × 2 + 6 = 14, 14 × 2 + 6 = 34, 34 × 2 + 6 = 74), which is correct. Even places: 5, 14, ?, 68, each term × 2 + 4: 5 × 2 + 4 = 14, 14 × 2 + 4 = 32, 32 × 2 + 4 = 68. So the third even term should be 32, and 36 is the incorrect number.","o":["74","34","36","68"],"a":[2],"qt":"नीचे दी गई श्रृंखला में संख्याओं का एक अनुक्रम है। तदनुसार गलत संयोजन की पहचान कीजिए। 4, 5, 14, 14, 34, 36, 74, 68","ot":["74","34","36","68"],"wt":"यह श्रृंखला दो एकांतर श्रृंखलाओं से बनी है। विषम स्थान: 4, 14, 34, 74, प्रत्येक पद × 2 + 6 (4 × 2 + 6 = 14, 14 × 2 + 6 = 34, 34 × 2 + 6 = 74), जो सही है। सम स्थान: 5, 14, ?, 68, प्रत्येक पद × 2 + 4: 5 × 2 + 4 = 14, 14 × 2 + 4 = 32, 32 × 2 + 4 = 68। अतः तीसरा सम पद 32 होना चाहिए, और 36 गलत संख्या है।"},{"id":"c25s1-26","p":"c25s1","n":26,"s":"ih","t":"Art & Culture","q":"Which of the following animals were NOT found on Mauryan stone pillars?","w":"Mauryan pillar capitals carry the lion (Sarnath, Vaishali, Lauriya Nandangarh), the bull (Rampurva) and the elephant (Sankissa), and the Sarnath abacus shows a lion, elephant, bull and horse. No eagle figure appears on any Mauryan pillar. The well-known Garuda pillar at Besnagar (Vidisha) was raised much later, around 113 BCE, by the Greek envoy Heliodorus during the Shunga period, so it is not a Mauryan pillar.","o":["Lions","Bulls","Elephants","Eagle"],"a":[3],"qt":"निम्नलिखित में से कौन से जानवर मौर्य पत्थर के स्तंभों पर नहीं पाए गए?","ot":["शेर","साँड़","हाथियों","गरुड़"],"wt":"मौर्य स्तंभों के शीर्षों पर सिंह (सारनाथ, वैशाली, लौरिया नंदनगढ़), साँड़ (रामपुरवा) और हाथी (संकिसा) बने हैं, तथा सारनाथ स्तंभ के फलक (अबेकस) पर सिंह, हाथी, साँड़ और घोड़ा उकेरे गए हैं। किसी भी मौर्य स्तंभ पर गरुड़ (चील) की आकृति नहीं मिलती। बेसनगर (विदिशा) का प्रसिद्ध गरुड़ स्तंभ बहुत बाद में, लगभग 113 ई.पू. में शुंग काल के दौरान यूनानी राजदूत हेलियोडोरस ने स्थापित कराया था, इसलिए वह मौर्य स्तंभ नहीं है।"},{"id":"c25s1-27","p":"c25s1","n":27,"s":"cur","t":"Static GK & Culture","q":"Fill in the blank:\nLadakhi new year (Losar) is welcomed with symbolic dough models of ______, sun, and moon placed in households.","w":"Losar, the Ladakhi (Buddhist) New Year, is celebrated in winter. As described on the Government of India's festival portal, the new year is welcomed with dough models of the ibex, sun and moon kept in homes, and lucky signs are painted with flour on kitchen walls. Prayers are held in monasteries, lamps are lit, and songs and dances honouring the ibex continue for several days.","o":["Ibex","Yak","Snow leopard","Buddha"],"a":[0],"qt":"रिक्त स्थान भरें:\nलद्दाखी नव वर्ष (लोसर) का स्वागत घरों में ______, सूर्य और चंद्रमा के प्रतीकात्मक आटे के मॉडल रखकर किया जाता है।","ot":["औबेक्स","याक","हिम तेंदुआ","बुद्धा"],"wt":"लोसर लद्दाखी (बौद्ध) नव वर्ष है, जो सर्दियों में मनाया जाता है। भारत सरकार के उत्सव पोर्टल के अनुसार, नव वर्ष का स्वागत घरों में आइबेक्स (पहाड़ी बकरी), सूर्य और चंद्रमा के आटे के मॉडल रखकर किया जाता है, और रसोई की दीवारों पर आटे से शुभ चिह्न बनाए जाते हैं। मठों में प्रार्थनाएँ होती हैं, दीप जलाए जाते हैं, और आइबेक्स के सम्मान में गीत और नृत्य कई दिनों तक चलते हैं। (विकल्प 1 में छपा 'औबेक्स' आइबेक्स ही है।)"},{"id":"c25s1-28","p":"c25s1","n":28,"s":"ih","t":"Ancient India","q":"What was the political significance of Bimbisara’s marriage to a Kosalan princess?","w":"Bimbisara of the Haryanka dynasty of Magadha strengthened his kingdom through marriage alliances. He married Kosala Devi, sister of King Prasenajit (Pasenadi) of Kosala, and received a revenue-yielding village of Kashi as dowry. The alliance secured friendly relations and peace with powerful Kosala, leaving Bimbisara free to expand eastwards, for example by annexing Anga. He also married Lichchhavi and Madra princesses for similar reasons.","o":["Spread of Buddhism","Peace with Kosala","Trade with South India","Fall of Pasenadi"],"a":[1],"qt":"कोसल की राजकुमारी से बिम्बिसार के विवाह का राजनीतिक महत्व क्या था?","ot":["बौद्ध धर्म का प्रसार","कोसल के साथ शांति","दक्षिण भारत के साथ व्यापार","पासेनदी का पतन"],"wt":"मगध के हर्यक वंश के शासक बिम्बिसार ने वैवाहिक संबंधों द्वारा अपने राज्य को मज़बूत किया। उन्होंने कोसल के राजा प्रसेनजित (पसेनदि) की बहन कोसल देवी से विवाह किया और दहेज में काशी का एक राजस्व देने वाला गाँव प्राप्त किया। इस संबंध से शक्तिशाली कोसल के साथ मैत्री और शांति बनी रही, जिससे बिम्बिसार पूर्व की ओर विस्तार कर सके, जैसे अंग का विलय। उन्होंने इसी उद्देश्य से लिच्छवि और मद्र राजकुमारियों से भी विवाह किया।"},{"id":"c25s1-29","p":"c25s1","n":29,"s":"cur","t":"Static GK & Culture","q":"Which of the following correctly describes the musical form Svarajati?","w":"Svarajati is a sung composition of Carnatic music with a fixed structure: a pallavi (often with an anupallavi) and charanams, each charanam having a svara (solfa) passage with matching sahitya (lyrics). Beginners learn simple svarajatis after geethams and before varnams, and Shyama Shastri's svarajatis in Bhairavi, Yadukula Kambhoji and Todi are concert classics. It is also an important item of the Bharatanatyam repertoire, so option 3 fits; it is not a temple-only bhajan, a structureless dance item or a film item.","o":["A bhajan form used only in temples","A dance item without fixed structure","A vocal form later adapted for dance","A film-based item with fast rhythm"],"a":[2],"qt":"निम्नलिखित में से कौन सा स्वराजति संगीत शैली का सही वर्णन करता है?","ot":["केवल मंदिरों में प्रयुक्त होने वाला भजन रूप","बिना किसी निश्चित संरचना वाला नृत्य आइटम","एक गायन शैली जिसे बाद में नृत्य के लिए अनुकूलित किया गया","तेज़ लय के साथ एक फ़िल्म-आधारित आइटम"],"wt":"स्वराजति कर्नाटक संगीत की एक गेय रचना है जिसकी संरचना निश्चित होती है: एक पल्लवी (प्रायः अनुपल्लवी के साथ) और कई चरणम्, जिनमें प्रत्येक चरणम् में स्वर (सरगम) भाग और उससे मेल खाता साहित्य (बोल) होता है। शिक्षार्थी सरल स्वराजति गीतम् के बाद और वर्णम् से पहले सीखते हैं, और श्यामा शास्त्री की भैरवी, यदुकुल काम्भोजी और तोड़ी राग की स्वराजतियाँ संगीत सभाओं की प्रसिद्ध रचनाएँ हैं। यह भरतनाट्यम के प्रदर्शनों का भी महत्वपूर्ण अंग है, इसलिए विकल्प 3 सही है; यह न तो केवल मंदिरों का भजन है, न बिना संरचना का नृत्य आइटम और न ही फ़िल्मी आइटम।"},{"id":"c25s1-30","p":"c25s1","n":30,"s":"cur","t":"Awards, Books & Persons","q":"Which of the following statements regarding the Dronacharya Award is/are correct?\n1) It carries a cash prize of ₹10 lakhs and features a gold statue of Guru Dronacharya.\n2) O.M. Nambiar was honored with the first Dronacharya Award in 1985 for outstanding coaching.","w":"The Dronacharya Award of the Ministry of Youth Affairs and Sports honours outstanding sports coaches. Statement 1 is wrong: the award has a bronze (not gold) statuette of Dronacharya, a certificate and a cash prize (₹10 lakh in the regular category and ₹15 lakh in the lifetime category since 2020). Statement 2 is correct: the award began in 1985, and its first recipients were O.M. Nambiar (athletics), Bhalchandra Bhaskar Bhagwat (wrestling) and Om Prakash Bhardwaj (boxing).","o":["Only 1 is Correct","Only 2 is Correct","1 and 2 are correct","Neither 1 nor 2 are Correct"],"a":[1],"qt":"द्रोणाचार्य पुरस्कार के बारे में निम्नलिखित में से कौन सा कथन सही है/हैं?\n1) इसमें ₹10 लाख का नकद पुरस्कार दिया जाता है और इसमें गुरु द्रोणाचार्य की सोने की प्रतिमा होती है।\n2) ओ.एम. नांबियार को उत्कृष्ट कोचिंग के लिए 1985 में पहले द्रोणाचार्य पुरस्कार से सम्मानित किया गया था।","ot":["केवल 1 सही है","केवल 2 सही है","1 और 2 सही हैं.","न तो 1 और न ही 2 सही है."],"wt":"द्रोणाचार्य पुरस्कार युवा कार्यक्रम एवं खेल मंत्रालय द्वारा उत्कृष्ट खेल प्रशिक्षकों (कोचों) को दिया जाता है। कथन 1 गलत है: इसमें द्रोणाचार्य की काँसे की (सोने की नहीं) प्रतिमा, प्रमाण-पत्र और नकद पुरस्कार दिया जाता है (2020 से नियमित श्रेणी में ₹10 लाख और लाइफ़टाइम श्रेणी में ₹15 लाख)। कथन 2 सही है: यह पुरस्कार 1985 में शुरू हुआ और इसके पहले विजेता ओ.एम. नांबियार (एथलेटिक्स), भालचंद्र भास्कर भागवत (कुश्ती) और ओम प्रकाश भारद्वाज (मुक्केबाज़ी) थे।"},{"id":"c25s1-31","p":"c25s1","n":31,"s":"ih","t":"Medieval India","q":"What position did Hindu Beg hold during Humayun’s reign?","w":"Hindu Beg was a senior Mughal noble who had served Babur. Alarmed by Sher Khan's victory over the Bengal army at Surajgarh (1534), Humayun appointed Hindu Beg governor (hakim) of Jaunpur to keep watch on the eastern region. Sher Khan (later Sher Shah Suri) assured him of his loyalty while he prepared, then sent him a threatening letter and attacked Bengal again in 1537, and Hindu Beg reported his hostile intentions to Humayun. So his post was that of a provincial governor.","o":["Rajput chief","Court scholar","Provincial governor","Spiritual guide"],"a":[2],"qt":"हुमायूँ के शासनकाल में हिन्दू बेग का क्या पद था?","ot":["राजपूत सरदार","दरबारी विद्वान","प्रांतीय गवर्नर","आध्यात्मिक मार्गदर्शक"],"wt":"हिन्दू बेग एक वरिष्ठ मुग़ल सरदार थे, जो बाबर की सेवा में भी रह चुके थे। सूरजगढ़ (1534) में बंगाल की सेना पर शेर ख़ाँ की विजय से चिंतित होकर हुमायूँ ने हिन्दू बेग को पूर्वी क्षेत्र पर नज़र रखने के लिए जौनपुर का गवर्नर (हाकिम) नियुक्त किया। शेर ख़ाँ (बाद में शेरशाह सूरी) ने तैयारी के दौरान उन्हें अपनी वफ़ादारी का भरोसा दिलाया, फिर उन्हें धमकी भरा पत्र भेजा और 1537 में बंगाल पर दोबारा आक्रमण किया; तब हिन्दू बेग ने हुमायूँ को उसके शत्रुतापूर्ण इरादों की सूचना दी। अतः उनका पद प्रांतीय गवर्नर का था।"},{"id":"c25s1-32","p":"c25s1","n":32,"s":"ih","t":"Modern India","q":"Which of the following statements regarding the Government of India Act, 1919 is correctly matched with its constitutional implication?","w":"The Government of India Act, 1919 (Montagu–Chelmsford Reforms) made the central legislature bicameral for the first time, with a Legislative Assembly and a Council of State. Reserved and transferred subjects divided provincial subjects under diarchy; they did not create a central–provincial overlap. Ministers handled only transferred subjects such as education and health, never defence or foreign affairs. The Act merely provided for a Public Service Commission (set up in 1926) and gave no financial control to Indian members.","o":["Transferred and Reserved subjects – Created functional overlap between central and provincial powers","Creation of bicameralism – Introduced two houses at the central level for the first time","Establishment of Public Service Commission – Gave financial control to Indian members in the Viceroy’s Council","Introduction of diarchy in provinces – Empowered Indian ministers to control defence and foreign affairs"],"a":[1],"qt":"भारत सरकार अधिनियम, 1919 के संबंध में निम्नलिखित में से कौन सा कथन इसके संवैधानिक निहितार्थ से सही ढंग से मेल खाता है?","ot":["हस्तांतरित और आरक्षित विषय – केंद्रीय और प्रांतीय शक्तियों के बीच कार्यात्मक ओवरलैप बनाया गया","द्विसदनीय व्यवस्था का निर्माण - पहली बार केंद्रीय स्तर पर दो सदनों की शुरुआत की गई","लोक सेवा आयोग की स्थापना – वायसराय की परिषद में भारतीय सदस्यों को वित्तीय नियंत्रण दिया गया","प्रांतों में द्वैध शासन की शुरुआत - भारतीय मंत्रियों को रक्षा और विदेशी मामलों पर नियंत्रण करने का अधिकार दिया गया"],"wt":"भारत सरकार अधिनियम, 1919 (मोंटेग्यू–चेम्सफ़ोर्ड सुधार) ने पहली बार केंद्रीय विधानमंडल को द्विसदनीय बनाया, जिसमें विधान सभा और राज्य परिषद थीं। आरक्षित और हस्तांतरित विषयों ने द्वैध शासन के अंतर्गत प्रांतीय विषयों को बाँटा; इनसे केंद्र और प्रांतों के बीच कोई ओवरलैप नहीं बना। मंत्री केवल शिक्षा और स्वास्थ्य जैसे हस्तांतरित विषय सँभालते थे, रक्षा या विदेशी मामले कभी नहीं। अधिनियम ने केवल लोक सेवा आयोग का प्रावधान किया (जो 1926 में स्थापित हुआ) और भारतीय सदस्यों को कोई वित्तीय नियंत्रण नहीं दिया।"},{"id":"c25s1-33","p":"c25s1","n":33,"s":"cur","t":"Sports","q":"Consider the following statements about Judo competition areas and contestants:\n1) The competition area is divided into an inner contest area (minimum 8m×8m) and an outer safety area (minimum 3m wide).\n2) The blue uniform contestant is called first, followed by the white uniform contestant.\nWhich of the statements is/are correct?","w":"Statement 1 is correct: under judo competition rules the competition area has an inner contest area of at least 8 m × 8 m (up to 10 m × 10 m) and an outer safety area at least 3 m wide (4 m where two competition areas adjoin). Statement 2 is wrong: the first contestant called wears the white judogi and the second wears the blue judogi, so the white-clad contestant is called first, not the blue one.","o":["Only 1 is Correct","Only 2 is Correct","1 and 2 are Correct","Neither 1 nor 2 are Correct"],"a":[0],"qt":"जूडो प्रतियोगिता क्षेत्रों और प्रतियोगियों के बारे में निम्नलिखित कथनों पर विचार करें:\n1) प्रतियोगिता क्षेत्र को एक आंतरिक प्रतियोगिता क्षेत्र (न्यूनतम 8 मीटर × 8 मीटर) और एक बाहरी सुरक्षा क्षेत्र (न्यूनतम 3 मीटर चौड़ा) में विभाजित किया गया है।\n2) नीली वर्दी वाले प्रतियोगी को पहले बुलाया जाता है, उसके बाद सफेद वर्दी वाले प्रतियोगी को बुलाया जाता है।\nकौन सा कथन सही है/हैं?","ot":["केवल 1 सही है","केवल 2 सही है","1 और 2 सही हैं","न तो 1 और न ही 2 सही है"],"wt":"कथन 1 सही है: जूडो प्रतियोगिता नियमों के अनुसार प्रतियोगिता क्षेत्र में कम से कम 8 मीटर × 8 मीटर (अधिकतम 10 मीटर × 10 मीटर) का आंतरिक प्रतियोगिता क्षेत्र और कम से कम 3 मीटर चौड़ा बाहरी सुरक्षा क्षेत्र होता है (जहाँ दो प्रतियोगिता क्षेत्र सटे हों, वहाँ 4 मीटर)। कथन 2 गलत है: पहले बुलाया जाने वाला प्रतियोगी सफ़ेद जूडोगी पहनता है और दूसरा नीली जूडोगी, अर्थात सफ़ेद वर्दी वाले प्रतियोगी को पहले बुलाया जाता है, नीली वर्दी वाले को नहीं।"},{"id":"c25s1-34","p":"c25s1","n":34,"s":"cur","t":"International","q":"Which country partners with India in the Maitri military exercise aimed at defence cooperation?","w":"MAITREE (Maitri) is the joint military exercise between the armies of India and Thailand, focusing on counter-terrorism operations in semi-urban terrain under a UN mandate and on interoperability. Its 14th edition was held at the Joint Training Node, Umroi, Meghalaya, from 1 to 14 September 2025. Do not confuse it with Surya Kiran (Nepal), Mitra Shakti (Sri Lanka) or Sampriti (Bangladesh).","o":["Bhutan","Sri Lanka","Bangladesh","Thailand"],"a":[3],"qt":"रक्षा सहयोग के उद्देश्य से मैत्री सैन्य अभ्यास में भारत के साथ कौन सा देश भागीदार है?","ot":["भूटान","श्रीलंका","बांग्लादेश","थाईलैंड"],"wt":"मैत्री (MAITREE) भारत और थाईलैंड की सेनाओं का संयुक्त सैन्य अभ्यास है, जो संयुक्त राष्ट्र के अधिदेश के अंतर्गत अर्ध-शहरी क्षेत्रों में आतंकवाद-रोधी अभियानों और आपसी तालमेल (इंटरऑपरेबिलिटी) पर केंद्रित है। इसका 14वाँ संस्करण 1 से 14 सितंबर 2025 तक मेघालय के उमरोई स्थित संयुक्त प्रशिक्षण नोड में आयोजित हुआ। इसे सूर्य किरण (नेपाल), मित्र शक्ति (श्रीलंका) या संप्रीति (बांग्लादेश) से न मिलाएँ।"},{"id":"c25s1-35","p":"c25s1","n":35,"s":"cur","t":"Awards, Books & Persons","q":"Who is the author of the book 'The Argumentative Indian'?","w":"'The Argumentative Indian: Writings on Indian History, Culture and Identity' (2005) is a collection of essays by Amartya Sen, winner of the 1998 Nobel Memorial Prize in Economic Sciences and the Bharat Ratna (1999). It highlights India's long tradition of public debate, scepticism and tolerance of differing views. Other books by Sen include 'Development as Freedom', 'The Idea of Justice' and 'Identity and Violence'.","o":["Amartya Sen","Shashi Tharoor","Ramachandra Guha","Arvind Subramanian"],"a":[0],"qt":"'द आर्गुमेंटेटिव इंडियन' पुस्तक के लेखक कौन हैं?","ot":["अमर्त्य सेन","शशि थरूर","रामचंद्र गुहा","अरविंद सुब्रमण्यन"],"wt":"'द आर्गुमेंटेटिव इंडियन: राइटिंग्स ऑन इंडियन हिस्ट्री, कल्चर एंड आइडेंटिटी' (2005) अमर्त्य सेन के निबंधों का संग्रह है, जिन्हें 1998 में अर्थशास्त्र का नोबेल स्मृति पुरस्कार और 1999 में भारत रत्न मिला। यह पुस्तक भारत में सार्वजनिक वाद-विवाद, संशयवाद और भिन्न विचारों के प्रति सहिष्णुता की लंबी परंपरा को रेखांकित करती है। सेन की अन्य पुस्तकों में 'डेवलपमेंट ऐज़ फ़्रीडम', 'द आइडिया ऑफ़ जस्टिस' और 'आइडेंटिटी एंड वायलेंस' शामिल हैं।"},{"id":"c25s1-36","p":"c25s1","n":36,"s":"geo","t":"World & Physical Geography","q":"Which of the following pairs is correctly matched with reference to limestone cave formations?","w":"In limestone (karst) caves, water carrying dissolved calcium carbonate drips from the roof and deposits calcite. Deposits hanging from the roof are stalactites, and those rising from the floor where the drops land are stalagmites. When a stalactite and a stalagmite grow until they meet, they form a pillar or column. Options 1 and 2 swap the two definitions, and stalagmites form from water dripping onto the floor, not water falling from it.","o":["Stalactite – Rises from cave floor","Stalagmite – Hangs from cave roof","Pillar – Formed by union of stalactite and stalagmite","Stalagmite – Formed by water falling from floor"],"a":[2],"qt":"चूना पत्थर गुफा संरचनाओं के संदर्भ में निम्नलिखित में से कौन सा युग्म सही सुमेलित है?","ot":["स्टैलेक्टाइट - गुफा के तल से उठता है","स्टैलाग्माइट - गुफा की छत से लटका हुआ","स्तंभ - स्टैलेक्टाइट और स्टैलेग्माइट के मिलन से निर्मित","स्टैलेग्माइट - फर्श से गिरने वाले पानी से बनता है"],"wt":"चूना पत्थर (कार्स्ट) की गुफाओं में घुले हुए कैल्शियम कार्बोनेट वाला पानी छत से टपकता है और कैल्साइट जमा करता है। छत से नीचे लटकने वाले निक्षेप स्टैलेक्टाइट कहलाते हैं, और जहाँ बूँदें गिरती हैं वहाँ फ़र्श से ऊपर उठने वाले निक्षेप स्टैलेग्माइट कहलाते हैं। जब स्टैलेक्टाइट और स्टैलेग्माइट बढ़ते-बढ़ते आपस में मिल जाते हैं, तो स्तंभ बनता है। विकल्प 1 और 2 में दोनों की परिभाषाएँ उलट दी गई हैं, और स्टैलेग्माइट फ़र्श पर टपकने वाले पानी से बनता है, फ़र्श से गिरने वाले पानी से नहीं।"},{"id":"c25s1-37","p":"c25s1","n":37,"s":"sci","t":"Science & Technology","q":"Which instrument description on XPoSat is correct?","w":"XPoSat, India's first dedicated X-ray polarimetry satellite, was launched by PSLV-C58 on 1 January 2024. Its POLIX payload, built by the Raman Research Institute, measures the polarisation of X-rays in the 8–30 keV band from bright sources such as black holes and neutron stars. The second payload, XSPECT (built by URSC), carries out X-ray spectroscopy and timing in the 0.8–15 keV band; it does not measure polarisation or extend POLIX's range.","o":["XSPECT extends POLIX’s polarimetry range to 0.5–20 keV.","POLIX performs X-ray spectroscopy and timing.","XSPECT measures X-ray polarization.","POLIX measures X-ray polarization (8–30 keV) to study black holes."],"a":[3],"qt":"XPoSat पर कौन सा उपकरण विवरण सही है?","ot":["XSPECT, POLIX की ध्रुवणमापी सीमा को 0.5-20 keV तक बढ़ाता है।","POLIX एक्स-रे स्पेक्ट्रोस्कोपी और टाइमिंग का कार्य करता है।","XSPECT एक्स-रे ध्रुवीकरण को मापता है।","POLIX ब्लैक होल का अध्ययन करने के लिए एक्स-रे ध्रुवीकरण (8-30 keV) को मापता है।"],"wt":"XPoSat, भारत का पहला समर्पित एक्स-रे ध्रुवणमापी (पोलरिमेट्री) उपग्रह, 1 जनवरी 2024 को PSLV-C58 से प्रक्षेपित किया गया। रमन अनुसंधान संस्थान द्वारा निर्मित इसका POLIX पेलोड ब्लैक होल और न्यूट्रॉन तारों जैसे चमकीले स्रोतों से आने वाली एक्स-रे के ध्रुवीकरण को 8–30 keV बैंड में मापता है। दूसरा पेलोड XSPECT (URSC द्वारा निर्मित) 0.8–15 keV बैंड में एक्स-रे स्पेक्ट्रोस्कोपी और टाइमिंग का कार्य करता है; यह न तो ध्रुवीकरण मापता है और न ही POLIX की सीमा बढ़ाता है।"},{"id":"c25s1-38","p":"c25s1","n":38,"s":"geo","t":"Indian Geography","q":"Which of the following statements best explains why age-specific rates are used in demography?","w":"Crude birth and death rates are worked out for the whole population, so they are affected by its age structure. Age-specific rates, such as age-specific fertility rates and age-specific death rates, are calculated separately for each age group (for example 20–24 years). They show how fertility and mortality vary with age and allow fair comparison between populations with different age compositions. The total fertility rate is built from age-specific fertility rates.","o":["They help identify regional literacy levels","They reflect age-wise variation in fertility or mortality","They show the economic condition of elderly people","They reduce the total number of indicators needed"],"a":[1],"qt":"निम्नलिखित में से कौन सा कथन सबसे अच्छे ढंग से बताता है कि जनसांख्यिकी में आयु-विशिष्ट दरों का उपयोग क्यों किया जाता है?","ot":["वे क्षेत्रीय साक्षरता स्तरों की पहचान करने में मदद करते हैं","वे प्रजनन क्षमता या मृत्यु दर में आयु-वार भिन्नता को दर्शाते हैं","वे बुजुर्ग लोगों की आर्थिक स्थिति को दर्शाते हैं","वे आवश्यक संकेतकों की कुल संख्या को कम कर देते हैं"],"wt":"अशोधित जन्म दर और मृत्यु दर पूरी जनसंख्या के लिए निकाली जाती हैं, इसलिए वे उसकी आयु-संरचना से प्रभावित होती हैं। आयु-विशिष्ट दरें, जैसे आयु-विशिष्ट प्रजनन दर और आयु-विशिष्ट मृत्यु दर, प्रत्येक आयु वर्ग (उदाहरण के लिए 20–24 वर्ष) के लिए अलग-अलग निकाली जाती हैं। ये दिखाती हैं कि प्रजनन क्षमता और मृत्यु दर आयु के साथ कैसे बदलती हैं, और भिन्न आयु-संरचना वाली जनसंख्याओं की उचित तुलना संभव बनाती हैं। कुल प्रजनन दर आयु-विशिष्ट प्रजनन दरों से ही बनती है।"},{"id":"c25s1-39","p":"c25s1","n":39,"s":"pol","t":"Government & Parliament","q":"\"Amit Shah already has the key portfolios of Union Home Minister and Minister of Cooperation in 2025. Think of these statements:\n1. He remains Union Home Minister and Minister of Cooperation post the 2024 elections.\n2. The Home Ministry is responsible for internal security, borders, and disaster management.\n3. The Home Minister enjoys a constitutionalized fixed 6-year term.\nWhich one of the above is/are true?","w":"Amit Shah has been Union Home Minister since 2019 and became India's first Minister of Cooperation when that ministry was created in July 2021; he kept both portfolios in the government formed in June 2024, so statement 1 is true. The Ministry of Home Affairs handles internal security, border management and disaster management, so statement 2 is true. Statement 3 is false: Union ministers hold office during the pleasure of the President (Article 75(2)) and have no fixed term.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3 all are correct"],"a":[0],"qt":"अमित शाह के पास 2025 में केंद्रीय गृह मंत्री और सहकारिता मंत्री के प्रमुख विभाग पहले से ही हैं। इन कथनों पर विचार करें:\n1. वह 2024 के चुनावों के बाद भी केंद्रीय गृह मंत्री और सहकारिता मंत्री बने रहेंगे।\n2. गृह मंत्रालय आंतरिक सुरक्षा, सीमाओं और आपदा प्रबंधन के लिए ज़िम्मेदार है।\n3. गृह मंत्री का संवैधानिक रूप से निश्चित 6-वर्षीय कार्यकाल होता है।\nउपरोक्त में से कौन सा/से कथन सत्य है/हैं?","ot":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3 सभी सही हैं"],"wt":"अमित शाह 2019 से केंद्रीय गृह मंत्री हैं और जुलाई 2021 में सहकारिता मंत्रालय बनने पर भारत के पहले सहकारिता मंत्री बने; जून 2024 में बनी सरकार में भी उन्होंने दोनों विभाग अपने पास रखे, इसलिए कथन 1 सत्य है। गृह मंत्रालय आंतरिक सुरक्षा, सीमा प्रबंधन और आपदा प्रबंधन का कार्य देखता है, इसलिए कथन 2 सत्य है। कथन 3 असत्य है: केंद्रीय मंत्री राष्ट्रपति के प्रसादपर्यंत (अनुच्छेद 75(2)) पद धारण करते हैं और उनका कोई निश्चित कार्यकाल नहीं होता।"},{"id":"c25s1-40","p":"c25s1","n":40,"s":"cur","t":"Sports","q":"Which events were initially announced as demonstration sports but later became full-fledged medal events in the 38th National Games held at Uttrakhand?","w":"The 38th National Games were held in Uttarakhand from 28 January to 14 February 2025. Yogasana and Mallakhamb were first listed by the Indian Olympic Association as demonstration sports, along with Kalaripayattu and rafting, but they were upgraded to full medal events during the Games. Kalaripayattu, a medal sport at the 37th Games in Goa, stayed only a demonstration sport, which its federation protested. Kho-kho, kabaddi, shooting, athletics, kayaking and rowing were regular medal sports.","o":["Kho-Kho and Kabaddi","Yogasana and Mallakhamb","Shooting and Athletics","Kayaking and Rowing"],"a":[1],"qt":"उत्तराखंड में आयोजित 38वें राष्ट्रीय खेलों में किन स्पर्धाओं को शुरू में प्रदर्शन खेल के रूप में घोषित किया गया था, लेकिन बाद में वे पूर्ण पदक स्पर्धा बन गईं?","ot":["खो-खो और कबड्डी","योगासन और मल्लखंभ","निशानेबाजी और एथलेटिक्स","कयाकिंग और रोइंग"],"wt":"38वें राष्ट्रीय खेल 28 जनवरी से 14 फ़रवरी 2025 तक उत्तराखंड में आयोजित हुए। भारतीय ओलंपिक संघ ने योगासन और मल्लखंभ को पहले कलारीपयट्टु और राफ़्टिंग के साथ प्रदर्शन खेलों में रखा था, लेकिन खेलों के दौरान इन्हें पूर्ण पदक स्पर्धा बना दिया गया। कलारीपयट्टु, जो गोवा में हुए 37वें खेलों में पदक खेल था, केवल प्रदर्शन खेल ही रहा, जिसका उसके महासंघ ने विरोध किया। खो-खो, कबड्डी, निशानेबाज़ी, एथलेटिक्स, कयाकिंग और रोइंग नियमित पदक खेल थे।"},{"id":"c25s1-41","p":"c25s1","n":41,"s":"geo","t":"Indian Geography","q":"The Kudremukh mines in Karnataka are primarily known for the extraction of which important mineral resource?","w":"Kudremukh, in the Western Ghats of Chikkamagaluru district, Karnataka, is known for its iron ore (magnetite) deposits. They were mined by KIOCL (Kudremukh Iron Ore Company Limited), and the ore was sent as slurry through a pipeline to Mangaluru for pelletisation and export. Mining at Kudremukh stopped at the end of 2005 after a Supreme Court order to protect the Kudremukh National Park. Ballari–Hosapete is Karnataka's other major iron ore belt.","o":["Bauxite","Limestone","Iron Ore","Copper"],"a":[2],"qt":"कर्नाटक में कुद्रेमुख खदानें मुख्य रूप से किस महत्वपूर्ण खनिज संसाधन के निष्कर्षण के लिए जानी जाती हैं?","ot":["बाक्साइट","चूना पत्थर","लौह अयस्क","ताँबा"],"wt":"कुद्रेमुख कर्नाटक के चिक्कमगलूरु ज़िले में पश्चिमी घाट में स्थित है और अपने लौह अयस्क (मैग्नेटाइट) भंडारों के लिए जाना जाता है। इनका खनन KIOCL (कुद्रेमुख आयरन ओर कंपनी लिमिटेड) करती थी, और अयस्क को घोल (स्लरी) के रूप में पाइपलाइन से मंगलुरु भेजा जाता था, जहाँ उसके पेलेट बनाकर निर्यात किए जाते थे। कुद्रेमुख राष्ट्रीय उद्यान की रक्षा के लिए सर्वोच्च न्यायालय के आदेश के बाद 2005 के अंत में यहाँ खनन बंद हो गया। बल्लारी–होसपेटे कर्नाटक की दूसरी प्रमुख लौह अयस्क पट्टी है।"},{"id":"c25s1-42","p":"c25s1","n":42,"s":"pol","t":"Judiciary & Constitutional Bodies","q":"Which of the following statements correctly applies the weighted voting mechanism under Article 279A(9) of the Indian Constitution?","w":"Under Article 279A(9), every decision of the GST Council needs a majority of at least three-fourths of the weighted votes of members present and voting. The Central Government's vote carries one-third of the total votes cast, and all the State Governments together carry two-thirds, so the States collectively have twice the Centre's weight. The Centre therefore holds about 33%, not 75%, and cannot pass a decision alone or with one State; equally, the States cannot pass one without the Centre.","o":["The Centre holds 75% of the voting power in the GST Council.","A GST Council decision can be passed solely with the support of the Centre and one State.","The States collectively have twice the voting weight of the Centre in the GST Council.","Each State has equal weightage as the Centre in GST Council voting."],"a":[2],"qt":"निम्नलिखित में से कौन सा कथन भारतीय संविधान के अनुच्छेद 279A(9) के तहत भारित मतदान तंत्र को सही ढंग से लागू करता है?","ot":["जीएसटी परिषद में केंद्र के पास 75% मतदान शक्ति है।","जीएसटी परिषद का निर्णय केवल केन्द्र और एक राज्य के सहयोग से पारित किया जा सकता है।","जीएसटी परिषद में राज्यों का सामूहिक रूप से केन्द्र से दोगुना मत-भार है।","जीएसटी परिषद के मतदान में प्रत्येक राज्य को केंद्र के समान महत्व प्राप्त है।"],"wt":"अनुच्छेद 279A(9) के अनुसार जीएसटी परिषद का प्रत्येक निर्णय उपस्थित और मतदान करने वाले सदस्यों के भारित मतों के कम से कम तीन-चौथाई बहुमत से होता है। केंद्र सरकार के मत का भार डाले गए कुल मतों का एक-तिहाई होता है और सभी राज्य सरकारों के मतों का सम्मिलित भार दो-तिहाई होता है, अतः राज्यों का सामूहिक भार केंद्र का दोगुना है। इसलिए केंद्र के पास लगभग 33% भार है, 75% नहीं, और वह अकेले या एक राज्य के साथ कोई निर्णय पारित नहीं कर सकता; इसी प्रकार राज्य भी केंद्र के बिना कोई निर्णय पारित नहीं कर सकते।"},{"id":"c25s1-43","p":"c25s1","n":43,"s":"sci","t":"Chemistry","q":"Consider the given statements regarding the behavior of ideal gases:\n1. Ideal gas molecules have negligible volume compared to the total volume of the container.\n2. There are strong intermolecular attractive forces between ideal gas molecules.\n3. Collisions between ideal gas molecules are perfectly elastic.\nWhich of the statements given above is/are correct?","w":"The kinetic theory model of an ideal gas assumes that the actual volume of the molecules is negligible compared with the volume of the container (statement 1 correct), that there are no attractive or repulsive forces between the molecules (statement 2 wrong), and that collisions between molecules and with the container walls are perfectly elastic, so total kinetic energy is conserved (statement 3 correct). Real gases deviate from these assumptions at high pressure and low temperature.","o":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"a":[1],"qt":"आदर्श गैसों के व्यवहार के संबंध में दिए गए कथनों पर विचार कीजिए:\n1. आदर्श गैस के अणुओं का आयतन पात्र के कुल आयतन की तुलना में नगण्य होता है।\n2. आदर्श गैस के अणुओं के बीच प्रबल अंतराण्विक आकर्षण बल होते हैं।\n3. आदर्श गैस के अणुओं के बीच संघट्ट पूर्णतः प्रत्यास्थ होते हैं।\nउपर्युक्त कथनों में से कौन सा/से सही है/हैं?","ot":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"wt":"आदर्श गैस के गतिज सिद्धांत मॉडल में माना जाता है कि अणुओं का वास्तविक आयतन पात्र के आयतन की तुलना में नगण्य होता है (कथन 1 सही), अणुओं के बीच कोई आकर्षण या प्रतिकर्षण बल नहीं होता (कथन 2 गलत), और अणुओं के आपसी तथा पात्र की दीवारों से होने वाले संघट्ट पूर्णतः प्रत्यास्थ होते हैं, जिससे कुल गतिज ऊर्जा संरक्षित रहती है (कथन 3 सही)। उच्च दाब और निम्न ताप पर वास्तविक गैसें इन मान्यताओं से विचलित होती हैं।"},{"id":"c25s1-44","p":"c25s1","n":44,"s":"pol","t":"Judiciary & Constitutional Bodies","q":"In Bharatiya Nagarik suraksha Samhita (BNSS), which court may grant default bail after time limit lapses?","w":"Section 187 of the Bharatiya Nagarik Suraksha Sanhita, 2023 (which replaced Section 167 of the CrPC) allows a Magistrate to authorise detention of an accused during investigation for up to 60 or 90 days, depending on the offence. If the investigation is not completed and the charge sheet is not filed within that period, the accused must be released on bail if he is prepared to furnish it. This default (statutory) bail is granted by the Magistrate.","o":["District Court","Magistrate","High Court","Gram Nyayalaya"],"a":[1],"qt":"भारतीय नागरिक सुरक्षा संहिता (बीएनएसएस) में, कौन सी अदालत समय सीमा समाप्त होने के बाद डिफ़ॉल्ट जमानत दे सकती है?","ot":["जिला अदालत","मजिस्ट्रेट","उच्च न्यायालय","ग्राम न्यायालय"],"wt":"भारतीय नागरिक सुरक्षा संहिता, 2023 की धारा 187 (जिसने दंड प्रक्रिया संहिता की धारा 167 का स्थान लिया) मजिस्ट्रेट को अपराध के अनुसार जाँच के दौरान अभियुक्त को 60 या 90 दिनों तक हिरासत में रखने का आदेश देने की अनुमति देती है। यदि इस अवधि में जाँच पूरी न हो और आरोप-पत्र दाखिल न हो, तो ज़मानत देने को तैयार अभियुक्त को ज़मानत पर रिहा करना अनिवार्य है। यह डिफ़ॉल्ट (वैधानिक) ज़मानत मजिस्ट्रेट द्वारा दी जाती है।"},{"id":"c25s1-45","p":"c25s1","n":45,"s":"eco","t":"Schemes & Welfare","q":"Which of the following schemes or initiatives is conceptually different from the others in terms of its sectoral focus?","w":"NSWS (National Single Window System, 2021) is a digital platform for investor and business approvals; LEADS (Logistics Ease Across Different States) ranks States and UTs on logistics performance; and PM Gati Shakti (2021) is a national master plan for integrated multimodal infrastructure. All three focus on industry, investment and logistics. PMFBY (Pradhan Mantri Fasal Bima Yojana, 2016) is a crop insurance scheme of the Ministry of Agriculture and Farmers Welfare, so its focus is agriculture.","o":["NSWS","LEADS","Gati Shakti","PMFBY"],"a":[3],"qt":"निम्नलिखित में से कौन सी योजना या पहल अपने क्षेत्रीय फोकस के संदर्भ में अन्य से वैचारिक रूप से भिन्न है?","ot":["एनएसडब्ल्यूएस","लीड्स","गति शक्ति","पीएमएफबीवाई"],"wt":"NSWS (राष्ट्रीय एकल खिड़की प्रणाली, 2021) निवेशकों और व्यवसायों की स्वीकृतियों के लिए एक डिजिटल मंच है; LEADS (लॉजिस्टिक्स ईज़ एक्रॉस डिफ़रेंट स्टेट्स) राज्यों और केंद्रशासित प्रदेशों को लॉजिस्टिक्स प्रदर्शन के आधार पर रैंक करता है; और पीएम गति शक्ति (2021) एकीकृत बहु-मॉडल अवसंरचना का राष्ट्रीय मास्टर प्लान है। ये तीनों उद्योग, निवेश और लॉजिस्टिक्स पर केंद्रित हैं। PMFBY (प्रधानमंत्री फसल बीमा योजना, 2016) कृषि एवं किसान कल्याण मंत्रालय की फसल बीमा योजना है, अतः इसका क्षेत्र कृषि है।"},{"id":"c25s1-46","p":"c25s1","n":46,"s":"cur","t":"Static GK & Culture","q":"Fill in the Blank:\nGhoomar was listed among top local dances globally in ______ year.","w":"Ghoomar is the traditional folk dance of Rajasthan, performed mainly by Bhil and Rajput women who swirl in long flowing ghagras; the Bhils first danced it in worship of Goddess Saraswati, and Rajput families later adopted it. In 2013, an online travel advisory survey ranked Ghoomar fourth among the world's top ten local dances, the only Indian dance on the list, with Hawaii's hula ranked first. It is performed at festivals, weddings and other special occasions.","o":["2010","2013","2015","2018"],"a":[1],"qt":"रिक्त स्थान भरें:\nघूमर को ______ वर्ष में विश्व स्तर पर शीर्ष स्थानीय नृत्यों में सूचीबद्ध किया गया था।","ot":["2010","2013","2015","2018"],"wt":"घूमर राजस्थान का पारंपरिक लोक नृत्य है, जिसे मुख्यतः भील और राजपूत महिलाएँ लंबे घेरदार घाघरे में घूमते हुए करती हैं; भीलों ने इसे पहले देवी सरस्वती की आराधना में किया और बाद में राजपूत परिवारों ने इसे अपनाया। 2013 में एक ऑनलाइन ट्रैवल एडवाइज़री सर्वेक्षण ने घूमर को विश्व के शीर्ष दस स्थानीय नृत्यों में चौथा स्थान दिया; सूची में यह एकमात्र भारतीय नृत्य था और पहले स्थान पर हवाई का हुला था। यह त्योहारों, विवाहों और अन्य विशेष अवसरों पर किया जाता है।"},{"id":"c25s1-47","p":"c25s1","n":47,"s":"cur","t":"International","q":"According to Transparency International, what is a major concern with EU golden passport and visa schemes?","w":"Golden passport (citizenship-by-investment) and golden visa (residence-by-investment) schemes grant citizenship or residence to wealthy foreigners in return for investment. Transparency International warns that weak checks let corrupt officials, money launderers and criminals buy access to the EU, exposing the whole bloc to corruption risks. On 29 April 2025 the Court of Justice of the European Union ruled that Malta's golden passport scheme breached EU law, a ruling Transparency International welcomed.","o":["They increase legal migration and help boost employment","They encourage cultural exchange across the EU","They enable the corrupt to exploit citizenship and residency systems for personal gain","They promote tourism through relaxed visa regulations"],"a":[2],"qt":"ट्रांसपेरेंसी इंटरनेशनल के अनुसार, यूरोपीय संघ की गोल्डन पासपोर्ट और वीज़ा योजनाओं के संबंध में मुख्य चिंता क्या है?","ot":["वे कानूनी प्रवासन को बढ़ाते हैं और रोजगार को बढ़ावा देने में मदद करते हैं","वे यूरोपीय संघ में सांस्कृतिक आदान-प्रदान को प्रोत्साहित करते हैं","वे भ्रष्ट लोगों को व्यक्तिगत लाभ के लिए नागरिकता और निवास प्रणालियों का शोषण करने में सक्षम बनाते हैं","वे वीज़ा नियमों में ढील देकर पर्यटन को बढ़ावा देते हैं"],"wt":"गोल्डन पासपोर्ट (निवेश द्वारा नागरिकता) और गोल्डन वीज़ा (निवेश द्वारा निवास) योजनाएँ निवेश के बदले धनी विदेशियों को नागरिकता या निवास देती हैं। ट्रांसपेरेंसी इंटरनेशनल चेतावनी देता है कि कमज़ोर जाँच के कारण भ्रष्ट अधिकारी, धन-शोधन करने वाले और अपराधी यूरोपीय संघ में प्रवेश ख़रीद लेते हैं, जिससे पूरा संघ भ्रष्टाचार के जोखिम में पड़ता है। 29 अप्रैल 2025 को यूरोपीय संघ के न्यायालय (CJEU) ने माल्टा की गोल्डन पासपोर्ट योजना को यूरोपीय संघ के कानून का उल्लंघन माना, जिसका ट्रांसपेरेंसी इंटरनेशनल ने स्वागत किया।"},{"id":"c25s1-48","p":"c25s1","n":48,"s":"cur","t":"National","q":"Which Indian city topped the Swachh Vayu Sarvekshan 2024 in the category of cities with a population over 10 lakh?","w":"Swachh Vayu Survekshan, run by the Union Environment Ministry under the National Clean Air Programme, ranks cities on the steps they take to improve air quality. Indore, SSC's answer, topped the over-10-lakh category in the 2023 survey (announced on 7 September 2023) and in the 2025 survey (announced in September 2025, just before this exam). In the 2024 survey, announced at Jaipur on 7 September 2024, Surat ranked first, followed by Jabalpur and Agra, so the year printed does not fit the key. (SSC key; some sources differ.)","o":["Bengaluru","Indore","Mumbai","Ahmedabad"],"a":[1],"qt":"10 लाख से अधिक आबादी वाले शहरों की श्रेणी में स्वच्छ वायु सर्वेक्षण 2024 में कौन सा भारतीय शहर शीर्ष पर रहा?","ot":["बेंगलुरु","इंदौर","मुंबई","अहमदाबाद"],"wt":"स्वच्छ वायु सर्वेक्षण, जिसे केंद्रीय पर्यावरण मंत्रालय राष्ट्रीय स्वच्छ वायु कार्यक्रम के अंतर्गत चलाता है, शहरों को वायु गुणवत्ता सुधारने के लिए उठाए गए कदमों के आधार पर रैंक करता है। SSC का उत्तर इंदौर 2023 के सर्वेक्षण (7 सितंबर 2023 को घोषित) और 2025 के सर्वेक्षण (सितंबर 2025 में, इस परीक्षा से ठीक पहले घोषित) में 10 लाख से अधिक आबादी वाली श्रेणी में शीर्ष पर रहा। 7 सितंबर 2024 को जयपुर में घोषित 2024 के सर्वेक्षण में सूरत पहले, जबलपुर दूसरे और आगरा तीसरे स्थान पर रहे, इसलिए प्रश्न में छपा वर्ष उत्तर कुंजी से मेल नहीं खाता। (SSC कुंजी; कुछ स्रोत भिन्न हैं।)"},{"id":"c25s1-49","p":"c25s1","n":49,"s":"sci","t":"Science & Technology","q":"Aditya-L1 is placed in a halo orbit around which type of gravitationally balanced point in space?","w":"Aditya-L1, India's first space-based solar observatory, was launched by PSLV-C57 on 2 September 2023 and placed in a halo orbit around Lagrange point 1 (L1) of the Sun–Earth system on 6 January 2024. L1 is about 1.5 million km from Earth towards the Sun; there the combined pull of the Sun and Earth lets a spacecraft keep pace with Earth, giving an uninterrupted view of the Sun without eclipses. Polar, sun-synchronous and geostationary are Earth orbits.","o":["Polar","Lagrangian","Sun-synchronous","Geostationary"],"a":[1],"qt":"आदित्य-एल1 को अंतरिक्ष में किस प्रकार के गुरुत्वाकर्षण संतुलित बिंदु के चारों ओर हेलो कक्षा में रखा गया है?","ot":["ध्रुवीय","लाग्रंगियन","सूर्य समकालिक","भू-स्थिर"],"wt":"आदित्य-एल1, भारत की पहली अंतरिक्ष-आधारित सौर वेधशाला, 2 सितंबर 2023 को PSLV-C57 से प्रक्षेपित की गई और 6 जनवरी 2024 को सूर्य–पृथ्वी तंत्र के लाग्रांज बिंदु 1 (L1) के चारों ओर हेलो कक्षा में स्थापित की गई। L1 पृथ्वी से सूर्य की दिशा में लगभग 15 लाख किमी दूर है; वहाँ सूर्य और पृथ्वी के संयुक्त गुरुत्वाकर्षण के कारण अंतरिक्ष यान पृथ्वी के साथ-साथ चलता है और बिना किसी ग्रहण के सूर्य को लगातार देख सकता है। ध्रुवीय, सूर्य-समकालिक और भू-स्थिर पृथ्वी की कक्षाएँ हैं।"},{"id":"c25s1-50","p":"c25s1","n":50,"s":"pol","t":"Constitution & Rights","q":"Consider the following statements:\n1. The GST Council makes binding recommendations on GST rates.\n2. Article 246A allows States to legislate on intra-state supply of goods and services.\nWhich of the above is/are correct?","w":"Statement 1 is wrong: in Union of India v. Mohit Minerals (2022) the Supreme Court held that GST Council recommendations under Article 279A are not binding; they have persuasive value, because Parliament and the State legislatures both have power to make GST laws. Statement 2 is correct: Article 246A, inserted by the 101st Amendment (2016), empowers Parliament and every State legislature to make laws on GST, while Parliament alone legislates on inter-State supply.","o":["Only 1","Only 2","Both 1 and 2","Neither 1 nor 2"],"a":[1],"qt":"निम्नलिखित कथनों पर विचार कीजिए:\n1. जीएसटी परिषद जीएसटी दरों पर बाध्यकारी सिफारिशें करती है।\n2. अनुच्छेद 246A राज्यों को वस्तुओं और सेवाओं की अंतर-राज्यीय आपूर्ति पर कानून बनाने की अनुमति देता है।\nउपर्युक्त में से कौन सा/से सही है/हैं?","ot":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"wt":"कथन 1 गलत है: यूनियन ऑफ़ इंडिया बनाम मोहित मिनरल्स (2022) में सर्वोच्च न्यायालय ने कहा कि अनुच्छेद 279A के अंतर्गत जीएसटी परिषद की सिफ़ारिशें बाध्यकारी नहीं, केवल प्रेरक महत्व की हैं, क्योंकि संसद और राज्य विधानमंडल दोनों को जीएसटी कानून बनाने की शक्ति है। कथन 2 सही है: 101वें संशोधन (2016) से जोड़ा गया अनुच्छेद 246A संसद और प्रत्येक राज्य विधानमंडल को जीएसटी पर कानून बनाने का अधिकार देता है, जबकि अंतर-राज्यीय आपूर्ति पर केवल संसद कानून बनाती है। ध्यान दें: हिंदी कथन 2 में 'अंतर-राज्यीय' छपना मुद्रण की चूक है; अंग्रेज़ी मूल में intra-state, अर्थात राज्य के भीतर (अंतःराज्यीय) आपूर्ति लिखा है। छपे रूप में कथन 2 गलत होता, पर उत्तर अंग्रेज़ी मूल के अनुसार 'केवल 2' है।"},{"id":"c25s1-51","p":"c25s1","n":51,"s":"qa","t":"Number System & Simplification","q":"What will come in place of ? to satisfy the equation : (√3 + 2)² = ? + 4√3","w":"Expand using (a + b)² = a² + 2ab + b². Here (√3 + 2)² = (√3)² + 2 × √3 × 2 + 2² = 3 + 4√3 + 4 = 7 + 4√3. Comparing 7 + 4√3 with ? + 4√3, the surd parts cancel and the rational part gives ? = 7. A common slip is forgetting the (√3)² = 3 term and choosing 4.","o":["7","6","5","4"],"a":[0],"qt":"समीकरण को संतुष्ट करने के लिए ? के स्थान पर क्या आएगा: (√3 + 2)² = ? + 4√3","ot":["7","6","5","4"],"wt":"(a + b)² = a² + 2ab + b² से विस्तार कीजिए। यहाँ (√3 + 2)² = (√3)² + 2 × √3 × 2 + 2² = 3 + 4√3 + 4 = 7 + 4√3। 7 + 4√3 की तुलना ? + 4√3 से करने पर करणी वाले भाग (4√3) निरस्त हो जाते हैं और परिमेय भाग से ? = 7 मिलता है। एक सामान्य भूल (√3)² = 3 वाले पद को छोड़ देना है, जिससे उत्तर 4 चुन लिया जाता है।"},{"id":"c25s1-52","p":"c25s1","n":52,"s":"qa","t":"Number System & Simplification","q":"Solve: (√7225 − √1225) × (1/5)","w":"Find the square roots first. 7225 ends in 25, so its root ends in 5: 85² = 7225, so √7225 = 85. Similarly 35² = 1225, so √1225 = 35. Then (85 − 35) × 1/5 = 50 × 1/5 = 10. Note that √7225 − √1225 is not √(7225 − 1225); the roots must be taken separately before subtracting.","o":["10","20","30","40"],"a":[0],"qt":"हल करना: (√7225 − √1225) × (1/5)","ot":["10","20","30","40"],"wt":"पहले वर्गमूल ज्ञात कीजिए। 7225 के अंत में 25 है, इसलिए इसके वर्गमूल का अंतिम अंक 5 होगा: 85² = 7225, अतः √7225 = 85। इसी प्रकार 35² = 1225, अतः √1225 = 35। तब (85 − 35) × 1/5 = 50 × 1/5 = 10। ध्यान दें कि √7225 − √1225, √(7225 − 1225) के बराबर नहीं है; घटाने से पहले वर्गमूल अलग-अलग निकालने होते हैं।"},{"id":"c25s1-53","p":"c25s1","n":53,"s":"qa","t":"Ratio, Average & Mixtures","q":"If 25% of (P + Q) = 75% of (P − Q), then find the ratio P: Q.","w":"Write the percentages as fractions: (1/4)(P + Q) = (3/4)(P − Q). Multiplying by 4 gives P + Q = 3P − 3Q, so 4Q = 2P, i.e. P = 2Q. Hence P : Q = 2 : 1. Check: with P = 2, Q = 1, 25% of 3 = 0.75 and 75% of 1 = 0.75, so both sides match.","o":["1 : 2","2 : 1","1 : 3","3 : 1"],"a":[1],"qt":"यदि (P + Q) का 25% = (P − Q) का 75% है, तो P: Q का अनुपात ज्ञात कीजिए।","ot":["1 : 2","2 : 1","1 : 3","3 : 1"],"wt":"प्रतिशतों को भिन्न के रूप में लिखिए: (1/4)(P + Q) = (3/4)(P − Q)। 4 से गुणा करने पर P + Q = 3P − 3Q, अतः 4Q = 2P, अर्थात् P = 2Q। इसलिए P : Q = 2 : 1। जाँच: P = 2, Q = 1 लेने पर 3 का 25% = 0.75 और 1 का 75% = 0.75, अतः दोनों पक्ष बराबर हैं।"},{"id":"c25s1-54","p":"c25s1","n":54,"s":"qa","t":"Ratio, Average & Mixtures","q":"A bag contains ₹5, ₹2, and ₹1 coins in the ratio 2 : 3 : 4. If the total amount of money in the bag is ₹200, find the number of coins of each kind.","w":"The ratio 2 : 3 : 4 is of the number of coins, so let the counts be 2k, 3k and 4k. Their value is 5(2k) + 2(3k) + 1(4k) = 10k + 6k + 4k = 20k. Setting 20k = 200 gives k = 10, so there are 20 coins of ₹5, 30 coins of ₹2 and 40 coins of ₹1. Check: 100 + 60 + 40 = ₹200.","o":["16 coins of ₹5, 24 coins of ₹2, and 32 coins of ₹1","20 coins of ₹5, 30 coins of ₹2, and 40 coins of ₹1","25 coins of ₹5, 35 coins of ₹2, and 45 coins of ₹1","18 coins of ₹5, 27 coins of ₹2, and 36 coins of ₹1"],"a":[1],"qt":"एक बैग में 2 : 3 : 4 के अनुपात में ₹5, ₹2 और ₹1 के सिक्के हैं। यदि बैग में कुल धनराशि ₹200 है, तो प्रत्येक प्रकार के सिक्कों की संख्या ज्ञात कीजिए।","ot":["₹5 के 16 सिक्के, ₹2 के 24 सिक्के और ₹1 के 32 सिक्के","₹5 के 20 सिक्के, ₹2 के 30 सिक्के और ₹1 के 40 सिक्के","₹5 के 25 सिक्के, ₹2 के 35 सिक्के और ₹1 के 45 सिक्के","₹5 के 18 सिक्के, ₹2 के 27 सिक्के और ₹1 के 36 सिक्के"],"wt":"अनुपात 2 : 3 : 4 सिक्कों की संख्या का है, अतः संख्याएँ 2k, 3k और 4k मान लीजिए। इनका कुल मूल्य = 5(2k) + 2(3k) + 1(4k) = 10k + 6k + 4k = 20k। 20k = 200 से k = 10, अतः ₹5 के 20, ₹2 के 30 और ₹1 के 40 सिक्के हैं। जाँच: 100 + 60 + 40 = ₹200।"},{"id":"c25s1-55","p":"c25s1","n":55,"s":"qa","t":"Percentage, Profit & Interest","q":"A shopkeeper marked a watch at ₹800. He sold it after allowing a 15% discount. If his profit on the sale was 20%, what was the cost price of the watch?","w":"Selling price = marked price × (100 − discount)% = 800 × 85/100 = ₹680. A 20% profit means SP = 120% of CP, so CP = 680 × 100/120 = 680/1.2 = ₹566.67. Note that the profit percentage is always reckoned on the cost price, not on the marked price, so the discount and profit cannot simply be added or subtracted.","o":["₹542.36","₹536.47","₹566.67","₹596.34"],"a":[2],"qt":"एक दुकानदार ने एक घड़ी का मूल्य ₹800 अंकित किया। उसने इसे 15% छूट देकर बेचा। यदि बिक्री पर उसका लाभ 20% था, तो घड़ी का क्रय मूल्य क्या था?","ot":["₹542.36","₹536.47","₹566.67","₹596.34"],"wt":"विक्रय मूल्य = अंकित मूल्य × (100 − छूट)% = 800 × 85/100 = ₹680। 20% लाभ का अर्थ है विक्रय मूल्य = क्रय मूल्य का 120%, अतः क्रय मूल्य = 680 × 100/120 = 680/1.2 = ₹566.67। ध्यान दें कि लाभ प्रतिशत सदैव क्रय मूल्य पर गिना जाता है, अंकित मूल्य पर नहीं, इसलिए छूट और लाभ के प्रतिशत सीधे जोड़े या घटाए नहीं जा सकते।"},{"id":"c25s1-56","p":"c25s1","n":56,"s":"qa","t":"Percentage, Profit & Interest","q":"A product is sold at a 20% discount on its marked price. This transaction results in a profit of 10% on its cost price. If the profit earned is ₹300, what would have been the selling price if the product was sold at a 30% discount on its marked price?","w":"Profit of 10% on CP is ₹300, so CP = 300 × 100/10 = ₹3000 and SP = 3000 + 300 = ₹3300. This SP is 80% of the marked price, so MP = 3300/0.8 = ₹4125. At a 30% discount the selling price would be 70% of 4125 = ₹2887.50. Option ₹3300 is the actual selling price at the 20% discount, not the one asked for.","o":["₹2887.50","₹3000.26","₹3300","₹3150"],"a":[0],"qt":"एक उत्पाद को उसके अंकित मूल्य पर 20% छूट पर बेचा जाता है। इस लेन-देन के परिणामस्वरूप उसके क्रय मूल्य पर 10% का लाभ होता है। यदि अर्जित लाभ ₹300 है, तो उत्पाद को उसके अंकित मूल्य पर 30% छूट पर बेचे जाने पर विक्रय मूल्य क्या होता?","ot":["₹2887.50","₹3000.26","₹3300","₹3150"],"wt":"क्रय मूल्य पर 10% लाभ ₹300 है, अतः क्रय मूल्य = 300 × 100/10 = ₹3000 और विक्रय मूल्य = 3000 + 300 = ₹3300। यह विक्रय मूल्य अंकित मूल्य का 80% है, अतः अंकित मूल्य = 3300/0.8 = ₹4125। 30% छूट पर विक्रय मूल्य 4125 का 70% = ₹2887.50 होगा। विकल्प ₹3300 तो 20% छूट पर वास्तविक विक्रय मूल्य है, पूछा गया मूल्य नहीं।"},{"id":"c25s1-57","p":"c25s1","n":57,"s":"qa","t":"Algebra","q":"If the cubic equation a³ − 4a² + 5a − 2 = 0 has the root x, y, z then find the value of x + y + z.","w":"For a cubic pa³ + qa² + ra + s = 0, the sum of the roots is −q/p. Here p = 1 and q = −4, so x + y + z = −(−4)/1 = 4. Check by factorising: a³ − 4a² + 5a − 2 = (a − 1)²(a − 2), so the roots are 1, 1 and 2, whose sum is 4.","o":["5","6","7","4"],"a":[3],"qt":"यदि घन समीकरण a³ − 4a² + 5a − 2 = 0 का मूल x, y, z है तो x + y + z का मान ज्ञात कीजिए।","ot":["5","6","7","4"],"wt":"घन समीकरण pa³ + qa² + ra + s = 0 के मूलों का योग −q/p होता है। यहाँ p = 1 और q = −4, अतः x + y + z = −(−4)/1 = 4। गुणनखंड द्वारा जाँच: a³ − 4a² + 5a − 2 = (a − 1)²(a − 2), अतः मूल 1, 1 और 2 हैं, जिनका योग 4 है।"},{"id":"c25s1-58","p":"c25s1","n":58,"s":"qa","t":"Percentage, Profit & Interest","q":"C borrowed ₹6000 from D on 15 March 2023 at a simple interest rate of 10% per annum. C decided to repay the loan on 15 September 2023. How much total amount must C return to D?","w":"From 15 March 2023 to 15 September 2023 is exactly 6 months, i.e. T = 1/2 year. Simple interest = P × R × T/100 = 6000 × 10 × (1/2)/100 = ₹300. The total amount to be returned = principal + interest = 6000 + 300 = ₹6300. ₹6600 would be the amount for a full year, which is not the period here.","o":["₹6300","₹6500","₹5400","₹5800"],"a":[0],"qt":"C ने 15 मार्च 2023 को D से 10% प्रति वर्ष की साधारण ब्याज दर पर ₹6000 उधार लिए। C ने 15 सितंबर 2023 को ऋण चुकाने का फैसला किया। C को D को कुल कितनी राशि वापस करनी होगी?","ot":["₹6300","₹6500","₹5400","₹5800"],"wt":"15 मार्च 2023 से 15 सितंबर 2023 तक ठीक 6 महीने हैं, अर्थात् T = 1/2 वर्ष। साधारण ब्याज = P × R × T/100 = 6000 × 10 × (1/2)/100 = ₹300। लौटाई जाने वाली कुल राशि = मूलधन + ब्याज = 6000 + 300 = ₹6300। ₹6600 पूरे एक वर्ष की राशि होती, जो यहाँ की अवधि नहीं है।"},{"id":"c25s1-59","p":"c25s1","n":59,"s":"qa","t":"Percentage, Profit & Interest","q":"A person invested a total sum of ₹2200 in three different schemes of simple interest at 4%, 5%, and 10% per annum. At the end of one year, he got the same interest from all three schemes. What was the amount (in ₹) invested at 5%?","w":"Let the equal one-year interest be k. Then the sums are k/0.04 = 25k, k/0.05 = 20k and k/0.10 = 10k, so they are in the ratio 25 : 20 : 10 = 5 : 4 : 2. Total 55k = 2200 gives k = 40, so the amount at 5% = 20 × 40 = ₹800. Check: 4% of 1000, 5% of 800 and 10% of 400 are all ₹40.","o":["₹1000","₹800","₹600","₹400"],"a":[1],"qt":"एक व्यक्ति ने ₹2200 की कुल राशि को साधारण ब्याज की तीन विभिन्न योजनाओं में 4%, 5% और 10% वार्षिक दर पर एक वर्ष के लिए निवेश किया। एक वर्ष के अंत में उसे तीनों योजनाओं से समान ब्याज प्राप्त हुआ। बताइए, उसने 5% ब्याज दर वाली योजना में कितनी राशि (₹ में) निवेश की थी?","ot":["₹1000","₹800","₹600","₹400"],"wt":"मान लीजिए एक वर्ष का समान ब्याज k है। तब राशियाँ k/0.04 = 25k, k/0.05 = 20k और k/0.10 = 10k हैं, अर्थात् इनका अनुपात 25 : 20 : 10 = 5 : 4 : 2 है। कुल 55k = 2200 से k = 40, अतः 5% पर निवेश की गई राशि = 20 × 40 = ₹800। जाँच: 1000 का 4%, 800 का 5% और 400 का 10%, तीनों ₹40 हैं।"},{"id":"c25s1-60","p":"c25s1","n":60,"s":"qa","t":"Trigonometry & Heights","q":"A man standing on the top of a 120 m high tower observes the angles of depression of two cars on opposite sides of the tower to be 30° and 45°. What is the distance between the two cars?","w":"The angle of depression equals the angle of elevation from each car. For 30°: distance = 120/tan 30° = 120√3 m. For 45°: distance = 120/tan 45° = 120 m. As the cars are on opposite sides, the distances add: 120√3 + 120 = 120(√3 + 1) m ≈ 327.8 m. The difference 120(√3 − 1) m would apply only if both cars were on the same side.","o":["120(√3 − 1) m","120√3 m","120 (1 + 1/√3) m","120(√3 + 1) m"],"a":[3],"qt":"120 मीटर ऊँचे टावर के शीर्ष पर खड़ा एक व्यक्ति टावर के विपरीत दिशाओं में खड़ी दो कारों के अवनमन कोण 30° और 45° देखता है। दोनों कारों के बीच की दूरी क्या है?","ot":["120(√3 − 1) मीटर","120√3 मीटर","120 (1 + 1/√3) मीटर","120(√3 + 1) मीटर"],"wt":"अवनमन कोण प्रत्येक कार से देखे गए उन्नयन कोण के बराबर होता है। 30° के लिए दूरी = 120/tan 30° = 120√3 मीटर। 45° के लिए दूरी = 120/tan 45° = 120 मीटर। कारें टावर के विपरीत ओर हैं, इसलिए दूरियाँ जुड़ेंगी: 120√3 + 120 = 120(√3 + 1) मीटर ≈ 327.8 मीटर। अंतर 120(√3 − 1) मीटर तभी लागू होता जब दोनों कारें एक ही ओर होतीं।"},{"id":"c25s1-61","p":"c25s1","n":61,"s":"qa","t":"Trigonometry & Heights","q":"A vertical pole TF has its base F on the ground. From a point A, 25 meters from F, the angle of elevation of T is x°. From another point B, 75 meters from F (and in the same line as A), the angle of elevation of T is y°. If the height of the pole is 25√3 meters, what is the value of x° + y°?","w":"In right triangle TFA, tan x = TF/FA = 25√3/25 = √3, so x = 60°. In right triangle TFB, tan y = TF/FB = 25√3/75 = 1/√3, so y = 30°. Therefore x° + y° = 60° + 30° = 90°. Remember tan 60° = √3 and tan 30° = 1/√3; the nearer point always gives the larger angle of elevation.","o":["60°","75°","90°","120°"],"a":[2],"qt":"एक ऊर्ध्वाधर खंभा TF का आधार F ज़मीन पर है। F से 25 मीटर दूर एक बिंदु A से, T का उन्नयन कोण x° है। F से 75 मीटर दूर (और A के समान रेखा में) दूसरे बिंदु B से, T का उन्नयन कोण y° है। यदि खंभे की ऊँचाई 25√3 मीटर है, तो x° + y° का मान क्या है?","ot":["60°","75°","90°","120°"],"wt":"समकोण त्रिभुज TFA में tan x = TF/FA = 25√3/25 = √3, अतः x = 60°। समकोण त्रिभुज TFB में tan y = TF/FB = 25√3/75 = 1/√3, अतः y = 30°। इसलिए x° + y° = 60° + 30° = 90°। याद रखें tan 60° = √3 और tan 30° = 1/√3; निकट वाले बिंदु से उन्नयन कोण सदैव बड़ा होता है।"},{"id":"c25s1-62","p":"c25s1","n":62,"s":"qa","t":"Mensuration","q":"Two identical solid hemispheres, each with a radius of 21 cm, are melted and recast into a single sphere. What is the radius of the new sphere formed?","w":"Volume is conserved on melting and recasting. Volume of one hemisphere = (2/3)πr³, so two hemispheres give 2 × (2/3)π(21)³ = (4/3)π(21)³. Setting (4/3)πR³ = (4/3)π(21)³ gives R³ = 21³, so R = 21 cm. Two identical hemispheres of radius r together make exactly one sphere of the same radius r.","o":["18 cm","21 cm","24 cm","27 cm"],"a":[1],"qt":"दो समान ठोस अर्धगोले, जिनमें प्रत्येक का त्रिज्या 21 सेमी है, को पिघलाकर एक पूर्ण गोला बनाया गया। बने हुए नए गोले की त्रिज्या क्या होगी?","ot":["18 सेमी","21 सेमी","24 सेमी","27 सेमी"],"wt":"पिघलाकर पुनः ढालने पर आयतन समान रहता है। एक अर्धगोले का आयतन = (2/3)πr³, अतः दो अर्धगोलों का आयतन = 2 × (2/3)π(21)³ = (4/3)π(21)³। (4/3)πR³ = (4/3)π(21)³ रखने पर R³ = 21³, अतः R = 21 सेमी। त्रिज्या r के दो समान अर्धगोले मिलकर ठीक उसी त्रिज्या r का एक गोला बनाते हैं।"},{"id":"c25s1-63","p":"c25s1","n":63,"s":"qa","t":"Mensuration","q":"Creating a frustum, a right circular cone is sliced parallel to its base. The height of the original cone is 30 cm, and the cut is made 10 cm from the vertex. What is the ratio of the volumes of the frustum to that of the entire cone?","w":"The small cone cut off at the top (height 10 cm) is similar to the whole cone (height 30 cm), with scale factor 10/30 = 1/3. Volumes of similar solids vary as the cube of the scale factor, so the small cone has (1/3)³ = 1/27 of the full volume. The frustum therefore has 1 − 1/27 = 26/27 of the volume, giving frustum : cone = 26 : 27.","o":["26:27","11:18","16:19","14:15"],"a":[0],"qt":"एक छिन्नक बनाते हुए, एक लम्बवृत्तीय शंकु को उसके आधार के समांतर काटा जाता है। मूल शंकु की ऊँचाई 30 सेमी है, और कट शीर्ष से 10 सेमी की दूरी पर काटा जाता है। छिन्नक के आयतन और पूरे शंकु के आयतन का अनुपात क्या है?","ot":["26:27","11:18","16:19","14:15"],"wt":"ऊपर से कटकर अलग हुआ छोटा शंकु (ऊँचाई 10 सेमी) पूरे शंकु (ऊँचाई 30 सेमी) के समरूप है, और इनकी रैखिक मापों का अनुपात 10/30 = 1/3 है। समरूप ठोसों के आयतन इस अनुपात के घन के अनुसार बदलते हैं, अतः छोटे शंकु का आयतन पूरे आयतन का (1/3)³ = 1/27 है। इसलिए छिन्नक का आयतन 1 − 1/27 = 26/27 है, अर्थात् छिन्नक : शंकु = 26 : 27।"},{"id":"c25s1-64","p":"c25s1","n":64,"s":"qa","t":"Mensuration","q":"The side of a regular octagon is half the side of a regular quadrilateral (square). If the perimeter of the quadrilateral is 20cm, what is the perimeter of the octagon?","w":"The square's side = perimeter/4 = 20/4 = 5 cm. The octagon's side is half of this, i.e. 2.5 cm. A regular octagon has 8 equal sides, so its perimeter = 8 × 2.5 = 20 cm. Shortcut: twice as many sides, each half as long, keeps the perimeter the same as the square's.","o":["10 cm","20 cm","30 cm","40 cm"],"a":[1],"qt":"एक सम अष्टभुज की भुजा एक सम चतुर्भुज (वर्ग) की भुजा की आधी है। यदि चतुर्भुज का परिमाप 20 सेमी है, तो अष्टभुज का परिमाप क्या है?","ot":["10 सेमी","20 सेमी","30 सेमी","40 सेमी"],"wt":"वर्ग की भुजा = परिमाप/4 = 20/4 = 5 सेमी। अष्टभुज की भुजा इसकी आधी, अर्थात् 2.5 सेमी है। सम अष्टभुज की 8 बराबर भुजाएँ होती हैं, अतः इसका परिमाप = 8 × 2.5 = 20 सेमी। संक्षिप्त विधि: भुजाओं की संख्या दोगुनी और प्रत्येक भुजा आधी, इसलिए परिमाप वर्ग के परिमाप के बराबर ही रहता है।"},{"id":"c25s1-65","p":"c25s1","n":65,"s":"qa","t":"Mensuration","q":"A decorative column is made in the shape of a regular hexagonal prism. The side length of its base is 10 cm. The column is built from multiple sections, and their heights form an arithmetic progression: the first section is 5 cm tall, and each subsequent section is 2 cm taller than the previous one. If the column has 4 sections in total, what is the total volume of the column?","w":"Area of a regular hexagon = (3√3/2)a² = (3√3/2) × 100 = 150√3 cm². The section heights are 5, 7, 9 and 11 cm, so the total height = (4/2)[2 × 5 + 3 × 2] = 32 cm. Volume of the prism = base area × height = 150√3 × 32 = 4800√3 cm³.","o":["4500√3 cm³","4800√3 cm³","5100√3 cm³","5400√3 cm³"],"a":[1],"qt":"एक सजावटी स्तंभ एक सम षट्कोणीय प्रिज्म के आकार में बना है। इसके आधार की भुजा की लंबाई 10 सेमी है। स्तंभ कई खंडों से बना है, और उनकी ऊँचाई एक अंकगणितीय श्रेणी बनाती है: पहला खंड 5 सेमी ऊँचा है, और प्रत्येक अगला खंड पिछले वाले से 2 सेमी ऊँचा है। यदि स्तंभ में कुल 4 खंड हैं, तो स्तंभ का कुल आयतन क्या है?","ot":["4500√3 सेमी³","4800√3 सेमी³","5100√3 सेमी³","5400√3 सेमी³"],"wt":"सम षट्भुज का क्षेत्रफल = (3√3/2)a² = (3√3/2) × 100 = 150√3 सेमी²। खंडों की ऊँचाइयाँ 5, 7, 9 और 11 सेमी हैं, अतः कुल ऊँचाई = (4/2)[2 × 5 + 3 × 2] = 32 सेमी। प्रिज्म का आयतन = आधार का क्षेत्रफल × ऊँचाई = 150√3 × 32 = 4800√3 सेमी³।"},{"id":"c25s1-66","p":"c25s1","n":66,"s":"qa","t":"Geometry","q":"Find the midpoint of segment joining (3,4) and (7,8).","w":"The midpoint of the segment joining (x₁, y₁) and (x₂, y₂) is ((x₁ + x₂)/2, (y₁ + y₂)/2). Here it is ((3 + 7)/2, (4 + 8)/2) = (10/2, 12/2) = (5, 6). Option (3, 4) is just one of the end points. A quick check: the midpoint must lie halfway, 2 units from each end in both x and y.","o":["(3, 4)","(5, 6)","(4, 5)","(6, 7)"],"a":[1],"qt":"(3,4) और (7,8) को मिलाने वाले रेखाखण्ड का मध्यबिंदु ज्ञात कीजिए।","ot":["(3, 4)","(5, 6)","(4, 5)","(6, 7)"],"wt":"(x₁, y₁) और (x₂, y₂) को मिलाने वाले रेखाखंड का मध्यबिंदु ((x₁ + x₂)/2, (y₁ + y₂)/2) होता है। यहाँ यह ((3 + 7)/2, (4 + 8)/2) = (10/2, 12/2) = (5, 6) है। विकल्प (3, 4) तो एक अंत्य बिंदु ही है। त्वरित जाँच: मध्यबिंदु ठीक बीच में, दोनों सिरों से x और y दोनों में 2 इकाई की दूरी पर होना चाहिए।"},{"id":"c25s1-67","p":"c25s1","n":67,"s":"qa","t":"Geometry","q":"The number of diagonals in a hexagon is:","w":"A polygon with n sides has n(n − 3)/2 diagonals, because each vertex joins to n − 3 non-adjacent vertices and each diagonal is counted twice. For a hexagon n = 6, so the number of diagonals = 6 × 3/2 = 9. The answer 15 is ⁶C₂, which counts the 6 sides as well as the 9 diagonals.","o":["6","9","12","15"],"a":[1],"qt":"एक षट्भुज में विकर्णों की संख्या है:","ot":["6","9","12","15"],"wt":"n भुजाओं वाले बहुभुज में n(n − 3)/2 विकर्ण होते हैं, क्योंकि प्रत्येक शीर्ष n − 3 असंलग्न शीर्षों से जुड़ता है और प्रत्येक विकर्ण दो बार गिना जाता है। षट्भुज के लिए n = 6, अतः विकर्णों की संख्या = 6 × 3/2 = 9। उत्तर 15 तो ⁶C₂ है, जिसमें 9 विकर्णों के साथ 6 भुजाएँ भी गिन ली जाती हैं।"},{"id":"c25s1-68","p":"c25s1","n":68,"s":"qa","t":"Geometry","q":"Triangle ABC has its centroid at point G(4, 5), and vertex A is located at (2, 3). If point D is the midpoint of side BC, what are the coordinates of D?","w":"AD is a median, and the centroid divides it in the ratio AG : GD = 2 : 1, so G = (A + 2D)/3. Hence D = (3G − A)/2 = ((12 − 2)/2, (15 − 3)/2) = (5, 6). Check: from A(2, 3) to G(4, 5) the step is (2, 2), and from G to D(5, 6) it is (1, 1), exactly half, as required.","o":["(5, 6)","(5, 8)","(6, 7)","(6, 8)"],"a":[0],"qt":"त्रिभुज ABC का केन्द्रक बिंदु G(4, 5) पर है, तथा शीर्ष A, (2, 3) पर स्थित है। यदि बिंदु D, भुजा BC का मध्य-बिंदु है, तो D के निर्देशांक क्या हैं?","ot":["(5, 6)","(5, 8)","(6, 7)","(6, 8)"],"wt":"AD एक माध्यिका है, और केन्द्रक इसे AG : GD = 2 : 1 के अनुपात में विभाजित करता है, अतः G = (A + 2D)/3। इसलिए D = (3G − A)/2 = ((12 − 2)/2, (15 − 3)/2) = (5, 6)। जाँच: A(2, 3) से G(4, 5) तक का अंतर (2, 2) है और G से D(5, 6) तक (1, 1), जो ठीक आधा है, जैसा होना चाहिए।"},{"id":"c25s1-69","p":"c25s1","n":69,"s":"qa","t":"Algebra","q":"Given, √(x + 3) + √(x − 2) = 5, then find the value of x.","w":"Let a = √(x + 3) and b = √(x − 2). Then a + b = 5 and a² − b² = (x + 3) − (x − 2) = 5, so a − b = 5/5 = 1. Adding gives 2a = 6, a = 3, so x + 3 = 9 and x = 6. Check: √9 + √4 = 3 + 2 = 5.","o":["5","6","7","8"],"a":[1],"qt":"दिया गया है, √(x + 3) + √(x − 2) = 5, तो x का मान ज्ञात कीजिए।","ot":["5","6","7","8"],"wt":"मान लीजिए a = √(x + 3) और b = √(x − 2)। तब a + b = 5 और a² − b² = (x + 3) − (x − 2) = 5, अतः a − b = 5/5 = 1। जोड़ने पर 2a = 6, a = 3, अतः x + 3 = 9 और x = 6। जाँच: √9 + √4 = 3 + 2 = 5।"},{"id":"c25s1-70","p":"c25s1","n":70,"s":"qa","t":"Geometry","q":"A common internal tangent connecting two circles is 9 cm long. The distance between the circles' centers is 15 cm. If the larger circle has a radius of 8 cm, what is the radius of the smaller circle?","w":"Length of a common internal (transverse) tangent = √[d² − (r₁ + r₂)²]. So 9² = 15² − (8 + r)², giving (8 + r)² = 225 − 81 = 144, so 8 + r = 12 and r = 4 cm. Using the direct-tangent formula √[d² − (r₁ − r₂)²] instead would give r = 20, which is not smaller, so the internal formula is the right one.","o":["4 cm","1 cm","6 cm","7 cm"],"a":[0],"qt":"दो वृत्तों को जोड़ने वाली एक उभयनिष्ठ आंतरिक स्पर्श रेखा 9 सेमी लंबी है। वृत्तों के केंद्रों के बीच की दूरी 15 सेमी है। यदि बड़े वृत्त की त्रिज्या 8 सेमी है, तो छोटे वृत्त की त्रिज्या क्या है?","ot":["4 सेमी","1 सेमी","6 सेमी","7 सेमी"],"wt":"उभयनिष्ठ आंतरिक (अनुप्रस्थ) स्पर्श रेखा की लंबाई = √[d² − (r₁ + r₂)²]। अतः 9² = 15² − (8 + r)², जिससे (8 + r)² = 225 − 81 = 144, अतः 8 + r = 12 और r = 4 सेमी। इसके स्थान पर सीधी (बाह्य) उभयनिष्ठ स्पर्श रेखा का सूत्र √[d² − (r₁ − r₂)²] लगाने पर r = 20 आता, जो छोटी त्रिज्या नहीं है, इसलिए आंतरिक स्पर्श रेखा का सूत्र ही सही है।"},{"id":"c25s1-71","p":"c25s1","n":71,"s":"qa","t":"Geometry","q":"In a cyclic quadrilateral ABCD, AB is the diameter of the circle. If angle ACD is 40°, what is the measure of angle BAD?","w":"Angles in the same segment are equal, so ∠ABD = ∠ACD = 40° (both stand on chord AD). Since AB is a diameter, ∠ADB = 90° (angle in a semicircle). In triangle ABD, ∠BAD = 180° − 90° − 40° = 50°. Choosing 40° confuses ∠BAD with ∠ABD.","o":["40°","50°","80°","90°"],"a":[1],"qt":"एक चक्रीय चतुर्भुज ABCD में, AB वृत्त का व्यास है। यदि कोण ACD 40° है, तो कोण BAD का माप क्या है?","ot":["40°","50°","80°","90°"],"wt":"एक ही वृत्तखंड में बने कोण बराबर होते हैं, अतः ∠ABD = ∠ACD = 40° (दोनों जीवा AD पर बने हैं)। AB व्यास है, इसलिए ∠ADB = 90° (अर्धवृत्त में बना कोण)। त्रिभुज ABD में ∠BAD = 180° − 90° − 40° = 50°। 40° चुनना ∠BAD को ∠ABD समझ लेने की भूल है।"},{"id":"c25s1-72","p":"c25s1","n":72,"s":"qa","t":"Trigonometry & Heights","q":"If sin²A − cos²A = 1/2, find the value of cos²A.","w":"Use the identity sin²A = 1 − cos²A. Then (1 − cos²A) − cos²A = 1/2, i.e. 1 − 2cos²A = 1/2, so 2cos²A = 1/2 and cos²A = 1/4. Then sin²A = 3/4, and indeed 3/4 − 1/4 = 1/2. Option 3/4 is the value of sin²A, not cos²A.","o":["1/2","1/4","3/4","2/3"],"a":[1],"qt":"यदि sin²A − cos²A = 1/2, तो cos²A का मान ज्ञात कीजिए।","ot":["1/2","1/4","3/4","2/3"],"wt":"सर्वसमिका sin²A = 1 − cos²A का प्रयोग कीजिए। तब (1 − cos²A) − cos²A = 1/2, अर्थात् 1 − 2cos²A = 1/2, अतः 2cos²A = 1/2 और cos²A = 1/4। तब sin²A = 3/4, और वास्तव में 3/4 − 1/4 = 1/2। विकल्प 3/4, sin²A का मान है, cos²A का नहीं।"},{"id":"c25s1-73","p":"c25s1","n":73,"s":"qa","t":"Trigonometry & Heights","q":"If cot A = x + 1/x, find cosec²A.","w":"Use the identity cosec²A = 1 + cot²A. Here cot²A = (x + 1/x)² = x² + 2 + 1/x², so cosec²A = 1 + x² + 2 + 1/x² = x² + 1/x² + 3. Forgetting the middle term 2 of the square gives x² + 1/x² + 1, which is wrong. (Options 1 and 2 are printed identically on the sheet.)","o":["x² + 1/x² + 1","x² + 1/x² + 1","x² + 1/x² + 3","x² + 1/x² − 1"],"a":[2],"qt":"यदि cot A = x + 1/x, तो cosec²A का मान ज्ञात कीजिए.","ot":["x² + 1/x² + 1","x² + 1/x² + 1","x² + 1/x² + 3","x² + 1/x² − 1"],"wt":"सर्वसमिका cosec²A = 1 + cot²A का प्रयोग कीजिए। यहाँ cot²A = (x + 1/x)² = x² + 2 + 1/x², अतः cosec²A = 1 + x² + 2 + 1/x² = x² + 1/x² + 3। वर्ग के मध्य पद 2 को भूल जाने पर x² + 1/x² + 1 आता है, जो गलत है। (प्रश्नपत्र में विकल्प 1 और 2 एक जैसे छपे हैं।)"},{"id":"c25s1-74","p":"c25s1","n":74,"s":"qa","t":"Number System & Simplification","q":"What is the value of (0.12³ + 0.06³) ÷ (0.24³ + 0.12³)?","w":"Each term of the numerator is half the matching term of the denominator: 0.12 = ½ × 0.24 and 0.06 = ½ × 0.12. So the numerator = (½)³ × (0.24³ + 0.12³), and the ratio = (½)³ = 1/8 = 0.125. Taking the ratio of the bases, 0.5, forgets that the terms are cubed.","o":["0.125","0.5","0.25","1"],"a":[0],"qt":"(0.12³ + 0.06³) ÷ (0.24³ + 0.12³) का मान क्या है?","ot":["0.125","0.5","0.25","1"],"wt":"अंश का प्रत्येक पद हर के संगत पद का आधा है: 0.12 = ½ × 0.24 और 0.06 = ½ × 0.12। अतः अंश = (½)³ × (0.24³ + 0.12³), और अनुपात = (½)³ = 1/8 = 0.125। आधारों का अनुपात 0.5 लेने में यह भूल होती है कि पदों का घन लिया गया है।"},{"id":"c25s1-75","p":"c25s1","n":75,"s":"qa","t":"Number System & Simplification","q":"Simplify: ((0.5)³ + (0.05)³ + (0.005)³) ÷ ((0.1)³ + (0.01)³ + (0.001)³)","w":"Each numerator term is 5 times the matching denominator term: 0.5 = 5 × 0.1, 0.05 = 5 × 0.01, 0.005 = 5 × 0.001. Hence the numerator = 5³ × ((0.1)³ + (0.01)³ + (0.001)³), and the ratio = 5³ = 125. Answer 5 forgets the cube on each term.","o":["5","25","125","625"],"a":[2],"qt":"सरलीकरण: ((0.5)³ + (0.05)³ + (0.005)³) ÷ ((0.1)³ + (0.01)³ + (0.001)³)","ot":["5","25","125","625"],"wt":"अंश का प्रत्येक पद हर के संगत पद का 5 गुना है: 0.5 = 5 × 0.1, 0.05 = 5 × 0.01, 0.005 = 5 × 0.001। अतः अंश = 5³ × ((0.1)³ + (0.01)³ + (0.001)³), और अनुपात = 5³ = 125। उत्तर 5 प्रत्येक पद के घन को भूल जाने से आता है।"},{"id":"c25s1-76","p":"c25s1","n":76,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word: COGENT","w":"'Cogent' describes an argument or reason that is clear, logical and persuasive, so its synonym is 'convincing' (a cogent argument convinces the listener). 'Weak', 'dubious' (doubtful) and 'unclear' all describe arguments that fail to persuade, so they are closer to antonyms. The word comes from Latin cogere, 'to compel', which suggests reasoning that compels agreement.","o":["Weak","Dubious","Convincing","Unclear"],"a":[2]},{"id":"c25s1-77","p":"c25s1","n":77,"s":"eng","t":"Vocabulary","q":"Select the most appropriate antonym of the given word. Lassitude","w":"'Lassitude' means a state of physical or mental tiredness and lack of energy. Its opposite is 'vigor' (British 'vigour'), meaning strength, energy and enthusiasm. 'Exhaustion' and 'lethargy' are near-synonyms of lassitude, and 'apathy' (lack of interest or concern) is closely related, so none of these can be the antonym.","o":["Exhaustion","Apathy","Vigor","Lethargy"],"a":[2]},{"id":"c25s1-78","p":"c25s1","n":78,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct meaning of idiom:\nWon his laurels","w":"To 'win (or gain) one's laurels' means to achieve honour, distinction or fame through one's achievements. In ancient Greece and Rome a wreath of laurel leaves was placed on the heads of victors and poets, so laurels became a symbol of glory. A related idiom, 'rest on one's laurels', means to be satisfied with past success and stop trying.","o":["Achieved distinction or fame","Lost everything","Changed his opinion","Saved money"],"a":[0]},{"id":"c25s1-79","p":"c25s1","n":79,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct meaning of idiom:\nCame of age","w":"To 'come of age' means to reach the age at which a person is legally regarded as an adult (the age of majority, 18 in India) or to become socially mature. Figuratively it also means that something has become fully developed, as in 'the industry has come of age'. Inheriting property may happen on coming of age, but that is not the meaning of the idiom.","o":["Reached adulthood legally or socially","Understood morality for the first time","Abandoned earlier beliefs","Inherited property"],"a":[0]},{"id":"c25s1-80","p":"c25s1","n":80,"s":"eng","t":"Spelling","q":"Select the correct spelling of a word meaning 'cheerfully optimistic, especially in difficult times'.","w":"The correct spelling is 'sanguine' (s-a-n-g-u-i-n-e), meaning optimistic and positive, especially in a difficult situation, as in 'He remained sanguine about the result'. It comes from Latin sanguis, 'blood', because a 'blood-dominant' temperament was believed to make people cheerful. 'Sangwine' and 'Sanguin' are misspellings, and 'Sangueenm' is not a word.","o":["Sanguine","Sangwine","Sanguin","Sangueenm"],"a":[0]},{"id":"c25s1-81","p":"c25s1","n":81,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct one-word substitution for: ‘A loud and confused noise’.","w":"'Cacophony' (Greek kakos 'bad' + phone 'sound') is a harsh, discordant and confused mixture of loud sounds. 'Soliloquy' is a speech made by a character alone on stage. 'Racket' is an informal word for a loud, unpleasant noise and 'roar' is a deep, loud sound; cacophony is the standard one-word substitute when the stress is on a confused, jarring mixture of sounds.","o":["Cacophony","Soliloquy","Racket","Roar"],"a":[0]},{"id":"c25s1-82","p":"c25s1","n":82,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct one-word substitute for: 'One who writes traditional poems'.","w":"A 'bard' is a poet, originally one who composed and recited traditional epic or heroic verse; Shakespeare is called 'the Bard of Avon'. A 'lyricist' writes the words of songs, a 'dramatist' writes plays, and an 'essayist' writes essays (short prose pieces). Only 'bard' matches a writer of traditional poems.","o":["Bard","Lyricist","Dramatist","Essayist"],"a":[0]},{"id":"c25s1-83","p":"c25s1","n":83,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Fill in the blank with the right phrasal verb:\nThe investigation was ______ after new evidence emerged.","w":"'Take up' means to begin dealing with or to start working on a matter, so 'The investigation was taken up after new evidence emerged' shows the fresh evidence led to the case being started or reopened. 'Called off' means cancelled, which does not follow from new evidence emerging. 'Picked up' is used for things gaining speed or for collecting, and 'revived up' is not an accepted phrasal verb (the verb is simply 'revived').","o":["called off","picked up","taken up","revived up"],"a":[2]},{"id":"c25s1-84","p":"c25s1","n":84,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Select the correct option:\nThe biochemist insisted ______ conducting a double-blind trial before publication.","w":"The verb 'insist' takes the preposition 'on' (or 'upon') before a noun or gerund: insist on doing something. Hence 'The biochemist insisted on conducting a double-blind trial before publication.' 'Insist with', 'insist to' and 'insist about' are not idiomatic. Alternatively, insist can take a that-clause: 'insisted that a double-blind trial be conducted'.","o":["with","on","to","about"],"a":[1]},{"id":"c25s1-85","p":"c25s1","n":85,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Find the part of the sentence that contains an error:\nThe interns were asked (1)/ to complete the assignment quickly (2)/ and submit it (3)/ with neat handwriting. (4)/","w":"The error is in part (4). Something is written 'in' a particular handwriting, so the correct phrase is 'in neat handwriting' (just as we say 'in ink', 'in capital letters'). The rest is correct: 'were asked to complete' is a proper passive with an infinitive, and 'to complete... and submit it' keeps the two infinitives parallel.","o":["(1)","(2)","(3)","(4)"],"a":[3]},{"id":"c25s1-86","p":"c25s1","n":86,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Find the part of the sentence that contains an error:\nIt was at the summit in Vienna (1)/ where the treaty was officially ratified, (2)/ thereby bringing to an end (3)/ decades of political uncertainty in the region. (4)","w":"The sentence is a cleft sentence, 'It was ... that ...', used to emphasise a phrase. When the emphasised part is an adverbial phrase of place such as 'at the summit in Vienna', it is followed by 'that', not 'where', because 'at' already expresses the place. So part (2) should read 'that the treaty was officially ratified'. 'Bringing to an end decades of...' in part (3) is correct.","o":["(1)","(2)","(3)","(4)"],"a":[1]},{"id":"c25s1-87","p":"c25s1","n":87,"s":"eng","t":"Voice & Narration","q":"Change the following from active to passive:\nThey had been negotiating the deal for months.","w":"The active verb 'had been negotiating' is past perfect continuous. Its passive form is had been + being + past participle, so the object 'the deal' becomes the subject: 'The deal had been being negotiated for months.' Option 1 keeps the active -ing form, option 3 wrongly changes the tense to present perfect, and option 4 changes it to past continuous. The agent 'by them' is dropped as it is vague.","o":["The deal had been negotiating for months.","The deal had been being negotiated for months.","The deal has been being negotiated for months.","The deal was being negotiated for months."],"a":[1]},{"id":"c25s1-88","p":"c25s1","n":88,"s":"eng","t":"Vocabulary","q":"Select the sentence containing the homonym of the highlighted word:\nThe nobleman received a ceremonial \"fief\" from the sovereign.","w":"A homonym is a word with the same spelling or sound as another but a different meaning. In the given sentence 'fief' has its feudal sense: land granted by a lord in return for loyal service. Options 1, 2 and 4 use 'fief' in this same land-tenure sense, so they are ruled out. Only option 3 puts 'fief' in an unrelated, mechanical context, so it is the intended answer by elimination. Strictly, dictionaries record no engineering sense of 'fief' (its only other meaning is figurative: an area under one person's control), so the question is loosely framed.","o":["The farmer leased the fief to a local tenant.","The law student confused fief with deed transfer.","The engineer calibrated the hydraulic fief for flow control.","The archives recorded the transfer of fief in Latin."],"a":[2]},{"id":"c25s1-89","p":"c25s1","n":89,"s":"eng","t":"Voice & Narration","q":"Convert the sentence provided below from its passive voice structure to an active voice structure:\nThe possibility of the files being leaked before the official release was not ruled out.","w":"The passive 'was not ruled out' is simple past with no agent, so a general subject such as 'someone' is supplied and the verb becomes 'did not rule out', with 'the possibility' as the object: 'Someone did not rule out the possibility that the files were leaked before release.' Option 1 reverses the meaning (ruled out instead of not ruled out), option 2 is still passive, and option 4 changes the meaning entirely.","o":["Officials ruled out the leak before the files were released.","The leak of the files was ruled out before the release.","Someone did not rule out the possibility that the files were leaked before release.","The release happened before ruling out the leak possibility."],"a":[2]},{"id":"c25s1-90","p":"c25s1","n":90,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Choose the most suitable option to replace the highlighted part of the sentence:\nThe manager \"is angry on\" the clerk.","w":"'Angry on' is never correct. The traditional rule taught for exams is: angry with a person, angry at or about a thing or situation. Since the clerk is a person, 'The manager is angry with the clerk' is the answer. 'Angry over' is used for an issue (angry over the delay), and 'is annoyed by' changes the expression. Modern dictionaries also allow 'angry at somebody', but SSC follows the traditional rule. (SSC key; some sources differ.)","o":["is angry at","is annoyed by","is angry with","is angry over"],"a":[2]},{"id":"c25s1-91","p":"c25s1","n":91,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Choose the most suitable option to replace the highlighted part of the sentence:\nHe was \"accused for stealing\" the documents.","w":"The verb 'accuse' always takes the preposition 'of' followed by a noun or gerund: accuse someone of something. So 'He was accused of stealing the documents' is correct. 'Accused for', 'accused to steal' and 'accused with' are wrong. Note the related verb 'charge', which takes 'with': 'He was charged with stealing'; 'charged for steal' is wrong in both preposition and verb form.","o":["accused of stealing","accused to steal","accused with stealing","charged for steal"],"a":[0]},{"id":"c25s1-92","p":"c25s1","n":92,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nThe accelerating depletion of fossil fuels, coupled with mounting ecological degradation, has propelled renewable energy from a peripheral concern to a central component of global energy discourse. Yet, the conversation often fixates on production rather than application. A nuanced understanding of renewable energy must include not only its sources—solar, wind, hydro, geothermal, and biomass—but also the multifaceted domains in which it can transform economies, decentralize power structures, and promote environmental justice. In the domain of electricity generation, renewables have already begun to displace conventional energy systems. Solar photovoltaic installations now power not only urban rooftops but remote rural hamlets long excluded from centralized grids. Micro-hydel projects have enabled mountain communities to harness perennial streams for electricity without the ecological upheaval of large dams. Similarly, wind energy has emerged as a significant contributor in coastal and arid zones, transforming local economies by creating decentralized, sustainable employment ecosystems. Beyond electricity, renewable energy finds compelling applications in transportation, industrial heating, and agriculture. The rise of biofuels—especially second-generation variants derived from agricultural waste—offers a pathway to decarbonize aviation and freight transport, sectors that have traditionally been resistant to electrification. In agrarian contexts, solar-powered pumps have reduced farmers’ dependence on erratic grid supply and diesel generators, enhancing irrigation autonomy while mitigating carbon emissions. Industries, often vilified for their carbon intensity, are also experimenting with renewable alternatives. Concentrated solar thermal technologies, for instance, are being employed in textile processing, food dehydration, and even metallurgy, demonstrating that clean energy need not be confined to low-intensity applications. Furthermore, geothermal energy is increasingly being harnessed for space heating in colder regions and for cooling through absorption chillers—thereby offsetting conventional HVAC loads. However, the significance of renewable energy transcends utility. At a deeper level, it challenges existing geopolitical hierarchies shaped by fossil fuel dependency. While oil-rich nations have historically wielded disproportionate influence, renewable resources—abundant yet diffuse—enable energy sovereignty for resource-scarce regions. This democratization of energy, if properly managed, can catalyze more equitable development paradigms. Nevertheless, integration challenges persist. Intermittency, storage limitations, land use conflicts, and upfront costs are not insignificant barriers. A hasty transition without resilient infrastructure or community consent could replicate the very injustices renewables seek to redress. Therefore, the question is not merely how to produce renewable energy, but how to embed it meaningfully across sectors, geographies, and social hierarchies.\nWhat primary argument does the author make about renewable energy?","w":"The author says the discussion fixates on production rather than application and stresses 'the multifaceted domains' where renewables can transform economies. Examples follow from electricity, transport, agriculture, industry, heating and cooling, and the passage ends by asking how to embed renewables 'across sectors, geographies, and social hierarchies'. Option 1 contradicts 'Beyond electricity...', option 2 ignores wind, hydro, biofuels and geothermal, and option 4 is never mentioned.","o":["It can only replace fossil fuels in electricity generation","It has limited potential beyond solar energy","Its transformative use lies across multiple sectors","It is primarily a Western innovation"],"a":[2]},{"id":"c25s1-93","p":"c25s1","n":93,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nThe accelerating depletion of fossil fuels, coupled with mounting ecological degradation, has propelled renewable energy from a peripheral concern to a central component of global energy discourse. Yet, the conversation often fixates on production rather than application. A nuanced understanding of renewable energy must include not only its sources—solar, wind, hydro, geothermal, and biomass—but also the multifaceted domains in which it can transform economies, decentralize power structures, and promote environmental justice. In the domain of electricity generation, renewables have already begun to displace conventional energy systems. Solar photovoltaic installations now power not only urban rooftops but remote rural hamlets long excluded from centralized grids. Micro-hydel projects have enabled mountain communities to harness perennial streams for electricity without the ecological upheaval of large dams. Similarly, wind energy has emerged as a significant contributor in coastal and arid zones, transforming local economies by creating decentralized, sustainable employment ecosystems. Beyond electricity, renewable energy finds compelling applications in transportation, industrial heating, and agriculture. The rise of biofuels—especially second-generation variants derived from agricultural waste—offers a pathway to decarbonize aviation and freight transport, sectors that have traditionally been resistant to electrification. In agrarian contexts, solar-powered pumps have reduced farmers’ dependence on erratic grid supply and diesel generators, enhancing irrigation autonomy while mitigating carbon emissions. Industries, often vilified for their carbon intensity, are also experimenting with renewable alternatives. Concentrated solar thermal technologies, for instance, are being employed in textile processing, food dehydration, and even metallurgy, demonstrating that clean energy need not be confined to low-intensity applications. Furthermore, geothermal energy is increasingly being harnessed for space heating in colder regions and for cooling through absorption chillers—thereby offsetting conventional HVAC loads. However, the significance of renewable energy transcends utility. At a deeper level, it challenges existing geopolitical hierarchies shaped by fossil fuel dependency. While oil-rich nations have historically wielded disproportionate influence, renewable resources—abundant yet diffuse—enable energy sovereignty for resource-scarce regions. This democratization of energy, if properly managed, can catalyze more equitable development paradigms. Nevertheless, integration challenges persist. Intermittency, storage limitations, land use conflicts, and upfront costs are not insignificant barriers. A hasty transition without resilient infrastructure or community consent could replicate the very injustices renewables seek to redress. Therefore, the question is not merely how to produce renewable energy, but how to embed it meaningfully across sectors, geographies, and social hierarchies.\nWhat distinguishes second-generation biofuels, as mentioned in the passage?","w":"The passage refers to 'second-generation variants derived from agricultural waste' that offer a pathway to decarbonise aviation and freight transport. Agricultural waste (crop residues such as stalks and husks) is non-edible, which is what separates second-generation biofuels from first-generation ones made from food crops. Animal fats and petroleum additives are not mentioned, and emitting more carbon than coal contradicts their decarbonising role.","o":["They are made from animal fats","They derive from non-edible agricultural waste","They require petroleum additives","They emit more carbon than coal"],"a":[1]},{"id":"c25s1-94","p":"c25s1","n":94,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nThe accelerating depletion of fossil fuels, coupled with mounting ecological degradation, has propelled renewable energy from a peripheral concern to a central component of global energy discourse. Yet, the conversation often fixates on production rather than application. A nuanced understanding of renewable energy must include not only its sources—solar, wind, hydro, geothermal, and biomass—but also the multifaceted domains in which it can transform economies, decentralize power structures, and promote environmental justice. In the domain of electricity generation, renewables have already begun to displace conventional energy systems. Solar photovoltaic installations now power not only urban rooftops but remote rural hamlets long excluded from centralized grids. Micro-hydel projects have enabled mountain communities to harness perennial streams for electricity without the ecological upheaval of large dams. Similarly, wind energy has emerged as a significant contributor in coastal and arid zones, transforming local economies by creating decentralized, sustainable employment ecosystems. Beyond electricity, renewable energy finds compelling applications in transportation, industrial heating, and agriculture. The rise of biofuels—especially second-generation variants derived from agricultural waste—offers a pathway to decarbonize aviation and freight transport, sectors that have traditionally been resistant to electrification. In agrarian contexts, solar-powered pumps have reduced farmers’ dependence on erratic grid supply and diesel generators, enhancing irrigation autonomy while mitigating carbon emissions. Industries, often vilified for their carbon intensity, are also experimenting with renewable alternatives. Concentrated solar thermal technologies, for instance, are being employed in textile processing, food dehydration, and even metallurgy, demonstrating that clean energy need not be confined to low-intensity applications. Furthermore, geothermal energy is increasingly being harnessed for space heating in colder regions and for cooling through absorption chillers—thereby offsetting conventional HVAC loads. However, the significance of renewable energy transcends utility. At a deeper level, it challenges existing geopolitical hierarchies shaped by fossil fuel dependency. While oil-rich nations have historically wielded disproportionate influence, renewable resources—abundant yet diffuse—enable energy sovereignty for resource-scarce regions. This democratization of energy, if properly managed, can catalyze more equitable development paradigms. Nevertheless, integration challenges persist. Intermittency, storage limitations, land use conflicts, and upfront costs are not insignificant barriers. A hasty transition without resilient infrastructure or community consent could replicate the very injustices renewables seek to redress. Therefore, the question is not merely how to produce renewable energy, but how to embed it meaningfully across sectors, geographies, and social hierarchies.\nWhy is geothermal energy cited in the passage?","w":"Geothermal energy appears in the list of practical applications beyond electricity: it 'is increasingly being harnessed for space heating in colder regions and for cooling through absorption chillers', offsetting conventional HVAC loads. Coming right after the industrial examples, it is cited to exemplify its heating and cooling utility; the passage names space heating and absorption chillers rather than factories, but option 3 is clearly the closest. It is described as growing, not rare or impractical; its political implications and cost are not discussed in connection with geothermal energy.","o":["To highlight a rare and impractical solution","To show its political implications","To exemplify its industrial cooling and heating utility","To criticize its high cost"],"a":[2]},{"id":"c25s1-95","p":"c25s1","n":95,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nThe accelerating depletion of fossil fuels, coupled with mounting ecological degradation, has propelled renewable energy from a peripheral concern to a central component of global energy discourse. Yet, the conversation often fixates on production rather than application. A nuanced understanding of renewable energy must include not only its sources—solar, wind, hydro, geothermal, and biomass—but also the multifaceted domains in which it can transform economies, decentralize power structures, and promote environmental justice. In the domain of electricity generation, renewables have already begun to displace conventional energy systems. Solar photovoltaic installations now power not only urban rooftops but remote rural hamlets long excluded from centralized grids. Micro-hydel projects have enabled mountain communities to harness perennial streams for electricity without the ecological upheaval of large dams. Similarly, wind energy has emerged as a significant contributor in coastal and arid zones, transforming local economies by creating decentralized, sustainable employment ecosystems. Beyond electricity, renewable energy finds compelling applications in transportation, industrial heating, and agriculture. The rise of biofuels—especially second-generation variants derived from agricultural waste—offers a pathway to decarbonize aviation and freight transport, sectors that have traditionally been resistant to electrification. In agrarian contexts, solar-powered pumps have reduced farmers’ dependence on erratic grid supply and diesel generators, enhancing irrigation autonomy while mitigating carbon emissions. Industries, often vilified for their carbon intensity, are also experimenting with renewable alternatives. Concentrated solar thermal technologies, for instance, are being employed in textile processing, food dehydration, and even metallurgy, demonstrating that clean energy need not be confined to low-intensity applications. Furthermore, geothermal energy is increasingly being harnessed for space heating in colder regions and for cooling through absorption chillers—thereby offsetting conventional HVAC loads. However, the significance of renewable energy transcends utility. At a deeper level, it challenges existing geopolitical hierarchies shaped by fossil fuel dependency. While oil-rich nations have historically wielded disproportionate influence, renewable resources—abundant yet diffuse—enable energy sovereignty for resource-scarce regions. This democratization of energy, if properly managed, can catalyze more equitable development paradigms. Nevertheless, integration challenges persist. Intermittency, storage limitations, land use conflicts, and upfront costs are not insignificant barriers. A hasty transition without resilient infrastructure or community consent could replicate the very injustices renewables seek to redress. Therefore, the question is not merely how to produce renewable energy, but how to embed it meaningfully across sectors, geographies, and social hierarchies.\nAccording to the author, how does renewable energy challenge global power structures?","w":"The author says renewable energy 'challenges existing geopolitical hierarchies shaped by fossil fuel dependency': while oil-rich nations have wielded disproportionate influence, renewable resources, abundant yet diffuse, 'enable energy sovereignty for resource-scarce regions'. Energy sovereignty means energy independence. Option 2 is the opposite of the decentralisation the passage describes, and options 1 and 4 are not stated.","o":["By reducing electricity usage","By centralizing production","By enabling energy independence in diverse regions","By increasing oil exports"],"a":[2]},{"id":"c25s1-96","p":"c25s1","n":96,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nThe accelerating depletion of fossil fuels, coupled with mounting ecological degradation, has propelled renewable energy from a peripheral concern to a central component of global energy discourse. Yet, the conversation often fixates on production rather than application. A nuanced understanding of renewable energy must include not only its sources—solar, wind, hydro, geothermal, and biomass—but also the multifaceted domains in which it can transform economies, decentralize power structures, and promote environmental justice. In the domain of electricity generation, renewables have already begun to displace conventional energy systems. Solar photovoltaic installations now power not only urban rooftops but remote rural hamlets long excluded from centralized grids. Micro-hydel projects have enabled mountain communities to harness perennial streams for electricity without the ecological upheaval of large dams. Similarly, wind energy has emerged as a significant contributor in coastal and arid zones, transforming local economies by creating decentralized, sustainable employment ecosystems. Beyond electricity, renewable energy finds compelling applications in transportation, industrial heating, and agriculture. The rise of biofuels—especially second-generation variants derived from agricultural waste—offers a pathway to decarbonize aviation and freight transport, sectors that have traditionally been resistant to electrification. In agrarian contexts, solar-powered pumps have reduced farmers’ dependence on erratic grid supply and diesel generators, enhancing irrigation autonomy while mitigating carbon emissions. Industries, often vilified for their carbon intensity, are also experimenting with renewable alternatives. Concentrated solar thermal technologies, for instance, are being employed in textile processing, food dehydration, and even metallurgy, demonstrating that clean energy need not be confined to low-intensity applications. Furthermore, geothermal energy is increasingly being harnessed for space heating in colder regions and for cooling through absorption chillers—thereby offsetting conventional HVAC loads. However, the significance of renewable energy transcends utility. At a deeper level, it challenges existing geopolitical hierarchies shaped by fossil fuel dependency. While oil-rich nations have historically wielded disproportionate influence, renewable resources—abundant yet diffuse—enable energy sovereignty for resource-scarce regions. This democratization of energy, if properly managed, can catalyze more equitable development paradigms. Nevertheless, integration challenges persist. Intermittency, storage limitations, land use conflicts, and upfront costs are not insignificant barriers. A hasty transition without resilient infrastructure or community consent could replicate the very injustices renewables seek to redress. Therefore, the question is not merely how to produce renewable energy, but how to embed it meaningfully across sectors, geographies, and social hierarchies.\nWhat is the author’s caution about the rapid adoption of renewable energy?","w":"The author warns that 'a hasty transition without resilient infrastructure or community consent could replicate the very injustices renewables seek to redress', so rapid adoption may repeat existing patterns of injustice. Upfront costs are listed only as one barrier, not as proof that renewables are economically unsustainable. Fossil fuel depletion is a cause of the shift, not a result, and the passage says wind energy creates employment.","o":["It is economically unsustainable","It may repeat existing patterns of injustice","It leads to fossil fuel scarcity","It diminishes employment"],"a":[1]},{"id":"c25s1-97","p":"c25s1","n":97,"s":"eng","t":"Voice & Narration","q":"Select the correct option for the Direct Speech conversion of the sentence below.\nHe confessed that the violin concerto would have remained fragmentary had the late maestro not bequeathed his annotated sketches.","w":"The reported clause is a third conditional with inversion ('would have remained ... had the maestro not bequeathed'). Such unreal past conditionals cannot be shifted further back, so the words stay the same in direct speech. Option 2 is ungrammatical because 'if' needs 'had not bequeathed', option 3 uses an impossible tense ('will be remaining ... had'), and option 4 changes the meaning and drops 'the late maestro'.","o":["He said, \"The violin concerto would have remained fragmentary had the late maestro not bequeathed his annotated sketches.\"","He said, \"The violin concerto would have remained fragmentary if the late maestro not bequeathed his annotated sketches.\"","He said, \"The violin concerto will be remaining fragmentary had the late maestro not bequeathed his annotated sketches.\"","He said, \"The violin concerto would be fragmentary if sketches had not been bequeathed.\""],"a":[0]},{"id":"c25s1-98","p":"c25s1","n":98,"s":"eng","t":"Voice & Narration","q":"A sentence is provided in direct speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding indirect speech.\nShe said, “I didn’t see him at the station.”","w":"With a past reporting verb ('said'), the simple past 'didn't see' shifts back to the past perfect 'had not seen', and 'I' becomes 'she'. Hence: 'She said that she had not seen him at the station.' Option 1 uses the present perfect, option 3 wrongly combines 'didn't' with the past form 'saw' (did is followed by the base form) and keeps the tense, and option 4 changes it to past continuous.","o":["She said that she hasn’t seen him at the station.","She said that she had not seen him at the station.","She said she didn’t saw him at the station.","She said that she was not seeing him at the station."],"a":[1]},{"id":"c25s1-99","p":"c25s1","n":99,"s":"eng","t":"Sentence Arrangement","q":"Rearrange the following sentences to form a coherent paragraph:\n1. This phenomenon is often referred to as a \"network effect,\" where the value of a service increases with the number of its users.\n2. Consequently, they tend to dominate their respective markets, leading to the creation of powerful monopolies or oligopolies.\n3. The digital economy has given rise to new business models that rely on the accumulation of data and the scale of their user base.\n4. A prime example is the platform economy, where companies like social media networks and ride-sharing apps create value by connecting users.","w":"Sentence 3 introduces the topic: the digital economy's new business models built on data and user base. Sentence 4 gives 'a prime example', the platform economy, where companies create value by connecting users. Sentence 1 names this phenomenon of value rising with users, the 'network effect'. Sentence 2 begins with 'Consequently' and gives the result, market dominance and monopolies. Order: 3, 4, 1, 2.","o":["2, 3, 4, 1","4, 1, 2, 3","3, 4, 1, 2","1, 3, 2, 4"],"a":[2]},{"id":"c25s1-100","p":"c25s1","n":100,"s":"eng","t":"Sentence Arrangement","q":"Rearrange the following sentences in correct order to make a logical passage.\n1. This helps prevent nutrient depletion and soil erosion.\n2. Crop rotation is a sustainable agricultural practice.\n3. It involves planting different crops sequentially on the same land.\n4. It also reduces the need for synthetic fertilizers.","w":"Sentence 2 introduces the subject, crop rotation, so it must come first. Sentence 3 explains what it involves, with 'It' referring to crop rotation. Sentence 1 begins 'This helps', giving the first benefit of the practice just described. Sentence 4 adds a further benefit with 'also', so it must follow sentence 1. The logical order is 2-3-1-4.","o":["2-3-1-4","1-2-3-4","2-4-1-3","3-4-2-1"],"a":[0]},{"id":"c25s2-1","p":"c25s2","n":1,"s":"rea","t":"Series","q":"Select the letter-cluster from among the given options that can replace the question mark (?) in the following series.\nQAZ, RBY, SCX, TDW, ?","w":"Track each position separately. First letters: Q, R, S, T move one step forward, so the next is U. Second letters: A, B, C, D move one step forward, so the next is E. Third letters: Z, Y, X, W move one step backward, so the next is V. The missing cluster is UEV. UBS has the right first letter but breaks the second and third patterns; JKS and VSA fit none of them.","o":["UBS","UEV","JKS","VSA"],"a":[1],"qt":"दिए गए विकल्पों में से उस अक्षर-समूह का चयन करें जो निम्नलिखित श्रृंखला में प्रश्न चिह्न (?) को प्रतिस्थापित कर सके।\nQAZ, RBY, SCX, TDW, ?","ot":["UBS","UEV","JKS","VSA"],"wt":"प्रत्येक स्थान को अलग-अलग देखें। पहले अक्षर: Q, R, S, T एक-एक स्थान आगे बढ़ते हैं, अतः अगला U है। दूसरे अक्षर: A, B, C, D एक-एक स्थान आगे बढ़ते हैं, अतः अगला E है। तीसरे अक्षर: Z, Y, X, W एक-एक स्थान पीछे जाते हैं, अतः अगला V है। लुप्त अक्षर-समूह UEV है। UBS का पहला अक्षर सही है, परंतु दूसरा और तीसरा पैटर्न टूटता है; JKS और VSA किसी भी पैटर्न में नहीं बैठते।"},{"id":"c25s2-2","p":"c25s2","n":2,"s":"rea","t":"Miscellaneous Reasoning","q":"Choose the address that is the same as the one given below.\nFlat No. 12B, Sunrise Towers,Park Street, Kolkata,West Bengal - 700016","w":"Compare the options part by part with the given address. Flat No. 12B, Sunrise Towers, Park Street, Kolkata and the PIN code 700016 are the same in all four options, so the state decides the answer. The given address says West Bengal; options 1, 2 and 3 change it to Bihar, Jharkhand and Odisha. Only option 4 keeps every element, including West Bengal, so it is the same address.","o":["Flat No. 12B, Sunrise Towers, Park Street, Kolkata, Bihar - 700016","Flat No. 12B, Sunrise Towers, Park Street, Kolkata, Jharkhand - 700016","Flat No. 12B, Sunrise Towers, Park Street, Kolkata, Odisha - 700016","Flat No. 12B, Sunrise Towers, Park Street, Kolkata, West Bengal - 700016"],"a":[3],"qt":"वह पता चुनें जो नीचे दिए गए पते के समान हो।\nFlat No. 12B, Sunrise Towers,Park Street, Kolkata,West Bengal - 700016","ot":["Flat No. 12B, Sunrise Towers, Park Street, Kolkata, Bihar - 700016","Flat No. 12B, Sunrise Towers, Park Street, Kolkata, Jharkhand - 700016","Flat No. 12B, Sunrise Towers, Park Street, Kolkata, Odisha - 700016","Flat No. 12B, Sunrise Towers, Park Street, Kolkata, West Bengal - 700016"],"wt":"विकल्पों की तुलना दिए गए पते से भाग-दर-भाग करें। Flat No. 12B, Sunrise Towers, Park Street, Kolkata और पिन कोड 700016 चारों विकल्पों में समान हैं, इसलिए राज्य से उत्तर तय होता है। दिए गए पते में West Bengal है; विकल्प 1, 2 और 3 में इसे बदलकर Bihar, Jharkhand और Odisha कर दिया गया है। केवल विकल्प 4 में West Bengal सहित हर तत्व समान है, अतः वही समान पता है।"},{"id":"c25s2-3","p":"c25s2","n":3,"s":"rea","t":"Miscellaneous Reasoning","q":"Choose the address that is the same as the one given below.\nSample Address:#301, Galaxy Towers,Hinoo, Ranchi,Jharkhand - 834002","w":"Check every element of the given address: #301, Galaxy Towers, Hinoo, Ranchi, Jharkhand, 834002. Option 2 changes \"Towers\" to \"Tower\", option 3 drops the \"#\" before 301, and option 4 spells the locality \"Hinu\" instead of \"Hinoo\". Only option 1 matches the sample address in every element, so it is the same address. Such questions test careful letter-by-letter comparison.","o":["#301, Galaxy Towers, Hinoo, Ranchi, Jharkhand - 834002","#301, Galaxy Tower, Hinoo, Ranchi, Jharkhand - 834002","301, Galaxy Towers, Hinoo, Ranchi, Jharkhand - 834002","#301, Galaxy Towers, Hinu, Ranchi, Jharkhand - 834002"],"a":[0],"qt":"वह पता चुनें जो नीचे दिए गए पते के समान हो।\nSample Address:#301, Galaxy Towers,Hinoo, Ranchi,Jharkhand - 834002","ot":["#301, Galaxy Towers, Hinoo, Ranchi, Jharkhand - 834002","#301, Galaxy Tower, Hinoo, Ranchi, Jharkhand - 834002","301, Galaxy Towers, Hinoo, Ranchi, Jharkhand - 834002","#301, Galaxy Towers, Hinu, Ranchi, Jharkhand - 834002"],"wt":"दिए गए पते के हर तत्व की जाँच करें: #301, Galaxy Towers, Hinoo, Ranchi, Jharkhand, 834002। विकल्प 2 में \"Towers\" के स्थान पर \"Tower\" है, विकल्प 3 में 301 से पहले \"#\" नहीं है, और विकल्प 4 में मोहल्ले का नाम \"Hinoo\" के स्थान पर \"Hinu\" लिखा है। केवल विकल्प 1 हर तत्व में नमूना पते से मेल खाता है, अतः वही समान पता है। ऐसे प्रश्न अक्षर-दर-अक्षर सावधानीपूर्वक तुलना की परीक्षा लेते हैं।"},{"id":"c25s2-4","p":"c25s2","n":4,"s":"rea","t":"Syllogism & Statements","q":"Consider the following statement and choose the option that follows.\nStatement: The railway authority decided to reduce ticket prices on long-distance trains.\nAssumptions:\nI. Lower prices will attract more passengers.\nII. The authority wants to compete with airlines.","w":"An assumption is what the decision-maker must take for granted. A fare cut makes sense only if the authority expects cheaper tickets to draw more passengers, so I is implicit. The statement says nothing about airlines; the cut could aim at buses, road travel or simply higher occupancy, so competing with airlines is only one possible motive and II is not implicit. Hence only I is implicit.","o":["Only I is implicit","Only II is implicit","Both are implicit","Neither is implicit"],"a":[0],"qt":"निम्नलिखित कथन पर विचार कीजिए और उसके बाद दिए गए विकल्प का चयन कीजिए।\nकथन: रेलवे प्राधिकरण ने लंबी दूरी की ट्रेनों में टिकट की कीमतें कम करने का निर्णय लिया है।\nधारणाएँ:\nI. कम कीमतें अधिक यात्रियों को आकर्षित करेंगी।\nII. प्राधिकरण एयरलाइनों के साथ प्रतिस्पर्धा करना चाहता है।","ot":["केवल I निहित है","केवल II निहित है","दोनों निहित हैं","कोई भी निहित नहीं है"],"wt":"धारणा वह है जिसे निर्णय लेने वाला पहले से मानकर चलता है। किराया घटाने का निर्णय तभी अर्थपूर्ण है जब प्राधिकरण यह मानता हो कि सस्ते टिकट अधिक यात्रियों को आकर्षित करेंगे, अतः I निहित है। कथन में एयरलाइनों का कोई उल्लेख नहीं है; किराया घटाने का उद्देश्य बसों या सड़क यात्रा से प्रतिस्पर्धा, या केवल अधिक सीटें भरना भी हो सकता है, इसलिए एयरलाइनों से प्रतिस्पर्धा केवल एक संभावित कारण है और II निहित नहीं है। अतः केवल I निहित है।"},{"id":"c25s2-5","p":"c25s2","n":5,"s":"rea","t":"Syllogism & Statements","q":"Consider the following statement and choose the option that follows.\nStatements:\nI. Banks have increased staff training on cyber security.\nII. There has been a surge in cyber attacks.","w":"A surge in cyber attacks is an event that pushes organisations to respond, and increasing staff training on cyber security is a natural response to it. So statement II (the surge in attacks) is the cause and statement I (more training) is the effect. The reverse is illogical, because training staff cannot cause a surge in cyber attacks; and the two are clearly linked, so options 3 and 4 are wrong.","o":["I is the cause and II is the effect.","II is the cause and I is the effect.","Both are unrelated.","No relation."],"a":[1],"qt":"निम्नलिखित कथन पर विचार कीजिए और उसके बाद दिए गए विकल्प का चयन कीजिए।\nकथन:\nI. बैंकों ने साइबर सुरक्षा पर कर्मचारियों के प्रशिक्षण में वृद्धि की है।\nII. साइबर हमलों में वृद्धि हुई है।","ot":["I कारण है और II प्रभाव है।","II कारण है और I प्रभाव है।","दोनों असंबंधित हैं।","इनमें कोई संबंध नहीं है।"],"wt":"साइबर हमलों में वृद्धि एक ऐसी घटना है जो संस्थाओं को प्रतिक्रिया करने के लिए प्रेरित करती है, और साइबर सुरक्षा पर कर्मचारियों का प्रशिक्षण बढ़ाना इसकी स्वाभाविक प्रतिक्रिया है। अतः कथन II (हमलों में वृद्धि) कारण है और कथन I (अधिक प्रशिक्षण) प्रभाव है। उल्टा संबंध तर्कसंगत नहीं है, क्योंकि कर्मचारियों का प्रशिक्षण साइबर हमलों में वृद्धि का कारण नहीं बन सकता; और दोनों कथन स्पष्ट रूप से जुड़े हैं, इसलिए विकल्प 3 और 4 गलत हैं।"},{"id":"c25s2-6","p":"c25s2","n":6,"s":"rea","t":"Series","q":"Find the WRONG term in the given series.\n5, 10, 15, 26, 37, 50","w":"The terms follow n² + 1: 2² + 1 = 5, 3² + 1 = 10, 4² + 1 = 17, 5² + 1 = 26, 6² + 1 = 37, 7² + 1 = 50. The third term should be 17, so 15 is wrong. Check with differences: the correct series 5, 10, 17, 26, 37, 50 has differences 5, 7, 9, 11, 13 (consecutive odd numbers), which 15 breaks.","o":["50","26","15","5"],"a":[2],"qt":"दी गई श्रृंखला में गलत पद ज्ञात कीजिए। 5, 10, 15, 26, 37, 50","ot":["50","26","15","5"],"wt":"पद n² + 1 के नियम पर चलते हैं: 2² + 1 = 5, 3² + 1 = 10, 4² + 1 = 17, 5² + 1 = 26, 6² + 1 = 37, 7² + 1 = 50। तीसरा पद 17 होना चाहिए, अतः 15 गलत है। अंतर से जाँच: सही श्रृंखला 5, 10, 17, 26, 37, 50 के अंतर 5, 7, 9, 11, 13 (क्रमागत विषम संख्याएँ) हैं, जिन्हें 15 तोड़ता है।"},{"id":"c25s2-7","p":"c25s2","n":7,"s":"rea","t":"Mathematical Operations","q":"Replace special characters with mathematical signs as given in options to make it meaningful equation.\n16 # 4 @ 2 = 62","w":"Put each pair in place of # and @ and apply BODMAS. Option 1: 16 ÷ 4 − 2 = 2. Option 2: 16 − 4 ÷ 2 = 14. Option 3: 16 × 4 − 2 = 64 − 2 = 62, which matches. Option 4: 16 − 4 × 2 = 8. So # = × and @ = −, giving 16 × 4 − 2 = 62.","o":["÷, −","−, ÷","×, −","−, ×"],"a":[2],"qt":"इसे अर्थपूर्ण समीकरण बनाने के लिए विकल्पों में दिए गए गणितीय चिह्नों से विशेष वर्णों को प्रतिस्थापित करें।\n16 # 4 @ 2 = 62","ot":["÷, −","−, ÷","×, −","−, ×"],"wt":"प्रत्येक विकल्प के चिह्नों को # और @ के स्थान पर रखें और BODMAS लगाएँ। विकल्प 1: 16 ÷ 4 − 2 = 2। विकल्प 2: 16 − 4 ÷ 2 = 14। विकल्प 3: 16 × 4 − 2 = 64 − 2 = 62, जो मेल खाता है। विकल्प 4: 16 − 4 × 2 = 8। अतः # = × और @ = −, जिससे 16 × 4 − 2 = 62 प्राप्त होता है।"},{"id":"c25s2-8","p":"c25s2","n":8,"s":"rea","t":"Mathematical Operations","q":"Which two signs should be swapped to correct the following?\n28 ÷ 4 × 3 − 5 + 7 = 19","w":"As given, 28 ÷ 4 × 3 − 5 + 7 = 21 − 5 + 7 = 23, not 19. Swap + and −: 28 ÷ 4 × 3 + 5 − 7 = 21 + 5 − 7 = 19, which is correct. Other swaps fail, for example × and − gives 28 ÷ 4 − 3 × 5 + 7 = 7 − 15 + 7 = −1, and ÷ and × gives 28 × 4 ÷ 3, which is not even a whole number.","o":["÷ and ×","× and −","÷ and +","+ and −"],"a":[3],"qt":"निम्नलिखित को सही करने के लिए किन दो चिह्नों को आपस में बदलना चाहिए?\n28 ÷ 4 × 3 − 5 + 7 = 19","ot":["÷ और ×","× और −","÷ और +","+ और −"],"wt":"दिए गए रूप में 28 ÷ 4 × 3 − 5 + 7 = 21 − 5 + 7 = 23, न कि 19। + और − को आपस में बदलने पर: 28 ÷ 4 × 3 + 5 − 7 = 21 + 5 − 7 = 19, जो सही है। अन्य अदला-बदली विफल होती हैं, उदाहरण के लिए × और − बदलने पर 28 ÷ 4 − 3 × 5 + 7 = 7 − 15 + 7 = −1 आता है, और ÷ और × बदलने पर 28 × 4 ÷ 3 आता है, जो पूर्ण संख्या भी नहीं है।"},{"id":"c25s2-9","p":"c25s2","n":9,"s":"rea","t":"Mathematical Operations","q":"By interchanging the given two signs which of the following equation will be NOT correct?\n+ and −\nI. 18 ÷ 3 + 8 × 5 − 4 = 20\nII. 6 + 8 × 9 ÷ 3 − 4 = 14","w":"Interchange + and − and solve using BODMAS. I becomes 18 ÷ 3 − 8 × 5 + 4 = 6 − 40 + 4 = −30, not 20. II becomes 6 − 8 × 9 ÷ 3 + 4 = 6 − 24 + 4 = −14, not 14 (a sign slip here is tempting). Neither equation becomes correct after the interchange, so both I and II are NOT correct.","o":["Neither I nor II","Both I and II","Only II","Only I"],"a":[1],"qt":"दिए गए दो चिह्नों को आपस में बदलने पर निम्नलिखित में से कौन सा समीकरण सही नहीं होगा?\n+ और −\nI. 18 ÷ 3 + 8 × 5 − 4 = 20\nII. 6 + 8 × 9 ÷ 3 − 4 = 14","ot":["न तो I और न ही II","I और II दोनों","केवल II","केवल I"],"wt":"+ और − को आपस में बदलें और BODMAS से हल करें। I बनता है 18 ÷ 3 − 8 × 5 + 4 = 6 − 40 + 4 = −30, न कि 20। II बनता है 6 − 8 × 9 ÷ 3 + 4 = 6 − 24 + 4 = −14, न कि 14 (यहाँ चिह्न की भूल से 14 मान लेने की संभावना रहती है)। चिह्न बदलने के बाद कोई भी समीकरण सही नहीं होता, अतः I और II दोनों सही नहीं हैं।"},{"id":"c25s2-10","p":"c25s2","n":10,"s":"rea","t":"Blood Relations & Directions","q":"In a family, there are 6 members P, Q, R, S, T and U.\n• P and Q are a married couple\n• R is the son of P\n• T is the sister of R\n• Q is the mother of S\nU is the brother of P\nWho is the father of S?","w":"Q is the mother of S, so Q is female. P and Q are a married couple, so P is Q's husband and therefore the father of S (R, T and S are the children of P and Q). U is P's brother, which makes him S's uncle, not father. Q is the mother, and R is S's brother, so neither can be the father.","o":["P","Q","U","R"],"a":[0],"qt":"एक परिवार में 6 सदस्य P, Q, R, S, T और U है\n• P और Q विवाहित जोड़े हैं\n• R, P का पुत्र है\n• T, R की बहन है\n• Q, S की माँ है\nU, P का भाई है\nS का पिता कौन है?","ot":["P","Q","U","R"],"wt":"Q, S की माँ है, अतः Q महिला है। P और Q विवाहित जोड़े हैं, इसलिए P, Q का पति है और इस प्रकार S का पिता है (R, T और S, P और Q की संतानें हैं)। U, P का भाई है, इसलिए वह S का चाचा है, पिता नहीं। Q माँ है और R, S का भाई है, इसलिए इनमें से कोई भी पिता नहीं हो सकता।"},{"id":"c25s2-11","p":"c25s2","n":11,"s":"rea","t":"Series","q":"What comes at the place of question mark: 2, 6, 12, 20, 30, ?","w":"Each term is n × (n + 1): 1 × 2 = 2, 2 × 3 = 6, 3 × 4 = 12, 4 × 5 = 20, 5 × 6 = 30, so the next term is 6 × 7 = 42. Differences confirm it: 4, 6, 8, 10, so the next difference is 12 and 30 + 12 = 42. 56 (7 × 8) skips a step.","o":["42","56","38","48"],"a":[0],"qt":"प्रश्न चिन्ह के स्थान पर क्या आएगा: 2, 6, 12, 20, 30, ?","ot":["42","56","38","48"],"wt":"प्रत्येक पद n × (n + 1) है: 1 × 2 = 2, 2 × 3 = 6, 3 × 4 = 12, 4 × 5 = 20, 5 × 6 = 30, अतः अगला पद 6 × 7 = 42 है। अंतर से पुष्टि: 4, 6, 8, 10, अतः अगला अंतर 12 है और 30 + 12 = 42। 56 (7 × 8) एक चरण छोड़ देता है।"},{"id":"c25s2-12","p":"c25s2","n":12,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement: The library will remain closed on Sunday due to renovation.\nI. The renovation is planned for Sunday.\nII. People cannot use the library this Sunday.","w":"The library is closed on Sunday because of renovation, which means renovation work is scheduled for that Sunday, so conclusion I follows. A closed library cannot be used, so people cannot use it this Sunday and conclusion II also follows. Both are direct consequences of the statement, so both I and II follow.","o":["Only Conclusion I follows","Only Conclusion II follows","Both I and II follow","Neither I nor II follows"],"a":[2],"qt":"निम्नलिखित कथन को ध्यानपूर्वक पढ़ें और निष्कर्ष निकालें।\nकथन: नवीनीकरण के कारण रविवार को पुस्तकालय बंद रहेगा।\nI. नवीनीकरण रविवार के लिए नियोजित है।\nII. लोग इस रविवार को पुस्तकालय का उपयोग नहीं कर सकते।","ot":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"wt":"पुस्तकालय रविवार को नवीनीकरण के कारण बंद रहेगा, जिसका अर्थ है कि नवीनीकरण का कार्य उस रविवार के लिए निर्धारित है, अतः निष्कर्ष I अनुसरण करता है। बंद पुस्तकालय का उपयोग नहीं किया जा सकता, इसलिए लोग इस रविवार को इसका उपयोग नहीं कर सकते और निष्कर्ष II भी अनुसरण करता है। दोनों कथन के प्रत्यक्ष परिणाम हैं, अतः I और II दोनों अनुसरण करते हैं।"},{"id":"c25s2-13","p":"c25s2","n":13,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement: The price of petrol has increased due to international oil prices.\nConclusions:\nI. Petrol prices are linked to global markets.\nII. The government has no control over fuel prices.","w":"Since petrol became costlier because of international oil prices, domestic petrol prices clearly depend on global markets, so conclusion I follows. The statement does not say the government is powerless; governments can still influence fuel prices through taxes, duties or subsidies. Conclusion II is an extreme claim not supported by the statement. Hence only conclusion I follows.","o":["Only Conclusion I follows","Only Conclusion II follows","Both I and II follow","Neither I nor II follows"],"a":[0],"qt":"निम्नलिखित कथन को ध्यानपूर्वक पढ़ें और निष्कर्ष निकालें।\nकथन: अंतर्राष्ट्रीय तेल कीमतों के कारण पेट्रोल की कीमत में वृद्धि हुई है।\nनिष्कर्ष:\nI. पेट्रोल की कीमतें वैश्विक बाजारों से जुड़ी हैं।\nII. सरकार का ईंधन की कीमतों पर कोई नियंत्रण नहीं है।","ot":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"wt":"चूँकि अंतर्राष्ट्रीय तेल कीमतों के कारण पेट्रोल महँगा हुआ है, इसलिए स्पष्ट है कि देश में पेट्रोल की कीमतें वैश्विक बाजारों पर निर्भर हैं, अतः निष्कर्ष I अनुसरण करता है। कथन यह नहीं कहता कि सरकार असहाय है; सरकार करों, शुल्कों या सब्सिडी के माध्यम से ईंधन की कीमतों को प्रभावित कर सकती है। निष्कर्ष II एक अतिवादी दावा है जिसका कथन समर्थन नहीं करता। अतः केवल निष्कर्ष I अनुसरण करता है।"},{"id":"c25s2-14","p":"c25s2","n":14,"s":"rea","t":"Analogy & Classification","q":"Find the option that best completes the analogy. DP : XZ :: EN : ?","w":"Use letter positions (A = 1 … Z = 26). In DP : XZ, D (4) + 20 = X (24) and P (16) + 10 = Z (26). Apply the same steps to EN: E (5) + 20 = Y (25) and N (14) + 10 = X (24). So EN : YX. YZ and YB begin with the right letter Y but do not apply +10 to N, and ZB fits neither step.","o":["YZ","YB","ZB","YX"],"a":[3],"qt":"वह विकल्प चुनिए जो सादृश्य को सर्वोत्तम रूप से पूरा करता है। DP : XZ :: EN : ?","ot":["YZ","YB","ZB","YX"],"wt":"अक्षरों के स्थानीय मान लें (A = 1 … Z = 26)। DP : XZ में D (4) + 20 = X (24) और P (16) + 10 = Z (26)। यही चरण EN पर लगाएँ: E (5) + 20 = Y (25) और N (14) + 10 = X (24)। अतः EN : YX। YZ और YB सही अक्षर Y से शुरू होते हैं, परंतु N पर +10 नहीं लगाते, और ZB किसी भी चरण में नहीं बैठता।"},{"id":"c25s2-15","p":"c25s2","n":15,"s":"rea","t":"Coding-Decoding","q":"If \"CANADA\" is written as \"ADANAC\", what is \"MEXICO\" written as?","w":"ADANAC is CANADA written in reverse order (C-A-N-A-D-A read from the end gives A-D-A-N-A-C). Reversing MEXICO in the same way: M-E-X-I-C-O becomes O-C-I-X-E-M, that is OCIXEM. OCIXME looks close but swaps the last two letters, so it is not the exact reverse; OCXEIM and OCMXIE are jumbled.","o":["OCIXME","OCIXEM","OCXEIM","OCMXIE"],"a":[1],"qt":"यदि \"CANADA\" को \"ADANAC\" लिखा जाता है, तो \"MEXICO\" को किस प्रकार लिखा जाएगा?","ot":["OCIXME","OCIXEM","OCXEIM","OCMXIE"],"wt":"ADANAC, CANADA को उल्टे क्रम में लिखने से बना है (C-A-N-A-D-A को अंत से पढ़ने पर A-D-A-N-A-C मिलता है)। इसी प्रकार MEXICO को उलटने पर M-E-X-I-C-O से O-C-I-X-E-M अर्थात OCIXEM बनता है। OCIXME मिलता-जुलता लगता है, परंतु इसमें अंतिम दो अक्षर आपस में बदल गए हैं, इसलिए यह ठीक उल्टा नहीं है; OCXEIM और OCMXIE अक्षरों का मनमाना क्रम हैं।"},{"id":"c25s2-16","p":"c25s2","n":16,"s":"rea","t":"Series","q":"What comes next?\nZYX, YXW, XWV, WVU, ?","w":"Each cluster is three consecutive letters in reverse alphabetical order, and each new cluster starts one letter earlier than the previous one: Z, Y, X, W, so the next starts with V. Three consecutive letters backward from V are V, U, T, giving VUT. UVT and TUV have the right letters in the wrong order, and VTS skips U.","o":["VUT","UVT","VTS","TUV"],"a":[0],"qt":"निम्नलिखित श्रृंखला में अगले स्थान पर कौन सा विकल्प आएगा?\nZYX, YXW, XWV, WVU, ?","ot":["VUT","UVT","VTS","TUV"],"wt":"प्रत्येक समूह उल्टे वर्णानुक्रम में तीन क्रमागत अक्षरों का है, और प्रत्येक नया समूह पिछले समूह से एक अक्षर पहले से शुरू होता है: Z, Y, X, W, अतः अगला समूह V से शुरू होगा। V से पीछे की ओर तीन क्रमागत अक्षर V, U, T हैं, जिससे VUT बनता है। UVT और TUV में अक्षर सही हैं पर क्रम गलत है, और VTS में U छूट गया है।"},{"id":"c25s2-17","p":"c25s2","n":17,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out from the given alternatives:","w":"Reduce, Reuse and Recycle are the well-known \"3 Rs\" of waste management, which aim to cut waste and conserve resources. Refuel means filling a vehicle or machine with fuel again; it is not a waste-management practice, so it is the odd one out. All four begin with \"Re\", so the prefix alone does not decide the answer.","o":["Reuse","Reduce","Recycle","Refuel"],"a":[3],"qt":"दिए गए विकल्पों में से विषम विकल्प को चुनिए:","ot":["पुन: उपयोग","कम करना","पुनर्चक्रण करें","पुनः ईंधन भरना"],"wt":"कम करना (Reduce), पुनः उपयोग (Reuse) और पुनर्चक्रण (Recycle) अपशिष्ट प्रबंधन के प्रसिद्ध \"3 R\" हैं, जिनका उद्देश्य कचरा घटाना और संसाधनों का संरक्षण करना है। पुनः ईंधन भरना (Refuel) का अर्थ है किसी वाहन या मशीन में फिर से ईंधन भरना; यह अपशिष्ट प्रबंधन की कोई पद्धति नहीं है, इसलिए यही विषम है। अंग्रेज़ी में चारों शब्द \"Re\" से शुरू होते हैं, इसलिए केवल उपसर्ग से उत्तर तय नहीं होता।"},{"id":"c25s2-18","p":"c25s2","n":18,"s":"rea","t":"Coding-Decoding","q":"Instruction: In a certain code language, Greek letters are used to represent English letters consistently. Using the provided code, decode the target sequence.\nIf γ α λ α ξ ι α is coded as GALAXIA, σ τ α ρ is coded as STAR,\nQuestion: Then what does σ γ α λ α represent?","w":"Match the codes letter by letter. From γ α λ α ξ ι α = GALAXIA: γ = G, α = A, λ = L, ξ = X, ι = I. From σ τ α ρ = STAR: σ = S, τ = T, ρ = R. Now decode σ γ α λ α: σ = S, γ = G, α = A, λ = L, α = A, giving SGALA. The other options put P, R or M in place of G.","o":["SGALA","SPALA","SRALA","SMALA"],"a":[0],"qt":"निर्देश: एक विशिष्ट कूट भाषा में, अंग्रेजी अक्षरों को दर्शाने के लिए ग्रीक अक्षरों का प्रयोग लगातार किया जाता है। दिए गए कोड का उपयोग करके, लक्ष्य अनुक्रम को डिकोड करें।\nयदि γ α λ α ξ ι α को GALAXIA, σ τ α ρ को STAR लिखा जाता है, तो\nप्रश्न: तो σ γ α λ α क्या दर्शाता है?","ot":["SGALA","SPALA","SRALA","SMALA"],"wt":"कूटों को अक्षर-दर-अक्षर मिलाएँ। γ α λ α ξ ι α = GALAXIA से: γ = G, α = A, λ = L, ξ = X, ι = I। σ τ α ρ = STAR से: σ = S, τ = T, ρ = R। अब σ γ α λ α को डिकोड करें: σ = S, γ = G, α = A, λ = L, α = A, जिससे SGALA प्राप्त होता है। अन्य विकल्पों में G के स्थान पर P, R या M रखा गया है।"},{"id":"c25s2-19","p":"c25s2","n":19,"s":"rea","t":"Miscellaneous Reasoning","q":"In a 30 L mixture, milk: water = 3:2. How much water must be added to make the ratio 1:1?","w":"Milk = 3/5 × 30 = 18 L and water = 2/5 × 30 = 12 L. Adding water does not change the milk, so for a 1:1 ratio water must also become 18 L. Water to be added = 18 − 12 = 6 L. Check: 18 : 18 = 1 : 1. Adding 10 L would give 18 : 22, which is not equal.","o":["6 L","10 L","9 L","12 L"],"a":[0],"qt":"30 लीटर के मिश्रण में, दूध: पानी = 3:2. अनुपात 1:1 करने के लिए कितना पानी मिलाना होगा?","ot":["6 लीटर","10 लीटर","9 लीटर","12 लीटर"],"wt":"दूध = 3/5 × 30 = 18 लीटर और पानी = 2/5 × 30 = 12 लीटर। पानी मिलाने से दूध की मात्रा नहीं बदलती, इसलिए 1:1 अनुपात के लिए पानी भी 18 लीटर होना चाहिए। मिलाया जाने वाला पानी = 18 − 12 = 6 लीटर। जाँच: 18 : 18 = 1 : 1। 10 लीटर मिलाने पर अनुपात 18 : 22 होगा, जो बराबर नहीं है।"},{"id":"c25s2-20","p":"c25s2","n":20,"s":"rea","t":"Miscellaneous Reasoning","q":"Find the LCM of 12, 18, 30?","w":"Write prime factors: 12 = 2² × 3, 18 = 2 × 3², 30 = 2 × 3 × 5. The LCM takes the highest power of each prime: 2² × 3² × 5 = 4 × 9 × 5 = 180. The other options fail: 90 is not divisible by 12, and 60 and 120 are not divisible by 18.","o":["90","180","60","120"],"a":[1],"qt":"12, 18, 30 का लघुत्तम समापवर्त्य ज्ञात कीजिए?","ot":["90","180","60","120"],"wt":"अभाज्य गुणनखंड लिखें: 12 = 2² × 3, 18 = 2 × 3², 30 = 2 × 3 × 5। लघुत्तम समापवर्त्य (LCM) में प्रत्येक अभाज्य संख्या की सबसे बड़ी घात ली जाती है: 2² × 3² × 5 = 4 × 9 × 5 = 180। अन्य विकल्प सही नहीं हैं: 90, 12 से विभाज्य नहीं है, तथा 60 और 120, 18 से विभाज्य नहीं हैं।"},{"id":"c25s2-21","p":"c25s2","n":21,"s":"rea","t":"Mathematical Operations","q":"If 10 @ 2 = 120 and 5 @ 5 = 100, what is 8 @ 3?","w":"The rule is a @ b = (a + b) × 10. Check: 10 @ 2 = (10 + 2) × 10 = 120 and 5 @ 5 = (5 + 5) × 10 = 100. So 8 @ 3 = (8 + 3) × 10 = 110. A product rule does not fit both examples (10 × 2 = 20 and 5 × 5 = 25 would need different multipliers), so the sum rule is the consistent one.","o":["80","96","108","110"],"a":[3],"qt":"यदि 10 @ 2 = 120 और 5 @ 5 = 100, तो 8 @ 3 क्या है?","ot":["80","96","108","110"],"wt":"नियम है a @ b = (a + b) × 10। जाँच: 10 @ 2 = (10 + 2) × 10 = 120 और 5 @ 5 = (5 + 5) × 10 = 100। अतः 8 @ 3 = (8 + 3) × 10 = 110। गुणनफल वाला नियम दोनों उदाहरणों पर लागू नहीं होता (10 × 2 = 20 और 5 × 5 = 25 के लिए अलग-अलग गुणक चाहिए), इसलिए योग वाला नियम ही संगत है।"},{"id":"c25s2-22","p":"c25s2","n":22,"s":"rea","t":"Blood Relations & Directions","q":"If P is the brother of Q, R is the sister of Q, and S is the father of P, how is R related to S?","w":"P, Q and R are siblings: P is Q's brother and R is Q's sister. S is the father of P, so S is also the father of Q and R. R is female (a sister), so R is S's daughter. Niece would need R to be the child of S's brother or sister, and wife or sister would put R in S's generation.","o":["Daughter","Niece","Wife","Sister"],"a":[0],"qt":"यदि P, Q का भाई है, R, Q की बहन है, और S, P का पिता है, तो R, S से किस प्रकार संबंधित है?","ot":["बेटी","भतीजी","पत्नी","बहन"],"wt":"P, Q और R भाई-बहन हैं: P, Q का भाई है और R, Q की बहन है। S, P का पिता है, इसलिए S, Q और R का भी पिता है। R महिला है (बहन), अतः R, S की बेटी है। भतीजी होने के लिए R को S के भाई या बहन की संतान होना चाहिए, और पत्नी या बहन होने पर R, S की ही पीढ़ी में होती।"},{"id":"c25s2-23","p":"c25s2","n":23,"s":"rea","t":"Series","q":"Find the next number in the series: 10, 21, 43, 87, ?, 351","w":"Each term is the previous term × 2 + 1: 10 × 2 + 1 = 21, 21 × 2 + 1 = 43, 43 × 2 + 1 = 87, 87 × 2 + 1 = 175, and 175 × 2 + 1 = 351, which confirms the last term. The differences 11, 22, 44, 88, 176 also double each time, giving 87 + 88 = 175.","o":["175","173","177","179"],"a":[0],"qt":"श्रृंखला में अगला अंक ज्ञात कीजिए: 10, 21, 43, 87, ?, 351","ot":["175","173","177","179"],"wt":"प्रत्येक पद पिछले पद × 2 + 1 है: 10 × 2 + 1 = 21, 21 × 2 + 1 = 43, 43 × 2 + 1 = 87, 87 × 2 + 1 = 175, और 175 × 2 + 1 = 351, जिससे अंतिम पद की पुष्टि होती है। अंतर 11, 22, 44, 88, 176 भी हर बार दोगुने होते हैं, जिससे 87 + 88 = 175 मिलता है।"},{"id":"c25s2-24","p":"c25s2","n":24,"s":"rea","t":"Miscellaneous Reasoning","q":"If a man’s present age is twice what it was 10 years ago, what is his current age?","w":"Let the present age be x. Ten years ago he was x − 10. Given x = 2(x − 10), so x = 2x − 20, which gives x = 20. Check: ten years ago he was 10, and 20 is twice 10. With 30, ten years ago he would be 20, and 30 is not twice 20, so 30 is wrong.","o":["20","30","40","25"],"a":[0],"qt":"यदि किसी व्यक्ति की वर्तमान आयु 10 वर्ष पहले की आयु से दोगुनी है, तो उसकी वर्तमान आयु क्या है?","ot":["20","30","40","25"],"wt":"मान लें वर्तमान आयु x है। 10 वर्ष पहले आयु x − 10 थी। दिया है x = 2(x − 10), अतः x = 2x − 20, जिससे x = 20। जाँच: 10 वर्ष पहले वह 10 वर्ष का था, और 20, 10 का दोगुना है। 30 लेने पर 10 वर्ष पहले आयु 20 होती, और 30, 20 का दोगुना नहीं है, इसलिए 30 गलत है।"},{"id":"c25s2-25","p":"c25s2","n":25,"s":"rea","t":"Series","q":"The series given below contains a sequence of numbers. Accordingly identify the incorrect combination 6, 7, 16, 51, 210","w":"The pattern is × n + n with n = 1, 2, 3, 4: 6 × 1 + 1 = 7, 7 × 2 + 2 = 16, 16 × 3 + 3 = 51, and 51 × 4 + 4 = 208. The last term should be 208, so 210 is the incorrect term. The first four terms fit the rule exactly, so 7, 16 and 51 are correct.","o":["210","16","7","51"],"a":[0],"qt":"नीचे दी गई श्रृंखला में संख्याओं का एक अनुक्रम है। तदनुसार गलत संयोजन की पहचान कीजिए। 6, 7, 16, 51, 210","ot":["210","16","7","51"],"wt":"पैटर्न × n + n है, जहाँ n = 1, 2, 3, 4: 6 × 1 + 1 = 7, 7 × 2 + 2 = 16, 16 × 3 + 3 = 51, और 51 × 4 + 4 = 208। अंतिम पद 208 होना चाहिए, अतः 210 गलत पद है। पहले चार पद नियम में ठीक बैठते हैं, इसलिए 7, 16 और 51 सही हैं।"},{"id":"c25s2-26","p":"c25s2","n":26,"s":"cur","t":"Static GK & Culture","q":"The Nabanna (new rice) during the Nuakhai festival in Sambalpur, Odisha, is first offered to which deity?","w":"Nuakhai is the harvest festival of western Odisha, celebrated on Bhadrava Shukla Panchami, the day after Ganesh Chaturthi. In Sambalpur the nabanna (first new rice of the season) is first offered to Maa Samaleswari, the presiding deity of the town, at the auspicious moment (lagna) fixed by the temple priests, amid hulahuli and drums. Only after this offering do families eat the new rice. Maa Mangala is the deity of Kakatpur and Maa Budhi Thakurani of Berhampur.","o":["Maa Samaleswari","Maa Mangala","Maa Bhubaneswari","Maa Budhi Thakurani"],"a":[0],"qt":"ओडिशा के संबलपुर में नुआखाई त्योहार के दौरान नबान्न (नया चावल) सबसे पहले किस देवता को चढ़ाया जाता है?","ot":["माँ समलेश्वरी","माँ मंगला","माँ भुवनेश्वरी","माँ बूढ़ी ठकुरानी"],"wt":"नुआखाई पश्चिमी ओडिशा का फसल उत्सव है, जो भाद्रपद शुक्ल पंचमी को, गणेश चतुर्थी के अगले दिन मनाया जाता है। संबलपुर में मौसम का पहला नया चावल (नबान्न) सबसे पहले नगर की अधिष्ठात्री देवी माँ समलेश्वरी को मंदिर के पुजारियों द्वारा तय शुभ मुहूर्त (लग्न) में हुलहुली और ढोल-बाजों के बीच अर्पित किया जाता है। इस भोग के बाद ही परिवार नया चावल खाते हैं। माँ मंगला काकटपुर की और माँ बूढ़ी ठकुरानी बरहमपुर की देवी हैं।"},{"id":"c25s2-27","p":"c25s2","n":27,"s":"ih","t":"Art & Culture","q":"Which of the following pairs of temple style & region are correctly matched?\n1. Vesara – Deccan\n2. Rekha-Deul – Odisha\n3. Bhumija – Malwa\n4. Kalinga – Tamil Nadu","w":"Vesara, the hybrid style of the Chalukyas and Hoysalas, belongs to the Deccan (Karnataka region). The rekha deul, a tall curvilinear tower over the sanctum, is the hallmark of Odisha's temples (Lingaraja, Jagannatha). Bhumija, a Nagara sub-style with rows of miniature spires on the tower, developed in Malwa under the Paramaras (Udayeshvara temple, Udaypur). Pair 4 is wrong: Kalinga is the style of Odisha, while Tamil Nadu follows the Dravida style. So pairs 1, 2 and 3 are correct.","o":["1 & 2 only","1, 2 & 3 are correct","2 & 4 only","only 1"],"a":[1],"qt":"मंदिर शैली और क्षेत्र के निम्नलिखित युग्मों में से कौन सा सही ढंग से मेल खाता है?\n1. वेसरा - दक्कन\n2. रेखा-देउल - ओडिशा\n3. भूमिजा - मालवा\n4. कलिंग - तमिलनाडु","ot":["केवल 1 और 2","1, 2 और 3 सही हैं","केवल 2 और 4","केवल 1"],"wt":"वेसर शैली, जो चालुक्यों और होयसलों की मिश्रित शैली है, दक्कन (कर्नाटक क्षेत्र) से संबंधित है। रेखा देउल, यानी गर्भगृह के ऊपर ऊँचा वक्ररेखीय शिखर, ओडिशा के मंदिरों (लिंगराज, जगन्नाथ) की पहचान है। भूमिजा, नागर शैली की एक उप-शैली जिसमें शिखर पर छोटे-छोटे शिखरों की पंक्तियाँ होती हैं, मालवा में परमारों के अधीन विकसित हुई (उदयपुर का उदयेश्वर मंदिर)। युग्म 4 गलत है: कलिंग ओडिशा की शैली है, जबकि तमिलनाडु में द्रविड़ शैली प्रचलित है। अतः युग्म 1, 2 और 3 सही हैं।"},{"id":"c25s2-28","p":"c25s2","n":28,"s":"ih","t":"Ancient India","q":"According to the Gupta dynasty's administrative structure, which one of the following pairs of officer and role is correctly matched?","w":"In Gupta administration the gramika (gramadhyaksha) was the village headman, who ran village affairs with the help of elders. The other pairs are wrong: the prathama-kulika was the chief artisan, who represented the craftsmen on the district advisory board alongside the nagara-shreshthi, sarthavaha and prathama-kayastha; the pustapala was the keeper of land records; and the talavataka is generally described as a village accountant, not a military paymaster.","o":["Prathamakulika – Public Works Supervisor","Gramika (Gramadhyaksha) – Village Headman","Talavataka – Military Paymaster","Pustapala – Tax-Collection Officer"],"a":[1],"qt":"गुप्त वंश की प्रशासनिक संरचना के अनुसार, अधिकारी और भूमिका के निम्नलिखित युग्मों में से कौन सा युग्म सही सुमेलित है?","ot":["प्रथमकुलिका – लोक निर्माण पर्यवेक्षक","ग्रामिका (ग्रामाध्यक्ष) - ग्राम प्रधान","तलवाटक - सैन्य भुगतानकर्ता","पुस्तपाल-कर-संग्रह अधिकारी"],"wt":"गुप्त प्रशासन में ग्रामिक (ग्रामाध्यक्ष) गाँव का मुखिया होता था, जो गाँव के बुज़ुर्गों की सहायता से गाँव का कामकाज चलाता था। बाकी युग्म गलत हैं: प्रथम-कुलिक मुख्य शिल्पी था, जो नगर-श्रेष्ठी, सार्थवाह और प्रथम-कायस्थ के साथ ज़िले के सलाहकार मंडल में कारीगरों का प्रतिनिधित्व करता था; पुस्तपाल भूमि-अभिलेखों का रक्षक था; और तलवाटक को सामान्यतः ग्राम लेखाकार बताया जाता है, सैन्य भुगतानकर्ता नहीं।"},{"id":"c25s2-29","p":"c25s2","n":29,"s":"cur","t":"Static GK & Culture","q":"Which of the following is a folk song form of Jharkhand that reflects the lived experiences, social unity, and often accompanies dance and drama performances?","w":"Domkach is a folk song-and-dance form of Jharkhand (especially the Nagpuri-speaking Chotanagpur region) and Bihar, performed at weddings. Women, notably of the groom's family on the night the baraat leaves, sing witty, teasing and joyful songs and dance in a circle, so it expresses shared experience and social bonding. The other options belong elsewhere: Lavani is from Maharashtra, Bhavai is a folk theatre of Gujarat (also a dance of Rajasthan), and Baul is the mystic minstrel song tradition of Bengal.","o":["Lavani","Domkach","Bhavai","Baul"],"a":[1],"qt":"निम्नलिखित में से कौन सा झारखंड का लोकगीत रूप है जो जीवंत अनुभवों, सामाजिक एकता को दर्शाता है और अक्सर नृत्य और नाटक प्रदर्शन के साथ होता है?","ot":["लावणी","डोमकाच","भवाई","बाउल"],"wt":"डोमकच झारखंड (विशेषकर नागपुरी भाषी छोटानागपुर क्षेत्र) और बिहार का लोकगीत-नृत्य रूप है, जो विवाह के अवसर पर किया जाता है। महिलाएँ, विशेषकर बारात निकल जाने के बाद की रात वर पक्ष की महिलाएँ, चुटीले, हँसी-मज़ाक भरे और उल्लासपूर्ण गीत गाती हैं और घेरा बनाकर नाचती हैं, इसलिए यह साझा अनुभवों और सामाजिक मेल-जोल को व्यक्त करता है। अन्य विकल्प दूसरे क्षेत्रों के हैं: लावणी महाराष्ट्र की है, भवाई गुजरात का लोकनाट्य (राजस्थान का नृत्य भी) है और बाउल बंगाल की रहस्यवादी लोकगायक परंपरा है।"},{"id":"c25s2-30","p":"c25s2","n":30,"s":"cur","t":"Sports","q":"What is the standard width of a singles badminton court as per international regulations?","w":"Under the Badminton World Federation (BWF) Laws, the court is 13.40 m long. Its full width of 6.10 m is used for doubles, while the singles court is narrower at 5.18 m, bounded by the inner side lines. So 6.10 m is the doubles width (a common trap) and 13.40 m is the length of both courts; 12.00 m is not a badminton court dimension. The net is 1.55 m high at the posts and 1.524 m at the centre.","o":["6.10 meters","13.40 meters","5.18 meters","12.00 meters"],"a":[2],"qt":"अंतर्राष्ट्रीय नियमों के अनुसार एकल बैडमिंटन कोर्ट की मानक चौड़ाई कितनी है?","ot":["6.10 मीटर","13.40 मीटर","5.18 मीटर","12.00 मीटर"],"wt":"बैडमिंटन वर्ल्ड फेडरेशन (BWF) के नियमों के अनुसार कोर्ट 13.40 मीटर लंबा होता है। इसकी पूरी चौड़ाई 6.10 मीटर युगल (डबल्स) के लिए है, जबकि एकल कोर्ट भीतरी साइड लाइनों से घिरा 5.18 मीटर चौड़ा होता है। इसलिए 6.10 मीटर युगल की चौड़ाई है (एक आम भ्रम) और 13.40 मीटर दोनों कोर्टों की लंबाई है; 12.00 मीटर बैडमिंटन कोर्ट का कोई माप नहीं है। नेट की ऊँचाई खंभों पर 1.55 मीटर और बीच में 1.524 मीटर होती है।"},{"id":"c25s2-31","p":"c25s2","n":31,"s":"ih","t":"Art & Culture","q":"Who among the following Chola emperors constructed the grand temple at Gangaikonda Cholapuram?","w":"Rajendra Chola I (1014–1044 CE) founded Gangaikonda Cholapuram as his new capital after his northern campaign reached the Ganga, and built its great Brihadisvara (Gangaikondacholisvaram) temple there. It is part of the UNESCO World Heritage Site of the Great Living Chola Temples, along with the Brihadisvara temple at Thanjavur, built by his father Rajaraja I, and the Airavatesvara temple at Darasuram, built under Rajaraja II.","o":["Rajaraja Chola I","Rajendra Chola I","Rajadhiraja Chola I","Kulothunga Chola I"],"a":[1],"qt":"निम्नलिखित में से किस चोल सम्राट ने गंगईकोंडा चोलपुरम में भव्य मंदिर का निर्माण कराया था?","ot":["राजराजा चोल प्रथम","राजेंद्र चोल प्रथम","राजाधिराज चोल प्रथम","कुलोथुंगा चोल I"],"wt":"राजेंद्र चोल प्रथम (1014–1044 ई.) ने अपने उत्तरी अभियान के गंगा तक पहुँचने के बाद गंगईकोंडा चोलपुरम को अपनी नई राजधानी बनाया और वहाँ विशाल बृहदीश्वर (गंगैकोंडचोलेश्वरम) मंदिर बनवाया। यह यूनेस्को विश्व धरोहर स्थल 'महान जीवंत चोल मंदिर' का हिस्सा है, जिसमें उनके पिता राजराज प्रथम द्वारा निर्मित तंजावुर का बृहदीश्वर मंदिर और राजराज द्वितीय के काल में बना दारासुरम का ऐरावतेश्वर मंदिर भी शामिल हैं।"},{"id":"c25s2-32","p":"c25s2","n":32,"s":"ih","t":"Modern India","q":"Read the following statements:\nStatement I: The Act of 1793 followed the tradition of personal rule without bringing in any legal reforms.\nStatement II: Judges were assigned to interpret laws rather than depend on the ruler's personal judgment.\nWhich of the above statements is/are true?","w":"The Act of 1793 refers to Lord Cornwallis's Regulations (the Cornwallis Code), issued along with the Permanent Settlement of Bengal. It did bring legal reforms: revenue collection was separated from the administration of justice, a graded system of civil and criminal courts was set up, and judges were to decide cases according to written regulations. This introduced the rule of law in place of the personal rule of earlier rulers. So Statement I is false and Statement II is true.","o":["Only 1 is true","Only 2 is true","Both Statement 1 and 2 are true","Neither 1 nor 2 is true"],"a":[1],"qt":"निम्नलिखित कथनों को पढ़ें:\nकथन I: 1793 के अधिनियम ने कोई कानूनी सुधार लाए बिना व्यक्तिगत शासन की परंपरा का पालन किया।\nकथन II: न्यायाधीशों को शासक के व्यक्तिगत निर्णय पर निर्भर रहने के बजाय कानूनों की व्याख्या करने के लिए नियुक्त किया गया था।\nउपर्युक्त कथनों में से कौन सा/से सत्य है/हैं?","ot":["केवल 1 सत्य है","केवल 2 सत्य है","कथन 1 और 2 दोनों सत्य हैं","न तो 1 और न ही 2 सत्य है"],"wt":"1793 का अधिनियम लॉर्ड कॉर्नवालिस के विनियमों (कॉर्नवालिस संहिता) को दर्शाता है, जो बंगाल के स्थायी बंदोबस्त के साथ जारी किए गए थे। इनसे कानूनी सुधार हुए: राजस्व वसूली को न्याय प्रशासन से अलग किया गया, दीवानी और फौजदारी अदालतों की श्रेणीबद्ध व्यवस्था बनाई गई और न्यायाधीशों को लिखित विनियमों के अनुसार मुकदमों का निर्णय करना था। इससे पहले के शासकों के व्यक्तिगत शासन के स्थान पर कानून का शासन आया। अतः कथन I असत्य और कथन II सत्य है।"},{"id":"c25s2-33","p":"c25s2","n":33,"s":"cur","t":"Sports","q":"Consider the following statements about the high jump:\n1) The minimum length of the runway is 15 meters.\n2) The diameter of the crossbar ranges between 15 cm and 20 cm.\nWhich of the statements is/are correct?","w":"Under World Athletics rules for the high jump, the runway must be at least 15 m long (25 m where conditions permit), so Statement 1 is correct. The crossbar is a circular bar of fibreglass or metal about 4 m long with a diameter of only 30 mm (plus or minus 1 mm), not 15 to 20 cm, so Statement 2 is wrong. The athlete must take off from one foot, and three consecutive failures eliminate the jumper.","o":["Only 1 is Correct","Only 2 is Correct","1 and 2 are Correct","Neither 1 nor 2 are Correct"],"a":[0],"qt":"ऊंची कूद के बारे में निम्नलिखित कथनों पर विचार करें:\n1) रनवे की न्यूनतम लंबाई 15 मीटर है।\n2) क्रॉसबार का व्यास 15 सेमी और 20 सेमी के बीच होता है।\nकौन सा कथन सही है/हैं?","ot":["केवल 1 सही है","केवल 2 सही है","1 और 2 सही हैं","न तो 1 और न ही 2 सही है"],"wt":"विश्व एथलेटिक्स के ऊँची कूद के नियमों के अनुसार रनवे कम से कम 15 मीटर लंबा होना चाहिए (जहाँ परिस्थितियाँ अनुमति दें, वहाँ 25 मीटर), इसलिए कथन 1 सही है। क्रॉसबार फाइबरग्लास या धातु की लगभग 4 मीटर लंबी गोल छड़ होती है, जिसका व्यास केवल 30 मिमी (±1 मिमी) होता है, 15 से 20 सेमी नहीं, इसलिए कथन 2 गलत है। खिलाड़ी को एक पैर से उछलना होता है और लगातार तीन विफलताओं पर वह प्रतियोगिता से बाहर हो जाता है।"},{"id":"c25s2-34","p":"c25s2","n":34,"s":"eco","t":"Agriculture, Industry & Trade","q":"Which of the following best reflects the strategic impact of the India–Australia Economic Cooperation and Trade Agreement (ECTA) after three years of implementation?","w":"The India–Australia ECTA was signed on 2 April 2022 and came into force on 29 December 2022; the question's \"three years\" count from the signing, whose third anniversary fell in April 2025. On that anniversary the Commerce Ministry reported that India's exports to Australia grew 14% in 2023-24 over 2022-23, with new export lines such as air liquefaction machinery, calcined petroleum coke and high-capacity diesel generating sets. Tariff cuts were reciprocal, not unilateral; India kept sensitive farm products such as dairy out of its concessions; and the agreement has no defence provisions.","o":["ECTA removed all tariffs on Australian farm goods unilaterally.","ECTA mainly benefitted old sectors like cotton, with little new growth.","ECTA led to 14% export growth (2022–24) and added new items like Air Liquefaction Machinery.","ECTA includes mutual defence procurement via an Indo-Pacific charter."],"a":[2],"qt":"निम्नलिखित में से कौन सा कथन कार्यान्वयन के तीन वर्षों के बाद भारत-ऑस्ट्रेलिया आर्थिक सहयोग और व्यापार समझौते ईसीटीए(ECTA) के रणनीतिक प्रभाव को सर्वोत्तम रूप से दर्शाता है?","ot":["ईसीटीए(ECTA) ने ऑस्ट्रेलियाई कृषि वस्तुओं पर एकतरफा रूप से सभी टैरिफ हटा दिए।","ईसीटीए(ECTA) से मुख्य रूप से कपास जैसे पुराने क्षेत्रों को लाभ हुआ, जबकि नई वृद्धि बहुत कम हुई।","ईसीटीए(ECTA) के कारण 14% निर्यात वृद्धि (2022-24) हुई और एयर लिक्विफैक्शन मशीनरी जैसी नई वस्तुओं को जोड़ा गया।","ईसीटीए(ECTA) में इंडो-पैसिफिक चार्टर के माध्यम से पारस्परिक रक्षा खरीद शामिल है।"],"wt":"भारत-ऑस्ट्रेलिया ईसीटीए पर 2 अप्रैल 2022 को हस्ताक्षर हुए और यह 29 दिसंबर 2022 को लागू हुआ; प्रश्न के 'तीन वर्ष' हस्ताक्षर से गिने गए हैं, जिसकी तीसरी वर्षगाँठ अप्रैल 2025 में थी। उस अवसर पर वाणिज्य मंत्रालय ने बताया कि 2022-23 की तुलना में 2023-24 में भारत का ऑस्ट्रेलिया को निर्यात 14% बढ़ा और एयर लिक्विफैक्शन मशीनरी, कैल्सिन्ड पेट्रोलियम कोक तथा उच्च क्षमता वाले डीजल जनरेटिंग सेट जैसी नई निर्यात वस्तुएँ जुड़ीं। शुल्क कटौती पारस्परिक थी, एकतरफा नहीं; भारत ने डेयरी जैसे संवेदनशील कृषि उत्पादों को रियायतों से बाहर रखा; और समझौते में रक्षा संबंधी कोई प्रावधान नहीं है।"},{"id":"c25s2-35","p":"c25s2","n":35,"s":"cur","t":"Awards, Books & Persons","q":"An Area of Darkness is a travelogue by which Indian author?","w":"An Area of Darkness (1964) is V.S. Naipaul's account of his first visit to India, the land of his ancestors, based on a year-long stay that began in 1962. It forms an India trilogy with India: A Wounded Civilization (1977) and India: A Million Mutinies Now (1990). Naipaul was born in Trinidad to a family of Indian origin and was a British citizen, so \"Indian author\" here means of Indian descent; he won the 2001 Nobel Prize in Literature. Vikram Seth's travel book is From Heaven Lake; Raja Rao and R.K. Narayan are known chiefly for novels.","o":["Raja Rao","V.S. Naipaul","R.K. Narayan","Vikram Seth"],"a":[1],"qt":"एन एरिया ऑफ डार्कनेस किस भारतीय लेखक द्वारा लिखा गया यात्रा वृत्तांत है?","ot":["राजा राव","वी.एस. नायपॉल","आर.के. नारायण","विक्रम सेठ"],"wt":"एन एरिया ऑफ डार्कनेस (1964) वी.एस. नायपॉल की अपने पूर्वजों की भूमि भारत की पहली यात्रा का वृत्तांत है, जो 1962 में शुरू हुए लगभग एक वर्ष के प्रवास पर आधारित है। यह इंडिया: ए वूंडेड सिविलाइज़ेशन (1977) और इंडिया: ए मिलियन म्यूटिनीज़ नाउ (1990) के साथ उनकी भारत-त्रयी बनाती है। नायपॉल त्रिनिदाद में भारतीय मूल के परिवार में जन्मे थे और ब्रिटिश नागरिक थे, इसलिए यहाँ 'भारतीय लेखक' का अर्थ भारतीय मूल का लेखक है; उन्हें 2001 में साहित्य का नोबेल पुरस्कार मिला। विक्रम सेठ की यात्रा पुस्तक फ्रॉम हेवन लेक है; राजा राव और आर.के. नारायण मुख्यतः अपने उपन्यासों के लिए जाने जाते हैं।"},{"id":"c25s2-36","p":"c25s2","n":36,"s":"cur","t":"Sports","q":"Which Indian fencer secured the bronze medal in the women’s Cadet Epee category at the 2022 Asian Junior and Cadet Fencing Championships?","w":"Prachi Lohan won the bronze medal in the women's cadet (under-17) épée event at the 2022 Asian Junior and Cadet Fencing Championships held in Tashkent, Uzbekistan. She later became the women's épée national champion at the 33rd Senior National Fencing Championships in 2023. Bhavani Devi, the tempting option, is a sabre fencer and was the first Indian fencer to compete at the Olympics (Tokyo 2020); she was not a cadet in 2022.","o":["Bhavani Devi","Prachi Lohan","C.A. Bhavya","Kushi Chaudhary"],"a":[1],"qt":"किस भारतीय फ़ेंसर ने 2022 एशियाई जूनियर और कैडेट फ़ेंसिंग चैंपियनशिप में महिला कैडेट एपी श्रेणी में कांस्य पदक हासिल किया?","ot":["भवानी देवी","प्राची लोहान","सी.ए. भव्या","कुशी चौधरी"],"wt":"प्राची लोहान ने ताशकंद (उज़्बेकिस्तान) में हुई 2022 एशियाई जूनियर और कैडेट फ़ेंसिंग चैंपियनशिप में महिला कैडेट (अंडर-17) एपी स्पर्धा में कांस्य पदक जीता। बाद में वह 2023 में 33वीं सीनियर राष्ट्रीय फ़ेंसिंग चैंपियनशिप में महिला एपी की राष्ट्रीय चैंपियन बनीं। भवानी देवी, जो भ्रमित करने वाला विकल्प हैं, सेबर फ़ेंसर हैं और ओलंपिक (टोक्यो 2020) में भाग लेने वाली पहली भारतीय फ़ेंसर थीं; वह 2022 में कैडेट नहीं थीं।"},{"id":"c25s2-37","p":"c25s2","n":37,"s":"cur","t":"Sports","q":"Which of the following statements about the Khelo India Youth Games (KIYG) 2023 is correct?","w":"The sixth Khelo India Youth Games (KIYG 2023) were held in Tamil Nadu, the first time in south India, from 19 to 31 January 2024: 13 days across 15 venues in four cities, namely Chennai, Madurai, Tiruchirappalli and Coimbatore. Over 5,600 athletes competed in 26 sports disciplines, with Silambam as the demonstration sport and squash included for the first time. Maharashtra topped the medal table, which may explain the Maharashtra distractor.","o":["The KIYG 2023 were held in four cities of Maharashtra.","The games included 20 disciplines and no demo sport.","The event lasted for 13 days across 15 venues.","Only 4000 athletes participated in KIYG 2023."],"a":[2],"qt":"खेलो इंडिया यूथ गेम्स (KIYG) केआईवाईजी 2023 के बारे में निम्नलिखित में से कौन सा कथन सही है?","ot":["केआईवाईजी( KIYG) 2023 महाराष्ट्र के चार शहरों में आयोजित किया गया।","खेलों में 20 खेल शामिल थे और कोई डेमो खेल नहीं था।","यह आयोजन 15 स्थानों पर 13 दिनों तक चला।","केआईवाईजी(KIYG) 2023 में केवल 4000 एथलीटों ने भाग लिया।"],"wt":"छठे खेलो इंडिया यूथ गेम्स (KIYG 2023) पहली बार दक्षिण भारत में, तमिलनाडु में 19 से 31 जनवरी 2024 तक आयोजित हुए: 13 दिनों तक, चार शहरों चेन्नई, मदुरै, तिरुचिरापल्ली और कोयंबटूर के 15 स्थलों पर। 5,600 से अधिक खिलाड़ियों ने 26 खेल विधाओं में भाग लिया, सिलंबम प्रदर्शन (डेमो) खेल था और स्क्वैश पहली बार शामिल हुआ। पदक तालिका में महाराष्ट्र शीर्ष पर रहा, जिससे शायद महाराष्ट्र वाला भ्रामक विकल्प बना।"},{"id":"c25s2-38","p":"c25s2","n":38,"s":"pol","t":"Government & Parliament","q":"Fill in the blanks:\nThe Union Home Minister chairs a Zonal Council meeting as ______ chairman.","w":"Zonal Councils are statutory bodies set up under the States Reorganisation Act, 1956, to promote Centre–State and inter-State cooperation. There are five of them (Northern, Central, Eastern, Western and Southern), and the Union Home Minister is the chairman of each by virtue of his office, that is, ex officio. The Chief Ministers of the member States take turns as vice-chairman, one year at a time, so the rotating post is that of vice-chairman, not chairman.","o":["ex-officio","rotating","ceremonial","honorary"],"a":[0],"qt":"रिक्त स्थान भरें:\nकेंद्रीय गृह मंत्री ______ अध्यक्ष के रूप में क्षेत्रीय परिषद की बैठक की अध्यक्षता करते हैं।","ot":["पदेन","घूर्णनशील","अनुष्ठानिक","मानद"],"wt":"क्षेत्रीय परिषदें राज्य पुनर्गठन अधिनियम, 1956 के तहत केंद्र-राज्य और अंतर-राज्यीय सहयोग बढ़ाने के लिए बनी सांविधिक संस्थाएँ हैं। ये पाँच हैं (उत्तरी, मध्य, पूर्वी, पश्चिमी और दक्षिणी), और केंद्रीय गृह मंत्री अपने पद के आधार पर, यानी पदेन, प्रत्येक के अध्यक्ष होते हैं। सदस्य राज्यों के मुख्यमंत्री बारी-बारी से एक-एक वर्ष के लिए उपाध्यक्ष बनते हैं, इसलिए बारी-बारी से बदलने वाला (घूर्णनशील) पद उपाध्यक्ष का है, अध्यक्ष का नहीं।"},{"id":"c25s2-39","p":"c25s2","n":39,"s":"sci","t":"Biology","q":"Which of the following statements regarding human antibodies is/are accurate?\n1. IgG constitutes the largest proportion of antibodies in human blood.\n2. IgE plays a key role in allergic responses.\n3. IgA is primarily located in bodily secretions such as saliva and breast milk.","w":"All three statements are correct. IgG is the most abundant antibody, about 75–80% of the antibodies in blood serum, and the only one that crosses the placenta. IgE binds to mast cells and basophils and triggers histamine release in allergic reactions; it also acts against parasitic worms. IgA is the main antibody of secretions such as saliva, tears, mucus and breast milk (especially colostrum), protecting mucous surfaces. IgM, a large pentamer, is the first antibody made in an infection.","o":["Only 1 and 2 are correct","Only 2 and 3 are correct","Only 1 and 3 are correct","1, 2 and 3 all are correct"],"a":[3],"qt":"मानव एंटीबॉडी के संबंध में निम्नलिखित में से कौन सा/से कथन सही है/हैं?\n1. मानव रक्त में एंटीबॉडी का सबसे बड़ा अनुपात IgG होता है।\n2. एलर्जी प्रतिक्रियाओं में IgE की महत्वपूर्ण भूमिका होती है।\n3. IgA मुख्य रूप से लार और स्तन के दूध जैसे शारीरिक स्रावों में पाया जाता है।","ot":["केवल 1 और 2 सही हैं","केवल 2 और 3 सही हैं","केवल 1 और 3 सही हैं","1, 2 और 3 सभी सही हैं"],"wt":"तीनों कथन सही हैं। IgG सबसे अधिक मात्रा में पाई जाने वाली एंटीबॉडी है, जो रक्त सीरम की एंटीबॉडी का लगभग 75–80% होती है, और यही एकमात्र एंटीबॉडी है जो प्लेसेंटा पार करती है। IgE मास्ट कोशिकाओं और बेसोफिल से जुड़कर एलर्जी प्रतिक्रियाओं में हिस्टामिन मुक्त कराती है; यह परजीवी कृमियों के विरुद्ध भी काम करती है। IgA लार, आँसू, श्लेष्मा और स्तन के दूध (विशेषकर कोलोस्ट्रम) जैसे स्रावों की मुख्य एंटीबॉडी है, जो श्लेष्म सतहों की रक्षा करती है। IgM, एक बड़ा पेंटामर, संक्रमण में सबसे पहले बनने वाली एंटीबॉडी है।"},{"id":"c25s2-40","p":"c25s2","n":40,"s":"pol","t":"Government & Parliament","q":"Arrange the following in chronological order:\nA) Sarkaria Commission report submitted\nB) Inter-State Council constituted\nC) Punchhi Commission constituted","w":"The Sarkaria Commission on Centre–State relations was set up in 1983 and submitted its report in 1988. Acting on one of its recommendations, the government constituted the Inter-State Council under Article 263 by a Presidential Order of 28 May 1990. The second commission on Centre–State relations, headed by Justice M.M. Punchhi, was constituted in April 2007 and reported in 2010. So the correct order is A (1988), B (1990), C (2007).","o":["A-B-C","A-C-B","B-C-A","C-B-A"],"a":[0],"qt":"निम्नलिखित को कालानुक्रमिक क्रम में व्यवस्थित कीजिए:\nA) सरकारिया आयोग की रिपोर्ट प्रस्तुत की गई\nB) अंतर-राज्यीय परिषद का गठन किया गया\nC) पुंछी आयोग का गठन किया गया","ot":["A-B-C","A-C-B","B-C-A","C-B-A"],"wt":"केंद्र-राज्य संबंधों पर सरकारिया आयोग 1983 में गठित हुआ और उसने 1988 में अपनी रिपोर्ट सौंपी। उसकी एक सिफारिश पर अमल करते हुए सरकार ने 28 मई 1990 के राष्ट्रपति आदेश द्वारा अनुच्छेद 263 के तहत अंतर-राज्यीय परिषद का गठन किया। केंद्र-राज्य संबंधों पर दूसरा आयोग, न्यायमूर्ति एम.एम. पुंछी की अध्यक्षता में, अप्रैल 2007 में गठित हुआ और उसने 2010 में रिपोर्ट दी। अतः सही क्रम A (1988), B (1990), C (2007) है।"},{"id":"c25s2-41","p":"c25s2","n":41,"s":"cur","t":"Static GK & Culture","q":"Fill in the Blank:\nTippani arises from the ______ region of Gujarat.","w":"Tippani is a folk dance of the Chorwad and Veraval area of Saurashtra in Gujarat. It grew out of the work of Koli women labourers who beat lime-concrete floors with a tippani, a long wooden pole with a heavy block at the lower end, while singing in two facing rows to lighten the labour. Today it is performed at festivals and weddings to instruments such as the turi, thali, dhol and shehnai.","o":["Kutch","Saurashtra","Surat","Vadodara"],"a":[1],"qt":"रिक्त स्थान को भरें:\nटिप्पाणी गुजरात के ______ क्षेत्र से उत्पन्न होती है।","ot":["कच्छ","सौराष्ट्र","सूरत","वडोदरा"],"wt":"टिप्पणी गुजरात के सौराष्ट्र क्षेत्र के चोरवाड और वेरावल इलाके का लोकनृत्य है। इसकी उत्पत्ति कोली समुदाय की मज़दूर महिलाओं के काम से हुई, जो काम की थकान दूर करने के लिए आमने-सामने दो पंक्तियों में गाते हुए टिप्पणी (निचले सिरे पर भारी गुटके वाला लंबा लकड़ी का डंडा) से चूने-कंक्रीट के फर्श को कूटती थीं। आज यह त्योहारों और विवाहों में तूरी, थाली, ढोल और शहनाई जैसे वाद्यों के साथ किया जाता है।"},{"id":"c25s2-42","p":"c25s2","n":42,"s":"eco","t":"Planning, Growth & Budget","q":"Which of the following is a key economic role of the government in both developed and developing countries?","w":"In every economy, developed or developing, the state provides the legal and institutional framework within which markets work: it frames laws, defines and protects property rights, enforces contracts and delivers justice, besides maintaining law and order. Without this framework private economic activity cannot run smoothly. The other options are too narrow or wrong: governments do much more than only regulating firms or only promoting exports, and currency exchange is mainly handled by central banks and markets.","o":["Only regulating private firms","Only promoting exports","Framing laws and delivering justice","Engaging in currency exchange"],"a":[2],"qt":"निम्नलिखित में से कौन सी विकसित और विकासशील दोनों देशों में सरकार की प्रमुख आर्थिक भूमिका है?","ot":["केवल निजी फर्मों का विनियमन","केवल निर्यात को बढ़ावा देना","कानून बनाना और न्याय प्रदान करना","मुद्रा विनिमय में संलग्न होना"],"wt":"हर अर्थव्यवस्था में, चाहे विकसित हो या विकासशील, राज्य वह कानूनी और संस्थागत ढाँचा देता है जिसके भीतर बाज़ार काम करते हैं: वह कानून बनाता है, संपत्ति के अधिकार तय करता है और उनकी रक्षा करता है, अनुबंध लागू कराता है और न्याय प्रदान करता है, साथ ही कानून-व्यवस्था बनाए रखता है। इस ढाँचे के बिना निजी आर्थिक गतिविधि सुचारु रूप से नहीं चल सकती। अन्य विकल्प बहुत सीमित या गलत हैं: सरकारें केवल फर्मों के विनियमन या केवल निर्यात बढ़ाने से कहीं अधिक करती हैं, और मुद्रा विनिमय मुख्यतः केंद्रीय बैंक और बाज़ार संभालते हैं।"},{"id":"c25s2-43","p":"c25s2","n":43,"s":"cur","t":"International","q":"The 2025 Global Peace Index indicates that global peacefulness has generally shown a:","w":"The Global Peace Index 2025, released in June 2025 by the Institute for Economics and Peace (IEP), Sydney, found that the average level of global peacefulness fell by 0.36%. This was the 13th deterioration in the last 17 years, showing a gradual long-term decline rather than improvement or stability. Iceland remained the most peaceful country (a position it has held since 2008), Russia was ranked the least peaceful, and India was placed 115th.","o":["Consistent upward trend","Gradual downward trend","Significant improvement","Stable and unchanging state"],"a":[1],"qt":"2025 वैश्विक शांति सूचकांक यह दर्शाता है कि वैश्विक शांति ने आम तौर पर निम्न दर्शाया है:","ot":["लगातार ऊपर की ओर रुझान","क्रमिक गिरावट की प्रवृत्ति","सार्थक सुधार","स्थिर और अपरिवर्तनीय अवस्था"],"wt":"सिडनी स्थित इंस्टीट्यूट फॉर इकोनॉमिक्स एंड पीस (IEP) द्वारा जून 2025 में जारी वैश्विक शांति सूचकांक 2025 के अनुसार वैश्विक शांति का औसत स्तर 0.36% घटा। यह पिछले 17 वर्षों में 13वीं गिरावट थी, जो सुधार या स्थिरता के बजाय क्रमिक दीर्घकालिक गिरावट दर्शाती है। आइसलैंड सबसे शांतिपूर्ण देश बना रहा (2008 से यह स्थान उसी के पास है), रूस सबसे कम शांतिपूर्ण देश रहा और भारत 115वें स्थान पर रहा।"},{"id":"c25s2-44","p":"c25s2","n":44,"s":"eco","t":"Agriculture, Industry & Trade","q":"When was the first Industrial Policy announced in independent India?","w":"The first Industrial Policy Resolution of independent India was announced on 6 April 1948. It laid the basis of a mixed economy by dividing industries into four groups: those reserved for the state (such as arms, atomic energy and railways), basic industries where only the state would set up new units, industries under government regulation, and the rest left to the private sector. It was replaced by the Industrial Policy Resolution of 1956.","o":["1948","1950","1951","1952"],"a":[0],"qt":"स्वतंत्र भारत में पहली औद्योगिक नीति कब घोषित की गई थी?","ot":["1948","1950","1951","1952"],"wt":"स्वतंत्र भारत का पहला औद्योगिक नीति प्रस्ताव 6 अप्रैल 1948 को घोषित हुआ। इसने उद्योगों को चार समूहों में बाँटकर मिश्रित अर्थव्यवस्था की नींव रखी: राज्य के लिए आरक्षित उद्योग (जैसे हथियार, परमाणु ऊर्जा और रेलवे), आधारभूत उद्योग जिनमें नई इकाइयाँ केवल राज्य लगाएगा, सरकारी विनियमन वाले उद्योग, और शेष उद्योग निजी क्षेत्र के लिए। इसका स्थान 1956 के औद्योगिक नीति प्रस्ताव ने लिया।"},{"id":"c25s2-45","p":"c25s2","n":45,"s":"eco","t":"Planning, Growth & Budget","q":"Read the following statements carefully and choose the correct option regarding Assertion (A) and Reason (R).\nAssertion (A): Globalization led to increased inequality in India.\nReason (R): Growth was unevenly distributed, benefiting mostly urban elite and service sectors.","w":"After the 1991 reforms (liberalisation, privatisation and globalisation) India's growth speeded up, but the gains were uneven. Much of the growth came from services such as IT, finance and telecom, which mainly benefited skilled urban workers and higher-income groups, while agriculture and the informal sector lagged behind. Critics therefore argue that income and regional inequality widened. The uneven distribution of growth is exactly why inequality rose, so both statements are true and R explains A.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":[0],"qt":"निम्नलिखित कथनों को ध्यानपूर्वक पढ़िए और अभिकथन (A) और कारण (R) के संबंध में सही विकल्प चुनिए।\nअभिकथन (A): वैश्वीकरण के कारण भारत में असमानता बढ़ी।\nकारण (R): विकास असमान रूप से वितरित हुआ, जिसका लाभ मुख्यतः शहरी अभिजात वर्ग और सेवा क्षेत्रों को हुआ।","ot":["A और R दोनों सत्य हैं और R, A का सही स्पष्टीकरण है।","A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है।","A सत्य है लेकिन R असत्य है।","A असत्य है लेकिन R सत्य है।"],"wt":"1991 के सुधारों (उदारीकरण, निजीकरण और वैश्वीकरण) के बाद भारत की वृद्धि तेज़ हुई, लेकिन उसके लाभ असमान रहे। अधिकांश वृद्धि आईटी, वित्त और दूरसंचार जैसी सेवाओं से आई, जिनसे मुख्यतः कुशल शहरी कामगारों और उच्च आय वर्गों को लाभ मिला, जबकि कृषि और अनौपचारिक क्षेत्र पीछे रह गए। इसलिए आलोचकों का तर्क है कि आय और क्षेत्रीय असमानता बढ़ी। वृद्धि का असमान वितरण ही असमानता बढ़ने का कारण है, इसलिए दोनों कथन सत्य हैं और R, A की सही व्याख्या करता है।"},{"id":"c25s2-46","p":"c25s2","n":46,"s":"eco","t":"Planning, Growth & Budget","q":"Disinvestment involves selling stakes in?","w":"Disinvestment means the government selling part or all of its equity in public sector enterprises, such as central public sector enterprises and public sector banks, through IPOs, offers for sale or strategic sale to a private buyer. The proceeds are non-debt capital receipts in the Union Budget. The work is handled by the Department of Investment and Public Asset Management (DIPAM) in the Ministry of Finance. The strategic sale of Air India to the Tata group in 2022 is a well-known example.","o":["NGOs","Private firms","Public enterprises","Trade unions"],"a":[2],"qt":"विनिवेश में किसमें हिस्सेदारी बेचना शामिल है?","ot":["गैर सरकारी संगठनों","निजी फर्मों","सार्वजनिक उद्यम","ट्रेड यूनियन"],"wt":"विनिवेश का अर्थ है सरकार द्वारा केंद्रीय सार्वजनिक क्षेत्र उद्यमों और सार्वजनिक क्षेत्र के बैंकों जैसे सार्वजनिक उद्यमों में अपनी इक्विटी का कुछ भाग या पूरा हिस्सा आईपीओ, ऑफर फॉर सेल या किसी निजी खरीदार को रणनीतिक बिक्री के माध्यम से बेचना। इससे मिली राशि केंद्रीय बजट में गैर-ऋण पूंजीगत प्राप्ति होती है। यह कार्य वित्त मंत्रालय का निवेश और लोक परिसंपत्ति प्रबंधन विभाग (दीपम) देखता है। 2022 में एयर इंडिया की टाटा समूह को रणनीतिक बिक्री इसका प्रसिद्ध उदाहरण है।"},{"id":"c25s2-47","p":"c25s2","n":47,"s":"geo","t":"Environment & Ecology","q":"Which one of the following National Park–State pairs is correctly matched?","w":"Similipal is in Mayurbhanj district, Odisha, and is the core of the Similipal Tiger Reserve and Biosphere Reserve, known for its melanistic (black) tigers. In April 2025 the Odisha government formally notified about 845.70 sq km of it as a national park, the state's second after Bhitarkanika. The other pairs are wrong: Namdapha is in Arunachal Pradesh, Bandipur is in Karnataka, and Vansda is in Navsari district of Gujarat.","o":["Namdapha National Park – Nagaland","Similipal National Park – Odisha","Bandipur National Park – Andhra Pradesh","Vansda National Park – Rajasthan"],"a":[1],"qt":"निम्नलिखित में से कौन सा राष्ट्रीय उद्यान-राज्य युग्म सही सुमेलित है?","ot":["नमदाफा राष्ट्रीय उद्यान – नागालैंड","सिमिलिपाल राष्ट्रीय उद्यान – ओडिशा","बांदीपुर राष्ट्रीय उद्यान – आंध्र प्रदेश","वांसदा राष्ट्रीय उद्यान – राजस्थान"],"wt":"सिमिलिपाल ओडिशा के मयूरभंज ज़िले में है और सिमिलिपाल टाइगर रिज़र्व तथा बायोस्फीयर रिज़र्व का कोर क्षेत्र है, जो अपने मेलानिस्टिक (काले) बाघों के लिए प्रसिद्ध है। अप्रैल 2025 में ओडिशा सरकार ने इसके लगभग 845.70 वर्ग किमी क्षेत्र को औपचारिक रूप से राष्ट्रीय उद्यान अधिसूचित किया, जो भितरकनिका के बाद राज्य का दूसरा राष्ट्रीय उद्यान है। अन्य युग्म गलत हैं: नमदाफा अरुणाचल प्रदेश में, बांदीपुर कर्नाटक में और वांसदा गुजरात के नवसारी ज़िले में है।"},{"id":"c25s2-48","p":"c25s2","n":48,"s":"pol","t":"Constitution & Rights","q":"The concept of “Reasonable Classification” as a limitation to the Right to Equality (Article 14) was established in which case?","w":"In State of West Bengal v. Anwar Ali Sarkar (1952), a seven-judge bench of the Supreme Court held that Article 14 forbids class legislation but permits reasonable classification. A classification is valid only if it rests on an intelligible differentia and that differentia has a rational nexus with the object of the law. The idea was first noted in Chiranjit Lal Chowdhury (1950) and restated in Budhan Choudhry (1955); E.P. Royappa (1974) and Maneka Gandhi (1978) later added the test of non-arbitrariness.","o":["Kesavananda Bharati v. State of Kerala","State of West Bengal v. Anwar Ali Sarkar","Maneka Gandhi v. Union of India","Golaknath Case v. State of Punjab & Anrs."],"a":[1],"qt":"समानता के अधिकार (अनुच्छेद 14) पर एक सीमा के रूप में “उचित वर्गीकरण” की अवधारणा किस मामले में स्थापित की गई थी?","ot":["केशवानंद भारती बनाम केरल राज्य","पश्चिम बंगाल राज्य बनाम अनवर अली सरकार","मेनका गांधी बनाम भारत संघ","गोलकनाथ मामला बनाम पंजाब राज्य और अन्य"],"wt":"पश्चिम बंगाल राज्य बनाम अनवर अली सरकार (1952) में सर्वोच्च न्यायालय की सात न्यायाधीशों की पीठ ने कहा कि अनुच्छेद 14 वर्ग विधान का निषेध करता है, लेकिन उचित वर्गीकरण की अनुमति देता है। वर्गीकरण तभी वैध है जब वह बोधगम्य अंतर पर आधारित हो और उस अंतर का कानून के उद्देश्य से तर्कसंगत संबंध हो। यह विचार पहली बार चिरंजीत लाल चौधरी (1950) में आया और बुधन चौधरी (1955) में दोहराया गया; बाद में ई.पी. रोयप्पा (1974) और मेनका गांधी (1978) ने मनमानेपन के विरुद्ध कसौटी जोड़ी। (हिंदी प्रश्नपत्र में विकल्प 3 भूलवश विकल्प 2 जैसा छपा था; अंग्रेज़ी के अनुसार इसे 'मेनका गांधी बनाम भारत संघ' किया गया है।)"},{"id":"c25s2-49","p":"c25s2","n":49,"s":"cur","t":"Static GK & Culture","q":"Match the dance with its core tribe/community.\nDance | Tribe/Community\n1. Kalbelia | A. Nomadic snake-charmers of Rajasthan\n2. Panthi | B. Satnami (Chhattisgarh)\n3. Dangi Nritya | C. Dang district Bhil-origin tribes\n4. Paika | D. Khandayat warrior caste of Odisha","w":"Kalbelia is the dance of the Kalbelia community, traditionally nomadic snake-charmers of Rajasthan; it is on UNESCO's intangible cultural heritage list (2010). Panthi is the devotional dance of the Satnami community of Chhattisgarh, honouring Guru Ghasidas. Dangi Nritya belongs to the Bhil and other tribes of the Dang district of Gujarat. Paika is a martial dance of Odisha linked with the Paikas, the traditional peasant militia drawn largely from the Khandayat caste. So the match is 1-A, 2-B, 3-C, 4-D.","o":["1-A 2-B 3-C 4-D","1-B 2-A 3-D 4-C","1-C 2-B 3-A 4-D","1-A 2-C 3-B 4-D"],"a":[0],"qt":"नृत्य को उसके मूल जनजाति/समुदाय से मिलाएं।\nनृत्य | जनजाति/समुदाय\n1.कालबेलिया | A.राजस्थान के घुमंतू सपेरे\n2. पंथी | B. सतनामी (छत्तीसगढ़)\n3. डांगी नृत्य | C. डांग जिले में भील मूल की जनजातियाँ हैं\n4. पाइका | D. ओडिशा की खंडायत योद्धा जाति","ot":["1-A, 2-B, 3-C, 4-D","1-B, 2-A, 3-D, 4-C","1-C, 2-B, 3-A, 4-D","1-A, 2-C, 3-B, 4-D"],"wt":"कालबेलिया, परंपरागत रूप से राजस्थान के घुमंतू सपेरे कालबेलिया समुदाय का नृत्य है; यह यूनेस्को की अमूर्त सांस्कृतिक विरासत सूची (2010) में शामिल है। पंथी छत्तीसगढ़ के सतनामी समुदाय का भक्ति नृत्य है, जो गुरु घासीदास के सम्मान में किया जाता है। डांगी नृत्य गुजरात के डांग ज़िले की भील और अन्य जनजातियों का है। पाइका ओडिशा का युद्ध-नृत्य है, जो पाइकों, यानी अधिकतर खंडायत जाति से आने वाले पारंपरिक किसान सैनिकों, से जुड़ा है। अतः सुमेलन 1-A, 2-B, 3-C, 4-D है।"},{"id":"c25s2-50","p":"c25s2","n":50,"s":"sci","t":"Science & Technology","q":"Identify the incorrect match of satellite type and application:","w":"Navigation satellites, such as India's NavIC (IRNSS) and the US GPS, provide position, navigation and timing services; they do not monitor forest fires. Forest fires are detected by earth-observation (remote sensing) and weather satellites using thermal and infrared sensors, as in the Forest Survey of India's fire alert system. The other pairs are correct: weather satellites (INSAT-3D series) track cyclones, communication satellites (GSAT series) carry TV and DTH broadcasts, and remote sensing satellites map land use.","o":["Weather satellite - Cyclone tracking","Communication satellite - TV broadcast","Navigation satellite - Forest fire monitoring","Remote sensing satellite - Land use mapping"],"a":[2],"qt":"उपग्रह प्रकार और अनुप्रयोग के गलत मिलान की पहचान करें:","ot":["मौसम उपग्रह - चक्रवात ट्रैकिंग","उपग्रह संचार - टीवी प्रसारण","उपग्रह नेविगेशन - वन अग्नि निगरानी","सुदूर संवेदन उपग्रह - भूमि उपयोग मानचित्रण"],"wt":"नेविगेशन उपग्रह, जैसे भारत का नाविक (IRNSS) और अमेरिका का जीपीएस, स्थिति, नेविगेशन और समय संबंधी सेवाएँ देते हैं; ये वनों की आग की निगरानी नहीं करते। वन अग्नि का पता थर्मल और इन्फ्रारेड सेंसर वाले पृथ्वी-अवलोकन (सुदूर संवेदन) और मौसम उपग्रहों से लगाया जाता है, जैसे भारतीय वन सर्वेक्षण की अग्नि चेतावनी प्रणाली में। अन्य युग्म सही हैं: मौसम उपग्रह (INSAT-3D श्रृंखला) चक्रवातों को ट्रैक करते हैं, संचार उपग्रह (GSAT श्रृंखला) टीवी और डीटीएच प्रसारण करते हैं, और सुदूर संवेदन उपग्रह भूमि उपयोग का मानचित्रण करते हैं।"},{"id":"c25s2-51","p":"c25s2","n":51,"s":"qa","t":"Ratio, Average & Mixtures","q":"If 30% of m is equal to 18% of n, what is the ratio m: n?","w":"Write the condition as an equation: 0.30m = 0.18n, so m/n = 0.18/0.30 = 18/30 = 3/5. Hence m : n = 3 : 5. Check: with m = 3 and n = 5, 30% of 3 = 0.9 and 18% of 5 = 0.9. The tempting 5 : 3 reverses the ratio; the larger percentage goes with the smaller quantity.","o":["5 : 3","2 : 3","3 : 5","3 : 2"],"a":[2],"qt":"यदि m का 30% n के 18% के बराबर है, तो m:n का अनुपात क्या है?","ot":["5 : 3","2 : 3","3 : 5","3 : 2"],"wt":"शर्त को समीकरण के रूप में लिखिए: 0.30m = 0.18n, अतः m/n = 0.18/0.30 = 18/30 = 3/5। इसलिए m : n = 3 : 5। जाँच: m = 3 और n = 5 लेने पर 3 का 30% = 0.9 और 5 का 18% = 0.9। आकर्षक विकल्प 5 : 3 अनुपात को उलट देता है; बड़ा प्रतिशत छोटी राशि के साथ जुड़ता है।"},{"id":"c25s2-52","p":"c25s2","n":52,"s":"qa","t":"Number System & Simplification","q":"Find the value of √(388 + √(127 + √289))","w":"Simplify nested roots from the innermost one outwards. √289 = 17, so the middle root is √(127 + 17) = √144 = 12. The outer root then becomes √(388 + 12) = √400 = 20. Taking the roots in any other order, or adding 388 + 127 first, gives a wrong value.","o":["20","30","40","50"],"a":[0],"qt":"√(388 + √(127 + √289)) का मान ज्ञात कीजिए","ot":["20","30","40","50"],"wt":"नेस्टेड (एक के भीतर एक) मूलों को सबसे भीतर वाले मूल से बाहर की ओर हल कीजिए। √289 = 17, अतः बीच वाला मूल √(127 + 17) = √144 = 12 होगा। तब बाहरी मूल √(388 + 12) = √400 = 20 हो जाता है। मूलों को किसी अन्य क्रम में लेने पर, या पहले 388 + 127 जोड़ देने पर, गलत मान मिलता है।"},{"id":"c25s2-53","p":"c25s2","n":53,"s":"qa","t":"Number System & Simplification","q":"Identify the incorrect relationship(s) from the list below:\n(i) √6 + √2 = √5 + √3\n(ii) √6 + √2 < √5 + √3\n(iii) √6 + √2 > √5 + √3","w":"Compare by squaring both positive sums. (√6 + √2)² = 6 + 2 + 2√12 = 8 + 2√12, and (√5 + √3)² = 5 + 3 + 2√15 = 8 + 2√15. Since √15 > √12, √5 + √3 is larger (about 3.968 against 3.864). So (ii) is true, and (i) and (iii) are the incorrect relationships. When two pairs have equal sums under the roots (6 + 2 = 5 + 3), the pair whose numbers are closer together gives the bigger sum.","o":["(i)","(ii)","(i) and (iii)","(ii) and (iii)"],"a":[2],"qt":"नीचे दी गई सूची में से गलत संबंध पहचानें:\n(i) √6 + √2 = √5 + √3\n(ii) √6 + √2 < √5 + √3\n(iii) √6 + √2 > √5 + √3","ot":["(i)","(ii)","(i) and (iii)","(ii) और (iii)"],"wt":"दोनों धनात्मक योगों का वर्ग करके तुलना कीजिए। (√6 + √2)² = 6 + 2 + 2√12 = 8 + 2√12, और (√5 + √3)² = 5 + 3 + 2√15 = 8 + 2√15। चूँकि √15 > √12, इसलिए √5 + √3 बड़ा है (लगभग 3.968, जबकि दूसरा 3.864)। अतः (ii) सत्य है, और (i) तथा (iii) गलत संबंध हैं। जब मूलों के अंदर की संख्याओं के योग बराबर हों (6 + 2 = 5 + 3), तो जिस युग्म की संख्याएँ एक-दूसरे के अधिक निकट हों, उसका योग बड़ा होता है।"},{"id":"c25s2-54","p":"c25s2","n":54,"s":"qa","t":"Percentage, Profit & Interest","q":"A bookseller purchases 5 novels at the marked price of 4 novels from a distributor. If he then sells these novels to customers, offering a discount of 5% on the marked price, what is his profit percentage?","w":"Let the marked price of one novel be ₹100. The bookseller pays the price of 4 novels for 5, so CP of 5 novels = ₹400. He sells each at 95% of ₹100, so SP of 5 novels = 5 × 95 = ₹475. Profit = 475 − 400 = ₹75, and profit % = 75/400 × 100 = 18.75%. Profit is reckoned on the cost (₹400), not on the marked value of the 5 novels.","o":["15%","18.75%","20.26%","25%"],"a":[1],"qt":"एक पुस्तक विक्रेता एक वितरक से 4 उपन्यासों के अंकित मूल्य पर 5 उपन्यास खरीदता है। यदि वह इन उपन्यासों को अंकित मूल्य पर 5% की छूट देकर ग्राहकों को बेचता है, तो उसका लाभ प्रतिशत क्या है?","ot":["15%","18.75%","20.26%","25%"],"wt":"मान लीजिए एक उपन्यास का अंकित मूल्य ₹100 है। विक्रेता 5 उपन्यासों के लिए 4 उपन्यासों का मूल्य देता है, अतः 5 उपन्यासों का क्रय मूल्य = ₹400। वह प्रत्येक को ₹100 के 95% पर बेचता है, अतः 5 उपन्यासों का विक्रय मूल्य = 5 × 95 = ₹475। लाभ = 475 − 400 = ₹75, और लाभ % = 75/400 × 100 = 18.75%। लाभ क्रय मूल्य (₹400) पर निकाला जाता है, 5 उपन्यासों के अंकित मूल्य पर नहीं।"},{"id":"c25s2-55","p":"c25s2","n":55,"s":"qa","t":"Time, Work, Speed & Distance","q":"A and B can finish a certain job in 28 and 35 days, respectively. They started working together, but A left after a while, and B managed to complete the remaining work in 17 days. How many days did A work before leaving?","w":"Take total work = LCM(28, 35) = 140 units. A does 140/28 = 5 units a day and B does 140/35 = 4 units a day. B alone works 17 days at the end, doing 17 × 4 = 68 units, so the two together did 140 − 68 = 72 units at 5 + 4 = 9 units a day. Hence they worked together for 72/9 = 8 days, which is how long A worked before leaving.","o":["8 days","5 days","6 7/2 days","7 5/2 days"],"a":[0],"qt":"A और B किसी काम को क्रमशः 28 और 35 दिनों में पूरा कर सकते हैं। उन्होंने साथ मिलकर काम करना शुरू किया, लेकिन कुछ समय बाद A ने काम छोड़ दिया और B ने शेष काम 17 दिनों में पूरा कर लिया। काम छोड़ने से पहले A ने कितने दिन काम किया?","ot":["8 दिन","5 दिन","6 7/2 दिन","7 5/2 दिन"],"wt":"कुल काम = LCM(28, 35) = 140 इकाई मानिए। A एक दिन में 140/28 = 5 इकाई और B एक दिन में 140/35 = 4 इकाई काम करता है। अंत में B अकेले 17 दिन काम करता है और 17 × 4 = 68 इकाई काम करता है, अतः दोनों ने मिलकर 140 − 68 = 72 इकाई काम 5 + 4 = 9 इकाई प्रतिदिन की दर से किया। इसलिए उन्होंने 72/9 = 8 दिन साथ काम किया, और यही वह अवधि है जितने दिन A ने काम छोड़ने से पहले काम किया।"},{"id":"c25s2-56","p":"c25s2","n":56,"s":"qa","t":"Algebra","q":"Given, x + 1/x = 4, Find the value of: x⁶ + 1/x⁶ − 3(x⁴ + 1/x⁴) + 4(x² + 1/x²)","w":"From x + 1/x = 4: x² + 1/x² = 4² − 2 = 14; x⁴ + 1/x⁴ = 14² − 2 = 194; and x⁶ + 1/x⁶ = (x² + 1/x²)³ − 3(x² + 1/x²) = 14³ − 3 × 14 = 2744 − 42 = 2702. The expression is 2702 − 3 × 194 + 4 × 14 = 2702 − 582 + 56 = 2176. Each step uses (a + 1/a)² = a² + 1/a² + 2 or the cube identity (a + 1/a)³ = a³ + 1/a³ + 3(a + 1/a).","o":["2176","2087","2562","2476"],"a":[0],"qt":"दिया गया है, x + 1/x = 4, तो x⁶ + 1/x⁶ − 3(x⁴ + 1/x⁴) + 4(x² + 1/x²) का मान ज्ञात कीजिए:","ot":["2176","2087","2562","2476"],"wt":"x + 1/x = 4 से: x² + 1/x² = 4² − 2 = 14; x⁴ + 1/x⁴ = 14² − 2 = 194; और x⁶ + 1/x⁶ = (x² + 1/x²)³ − 3(x² + 1/x²) = 14³ − 3 × 14 = 2744 − 42 = 2702। व्यंजक का मान = 2702 − 3 × 194 + 4 × 14 = 2702 − 582 + 56 = 2176। प्रत्येक चरण में (a + 1/a)² = a² + 1/a² + 2 या घन सर्वसमिका (a + 1/a)³ = a³ + 1/a³ + 3(a + 1/a) का प्रयोग होता है।"},{"id":"c25s2-57","p":"c25s2","n":57,"s":"qa","t":"Percentage, Profit & Interest","q":"Reena borrowed Rs. 1200 at simple interest for a number of years equal to the rate of interest. At the end of the loan term, she paid Rs. 432 in interest. What was the interest rate?","w":"Simple interest SI = P × R × T/100. Here T = R, so 432 = 1200 × R × R/100 = 12R². Then R² = 432/12 = 36 and R = 6. The rate is 6% per annum for 6 years. Check: 1200 × 6 × 6/100 = ₹432.","o":["6%","7%","8%","9%"],"a":[0],"qt":"रीना ने 1200 रुपये साधारण ब्याज पर कई वर्षों के लिए उधार लिए, जो ब्याज दर के बराबर था। ऋण अवधि के अंत में, उसने 432 रुपये ब्याज के रूप में चुकाए। ब्याज दर क्या थी?","ot":["6%","7%","8%","9%"],"wt":"साधारण ब्याज SI = P × R × T/100। यहाँ T = R है, अतः 432 = 1200 × R × R/100 = 12R²। तब R² = 432/12 = 36 और R = 6। ब्याज दर 6% वार्षिक है और अवधि 6 वर्ष। जाँच: 1200 × 6 × 6/100 = ₹432।"},{"id":"c25s2-58","p":"c25s2","n":58,"s":"qa","t":"Percentage, Profit & Interest","q":"A person invested ₹20,000 in two different schemes. He invested one part for 4 years at 8% simple interest and the other part for the same duration at 10% simple interest. If the interest earned from the second part was ₹2,240 more than the interest earned from the first part, how much money was invested in the second scheme?","w":"Let ₹x be invested at 10%; then ₹(20,000 − x) is at 8%. Over 4 years the interests are 40% of x and 32% of (20,000 − x). So 0.40x − 0.32(20,000 − x) = 2,240, giving 0.72x − 6,400 = 2,240, i.e. 0.72x = 8,640 and x = ₹12,000. Check: 4,800 − 2,560 = ₹2,240.","o":["₹8,000","₹10,000","₹12,000","₹12,500"],"a":[2],"qt":"एक व्यक्ति ने दो अलग-अलग योजनाओं में ₹20,000 का निवेश किया। उसने एक भाग को 4 वर्ष के लिए 8% साधारण ब्याज पर तथा दूसरे भाग को समान अवधि के लिए 10% साधारण ब्याज पर निवेश किया। यदि दूसरे भाग से अर्जित ब्याज पहले भाग से अर्जित ब्याज से ₹2,240 अधिक था, तो दूसरी योजना में कितना पैसा निवेश किया गया?","ot":["₹8,000","₹10,000","₹12,000","₹12,500"],"wt":"मान लीजिए ₹x को 10% पर निवेश किया गया; तब ₹(20,000 − x) 8% पर है। 4 वर्षों में ब्याज क्रमशः x का 40% और (20,000 − x) का 32% होगा। अतः 0.40x − 0.32(20,000 − x) = 2,240, जिससे 0.72x − 6,400 = 2,240, अर्थात् 0.72x = 8,640 और x = ₹12,000। जाँच: 4,800 − 2,560 = ₹2,240।"},{"id":"c25s2-59","p":"c25s2","n":59,"s":"qa","t":"Trigonometry & Heights","q":"A rock climber uses a rope to ascend a cliff. If the vertical height of the cliff is 35 meters and the rope makes an angle of 30° with the level ground, what is the minimum length of the rope required to reach the top?","w":"The rope is the hypotenuse of a right triangle whose side opposite the 30° angle is the cliff height. So sin 30° = height/rope, giving rope = 35/sin 30° = 35/(1/2) = 70 m. Using tan 30° instead would give the horizontal distance from the foot of the cliff (35√3 ≈ 60.6 m), not the rope length.","o":["35m","40m","60m","70m"],"a":[3],"qt":"एक चट्टान पर चढ़ने वाला व्यक्ति चट्टान पर चढ़ने के लिए रस्सी का उपयोग करता है। यदि चट्टान की ऊर्ध्वाधर ऊंचाई 35 मीटर है और रस्सी समतल जमीन के साथ 30° का कोण बनाती है, तो शीर्ष तक पहुँचने के लिए रस्सी की न्यूनतम लंबाई कितनी होनी चाहिए?","ot":["35 मीटर","40 मीटर","60 मीटर","70 मीटर"],"wt":"रस्सी एक समकोण त्रिभुज का कर्ण है, जिसमें 30° कोण के सामने की भुजा चट्टान की ऊँचाई है। अतः sin 30° = ऊँचाई/रस्सी, जिससे रस्सी = 35/sin 30° = 35/(1/2) = 70 मीटर। इसके स्थान पर tan 30° का प्रयोग करने पर चट्टान के आधार से क्षैतिज दूरी (35√3 ≈ 60.6 मीटर) मिलती है, रस्सी की लंबाई नहीं।"},{"id":"c25s2-60","p":"c25s2","n":60,"s":"qa","t":"Mensuration","q":"A marble is spherical in shape with a radius of 4 cm. If the marble is placed inside a cube with side length 10 cm, what is the volume of the cube that is not occupied by the marble?","w":"Volume of the cube = 10³ = 1000 cm³. Volume of the marble = (4/3)πr³ = (4/3) × 3.14 × 4³ = (4/3) × 3.14 × 64 = 267.946… cm³. Unoccupied volume = 1000 − 267.946 ≈ 732.05 cm³; the keyed 732.06 cm³ comes from cutting the marble volume to 267.94, and with exact π the value is about 731.92 cm³. Either way 732.06 cm³ is the only option near the true value. The sphere fits because its diameter, 8 cm, is less than the cube's side.","o":["100 cm³","732.06 cm³","300 cm³","624.82 cm³"],"a":[1],"qt":"एक मार्बल गोलाकार है जिसकी त्रिज्या 4 सेमी है। यदि मार्बल को 10 सेमी भुजा वाले घन के अंदर रखा जाए, तो उस घन का आयतन क्या होगा जिसमें मार्बल नहीं है?","ot":["100 सेमी³","732.06 सेमी³","300 सेमी³","624.82 सेमी³"],"wt":"घन का आयतन = 10³ = 1000 सेमी³। मार्बल का आयतन = (4/3)πr³ = (4/3) × 3.14 × 4³ = (4/3) × 3.14 × 64 = 267.946… सेमी³। खाली आयतन = 1000 − 267.946 ≈ 732.05 सेमी³; कुंजी का 732.06 सेमी³ मार्बल के आयतन को 267.94 तक काटने से आता है, और π का सटीक मान लेने पर यह लगभग 731.92 सेमी³ है। दोनों ही स्थितियों में केवल 732.06 सेमी³ ही वास्तविक मान के निकट विकल्प है। गोला घन में समा जाता है क्योंकि उसका व्यास 8 सेमी, घन की भुजा से कम है।"},{"id":"c25s2-61","p":"c25s2","n":61,"s":"qa","t":"Mensuration","q":"Two hemispheres of radii 2 cm and 4 cm respectively are melted and recast into another hemisphere. What is the approximate total surface area of the newly formed hemisphere?","w":"Volume is conserved: (2/3)πR³ = (2/3)π(2³ + 4³), so R³ = 8 + 64 = 72 and R ≈ 4.16 cm. Total surface area of a solid hemisphere = curved 2πR² + base πR² = 3πR² = 3 × 3.1416 × 17.31 ≈ 163 cm². Remember to include the flat circular face; using only 2πR² gives about 109 cm².","o":["163cm²","142cm³","150cm²","138cm²"],"a":[0],"qt":"दो अर्धगोलों की त्रिज्याएँ क्रमशः 2 सेमी और 4 सेमी हैं। इन्हें पिघलाकर एक नए अर्धगोले में ढाला गया है। नए बने अर्धगोले का कुल पृष्ठीय क्षेत्रफल लगभग कितना होगा?","ot":["163 सेमी²","142 सेमी³","150 सेमी²","138 सेमी²"],"wt":"आयतन संरक्षित रहता है: (2/3)πR³ = (2/3)π(2³ + 4³), अतः R³ = 8 + 64 = 72 और R ≈ 4.16 सेमी। ठोस अर्धगोले का कुल पृष्ठीय क्षेत्रफल = वक्र पृष्ठ 2πR² + आधार πR² = 3πR² = 3 × 3.1416 × 17.31 ≈ 163 सेमी²। समतल वृत्ताकार सतह को शामिल करना याद रखें; केवल 2πR² लेने पर लगभग 109 सेमी² मिलता है।"},{"id":"c25s2-62","p":"c25s2","n":62,"s":"qa","t":"Mensuration","q":"If all three dimensions of a cuboid are increased by 10%, the volume increases by what percentage?","w":"Volume = l × b × h. With each dimension multiplied by 1.1, the new volume is 1.1³ = 1.331 times the old one, an increase of 33.1%. Equivalently, apply successive change three times: 10% and 10% give 21%, then 21% and 10% give 21 + 10 + 2.1 = 33.1%. Simply adding (30%) ignores the compounding.","o":["10%","21%","30%","33.1%"],"a":[3],"qt":"यदि किसी घनाभ के तीनों आयामों में 10% की वृद्धि कर दी जाए, तो आयतन में कितने प्रतिशत की वृद्धि होगी?","ot":["10%","21%","30%","33.1%"],"wt":"आयतन = l × b × h। प्रत्येक आयाम को 1.1 से गुणा करने पर नया आयतन पुराने का 1.1³ = 1.331 गुना हो जाता है, अर्थात् 33.1% की वृद्धि। इसी प्रकार क्रमिक परिवर्तन को तीन बार लगाइए: 10% और 10% से 21% मिलता है, फिर 21% और 10% से 21 + 10 + 2.1 = 33.1%। केवल जोड़ देना (30%) चक्रवृद्धि प्रभाव को अनदेखा करता है।"},{"id":"c25s2-63","p":"c25s2","n":63,"s":"qa","t":"Mensuration","q":"A cone is sliced into two sections by a plane that is parallel to its base, with the upper section representing 1/8 of the overall volume. What is the ratio of the heights of the smaller cone to the original cone?","w":"A cut parallel to the base gives a small cone similar to the original. For similar solids, volumes are in the ratio of the cubes of corresponding lengths, so (h/H)³ = 1/8 and h/H = 1/2. Hence the heights are in the ratio 1 : 2. The ratio 1 : 7 is that of the volumes of the small cone and the remaining frustum, not of heights.","o":["1 : 2","1 : 7","5 : 1","6 : 1"],"a":[0],"qt":"एक शंकु को उसके आधार के समांतर एक समतल द्वारा दो भागों में काटा गया है, जिसमें ऊपरी भाग कुल आयतन का 1/8 भाग दर्शाता है। छोटे शंकु की ऊँचाई का मूल शंकु से अनुपात क्या है?","ot":["1 : 2","1 : 7","5 : 1","6 : 1"],"wt":"आधार के समांतर काटने पर एक छोटा शंकु बनता है जो मूल शंकु के समरूप होता है। समरूप ठोसों के आयतन संगत लंबाइयों के घनों के अनुपात में होते हैं, अतः (h/H)³ = 1/8 और h/H = 1/2। इसलिए ऊँचाइयों का अनुपात 1 : 2 है। अनुपात 1 : 7 छोटे शंकु और शेष छिन्नक के आयतनों का है, ऊँचाइयों का नहीं।"},{"id":"c25s2-64","p":"c25s2","n":64,"s":"qa","t":"Trigonometry & Heights","q":"If sin A = 3/5 and cos B = 12/13, A and B ∈ (0, π/2), find sin(A + B).","w":"Both angles are acute, so all ratios are positive. From sin A = 3/5, cos A = 4/5 (3-4-5 triangle); from cos B = 12/13, sin B = 5/13 (5-12-13 triangle). Then sin(A + B) = sin A cos B + cos A sin B = (3/5)(12/13) + (4/5)(5/13) = 36/65 + 20/65 = 56/65. The value 16/65 would be sin(A − B).","o":["56/65","63/65","33/65","77/85"],"a":[0],"qt":"अगर sin A = 3/5 और cos B = 12/13, A and B ∈ (0, π/2), खोजो sin(A + B).","ot":["56/65","63/65","33/65","77/85"],"wt":"दोनों कोण न्यून हैं, अतः सभी अनुपात धनात्मक हैं। sin A = 3/5 से cos A = 4/5 (3-4-5 त्रिभुज); cos B = 12/13 से sin B = 5/13 (5-12-13 त्रिभुज)। तब sin(A + B) = sin A cos B + cos A sin B = (3/5)(12/13) + (4/5)(5/13) = 36/65 + 20/65 = 56/65। मान 16/65, sin(A − B) होगा।"},{"id":"c25s2-65","p":"c25s2","n":65,"s":"qa","t":"Trigonometry & Heights","q":"A tower generates a shadow that is 40 meters long when the sun’s angle of elevation is 45 degrees. What is the height of the tower?","w":"The tower, its shadow and the sun's ray form a right triangle with the angle of elevation at the tip of the shadow. tan 45° = height/shadow, and tan 45° = 1, so height = shadow = 40 m. Whenever the elevation is 45°, the height of the object equals the length of its shadow.","o":["50 m","40 m","20 m","10 m"],"a":[1],"qt":"एक मीनार की परछाई 40 मीटर लंबी होती है जब सूर्य का उन्नयन कोण 45 डिग्री होता है। मीनार की ऊँचाई कितनी है?","ot":["50 मीटर","40 मीटर","20 मीटर","10 मीटर"],"wt":"मीनार, उसकी परछाई और सूर्य की किरण एक समकोण त्रिभुज बनाते हैं, जिसमें उन्नयन कोण परछाई के छोर पर होता है। tan 45° = ऊँचाई/परछाई, और tan 45° = 1, अतः ऊँचाई = परछाई = 40 मीटर। जब भी उन्नयन कोण 45° हो, वस्तु की ऊँचाई उसकी परछाई की लंबाई के बराबर होती है।"},{"id":"c25s2-66","p":"c25s2","n":66,"s":"qa","t":"Algebra","q":"A line y = mx + 2 passes through (3,8). Find m.","w":"A point lies on a line when its coordinates satisfy the equation. Put x = 3 and y = 8 in y = mx + 2: 8 = 3m + 2, so 3m = 6 and m = 2. Here m is the slope and 2 is the y-intercept, so the line rises 2 units for each unit moved to the right.","o":["5","4","3","2"],"a":[3],"qt":"एक रेखा y = mx + 2, (3,8) से होकर जाती है। m ज्ञात कीजिए।","ot":["5","4","3","2"],"wt":"कोई बिंदु किसी रेखा पर तभी स्थित होता है जब उसके निर्देशांक रेखा के समीकरण को संतुष्ट करें। y = mx + 2 में x = 3 और y = 8 रखिए: 8 = 3m + 2, अतः 3m = 6 और m = 2। यहाँ m ढलान (प्रवणता) है और 2 y-अंतःखंड है, अतः दाईं ओर प्रत्येक एक इकाई चलने पर रेखा 2 इकाई ऊपर उठती है।"},{"id":"c25s2-67","p":"c25s2","n":67,"s":"qa","t":"Mensuration","q":"A sector of a circle has a central angle of 120° and a radius of 5 cm. Another sector of the same circle has a central angle of 2π/3 radians. What is the ratio of the area of the first sector to the area of the second sector?","w":"Convert radians to degrees: 2π/3 rad = (2/3) × 180° = 120°. Both sectors are in the same circle (radius 5 cm) and have the same central angle, so their areas, (θ/360°) × πr², are equal: each is (1/3) × π × 25 ≈ 26.2 cm². Hence the ratio is 1 : 1. The different units are the only trap in the question.","o":["1:1","3:4","2:3","5:6"],"a":[0],"qt":"एक वृत्त के एक त्रिज्यखंड का केंद्रीय कोण 120° और त्रिज्या 5 सेमी है। उसी वृत्त के एक अन्य त्रिज्यखंड का केंद्रीय कोण 2π/3 रेडियन है। पहले त्रिज्यखंड के क्षेत्रफल का दूसरे त्रिज्यखंड के क्षेत्रफल से अनुपात क्या है?","ot":["1:1","3:4","2:3","5:6"],"wt":"रेडियन को डिग्री में बदलिए: 2π/3 रेडियन = (2/3) × 180° = 120°। दोनों त्रिज्यखंड एक ही वृत्त (त्रिज्या 5 सेमी) के हैं और उनका केंद्रीय कोण भी समान है, अतः उनके क्षेत्रफल, (θ/360°) × πr², बराबर हैं: प्रत्येक (1/3) × π × 25 ≈ 26.2 सेमी² है। इसलिए अनुपात 1 : 1 है। प्रश्न में अलग-अलग इकाइयाँ ही एकमात्र जाल हैं।"},{"id":"c25s2-68","p":"c25s2","n":68,"s":"qa","t":"Geometry","q":"What is the measure of each interior angle in a regular eight-sided polygon?","w":"The sum of the interior angles of an n-sided polygon is (n − 2) × 180°. For a regular octagon, n = 8, so the sum is 6 × 180° = 1080° and each angle is 1080°/8 = 135°. Alternatively, each exterior angle is 360°/8 = 45°, so each interior angle is 180° − 45° = 135°. 120° is the angle of a regular hexagon.","o":["120°","135°","150°","165°"],"a":[1],"qt":"एक नियमित आठ भुजाओं वाले बहुभुज में प्रत्येक आंतरिक कोण का माप क्या है?","ot":["120°","135°","150°","165°"],"wt":"n भुजाओं वाले बहुभुज के आंतरिक कोणों का योग (n − 2) × 180° होता है। नियमित अष्टभुज के लिए n = 8, अतः योग 6 × 180° = 1080° और प्रत्येक कोण 1080°/8 = 135° है। वैकल्पिक रूप से, प्रत्येक बाह्य कोण 360°/8 = 45° है, अतः प्रत्येक आंतरिक कोण 180° − 45° = 135°। 120° नियमित षट्भुज का कोण है।"},{"id":"c25s2-69","p":"c25s2","n":69,"s":"qa","t":"Mensuration","q":"In a trapezoid, the two parallel sides are in the ratio 3:5. If the height of the trapezoid is 10 cm and its total area is 240 cm², determine the lengths of the parallel sides.","w":"Let the parallel sides be 3k and 5k. Area of a trapezium = ½ × (sum of parallel sides) × height, so 240 = ½ × 8k × 10 = 40k, giving k = 6. The sides are 3 × 6 = 18 cm and 5 × 6 = 30 cm. Check: ½ × 48 × 10 = 240 cm². Option 15 cm and 25 cm keeps the ratio but gives an area of only 200 cm².","o":["15 cm and 25 cm","18 cm and 30 cm","20 cm and 40 cm","30 cm and 50 cm"],"a":[1],"qt":"एक समलम्ब चतुर्भुज में, दो समांतर भुजाएँ 3:5 के अनुपात में हैं। यदि समलम्ब चतुर्भुज की ऊँचाई 10 सेमी है और इसका कुल क्षेत्रफल 240 वर्ग सेमी है, तो समांतर भुजाओं की लंबाई ज्ञात कीजिए।","ot":["15 सेमी और 25 सेमी","18 सेमी और 30 सेमी","20 सेमी और 40 सेमी","30 सेमी और 50 सेमी"],"wt":"मान लीजिए समांतर भुजाएँ 3k और 5k हैं। समलम्ब चतुर्भुज का क्षेत्रफल = ½ × (समांतर भुजाओं का योग) × ऊँचाई, अतः 240 = ½ × 8k × 10 = 40k, जिससे k = 6। भुजाएँ 3 × 6 = 18 सेमी और 5 × 6 = 30 सेमी हैं। जाँच: ½ × 48 × 10 = 240 वर्ग सेमी। विकल्प 15 सेमी और 25 सेमी अनुपात तो बनाए रखता है, पर उससे क्षेत्रफल केवल 200 वर्ग सेमी आता है।"},{"id":"c25s2-70","p":"c25s2","n":70,"s":"qa","t":"Geometry","q":"△ABC has sides AB=5 cm, BC=6 cm, AC=7 cm. △XYZ is congruent to △ABC. What is the perimeter of △XYZ?","w":"Congruent triangles have exactly the same size and shape, so their corresponding sides are equal. Hence △XYZ has sides 5 cm, 6 cm and 7 cm, and its perimeter equals that of △ABC: 5 + 6 + 7 = 18 cm. (Only for similar, not congruent, triangles would the perimeters be in a ratio other than 1 : 1.)","o":["13 cm","18 cm","20 cm","24 cm"],"a":[1],"qt":"△ABC की भुजाएँ AB=5 सेमी, BC=6 सेमी, AC=7 सेमी हैं। △XYZ, △ABC के सर्वांगसम है। △XYZ का परिमाप क्या है?","ot":["13 सेमी","18 सेमी","20 सेमी","24 सेमी"],"wt":"सर्वांगसम त्रिभुजों का आकार और आकृति बिल्कुल समान होते हैं, अतः उनकी संगत भुजाएँ बराबर होती हैं। इसलिए △XYZ की भुजाएँ 5 सेमी, 6 सेमी और 7 सेमी हैं, और इसका परिमाप △ABC के परिमाप के बराबर है: 5 + 6 + 7 = 18 सेमी। (केवल समरूप, न कि सर्वांगसम, त्रिभुजों में ही परिमापों का अनुपात 1 : 1 से भिन्न हो सकता है।)"},{"id":"c25s2-71","p":"c25s2","n":71,"s":"qa","t":"Algebra","q":"Given, √x + 1/√x = 4, then what is x + 1/x?","w":"Square both sides: (√x + 1/√x)² = x + 1/x + 2 × √x × (1/√x) = x + 1/x + 2. So 4² = x + 1/x + 2, i.e. 16 = x + 1/x + 2, giving x + 1/x = 14. A common slip is to forget the middle term 2 and choose 16.","o":["15","14","16","17"],"a":[1],"qt":"दिया गया है, √x + 1/√x = 4, तो क्या है x + 1/x?","ot":["15","14","16","17"],"wt":"दोनों पक्षों का वर्ग कीजिए: (√x + 1/√x)² = x + 1/x + 2 × √x × (1/√x) = x + 1/x + 2। अतः 4² = x + 1/x + 2, अर्थात् 16 = x + 1/x + 2, जिससे x + 1/x = 14। एक सामान्य भूल बीच वाले पद 2 को भूल जाना और 16 चुन लेना है।"},{"id":"c25s2-72","p":"c25s2","n":72,"s":"qa","t":"Trigonometry & Heights","q":"If cot A = 2, then sin A − cos A = ?","w":"cot A = adjacent/opposite = 2/1, so take adjacent side 2, opposite side 1 and hypotenuse √(2² + 1²) = √5. Taking A as acute (the usual assumption), sin A = 1/√5 and cos A = 2/√5. Hence sin A − cos A = 1/√5 − 2/√5 = −1/√5. The result is negative because cot A > 1 means A < 45°, where cos A exceeds sin A. (If A were in the third quadrant, both ratios would be negative and the value +1/√5, which is not an option.)","o":["2/√5","−1/√5","0","3/5"],"a":[1],"qt":"अगर cot A = 2, तब sin A − cos A = ?","ot":["2/√5","−1/√5","0","3/5"],"wt":"cot A = आसन्न भुजा/सम्मुख भुजा = 2/1, अतः आसन्न भुजा 2, सम्मुख भुजा 1 और कर्ण √(2² + 1²) = √5 लीजिए। A को न्यून कोण मानने पर (सामान्य मान्यता), sin A = 1/√5 और cos A = 2/√5। अतः sin A − cos A = 1/√5 − 2/√5 = −1/√5। परिणाम ऋणात्मक है क्योंकि cot A > 1 का अर्थ है A < 45°, जहाँ cos A, sin A से बड़ा होता है। (यदि A तीसरे चतुर्थांश में होता, तो दोनों अनुपात ऋणात्मक होते और मान +1/√5 होता, जो विकल्पों में नहीं है।)"},{"id":"c25s2-73","p":"c25s2","n":73,"s":"qa","t":"Geometry","q":"A circle has radius 7 cm. A tangent is drawn from an external point P. If the length of the tangent is 24 cm, what is the distance from P to the center of the circle?","w":"The radius drawn to the point of contact is perpendicular to the tangent, so the radius, the tangent and the line from P to the centre form a right triangle with that line as hypotenuse. Distance = √(7² + 24²) = √(49 + 576) = √625 = 25 cm. Option 576 cm is just 24², and 31 cm is the simple sum 7 + 24.","o":["17 cm","25 cm","31 cm","576 cm"],"a":[1],"qt":"एक वृत्त की त्रिज्या 7 सेमी है। बाह्य बिंदु P से एक स्पर्श रेखा खींची गई है। यदि स्पर्श रेखा की लंबाई 24 सेमी है, तो P से वृत्त के केंद्र की दूरी क्या है?","ot":["17 सेमी","25 सेमी","31 सेमी","576 सेमी"],"wt":"स्पर्श बिंदु तक खींची गई त्रिज्या स्पर्श रेखा पर लंब होती है, अतः त्रिज्या, स्पर्श रेखा और P से केंद्र तक की रेखा एक समकोण त्रिभुज बनाते हैं, जिसमें यह रेखा कर्ण है। दूरी = √(7² + 24²) = √(49 + 576) = √625 = 25 सेमी। विकल्प 576 सेमी केवल 24² है, और 31 सेमी सीधा योग 7 + 24 है।"},{"id":"c25s2-74","p":"c25s2","n":74,"s":"qa","t":"Geometry","q":"From a point outside a circle, two tangents are drawn to the circle. If one of the tangents measures 12 cm, what is the length of the other tangent?","w":"The two tangents drawn to a circle from an external point are always equal in length. This follows from congruent right triangles: each has the line joining the point to the centre as hypotenuse and a radius as one leg, which is perpendicular to the tangent. Hence the other tangent is also 12 cm.","o":["10 cm","11 cm","12 cm","14 cm"],"a":[2],"qt":"एक वृत्त के बाहर एक बिंदु से वृत्त पर दो स्पर्श रेखाएँ खींची गई हैं। यदि एक स्पर्श रेखा की लंबाई 12 सेमी है, तो दूसरी स्पर्श रेखा की लंबाई क्या है?","ot":["10 सेमी","11 सेमी","12 सेमी","14 सेमी"],"wt":"किसी बाह्य बिंदु से वृत्त पर खींची गई दोनों स्पर्श रेखाएँ सदैव लंबाई में बराबर होती हैं। यह सर्वांगसम समकोण त्रिभुजों से सिद्ध होता है: प्रत्येक में बिंदु को केंद्र से मिलाने वाली रेखा कर्ण होती है और एक भुजा त्रिज्या होती है, जो स्पर्श रेखा पर लंब होती है। अतः दूसरी स्पर्श रेखा भी 12 सेमी है।"},{"id":"c25s2-75","p":"c25s2","n":75,"s":"qa","t":"Number System & Simplification","q":"Evaluate: (0.04³ + 0.02³) ÷ (0.2³ + 0.1³)","w":"Note that 0.04 = 0.2 × 0.2 and 0.02 = 0.1 × 0.2, so the numerator is 0.2³ × (0.2³ + 0.1³). Dividing by (0.2³ + 0.1³) leaves 0.2³ = 0.008. Directly: numerator = 0.000064 + 0.000008 = 0.000072 and denominator = 0.008 + 0.001 = 0.009, so the value is 0.000072/0.009 = 0.008.","o":["0.008","0.004","0.002","0.016"],"a":[0],"qt":"मूल्यांकन करें: (0.04³ + 0.02³) ÷ (0.2³ + 0.1³)","ot":["0.008","0.004","0.002","0.016"],"wt":"ध्यान दीजिए कि 0.04 = 0.2 × 0.2 और 0.02 = 0.1 × 0.2, अतः अंश = 0.2³ × (0.2³ + 0.1³)। इसे (0.2³ + 0.1³) से भाग देने पर 0.2³ = 0.008 बचता है। सीधे हल करने पर: अंश = 0.000064 + 0.000008 = 0.000072 और हर = 0.008 + 0.001 = 0.009, अतः मान 0.000072/0.009 = 0.008।"},{"id":"c25s2-76","p":"c25s2","n":76,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word: INVECTIVE","w":"'Invective' means insulting, abusive or highly critical language, a violent verbal attack on someone. Its synonym is 'tirade', a long, angry speech of criticism or accusation, as in 'The leader launched a tirade against the government.' 'Eulogy' (a speech praising someone, especially after death), 'compliment' and 'praise' all express approval, so they are closer to antonyms of invective than synonyms.","o":["Eulogy","Compliment","Praise","Tirade"],"a":[3]},{"id":"c25s2-77","p":"c25s2","n":77,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word: EBULLIENT","w":"'Ebullient' means cheerful and full of energy and excitement; it literally means 'boiling over' (Latin ebullire, to bubble out). So 'enthusiastic' is the closest synonym, as in 'an ebullient crowd'. 'Depressed' and 'dull' are its opposites, and 'calm' suggests quiet composure, which is the reverse of the bubbling excitement that ebullient describes.","o":["Depressed","Dull","Enthusiastic","Calm"],"a":[2]},{"id":"c25s2-78","p":"c25s2","n":78,"s":"eng","t":"Vocabulary","q":"Select the most appropriate antonym of the given word. Sagacious","w":"'Sagacious' means having keen mental discernment and sound judgement; wise and shrewd (Latin sagax, 'of keen perception'). Its antonym is 'foolish', lacking good sense or judgement. 'Insightful', 'wise' and 'prudent' (careful and sensible about the future) are all synonyms or near-synonyms of sagacious, so none of them can be its opposite.","o":["Insightful","Wise","Foolish","Prudent"],"a":[2]},{"id":"c25s2-79","p":"c25s2","n":79,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct meaning of idiom:\nGall and wormwood","w":"'Gall and wormwood' describes something extremely bitter and galling to a person, a source of deep frustration, bitterness or resentment. Gall (bile) and wormwood (a bitter herb) are both proverbially bitter, and the phrase comes from the Bible. Example: His rival's promotion was gall and wormwood to him. The idiom has nothing to do with curiosity, harmless envy or sudden enlightenment.","o":["Lingering curiosity","Harmless envy","Sudden realization or enlightenment","Deep frustration or resentment"],"a":[3]},{"id":"c25s2-80","p":"c25s2","n":80,"s":"eng","t":"Spelling","q":"Choose the correct spelling of a word meaning 'a person of high rank or title'.","w":"The correct spelling is 'noble' (n-o-b-l-e). As a noun, a noble is a person who belongs to the aristocracy by birth or title, such as a duke or an earl; as an adjective it also means having fine moral qualities. 'Nobble' is a different, informal British verb meaning to tamper with or win over improperly, 'Noblie' is not a word, and 'Nobel' is the surname of Alfred Nobel, after whom the Nobel Prizes are named.","o":["Nobble","Noblie","Noble","Nobel"],"a":[2]},{"id":"c25s2-81","p":"c25s2","n":81,"s":"eng","t":"Spelling","q":"Choose the correctly spelt word for Expression of mild disapproval","w":"'Expostulation' (e-x-p-o-s-t-u-l-a-t-i-o-n) is the correct spelling. It means an expression of mild disapproval or an earnest, reasoned protest; the verb 'expostulate' means to argue with someone to dissuade them. Note the single s in 'st' and the single l in '-ulation'. 'Expossulation' (double s), 'Expostelation' (e in place of u) and 'Expostullation' (double l) are misspellings.","o":["Expostulation","Expossulation","Expostelation","Expostullation"],"a":[0]},{"id":"c25s2-82","p":"c25s2","n":82,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct one-word substitution for: ‘A person who is excessively concerned with minor details’.","w":"A 'pedant' is a person who is excessively concerned with minor details and rules, especially in learning or language; the adjective is 'pedantic'. A 'critic' judges the merits of books, films or works of art, a 'grammarian' is an expert in grammar, and a 'scholar' is a learned person. Only 'pedant' carries the sense of fussy, excessive attention to trivial details.","o":["Critic","Grammarian","Scholar","Pedant"],"a":[3]},{"id":"c25s2-83","p":"c25s2","n":83,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct one-word substitute for: “To leave suddenly and hurriedly”.","w":"'Abscond' means to leave suddenly and hurriedly, usually in secret, often to escape arrest or responsibility, as in 'The cashier absconded with the money.' 'Perambulate' means to walk through a place in a leisurely way, 'circumambulate' means to walk all the way round something such as a shrine, and 'loiter' means to stand or wait around idly. None of these suggests a sudden departure.","o":["Abscond","Perambulate","Circumambulate","Loiter"],"a":[0]},{"id":"c25s2-84","p":"c25s2","n":84,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Fill in the Blanks :\nHad they submitted the proposal earlier, they ______ the funding.","w":"'Had they submitted' is an inverted third conditional (= 'If they had submitted'), which refers to an unreal past situation. The result clause of a third conditional takes would/could/might + have + past participle, so 'they would have received the funding'. 'Would get' belongs to the second conditional, 'had received' cannot stand in the result clause, and 'will have received' (future perfect) does not suit an unreal past.","o":["would get","would have received","had received","will have received"],"a":[1]},{"id":"c25s2-85","p":"c25s2","n":85,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Find the part of the sentence that contains an error:\nThe CEO along with his deputies (1)/ were present during the final negotiations (2)/ with the investors (3)/ and regulators. (4)/","w":"The subject is 'The CEO', which is singular. A phrase introduced by 'along with', 'together with', 'as well as' or 'accompanied by' does not change the number of the subject, so the verb must agree with 'The CEO', not with 'his deputies'. Part (2) should read 'was present during the final negotiations'. The other parts, 'The CEO along with his deputies' and 'with the investors and regulators', are correct.","o":["(1)","(2)","(3)","(4)"],"a":[1]},{"id":"c25s2-86","p":"c25s2","n":86,"s":"eng","t":"Voice & Narration","q":"Change the following from active to passive:\nThe storm damaged many houses.","w":"In the active sentence 'The storm' is the subject, 'damaged' is simple past and 'many houses' is the object. In the passive the object becomes the subject and the simple past takes was/were + past participle, with 'were' for the plural 'houses': 'Many houses were damaged by the storm.' Option 1 (are damaged) is present tense, option 2 (had been damaged) is past perfect and option 4 (have been damaged) is present perfect.","o":["Many houses are damaged by the storm.","Many houses had been damaged by the storm.","Many houses were damaged by the storm.","Many houses have been damaged by the storm."],"a":[2]},{"id":"c25s2-87","p":"c25s2","n":87,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Find the part of the sentence that contains an error:\nIf the allegations were substantiated (1)/ and procedural lapses proven, the committee might have (2)/ had enough reason to initiate an internal probe (3)/ which never occurred. (4)","w":"'Which never occurred' shows the probe never took place, so this is an unreal past (third) conditional: If + had + past participle, with might/would + have + past participle in the result. The key marks part (2), taking 'and procedural lapses proven' as faulty: it should read 'and procedural lapses had been proven' to match 'might have had'. But part (1) 'were substantiated' has the same tense fault ('had been substantiated'), and once it is corrected the shortened 'procedural lapses proven' is acceptable, so part (1) is the stronger answer. (SSC key; some sources differ.)","o":["(1)","(2)","(3)","(4)"],"a":[1]},{"id":"c25s2-88","p":"c25s2","n":88,"s":"eng","t":"Vocabulary","q":"Select the sentence containing the homonym of the highlighted word:\nThe bishop wore a \"mitre\" embroidered with gold thread.","w":"In the given sentence 'mitre' is the tall, pointed headdress worn by bishops. Its homonym (same spelling and sound, different meaning) is the 'mitre' of carpentry and metalwork: a joint made by cutting two pieces at an angle, usually 45°, so that they meet at a right angle, as in a picture frame. Option 1 uses this sense. Options 2, 3 and 4 (the cardinal's mitre, an ancient mitre, a mitre on the altar) all refer to the headdress.","o":["The welder fitted a steel mitre joint at a 45° angle.","The cardinal’s mitre was trimmed in crimson.","The procession displayed an ancient mitre in a glass case.","The children admired the sparkling mitre on the altar."],"a":[0]},{"id":"c25s2-89","p":"c25s2","n":89,"s":"eng","t":"Voice & Narration","q":"Convert the sentence provided below from its passive voice structure to an active voice structure:\nThe findings were interpreted to have been misrepresented by the spokesperson in the official release.","w":"'The spokesperson' is the doer and 'the findings' the receiver of 'misrepresented'. No option keeps 'were interpreted', so judge by the inner clause: the passive perfect infinitive 'to have been misrepresented by the spokesperson' becomes the active 'the spokesperson ... to have misrepresented the findings', giving 'The spokesperson is believed to have misrepresented the findings.' Option 1 says much the same but recasts it as an 'It is believed that' clause, option 2 reverses the roles, and option 4 changes the verb to 'misinterpreted' and the object to 'the release'.","o":["It is believed that the spokesperson misrepresented the findings.","The official release was said to have misrepresented the spokesperson.","The spokesperson is believed to have misrepresented the findings.","It was believed that the spokesperson had misinterpreted the release."],"a":[2]},{"id":"c25s2-90","p":"c25s2","n":90,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Choose the most suitable option to replace the highlighted part of the sentence:\nI \"am liking this movie\" a lot.","w":"'Like' is a stative verb: it expresses a state of mind or feeling rather than an action. Stative verbs such as like, love, hate, know, believe and prefer are normally not used in the continuous tenses, so 'I am liking this movie a lot' should be 'I like this movie a lot' (simple present). 'Have liked' and 'liked' change the time reference to a completed or past experience, and 'am enjoy this movie' is ungrammatical.","o":["have liked","like","liked","am enjoy this movie"],"a":[1]},{"id":"c25s2-91","p":"c25s2","n":91,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn contemporary discourse, “free will” is often celebrated as the cornerstone of individual autonomy and democratic agency. Yet, a deeper examination reveals that this perceived freedom may be more constructed than authentic. Modern society, while outwardly championing liberty, subtly engineers conformity through systems of social conditioning, digital surveillance, and algorithmic manipulation. The choices we make—what to wear, what to consume, even what to believe—are frequently shaped less by volition than by invisible frameworks of control. Consumer behavior is a telling example. Market forces, armed with behavioral data and predictive analytics, sculpt preferences before individuals are even conscious of them. Personalization engines masquerade as facilitators of choice, but in reality, they nudge individuals toward decisions already engineered to optimize corporate profit. Similarly, social media platforms curate information ecosystems that reinforce existing biases, creating cognitive echo chambers that masquerade as informed choice. Even political decisions—arguably the most significant expression of agency—are susceptible to manipulation. Campaign strategies leveraging psychographic profiling can influence voting behavior by exploiting psychological vulnerabilities rather than rational deliberation. The illusion of participation, thus, replaces genuine engagement. Moreover, societal norms, instilled through education, media, and cultural traditions, define the boundaries within which ‘freedom’ operates. A person may “choose” a career path, but that choice is often filtered through expectations shaped by socioeconomic class, geography, and familial pressures. What appears voluntary is often a conditioned response disguised as self-determination. To be clear, this is not an argument for fatalism, but rather a call for awareness. Recognizing the architecture that underpins our choices is the first step toward reclaiming autonomy. True agency, therefore, is not the absence of influence but the conscious interrogation of it. Without such reflection, free will in modern society may remain a comforting mirage rather than an existential reality.\nWhat is the central argument of the passage?","w":"The passage shows how markets, algorithms, social media, campaigns and social norms shape our choices, but says this is 'not an argument for fatalism, but rather a call for awareness'. Its conclusion is that 'True agency ... is not the absence of influence but the conscious interrogation of it', so true freedom requires questioning those influences. Option 1 is never claimed, option 3 contradicts the view that society 'subtly engineers conformity', and option 4 is wrong because market forces are criticised, not praised.","o":["Free will is incompatible with democracy","True freedom requires interrogation of influences","Modern society gives full autonomy to individuals","Autonomy is best achieved through capitalism"],"a":[1]},{"id":"c25s2-92","p":"c25s2","n":92,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn contemporary discourse, “free will” is often celebrated as the cornerstone of individual autonomy and democratic agency. Yet, a deeper examination reveals that this perceived freedom may be more constructed than authentic. Modern society, while outwardly championing liberty, subtly engineers conformity through systems of social conditioning, digital surveillance, and algorithmic manipulation. The choices we make—what to wear, what to consume, even what to believe—are frequently shaped less by volition than by invisible frameworks of control. Consumer behavior is a telling example. Market forces, armed with behavioral data and predictive analytics, sculpt preferences before individuals are even conscious of them. Personalization engines masquerade as facilitators of choice, but in reality, they nudge individuals toward decisions already engineered to optimize corporate profit. Similarly, social media platforms curate information ecosystems that reinforce existing biases, creating cognitive echo chambers that masquerade as informed choice. Even political decisions—arguably the most significant expression of agency—are susceptible to manipulation. Campaign strategies leveraging psychographic profiling can influence voting behavior by exploiting psychological vulnerabilities rather than rational deliberation. The illusion of participation, thus, replaces genuine engagement. Moreover, societal norms, instilled through education, media, and cultural traditions, define the boundaries within which ‘freedom’ operates. A person may “choose” a career path, but that choice is often filtered through expectations shaped by socioeconomic class, geography, and familial pressures. What appears voluntary is often a conditioned response disguised as self-determination. To be clear, this is not an argument for fatalism, but rather a call for awareness. Recognizing the architecture that underpins our choices is the first step toward reclaiming autonomy. True agency, therefore, is not the absence of influence but the conscious interrogation of it. Without such reflection, free will in modern society may remain a comforting mirage rather than an existential reality.\nWhat is meant by \"cognitive echo chambers\"?","w":"The passage says social media platforms 'curate information ecosystems that reinforce existing biases, creating cognitive echo chambers'. An echo chamber is an environment in which a person meets only views that repeat and confirm what he already believes, so the phrase means information environments that reinforce existing beliefs. The passage does not speak of the media echoing public opinion, repetitive political slogans or chatbots mimicking users.","o":["Media echoing public opinions","Repetitive political slogans","Information environments reinforcing existing beliefs","Chatbots mimicking users"],"a":[2]},{"id":"c25s2-93","p":"c25s2","n":93,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn contemporary discourse, “free will” is often celebrated as the cornerstone of individual autonomy and democratic agency. Yet, a deeper examination reveals that this perceived freedom may be more constructed than authentic. Modern society, while outwardly championing liberty, subtly engineers conformity through systems of social conditioning, digital surveillance, and algorithmic manipulation. The choices we make—what to wear, what to consume, even what to believe—are frequently shaped less by volition than by invisible frameworks of control. Consumer behavior is a telling example. Market forces, armed with behavioral data and predictive analytics, sculpt preferences before individuals are even conscious of them. Personalization engines masquerade as facilitators of choice, but in reality, they nudge individuals toward decisions already engineered to optimize corporate profit. Similarly, social media platforms curate information ecosystems that reinforce existing biases, creating cognitive echo chambers that masquerade as informed choice. Even political decisions—arguably the most significant expression of agency—are susceptible to manipulation. Campaign strategies leveraging psychographic profiling can influence voting behavior by exploiting psychological vulnerabilities rather than rational deliberation. The illusion of participation, thus, replaces genuine engagement. Moreover, societal norms, instilled through education, media, and cultural traditions, define the boundaries within which ‘freedom’ operates. A person may “choose” a career path, but that choice is often filtered through expectations shaped by socioeconomic class, geography, and familial pressures. What appears voluntary is often a conditioned response disguised as self-determination. To be clear, this is not an argument for fatalism, but rather a call for awareness. Recognizing the architecture that underpins our choices is the first step toward reclaiming autonomy. True agency, therefore, is not the absence of influence but the conscious interrogation of it. Without such reflection, free will in modern society may remain a comforting mirage rather than an existential reality.\nAccording to the passage, how do personalization algorithms affect consumer choice?","w":"The passage says market forces using behavioural data 'sculpt preferences before individuals are even conscious of them', and that personalization engines 'masquerade as facilitators of choice' while they 'nudge individuals toward decisions already engineered to optimize corporate profit'. So they manipulate preferences subtly. Option 2 is the opposite of the author's view, since 'masquerade' shows the empowerment is only apparent, and market competition and data privacy are not discussed.","o":["They eliminate market competition","They empower user decisions","They manipulate preferences subtly","They increase data privacy"],"a":[2]},{"id":"c25s2-94","p":"c25s2","n":94,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn contemporary discourse, “free will” is often celebrated as the cornerstone of individual autonomy and democratic agency. Yet, a deeper examination reveals that this perceived freedom may be more constructed than authentic. Modern society, while outwardly championing liberty, subtly engineers conformity through systems of social conditioning, digital surveillance, and algorithmic manipulation. The choices we make—what to wear, what to consume, even what to believe—are frequently shaped less by volition than by invisible frameworks of control. Consumer behavior is a telling example. Market forces, armed with behavioral data and predictive analytics, sculpt preferences before individuals are even conscious of them. Personalization engines masquerade as facilitators of choice, but in reality, they nudge individuals toward decisions already engineered to optimize corporate profit. Similarly, social media platforms curate information ecosystems that reinforce existing biases, creating cognitive echo chambers that masquerade as informed choice. Even political decisions—arguably the most significant expression of agency—are susceptible to manipulation. Campaign strategies leveraging psychographic profiling can influence voting behavior by exploiting psychological vulnerabilities rather than rational deliberation. The illusion of participation, thus, replaces genuine engagement. Moreover, societal norms, instilled through education, media, and cultural traditions, define the boundaries within which ‘freedom’ operates. A person may “choose” a career path, but that choice is often filtered through expectations shaped by socioeconomic class, geography, and familial pressures. What appears voluntary is often a conditioned response disguised as self-determination. To be clear, this is not an argument for fatalism, but rather a call for awareness. Recognizing the architecture that underpins our choices is the first step toward reclaiming autonomy. True agency, therefore, is not the absence of influence but the conscious interrogation of it. Without such reflection, free will in modern society may remain a comforting mirage rather than an existential reality.\nWhy does the author mention career choices in the context of free will?","w":"The author says a person may \"choose\" a career path, but the choice is 'filtered through expectations shaped by socioeconomic class, geography, and familial pressures', and adds that what appears voluntary is often 'a conditioned response disguised as self-determination'. The quotation marks around 'choose' signal this irony, so the example illustrates the illusion of self-determination. Options 2 and 4 contradict the passage, which stresses family and class, and option 1 is not argued; education is listed among the conditioning forces.","o":["To show how education leads to autonomy","To highlight the irrelevance of family","To illustrate the illusion of self-determination shaped by societal filters","To argue that class no longer matters"],"a":[2]},{"id":"c25s2-95","p":"c25s2","n":95,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn contemporary discourse, “free will” is often celebrated as the cornerstone of individual autonomy and democratic agency. Yet, a deeper examination reveals that this perceived freedom may be more constructed than authentic. Modern society, while outwardly championing liberty, subtly engineers conformity through systems of social conditioning, digital surveillance, and algorithmic manipulation. The choices we make—what to wear, what to consume, even what to believe—are frequently shaped less by volition than by invisible frameworks of control. Consumer behavior is a telling example. Market forces, armed with behavioral data and predictive analytics, sculpt preferences before individuals are even conscious of them. Personalization engines masquerade as facilitators of choice, but in reality, they nudge individuals toward decisions already engineered to optimize corporate profit. Similarly, social media platforms curate information ecosystems that reinforce existing biases, creating cognitive echo chambers that masquerade as informed choice. Even political decisions—arguably the most significant expression of agency—are susceptible to manipulation. Campaign strategies leveraging psychographic profiling can influence voting behavior by exploiting psychological vulnerabilities rather than rational deliberation. The illusion of participation, thus, replaces genuine engagement. Moreover, societal norms, instilled through education, media, and cultural traditions, define the boundaries within which ‘freedom’ operates. A person may “choose” a career path, but that choice is often filtered through expectations shaped by socioeconomic class, geography, and familial pressures. What appears voluntary is often a conditioned response disguised as self-determination. To be clear, this is not an argument for fatalism, but rather a call for awareness. Recognizing the architecture that underpins our choices is the first step toward reclaiming autonomy. True agency, therefore, is not the absence of influence but the conscious interrogation of it. Without such reflection, free will in modern society may remain a comforting mirage rather than an existential reality.\nWhat tone best describes the author’s perspective?","w":"The author reflects on whether free will is real and critically examines how markets, algorithms, campaigns and social norms shape our choices, so the tone is reflective and critical. It is not fatalistic or passive, because the author says 'this is not an argument for fatalism, but rather a call for awareness'. It is not neutral or historical, since it takes a clear stand on the present, and not optimistic, since free will 'may remain a comforting mirage'.","o":["Fatalistic and passive","Neutral and historical","Reflective and critical","Optimistic and persuasive"],"a":[2]},{"id":"c25s2-96","p":"c25s2","n":96,"s":"eng","t":"Voice & Narration","q":"A sentence is provided in direct speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding indirect speech.\nRita said, “I haven't eaten anything.”","w":"When the reporting verb is in the past tense ('said'), the present perfect of the direct speech shifts back to the past perfect in indirect speech: 'haven't eaten' becomes 'hadn't eaten', and the pronoun 'I' becomes 'she'. Hence: 'Rita said that she hadn't eaten anything.' Option 1 uses the simple past, option 2 keeps the present perfect without the required backshift, and option 4 wrongly changes it to the past continuous.","o":["Rita said that she didn’t eat anything.","Rita said that she hasn’t eaten anything.","Rita said that she hadn't eaten anything.","Rita said that she wasn't eating anything."],"a":[2]},{"id":"c25s2-97","p":"c25s2","n":97,"s":"eng","t":"Voice & Narration","q":"A sentence is provided in direct speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding indirect speech.\nThey said, “We shall overcome this challenge together.”","w":"With a past reporting verb ('said'), 'shall' expressing a future intention changes to 'would' in indirect speech, the pronoun 'we' becomes 'they', and 'this' becomes 'that'. So: 'They said they would overcome that challenge together.' Option 1 keeps 'will' and option 4 keeps 'shall' without the backshift, while option 2 uses 'should', which suggests obligation, and also leaves 'this' unchanged.","o":["They said they will overcome that challenge together.","They said they should overcome this challenge together.","They said they would overcome that challenge together.","They said they shall overcome that challenge together."],"a":[2]},{"id":"c25s2-98","p":"c25s2","n":98,"s":"eng","t":"Voice & Narration","q":"A sentence is provided in indirect speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding direct speech.\nThe lawyer said that had the evidence not been tampered with, the verdict could have been different.","w":"The reported clause is an inverted third conditional: 'had the evidence not been tampered with, the verdict could have been different'. Unreal past conditionals keep the same tense in direct and indirect speech, so the direct form simply puts the same words in quotation marks. Option 1 drops 'been' (making the evidence the doer) and changes the result clause, option 2 uses 'were' instead of 'had been', and option 4 drops 'been ... with' and uses 'may differ'.","o":["“If the evidence had not tampered with, the verdict could change,” said the lawyer.","“If the evidence were not tampered with, the verdict could have changed,” the lawyer said.","“Had the evidence not been tampered with, the verdict could have been different,” said the lawyer.","“Had not the evidence tampered, the verdict may differ,” said he."],"a":[2]},{"id":"c25s2-99","p":"c25s2","n":99,"s":"eng","t":"Sentence Arrangement","q":"Rearrange the following sentences to form a coherent paragraph:\n1. Artificial intelligence is a field of computer science focused on creating machines that can simulate human cognitive functions.\n2. This process is used in various applications, from self-driving cars to medical diagnosis systems.\n3. This is typically achieved by training machine learning models on vast datasets, allowing them to identify patterns and make predictions.\n4. Through this training, an AI system learns to perform specific tasks, such as recognizing objects in images or translating text.","w":"Sentence 1 defines artificial intelligence and introduces the topic, so it comes first. Sentence 3, 'This is typically achieved by training machine learning models', explains how machines simulate cognition. Sentence 4 begins 'Through this training', referring back to sentence 3, and names the tasks AI learns. Sentence 2, 'This process is used in various applications', gives real-world uses and concludes. Order: 1, 3, 4, 2. Option 4 is wrong because 'this training' needs sentence 3 before it.","o":["2, 3, 4, 1","3, 1, 2, 4","1, 3, 4, 2","1, 4, 3, 2"],"a":[2]},{"id":"c25s2-100","p":"c25s2","n":100,"s":"eng","t":"Sentence Arrangement","q":"Rearrange the following sentences in correct order to make a logical passage.\n1. Therefore, protecting them is a shared responsibility.\n2. Coral reefs are vital marine ecosystems.\n3. They provide habitats for countless species and protect coastlines.\n4. Pollution and climate change pose severe threats to their survival.","w":"Sentence 2 introduces the topic, coral reefs as vital marine ecosystems. Sentence 3 explains why they are vital, with 'They' referring to coral reefs. Sentence 4 then states the threats from pollution and climate change. Sentence 1, beginning with 'Therefore', draws the conclusion that protecting them is a shared responsibility, so it must come last. The logical order is 2-3-4-1.","o":["2-1-3-4","2-4-1-3","3-4-2-1","2-3-4-1"],"a":[3]},{"id":"c25s3-1","p":"c25s3","n":1,"s":"rea","t":"Series","q":"Select the letter-cluster from among the given options that can replace the question mark (?) in the following series.\nD I N, I N S, N S X, S X C, ?","w":"Within each cluster the letters move +5: D (4) → I (9) → N (14). Each new cluster drops the first letter of the previous one and adds a letter 5 steps ahead: DIN, INS, NSX, SXC. So the next cluster starts with X, C and adds H: C (3) + 5 = H (8), just as X (24) + 5 wraps round to C (3). The answer is XCH. LKA, JNA and GVA break the +5 pattern.","o":["LKA","JNA","GVA","XCH"],"a":[3],"qt":"दिए गए विकल्पों में से उस अक्षर-समूह का चयन करें जो निम्नलिखित श्रृंखला में प्रश्न चिह्न (?) को प्रतिस्थापित कर सके।\nD I N, I N S, N S X, S X C, ?","ot":["LKA","JNA","GVA","XCH"],"wt":"प्रत्येक अक्षर-समूह में अक्षर 5-5 स्थान आगे बढ़ते हैं: D (4) → I (9) → N (14)। हर नया समूह पिछले समूह का पहला अक्षर हटाकर 5 स्थान आगे का एक नया अक्षर जोड़ता है: DIN, INS, NSX, SXC। अतः अगला समूह X, C से शुरू होगा और उसमें H जुड़ेगा: C (3) + 5 = H (8), ठीक वैसे ही जैसे X (24) + 5 वर्णमाला का चक्कर पूरा कर C (3) पर आता है। उत्तर XCH है। LKA, JNA और GVA +5 के पैटर्न को तोड़ते हैं।"},{"id":"c25s3-2","p":"c25s3","n":2,"s":"rea","t":"Mathematical Operations","q":"If 6 @ 2 = 9, 15 @ 3 = 125, then 8 @ 4 = ?","w":"The rule is a @ b = (a ÷ b) raised to the power b. Check: 6 @ 2 = (6 ÷ 2)² = 3² = 9 and 15 @ 3 = (15 ÷ 3)³ = 5³ = 125. So 8 @ 4 = (8 ÷ 4)⁴ = 2⁴ = 16. Options 4 and 8 are 2² and 2³, which use the wrong power, and 10 fits no consistent rule.","o":["4","8","16","10"],"a":[2],"qt":"अगर 6 @ 2 = 9, 15 @ 3 = 125, तो 8 @ 4 = ?","ot":["4","8","16","10"],"wt":"नियम है: a @ b = (a ÷ b) की घात b। जाँच: 6 @ 2 = (6 ÷ 2)² = 3² = 9 और 15 @ 3 = (15 ÷ 3)³ = 5³ = 125। अतः 8 @ 4 = (8 ÷ 4)⁴ = 2⁴ = 16। विकल्प 4 और 8 क्रमशः 2² और 2³ हैं, जिनमें गलत घात ली गई है, और 10 किसी सुसंगत नियम में नहीं बैठता।"},{"id":"c25s3-3","p":"c25s3","n":3,"s":"rea","t":"Mathematical Operations","q":"Choose the correct signs to swap.\n40 ÷ 8 + 10 − 5 × 2 = 5","w":"The printed equation is already true (5 + 10 − 10 = 5), so the question really asks which swap keeps it true. By BODMAS, swapping + and − gives 40 ÷ 8 − 10 + 5 × 2 = 5 − 10 + 10 = 5. The other swaps give 327.5 (÷ and ×: 40 × 8 + 10 − 5 ÷ 2), 30.8 (÷ and +: 40 + 8 ÷ 10 − 5 × 2) and 53 (− and ×: 40 ÷ 8 + 10 × 5 − 2). So + and − is the only valid swap.","o":["÷ and ×","+ and −","÷ and +","− and ×"],"a":[1],"qt":"अदला-बदली के लिए सही चिह्न चुनें।\n40 ÷ 8 + 10 − 5 × 2 = 5","ot":["÷ और ×","+ और −","÷ और +","− और ×"],"wt":"दिया गया समीकरण पहले से ही सही है (5 + 10 − 10 = 5), इसलिए प्रश्न वास्तव में यह पूछता है कि कौन-सी अदला-बदली इसे सही बनाए रखती है। BODMAS से, + और − बदलने पर 40 ÷ 8 − 10 + 5 × 2 = 5 − 10 + 10 = 5 मिलता है। अन्य अदला-बदली से 327.5 (÷ और ×: 40 × 8 + 10 − 5 ÷ 2), 30.8 (÷ और +: 40 + 8 ÷ 10 − 5 × 2) और 53 (− और ×: 40 ÷ 8 + 10 × 5 − 2) मिलते हैं। अतः केवल + और − की अदला-बदली मान्य है।"},{"id":"c25s3-4","p":"c25s3","n":4,"s":"rea","t":"Blood Relations & Directions","q":"A is the brother of B. B is the sister of C. C is the brother of D. How is B related to D?","w":"B is the sister of C, so B is female. C is the brother of D, so C and D are siblings, which makes A, B, C and D children of the same parents. Hence B is D's sister. \"Can't say\" is tempting because D's gender is not given, but it does not matter: the question asks how B is related to D, and B, being female, is D's sister either way. Aunt and niece would need a different generation.","o":["Sister","Aunt","Niece","Can’t say"],"a":[0],"qt":"A, B का भाई है। B, C की बहन है। C, D का भाई है। B का D से क्या संबंध है?","ot":["बहन","चाची","भतीजी","कह नहीं सकतें"],"wt":"B, C की बहन है, अतः B स्त्री है। C, D का भाई है, अतः C और D भाई-बहन हैं; इस प्रकार A, B, C और D एक ही माता-पिता की संतान हैं। अतः B, D की बहन है। \"कह नहीं सकते\" आकर्षक लगता है क्योंकि D का लिंग नहीं दिया गया है, पर इससे कोई अंतर नहीं पड़ता: प्रश्न B का D से संबंध पूछता है, और B स्त्री होने के कारण हर स्थिति में D की बहन है। चाची और भतीजी के लिए अलग पीढ़ी चाहिए।"},{"id":"c25s3-5","p":"c25s3","n":5,"s":"rea","t":"Analogy & Classification","q":"Solve:\nFD : KH :: QM : ?","w":"Use letter positions (A = 1 … Z = 26). In FD : KH, F (6) + 5 = K (11) and D (4) + 4 = H (8). Apply the same steps to QM: Q (17) + 5 = V (22) and M (13) + 4 = Q (17). So QM : VQ. VP has the right first letter but adds only 3 to M, while WT and UW do not follow either step.","o":["VP","WT","VQ","UW"],"a":[2],"qt":"हल करें :\nFD : KH :: QM : ?","ot":["VP","WT","VQ","UW"],"wt":"अक्षरों के स्थान लें (A = 1 … Z = 26)। FD : KH में F (6) + 5 = K (11) और D (4) + 4 = H (8)। यही चरण QM पर लगाएँ: Q (17) + 5 = V (22) और M (13) + 4 = Q (17)। अतः QM : VQ। VP का पहला अक्षर सही है, पर उसमें M में केवल 3 जोड़ा गया है, जबकि WT और UW किसी भी चरण का पालन नहीं करते।"},{"id":"c25s3-6","p":"c25s3","n":6,"s":"rea","t":"Series","q":"What comes next: 13, 16, 21, 30, 45, ?","w":"Take differences: 16 − 13 = 3, 21 − 16 = 5, 30 − 21 = 9, 45 − 30 = 15. The differences themselves grow by 2, 4, 6, so the next increase is 8 and the next difference is 15 + 8 = 23. The next term is 45 + 23 = 68. 67 or 66 would need a difference of 22 or 21, which breaks the 2, 4, 6, 8 pattern of second differences.","o":["70","66","67","68"],"a":[3],"qt":"इसके बाद क्या आएगा: 13, 16, 21, 30, 45, ?","ot":["70","66","67","68"],"wt":"अंतर लें: 16 − 13 = 3, 21 − 16 = 5, 30 − 21 = 9, 45 − 30 = 15। ये अंतर स्वयं 2, 4, 6 से बढ़ते हैं, अतः अगली वृद्धि 8 होगी और अगला अंतर 15 + 8 = 23 होगा। अगला पद 45 + 23 = 68 है। 67 या 66 के लिए अंतर 22 या 21 चाहिए, जो दूसरे अंतरों के 2, 4, 6, 8 वाले पैटर्न को तोड़ता है।"},{"id":"c25s3-7","p":"c25s3","n":7,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement: Rising noise pollution in urban areas is affecting children’s concentration.\nConclusion I: Urban children can’t study well.\nConclusion II: Controlling noise pollution may improve children’s concentration.","w":"Conclusion I is too sweeping: the statement says noise is affecting concentration, not that urban children cannot study well at all, so I does not follow. Since rising noise is harming concentration, it is reasonable to infer that controlling noise pollution may improve it; the cautious word \"may\" makes II a valid conclusion. Hence only II follows.","o":["Only I follows","Only II follows","Both follow","Neither follows"],"a":[1],"qt":"निम्नलिखित कथन को ध्यान से पढ़ें और निष्कर्ष की पहचान करें।\nकथन: शहरी क्षेत्रों में बढ़ता ध्वनि प्रदूषण बच्चों की एकाग्रता को प्रभावित कर रहा है।\nनिष्कर्ष I: शहरी बच्चे अच्छी तरह से पढ़ाई नहीं कर सकते।\nनिष्कर्ष II: ध्वनि प्रदूषण को नियंत्रित करने से बच्चों की एकाग्रता में सुधार हो सकता है।","ot":["केवल I अनुसरण करता है","केवल II अनुसरण करता है","दोनों अनुसरण करते हैं","कोई भी अनुसरण नहीं करता है"],"wt":"निष्कर्ष I बहुत व्यापक है: कथन कहता है कि शोर एकाग्रता को प्रभावित कर रहा है, यह नहीं कि शहरी बच्चे बिल्कुल अच्छी तरह पढ़ाई नहीं कर सकते, अतः I अनुसरण नहीं करता। चूँकि बढ़ता शोर एकाग्रता को नुकसान पहुँचा रहा है, यह मानना तर्कसंगत है कि ध्वनि प्रदूषण को नियंत्रित करने से उसमें सुधार हो सकता है; सावधानी भरा शब्द \"हो सकता है\" II को मान्य निष्कर्ष बनाता है। अतः केवल II अनुसरण करता है।"},{"id":"c25s3-8","p":"c25s3","n":8,"s":"rea","t":"Analogy & Classification","q":"Identify the odd one out:","w":"121, 131 and 444 are palindromic numbers: each reads the same forwards and backwards. 544 read backwards is 445, so it is not a palindrome and is the odd one out. Other properties do not group the numbers consistently (121 is a perfect square, 131 is prime, 444 is even), so the palindrome property is the intended rule.","o":["121","131","444","544"],"a":[3],"qt":"इनमें से विषम को पहचानें:","ot":["121","131","444","544"],"wt":"121, 131 और 444 पैलिंड्रोम संख्याएँ हैं: प्रत्येक संख्या आगे से और पीछे से एक जैसी पढ़ी जाती है। 544 को उल्टा पढ़ने पर 445 बनता है, अतः यह पैलिंड्रोम नहीं है और विषम है। अन्य गुण इन संख्याओं को सुसंगत रूप से समूहित नहीं करते (121 पूर्ण वर्ग है, 131 अभाज्य है, 444 सम है), इसलिए पैलिंड्रोम ही अभिप्रेत नियम है।"},{"id":"c25s3-9","p":"c25s3","n":9,"s":"rea","t":"Syllogism & Statements","q":"Instruction: Identify the assumptions that must hold for the statement to be valid, then choose the correct option.\nStatement: The introduction of Artificial Intelligence into healthcare systems can enhance diagnostic accuracy, but its widespread implementation may lead to ethical dilemmas in patient care.\nAssumptions:\nI. AI can improve healthcare diagnostics.\nII. The ethical concerns surrounding AI in healthcare are significant.\nIII. AI will eventually replace human healthcare professionals.","w":"An assumption is what the statement takes for granted. Saying AI \"can enhance diagnostic accuracy\" presumes that AI can improve healthcare diagnostics, so I is implicit. Warning that its use \"may lead to ethical dilemmas\" presumes the ethical concerns are real and significant enough to mention, so II is implicit. The statement nowhere suggests that AI will replace human healthcare professionals, so III is not implicit. Hence only I and II are implicit.","o":["Only I and II are implicit","Only II and III are implicit","All I, II and III are implicit","Only I is implicit"],"a":[0],"qt":"निर्देश: कथन को मान्य बनाने के लिए आवश्यक मान्यताओं की पहचान करें, फिर सही विकल्प चुनें।\nकथन: स्वास्थ्य सेवा प्रणालियों में आर्टिफिशियल इंटेलिजेंस की शुरूआत निदान सटीकता को बढ़ा सकती है, लेकिन इसके व्यापक कार्यान्वयन से रोगी देखभाल में नैतिक दुविधाएँ पैदा हो सकती हैं।\nमान्यताएँ:\nI. AI स्वास्थ्य सेवा निदान में सुधार कर सकता है।\nII. स्वास्थ्य सेवा में AI से जुड़ी नैतिक चिंताएँ महत्वपूर्ण हैं।\nIII. AI अंततः मानव स्वास्थ्य सेवा पेशेवरों की जगह ले लेगा।","ot":["केवल I और II निहित हैं","केवल II और III निहित हैं","सभी I, II और III निहित हैं","केवल I निहित है"],"wt":"मान्यता वह है जिसे कथन पहले से मानकर चलता है। यह कहना कि AI \"निदान सटीकता को बढ़ा सकती है\", यह मानता है कि AI स्वास्थ्य सेवा निदान में सुधार कर सकता है, अतः I निहित है। यह चेतावनी कि इसका व्यापक उपयोग \"नैतिक दुविधाएँ पैदा कर सकता है\", यह मानती है कि नैतिक चिंताएँ वास्तविक हैं और उल्लेख करने योग्य महत्वपूर्ण हैं, अतः II निहित है। कथन कहीं नहीं कहता कि AI मानव स्वास्थ्य सेवा पेशेवरों की जगह ले लेगा, अतः III निहित नहीं है। अतः केवल I और II निहित हैं।"},{"id":"c25s3-10","p":"c25s3","n":10,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement: All metro stations are under CCTV surveillance.\nConclusions:\nI. Activities at metro stations are being monitored.\nII. No criminal activity can happen in metro stations.","w":"CCTV surveillance means the stations are being watched, so activities at metro stations are being monitored and conclusion I follows. Surveillance can deter or record crime but cannot make it impossible, so the absolute claim in conclusion II that no criminal activity can happen does not follow. Hence only conclusion I follows.","o":["Only Conclusion I follows","Only Conclusion II follows","Both I and II follow","Neither I nor II follows"],"a":[0],"qt":"निम्नलिखित कथन को ध्यानपूर्वक पढ़ें और निष्कर्ष निकालें।\nकथन: सभी मेट्रो स्टेशन सीसीटीवी निगरानी में हैं।\nनिष्कर्ष:\nI. मेट्रो स्टेशनों पर गतिविधियों पर नज़र रखी जा रही है।\nII. मेट्रो स्टेशनों पर कोई आपराधिक गतिविधि नहीं हो सकती।","ot":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"wt":"सीसीटीवी निगरानी का अर्थ है कि स्टेशनों पर नज़र रखी जा रही है, अतः मेट्रो स्टेशनों पर गतिविधियों की निगरानी हो रही है और निष्कर्ष I अनुसरण करता है। निगरानी अपराध को रोक सकती है या रिकॉर्ड कर सकती है, पर उसे असंभव नहीं बना सकती, अतः निष्कर्ष II का यह निरपेक्ष दावा कि कोई आपराधिक गतिविधि हो ही नहीं सकती, अनुसरण नहीं करता। अतः केवल निष्कर्ष I अनुसरण करता है।"},{"id":"c25s3-11","p":"c25s3","n":11,"s":"rea","t":"Arrangement & Puzzles","q":"Direction: Study the information carefully and answer the given questions.\nEight People Tina, Raj, Dia, Viraj, Soma, Meena, Neha and Ria are living in an eight-storey building, but not necessarily in the same order. The ground floor is numbered 1 and the floor above it is numbered 2, and so on, until the topmost floor is numbered 8. Dia lives on the lowermost floor. Only three people live between Dia and Ria. Tina lives on the 4th floor. Only two people live between Tina and Raj. Only five people live between Viraj and Soma. Neha lives on an odd numbered floor. Only one person lives between Meena and Viraj.\nWho lives three floors below the one who lives immediate below Raj?","w":"Dia is on floor 1, so Ria (three people between) is on 5. Tina is on 4, so Raj (two between) is on 7, since 1 is taken. Viraj and Soma have five people between them, so they take floors 2 and 8. Neha and Meena take floors 3 and 6; Neha is on an odd floor, so Neha is on 3 and Meena on 6. One person between Meena and Viraj puts Viraj on 8 and Soma on 2. Immediately below Raj (7) is Meena (6), and three floors below 6 is floor 3: Neha.","o":["Neha","Tina","Dia","Raj"],"a":[0],"qt":"निर्देश: दी गई जानकारी का ध्यानपूर्वक अध्ययन कीजिए और दिए गए प्रश्नों के उत्तर दीजिए।\nआठ व्यक्ति टीना, राज, दीया, विराज, सोमा, मीना, नेहा और रिया एक आठ मंजिला इमारत में रहते हैं, लेकिन जरूरी नहीं कि इसी क्रम में हों। भूतल को 1 से क्रमांकित किया गया है और उसके ऊपर की मंजिल को 2 से क्रमांकित किया गया है, और इसी प्रकार सबसे ऊपरी मंजिल को 8 से क्रमांकित किया जाता है। दीया सबसे निचली मंजिल पर रहती है। दीया और रिया के बीच केवल तीन व्यक्ति रहते हैं। टीना चौथी मंजिल पर रहती है। टीना और राज के बीच केवल दो व्यक्ति रहते हैं। विराज और सोमा के बीच केवल पाँच व्यक्ति रहते हैं। नेहा विषम क्रमांकित मंजिल पर रहती है। मीना और विराज के बीच केवल एक व्यक्ति रहता है।\nराज के ठीक नीचे रहने वाले व्यक्ति से तीन मंजिल नीचे कौन रहता है?","ot":["नेहा","टीना","दीया","राज"],"wt":"दीया मंजिल 1 पर है, अतः रिया (बीच में तीन व्यक्ति) मंजिल 5 पर है। टीना 4 पर है, अतः राज (बीच में दो व्यक्ति) 7 पर है, क्योंकि 1 पहले से भरी है। विराज और सोमा के बीच पाँच व्यक्ति हैं, अतः वे मंजिल 2 और 8 पर हैं। नेहा और मीना मंजिल 3 और 6 पर हैं; नेहा विषम मंजिल पर है, अतः नेहा 3 पर और मीना 6 पर है। मीना और विराज के बीच एक व्यक्ति होने से विराज 8 पर और सोमा 2 पर है। राज (7) के ठीक नीचे मीना (6) है, और 6 से तीन मंजिल नीचे मंजिल 3 है: नेहा।"},{"id":"c25s3-12","p":"c25s3","n":12,"s":"rea","t":"Syllogism & Statements","q":"Read the following statement carefully and identify the conclusion that follows.\nStatement:\nNo painters are athletes. Some artists are athletes. All artists are painters.\nConclusions:\nI. Some painters are athletes.\nII. Some athletes are not painters.","w":"The statements clash: artists who are athletes are also painters (all artists are painters), which contradicts \"No painters are athletes\". SSC's key takes \"No painters are athletes\" as given. Conclusion I (Some painters are athletes) directly contradicts it, so I does not follow. It also means no athlete is a painter, and athletes exist (some artists are athletes), so some athletes are not painters: II follows. Combining the other two statements would instead give I, which is why \"Both follow\" is also argued. (SSC key; some sources differ.)","o":["Only I follows","Only II follows","Both I and II follow","Neither I nor II follows"],"a":[1],"qt":"निम्नलिखित कथन को ध्यानपूर्वक पढ़ें और निष्कर्ष निकालें।\nकथन:\nकोई भी चित्रकार एथलीट नहीं है। कुछ कलाकार एथलीट हैं। सभी कलाकार चित्रकार हैं।\nनिष्कर्ष:\nI. कुछ चित्रकार एथलीट हैं।\nII. कुछ एथलीट चित्रकार नहीं हैं।","ot":["केवल I अनुसरण करता है","केवल II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"wt":"कथन आपस में टकराते हैं: जो कलाकार एथलीट हैं वे चित्रकार भी हैं (सभी कलाकार चित्रकार हैं), जो \"कोई भी चित्रकार एथलीट नहीं है\" का खंडन करता है। SSC की कुंजी \"कोई भी चित्रकार एथलीट नहीं है\" को आधार मानती है। निष्कर्ष I (कुछ चित्रकार एथलीट हैं) इसका सीधा खंडन है, अतः I अनुसरण नहीं करता। इसका यह भी अर्थ है कि कोई एथलीट चित्रकार नहीं है, और एथलीट मौजूद हैं (कुछ कलाकार एथलीट हैं), अतः कुछ एथलीट चित्रकार नहीं हैं: II अनुसरण करता है। शेष दो कथनों को मिलाने पर I निकलता है, इसीलिए \"दोनों अनुसरण करते हैं\" का भी तर्क दिया जाता है। (SSC कुंजी; कुछ स्रोत भिन्न हैं।)"},{"id":"c25s3-13","p":"c25s3","n":13,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out:\nPacific, Atlantic, Indian, Arctic, Mediterranean","w":"Pacific, Atlantic, Indian and Arctic are oceans; with the Southern Ocean they make up the world's five oceans. The Mediterranean is a sea, almost enclosed by Europe, Africa and Asia and joined to the Atlantic Ocean through the Strait of Gibraltar. So Mediterranean is the odd one out. The Indian Ocean appears in the list but not among the options.","o":["Pacific","Atlantic","Mediterranean","Arctic"],"a":[2],"qt":"इनमें से विषम चुनें:\nप्रशांत, अटलांटिक, हिंद, आर्कटिक, भूमध्य सागर","ot":["प्रशांत","अटलांटिक","भूमध्य सागर","आर्कटिक"],"wt":"प्रशांत, अटलांटिक, हिंद और आर्कटिक महासागर हैं; दक्षिणी महासागर के साथ ये विश्व के पाँच महासागर बनाते हैं। भूमध्य सागर एक सागर है, जो यूरोप, अफ्रीका और एशिया से लगभग घिरा हुआ है और जिब्राल्टर जलडमरूमध्य द्वारा अटलांटिक महासागर से जुड़ा है। अतः भूमध्य सागर विषम है। सूची में हिंद महासागर है, पर वह विकल्पों में नहीं है।"},{"id":"c25s3-14","p":"c25s3","n":14,"s":"rea","t":"Coding-Decoding","q":"If CLOUD is coded as BKNTC, how is RAINY written?","w":"Each letter of CLOUD moves one step back: C − 1 = B, L − 1 = K, O − 1 = N, U − 1 = T, D − 1 = C, giving BKNTC. Apply the same rule to RAINY: R − 1 = Q, A − 1 = Z (wrapping round the alphabet), I − 1 = H, N − 1 = M, Y − 1 = X, giving QZHMX. The other options go wrong at the fourth or fifth letter (L instead of M, or W or V instead of X).","o":["QZHMX","QZHLX","QZHLW","QZHMV"],"a":[0],"qt":"अगर CLOUD को BKNTC के रूप में कोड किया जाता है, तो RAINY को कैसे लिखा जाएगा?","ot":["QZHMX","QZHLX","QZHLW","QZHMV"],"wt":"CLOUD का प्रत्येक अक्षर एक स्थान पीछे जाता है: C − 1 = B, L − 1 = K, O − 1 = N, U − 1 = T, D − 1 = C, जिससे BKNTC बनता है। यही नियम RAINY पर लगाएँ: R − 1 = Q, A − 1 = Z (वर्णमाला में पीछे घूमकर), I − 1 = H, N − 1 = M, Y − 1 = X, जिससे QZHMX बनता है। अन्य विकल्प चौथे या पाँचवें अक्षर पर गलत हैं (M के स्थान पर L, या X के स्थान पर W या V)।"},{"id":"c25s3-15","p":"c25s3","n":15,"s":"rea","t":"Analogy & Classification","q":"In each of the following questions, a specific alphabetical pattern is applied to the first set of letters to form the second. Apply the same logic to find the missing term that relates to the third set in the same way. Choose the correct option from the given alternatives.\nAEFJ : KOPT :: ? : QUVZ","w":"In AEFJ : KOPT each letter moves 10 steps forward: A (1) + 10 = K (11), E (5) + 10 = O (15), F (6) + 10 = P (16), J (10) + 10 = T (20). The missing term must give QUVZ after adding 10, so go 10 steps back: Q (17) → G (7), U (21) → K (11), V (22) → L (12), Z (26) → P (16). The answer is GKLP. GLKP has K and L swapped, so it is a trap.","o":["HKQL","GLKP","GKLP","HLKP"],"a":[2],"qt":"निम्नलिखित प्रत्येक प्रश्न में, पहले अक्षरों के समूह को दूसरे समूह में बदलने के लिए एक विशिष्ट वर्णमाला क्रम लागू किया गया है। इसी तर्क का प्रयोग करके तीसरे समूह से संबंधित लुप्त पद ज्ञात कीजिए। दिए गए विकल्पों में से सही विकल्प चुनिए।\nAEFJ : KOPT :: ? : QUVZ","ot":["HKQL","GLKP","GKLP","HLKP"],"wt":"AEFJ : KOPT में प्रत्येक अक्षर 10 स्थान आगे जाता है: A (1) + 10 = K (11), E (5) + 10 = O (15), F (6) + 10 = P (16), J (10) + 10 = T (20)। लुप्त पद में 10 जोड़ने पर QUVZ बनना चाहिए, अतः 10 स्थान पीछे जाएँ: Q (17) → G (7), U (21) → K (11), V (22) → L (12), Z (26) → P (16)। उत्तर GKLP है। GLKP में K और L की जगह आपस में बदली हुई है, अतः यह भ्रमित करने वाला विकल्प है।"},{"id":"c25s3-16","p":"c25s3","n":16,"s":"rea","t":"Analogy & Classification","q":"TEACHER is to CLASSROOM as SURGEON is to:","w":"The relation is person : place of work. A teacher works in a classroom, and a surgeon works in an operation theatre (OT), so OT completes the analogy. A patient is the person a surgeon treats, a scalpel is the surgeon's tool and an operation is the surgeon's work; none of these is the place where the surgeon works, so they break the relation.","o":["PATIENT","SCALPEL","OPERATION","OT (Operation Theatre)"],"a":[3],"qt":"जिस प्रकार TEACHER को CLASSROOM लिखा जाता है, उसी प्रकार SURGEON को क्या लिखा जाएगा?","ot":["PATIENT","SCALPEL","OPERATION","OT (Operation Theatre)"],"wt":"संबंध व्यक्ति : कार्यस्थल का है। शिक्षक (TEACHER) कक्षा (CLASSROOM) में काम करता है, और सर्जन (SURGEON) ऑपरेशन थिएटर (OT) में काम करता है, अतः OT सादृश्य को पूरा करता है। PATIENT (रोगी) वह व्यक्ति है जिसका सर्जन उपचार करता है, SCALPEL सर्जन का औज़ार है और OPERATION सर्जन का कार्य है; इनमें से कोई भी सर्जन का कार्यस्थल नहीं है, अतः ये संबंध को तोड़ते हैं।"},{"id":"c25s3-17","p":"c25s3","n":17,"s":"rea","t":"Series","q":"What is the sum of the first 10 terms of the series?\n1, 3, 5, 7, ...?","w":"The series 1, 3, 5, 7, … is the sequence of odd numbers, an AP with first term 1 and common difference 2. The sum of the first n odd numbers is n², so the sum of the first 10 terms is 10² = 100. Check with the AP formula: S = n/2 × [2a + (n − 1)d] = 10/2 × [2 + 18] = 5 × 20 = 100 (the 10th term is 19).","o":["90","100","110","120"],"a":[1],"qt":"निम्नलिखित श्रृंखला के प्रथम 10 पदों का योग क्या है?\n1, 3, 5, 7, ...?","ot":["90","100","110","120"],"wt":"श्रृंखला 1, 3, 5, 7, … विषम संख्याओं का अनुक्रम है, जो प्रथम पद 1 और सार्व अंतर 2 वाली समांतर श्रेढ़ी (AP) है। प्रथम n विषम संख्याओं का योग n² होता है, अतः प्रथम 10 पदों का योग 10² = 100 है। AP सूत्र से जाँच: S = n/2 × [2a + (n − 1)d] = 10/2 × [2 + 18] = 5 × 20 = 100 (10वाँ पद 19 है)।"},{"id":"c25s3-18","p":"c25s3","n":18,"s":"rea","t":"Series","q":"What comes next?\nBYD, DWF, FUH, ?","w":"Track each position separately. First letters: B, D, F move two steps forward, so the next is H. Second letters: Y, W, U move two steps backward, so the next is S. Third letters: D, F, H move two steps forward, so the next is J. The next cluster is HSJ. HQJ goes wrong on the second letter (Q instead of S), while IQK and JQL break the pattern in every position.","o":["HSJ","IQK","HQJ","JQL"],"a":[0],"qt":"निम्नलिखित श्रृंखला में अगले स्थान पर कौन सा विकल्प आएगा?\nBYD, DWF, FUH, ?","ot":["HSJ","IQK","HQJ","JQL"],"wt":"प्रत्येक स्थान को अलग-अलग देखें। पहले अक्षर: B, D, F दो-दो स्थान आगे बढ़ते हैं, अतः अगला H है। दूसरे अक्षर: Y, W, U दो-दो स्थान पीछे जाते हैं, अतः अगला S है। तीसरे अक्षर: D, F, H दो-दो स्थान आगे बढ़ते हैं, अतः अगला J है। अगला अक्षर-समूह HSJ है। HQJ दूसरे अक्षर पर गलत है (S के स्थान पर Q), जबकि IQK और JQL हर स्थान पर पैटर्न तोड़ते हैं।"},{"id":"c25s3-19","p":"c25s3","n":19,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out from the given alternatives:","w":"Troposphere, stratosphere and mesosphere are layers of the Earth's atmosphere (from the ground up: troposphere, stratosphere, mesosphere, thermosphere, exosphere). The hydrosphere is not an atmospheric layer; it is all the water on Earth, including oceans, rivers, lakes, ice and groundwater. So hydrosphere is the odd one out. All four end in \"-sphere\", so the suffix alone does not decide the answer.","o":["Troposphere","Stratosphere","Hydrosphere","Mesosphere"],"a":[2],"qt":"दिए गए विकल्पों में से विषम विकल्प को चुनिए:","ot":["क्षोभ मंडल","स्ट्रैटोस्फियर","हीड्रास्फीयर","मीसोस्फीयर"],"wt":"क्षोभ मंडल (ट्रोपोस्फियर), समताप मंडल (स्ट्रैटोस्फियर) और मध्य मंडल (मीसोस्फियर) पृथ्वी के वायुमंडल की परतें हैं (नीचे से ऊपर: क्षोभ मंडल, समताप मंडल, मध्य मंडल, ताप मंडल, बहिर्मंडल)। जलमंडल (हाइड्रोस्फियर) वायुमंडल की परत नहीं है; यह पृथ्वी का समस्त जल है, जिसमें महासागर, नदियाँ, झीलें, बर्फ और भूजल शामिल हैं। अतः जलमंडल विषम है। चारों के अंग्रेज़ी नाम \"-sphere\" पर समाप्त होते हैं, इसलिए केवल प्रत्यय से उत्तर तय नहीं होता।"},{"id":"c25s3-20","p":"c25s3","n":20,"s":"rea","t":"Analogy & Classification","q":"Find the odd one out from the given alternatives:","w":"Retina, cornea and iris are parts of the human eye: the cornea is the transparent front layer, the iris is the coloured part that controls the size of the pupil, and the retina is the light-sensitive layer at the back. The femur is the thigh bone, the longest bone in the human body, and is not part of the eye. So femur is the odd one out.","o":["Retina","Cornea","Iris","Femur"],"a":[3],"qt":"दिए गए विकल्पों में से विषम विकल्प को चुनिए:","ot":["रेटिना","कॉर्निया","आइरिस","जांध की हड्डी"],"wt":"रेटिना, कॉर्निया और आइरिस मानव नेत्र के भाग हैं: कॉर्निया आगे की पारदर्शी परत है, आइरिस रंगीन भाग है जो पुतली का आकार नियंत्रित करता है, और रेटिना पीछे की प्रकाश-संवेदी परत है। फीमर जाँघ की हड्डी है, जो मानव शरीर की सबसे लंबी हड्डी है, और नेत्र का भाग नहीं है। अतः फीमर (जाँघ की हड्डी) विषम है।"},{"id":"c25s3-21","p":"c25s3","n":21,"s":"rea","t":"Coding-Decoding","q":"In a certain code, NIGHT is written as OHJIS How will LIGHT be written?","w":"Compare NIGHT with OHJIS letter by letter: N + 1 = O, I − 1 = H, G + 3 = J, H + 1 = I, T − 1 = S. Apply the same steps to LIGHT: L + 1 = M, I − 1 = H, G + 3 = J, H + 1 = I, T − 1 = S, giving MHJIS. Quicker: NIGHT and LIGHT share IGHT, so the code must end in HJIS and only the first letter changes (L + 1 = M). KJHIS, LIHIS and MIHIS alter the common part.","o":["MHJIS","KJHIS","LIHIS","MIHIS"],"a":[0],"qt":"एक निश्चित कोड में, NIGHT को OHJIS लिखा जाता है। LIGHT को कैसे लिखा जाएगा?","ot":["MHJIS","KJHIS","LIHIS","MIHIS"],"wt":"NIGHT और OHJIS की अक्षर-दर-अक्षर तुलना करें: N + 1 = O, I − 1 = H, G + 3 = J, H + 1 = I, T − 1 = S। यही चरण LIGHT पर लगाएँ: L + 1 = M, I − 1 = H, G + 3 = J, H + 1 = I, T − 1 = S, जिससे MHJIS बनता है। शीघ्र विधि: NIGHT और LIGHT में IGHT समान है, अतः कोड HJIS पर समाप्त होगा और केवल पहला अक्षर बदलेगा (L + 1 = M)। KJHIS, LIHIS और MIHIS समान भाग को बदल देते हैं।"},{"id":"c25s3-22","p":"c25s3","n":22,"s":"rea","t":"Blood Relations & Directions","q":"Pointing to a woman, John says, “She is the wife of my uncle’s only son.” How is the woman related to John?","w":"John's uncle's only son is John's cousin, and the woman is that cousin's wife. Strictly, English would call her a cousin-in-law, but in Indian usage a cousin's wife is called sister-in-law (bhabhi, the word the Hindi option uses), and it is the only option that fits. \"Cousin\" describes her husband, not her; sister and niece are blood relations that do not fit a cousin's wife. Hence the woman is John's sister-in-law.","o":["Sister","Cousin","Sister-in-law","Niece"],"a":[2],"qt":"एक महिला की ओर इशारा करते हुए जॉन कहता है, “वह मेरे चाचा के इकलौते बेटे की पत्नी है।” वह महिला जॉन से किस प्रकार संबंधित है?","ot":["बहन","चचेरा","भाभी","भतीजी"],"wt":"जॉन के चाचा का इकलौता बेटा जॉन का चचेरा भाई है, और वह महिला उस चचेरे भाई की पत्नी है। अंग्रेज़ी में सख्ती से उसे cousin-in-law कहा जाएगा, पर भारतीय प्रयोग में चचेरे भाई की पत्नी को भाभी (sister-in-law) कहा जाता है, और विकल्पों में यही एकमात्र उपयुक्त उत्तर है। \"चचेरा\" उसके पति का संबंध बताता है, उसका नहीं; बहन और भतीजी रक्त-संबंध हैं जो चचेरे भाई की पत्नी पर लागू नहीं होते। अतः वह महिला जॉन की भाभी है।"},{"id":"c25s3-23","p":"c25s3","n":23,"s":"rea","t":"Mathematical Operations","q":"If × = +, + = −, − = ×; then 4 × 5 + 2 − 3 = ?","w":"Replace the signs as given: × becomes +, + becomes − and − becomes ×. So 4 × 5 + 2 − 3 becomes 4 + 5 − 2 × 3. By BODMAS, multiply first: 2 × 3 = 6, then 4 + 5 − 6 = 3. Option 7 comes from 4 + 5 − 2, which ignores the multiplication by 3; 35 and 29 do not come from the correct substitution.","o":["3","7","35","29"],"a":[0],"qt":"यदि × = +, + = −, − = ×; तो 4 × 5 + 2 − 3 = ?","ot":["3","7","35","29"],"wt":"दिए गए चिह्न बदलें: × के स्थान पर +, + के स्थान पर − और − के स्थान पर ×। इस प्रकार 4 × 5 + 2 − 3 बन जाता है 4 + 5 − 2 × 3। BODMAS के अनुसार पहले गुणा करें: 2 × 3 = 6, फिर 4 + 5 − 6 = 3। विकल्प 7, 4 + 5 − 2 से आता है, जिसमें 3 से गुणा छोड़ दिया गया है; 35 और 29 सही प्रतिस्थापन से नहीं आते।"},{"id":"c25s3-24","p":"c25s3","n":24,"s":"rea","t":"Miscellaneous Reasoning","q":"If the sum of 13 and 39 is multiplied by 2, what is the result?","w":"The wording \"the sum … is multiplied by 2\" means (13 + 39) × 2. First add: 13 + 39 = 52. Then multiply: 52 × 2 = 104. Check with the distributive law: 13 × 2 + 39 × 2 = 26 + 78 = 104, the same result. 100, 106 and 110 are close figures that come from slips in the addition or multiplication.","o":["100","104","106","110"],"a":[1],"qt":"यदि 13 और 39 के योग को 2 से गुणा किया जाए तो परिणाम क्या होगा?","ot":["100","104","106","110"],"wt":"\"योग को 2 से गुणा किया जाए\" का अर्थ है (13 + 39) × 2। पहले जोड़ें: 13 + 39 = 52। फिर गुणा करें: 52 × 2 = 104। वितरण नियम से जाँच: 13 × 2 + 39 × 2 = 26 + 78 = 104, वही परिणाम। 100, 106 और 110 निकट की संख्याएँ हैं जो जोड़ या गुणा में चूक से आती हैं।"},{"id":"c25s3-25","p":"c25s3","n":25,"s":"rea","t":"Series","q":"The series given below contains a sequence of numbers. Accordingly identify the incorrect combination. 25, 32, 46, 67, 97","w":"Look at the differences: 32 − 25 = 7, 46 − 32 = 14, 67 − 46 = 21, 97 − 67 = 30. The first three are consecutive multiples of 7 (7, 14, 21), so the next difference should be 28 and the last term 67 + 28 = 95. Hence 97 is the incorrect term. 32, 46 and 67 all fit the +7, +14, +21 pattern, so they are correct.","o":["32","46","97","67"],"a":[2],"qt":"नीचे दी गई श्रृंखला में संख्याओं का एक अनुक्रम है। तदनुसार गलत संयोजन की पहचान कीजिए।\n25, 32, 46, 67, 97","ot":["32","46","97","67"],"wt":"अंतर देखें: 32 − 25 = 7, 46 − 32 = 14, 67 − 46 = 21, 97 − 67 = 30। पहले तीन अंतर 7 के क्रमागत गुणज हैं (7, 14, 21), अतः अगला अंतर 28 होना चाहिए और अंतिम पद 67 + 28 = 95 होना चाहिए। अतः 97 गलत पद है। 32, 46 और 67 सभी +7, +14, +21 के पैटर्न में बैठते हैं, अतः वे सही हैं।"},{"id":"c25s3-26","p":"c25s3","n":26,"s":"sci","t":"Science & Technology","q":"What is the contribution of Vikram Sarabhai Space Centre (VSSC) to India’s space program?","w":"The Vikram Sarabhai Space Centre at Thiruvananthapuram, Kerala, is ISRO's lead centre for launch vehicle technology. It designs and develops India's rockets, from SLV-3 and ASLV to PSLV, GSLV and LVM3, as well as sounding rockets. It grew out of the Thumba Equatorial Rocket Launching Station (1963) and was named after Vikram Sarabhai after his death in 1971. Launches take place from the Satish Dhawan Space Centre, Sriharikota; astronaut training is the job of the Human Space Flight Centre, and satellite tracking and control that of ISTRAC and the Master Control Facility.","o":["Launch site for ISRO missions","Designs and builds launch vehicles","Trains Indian astronauts","Controls ISRO satellites"],"a":[1],"qt":"भारत के अंतरिक्ष कार्यक्रम में विक्रम साराभाई अंतरिक्ष केंद्र (वीएसएससी) का क्या योगदान है?","ot":["इसरो मिशन के लिए प्रक्षेपण स्थल","प्रक्षेपण वाहनों का डिजाइन और निर्माण","भारतीय अंतरिक्ष यात्रियों को प्रशिक्षित करता है","इसरो उपग्रहों को नियंत्रित करता है"],"wt":"विक्रम साराभाई अंतरिक्ष केंद्र, तिरुवनंतपुरम (केरल), प्रक्षेपण यान प्रौद्योगिकी के लिए इसरो का प्रमुख केंद्र है। यह SLV-3 और ASLV से लेकर PSLV, GSLV और LVM3 तक भारत के रॉकेटों तथा साउंडिंग रॉकेटों का डिज़ाइन और विकास करता है। इसकी शुरुआत थुंबा इक्वेटोरियल रॉकेट लॉन्चिंग स्टेशन (1963) से हुई और 1971 में विक्रम साराभाई के निधन के बाद इसे उनका नाम दिया गया। प्रक्षेपण सतीश धवन अंतरिक्ष केंद्र, श्रीहरिकोटा से होते हैं; अंतरिक्ष यात्रियों का प्रशिक्षण मानव अंतरिक्ष उड़ान केंद्र का काम है, और उपग्रहों की ट्रैकिंग व नियंत्रण इस्ट्रैक (ISTRAC) तथा मास्टर कंट्रोल फैसिलिटी का।"},{"id":"c25s3-27","p":"c25s3","n":27,"s":"eco","t":"Schemes & Welfare","q":"The \"Atal Innovation Mission (AIM)\" is a flagship initiative to promote innovation and entrepreneurship in India. Which of the following is a key component or program under AIM?","w":"The Atal Innovation Mission was set up by NITI Aayog in 2016. Its flagship programme is the Atal Tinkering Labs, workspaces in schools where students of classes 6 to 12 build projects with tools such as 3D printers, robotics and electronics kits. AIM also runs Atal Incubation Centres, Atal Community Innovation Centres, the Atal New India Challenge and Mentor India. The Startup India Seed Fund Scheme belongs to DPIIT (Ministry of Commerce and Industry), while Skill India and PMKVY come under the Ministry of Skill Development and Entrepreneurship.","o":["Skill India Centers","Startup India Seed Fund Scheme","Atal Tinkering Labs (ATLs)","Pradhan Mantri Kaushal Vikas Yojana (PMKVY)"],"a":[2],"qt":"\"अटल इनोवेशन मिशन (एआईएम)\" भारत में नवाचार और उद्यमिता को बढ़ावा देने के लिए एक प्रमुख पहल है। निम्नलिखित में से कौन सा एआईएम के तहत एक प्रमुख घटक या कार्यक्रम है?","ot":["कौशल भारत केंद्र","स्टार्टअप इंडिया सीड फंड योजना","अटल टिंकरिंग लैब्स (एटीएल)","प्रधानमंत्री कौशल विकास योजना (पीएमकेवीवाई)"],"wt":"अटल इनोवेशन मिशन की स्थापना नीति आयोग ने 2016 में की थी। इसका प्रमुख कार्यक्रम अटल टिंकरिंग लैब्स है, यानी स्कूलों में ऐसी कार्यशालाएँ जहाँ कक्षा 6 से 12 के विद्यार्थी 3D प्रिंटर, रोबोटिक्स और इलेक्ट्रॉनिक्स किट जैसे उपकरणों से प्रोजेक्ट बनाते हैं। AIM अटल इनक्यूबेशन सेंटर, अटल कम्युनिटी इनोवेशन सेंटर, अटल न्यू इंडिया चैलेंज और मेंटर इंडिया भी चलाता है। स्टार्टअप इंडिया सीड फंड योजना DPIIT (वाणिज्य और उद्योग मंत्रालय) की है, जबकि स्किल इंडिया और PMKVY कौशल विकास और उद्यमिता मंत्रालय के अंतर्गत आते हैं।"},{"id":"c25s3-28","p":"c25s3","n":28,"s":"ih","t":"Modern India","q":"The integration of the princely states into the Indian Union after 1947 involved a complex interplay of political negotiation, popular movements, and, at times, coercion. Which of the following factors most significantly undermined the initial aspirations of some princely rulers to maintain independent or autonomous status?","w":"When British paramountcy lapsed in 1947, rulers such as those of Travancore, Hyderabad, Bhopal and Jammu and Kashmir hoped to stay independent. But the people of most states wanted to join India, and the States' People's movements and Praja Mandals, linked to the All India States People's Conference (1927), organised agitations, as in Travancore, Junagadh, Hyderabad and the Orissa states. Together with the diplomacy of Sardar Patel and V.P. Menon through the Instrument of Accession, this popular pressure made independence unworkable. Britain did not back independent states, and Pakistan was not militarily dominant.","o":["The overwhelming military superiority of the newly formed Pakistani state, compelling the rulers to seek protection within India.","The consistent and unwavering support provided by the British government to the princely states seeking independence.","The strong undercurrent of popular will within the princely states favoring accession to India, often expressed through organized movements and protests.","The economic prosperity and stability offered by remaining independent, making integration into the financially strained Indian Union unattractive."],"a":[2],"qt":"1947 के बाद रियासतों के भारतीय संघ में एकीकरण में राजनीतिक बातचीत, लोकप्रिय आंदोलनों और कई बार जबरदस्ती की जटिल अंतर्क्रिया शामिल थी। निम्नलिखित में से किस कारक ने कुछ रियासतों की स्वतंत्र या स्वायत्त स्थिति बनाए रखने की शुरुआती आकांक्षाओं को सबसे महत्वपूर्ण रूप से कमजोर किया?","ot":["नवगठित पाकिस्तानी राज्य की अत्यधिक सैन्य श्रेष्ठता के कारण शासकों को भारत में सुरक्षा लेने के लिए बाध्य होना पड़ा।","स्वतंत्रता चाहने वाली रियासतों को ब्रिटिश सरकार द्वारा प्रदान किया गया निरंतर और अटूट समर्थन।","रियासतों के भीतर भारत में विलय के पक्ष में लोकप्रिय इच्छा की प्रबल भावना, अक्सर संगठित आंदोलनों और विरोध प्रदर्शनों के माध्यम से व्यक्त की जाती थी।","स्वतंत्र रहने से प्राप्त होने वाली आर्थिक समृद्धि और स्थिरता, वित्तीय रूप से तनावग्रस्त भारतीय संघ में एकीकरण को अनाकर्षक बनाती है।"],"wt":"1947 में ब्रिटिश सर्वोच्चता (पैरामाउंटसी) समाप्त होने पर त्रावणकोर, हैदराबाद, भोपाल और जम्मू-कश्मीर जैसे राज्यों के शासक स्वतंत्र रहने की आशा कर रहे थे। लेकिन अधिकांश रियासतों की जनता भारत में शामिल होना चाहती थी, और अखिल भारतीय देशी राज्य प्रजा परिषद (1927) से जुड़े प्रजा मंडलों और रियासती जन आंदोलनों ने त्रावणकोर, जूनागढ़, हैदराबाद और ओडिशा की रियासतों जैसे स्थानों में आंदोलन किए। सरदार पटेल और वी.पी. मेनन की विलय-पत्र (इंस्ट्रूमेंट ऑफ एक्सेशन) वाली कूटनीति के साथ मिलकर इस जन-दबाव ने स्वतंत्र रहना असंभव बना दिया। ब्रिटेन ने स्वतंत्र रियासतों का समर्थन नहीं किया, और पाकिस्तान सैन्य रूप से प्रबल नहीं था।"},{"id":"c25s3-29","p":"c25s3","n":29,"s":"pol","t":"Judiciary & Constitutional Bodies","q":"The Bharatiya Nyaya Sanhita (BNS) was introduced as part of:","w":"The Bharatiya Nyaya Sanhita, 2023 replaced the colonial-era Indian Penal Code, 1860. It was enacted together with the Bharatiya Nagarik Suraksha Sanhita (replacing the CrPC, 1973) and the Bharatiya Sakshya Adhiniyam (replacing the Indian Evidence Act, 1872); all three received assent in December 2023 and came into force on 1 July 2024. The government presented them as decolonising and modernising criminal justice, with a focus on justice rather than punishment, new offences such as organised crime and terrorism, and community service as a punishment.","o":["The effort to codify personal laws.","The effort to modernize and decolonize India’s criminal justice system.","The new taxation policy.","A trade agreement."],"a":[1],"qt":"भारतीय न्याय संहिता (बीएनएस) को इसके भाग के रूप में पेश किया गया था:","ot":["व्यक्तिगत कानूनों को संहिताबद्ध करने का प्रयास।","भारत की आपराधिक न्याय प्रणाली को आधुनिक बनाने और उपनिवेशवाद मुक्त करने का प्रयास।","नई कराधान नीति।","एक व्यापार समझौता।"],"wt":"भारतीय न्याय संहिता, 2023 ने औपनिवेशिक काल की भारतीय दंड संहिता, 1860 का स्थान लिया। इसे भारतीय नागरिक सुरक्षा संहिता (दंड प्रक्रिया संहिता, 1973 के स्थान पर) और भारतीय साक्ष्य अधिनियम, 2023 (इंडियन एविडेंस एक्ट, 1872 के स्थान पर) के साथ बनाया गया; तीनों को दिसंबर 2023 में स्वीकृति मिली और ये 1 जुलाई 2024 से लागू हुए। सरकार ने इन्हें आपराधिक न्याय प्रणाली को उपनिवेशवाद से मुक्त और आधुनिक बनाने वाला बताया, जिनमें दंड के बजाय न्याय पर बल, संगठित अपराध और आतंकवाद जैसे नए अपराध, और दंड के रूप में सामुदायिक सेवा शामिल हैं।"},{"id":"c25s3-30","p":"c25s3","n":30,"s":"geo","t":"Indian Geography","q":"Digboi, Moran, Sivasagar, and Naharkatiya oil fields are located in which of the following regions of India?","w":"All four oil fields are in Upper Assam in North-Eastern India. NCERT notes that Assam is the oldest oil-producing state of India, with Digboi, Naharkatiya and Moran-Hugrijan as its important fields; Sivasagar district has fields such as Rudrasagar and Lakwa. Oil was struck at Digboi in 1889, and the Digboi refinery (1901) is among the oldest working refineries in the world. The western offshore and Gujarat fields, such as Mumbai High and Ankleshwar, form a different group, so Western Coastal Plains is a trap.","o":["Aravalli and Delhi Ridge","Deccan Plateau","North-Eastern India","Western Coastal Plains"],"a":[2],"qt":"डिगबोई, मोरन, शिवसागर और नहरकटिया तेल क्षेत्र भारत के निम्नलिखित में से किस क्षेत्र में स्थित हैं?","ot":["अरावली और दिल्ली रिज","दक्कन का पठार","पूर्वोत्तर भारत","पश्चिमी तटीय मैदान"],"wt":"चारों तेल क्षेत्र पूर्वोत्तर भारत में ऊपरी असम में हैं। NCERT के अनुसार असम भारत का सबसे पुराना तेल उत्पादक राज्य है, और डिगबोई, नहरकटिया तथा मोरन-हुगरीजान इसके प्रमुख तेल क्षेत्र हैं; शिवसागर ज़िले में रुद्रसागर और लकवा जैसे क्षेत्र हैं। डिगबोई में 1889 में तेल मिला था, और डिगबोई रिफ़ाइनरी (1901) दुनिया की सबसे पुरानी चालू रिफ़ाइनरियों में से एक है। मुंबई हाई और अंकलेश्वर जैसे पश्चिमी अपतटीय और गुजरात के क्षेत्र एक अलग समूह हैं, इसलिए पश्चिमी तटीय मैदान एक भ्रामक विकल्प है।"},{"id":"c25s3-31","p":"c25s3","n":31,"s":"cur","t":"Static GK & Culture","q":"The term 'svaravalis' refers to what in the context of Indian classical music?","w":"Svaravali (svara + avali, 'a row of notes'), also called sarali varisai, is the first set of exercises taught in Carnatic music. Organised by Purandara Dasa and sung in raga Mayamalavagowla, these exercises are melodic patterns of the seven svaras of the scale (sa ri ga ma pa dha ni), sung up and down in three speeds to train the voice and pitch. They are not a separate raga; ornamentation of a raga is called gamaka, and a rhythmic cycle is a tala.","o":["A specific type of raga","A melody composed using the seven notes of the scale","Ornamentation and embellishment of a raga","A rhythmic cycle used in carnatic music"],"a":[1],"qt":"भारतीय शास्त्रीय संगीत के संदर्भ में 'स्वरावली' शब्द का क्या अर्थ है?","ot":["राग का एक विशिष्ट प्रकार","स्केल के सात स्वरों का उपयोग करके रचित एक राग","राग का अलंकरण और ठाठ","कर्नाटक संगीत में प्रयुक्त एक लयबद्ध चक्र"],"wt":"स्वरावली (स्वर + आवली, यानी 'स्वरों की पंक्ति'), जिसे सरली वरिसै भी कहते हैं, कर्नाटक संगीत में सिखाए जाने वाले अभ्यासों का पहला समूह है। पुरंदर दास द्वारा व्यवस्थित और राग मायामालवगौल में गाए जाने वाले ये अभ्यास सप्तक के सात स्वरों (स रि ग म प ध नि) के मधुर क्रम हैं, जिन्हें आवाज़ और सुर साधने के लिए तीन गतियों में आरोह-अवरोह में गाया जाता है। ये कोई अलग राग नहीं हैं; राग के अलंकरण को गमक कहते हैं, और लयबद्ध चक्र ताल कहलाता है।"},{"id":"c25s3-32","p":"c25s3","n":32,"s":"geo","t":"Indian Geography","q":"Consider the following physiographic features.\n1. Tors\n2. Spurs\n3. Block Mountains\nWhich of the feature/features given above is/are found in the peninsular plateau of India?","w":"The Peninsular plateau is an old, stable tableland of crystalline, igneous and metamorphic rocks that has gone through repeated phases of uplift and submergence with crustal faulting and fracturing. NCERT (India: Physical Environment) lists its typical relief features as tors, block mountains, rift valleys, spurs, bare rocky structures, series of hummocky hills and wall-like quartzite dykes that offer natural sites for water storage. So all three features are found there; the Satpura range, flanked by the Narmada and Tapi rift valleys, is an example of a block mountain.","o":["1 and 3 only","3 only","2 and 3 only","1, 2, and 3"],"a":[3],"qt":"निम्नलिखित भौतिक विशेषताओं पर विचार करें।\n1. टोर\n2. स्पर्स\n3. ब्लॉक पर्वत\nउपर्युक्त विशेषता/विशेषताओं में से कौन सी/कौन सी विशेषता भारत के प्रायद्वीपीय पठार में पाई जाती है/हैं?","ot":["केवल 1 और 3","केवल 3","केवल 2 और 3","1, 2, और 3"],"wt":"प्रायद्वीपीय पठार क्रिस्टलीय, आग्नेय और कायांतरित चट्टानों से बना एक प्राचीन, स्थिर पठार है, जिसमें भूपर्पटी के भ्रंशन और विभंजन के साथ बार-बार उत्थान और निमज्जन हुआ है। NCERT (भारत: भौतिक पर्यावरण) इसकी विशिष्ट उच्चावच आकृतियों में टोर, ब्लॉक पर्वत, भ्रंश घाटियाँ, स्पर, नग्न चट्टानी संरचनाएँ, टेकरीनुमा पहाड़ियों की श्रृंखला और जल संग्रहण के प्राकृतिक स्थल देने वाली दीवारनुमा क्वार्टज़ाइट डाइक गिनाती है। अतः तीनों आकृतियाँ यहाँ पाई जाती हैं; नर्मदा और तापी की भ्रंश घाटियों के बीच स्थित सतपुड़ा श्रेणी ब्लॉक पर्वत का उदाहरण है।"},{"id":"c25s3-33","p":"c25s3","n":33,"s":"ih","t":"Art & Culture","q":"Which of the following building materials were primarily used in constructing Purana Qila?","w":"Purana Qila in Delhi stands on the site of Humayun's city Dinpanah (begun 1533) and was largely completed by Sher Shah Suri in the 1540s. Its double-storeyed gateways, the Bara Darwaza, Humayun Darwaza and Talaqi Darwaza, are of red sandstone decorated with white and coloured marble inlay and blue tiles. The Qila-i-Kuhna Mosque (1541), built by Sher Shah, is of red sandstone with marble decoration, and the octagonal Sher Mandal is also of red sandstone. So sandstone and marble are its characteristic materials; granite, concrete and terracotta do not fit.","o":["Granite and lime plaster","Concrete and red bricks","Sandstone and marble","Wood and terracotta"],"a":[2],"qt":"पुराना किला के निर्माण में मुख्य रूप से निम्नलिखित में से किस निर्माण सामग्री का उपयोग किया गया था?","ot":["ग्रेनाइट और चूने का प्लास्टर","कंक्रीट और लाल ईंटें","बलुआ पत्थर और संगमरमर","लकड़ी और टेराकोटा"],"wt":"दिल्ली का पुराना किला हुमायूँ के नगर दीनपनाह (1533 में आरंभ) के स्थल पर स्थित है और इसे मुख्यतः शेरशाह सूरी ने 1540 के दशक में पूरा कराया। इसके दोमंज़िला द्वार, बड़ा दरवाज़ा, हुमायूँ दरवाज़ा और तलाकी दरवाज़ा, लाल बलुआ पत्थर के हैं, जिन पर सफ़ेद और रंगीन संगमरमर की जड़ाई और नीली टाइलें हैं। शेरशाह द्वारा बनवाई गई किला-ए-कुहना मस्जिद (1541) लाल बलुआ पत्थर की है जिसमें संगमरमर की सजावट है, और अष्टकोणीय शेर मंडल भी लाल बलुआ पत्थर का है। अतः बलुआ पत्थर और संगमरमर इसकी विशिष्ट निर्माण सामग्री हैं; ग्रेनाइट, कंक्रीट और टेराकोटा उपयुक्त नहीं हैं।"},{"id":"c25s3-34","p":"c25s3","n":34,"s":"cur","t":"Static GK & Culture","q":"During the Solung festival celebrated by the Adi tribe of Arunachal Pradesh, which traditional drink is shared to promote social bonding?","w":"Solung is the main festival of the Adi people of Arunachal Pradesh, celebrated around 1 September, mainly as an agricultural festival. According to the Government of India's festival portal, people give meat and apong (rice beer) to neighbours and relatives, which strengthens family and social ties; prayers and animal sacrifices are offered to the deities, followed by folk dances, archery and tug-of-war. Thukpa is a noodle soup, chhang is a barley or millet beer of Ladakh, Sikkim and the Himalaya, and soma is the Vedic ritual drink.","o":["Soma","Apong","Thukpa","Chhang"],"a":[1],"qt":"अरुणाचल प्रदेश की आदि जनजाति द्वारा मनाए जाने वाले सोलुंग त्योहार के दौरान सामाजिक बंधन को बढ़ावा देने के लिए कौन सा पारंपरिक पेय साझा किया जाता है?","ot":["सोम","अपोंग","थुकपा","छांग"],"wt":"सोलुंग अरुणाचल प्रदेश की आदि जनजाति का प्रमुख त्योहार है, जो लगभग 1 सितंबर को मुख्यतः कृषि उत्सव के रूप में मनाया जाता है। भारत सरकार के उत्सव पोर्टल के अनुसार लोग पड़ोसियों और संबंधियों को मांस और अपोंग (चावल की बीयर) देते हैं, जिससे पारिवारिक और सामाजिक संबंध मज़बूत होते हैं; देवताओं की प्रार्थना और पशुबलि के बाद लोकनृत्य, तीरंदाज़ी और रस्साकशी होती है। थुकपा नूडल सूप है, छांग लद्दाख, सिक्किम और हिमालयी क्षेत्र की जौ या बाजरे की बीयर है, और सोम वैदिक अनुष्ठानों का पेय था।"},{"id":"c25s3-35","p":"c25s3","n":35,"s":"ih","t":"Ancient India","q":"The drainage system at Mohenjodaro was notable because each house was connected to:","w":"Harappan cities had carefully planned drainage. As NCERT explains, streets were laid out on a grid with their drains planned first, and every house had one wall along a street so that domestic waste water could flow out into the street drains. Bathrooms paved with bricks sloped towards these drains. The street drains were built of brick and covered with bricks or stone slabs, with sumps and removable covers at intervals for cleaning. Ernest Mackay called it the most complete ancient drainage system yet discovered.","o":["An underground water tank","A central pillar for support","A covered street drain","A rooftop reservoir"],"a":[2],"qt":"मोहनजोदड़ो की जल निकासी प्रणाली उल्लेखनीय थी क्योंकि प्रत्येक घर निम्नलिखित से जुड़ा हुआ था:","ot":["एक भूमिगत पानी की टंकी","समर्थन के लिए एक केंद्रीय स्तंभ","एक ढकी हुई सड़क नाली","छत पर जलाशय"],"wt":"हड़प्पाई नगरों में जल निकासी की सुनियोजित व्यवस्था थी। NCERT के अनुसार सड़कें ग्रिड पद्धति में बनाई गईं और उनकी नालियाँ पहले नियोजित की गईं; हर घर की कम से कम एक दीवार सड़क से लगी होती थी ताकि घर का गंदा पानी सड़क की नालियों में बह सके। ईंटों से बने स्नानघरों का ढलान इन्हीं नालियों की ओर होता था। सड़क की नालियाँ ईंटों से बनी थीं और ईंटों या पत्थर की पट्टियों से ढकी रहती थीं, तथा सफ़ाई के लिए बीच-बीच में हौदियाँ (सम्प) और हटाए जा सकने वाले ढक्कन होते थे। अर्नेस्ट मैके ने इसे अब तक खोजी गई सबसे पूर्ण प्राचीन जल निकासी प्रणाली कहा।"},{"id":"c25s3-36","p":"c25s3","n":36,"s":"cur","t":"Sports","q":"Which of the following statements is correct regarding the Golden Raid and card system in Kabaddi?","w":"A knockout kabaddi match that ends level is decided first by five raids for each team, made by five different raiders. If the score is still tied after these 5–5 raids, a fresh toss is taken; the toss winner gets the Golden Raid, and only if it fails to score does the other team get one, so no team gets two. Under the card system, a green card is a warning, a yellow card means a 2-minute suspension, and a red card means suspension for the rest of the match. So only statement 3 is correct.","o":["A team is allowed two Golden Raids before the result is decided.","A Green Card leads to a 2-minute suspension from the game.","A fresh toss is taken if the match is tied even after 5–5 raids.","A Red Card results in a warning with no match suspension."],"a":[2],"qt":"कबड्डी में गोल्डन रेड और कार्ड प्रणाली के संबंध में निम्नलिखित में से कौन सा कथन सही है?","ot":["परिणाम तय होने से पहले एक टीम को दो गोल्डन रेड की अनुमति होती है।","ग्रीन कार्ड मिलने पर खिलाड़ी को खेल से 2 मिनट के लिए निलंबित कर दिया जाता है।","यदि 5-5 रेड के बाद भी मैच बराबर रहता है तो पुनः टॉस लिया जाता है।","रेड कार्ड के परिणामस्वरूप चेतावनी दी जाती है, मैच पर कोई प्रतिबंध नहीं लगाया जाता।"],"wt":"बराबरी पर समाप्त हुए नॉकआउट कबड्डी मैच का फ़ैसला पहले दोनों टीमों को पाँच-पाँच रेड देकर किया जाता है, जो पाँच अलग-अलग रेडर करते हैं। यदि इन 5-5 रेड के बाद भी स्कोर बराबर रहे, तो पुनः टॉस होता है; टॉस जीतने वाली टीम को गोल्डन रेड मिलती है, और उसके अंक न ले पाने पर ही दूसरी टीम को गोल्डन रेड मिलती है, इसलिए किसी टीम को दो गोल्डन रेड नहीं मिलतीं। कार्ड प्रणाली में ग्रीन कार्ड चेतावनी है, येलो कार्ड का अर्थ 2 मिनट का निलंबन है, और रेड कार्ड का अर्थ शेष मैच के लिए निलंबन है। अतः केवल कथन 3 सही है।"},{"id":"c25s3-37","p":"c25s3","n":37,"s":"ih","t":"Medieval India","q":"What was a major challenge for agriculture in the Chola kingdom apart from rocky land?","w":"The Chola heartland was the Kaveri delta, but much of the surrounding region was dry and rocky, so farming depended on artificial watering. NCERT (Our Pasts II) explains that forests had to be cleared and land levelled, embankments built in the delta to prevent floods and canals dug to carry water to the fields. As crops often had to be watered artificially, wells were dug and huge tanks were built to collect rainwater, and village assemblies (sabhas) had committees to look after irrigation works. So the supply of irrigation water was the main challenge.","o":["Lack of seeds","Lack of labour","Irrigation water","Pest infestation"],"a":[2],"qt":"चट्टानी भूमि के अलावा चोल साम्राज्य में कृषि के लिए प्रमुख चुनौती क्या थी?","ot":["बीजों की कमी","श्रमिक अभाव","सिंचाई जल","कीट संक्रमण"],"wt":"चोल राज्य का केंद्र कावेरी डेल्टा था, पर आसपास का बड़ा क्षेत्र शुष्क और चट्टानी था, इसलिए खेती कृत्रिम सिंचाई पर निर्भर थी। NCERT (हमारे अतीत II) बताती है कि जंगल साफ़ करने पड़े और ज़मीन समतल करनी पड़ी, डेल्टा में बाढ़ रोकने के लिए तटबंध बनाए गए और खेतों तक पानी ले जाने के लिए नहरें खोदी गईं। चूँकि फ़सलों को प्रायः कृत्रिम रूप से सींचना पड़ता था, इसलिए कुएँ खोदे गए और वर्षा जल इकट्ठा करने के लिए विशाल तालाब बनाए गए, तथा ग्राम सभाओं (सभा) में सिंचाई कार्यों की देखरेख के लिए समितियाँ होती थीं। अतः सिंचाई जल की आपूर्ति ही मुख्य चुनौती थी।"},{"id":"c25s3-38","p":"c25s3","n":38,"s":"cur","t":"Sports","q":"Consider the following statements about recent National Basketball Championships:\n1) Tamil Nadu won the 74th Senior Men’s title; Punjab and Indian Railways were runner-up and second runner-up.\n2) Rajasthan won the 39th Youth Boys, and Karnataka won the Youth Girls tournament.\nWhich of the statements is/are correct?","w":"Both statements are correct. At the 74th Senior National Basketball Championship in Bhavnagar, Gujarat (January 2025), Tamil Nadu beat Punjab 80–56 in the men's final, and Indian Railways finished third; the Railways women won their title by beating Kerala. At the 39th Youth National Basketball Championship in Kolkata (December 2024), Rajasthan won the boys' title by beating Karnataka 85–67, and the Karnataka girls beat Tamil Nadu 61–54 in their final.","o":["Only 1 is Correct","Only 2 is Correct","1 and 2 are Correct","Neither 1 nor 2 is Correct"],"a":[2],"qt":"हाल ही में आयोजित राष्ट्रीय बास्केटबॉल चैंपियनशिप के बारे में निम्नलिखित कथनों पर विचार करें:\n1) तमिलनाडु ने 74वां सीनियर पुरुष खिताब जीता; पंजाब और भारतीय रेलवे उपविजेता और दूसरे उपविजेता रहे।\n2) राजस्थान ने 39वां युवा लड़कों का खिताब जीता और कर्नाटक ने युवा लड़कियों का टूर्नामेंट जीता।\nकौन सा कथन सही है/हैं?","ot":["केवल 1 सही है","केवल 2 सही है","1 और 2 सही हैं","न तो 1 और न ही 2 सही है"],"wt":"दोनों कथन सही हैं। भावनगर, गुजरात में हुई 74वीं सीनियर राष्ट्रीय बास्केटबॉल चैंपियनशिप (जनवरी 2025) के पुरुष फ़ाइनल में तमिलनाडु ने पंजाब को 80–56 से हराया और भारतीय रेलवे तीसरे स्थान पर रही; महिला वर्ग में रेलवे ने केरल को हराकर खिताब जीता। कोलकाता में हुई 39वीं युवा राष्ट्रीय बास्केटबॉल चैंपियनशिप (दिसंबर 2024) में राजस्थान ने कर्नाटक को 85–67 से हराकर लड़कों का खिताब जीता, और कर्नाटक की लड़कियों ने फ़ाइनल में तमिलनाडु को 61–54 से हराया।"},{"id":"c25s3-39","p":"c25s3","n":39,"s":"cur","t":"International","q":"The “Kaladan Multimodal Transit Transport Project” links India with which country?","w":"The Kaladan Multi-Modal Transit Transport Project, based on a 2008 India–Myanmar framework agreement, gives Mizoram and the North-East a route to the sea that avoids the narrow Siliguri corridor. Cargo goes by sea from Kolkata to Sittwe port in Myanmar's Rakhine State, by inland waterway up the Kaladan river to Paletwa, and then by road to Zorinpui on the Mizoram border. Sittwe port, built with Indian funding, was operationalised in May 2023. The project is a key part of India's Act East Policy.","o":["China","Myanmar","Bangladesh","Nepal"],"a":[1],"qt":"\"कलादान मल्टीमॉडल ट्रांजिट ट्रांसपोर्ट प्रोजेक्ट\" भारत को किस देश से जोड़ता है?","ot":["चीन","म्यांमार","बांग्लादेश","नेपाल"],"wt":"कलादान मल्टी-मॉडल ट्रांज़िट ट्रांसपोर्ट परियोजना, जो 2008 के भारत-म्यांमार फ्रेमवर्क समझौते पर आधारित है, मिज़ोरम और पूर्वोत्तर को संकरे सिलीगुड़ी गलियारे से बचते हुए समुद्र तक मार्ग देती है। माल कोलकाता से समुद्री मार्ग द्वारा म्यांमार के रखाइन प्रांत के सित्वे बंदरगाह तक, फिर कलादान नदी के अंतर्देशीय जलमार्ग से पलेतवा तक और फिर सड़क मार्ग से मिज़ोरम सीमा पर ज़ोरिनपुई तक जाता है। भारत के वित्तपोषण से बना सित्वे बंदरगाह मई 2023 में चालू हुआ। यह परियोजना भारत की एक्ट ईस्ट नीति का महत्वपूर्ण हिस्सा है।"},{"id":"c25s3-40","p":"c25s3","n":40,"s":"cur","t":"Awards, Books & Persons","q":"'The Namesake' is a famous novel by which Indian-American author?","w":"The Namesake (2003) is the first novel of Jhumpa Lahiri, an American writer of Bengali origin. It follows Gogol Ganguli, son of Bengali immigrants in the United States, and his struggle with his unusual name and identity; Mira Nair made it into a film in 2006. Lahiri had earlier won the Pulitzer Prize for Fiction (2000) for her story collection Interpreter of Maladies. Kiran Desai wrote The Inheritance of Loss (Booker 2006), Arundhati Roy The God of Small Things, and Chitra Banerjee Divakaruni The Mistress of Spices.","o":["Jhumpa Lahiri","Arundhati Roy","Chitra Banerjee","Kiran Desai"],"a":[0],"qt":"'द नेमसेक' किस भारतीय-अमेरिकी लेखक का प्रसिद्ध उपन्यास है?","ot":["झुम्पा लाहिड़ी","अरुंधति रॉय","चित्रा बनर्जी","किरण देसाई"],"wt":"द नेमसेक (2003) बंगाली मूल की अमेरिकी लेखिका झुम्पा लाहिड़ी का पहला उपन्यास है। यह अमेरिका में बसे बंगाली आप्रवासियों के बेटे गोगोल गांगुली और अपने अनोखे नाम व पहचान को लेकर उसके संघर्ष की कहानी है; मीरा नायर ने 2006 में इस पर फ़िल्म बनाई। लाहिड़ी इससे पहले अपने कहानी संग्रह इंटरप्रेटर ऑफ मैलेडीज़ के लिए कथा साहित्य का पुलित्ज़र पुरस्कार (2000) जीत चुकी थीं। किरण देसाई ने द इनहेरिटेंस ऑफ लॉस (बुकर 2006), अरुंधति रॉय ने द गॉड ऑफ स्मॉल थिंग्स, और चित्रा बनर्जी दिवाकरुणी ने द मिस्ट्रेस ऑफ स्पाइसेस लिखी।"},{"id":"c25s3-41","p":"c25s3","n":41,"s":"geo","t":"Indian Geography","q":"Which of the following statements is correct regarding population stabilization?","w":"A population is stable when it stops growing, that is, when the birth rate and death rate are nearly equal so that natural increase is close to zero. This is the last stage of the demographic transition. In the long run it needs fertility at replacement level, a total fertility rate of about 2.1 children per woman, not zero fertility. India's National Population Policy, 2000 set the long-term goal of a stable population by 2045. A birth rate higher than the death rate means growth, not stability.","o":["Stabilization occurs when birth rate exceeds death rate","Stabilization is reached when fertility rate drops to zero","Stabilization occurs when birth and death rates are nearly equal","Stabilization refers to doubling of population every decade"],"a":[2],"qt":"जनसंख्या स्थिरीकरण के संबंध में निम्नलिखित में से कौन सा कथन सही है?","ot":["स्थिरीकरण तब होता है जब जन्म दर मृत्यु दर से अधिक हो जाती है","स्थिरीकरण तब होता है जब प्रजनन दर शून्य हो जाती है","स्थिरीकरण तब होता है जब जन्म और मृत्यु दर लगभग बराबर होती हैं","स्थिरीकरण का अर्थ है हर दशक में जनसंख्या का दोगुना होना"],"wt":"जनसंख्या तब स्थिर होती है जब उसकी वृद्धि रुक जाती है, यानी जब जन्म दर और मृत्यु दर लगभग बराबर हों ताकि प्राकृतिक वृद्धि लगभग शून्य रहे। यह जनांकिकीय संक्रमण की अंतिम अवस्था है। दीर्घकाल में इसके लिए प्रजनन दर का प्रतिस्थापन स्तर पर होना आवश्यक है, यानी लगभग 2.1 बच्चे प्रति महिला की कुल प्रजनन दर, न कि शून्य प्रजनन। भारत की राष्ट्रीय जनसंख्या नीति, 2000 ने 2045 तक स्थिर जनसंख्या का दीर्घकालिक लक्ष्य रखा। मृत्यु दर से अधिक जन्म दर का अर्थ वृद्धि है, स्थिरता नहीं।"},{"id":"c25s3-42","p":"c25s3","n":42,"s":"cur","t":"National","q":"Ajit Doval is known as a key figure in India’s strategic affairs, remains the National Security Advisor (NSA). In light of his ongoing tenure and recent developments, which of the following statements best reflects his current status as of July 2025?","w":"Ajit Doval, a former Director of the Intelligence Bureau, has been NSA since May 2014. After the 2024 general election, the Appointments Committee of the Cabinet reappointed him for a third term with effect from 10 June 2024, co-terminus with the Prime Minister's term or until further orders, with the rank of a Cabinet Minister (given to him since 2019). So option 3 fits. His tenure began in 2014, not 2025; his rank is not that of Cabinet Secretary and there is no fixed five-year term; and the National Security Council is chaired by the Prime Minister.","o":["Ajit Doval's current tenure as NSA, which began in June 2025, is his first independent term after serving as Principal Advisor on National Security for a decade.","He holds the ex-officio rank equivalent to a Cabinet Secretary, with his appointment typically for a fixed five-year term irrespective of the government's tenure.","Having been reappointed for a fresh term in June 2024, his current position is co-terminus with the Prime Minister's term and he holds the rank of a Cabinet Minister.","As NSA, his primary role is to chair the National Security Council (NSC), where he holds voting power on all key security policy decisions, including those related to defence procurement."],"a":[2],"qt":"अजीत डोभाल भारत के रणनीतिक मामलों में एक प्रमुख व्यक्ति के रूप में जाने जाते हैं और राष्ट्रीय सुरक्षा सलाहकार (NSA) के पद पर बने हुए हैं। उनके वर्तमान कार्यकाल और हालिया घटनाक्रमों के मद्देनजर, निम्नलिखित में से कौन सा कथन जुलाई 2025 तक उनकी वर्तमान स्थिति को सबसे अच्छी तरह दर्शाता है?","ot":["एनएसए के रूप में अजीत डोभाल का वर्तमान कार्यकाल, जो जून 2025 में शुरू होगा, एक दशक तक राष्ट्रीय सुरक्षा पर प्रधान सलाहकार के रूप में कार्य करने के बाद उनका पहला स्वतंत्र कार्यकाल है।","वह कैबिनेट सचिव के समकक्ष पद पर होते हैं, तथा उनकी नियुक्ति आमतौर पर सरकार के कार्यकाल से परे, पांच वर्ष की निश्चित अवधि के लिए होती है।","जून 2024 में नए कार्यकाल के लिए पुनर्नियुक्त होने के बाद, उनका वर्तमान पद प्रधानमंत्री के कार्यकाल के साथ समाप्त हो जाएगा और उन्हें कैबिनेट मंत्री का दर्जा प्राप्त होगा।","एनएसए के रूप में उनकी प्राथमिक भूमिका राष्ट्रीय सुरक्षा परिषद (एनएससी) की अध्यक्षता करना है, जहां उनके पास रक्षा खरीद से संबंधित निर्णयों सहित सभी प्रमुख सुरक्षा नीति निर्णयों पर मतदान का अधिकार है।"],"wt":"खुफिया ब्यूरो के पूर्व निदेशक अजीत डोभाल मई 2014 से राष्ट्रीय सुरक्षा सलाहकार हैं। 2024 के आम चुनाव के बाद मंत्रिमंडल की नियुक्ति समिति ने उन्हें 10 जून 2024 से तीसरे कार्यकाल के लिए पुनर्नियुक्त किया, जो प्रधानमंत्री के कार्यकाल के साथ या अगले आदेश तक चलेगा, और उन्हें कैबिनेट मंत्री का दर्जा दिया गया (जो उन्हें 2019 से प्राप्त है)। अतः विकल्प 3 उपयुक्त है। उनका कार्यकाल 2014 में शुरू हुआ था, 2025 में नहीं; उनका दर्जा कैबिनेट सचिव का नहीं है और कोई निश्चित पाँच वर्षीय कार्यकाल नहीं है; तथा राष्ट्रीय सुरक्षा परिषद की अध्यक्षता प्रधानमंत्री करते हैं।"},{"id":"c25s3-43","p":"c25s3","n":43,"s":"cur","t":"Sports","q":"Which of the following combinations of athletics winners at the 2025 National Games is entirely correct?","w":"Only option 1 pairs the athletes with their own events. Jyothi Yarraji (Andhra Pradesh) won the women's 100 m hurdles at the 38th National Games in Uttarakhand (February 2025) in a Games-record 13.10 s, and Parul Chaudhary is India's leading 3000 m steeplechaser and national record holder. In the other options, Lovlina Borgohain is a boxer, Amoj Jacob a 400 m runner, and Swapnil Kusale and Sarabjot Singh are shooters. However, results show the 2025 Games steeplechase gold went to Ankita Dhyani of Uttarakhand, Parul not starting. (SSC key; some sources differ.)","o":["Parul Chaudhary – 3000m steeplechase; Jyothi Yarraji – 100m hurdles","Lovlina – 100m hurdles; Amoj Jacob – Shot Put","Swapnil Kusale – Boxing; Sarabjot – Sprint","Amoj Jacob – Wrestling; Jyothi – Relay"],"a":[0],"qt":"2025 राष्ट्रीय खेलों में एथलेटिक्स विजेताओं का निम्नलिखित में से कौन सा संयोजन पूरी तरह से सही है?","ot":["पारुल चौधरी – 3000 मीटर स्टीपलचेज़; ज्योति याराजी – 100 मीटर बाधा दौड़","लवलीना – 100 मीटर बाधा दौड़; अमोज जैकब – शॉटपुट","स्वप्निल कुसाले - मुक्केबाजी; सरबजोत - स्प्रिंट","अमोज जैकब - कुश्ती; ज्योति - रिले"],"wt":"केवल विकल्प 1 में खिलाड़ियों को उनकी अपनी स्पर्धाओं से जोड़ा गया है। ज्योति याराजी (आंध्र प्रदेश) ने उत्तराखंड में हुए 38वें राष्ट्रीय खेलों (फरवरी 2025) में महिलाओं की 100 मीटर बाधा दौड़ 13.10 सेकंड के खेल रिकॉर्ड के साथ जीती, और पारुल चौधरी भारत की अग्रणी 3000 मीटर स्टीपलचेज़ धाविका और राष्ट्रीय रिकॉर्डधारी हैं। अन्य विकल्पों में लवलीना बोरगोहेन मुक्केबाज़ हैं, अमोज जैकब 400 मीटर धावक हैं, तथा स्वप्निल कुसाले और सरबजोत सिंह निशानेबाज़ हैं। हालाँकि परिणामों के अनुसार 2025 खेलों में स्टीपलचेज़ का स्वर्ण उत्तराखंड की अंकिता ध्यानी ने जीता था और पारुल ने दौड़ में भाग नहीं लिया। (SSC कुंजी; कुछ स्रोत भिन्न हैं।)"},{"id":"c25s3-44","p":"c25s3","n":44,"s":"pol","t":"Constitution & Rights","q":"Under Article 258A, what power is granted to States?","w":"Article 258A, added by the Seventh Amendment (1956), lets the Governor of a State, with the consent of the Government of India, entrust to that Government or its officers functions on any matter to which the executive power of the State extends. It is the reverse of Article 258(1), under which the President, with a State's consent, entrusts Union functions to the State. Option 4 is the only one built on the State acting with the Union's consent, but its wording is loose: the functions entrusted are the State's, given to Union officers. (SSC key; some sources differ.)","o":["States need Presidential assent to assign functions to Union","Governor can entrust Union tasks to State Legislature with President’s consent","State Legislature can entrust Union work to State officers with Centre’s approval","State Government can, with Union’s consent, assign Union functions to its officers"],"a":[3],"qt":"अनुच्छेद 258ए के तहत राज्यों को क्या शक्ति प्रदान की गई है?","ot":["राज्यों को संघ को कार्य सौंपने के लिए राष्ट्रपति की सहमति की आवश्यकता है","राज्यपाल राष्ट्रपति की सहमति से संघीय कार्यों को राज्य विधानमंडल को सौंप सकते हैं","राज्य विधानमंडल केंद्र की मंजूरी से राज्य के अधिकारियों को संघीय कार्य सौंप सकता है","राज्य सरकार संघ की सहमति से अपने अधिकारियों को संघ के कार्य सौंप सकती है"],"wt":"सातवें संशोधन (1956) द्वारा जोड़ा गया अनुच्छेद 258ए किसी राज्य के राज्यपाल को यह अधिकार देता है कि वह भारत सरकार की सहमति से, राज्य की कार्यपालिका शक्ति के अंतर्गत आने वाले किसी भी विषय से संबंधित कार्य भारत सरकार या उसके अधिकारियों को सौंप सके। यह अनुच्छेद 258(1) का उलटा है, जिसके तहत राष्ट्रपति राज्य की सहमति से संघ के कार्य राज्य को सौंपते हैं। विकल्प 4 ही एकमात्र विकल्प है जो संघ की सहमति से राज्य द्वारा कार्य सौंपने पर आधारित है, पर इसकी शब्दावली ढीली है: सौंपे जाने वाले कार्य राज्य के होते हैं और वे संघ के अधिकारियों को दिए जाते हैं। (SSC कुंजी; कुछ स्रोत भिन्न हैं।)"},{"id":"c25s3-45","p":"c25s3","n":45,"s":"sci","t":"Physics","q":"Read the following statements about the photoelectric effect:\n1. The kinetic energy of emitted photoelectrons increases with increasing intensity of incident light.\n2. The photoelectric effect demonstrates the particle nature of light.\n3. There is a threshold frequency below which no photoemission occurs, regardless of light intensity.\nWhich of the above statements are correct?","w":"By Einstein's equation, the maximum kinetic energy of photoelectrons is K = hν − φ, where φ is the work function of the metal. It depends on the frequency of light, not its intensity; higher intensity only means more photons and so more photoelectrons (a larger photocurrent). So statement 1 is wrong. Einstein explained the effect (1905) by treating light as particles (photons), so statement 2 is correct. Emission needs hν ≥ φ, so below the threshold frequency ν₀ = φ/h no electrons are emitted at any intensity; statement 3 is correct.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[1],"qt":"प्रकाश-विद्युत प्रभाव के बारे में निम्नलिखित कथन पढ़ें:\n1. उत्सर्जित प्रकाश-इलेक्ट्रॉनों की गतिज ऊर्जा, आपतित प्रकाश की तीव्रता बढ़ने पर बढ़ती है।\n2. प्रकाश-विद्युत प्रभाव प्रकाश की कणिकीय प्रकृति को दर्शाता है।\n3. एक सीमा आवृत्ति होती है जिसके नीचे प्रकाश की तीव्रता चाहे जो भी हो, कोई प्रकाश-उत्सर्जन नहीं होता है।\nउपरोक्त में से कौन से कथन सत्य हैं?","ot":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"wt":"आइंस्टीन के समीकरण के अनुसार प्रकाश-इलेक्ट्रॉनों की अधिकतम गतिज ऊर्जा K = hν − φ होती है, जहाँ φ धातु का कार्य फलन है। यह प्रकाश की आवृत्ति पर निर्भर करती है, तीव्रता पर नहीं; अधिक तीव्रता का अर्थ केवल अधिक फोटॉन और इसलिए अधिक प्रकाश-इलेक्ट्रॉन (अधिक प्रकाश-विद्युत धारा) है। अतः कथन 1 गलत है। आइंस्टीन ने (1905 में) प्रकाश को कणों (फोटॉनों) के रूप में मानकर इस प्रभाव की व्याख्या की, इसलिए कथन 2 सही है। उत्सर्जन के लिए hν ≥ φ आवश्यक है, इसलिए देहली आवृत्ति ν₀ = φ/h से कम आवृत्ति पर किसी भी तीव्रता में इलेक्ट्रॉन उत्सर्जित नहीं होते; कथन 3 सही है।"},{"id":"c25s3-46","p":"c25s3","n":46,"s":"cur","t":"Static GK & Culture","q":"Fill in the Blank:\nGhoomar was originally performed to worship ______.","w":"Ghoomar is a traditional folk dance of Rajasthan. It is said to have been developed by the Bhil tribe to worship the goddess Saraswati and was later adopted by the Rajputs and other Rajasthani communities. Women in flowing ghaghras and veils dance in circles, and the name comes from ghoomna, the twirling movement. It is performed at festivals such as Teej, Gangaur and Holi and at weddings and other auspicious occasions.","o":["Shiva","Saraswati","Krishna","Ganesha"],"a":[1],"qt":"रिक्त स्थान भरें:\nघूमर मूल रूप से ______ की पूजा करने के लिए किया जाता था।","ot":["शिव","सरस्वती","कृष्ण","गणेश"],"wt":"घूमर राजस्थान का पारंपरिक लोकनृत्य है। कहा जाता है कि इसे भील जनजाति ने देवी सरस्वती की पूजा के लिए विकसित किया था और बाद में राजपूतों तथा अन्य राजस्थानी समुदायों ने इसे अपनाया। लहराते घाघरे और घूँघट पहने महिलाएँ गोल घेरे में नृत्य करती हैं, और इसका नाम 'घूमना' (घूमने की क्रिया) से बना है। यह तीज, गणगौर और होली जैसे त्योहारों तथा विवाह और अन्य शुभ अवसरों पर किया जाता है।"},{"id":"c25s3-47","p":"c25s3","n":47,"s":"eco","t":"Agriculture, Industry & Trade","q":"Which new element was incorporated in the 2023 edition of the Logistics Performance Index (LPI)?","w":"The Logistics Performance Index is the World Bank's benchmarking tool for trade logistics, published every two years from 2010 to 2018. The 2023 edition, the seventh, covering 139 countries, for the first time measured the speed of trade with new indicators drawn from big datasets that track shipments, alongside the usual survey of logistics professionals. India ranked 38th, up six places from 44th in 2018. The LPI covers all transport modes and all income groups and has nothing to do with tourism.","o":["It evaluates only land-based transport systems","It ranks countries based on tourism potential","It includes indicators measuring trade speed using big data","It excludes lower-income economies from the analysis"],"a":[2],"qt":"लॉजिस्टिक्स परफॉर्मेंस इंडेक्स (LPI) के 2023 संस्करण में कौन सा नया तत्व शामिल किया गया?","ot":["यह केवल भूमि-आधारित परिवहन प्रणालियों का मूल्यांकन करता है","यह पर्यटन क्षमता के आधार पर देशों को रैंक करता है","इसमें बड़े डेटा का उपयोग करके व्यापार की गति को मापने वाले संकेतक शामिल हैं","यह विश्लेषण से निम्न-आय वाली अर्थव्यवस्थाओं को बाहर रखता है"],"wt":"लॉजिस्टिक्स परफॉर्मेंस इंडेक्स व्यापार लॉजिस्टिक्स के लिए विश्व बैंक का तुलनात्मक मूल्यांकन उपकरण है, जो 2010 से 2018 तक हर दो वर्ष में प्रकाशित हुआ। 139 देशों को शामिल करने वाले 2023 के सातवें संस्करण ने पहली बार, लॉजिस्टिक्स पेशेवरों के सामान्य सर्वेक्षण के साथ-साथ, शिपमेंट को ट्रैक करने वाले बड़े डेटासेट से लिए गए नए संकेतकों द्वारा व्यापार की गति मापी। भारत 2018 के 44वें स्थान से छह स्थान ऊपर चढ़कर 38वें स्थान पर रहा। LPI सभी परिवहन साधनों और सभी आय वर्गों को शामिल करता है और इसका पर्यटन से कोई संबंध नहीं है।"},{"id":"c25s3-48","p":"c25s3","n":48,"s":"geo","t":"Environment & Ecology","q":"Which institute has been studying the Pensilungpa Glacier in Zanskar, Ladakh, to monitor its retreat and mass balance?","w":"Scientists of the Wadia Institute of Himalayan Geology, Dehradun, an autonomous institute under the Department of Science and Technology, have studied the Pensilungpa Glacier in the Zanskar valley of Ladakh. Their study, reported by DST in 2021, found that the glacier is retreating at about 6.7 ± 3 m a year and that its mass balance for 2016–2019 was negative, mainly because of rising temperature and falling winter precipitation, with debris cover affecting summer melt. INCOIS (Hyderabad) and CMFRI (Kochi) deal with the oceans, and ZSI surveys animal life.","o":["Indian National Centre for Ocean Information Services (INCOIS)","Wadia Institute of Himalayan Geology (WIHG)","Central Marine Fisheries Research Institute (CMFRI)","Zoological Survey of India (ZSI)"],"a":[1],"qt":"कौन सा संस्थान लद्दाख के ज़ांस्कर में पेनसिलुंगपा ग्लेशियर का अध्ययन कर रहा है, ताकि इसके पीछे हटने और द्रव्यमान संतुलन की निगरानी की जा सके?","ot":["भारतीय राष्ट्रीय महासागर सूचना सेवा केंद्र (आईएनसीओआईएस)","वाडिया हिमालय भूविज्ञान संस्थान (डब्ल्यूआईएचजी)","केंद्रीय समुद्री मत्स्य अनुसंधान संस्थान (सीएमएफआरआई)","भारतीय प्राणी सर्वेक्षण(जेडएसआई)"],"wt":"वाडिया हिमालय भूविज्ञान संस्थान, देहरादून (विज्ञान और प्रौद्योगिकी विभाग के अधीन एक स्वायत्त संस्थान) के वैज्ञानिकों ने लद्दाख की ज़ांस्कर घाटी में पेनसिलुंगपा ग्लेशियर का अध्ययन किया है। DST द्वारा 2021 में बताए गए उनके अध्ययन के अनुसार यह ग्लेशियर लगभग 6.7 ± 3 मीटर प्रति वर्ष की दर से पीछे हट रहा है और 2016–2019 में इसका द्रव्यमान संतुलन ऋणात्मक रहा, जिसका मुख्य कारण बढ़ता तापमान और घटती शीतकालीन वर्षा है, तथा मलबे का आवरण ग्रीष्मकालीन पिघलन को प्रभावित करता है। INCOIS (हैदराबाद) और CMFRI (कोच्चि) महासागरों से संबंधित हैं, और ZSI जीव-जंतुओं का सर्वेक्षण करता है।"},{"id":"c25s3-49","p":"c25s3","n":49,"s":"geo","t":"World & Physical Geography","q":"Earth's atmosphere reaches what height approximately(Kármán line )?","w":"The Kármán line, about 100 km above mean sea level, is the conventional boundary between Earth's atmosphere and outer space, used by the Fédération Aéronautique Internationale (FAI). It is named after Theodore von Kármán, who showed that above roughly this height an aircraft would have to fly at orbital speed to get enough aerodynamic lift. The atmosphere has no sharp top: it thins out gradually, and the very thin exosphere extends to several thousand kilometres, so the other options do not match the Kármán line.","o":["100 km","1000 km","10,000 km","100,000 km"],"a":[0],"qt":"पृथ्वी का वायुमंडल लगभग कितनी ऊंचाई तक पहुंचता है (कारमन रेखा)?","ot":["100 किमी","1000 किमी","10,000 किमी","100,000 किमी"],"wt":"कारमन रेखा, जो माध्य समुद्र तल से लगभग 100 किमी ऊपर है, पृथ्वी के वायुमंडल और बाह्य अंतरिक्ष के बीच की पारंपरिक सीमा है, जिसे फ़ेडरेशन एरोनॉटिक इंटरनेशनल (FAI) मानता है। इसका नाम थियोडोर वॉन कारमन के नाम पर है, जिन्होंने दिखाया कि लगभग इस ऊँचाई के ऊपर किसी विमान को पर्याप्त वायुगतिकीय उत्थापन (लिफ्ट) पाने के लिए कक्षीय वेग से उड़ना पड़ेगा। वायुमंडल का कोई स्पष्ट ऊपरी छोर नहीं है: यह धीरे-धीरे विरल होता जाता है, और अत्यंत विरल बहिर्मंडल कई हज़ार किलोमीटर तक फैला है, इसलिए अन्य विकल्प कारमन रेखा से मेल नहीं खाते।"},{"id":"c25s3-50","p":"c25s3","n":50,"s":"pol","t":"Constitution & Rights","q":"Consider the following statements:\n1. Article 300 allows legal suits against State Governments.\n2. The term 'Government of India' is a legal entity under Article 300.\nWhich of the above is/are correct?","w":"Article 300 provides that the Government of India may sue or be sued by the name of the Union of India, and the Government of a State by the name of the State, in the same cases as the Dominion of India and the provinces could before the Constitution, subject to laws made by Parliament or the State Legislature. So suits can be filed against State Governments (statement 1), and the Government of India is treated as a juristic entity that can sue and be sued (statement 2), the party being named 'Union of India'.","o":["Only 1","Only 2","Both 1 and 2","Neither 1 nor 2"],"a":[2],"qt":"निम्नलिखित कथनों पर विचार कीजिए:\n1. अनुच्छेद 300 राज्य सरकारों के विरुद्ध कानूनी मुकदमों की अनुमति देता है।\n2. अनुच्छेद 300 के अंतर्गत 'भारत सरकार' शब्द एक कानूनी इकाई है।\nउपर्युक्त में से कौन सा/से सही है/हैं?","ot":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"wt":"अनुच्छेद 300 के अनुसार भारत सरकार 'भारत संघ' के नाम से और किसी राज्य की सरकार उस राज्य के नाम से वाद ला सकती है और उस पर वाद लाया जा सकता है, उन्हीं मामलों में जिनमें संविधान से पहले भारत डोमिनियन और प्रांत ऐसा कर सकते थे, बशर्ते संसद या राज्य विधानमंडल द्वारा बनाए गए कानून कुछ और न कहें। अतः राज्य सरकारों के विरुद्ध मुकदमे दायर किए जा सकते हैं (कथन 1), और भारत सरकार को एक विधिक इकाई माना जाता है जो वाद ला सकती है और जिस पर वाद लाया जा सकता है (कथन 2), जहाँ पक्षकार का नाम 'भारत संघ' होता है।"},{"id":"c25s3-51","p":"c25s3","n":51,"s":"qa","t":"Number System & Simplification","q":"Solve: (√6400 − √2401) × (1/4)","w":"Take the square roots first: √6400 = 80 (since 80² = 6400) and √2401 = 49 (since 49² = 2401). The bracket is 80 − 49 = 31, and 31 × (1/4) = 31/4 = 7.75. Each distractor needs a different bracket (8.75 needs 35, 9.75 needs 39), so a slip in a root shows up at once; confirm each root by squaring.","o":["7.75","8.75","9.75","10.75"],"a":[0],"qt":"हल करना: (√6400 − √2401) × (1/4)","ot":["7.75","8.75","9.75","10.75"],"wt":"पहले वर्गमूल निकालिए: √6400 = 80 (क्योंकि 80² = 6400) और √2401 = 49 (क्योंकि 49² = 2401)। कोष्ठक का मान 80 − 49 = 31 है, और 31 × (1/4) = 31/4 = 7.75। प्रत्येक गलत विकल्प के लिए कोष्ठक का मान अलग होना चाहिए (8.75 के लिए 35, 9.75 के लिए 39), इसलिए वर्गमूल में हुई चूक तुरंत पकड़ में आ जाती है; प्रत्येक मूल का वर्ग करके जाँच लीजिए।"},{"id":"c25s3-52","p":"c25s3","n":52,"s":"qa","t":"Number System & Simplification","q":"Solve: (√5776 − √4761) × (1/2)","w":"Find each square root: 76² = 5776, so √5776 = 76; 69² = 4761, so √4761 = 69. The bracket is 76 − 69 = 7, and 7 × (1/2) = 3.5. Quick check: a square ending in 6 has a root ending in 4 or 6, and one ending in 1 has a root ending in 1 or 9; since 75² = 5625 < 5776 and 4761 < 70² = 4900, the roots are 76 and 69.","o":["3.5","4.5","6.5","7.5"],"a":[0],"qt":"हल करना: (√5776 − √4761) × (1/2)","ot":["3.5","4.5","6.5","7.5"],"wt":"प्रत्येक वर्गमूल ज्ञात कीजिए: 76² = 5776, अतः √5776 = 76; 69² = 4761, अतः √4761 = 69। कोष्ठक का मान 76 − 69 = 7 है, और 7 × (1/2) = 3.5। त्वरित जाँच: 6 पर समाप्त होने वाले वर्ग का मूल 4 या 6 पर समाप्त होता है, और 1 पर समाप्त होने वाले वर्ग का मूल 1 या 9 पर; चूँकि 75² = 5625 < 5776 और 4761 < 70² = 4900, इसलिए मूल 76 और 69 हैं।"},{"id":"c25s3-53","p":"c25s3","n":53,"s":"qa","t":"Ratio, Average & Mixtures","q":"If 40% of A = 0.5 of B = 1/4 of C, then what is A: B: C?","w":"Let each equal quantity be k. Then 0.4A = k gives A = 2.5k; 0.5B = k gives B = 2k; and C/4 = k gives C = 4k. So A : B : C = 2.5 : 2 : 4 = 5 : 4 : 8 (multiplying by 2). Check with k = 2: A = 5, B = 4, C = 8, and 40% of 5 = 0.5 of 4 = 1/4 of 8 = 2. Option 5 : 4 : 2 fails this check, since 1/4 of 2 is 0.5, not 2.","o":["5 : 4 : 2","10 : 8 : 5","5 : 4 : 8","5 : 10 : 20"],"a":[2],"qt":"यदि A का 40% = B का 0.5 = C का 1/4 तो A: B: C क्या है?","ot":["5 : 4 : 2","10 : 8 : 5","5 : 4 : 8","5 : 10 : 20"],"wt":"प्रत्येक बराबर राशि को k मान लीजिए। तब 0.4A = k से A = 2.5k; 0.5B = k से B = 2k; और C/4 = k से C = 4k। अतः A : B : C = 2.5 : 2 : 4 = 5 : 4 : 8 (2 से गुणा करने पर)। k = 2 लेकर जाँच: A = 5, B = 4, C = 8, और 5 का 40% = 4 का 0.5 = 8 का 1/4 = 2। विकल्प 5 : 4 : 2 इस जाँच में विफल रहता है, क्योंकि 2 का 1/4 = 0.5 है, 2 नहीं।"},{"id":"c25s3-54","p":"c25s3","n":54,"s":"qa","t":"Ratio, Average & Mixtures","q":"Two containers of equal capacity filled with milk and water. The first contains milk and water in the ratio 2 : 3, and the second in the ratio 3 : 2. The mixtures are then combined. What is the ratio of milk to water in the resulting mixture?","w":"Take each container as 5 litres (the ratio parts add to 5 in both). The first has 2 L milk and 3 L water; the second has 3 L milk and 2 L water. Combined: milk = 2 + 3 = 5 L and water = 3 + 2 = 5 L, so milk : water = 5 : 5 = 1 : 1. The option 5:5 is the same ratio left unsimplified; a ratio is normally given in its lowest terms, 1:1, which is the keyed option.","o":["1:1","2:3","3:2","5:5"],"a":[0],"qt":"बराबर क्षमता वाले दो बर्तन दूध और पानी से भरे हुए हैं। पहले बर्तन में दूध और पानी का अनुपात 2 : 3 है, और दूसरे बर्तन में 3 : 2 है। फिर मिश्रण को मिलाया जाता है। परिणामी मिश्रण में दूध और पानी का अनुपात क्या है?","ot":["1:1","2:3","3:2","5:5"],"wt":"प्रत्येक बर्तन को 5 लीटर मान लीजिए (दोनों अनुपातों के भागों का योग 5 है)। पहले बर्तन में 2 L दूध और 3 L पानी है; दूसरे में 3 L दूध और 2 L पानी। मिलाने पर: दूध = 2 + 3 = 5 L और पानी = 3 + 2 = 5 L, अतः दूध : पानी = 5 : 5 = 1 : 1। विकल्प 5:5 वही अनुपात है, बस सरल नहीं किया गया; अनुपात सामान्यतः न्यूनतम पदों में लिखा जाता है, अर्थात 1:1, जो कुंजी वाला विकल्प है।"},{"id":"c25s3-55","p":"c25s3","n":55,"s":"qa","t":"Percentage, Profit & Interest","q":"A pair of shoes is listed at ₹ 800. After two successive discounts, it is sold for ₹ 612. If the first discount offered was 10%, what was the second discount percentage?","w":"After the first discount of 10%, the price is 800 × 0.90 = ₹720. The second discount brings it from ₹720 to ₹612, a reduction of ₹108. Second discount = 108/720 × 100 = 15%. Check: 800 × 0.90 × 0.85 = ₹612. The second discount is worked on the already reduced price (₹720), not on the list price; 188/800 would give the total discount of 23.5%.","o":["12%","14%","15%","18%"],"a":[2],"qt":"एक जोड़ी जूते का मूल्य ₹ 800 है। दो क्रमिक छूट के बाद इसे ₹ 612 में बेचा जाता है। यदि दी गई पहली छूट 10% थी, तो दूसरी छूट का प्रतिशत क्या था?","ot":["12%","14%","15%","18%"],"wt":"10% की पहली छूट के बाद मूल्य = 800 × 0.90 = ₹720। दूसरी छूट मूल्य को ₹720 से ₹612 कर देती है, अर्थात ₹108 की कमी। दूसरी छूट = 108/720 × 100 = 15%। जाँच: 800 × 0.90 × 0.85 = ₹612। दूसरी छूट पहले से घटे हुए मूल्य (₹720) पर लगती है, सूची मूल्य पर नहीं; 188/800 से कुल छूट 23.5% मिलती है।"},{"id":"c25s3-56","p":"c25s3","n":56,"s":"qa","t":"Percentage, Profit & Interest","q":"A retailer marked a product 60% above its cost price. He provided two successive discounts of 25% and 10%. If he earned a profit of ₹160, what was the cost price of the product?","w":"Let CP = ₹x. Marked price = 1.6x. After successive discounts of 25% and 10%, SP = 1.6x × 0.75 × 0.90 = 1.08x. So the profit is 8% of CP: 0.08x = 160, giving x = ₹2000. Check: MP = 3200, after 25% off = 2400, after 10% off = 2160, and 2160 − 2000 = ₹160. The distractor ₹1080 confuses the multiplier 1.08 with the answer.","o":["₹2000","₹2500","₹1080","₹1000"],"a":[0],"qt":"एक खुदरा विक्रेता ने एक उत्पाद को उसके लागत मूल्य से 60% अधिक मूल्य पर अंकित किया। उसने 25% और 10% की दो क्रमिक छूट प्रदान की। यदि उसने ₹160 का लाभ कमाया, तो उत्पाद का लागत मूल्य क्या था?","ot":["₹2000","₹2500","₹1080","₹1000"],"wt":"मान लीजिए लागत मूल्य (CP) = ₹x। अंकित मूल्य = 1.6x। 25% और 10% की क्रमिक छूट के बाद विक्रय मूल्य = 1.6x × 0.75 × 0.90 = 1.08x। अतः लाभ लागत मूल्य का 8% है: 0.08x = 160, जिससे x = ₹2000। जाँच: अंकित मूल्य = 3200, 25% छूट के बाद = 2400, 10% छूट के बाद = 2160, और 2160 − 2000 = ₹160। विकल्प ₹1080 गुणक 1.08 को ही उत्तर समझने की भूल है।"},{"id":"c25s3-57","p":"c25s3","n":57,"s":"qa","t":"Algebra","q":"If (x + 2/x = 7), find the value of x³ + 8/x³.","w":"Use (a + b)³ = a³ + b³ + 3ab(a + b) with a = x and b = 2/x, so ab = 2. Then x³ + 8/x³ = (x + 2/x)³ − 3 × 2 × (x + 2/x) = 7³ − 6 × 7 = 343 − 42 = 301. Using 3 instead of 3ab = 6 (as for x + 1/x) gives 343 − 21 = 322, and forgetting the product term entirely gives 343; neither is the right value.","o":["256","301","352","298"],"a":[1],"qt":"यदि (x + 2/x = 7), तो x³ + 8/x³ का मान ज्ञात कीजिए।","ot":["256","301","352","298"],"wt":"(a + b)³ = a³ + b³ + 3ab(a + b) का प्रयोग कीजिए, जहाँ a = x और b = 2/x, अतः ab = 2। तब x³ + 8/x³ = (x + 2/x)³ − 3 × 2 × (x + 2/x) = 7³ − 6 × 7 = 343 − 42 = 301। 3ab = 6 के स्थान पर 3 लेने पर (जैसा x + 1/x में होता है) 343 − 21 = 322 मिलता है, और गुणनफल वाला पद पूरी तरह भूल जाने पर 343; इनमें से कोई भी सही मान नहीं है।"},{"id":"c25s3-58","p":"c25s3","n":58,"s":"qa","t":"Percentage, Profit & Interest","q":"An educational fund of ₹6,00,000 earns simple interest at 9% per annum. This annual interest is used to grant three scholarships. If the first and third scholarships are ₹18,000 and ₹22,000 respectively, what is the value of the second scholarship?","w":"Annual simple interest = P × R × T/100 = 6,00,000 × 9 × 1/100 = ₹54,000. This whole amount is shared by the three scholarships, so the second one = 54,000 − (18,000 + 22,000) = 54,000 − 40,000 = ₹14,000. Only one year's interest is used, because the scholarships are paid from the annual interest.","o":["₹14,000","₹16,000","₹18,000","₹20,000"],"a":[0],"qt":"₹6,00,000 के एक शैक्षिक कोष पर 9% प्रति वर्ष साधारण ब्याज मिलता है। इस वार्षिक ब्याज का उपयोग तीन छात्रवृत्तियाँ प्रदान करने के लिए किया जाता है। यदि पहली और तीसरी छात्रवृत्तियाँ क्रमशः ₹18,000 और ₹22,000 हैं, तो दूसरी छात्रवृत्ति का मूल्य क्या है?","ot":["₹14,000","₹16,000","₹18,000","₹20,000"],"wt":"वार्षिक साधारण ब्याज = P × R × T/100 = 6,00,000 × 9 × 1/100 = ₹54,000। यह पूरी राशि तीनों छात्रवृत्तियों में बँटती है, अतः दूसरी छात्रवृत्ति = 54,000 − (18,000 + 22,000) = 54,000 − 40,000 = ₹14,000। केवल एक वर्ष का ब्याज लिया जाता है, क्योंकि छात्रवृत्तियाँ वार्षिक ब्याज से दी जाती हैं।"},{"id":"c25s3-59","p":"c25s3","n":59,"s":"qa","t":"Percentage, Profit & Interest","q":"Suppose ₹X is invested, and after 2 years at 5% simple interest, it yields ₹Y interest. If ₹Y is then invested for 2 years at 5% simple interest, it yields ₹Z interest. Which of the following is true?","w":"Simple interest for 2 years at 5% is 10% of the principal. So Y = X × 5 × 2/100 = X/10, and Z = Y × 5 × 2/100 = Y/10. Hence Y/X = Z/Y = 1/10, i.e. X, Y, Z are in geometric progression, so Y² = XZ. Check with X = 1000: Y = 100, Z = 10, and 100² = 10,000 = 1000 × 10, while X + Z = 1010 ≠ Y.","o":["Y = X + Z","Y² = XZ","X = Y + Z","X² = Y + Z"],"a":[1],"qt":"मान लीजिए ₹X का निवेश किया जाता है, और 2 वर्ष बाद 5% साधारण ब्याज पर, इस पर ₹Y ब्याज मिलता है। यदि ₹Y को 2 वर्ष के लिए 5% साधारण ब्याज पर निवेश किया जाता है, तो इस पर ₹Z ब्याज मिलता है। निम्नलिखित में से कौन सा कथन सत्य है?","ot":["Y = X + Z","Y² = XZ","X = Y + Z","X² = Y + Z"],"wt":"5% की दर से 2 वर्ष का साधारण ब्याज मूलधन का 10% होता है। अतः Y = X × 5 × 2/100 = X/10, और Z = Y × 5 × 2/100 = Y/10। इसलिए Y/X = Z/Y = 1/10, अर्थात X, Y, Z गुणोत्तर श्रेढ़ी में हैं, अतः Y² = XZ। X = 1000 लेकर जाँच: Y = 100, Z = 10, और 100² = 10,000 = 1000 × 10, जबकि X + Z = 1010 ≠ Y।"},{"id":"c25s3-60","p":"c25s3","n":60,"s":"qa","t":"Trigonometry & Heights","q":"An airplane flying at a height of 300 m notices the angles of depression to two boats located on opposite sides as 45° and 30°. Find the distance between the two boats.","w":"The angle of depression from the plane equals the angle of elevation from each boat. Horizontal distance of a boat = height/tan(angle). For 45°: 300/1 = 300 m; for 30°: 300/(1/√3) = 300√3 m. The boats are on opposite sides of the point below the plane, so the distances add: 300 + 300√3 = 300(√3 + 1) m ≈ 819.6 m. If they were on the same side, the answer would be the difference, 300(√3 − 1) m.","o":["300(√3 − 1) m","300√3 m","300 (1 + 1/√3) m","300(√3 + 1) m"],"a":[3],"qt":"300 मीटर की ऊंचाई पर उड़ता एक हवाई जहाज विपरीत दिशाओं में स्थित दो नावों के अवनमन कोण 45° और 30° देखता है। दोनों नावों के बीच की दूरी ज्ञात कीजिए।","ot":["300(√3 − 1) मीटर","300√3 मीटर","300 (1 + 1/√3) मीटर","300(√3 + 1) मीटर"],"wt":"हवाई जहाज से अवनमन कोण, प्रत्येक नाव से उन्नयन कोण के बराबर होता है। नाव की क्षैतिज दूरी = ऊँचाई/tan(कोण)। 45° के लिए: 300/1 = 300 मीटर; 30° के लिए: 300/(1/√3) = 300√3 मीटर। नावें विमान के ठीक नीचे वाले बिंदु के विपरीत ओर हैं, इसलिए दूरियाँ जुड़ती हैं: 300 + 300√3 = 300(√3 + 1) मीटर ≈ 819.6 मीटर। यदि वे एक ही ओर होतीं, तो उत्तर उनका अंतर, 300(√3 − 1) मीटर, होता।"},{"id":"c25s3-61","p":"c25s3","n":61,"s":"qa","t":"Trigonometry & Heights","q":"A statue that is 1.6 meters in height is positioned on top of a pedestal. From a location on the ground, the angle of elevation to the top of the statue measures 60 degrees, while the angle of elevation to the top of the pedestal from the same point is 45 degrees. Determine the height of the pedestal.","w":"Let the pedestal be h m and the point be d m from its foot. tan 45° = h/d gives d = h. tan 60° = (h + 1.6)/d gives √3h = h + 1.6, so h(√3 − 1) = 1.6 and h = 1.6/(√3 − 1). Rationalise: 1.6(√3 + 1)/(3 − 1) = 0.8(√3 + 1) m ≈ 2.19 m. Forgetting to divide by 2 while rationalising gives the distractor 1.6(√3 + 1) m.","o":["0.8(√3 − 1) m","1.6(√3 − 1) m","0.8(√3 + 1) m","1.6(√3 + 1) m"],"a":[2],"qt":"एक प्रतिमा जिसकी ऊँचाई 1.6 मीटर है, एक आधारस्तंभ (पेडेस्टल) के ऊपर स्थित है। जमीन पर एक बिंदु से, प्रतिमा के शीर्ष तक का उन्नयन कोण 60° है, जबकि उसी बिंदु से आधारस्तंभ के शीर्ष तक का उन्नयन कोण 45° है। आधारस्तंभ की ऊँचाई ज्ञात कीजिए।","ot":["0.8(√3 − 1) मीटर","1.6(√3 − 1) मीटर","0.8(√3 + 1) मीटर","1.6(√3 + 1) मीटर"],"wt":"मान लीजिए आधारस्तंभ की ऊँचाई h मीटर है और बिंदु उसके पाद से d मीटर दूर है। tan 45° = h/d से d = h। tan 60° = (h + 1.6)/d से √3h = h + 1.6, अतः h(√3 − 1) = 1.6 और h = 1.6/(√3 − 1)। परिमेयकरण: 1.6(√3 + 1)/(3 − 1) = 0.8(√3 + 1) मीटर ≈ 2.19 मीटर। परिमेयकरण करते समय 2 से भाग देना भूल जाने पर गलत विकल्प 1.6(√3 + 1) मीटर मिलता है।"},{"id":"c25s3-62","p":"c25s3","n":62,"s":"qa","t":"Mensuration","q":"The inner and outer radius of a hollow hemispherical shell are 7 cm and 14 cm respectively. Find the approximate volume of the metal used.","w":"Volume of metal = volume of outer hemisphere − volume of inner hemisphere = (2/3)π(R³ − r³) = (2/3)π(14³ − 7³) = (2/3)π(2744 − 343) = (2/3)π × 2401. With π = 3.14 this is about 5026.1 cm³ (about 5028.6 cm³ with exact π). SSC's 5026.33 cm³ is a slightly rounded figure for this value and the only option near it; every other option is at least 470 cm³ away.","o":["5987.25 cm³","5026.33 cm³","4500.8 cm³","5500 cm³"],"a":[1],"qt":"एक खोखले अर्धगोलाकार खोल की आंतरिक और बाहरी त्रिज्याएँ क्रमशः 7 सेमी और 14 सेमी हैं। प्रयुक्त धातु का लगभग आयतन ज्ञात कीजिए।","ot":["5987.25 सेमी³","5026.33 सेमी³","4500.8 सेमी³","5500 सेमी³"],"wt":"धातु का आयतन = बाहरी अर्धगोले का आयतन − आंतरिक अर्धगोले का आयतन = (2/3)π(R³ − r³) = (2/3)π(14³ − 7³) = (2/3)π(2744 − 343) = (2/3)π × 2401। π = 3.14 लेने पर यह लगभग 5026.1 सेमी³ है (वास्तविक π से लगभग 5028.6 सेमी³)। SSC का 5026.33 सेमी³ इसी मान का थोड़ा पूर्णांकित रूप है और इसके निकट एकमात्र विकल्प है; अन्य सभी विकल्प इससे कम से कम 470 सेमी³ दूर हैं।"},{"id":"c25s3-63","p":"c25s3","n":63,"s":"qa","t":"Mensuration","q":"A right circular cone is divided into two sections by a plane that is parallel to the base, with the volumes of the frustum and the smaller cone having a ratio of 7:1. Determine the ratio of their heights.","w":"Frustum : small cone = 7 : 1 in volume, so the small cone is 1/8 of the whole cone. The small cone is similar to the whole, so (h/H)³ = 1/8 and h = H/2. The frustum's height is then H − H/2 = H/2, the same as the small cone's height, so the ratio of their heights is 1 : 1. Taking the volume ratio 7 : 1 (or 1 : 7) directly as the height ratio is the usual mistake.","o":["1:1","1:7","5:1","6:1"],"a":[0],"qt":"एक समकोण वृत्तीय शंकु को उसके आधार के समांतर एक तल द्वारा दो भागों में विभाजित किया गया है। इन भागों में से एक एक छोटा शंकु है और दूसरा एक खंड (फ्रसटम)। यदि खंड और छोटे शंकु के आयतनों का अनुपात 7:1 है, तो उनके ऊँचाइयों का अनुपात ज्ञात कीजिए।","ot":["1:1","1:7","5:1","6:1"],"wt":"आयतन में खंड : छोटा शंकु = 7 : 1, अतः छोटा शंकु पूरे शंकु का 1/8 है। छोटा शंकु पूरे शंकु के समरूप है, अतः (h/H)³ = 1/8 और h = H/2। तब खंड की ऊँचाई H − H/2 = H/2 है, जो छोटे शंकु की ऊँचाई के बराबर है, अतः उनकी ऊँचाइयों का अनुपात 1 : 1 है। आयतन अनुपात 7 : 1 (या 1 : 7) को सीधे ऊँचाइयों का अनुपात मान लेना सामान्य भूल है।"},{"id":"c25s3-64","p":"c25s3","n":64,"s":"qa","t":"Mensuration","q":"If the side of a regular hexagon is doubled, what happens to its area?","w":"Area of a regular hexagon of side a = (3√3/2)a². Area varies as the square of the side, so with side 2a the area is (3√3/2)(2a)² = 4 × (3√3/2)a², i.e. four times the original: quadrupled. This holds for any plane figure scaled up: doubling every length multiplies the area by 2² = 4 (and a volume by 2³ = 8). \"Increases 6 times\" wrongly links the 6 sides to the factor.","o":["Doubled","Tripled","Quadrupled","Increases 6 times"],"a":[2],"qt":"यदि एक समषट्भुज की भुजा को दोगुना कर दिया जाए, तो उसके क्षेत्रफल पर क्या प्रभाव पड़ेगा?","ot":["दोगुनी","तीन गुना","चार गुना","6 गुना बढ़ जाता है"],"wt":"a भुजा वाले समषट्भुज का क्षेत्रफल = (3√3/2)a²। क्षेत्रफल भुजा के वर्ग के अनुपात में बदलता है, अतः भुजा 2a होने पर क्षेत्रफल (3√3/2)(2a)² = 4 × (3√3/2)a², अर्थात मूल का चार गुना हो जाता है। यह हर समतल आकृति पर लागू होता है: प्रत्येक लंबाई दोगुनी करने पर क्षेत्रफल 2² = 4 गुना (और आयतन 2³ = 8 गुना) हो जाता है। विकल्प '6 गुना बढ़ जाता है' गलत ढंग से 6 भुजाओं को गुणक से जोड़ता है।"},{"id":"c25s3-65","p":"c25s3","n":65,"s":"qa","t":"Mensuration","q":"A cylindrical storage container has a base radius of 3 cm. It is designed with sections whose heights form an arithmetic progression, starting from 2 cm for the bottom section and reaching 10 cm for the topmost section, covering a total of 5 sections. What is the total volume of the container? (Use π≈3.14)","w":"Five terms from 2 to 10 in an AP have common difference (10 − 2)/4 = 2, so the heights are 2, 4, 6, 8, 10 cm. Total height = n(a + l)/2 = 5 × (2 + 10)/2 = 30 cm. All sections share the radius 3 cm, so volume = πr²h = 3.14 × 9 × 30 = 847.8 cm³. The other options correspond to heights of 26.67, 33.33 and 40 cm.","o":["753.6 cm³","847.8 cm³","942.0 cm³","1130.4 cm³"],"a":[1],"qt":"एक बेलनाकार भंडारण पात्र की आधार त्रिज्या 3 सेमी है। इसे ऐसे खंडों में डिज़ाइन किया गया है जिनकी ऊँचाई एक अंकगणितीय क्रम में है, जो सबसे निचले भाग के लिए 2 सेमी से शुरू होकर सबसे ऊपरी भाग के लिए 10 सेमी तक है, और कुल 5 खंडों को कवर करती है। पात्र का कुल आयतन क्या है? (π≈3.14 का प्रयोग करें)","ot":["753.6 सेमी³","847.8 सेमी³","942.0 सेमी³","1130.4 सेमी³"],"wt":"2 से 10 तक के पाँच पदों वाली समांतर श्रेढ़ी का सार्व अंतर (10 − 2)/4 = 2 है, अतः ऊँचाइयाँ 2, 4, 6, 8, 10 सेमी हैं। कुल ऊँचाई = n(a + l)/2 = 5 × (2 + 10)/2 = 30 सेमी। सभी खंडों की त्रिज्या 3 सेमी है, अतः आयतन = πr²h = 3.14 × 9 × 30 = 847.8 सेमी³। अन्य विकल्प 26.67, 33.33 और 40 सेमी की कुल ऊँचाई के अनुरूप हैं।"},{"id":"c25s3-66","p":"c25s3","n":66,"s":"qa","t":"Algebra","q":"Find slope of line 7x + 4y = 8.","w":"Write the line in slope-intercept form y = mx + c: 4y = −7x + 8, so y = (−7/4)x + 2. Hence the slope m = −7/4. In general, the slope of ax + by + c = 0 is −a/b = −(coefficient of x)/(coefficient of y). The slope is negative here because both coefficients are positive. The option −4/7 inverts the ratio (b/a), and 4/7 is the slope of a line perpendicular to this one.","o":["−7/4","7/4","−4/7","4/7"],"a":[0],"qt":"7x + 4y = 8 रेखा का ढाल ज्ञात कीजिए","ot":["−7/4","7/4","−4/7","4/7"],"wt":"रेखा को ढाल-अंतःखंड रूप y = mx + c में लिखिए: 4y = −7x + 8, अतः y = (−7/4)x + 2। इसलिए ढाल m = −7/4। सामान्यतः ax + by + c = 0 का ढाल −a/b = −(x का गुणांक)/(y का गुणांक) होता है। यहाँ ढाल ऋणात्मक है क्योंकि दोनों गुणांक धनात्मक हैं। विकल्प −4/7 अनुपात को उलट देता है (b/a), और 4/7 इस रेखा पर लंबवत रेखा का ढाल है।"},{"id":"c25s3-67","p":"c25s3","n":67,"s":"qa","t":"Geometry","q":"What is the total sum of the exterior angles of any polygon, one at each vertex?","w":"At each vertex, interior angle + exterior angle = 180°. For an n-sided polygon the exterior angles add up to n × 180° − (n − 2) × 180° = 360°, whatever n is. Hence the sum is always 360°, which is why each exterior angle of a regular n-gon is 360°/n. It is the interior-angle sum, (n − 2) × 180°, that depends on the number of sides.","o":["180°","360°","Depends on the number of sides","540°"],"a":[1],"qt":"किसी बहुभुज के प्रत्येक शीर्ष पर एक बाह्य कोणों का कुल योग क्या होता है?","ot":["180°","360°","पक्षों की संख्या पर निर्भर करता है","540°"],"wt":"प्रत्येक शीर्ष पर, अंतः कोण + बाह्य कोण = 180°। n भुजाओं वाले बहुभुज के बाह्य कोणों का योग n × 180° − (n − 2) × 180° = 360° होता है, n चाहे जो भी हो। अतः योग सदैव 360° है, इसीलिए सम n-भुज का प्रत्येक बाह्य कोण 360°/n होता है। भुजाओं की संख्या पर तो अंतः कोणों का योग, (n − 2) × 180°, निर्भर करता है।"},{"id":"c25s3-68","p":"c25s3","n":68,"s":"qa","t":"Geometry","q":"In triangle ABC, medians AD, BE, and CF intersect at the Centroid G. If the area of triangle ABC is 60 cm², what is the area of triangle GBC?","w":"The centroid divides each median in the ratio 2 : 1, so GD = AD/3 and the height of △GBC from G to BC is one-third of the height of △ABC from A. With the same base BC, area of △GBC = (1/3) × 60 = 20 cm². In fact the three triangles GBC, GCA and GAB are equal, each one-third of △ABC. 10 cm² is the area of each of the six small triangles formed by the three medians.","o":["10 cm²","15 cm²","20 cm²","30 cm²"],"a":[2],"qt":"त्रिभुज ABC में, माध्यिकाएँ AD, BE और CF केन्द्रक G पर प्रतिच्छेद करती हैं। यदि त्रिभुज ABC का क्षेत्रफल 60 वर्ग सेमी है, तो त्रिभुज GBC का क्षेत्रफल क्या है?","ot":["10 cm²","15 cm²","20 cm²","30 cm²"],"wt":"केन्द्रक प्रत्येक माध्यिका को 2 : 1 के अनुपात में विभाजित करता है, अतः GD = AD/3 और G से BC पर △GBC की ऊँचाई, A से △ABC की ऊँचाई की एक-तिहाई है। आधार BC समान होने से △GBC का क्षेत्रफल = (1/3) × 60 = 20 वर्ग सेमी। वास्तव में तीनों त्रिभुज GBC, GCA और GAB बराबर हैं, प्रत्येक △ABC का एक-तिहाई। 10 वर्ग सेमी तीनों माध्यिकाओं से बने छह छोटे त्रिभुजों में से प्रत्येक का क्षेत्रफल है।"},{"id":"c25s3-69","p":"c25s3","n":69,"s":"qa","t":"Algebra","q":"Given, (√(5+x) + √(5−x))/(√(5+x) − √(5−x)) = 3, then what is the value of x?","w":"Apply componendo and dividendo: if (a + b)/(a − b) = 3/1, then a/b = (3 + 1)/(3 − 1) = 2. So √(5 + x) = 2√(5 − x); squaring, 5 + x = 4(5 − x) = 20 − 4x, so 5x = 15 and x = 3. Check: √8 = 2√2 and √2, giving (3√2)/(√2) = 3. With x = 4 the ratio is 2, not 3.","o":["3","4","5","2"],"a":[0],"qt":"दिया गया है, (√(5+x) + √(5−x))/(√(5+x) − √(5−x)) = 3, तो x का मान क्या है?","ot":["3","4","5","2"],"wt":"योगांतरानुपात (componendo and dividendo) लगाइए: यदि (a + b)/(a − b) = 3/1, तो a/b = (3 + 1)/(3 − 1) = 2। अतः √(5 + x) = 2√(5 − x); वर्ग करने पर 5 + x = 4(5 − x) = 20 − 4x, अतः 5x = 15 और x = 3। जाँच: √8 = 2√2 और √2, जिससे (3√2)/(√2) = 3। x = 4 पर अनुपात 2 आता है, 3 नहीं।"},{"id":"c25s3-70","p":"c25s3","n":70,"s":"qa","t":"Geometry","q":"Two circles have radii in the ratio 2 : 1. The length of a direct common tangent is 8 cm, and the distance between their centers is 10 cm. What is the radius of the smaller circle?","w":"Length of a direct common tangent = √(d² − (R − r)²). With radii 2r and r, R − r = r, so 8 = √(10² − r²), giving r² = 100 − 64 = 36 and r = 6 cm (the larger radius is 12 cm). Check: √(100 − 6²) = √64 = 8. Here R + r = 18 cm is more than d = 10 cm, so the circles overlap and have no transverse common tangent; a direct common tangent still exists because d is more than R − r = 6 cm.","o":["3 cm","4 cm","5 cm","6 cm"],"a":[3],"qt":"दो वृत्तों की त्रिज्याएँ इस अनुपात में हैं 2 : 1. एक सीधी उभयनिष्ठ स्पर्श रेखा की लंबाई है 8 सेमी, और उनके केंद्रों के बीच की दूरी है 10 सेमी. छोटे वृत्त की त्रिज्या क्या है?","ot":["3 सेमी","4 सेमी","5 सेमी","6 सेमी"],"wt":"सीधी उभयनिष्ठ स्पर्श रेखा की लंबाई = √(d² − (R − r)²)। त्रिज्याएँ 2r और r हों तो R − r = r, अतः 8 = √(10² − r²), जिससे r² = 100 − 64 = 36 और r = 6 सेमी (बड़ी त्रिज्या 12 सेमी)। जाँच: √(100 − 6²) = √64 = 8। यहाँ R + r = 18 सेमी, d = 10 सेमी से अधिक है, अतः वृत्त एक-दूसरे को काटते हैं और उनकी कोई अनुप्रस्थ उभयनिष्ठ स्पर्श रेखा नहीं होती; फिर भी सीधी उभयनिष्ठ स्पर्श रेखा होती है, क्योंकि d, R − r = 6 सेमी से अधिक है।"},{"id":"c25s3-71","p":"c25s3","n":71,"s":"qa","t":"Geometry","q":"In a circle having a radius 10 cm, a chord is 6 cm away from the center. Find the length of the chord.","w":"The perpendicular from the centre to a chord bisects it. In the right triangle formed by the radius (10 cm), the distance to the chord (6 cm) and half the chord, half chord = √(10² − 6²) = √(100 − 36) = √64 = 8 cm. So the chord is 2 × 8 = 16 cm. Forgetting to double the half-chord gives 8 cm, and 12 cm is just twice the distance.","o":["16 cm","12 cm","14 cm","18 cm"],"a":[0],"qt":"10 सेमी त्रिज्या वाले एक वृत्त में, एक जीवा केंद्र से 6 सेमी दूर है। जीवा की लंबाई ज्ञात कीजिए।","ot":["16 सेमी","12 सेमी","14 सेमी","18 सेमी"],"wt":"केंद्र से जीवा पर डाला गया लंब जीवा को समद्विभाजित करता है। त्रिज्या (10 सेमी), जीवा की केंद्र से दूरी (6 सेमी) और आधी जीवा से बने समकोण त्रिभुज में, आधी जीवा = √(10² − 6²) = √(100 − 36) = √64 = 8 सेमी। अतः जीवा = 2 × 8 = 16 सेमी। आधी जीवा को दोगुना करना भूल जाने पर 8 सेमी मिलता है, और 12 सेमी केवल दूरी का दोगुना है।"},{"id":"c25s3-72","p":"c25s3","n":72,"s":"qa","t":"Trigonometry & Heights","q":"If tan A + cot A = 4 and tan A · cot A = 1, find tan²A + sec²A.","w":"Let t = tan A, so t + 1/t = 4, i.e. t² − 4t + 1 = 0 and t = 2 ± √3. Taking t = 2 + √3 (A = 75°), t² = 7 + 4√3. Since sec²A = 1 + tan²A, the expression is 2t² + 1 = 2(7 + 4√3) + 1 = 15 + 8√3. The other root, t = 2 − √3 (A = 15°), gives 15 − 8√3, which is not an option. The condition tan A · cot A = 1 is always true and adds nothing.","o":["14 + 8√3","15 + 8√3","16 + 6√2","13 + 4√3"],"a":[1],"qt":"यदि tan A + cot A = 4 और tan A · cot A = 1, तो ज्ञात कीजिए tan²A + sec²A","ot":["14 + 8√3","15 + 8√3","16 + 6√2","13 + 4√3"],"wt":"मान लीजिए t = tan A, तब t + 1/t = 4, अर्थात t² − 4t + 1 = 0 और t = 2 ± √3। t = 2 + √3 (A = 75°) लेने पर t² = 7 + 4√3। चूँकि sec²A = 1 + tan²A, व्यंजक = 2t² + 1 = 2(7 + 4√3) + 1 = 15 + 8√3। दूसरा मूल t = 2 − √3 (A = 15°) 15 − 8√3 देता है, जो विकल्पों में नहीं है। शर्त tan A · cot A = 1 सदैव सत्य है और कोई नई जानकारी नहीं देती।"},{"id":"c25s3-73","p":"c25s3","n":73,"s":"qa","t":"Trigonometry & Heights","q":"If sin A = 2x/(1+x²), what is cos A?","w":"Take sin A = opposite/hypotenuse = 2x/(1 + x²). Then adjacent² = (1 + x²)² − (2x)² = 1 + 2x² + x⁴ − 4x² = (1 − x²)², so adjacent = 1 − x² and cos A = (1 − x²)/(1 + x²) (taking A acute and 0 < x < 1, as intended). This is the standard identity with x = tan(A/2). Option (1 + x²)/(1 − x²) is sec A, and 2x/(1 − x²) is tan A.","o":["(1+x²)/(1−x²)","(1−x²)/(1+x²)","2x/(1−x²)","(1−x²)/2x"],"a":[1],"qt":"sin A = 2x/(1+x²), cos A क्या है?","ot":["(1+x²)/(1−x²)","(1−x²)/(1+x²)","2x/(1−x²)","(1−x²)/2x"],"wt":"sin A = लंब/कर्ण = 2x/(1 + x²) लीजिए। तब आधार² = (1 + x²)² − (2x)² = 1 + 2x² + x⁴ − 4x² = (1 − x²)², अतः आधार = 1 − x² और cos A = (1 − x²)/(1 + x²) (A को न्यून कोण और 0 < x < 1 मानकर, जैसा प्रश्न का आशय है)। यह x = tan(A/2) वाली मानक सर्वसमिका है। विकल्प (1 + x²)/(1 − x²) sec A है, और 2x/(1 − x²) tan A है।"},{"id":"c25s3-74","p":"c25s3","n":74,"s":"qa","t":"Number System & Simplification","q":"Simplify: (0.25³ + 0.05³) ÷ (0.5³ + 0.1³)","w":"Note that 0.25 = 0.5 × 0.5 and 0.05 = 0.1 × 0.5, so the numerator is 0.5³ × (0.5³ + 0.1³). Dividing by (0.5³ + 0.1³) leaves 0.5³ = 0.125. Directly: numerator = 0.015625 + 0.000125 = 0.01575 and denominator = 0.125 + 0.001 = 0.126, and 0.01575/0.126 = 0.125. Option 0.5 is the common factor 0.5 not cubed, and 0.25 only squares it.","o":["0.25","0.125","0.5","0.75"],"a":[1],"qt":"सरल करें: (0.25³ + 0.05³) ÷ (0.5³ + 0.1³)","ot":["0.25","0.125","0.5","0.75"],"wt":"ध्यान दीजिए कि 0.25 = 0.5 × 0.5 और 0.05 = 0.1 × 0.5, अतः अंश = 0.5³ × (0.5³ + 0.1³)। (0.5³ + 0.1³) से भाग देने पर 0.5³ = 0.125 बचता है। सीधे: अंश = 0.015625 + 0.000125 = 0.01575 और हर = 0.125 + 0.001 = 0.126, तथा 0.01575/0.126 = 0.125। विकल्प 0.5 उभयनिष्ठ गुणनखंड 0.5 का घन नहीं लेता, और 0.25 केवल उसका वर्ग है।"},{"id":"c25s3-75","p":"c25s3","n":75,"s":"qa","t":"Number System & Simplification","q":"Find the value of (0.05³ + 0.005³) ÷ (0.25³ + 0.025³)","w":"Each term in the numerator is 1/5 of the matching term in the denominator: 0.05 = 0.25 × 1/5 and 0.005 = 0.025 × 1/5. So the numerator = (1/5)³ × (0.25³ + 0.025³), and the quotient is (1/5)³ = 1/125. Directly: 0.000125125 ÷ 0.015640625 = 0.008 = 1/125. Choosing 1/5 forgets to cube the common factor.","o":["1/5","1/25","1/125","1/625"],"a":[2],"qt":"(0.05³ + 0.005³) ÷ (0.25³ + 0.025³) का मान ज्ञात कीजिए","ot":["1/5","1/25","1/125","1/625"],"wt":"अंश का प्रत्येक पद हर के संगत पद का 1/5 है: 0.05 = 0.25 × 1/5 और 0.005 = 0.025 × 1/5। अतः अंश = (1/5)³ × (0.25³ + 0.025³), और भागफल = (1/5)³ = 1/125। सीधे: 0.000125125 ÷ 0.015640625 = 0.008 = 1/125। 1/5 चुनना उभयनिष्ठ गुणनखंड का घन लेना भूल जाना है।"},{"id":"c25s3-76","p":"c25s3","n":76,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word: COMPLAISANT","w":"'Complaisant' means willing to please others or to accept what they say or do without protest; obliging and compliant. Of the options, 'submissive' (ready to yield to the will of others) is the closest in meaning. Do not confuse it with 'complacent' (smugly self-satisfied). 'Insecure', 'anxious' and 'alert' describe uncertainty, worry or watchfulness, none of which conveys the readiness to oblige that complaisant expresses.","o":["Insecure","Anxious","Alert","Submissive"],"a":[3]},{"id":"c25s3-77","p":"c25s3","n":77,"s":"eng","t":"Vocabulary","q":"Select the most appropriate antonym of the given word. Opprobrium","w":"'Opprobrium' means harsh public criticism, or the disgrace and shame that come from bad conduct, as in 'The decision drew international opprobrium.' Its antonym is 'honor' (high respect, esteem and good reputation). 'Disgrace' and 'contempt' are near-synonyms of opprobrium, and 'censure' (strong formal disapproval) is also similar in meaning, so none of them can be its opposite.","o":["Disgrace","Contempt","Honor","Censure"],"a":[2]},{"id":"c25s3-78","p":"c25s3","n":78,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct meaning of idiom:\nThe sword of Damocles","w":"'The sword of Damocles' means a constant threat or imminent danger hanging over someone, especially one that comes with power or good fortune. In the Greek story told by Cicero, the courtier Damocles envied the tyrant Dionysius of Syracuse, who seated him at a banquet beneath a sword hung by a single horsehair to show how precarious a ruler's happiness is. Example: Debt hung over the firm like the sword of Damocles.","o":["A pleasant illusion","A constant threat hanging over someone","A royal invitation","A wise judgment"],"a":[1]},{"id":"c25s3-79","p":"c25s3","n":79,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct meaning of idiom:\nKeeps a good table","w":"To 'keep a good table' means to regularly serve generous, good-quality food to one's family and guests; here 'table' stands for the meals served at it. Example: Their grandmother always kept a good table, so relatives loved visiting her. The idiom says nothing about running a disciplined household, following religious rules or feeding the poor; it praises the quality and abundance of the food a host provides.","o":["Serves generous and high-quality meals","Maintains a disciplined home","Follows religious rules strictly","Provides food to the poor regularly"],"a":[0]},{"id":"c25s3-80","p":"c25s3","n":80,"s":"eng","t":"Spelling","q":"Which is the correct spelling of a word meaning 'clever or skillful'?","w":"'Adept' (a-d-e-p-t) is the correct spelling of the adjective meaning clever or skilful at something, as in 'She is adept at negotiation'; as a noun, an adept is an expert. 'Adapt' is a correctly spelt but different word meaning to adjust to new conditions, so it does not fit the meaning given. 'Addept' (double d) and 'Adeptt' (double t) are misspellings.","o":["Adept","Adapt","Addept","Adeptt"],"a":[0]},{"id":"c25s3-81","p":"c25s3","n":81,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct one-word substitution for: ‘One who lives entirely for pleasure’.","w":"'Epicure' comes from the Greek philosopher Epicurus, who taught that pleasure is the chief good of life. Merriam-Webster records its older sense, one devoted to sensual pleasure (a sybarite); today it usually means a person of refined taste in fine food and drink. 'Hedonist' and 'sybarite' are close synonyms. A 'hermit' lives alone in seclusion, a 'reveler' joins in a noisy celebration, and a 'glutton' simply eats and drinks too much, so none of them means one who lives for pleasure.","o":["Hermit","Reveler","Glutton","Epicure"],"a":[3]},{"id":"c25s3-82","p":"c25s3","n":82,"s":"eng","t":"Idioms & One-word Substitution","q":"Choose the correct one-word substitution for: ‘A person who believes in fate or destiny’.","w":"A 'fatalist' is a person who believes that all events are decided in advance by fate or destiny and cannot be changed by human effort; the belief is called fatalism. A 'dreamer' lives in imagination or pursues unrealistic plans, a 'realist' accepts situations as they are and deals with them practically, and an 'idealist' is guided by high ideals. Only 'fatalist' refers to belief in fate.","o":["Dreamer","Realist","Idealist","Fatalist"],"a":[3]},{"id":"c25s3-83","p":"c25s3","n":83,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Select the appropriate word form:\nThe policy's lack of clarity led to widespread ______.","w":"The blank follows the adjective 'widespread' and is the object of 'led to', so it needs a noun. The noun 'confusion' gives 'The policy's lack of clarity led to widespread confusion.' 'Confuse' is a verb, and 'confusing' and 'confused' are participles used as adjectives (a confusing policy, confused citizens), so none of them can stand after 'widespread' as the thing that the lack of clarity led to.","o":["confuse","confusing","confusion","confused"],"a":[2]},{"id":"c25s3-84","p":"c25s3","n":84,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Select the correct option:\nShe arrived at the interview ten minutes early, ______ showed professionalism.","w":"The blank begins a non-defining relative clause, after a comma, that refers to the whole previous clause (her arriving ten minutes early). Such a clause is introduced by 'which': 'She arrived at the interview ten minutes early, which showed professionalism.' 'That' cannot introduce a non-defining clause after a comma, 'what' means 'the thing that' and takes no antecedent, and 'this' would join two independent clauses with only a comma (a comma splice).","o":["what","which","that","this"],"a":[1]},{"id":"c25s3-85","p":"c25s3","n":85,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Find the part of the sentence that contains an error:\nThe CEO demanded that the report is submitted (1)/ to the board (2)/ not later than Wednesday afternoon (3)/ for immediate evaluation. (4)/","w":"Verbs of demand, command and suggestion such as demand, insist, recommend and propose are followed by a that-clause in the subjunctive: the base form of the verb, or should + base form. So part (1) should read 'The CEO demanded that the report be submitted' (or 'should be submitted'), not 'is submitted'. The other parts, 'to the board', 'not later than Wednesday afternoon' and 'for immediate evaluation', are correct.","o":["(1)","(2)","(3)","(4)"],"a":[0]},{"id":"c25s3-86","p":"c25s3","n":86,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Find the part of the sentence that contains an error:\nNo sooner had the proposal been circulated (1)/ that objections were raised (2)/ regarding its feasibility and financial implications (3)/ across all departments. (4)","w":"'No sooner' is always paired with 'than', never with 'that' or 'when': No sooner + had + subject + past participle ... than + simple past. The inversion 'No sooner had the proposal been circulated' in part (1) is correct, so the error is in part (2), which should read 'than objections were raised'. Parts (3) and (4), 'regarding its feasibility and financial implications across all departments', are correct.","o":["(1)","(2)","(3)","(4)"],"a":[1]},{"id":"c25s3-87","p":"c25s3","n":87,"s":"eng","t":"Voice & Narration","q":"Change the following from active to passive:\nThey feed the animals twice a day.","w":"'They feed' is in the simple present, so the passive takes is/are + past participle: the object 'the animals' becomes the subject with 'are', and 'feed' becomes 'fed'. The vague subject 'they' is dropped as the agent, giving 'The animals are fed twice a day.' Option 2 (were fed) is simple past, option 3 (are being fed) is present continuous and option 4 (have been fed) is present perfect, so each changes the tense.","o":["The animals are fed twice a day.","The animals were fed twice a day.","The animals are being fed twice a day.","The animals have been fed twice a day."],"a":[0]},{"id":"c25s3-88","p":"c25s3","n":88,"s":"eng","t":"Vocabulary","q":"Select the sentence containing the homonym of the highlighted word:\nThe cleric wore a silk \"amice\" over his alb during the liturgy.","w":"In the given sentence 'amice' is the liturgical vestment, a square of white linen worn by a priest on the neck and shoulders under the alb. A separate word 'amice' (a variant of almuce, from French aumusse) names a hood or hooded cape, an outer wrap. The novelist uses it in this sense for a scarf, so option 2 has the homonym. In options 1, 3 and 4 (the altar server, the bishop, the gold embroidery) it is still the church vestment.","o":["The altar server retrieved the amice from the vestry.","The novelist described her protagonist's scarf as an amice.","The bishop adjusted the amice before the blessing.","The amice was embroidered with gold thread."],"a":[1]},{"id":"c25s3-89","p":"c25s3","n":89,"s":"eng","t":"Voice & Narration","q":"Convert the sentence provided below from its passive voice structure to an active voice structure:\nThe draft is understood to have been reviewed by the legal department last week.","w":"The doer, 'the legal department', becomes the subject and 'the draft' becomes the object. The framing verb 'is understood' stays, and only the passive perfect infinitive 'to have been reviewed' changes to the active 'to have reviewed': 'The legal department is understood to have reviewed the draft last week.' Option 2 drops the doer and stays passive, option 3 changes the doer to 'the legal team' and the tenses, and option 4 is illogical.","o":["The legal department is understood to have reviewed the draft last week.","The draft was reviewed last week, as is understood.","It was understood the legal team is reviewing the draft.","The draft understood itself to be reviewed."],"a":[0]},{"id":"c25s3-90","p":"c25s3","n":90,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Choose the most suitable option to replace the highlighted part of the sentence:\nHe is \"having a car\" for five years.","w":"'For five years' shows a state that began in the past and continues to the present, which needs the present perfect: 'He has had a car for five years.' 'Have' meaning possess is a stative verb and is not used in continuous tenses, so 'is having' is wrong. The simple present 'has' cannot express duration up to now with 'for', and the simple past 'had' would mean he no longer owns the car.","o":["has","had","has had","is having"],"a":[2]},{"id":"c25s3-91","p":"c25s3","n":91,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Choose the most suitable option to replace the highlighted part of the sentence:\nHe worked very hard \"lest he may fail\".","w":"'Lest' means 'for fear that' or 'in order that ... not'. It is already negative and is followed by 'should' + base verb (or the bare subjunctive, 'lest he fail'), never by may, might or not. So the correct form is 'He worked very hard lest he should fail.' 'In order that he does not fail' and 'so that he did not fail' do not suit a past purpose clause (they need 'might not' or 'would not'), and 'for not failing' is unidiomatic.","o":["in order that he does not fail","for not failing","lest he should fail","so that he did not fail"],"a":[2]},{"id":"c25s3-92","p":"c25s3","n":92,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn the tapestry of human civilization, communication functions as the warp thread—a foundational axis around which all societal patterns are woven. Far from being a mere conduit of information, communication embodies the dynamic interplay of perception, cognition, intention, and empathy. The profound necessity of communication arises not solely from the need to disseminate knowledge or coordinate actions, but from the imperative to construct meaning, cultivate understanding, and negotiate the complex terrain of human relationships. Historically, communication has been the catalytic force behind societal transformation—from the oral traditions that preserved mythological cosmologies to the written word that enabled legal systems and codified morality. The printing press, the telegraph, and now digital media are not just technological milestones; they are paradigmatic shifts in the communicative capacity of humankind. Each advancement has not only expanded the velocity and reach of messages but has also redefined the epistemological contours of truth, authority, and discourse. At the interpersonal level, communication is far from unidirectional. It encompasses verbal, non-verbal, and paralinguistic dimensions that function in concert to convey nuance and intention. Eye contact, silence, body posture, and even prosody become carriers of latent meaning—often transcending the spoken word. The failure to decode or acknowledge these layers frequently leads to misapprehension, conflict, or alienation. Thus, effective communication is not merely the transmission of speech, but the art of calibrated expression and attentive reception. In professional and organizational contexts, the strategic deployment of communication is pivotal. It determines leadership efficacy, influences team cohesion, and governs decision-making processes. Hierarchical structures often obfuscate open communication, resulting in informational asymmetries and the erosion of institutional trust. In contrast, transparent, dialogic, and inclusive communication frameworks nurture a culture of accountability and innovation. Cultural semiotics also shape communication, embedding within language a constellation of values, assumptions, and power dynamics. What is deemed assertive in one cultural matrix may be interpreted as aggressive in another. Consequently, intercultural communication necessitates a heightened awareness of contextual sensitivity, linguistic pluralism, and implicit biases. In an era marked by algorithmic echo chambers and hyper-mediated realities, the ethical imperative of responsible communication becomes paramount. The virality of misinformation, the commodification of attention, and the erosion of discourse norms threaten the democratic fabric of societies. Hence, communicative competence today must be coupled with critical media literacy, epistemic humility, and ethical discernment. Ultimately, communication is not ancillary to human existence—it is constitutive of it. To communicate is to assert presence, to co-create reality, and to engage in the continuous reconstitution of the social world. In its highest form, communication becomes a moral act: a commitment to understanding, mutuality, and the transcendence of solipsism.\nWhich of the following best encapsulates the primary thesis of the passage?","w":"The passage argues that communication is not a mere channel for information but the basis of social life: it constructs meaning, shapes relationships and institutions, and 'is not ancillary to human existence—it is constitutive of it', since to communicate is 'to co-create reality'. So it is foundational to constructing shared human realities. Option 1 contradicts 'Far from being a mere conduit of information', option 2 is too narrow, and option 4 is never argued.","o":["Communication is a tool for fast information delivery.","It is an act of linguistic persuasion.","Communication is foundational to constructing shared human realities.","It functions primarily as a cultural symbol across civilizations."],"a":[2]},{"id":"c25s3-93","p":"c25s3","n":93,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn the tapestry of human civilization, communication functions as the warp thread—a foundational axis around which all societal patterns are woven. Far from being a mere conduit of information, communication embodies the dynamic interplay of perception, cognition, intention, and empathy. The profound necessity of communication arises not solely from the need to disseminate knowledge or coordinate actions, but from the imperative to construct meaning, cultivate understanding, and negotiate the complex terrain of human relationships. Historically, communication has been the catalytic force behind societal transformation—from the oral traditions that preserved mythological cosmologies to the written word that enabled legal systems and codified morality. The printing press, the telegraph, and now digital media are not just technological milestones; they are paradigmatic shifts in the communicative capacity of humankind. Each advancement has not only expanded the velocity and reach of messages but has also redefined the epistemological contours of truth, authority, and discourse. At the interpersonal level, communication is far from unidirectional. It encompasses verbal, non-verbal, and paralinguistic dimensions that function in concert to convey nuance and intention. Eye contact, silence, body posture, and even prosody become carriers of latent meaning—often transcending the spoken word. The failure to decode or acknowledge these layers frequently leads to misapprehension, conflict, or alienation. Thus, effective communication is not merely the transmission of speech, but the art of calibrated expression and attentive reception. In professional and organizational contexts, the strategic deployment of communication is pivotal. It determines leadership efficacy, influences team cohesion, and governs decision-making processes. Hierarchical structures often obfuscate open communication, resulting in informational asymmetries and the erosion of institutional trust. In contrast, transparent, dialogic, and inclusive communication frameworks nurture a culture of accountability and innovation. Cultural semiotics also shape communication, embedding within language a constellation of values, assumptions, and power dynamics. What is deemed assertive in one cultural matrix may be interpreted as aggressive in another. Consequently, intercultural communication necessitates a heightened awareness of contextual sensitivity, linguistic pluralism, and implicit biases. In an era marked by algorithmic echo chambers and hyper-mediated realities, the ethical imperative of responsible communication becomes paramount. The virality of misinformation, the commodification of attention, and the erosion of discourse norms threaten the democratic fabric of societies. Hence, communicative competence today must be coupled with critical media literacy, epistemic humility, and ethical discernment. Ultimately, communication is not ancillary to human existence—it is constitutive of it. To communicate is to assert presence, to co-create reality, and to engage in the continuous reconstitution of the social world. In its highest form, communication becomes a moral act: a commitment to understanding, mutuality, and the transcendence of solipsism.\nIn the context of intercultural communication, what is implied by the phrase “constellation of values”?","w":"The passage says cultural semiotics embed 'within language a constellation of values, assumptions, and power dynamics', and adds that what is assertive in one culture may seem aggressive in another. Like stars in a constellation, these values form an interlinked pattern, so communication carries embedded assumptions and norms shaped by culture. Option 1 takes the metaphor literally, option 2 contradicts the interlinked pattern the word suggests, and option 3 contradicts the idea that culture shapes communication.","o":["Cultures are astronomically defined.","Values are isolated and static in different cultures.","Communication patterns are random across cultures.","Communication carries embedded assumptions and norms shaped by culture."],"a":[3]},{"id":"c25s3-94","p":"c25s3","n":94,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn the tapestry of human civilization, communication functions as the warp thread—a foundational axis around which all societal patterns are woven. Far from being a mere conduit of information, communication embodies the dynamic interplay of perception, cognition, intention, and empathy. The profound necessity of communication arises not solely from the need to disseminate knowledge or coordinate actions, but from the imperative to construct meaning, cultivate understanding, and negotiate the complex terrain of human relationships. Historically, communication has been the catalytic force behind societal transformation—from the oral traditions that preserved mythological cosmologies to the written word that enabled legal systems and codified morality. The printing press, the telegraph, and now digital media are not just technological milestones; they are paradigmatic shifts in the communicative capacity of humankind. Each advancement has not only expanded the velocity and reach of messages but has also redefined the epistemological contours of truth, authority, and discourse. At the interpersonal level, communication is far from unidirectional. It encompasses verbal, non-verbal, and paralinguistic dimensions that function in concert to convey nuance and intention. Eye contact, silence, body posture, and even prosody become carriers of latent meaning—often transcending the spoken word. The failure to decode or acknowledge these layers frequently leads to misapprehension, conflict, or alienation. Thus, effective communication is not merely the transmission of speech, but the art of calibrated expression and attentive reception. In professional and organizational contexts, the strategic deployment of communication is pivotal. It determines leadership efficacy, influences team cohesion, and governs decision-making processes. Hierarchical structures often obfuscate open communication, resulting in informational asymmetries and the erosion of institutional trust. In contrast, transparent, dialogic, and inclusive communication frameworks nurture a culture of accountability and innovation. Cultural semiotics also shape communication, embedding within language a constellation of values, assumptions, and power dynamics. What is deemed assertive in one cultural matrix may be interpreted as aggressive in another. Consequently, intercultural communication necessitates a heightened awareness of contextual sensitivity, linguistic pluralism, and implicit biases. In an era marked by algorithmic echo chambers and hyper-mediated realities, the ethical imperative of responsible communication becomes paramount. The virality of misinformation, the commodification of attention, and the erosion of discourse norms threaten the democratic fabric of societies. Hence, communicative competence today must be coupled with critical media literacy, epistemic humility, and ethical discernment. Ultimately, communication is not ancillary to human existence—it is constitutive of it. To communicate is to assert presence, to co-create reality, and to engage in the continuous reconstitution of the social world. In its highest form, communication becomes a moral act: a commitment to understanding, mutuality, and the transcendence of solipsism.\nAccording to the passage, what role do non-verbal cues primarily serve in interpersonal communication?","w":"The passage says communication 'encompasses verbal, non-verbal, and paralinguistic dimensions that function in concert to convey nuance and intention', and that eye contact, silence, body posture and prosody 'become carriers of latent meaning—often transcending the spoken word'. So non-verbal cues convey subtle or latent meanings beyond words. Because they work together with speech, they neither replace it entirely nor are mere embellishments, and the passage never calls them irrelevant in professional contexts.","o":["They replace verbal communication entirely.","They act as secondary embellishments.","They convey subtle or latent meanings often missed by verbal speech.","They are irrelevant in professional contexts."],"a":[2]},{"id":"c25s3-95","p":"c25s3","n":95,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn the tapestry of human civilization, communication functions as the warp thread—a foundational axis around which all societal patterns are woven. Far from being a mere conduit of information, communication embodies the dynamic interplay of perception, cognition, intention, and empathy. The profound necessity of communication arises not solely from the need to disseminate knowledge or coordinate actions, but from the imperative to construct meaning, cultivate understanding, and negotiate the complex terrain of human relationships. Historically, communication has been the catalytic force behind societal transformation—from the oral traditions that preserved mythological cosmologies to the written word that enabled legal systems and codified morality. The printing press, the telegraph, and now digital media are not just technological milestones; they are paradigmatic shifts in the communicative capacity of humankind. Each advancement has not only expanded the velocity and reach of messages but has also redefined the epistemological contours of truth, authority, and discourse. At the interpersonal level, communication is far from unidirectional. It encompasses verbal, non-verbal, and paralinguistic dimensions that function in concert to convey nuance and intention. Eye contact, silence, body posture, and even prosody become carriers of latent meaning—often transcending the spoken word. The failure to decode or acknowledge these layers frequently leads to misapprehension, conflict, or alienation. Thus, effective communication is not merely the transmission of speech, but the art of calibrated expression and attentive reception. In professional and organizational contexts, the strategic deployment of communication is pivotal. It determines leadership efficacy, influences team cohesion, and governs decision-making processes. Hierarchical structures often obfuscate open communication, resulting in informational asymmetries and the erosion of institutional trust. In contrast, transparent, dialogic, and inclusive communication frameworks nurture a culture of accountability and innovation. Cultural semiotics also shape communication, embedding within language a constellation of values, assumptions, and power dynamics. What is deemed assertive in one cultural matrix may be interpreted as aggressive in another. Consequently, intercultural communication necessitates a heightened awareness of contextual sensitivity, linguistic pluralism, and implicit biases. In an era marked by algorithmic echo chambers and hyper-mediated realities, the ethical imperative of responsible communication becomes paramount. The virality of misinformation, the commodification of attention, and the erosion of discourse norms threaten the democratic fabric of societies. Hence, communicative competence today must be coupled with critical media literacy, epistemic humility, and ethical discernment. Ultimately, communication is not ancillary to human existence—it is constitutive of it. To communicate is to assert presence, to co-create reality, and to engage in the continuous reconstitution of the social world. In its highest form, communication becomes a moral act: a commitment to understanding, mutuality, and the transcendence of solipsism.\nWhat does the passage suggest is the consequence of informational asymmetry within hierarchical institutions?","w":"The passage states that 'Hierarchical structures often obfuscate open communication, resulting in informational asymmetries and the erosion of institutional trust', and contrasts this with transparent, dialogic frameworks that nurture accountability. So informational asymmetry goes with the erosion of trust and a breakdown of open communication. The passage does not credit hierarchy with higher productivity or faster decisions, and decentralisation is the opposite of the hierarchical structures it describes.","o":["Increased productivity due to streamlined authority.","Erosion of institutional trust and communication breakdown.","Faster decision-making due to lack of dissent.","Decentralization of organizational roles."],"a":[1]},{"id":"c25s3-96","p":"c25s3","n":96,"s":"eng","t":"Reading Comprehension","q":"Read the following passage and answer the questions based on the passage :\nIn the tapestry of human civilization, communication functions as the warp thread—a foundational axis around which all societal patterns are woven. Far from being a mere conduit of information, communication embodies the dynamic interplay of perception, cognition, intention, and empathy. The profound necessity of communication arises not solely from the need to disseminate knowledge or coordinate actions, but from the imperative to construct meaning, cultivate understanding, and negotiate the complex terrain of human relationships. Historically, communication has been the catalytic force behind societal transformation—from the oral traditions that preserved mythological cosmologies to the written word that enabled legal systems and codified morality. The printing press, the telegraph, and now digital media are not just technological milestones; they are paradigmatic shifts in the communicative capacity of humankind. Each advancement has not only expanded the velocity and reach of messages but has also redefined the epistemological contours of truth, authority, and discourse. At the interpersonal level, communication is far from unidirectional. It encompasses verbal, non-verbal, and paralinguistic dimensions that function in concert to convey nuance and intention. Eye contact, silence, body posture, and even prosody become carriers of latent meaning—often transcending the spoken word. The failure to decode or acknowledge these layers frequently leads to misapprehension, conflict, or alienation. Thus, effective communication is not merely the transmission of speech, but the art of calibrated expression and attentive reception. In professional and organizational contexts, the strategic deployment of communication is pivotal. It determines leadership efficacy, influences team cohesion, and governs decision-making processes. Hierarchical structures often obfuscate open communication, resulting in informational asymmetries and the erosion of institutional trust. In contrast, transparent, dialogic, and inclusive communication frameworks nurture a culture of accountability and innovation. Cultural semiotics also shape communication, embedding within language a constellation of values, assumptions, and power dynamics. What is deemed assertive in one cultural matrix may be interpreted as aggressive in another. Consequently, intercultural communication necessitates a heightened awareness of contextual sensitivity, linguistic pluralism, and implicit biases. In an era marked by algorithmic echo chambers and hyper-mediated realities, the ethical imperative of responsible communication becomes paramount. The virality of misinformation, the commodification of attention, and the erosion of discourse norms threaten the democratic fabric of societies. Hence, communicative competence today must be coupled with critical media literacy, epistemic humility, and ethical discernment. Ultimately, communication is not ancillary to human existence—it is constitutive of it. To communicate is to assert presence, to co-create reality, and to engage in the continuous reconstitution of the social world. In its highest form, communication becomes a moral act: a commitment to understanding, mutuality, and the transcendence of solipsism.\nThe phrase “epistemic humility” in the passage most likely refers to which of the following?","w":"'Epistemic' means relating to knowledge, so 'epistemic humility' is the recognition that one's own knowledge and views are limited and may be wrong, with openness to other perspectives. The passage lists it with critical media literacy and ethical discernment as part of the communicative competence needed in an age of misinformation and echo chambers. Option 2 is the opposite of humility, option 1 confuses humility with silence, and option 4 is not discussed.","o":["Reluctance to speak in public discourse.","Acceptance of one’s cultural superiority.","Awareness of the limits of one’s knowledge in communicative contexts.","Dependence on traditional forms of communication."],"a":[2]},{"id":"c25s3-97","p":"c25s3","n":97,"s":"eng","t":"Voice & Narration","q":"Select the correct option for the Direct Speech conversion of the sentence below.\nHe remarked that the sculpture would have commanded greater gravitas had the pedestal been proportionally austere.","w":"The reported clause is an inverted third conditional: 'had the pedestal been proportionally austere' with 'would have commanded' in the main clause. Unreal past conditionals keep their tenses in reported speech, so the direct form puts the same words in quotation marks after 'He said'. Option 2 turns it into a real present condition, option 3 wrongly mixes 'will command' with 'had been', and option 4 uses 'must have' and drops 'proportionally'.","o":["He said, \"The sculpture would have commanded greater gravitas had the pedestal been proportionally austere.\"","He said, \"If the pedestal is proportionally austere, the sculpture commands greater gravitas.\"","He said, \"The sculpture will command greater gravitas if the pedestal had been austere.\"","He said, \"Had the pedestal been austere, the sculpture must have commanded greater gravitas.\""],"a":[0]},{"id":"c25s3-98","p":"c25s3","n":98,"s":"eng","t":"Voice & Narration","q":"A sentence is provided in direct speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding indirect speech.\nShe said, “Why did you lie to me?”","w":"In reporting a question, 'said' becomes 'asked', the question word 'why' joins the clauses, and question order changes to statement order (subject + verb), so the auxiliary 'did' goes. The simple past 'did lie' backshifts to the past perfect 'had lied', 'you' becomes 'I' (the person addressed is reporting) and 'me' becomes 'her': 'She asked why I had lied to her.' Option 1 lacks the backshift, and options 3 and 4 keep question word order.","o":["She asked why I lied to her.","She asked why I had lied to her.","She asked why had I lied to her.","She asked why did I lie to her."],"a":[1]},{"id":"c25s3-99","p":"c25s3","n":99,"s":"eng","t":"Sentence Arrangement","q":"Rearrange the following sentences to form a meaningful passage:\n1. Machine learning models require large datasets to train.\n2. Data preprocessing ensures that the input is clean and formatted correctly.\n3. The model is tested to evaluate its accuracy.\n4. Once trained, the model can be deployed for real-world applications.","w":"The key's order 2-1-3-4 follows the stages of a machine learning workflow: data preprocessing first prepares clean, correctly formatted input (2), the models are then trained on large datasets (1), the trained model is tested for accuracy (3), and finally it is deployed for real-world use (4). However, sentence 1 introduces the topic and the datasets that 'the input' in sentence 2 refers to, so 1-2-3-4 also reads naturally. (SSC key; some sources differ.)","o":["2-1-3-4","3-1-2-4","1-2-3-4","4-3-2-1"],"a":[0]},{"id":"c25s3-100","p":"c25s3","n":100,"s":"eng","t":"Sentence Arrangement","q":"Rearrange the following sentences in correct order to make a logical passage.\n1. The first step is to recognize unhealthy patterns.\n2. Breaking bad habits requires discipline and self-awareness.\n3. Seeking support from friends or professionals can be helpful.\n4. Consistency in applying new behaviors is key to lasting change.","w":"Sentence 2 introduces the topic: breaking bad habits requires discipline and self-awareness. Sentence 1, 'The first step is to recognize unhealthy patterns', begins the process and reflects that self-awareness. Sentence 3 adds a further aid, seeking support from friends or professionals, and sentence 4 concludes that consistency is the key to lasting change. The order is 2-1-3-4. Option 4 (2-3-1-4) fails because 'the first step' must come straight after the introduction.","o":["2-1-3-4","2-4-1-3","3-4-2-1","2-3-1-4"],"a":[0]},{"id":"c24s1-1","p":"c24s1","n":1,"s":"rea","t":"Mathematical Operations","q":"What will come in place of the question mark (?) in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged?\n4515 × 5 − 431 ÷ 3 + 821 = ?","w":"Make the interchanges first: × becomes ÷, − becomes +, ÷ becomes × and + becomes −. The equation reads 4515 ÷ 5 + 431 × 3 − 821. By BODMAS, do division and multiplication first: 4515 ÷ 5 = 903 and 431 × 3 = 1293. Then 903 + 1293 = 2196, and 2196 − 821 = 1375. A common slip is to change only one pair of signs, which gives a different total.","o":["1335","1775","1575","1375"],"a":[3],"qt":"यदि ‘+’ और ‘−’ को आपस में बदल दिया जाए और ‘×’ और ‘÷’ को आपस में बदल दिया जाए, तो निम्नलिखित समीकरण में प्रश्न चिह्न (?) के स्थान पर क्या आएगा?\n4515 × 5 − 431 ÷ 3 + 821 = ?","ot":["1335","1775","1575","1375"],"wt":"पहले चिह्नों को आपस में बदलें: × के स्थान पर ÷, − के स्थान पर +, ÷ के स्थान पर × और + के स्थान पर − आएगा। समीकरण बनता है 4515 ÷ 5 + 431 × 3 − 821। BODMAS के अनुसार पहले भाग और गुणा करें: 4515 ÷ 5 = 903 और 431 × 3 = 1293। फिर 903 + 1293 = 2196 और 2196 − 821 = 1375। केवल एक जोड़ी चिह्न बदलना एक आम गलती है, जिससे अलग उत्तर आता है।"},{"id":"c24s1-2","p":"c24s1","n":2,"s":"rea","t":"Analogy & Classification","q":"31 is related to 152 by certain logic. Following the same logic, 47 is related to 168. To which of the following is 66 related, following the same logic? (NOTE : Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding /deleting /multiplying etc., to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.)","w":"Find the difference in each given pair: 152 − 31 = 121 and 168 − 47 = 121. So the rule is \"add 121\" (121 = 11²) to the first number. Applying it to 66: 66 + 121 = 187. The other options give differences of 114 (180), 119 (185) and 124 (190), which do not fit the rule.","o":["180","187","185","190"],"a":[1],"qt":"31 एक निश्चित तर्क का अनुसरण करते हुए 152 से संबंधित है। इसी तर्क का अनुसरण करते हुए 47, 168 से संबंधित है। समान तर्क का अनुसरण करते हुए, 66 निम्नलिखित में से किससे संबंधित है? नोट: संख्याओं को उनके घटक अंकों में विभक्त किए बिना पूर्ण संख्याओं पर संक्रियाएं की जानी चाहिए। उदाहरण के लिए 13 को लें- 13 पर संक्रियाएं, जैसे कि जोड़ना/घटाना/गुणा आदि 13 में की जा सकती हैं। 13 को 1 और 3 में विभक्त करना और फिर 1 और 3 पर गणितीय संक्रियाएं करने की अनुमति नहीं है।","ot":["180","187","185","190"],"wt":"प्रत्येक दिए गए युग्म में अंतर ज्ञात करें: 152 − 31 = 121 और 168 − 47 = 121। अतः नियम है पहली संख्या में 121 (121 = 11²) जोड़ना। 66 पर यही नियम लगाने पर: 66 + 121 = 187। अन्य विकल्पों में अंतर 114 (180), 119 (185) और 124 (190) आता है, जो इस नियम में नहीं बैठते।"},{"id":"c24s1-3","p":"c24s1","n":3,"s":"rea","t":"Non-verbal Reasoning","q":"Six letters Q, Z, V, T, L and A are written on different faces of a dice. Two positions of this dice are shown in the figures below. Find the letter on the face opposite to Q.","w":"V is common to both positions and sits on the same (right) face in both, so the dice has only been turned about the axis through V. When the common face is in the same position, the faces in matching positions are opposite: top Q is opposite top T, and left Z is opposite left L. V touches Q, Z, T and L, so V is opposite A. Hence the letter opposite Q is T.","img":"data:image/png;base64,","o":["Z","T","V","A"],"a":[1],"qt":"एक पासे के विभिन्न फलकों पर छह अक्षर Q, Z, V, T, L और A लिखे गए हैं। इस पासे की दो स्थितियाँ नीचे चित्र में दर्शाई गई हैं। Q के विपरीत वाले फलक पर आने वाला अक्षर ज्ञात कीजिए।","ot":["Z","T","V","A"],"wt":"V दोनों स्थितियों में उभयनिष्ठ है और दोनों में एक ही (दाएँ) फलक पर है, अतः पासे को केवल V से होकर जाने वाले अक्ष के चारों ओर घुमाया गया है। जब उभयनिष्ठ फलक एक ही स्थान पर हो, तो समान स्थानों वाले फलक एक-दूसरे के विपरीत होते हैं: ऊपर का Q ऊपर के T के विपरीत है और बाएँ का Z बाएँ के L के विपरीत है। V, Q, Z, T और L को छूता है, अतः V के विपरीत A है। इसलिए Q के विपरीत अक्षर T है।"},{"id":"c24s1-4","p":"c24s1","n":4,"s":"rea","t":"Analogy & Classification","q":"In the following number-pairs, the second number is obtained by applying certain mathematical operations to the first number. In three of the four pairs, the same pattern is applied and hence they form a group. Select the number-pair that DOES NOT belong to this group.\n(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into their constituent digits. E.g. 13 – Operations on 13 such as adding/subtracting/multiplying to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.)","w":"Subtract the second number from the first in each pair. 335 − 119 = 216, 317 − 101 = 216 and 308 − 92 = 216, so the rule is \"subtract 216\" (216 = 6³). For 358 − 152 the difference is 206, not 216; following the rule, 358 should give 142. So the pair 358 - 152 does not belong to the group.","o":["335 - 119","358 - 152","317 - 101","308 - 92"],"a":[1],"qt":"निम्नलिखित संख्या-युग्मों में, पहली संख्या पर कुछ गणितीय संक्रियाएँ लागू करके दूसरी संख्या प्राप्त की जाती है। चार में से तीन युग्मों में, समान स्वरूप लागू किया गया है और इसलिए वे एक समूह बनाते हैं। उस संख्या-युग्म का चयन कीजिए जो इस समूह से संबंधित नहीं है।\n(नोट: संख्याओं को उनके घटक अंकों में विभक्त किए बिना पूर्ण संख्याओं पर संक्रियाएँ की जानी चाहिए। उदाहरण के लिए, 13 को लीजिए – 13 पर संक्रियाएँ, जैसे कि 13 में जोड़ना/घटाना/गुणा करना आदि, की जा सकती हैं। 13 को 1 और 3 में विभक्त करने और फिर 1 और 3 पर गणितीय संक्रियाएँ करने की अनुमति नहीं है।)","ot":["335 - 119","358 - 152","317 - 101","308 - 92"],"wt":"प्रत्येक युग्म में पहली संख्या से दूसरी संख्या घटाएँ। 335 − 119 = 216, 317 − 101 = 216 और 308 − 92 = 216, अतः नियम है ‘216 घटाना’ (216 = 6³)। 358 - 152 में अंतर 206 है, 216 नहीं; नियम के अनुसार 358 से 142 मिलना चाहिए। अतः युग्म 358 - 152 इस समूह से संबंधित नहीं है।"},{"id":"c24s1-5","p":"c24s1","n":5,"s":"rea","t":"Coding-Decoding","q":"In a certain code language, 'NAME’ is written as 'FNBO' and 'NANO' is written as 'POBO’. How will 'NAIL’ be written in that language?","w":"Write the word in reverse order and then move each letter one step forward. NAME reversed is EMAN; +1 gives FNBO. NANO reversed is ONAN; +1 gives POBO. So NAIL reversed is LIAN, and +1 on each letter gives L→M, I→J, A→B, N→O, that is MJBO. The other options use the right letters in a wrong order.","o":["MOBJ","MJOB","MOJB","MJBO"],"a":[3],"qt":"एक निश्चित कूट भाषा में, 'NAME’ को 'FNBO' लिखा जाता है और ‘NANO' को 'POBO’ लिखा जाता है। इसी कूट भाषा में 'NAIL’ को किस प्रकार लिखा जाएगा?","ot":["MOBJ","MJOB","MOJB","MJBO"],"wt":"शब्द को उल्टे क्रम में लिखें और फिर प्रत्येक अक्षर को एक स्थान आगे बढ़ाएँ। NAME उल्टे क्रम में EMAN है; +1 करने पर FNBO मिलता है। NANO उल्टे क्रम में ONAN है; +1 करने पर POBO मिलता है। अतः NAIL उल्टे क्रम में LIAN है, और प्रत्येक अक्षर में +1 करने पर L→M, I→J, A→B, N→O, अर्थात MJBO। अन्य विकल्पों में सही अक्षर गलत क्रम में हैं।"},{"id":"c24s1-6","p":"c24s1","n":6,"s":"rea","t":"Analogy & Classification","q":"The question contains pairs of words that are related to each other in a certain way. Three of the following four word pairs are alike as these have the same relationship and thus form a group. Which word pair is the one that DOES NOT belong to that group?\n(The words must be considered as meaningful English words and must not be related to each other based on the number of letters/number of consonants/vowels in the word.)","w":"Each pair matches a polygon with its number of sides. A pentagon has 5 sides, a triangle 3 and a square 4, so these three pairs are correct. A hexagon has 6 sides (hexa = six); 8 sides belong to an octagon. So \"Hexagon - 8 sides\" breaks the relationship and is the odd pair.","o":["Pentagon - 5 sides","Hexagon - 8 sides","Triangle - 3 sides","Square - 4 sides"],"a":[1],"qt":"प्रश्न में ऐसे शब्द युग्म हैं जो एक निश्चित तरीके से एक-दूसरे से संबंधित हैं। निम्नलिखित चार शब्द युग्मों में से तीन शब्द युग्म एक समान हैं क्योंकि इनमें संबंध समान है और इस प्रकार वे एक समूह बनाते हैं। निम्नलिखित में से कौन-सा शब्द युग्म उस समूह से संबंधित नहीं है?\n(शब्दों को अर्थपूर्ण अंग्रेजी/हिंदी शब्द माना जाना चाहिए और शब्द में अक्षरों / व्यंजनों / स्वरों की संख्या के आधार पर एक-दूसरे से संबंधित नहीं होने चाहिए।)","ot":["पंचभुज - 5 भुजाएँ","षट्भुज - 8 भुजाएँ","त्रिभुज - 3 भुजाएँ","वर्ग - 4 भुजाएँ"],"wt":"प्रत्येक युग्म में एक बहुभुज और उसकी भुजाओं की संख्या दी गई है। पंचभुज की 5, त्रिभुज की 3 और वर्ग की 4 भुजाएँ होती हैं, अतः ये तीनों युग्म सही हैं। षट्भुज की 6 भुजाएँ होती हैं (षट् = छह); 8 भुजाएँ अष्टभुज की होती हैं। अतः ‘षट्भुज - 8 भुजाएँ’ इस संबंध को तोड़ता है और यही भिन्न युग्म है।"},{"id":"c24s1-7","p":"c24s1","n":7,"s":"rea","t":"Miscellaneous Reasoning","q":"The position of how many letters will remain unchanged if each of the letters in the word ‘NIGHTMARES’ is re-arranged in the English alphabetical order from left to right?","w":"Write the word and its letters in alphabetical order one under the other. NIGHTMARES: N I G H T M A R E S. Alphabetical: A E G H I M N R S T. Compare position by position: 3rd G = G, 4th H = H, 6th M = M and 8th R = R; all other positions differ. So the positions of four letters (G, H, M and R) remain unchanged.","o":["One","Four","Two","Three"],"a":[1],"qt":"यदि शब्द ‘NIGHTMARES’ के प्रत्येक अक्षर को अंग्रेजी वर्णमाला के क्रम में बाएँ से दाएँ पुनर्व्यवस्थित किया जाए तो कितने अक्षरों की स्थिति अपरिवर्तित रहेगी?","ot":["एक","चार","दो","तीन"],"wt":"शब्द और उसके अक्षरों का वर्णानुक्रम एक-दूसरे के नीचे लिखें। NIGHTMARES: N I G H T M A R E S। वर्णानुक्रम: A E G H I M N R S T। स्थान-दर-स्थान तुलना करें: तीसरा G = G, चौथा H = H, छठा M = M और आठवाँ R = R; अन्य सभी स्थान भिन्न हैं। अतः चार अक्षरों (G, H, M और R) की स्थिति अपरिवर्तित रहती है।"},{"id":"c24s1-8","p":"c24s1","n":8,"s":"rea","t":"Mathematical Operations","q":"What will come in the place of ‘?’ in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged?\n5 − 4 ÷ 9 + 80 × 10 = ?","w":"After the interchanges, − becomes +, ÷ becomes ×, + becomes − and × becomes ÷. The equation becomes 5 + 4 × 9 − 80 ÷ 10. Apply BODMAS: 4 × 9 = 36 and 80 ÷ 10 = 8. Then 5 + 36 − 8 = 33. Solving without following BODMAS (left to right) would give a wrong value.","o":["31","33","35","30"],"a":[1],"qt":"यदि '+' और '−' को परस्पर बदल दिया जाए और '×' और '÷' को परस्पर बदल दिया जाए, तो निम्नलिखित समीकरण में '?' के स्थान पर कितना मान आएगा?\n5 − 4 ÷ 9 + 80 × 10 = ?","ot":["31","33","35","30"],"wt":"चिह्न बदलने पर − का +, ÷ का ×, + का − और × का ÷ हो जाता है। समीकरण बनता है 5 + 4 × 9 − 80 ÷ 10। BODMAS लगाएँ: 4 × 9 = 36 और 80 ÷ 10 = 8। फिर 5 + 36 − 8 = 33। BODMAS का पालन किए बिना (बाएँ से दाएँ) हल करने पर गलत मान आएगा।"},{"id":"c24s1-9","p":"c24s1","n":9,"s":"rea","t":"Analogy & Classification","q":"Select the option in which the numbers share the same relationship as that shared by the given pair of numbers.\n(149, 213)\n(168, 232)\n(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding/deleting/multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.)","w":"In both given pairs the second number is the first plus 64: 149 + 64 = 213 and 168 + 64 = 232. Check the options: 162 + 60 = 222, 153 + 64 = 217, 137 + 74 = 211 and 144 + 54 = 198. Only (153, 217) has a difference of 64, so it shares the same relationship.","o":["(162, 222)","(153, 217)","(137, 211)","(144, 198)"],"a":[1],"qt":"उस विकल्प का चयन कीजिए, जिसमें संख्याएँ वही संबंध साझा करती हैं, जो संख्याओं के दिए गए युग्म द्वारा साझा किया गया है।\n(149, 213)\n(168, 232)\n(नोट: पूर्ण संख्याओं पर संक्रिया का प्रयोग, संख्याओं को उनके घटक अंकों में विभक्त किए बिना किया जाना चाहिए। उदाहरण के लिए, 13 :- 13 पर संक्रिया जैसे कि जोड़ने/घटाने/गुणा करने आदि को 13 में किया जा सकता है। 13 को 1 और 3 में विभक्त करके और फिर 1 और 3 पर गणितीय संक्रियाओं का प्रयोग करने की अनुमति नहीं है।)","ot":["(162, 222)","(153, 217)","(137, 211)","(144, 198)"],"wt":"दोनों दिए गए युग्मों में दूसरी संख्या पहली संख्या में 64 जोड़ने पर मिलती है: 149 + 64 = 213 और 168 + 64 = 232। विकल्पों की जाँच करें: 162 + 60 = 222, 153 + 64 = 217, 137 + 74 = 211 और 144 + 54 = 198। केवल (153, 217) में अंतर 64 है, अतः इसमें वही संबंध है।"},{"id":"c24s1-10","p":"c24s1","n":10,"s":"rea","t":"Non-verbal Reasoning","q":"Select the correct mirror image of the given figure when the mirror is placed at MN as shown below.","w":"With a vertical mirror MN on the right, the image is a left-right reversal: the order of characters reverses (n, 3, 9, r, f, T, y) and each character is flipped sideways, while nothing turns upside down. Option 2 shows exactly this, with T unchanged because it is symmetric. Option 1 turns f and T upside down, option 3 leaves 9 and 3 unflipped, and option 4 leaves n, r and y unflipped.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"जब दर्पण को नीचे दर्शाए गए अनुसार MN पर रखा जाता है तो दी गई आकृति के सही दर्पण प्रतिबिंब का चयन कीजिए।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"दर्पण MN दाईं ओर ऊर्ध्वाधर रखा है, अतः प्रतिबिंब में बायाँ-दायाँ उलट जाता है: वर्णों का क्रम उलट जाता है (n, 3, 9, r, f, T, y) और प्रत्येक वर्ण पार्श्व रूप से पलट जाता है, जबकि कोई भी वर्ण ऊपर-नीचे नहीं उलटता। विकल्प 2 ठीक यही दर्शाता है; T सममित होने के कारण अपरिवर्तित है। विकल्प 1 में f और T ऊपर-नीचे उलटे हैं, विकल्प 3 में 9 और 3 नहीं पलटे हैं, और विकल्प 4 में n, r और y नहीं पलटे हैं।"},{"id":"c24s1-11","p":"c24s1","n":11,"s":"rea","t":"Analogy & Classification","q":"Select the option that is related to the fifth letter-cluster in the same way as the second letter-cluster is related to the first letter-cluster and the fourth letter-cluster is related to the third letter-cluster.\nMEK: NVP :: GYT: TBG :: JWH:?","w":"Each letter is replaced by its opposite letter in the alphabet (the two positions add up to 27). M(13)→N(14), E(5)→V(22), K(11)→P(16) gives NVP; G→T, Y→B, T→G gives TBG. For JWH: J(10)→Q(17), W(23)→D(4), H(8)→S(19), giving QDS. PCR, QDT and PCS each break the rule in at least one letter.","o":["QDS","PCR","QDT","PCS"],"a":[0],"qt":"उस विकल्प का चयन करें जो पाँचवें अक्षर-समूह से उसी प्रकार संबंधित है जिस प्रकार दूसरा अक्षर-समूह पहले अक्षर-समूह से संबंधित है और चौथा अक्षर-समूह तीसरे अक्षर-समूह से संबंधित है।\nMEK: NVP :: GYT: TBG :: JWH:?","ot":["QDS","PCR","QDT","PCS"],"wt":"प्रत्येक अक्षर को वर्णमाला में उसके विपरीत अक्षर से बदला गया है (दोनों के स्थानों का योग 27 होता है)। M(13)→N(14), E(5)→V(22), K(11)→P(16) से NVP मिलता है; G→T, Y→B, T→G से TBG मिलता है। JWH के लिए: J(10)→Q(17), W(23)→D(4), H(8)→S(19), अर्थात QDS। PCR, QDT और PCS में कम से कम एक अक्षर इस नियम को तोड़ता है।"},{"id":"c24s1-12","p":"c24s1","n":12,"s":"rea","t":"Syllogism & Statements","q":"Three statements are given followed by three conclusions numbered I, II and III. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements.\nStatements:\nNo card is a parcel.\nAll cards are envelopes.\nSome envelopes are bags.\nConclusions:\nI. All envelopes can never be parcels.\nII. No card is a bag.\nIII. At least some bags are postcards.","w":"All cards are envelopes and no card is a parcel, so some envelopes (the cards) are definitely not parcels; therefore \"all envelopes are parcels\" is impossible and I follows. Cards and bags have no definite relation (some cards may or may not be bags), so II does not follow. Postcards are not mentioned in the statements, so III does not follow. Only I follows.","o":["Only I follows","Only II follows","Only I and III follow","Only II and III follow"],"a":[0],"qt":"तीन कथन और उसके बाद तीन निष्कर्ष I, II और III दिए गए हैं। कथनों को सत्य मानते हुए, भले ही वे सामान्य रूप से ज्ञात तथ्यों से भिन्न प्रतीत होते हों, तय कीजिए कि कौन-सा/से निष्कर्ष इन कथनों का तार्किक रूप से अनुसरण करता है/करते हैं।\nकथन:\nकोई भी कार्ड, पार्सल नहीं है।\nसभी कार्ड, लिफाफे हैं।\nकुछ लिफाफे, बैग हैं।\nनिष्कर्ष:\nI. सभी लिफाफे कभी भी पार्सल नहीं हो सकते।\nII. कोई भी कार्ड, बैग नहीं है।\nIII. कम से कम कुछ बैग, पोस्टकार्ड हैं।","ot":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I और III अनुसरण करते हैं","केवल निष्कर्ष II और III अनुसरण करते हैं"],"wt":"सभी कार्ड लिफाफे हैं और कोई भी कार्ड पार्सल नहीं है, अतः कुछ लिफाफे (कार्ड) निश्चित रूप से पार्सल नहीं हैं; इसलिए ‘सभी लिफाफे पार्सल हैं’ असंभव है और निष्कर्ष I अनुसरण करता है। कार्ड और बैग के बीच कोई निश्चित संबंध नहीं है (कुछ कार्ड बैग हो भी सकते हैं और नहीं भी), अतः II अनुसरण नहीं करता। कथनों में पोस्टकार्ड का उल्लेख नहीं है, अतः III अनुसरण नहीं करता। केवल I अनुसरण करता है।"},{"id":"c24s1-13","p":"c24s1","n":13,"s":"rea","t":"Non-verbal Reasoning","q":"Select the correct mirror image of the given figure when the mirror is placed at MN as shown.","w":"The mirror MN is vertical and on the right, so the image reverses left and right: the order becomes l, g, F, c, b and every letter is laterally inverted. l stays l, g and F appear reversed, c becomes ɔ and b becomes d. Option 1 shows all five changes. Option 2 keeps c and b unchanged, option 3 keeps g and c unchanged, and option 4 keeps g, F and b unchanged.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[0],"qt":"जब दर्पण को दर्शाए गए अनुसार MN पर रखा जाता है, तो दी गई आकृति के सही दर्पण प्रतिबिंब का चयन करें।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"दर्पण MN दाईं ओर ऊर्ध्वाधर है, अतः प्रतिबिंब में बायाँ-दायाँ उलट जाता है: क्रम l, g, F, c, b हो जाता है और प्रत्येक अक्षर पार्श्व रूप से पलट जाता है। l वैसा ही रहता है, g और F उलटे दिखते हैं, c बदलकर ɔ और b बदलकर d हो जाता है। विकल्प 1 में ये पाँचों परिवर्तन हैं। विकल्प 2 में c और b अपरिवर्तित हैं, विकल्प 3 में g और c अपरिवर्तित हैं, और विकल्प 4 में g, F और b अपरिवर्तित हैं।"},{"id":"c24s1-14","p":"c24s1","n":14,"s":"rea","t":"Non-verbal Reasoning","q":"Identify the option figure that when put in place of the question mark (?) will logically complete the series.","w":"Every element moves one step along the path top-left → bottom-left → bottom-right → top-right → centre → top-left, keeping its own direction. For example, the circle goes top-left, bottom-left, bottom-right, top-right, so it comes to the centre next. From figure 4: square (top-left) → bottom-left, down-arrow (bottom-left) → bottom-right, up-arrow (bottom-right) → top-right, circle → centre, triangle (centre) → top-left. Option 2 matches.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"उस विकल्प आकृति की पहचान कीजिए जिसे प्रश्न चिह्न (?) के स्थान पर रखने पर शृंखला तार्किक रूप से पूरी हो जाएगी।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"प्रत्येक तत्व अपनी दिशा बनाए रखते हुए इस पथ पर एक कदम आगे बढ़ता है: ऊपर-बाएँ → नीचे-बाएँ → नीचे-दाएँ → ऊपर-दाएँ → केंद्र → ऊपर-बाएँ। उदाहरण के लिए, वृत्त ऊपर-बाएँ, नीचे-बाएँ, नीचे-दाएँ, ऊपर-दाएँ जाता है, अतः अगली बार केंद्र में आएगा। आकृति 4 से: वर्ग (ऊपर-बाएँ) → नीचे-बाएँ, नीचे की ओर वाला तीर (नीचे-बाएँ) → नीचे-दाएँ, ऊपर की ओर वाला तीर (नीचे-दाएँ) → ऊपर-दाएँ, वृत्त → केंद्र, त्रिभुज (केंद्र) → ऊपर-बाएँ। विकल्प 2 इससे मेल खाता है।"},{"id":"c24s1-15","p":"c24s1","n":15,"s":"rea","t":"Series","q":"Which of the four options will replace the question mark (?) in the following series?\nUE 88, VG 84, WI 80, XK76, ?","w":"Treat the three parts separately. First letters U, V, W, X move +1, so next is Y. Second letters E, G, I, K move +2, so next is M. The numbers 88, 84, 80, 76 decrease by 4, so next is 72. The missing term is YM72. ZM72 has the wrong first letter, and ZN71 and YN73 break the letter and number patterns.","o":["ZM72","ZN71","YN73","YM72"],"a":[3],"qt":"चार विकल्पों में से कौन सा विकल्प निम्नलिखित श्रृंखला में प्रश्न चिह्न (?) के स्थान पर आएगा?\nUE 88, VG 84, WI 80, XK76, ?","ot":["ZM72","ZN71","YN73","YM72"],"wt":"तीनों भागों को अलग-अलग देखें। पहले अक्षर U, V, W, X में +1 का अंतर है, अतः अगला Y है। दूसरे अक्षर E, G, I, K में +2 का अंतर है, अतः अगला M है। संख्याएँ 88, 84, 80, 76 में 4 की कमी हो रही है, अतः अगली संख्या 72 है। लुप्त पद YM72 है। ZM72 का पहला अक्षर गलत है, और ZN71 तथा YN73 अक्षर और संख्या के क्रम को तोड़ते हैं।"},{"id":"c24s1-16","p":"c24s1","n":16,"s":"rea","t":"Series","q":"Select the option that represents the letters that when placed from left to right in the blanks below will complete the letter series.\nL_P_QS_K_P_S_KP_Q_L_ _PQS","w":"Filling the blanks with K, P, L, P, Q, L, P, S, K, P gives L K P P Q S / L K P P Q S / L K P P Q S / L K P P Q S. The series is the group \"LKPPQS\" repeated four times. Every other option breaks this repetition at some blank, for example option 1 puts L in the fifth blank where Q is needed.","o":["KPLPLQLSPK","PKLPQPLSKP","KPLPQQLPSK","KPLPQLPSKP"],"a":[3],"qt":"उस विकल्प का चयन कीजिए जो उन अक्षरों को निरूपित करता है जिन्हें नीचे रिक्त स्थानों में बाएँ से दाएँ रखने पर अक्षर श्रृंखला पूरी हो जाएगी।\nL_P_QS_K_P_S_KP_Q_L_ _PQS","ot":["KPLPLQLSPK","PKLPQPLSKP","KPLPQQLPSK","KPLPQLPSKP"],"wt":"रिक्त स्थानों में K, P, L, P, Q, L, P, S, K, P भरने पर L K P P Q S / L K P P Q S / L K P P Q S / L K P P Q S मिलता है। श्रृंखला में समूह ‘LKPPQS’ चार बार दोहराया गया है। अन्य सभी विकल्प किसी न किसी रिक्त स्थान पर इस दोहराव को तोड़ते हैं, उदाहरण के लिए विकल्प 1 पाँचवें रिक्त स्थान पर L रखता है, जहाँ Q चाहिए।"},{"id":"c24s1-17","p":"c24s1","n":17,"s":"rea","t":"Non-verbal Reasoning","q":"Identify the figure from the given options, which when put in place of the question mark (?), will logically complete the series.","w":"Read each figure in the order top-left, top-right, bottom-right, bottom-left, centre: A B C D E, then E A B C D, then D E A B C, then C D E A B. Each time every letter moves one step along this path. The next figure is B C D E A: B top-left, C top-right, D bottom-right, E bottom-left and A in the centre, which is option 2. Options 3 and 4 use mirrored letters, and option 1 has wrong positions.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"दिए गए विकल्पों में से उस आकृति की पहचान कीजिए, जिसे प्रश्न चिह्न (?) के स्थान पर रखने पर, शृंखला तार्किक रूप से पूर्ण हो जाएगी।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"प्रत्येक आकृति को ऊपर-बाएँ, ऊपर-दाएँ, नीचे-दाएँ, नीचे-बाएँ, केंद्र के क्रम में पढ़ें: A B C D E, फिर E A B C D, फिर D E A B C, फिर C D E A B। हर बार प्रत्येक अक्षर इस पथ पर एक कदम आगे बढ़ता है। अगली आकृति B C D E A है: B ऊपर-बाएँ, C ऊपर-दाएँ, D नीचे-दाएँ, E नीचे-बाएँ और A केंद्र में, जो विकल्प 2 है। विकल्प 3 और 4 में दर्पण-उलटे अक्षर हैं, और विकल्प 1 में स्थान गलत हैं।"},{"id":"c24s1-18","p":"c24s1","n":18,"s":"rea","t":"Non-verbal Reasoning","q":"Six numbers 21, 22, 23, 24, 25 and 26 are written on different faces of a dice. Three positions of this dice are shown in the figure. Find the number on the face opposite to 24.","w":"From the figures, 25 appears with 21, 23, 22 and 24, so the only number left for its opposite face is 26. 21 appears with 23, 25 and 22, and 26 is already opposite 25, so 21 must be opposite 24. The remaining pair is 22 and 23. Hence the number opposite 24 is 21.","img":"data:image/png;base64,","o":["26","25","22","21"],"a":[3],"qt":"एक पासे के विभिन्न फलकों पर छ: संख्याएँ 21, 22, 23, 24, 25 और 26 लिखी गई हैं। नीचे चित्र में इस पासे की तीन स्थितियाँ दिखाई गई है। संख्या 24 के विपरीत फलक पर कौन-सी संख्या है?","ot":["26","25","22","21"],"wt":"आकृतियों में 25 के साथ 21, 23, 22 और 24 दिखाई देते हैं, अतः इसके विपरीत फलक के लिए केवल 26 बचता है। 21 के साथ 23, 25 और 22 दिखाई देते हैं, और 26 पहले से 25 के विपरीत है, अतः 21 को 24 के विपरीत होना चाहिए। शेष युग्म 22 और 23 है। अतः 24 के विपरीत फलक पर संख्या 21 है।"},{"id":"c24s1-19","p":"c24s1","n":19,"s":"rea","t":"Non-verbal Reasoning","q":"How many triangles are there in the given figure?","w":"Top-left square: 4 corner triangles plus the upper-left half of the small overlapping square = 5. V under the top edge: two halves and the whole V = 3. Lower-left: four triangles meeting at the left-edge point, including the tall one made by both slanting lines, plus two halves of the next square = 6. Bottom zig-zag: two small, their combination and the one standing on the bottom edge = 4. Right side: two halves of a small square and one at the right edge = 3. Total 5 + 3 + 6 + 4 + 3 = 21.","img":"data:image/png;base64,","o":["21","20","18","19"],"a":[0],"qt":"दी गई आकृति में कितने त्रिभुज हैं?","ot":["21","20","18","19"],"wt":"ऊपर-बाएँ वर्ग: 4 कोने वाले त्रिभुज तथा छोटे अतिव्यापी वर्ग का ऊपरी-बायाँ आधा भाग = 5। ऊपरी किनारे के नीचे का V: इसके दोनों आधे भाग और पूरा V = 3। नीचे-बाएँ: बाएँ किनारे के बिंदु पर मिलने वाले चार त्रिभुज, जिनमें दोनों तिरछी रेखाओं से बना लंबा त्रिभुज भी शामिल है, तथा अगले वर्ग के दो आधे भाग = 6। नीचे का टेढ़ा-मेढ़ा भाग: दो छोटे त्रिभुज, उनका संयुक्त त्रिभुज और निचले किनारे पर खड़ा त्रिभुज = 4। दाईं ओर: एक छोटे वर्ग के दो आधे भाग और दाएँ किनारे पर एक त्रिभुज = 3। कुल 5 + 3 + 6 + 4 + 3 = 21।"},{"id":"c24s1-20","p":"c24s1","n":20,"s":"rea","t":"Coding-Decoding","q":"In a certain code language, ‘what where how’ is written as ‘aa dd ff’; ‘where there that’ is written as ‘dd zz pp’ and ‘which what here’ is written as ‘ff kk ll’. How is ‘how’ written in that language?","w":"Compare sentences that share a word. \"where\" is common to the first two sentences and \"dd\" is common to their codes, so where = dd. \"what\" is common to the first and third, and \"ff\" is common to their codes, so what = ff. In the first sentence the remaining word \"how\" must take the remaining code \"aa\". So how = aa.","o":["aa","kk","zz","ff"],"a":[0],"qt":"एक निश्चित कूट भाषा में ‘what where how’ को 'aa dd ff' के रूप में लिखा जाता है; ‘where there that’ को ‘dd zz pp’ और 'which what here' को 'ff kk ll' लिखा जाता है। उसी भाषा में 'how' कैसे लिखा जाता है?","ot":["aa","kk","zz","ff"],"wt":"जिन वाक्यों में कोई शब्द उभयनिष्ठ है, उनकी तुलना करें। ‘where’ पहले दो वाक्यों में उभयनिष्ठ है और उनके कूटों में ‘dd’ उभयनिष्ठ है, अतः where = dd। ‘what’ पहले और तीसरे वाक्य में उभयनिष्ठ है और उनके कूटों में ‘ff’ उभयनिष्ठ है, अतः what = ff। पहले वाक्य का शेष शब्द ‘how’ शेष कूट ‘aa’ लेगा। अतः how = aa।"},{"id":"c24s1-21","p":"c24s1","n":21,"s":"rea","t":"Syllogism & Statements","q":"Three statements are given followed by three conclusions numbered I, II and III. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements.\nStatements:\nSome tears are drops.\nSome drops are streams.\nAll streams are rivers.\nConclusions:\nI. All tears can never be rivers.\nII. Some drops are rivers.\nIII. All tears being streams is a possibility.","w":"Some drops are streams and all streams are rivers, so those drops are rivers: II follows. Tears and streams have no definite relation, so all tears being streams is possible: III follows. Since all tears could be streams (and so rivers), \"all tears can never be rivers\" is false, so I does not follow. Hence both II and III follow.","o":["Only conclusion I follows","Both II and III conclusion follow","Only conclusion III follows","Both I and II conclusion follow"],"a":[1],"qt":"तीन कथन और उसके बाद तीन निष्कर्ष I, II और III दिए गए हैं। कथनों को सत्य मानते हुए, भले ही वे सामान्य रूप से ज्ञात तथ्यों से भिन्न प्रतीत होते हों, तय कीजिए कि कौन-सा/से निष्कर्ष इन कथनों का तार्किक रूप से अनुसरण करता है/करते हैं।\nकथन:\nकुछ आंसू, बूंदें हैं।\nकुछ बूंदें, धाराएं हैं।\nसभी धाराएं, नदियां हैं।\nनिष्कर्ष:\nI. सभी आंसू कभी भी नदियां नहीं हो सकते हैं।\nII. कुछ बूंदें, नदियां हैं।\nIII. सभी आंसुओं के धाराएं होने की संभावना है।","ot":["केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष II और III दोनों अनुसरण करते हैं","केवल निष्कर्ष III अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"wt":"कुछ बूंदें धाराएं हैं और सभी धाराएं नदियां हैं, अतः वे बूंदें नदियां हैं: II अनुसरण करता है। आंसुओं और धाराओं के बीच कोई निश्चित संबंध नहीं है, अतः सभी आंसुओं का धाराएं होना संभव है: III अनुसरण करता है। चूँकि सभी आंसू धाराएं (और इसलिए नदियां) हो सकते हैं, ‘सभी आंसू कभी भी नदियां नहीं हो सकते’ गलत है, इसलिए I अनुसरण नहीं करता। अतः II और III दोनों अनुसरण करते हैं।"},{"id":"c24s1-22","p":"c24s1","n":22,"s":"rea","t":"Series","q":"Which of the following terms will replace the question mark (?) in the given series?\nYZUW, ?, QTQU, MQOT, INMS","w":"Follow each letter position separately. First letters: Y, ?, Q, M, I fall by 4, so Y − 4 = U. Second: Z, ?, T, Q, N fall by 3, so Z − 3 = W. Third: U, ?, Q, O, M fall by 2, so U − 2 = S. Fourth: W, ?, U, T, S fall by 1, so W − 1 = V. The missing term is UWSV; the other options contain the same letters in a wrong order.","o":["UWSV","UWVS","USWV","WUSV"],"a":[0],"qt":"निम्नलिखित में से कौन-सा पद दी गई शृंखला में प्रश्न-चिह्न (?) को प्रतिस्थापित करेगा?\nYZUW, ?, QTQU, MQOT, INMS","ot":["UWSV","UWVS","USWV","WUSV"],"wt":"प्रत्येक अक्षर-स्थान को अलग-अलग देखें। पहले अक्षर: Y, ?, Q, M, I में 4 की कमी, अतः Y − 4 = U। दूसरे अक्षर: Z, ?, T, Q, N में 3 की कमी, अतः Z − 3 = W। तीसरे अक्षर: U, ?, Q, O, M में 2 की कमी, अतः U − 2 = S। चौथे अक्षर: W, ?, U, T, S में 1 की कमी, अतः W − 1 = V। लुप्त पद UWSV है; अन्य विकल्पों में यही अक्षर गलत क्रम में हैं।"},{"id":"c24s1-23","p":"c24s1","n":23,"s":"rea","t":"Blood Relations & Directions","q":"In a certain code language,\n‘A + B’ means ‘A is the mother of B’,\n‘A − B’ means ‘A is the father of B’,\n‘A $ B’ means ‘A is the son of B’,\n‘A % B’ means ‘A is the sister of B’,\n‘A / B’ means ‘A is the wife of B’ and\n‘A = B’ means ‘A is the brother of B’.\nWhich of the following means A is the daughter of K?\ni. A + K / J − P = D\nii. J % P = K + A = D\niii. K + A / P − D % J\niv. D + K = A / P − J","w":"Decode iii: K + A means K is the mother of A, and A / P means A is the wife of P, so A is female. Hence A is the daughter of K. In i, A is the mother of K. In ii, K + A = D makes A the brother of D, so A is K's son. In iv, D is the mother of K and A, and K is A's brother, so A is D's daughter, not K's.","o":["i","iii","ii","iv"],"a":[1],"qt":"एक निश्चित कूट भाषा में,\n‘A + B’ का अर्थ है ‘A, B की माँ है’,\n‘A − B’ का अर्थ है ‘A, B का पिता है’,\n‘A $ B’ का अर्थ है ‘A, B का पुत्र है’,\n‘A % B’ का अर्थ है ‘A, B की बहन है’,\n‘A / B’ का अर्थ है ‘A, B की पत्नी है’ और\n‘A = B’ का अर्थ है ‘A, B का भाई है’।\nनिम्नलिखित में से किसका अर्थ है कि A, K की पुत्री है?\ni. A + K / J − P = D\nii. J % P = K + A = D\niii. K + A / P − D % J\niv. D + K = A / P − J","ot":["i","iii","ii","iv"],"wt":"iii को डिकोड करें: K + A का अर्थ है K, A की माँ है, और A / P का अर्थ है A, P की पत्नी है, अतः A स्त्री है। इसलिए A, K की पुत्री है। i में A, K की माँ है। ii में K + A = D से A, D का भाई बनता है, अतः A, K का पुत्र है। iv में D, K और A दोनों की माँ है, और K, A का भाई है, अतः A, D की पुत्री है, K की नहीं।"},{"id":"c24s1-24","p":"c24s1","n":24,"s":"rea","t":"Analogy & Classification","q":"19 is related to 209 following a certain logic. Following the same logic, 27 is related to 297. To which of the following is 61 related, following the same logic?\n(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding /deleting /multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed)","w":"The second number is 11 times the first: 19 × 11 = 209 and 27 × 11 = 297. Applying the same rule, 61 × 11 = 671. A quick check for multiplying a two-digit number by 11: write the digits apart and put their sum in between (6, 6 + 1, 1 = 671), but the rule itself works on the whole number.","o":["653","600","571","671"],"a":[3],"qt":"एक निश्चित तर्क का अनुसरण करते हुए 19, 209 से संबंधित है। उसी तर्क का अनुसरण करते हुए, 27, 297 से संबंधित है। उसी तर्क का अनुसरण करते हुए, 61 निम्नलिखित में से किससे संबंधित है?\n(नोट: संख्याओं को उसके घटक अंकों में तोड़े बिना, पूर्ण संख्याओं पर संक्रियाएं की जानी चाहिए। उदाहरण के लिए संख्या 13 को लें - 13 पर संक्रियाएं, जैसे कि 13 में जोड़ना/घटाना/गुणा करना आदि, की जा सकती हैं। 13 को 1 और 3 में तोड़ने और फिर 1 और 3 पर गणितीय संक्रियाएं करने की अनुमति नहीं है)","ot":["653","600","571","671"],"wt":"दूसरी संख्या पहली संख्या की 11 गुनी है: 19 × 11 = 209 और 27 × 11 = 297। यही नियम लगाने पर 61 × 11 = 671। किसी दो अंकों की संख्या को 11 से गुणा करने की त्वरित जाँच: दोनों अंकों को अलग लिखें और बीच में उनका योग रखें (6, 6 + 1, 1 = 671), परंतु नियम स्वयं पूर्ण संख्या पर लागू होता है।"},{"id":"c24s1-25","p":"c24s1","n":25,"s":"rea","t":"Series","q":"Which of the following numbers will replace the question mark (?) in the given series?\n1, 3, 10, 41, ?, 1237","w":"Each term is the previous term multiplied by an increasing number, plus 1: 1 × 2 + 1 = 3, 3 × 3 + 1 = 10, 10 × 4 + 1 = 41, 41 × 5 + 1 = 206, and 206 × 6 + 1 = 1237. The last term confirms the rule, so the missing number is 206.","o":["202","210","200","206"],"a":[3],"qt":"निम्नलिखित में से कौन सी संख्या दी गई श्रृंखला में प्रश्न चिह्न (?) का स्थान लेगी?\n1, 3, 10, 41, ?, 1237","ot":["202","210","200","206"],"wt":"प्रत्येक पद पिछले पद को एक बढ़ती हुई संख्या से गुणा करके 1 जोड़ने पर मिलता है: 1 × 2 + 1 = 3, 3 × 3 + 1 = 10, 10 × 4 + 1 = 41, 41 × 5 + 1 = 206, और 206 × 6 + 1 = 1237। अंतिम पद इस नियम की पुष्टि करता है, अतः लुप्त संख्या 206 है।"},{"id":"c24s1-26","p":"c24s1","n":26,"s":"geo","t":"Environment & Ecology","q":"In which year was Project Tiger launched in India?","w":"Project Tiger, a centrally sponsored scheme of the Union environment ministry, was launched on 1 April 1973 with nine tiger reserves, including Jim Corbett National Park, Kanha, Manas and the Sundarbans. The Wildlife (Protection) Act had been passed a year earlier, in 1972, which makes 1972 a tempting option. Since 2006 the scheme has been run by the statutory National Tiger Conservation Authority (NTCA), and the network has grown to more than 50 tiger reserves.","o":["1973","1970","1972","1985"],"a":[0],"qt":"भारत में प्रोजेक्ट टाइगर (Project Tiger) किस वर्ष शुरू किया गया था?","ot":["1973 में","1970 में","1972 में","1985 में"],"wt":"प्रोजेक्ट टाइगर, केंद्रीय पर्यावरण मंत्रालय की एक केंद्र प्रायोजित योजना, 1 अप्रैल 1973 को नौ टाइगर रिज़र्व (बाघ अभयारण्यों) के साथ शुरू की गई थी, जिनमें जिम कॉर्बेट राष्ट्रीय उद्यान, कान्हा, मानस और सुंदरबन शामिल थे। वन्यजीव (संरक्षण) अधिनियम इससे एक वर्ष पहले, 1972 में पारित हुआ था, इसलिए 1972 एक भ्रामक विकल्प है। 2006 से इस योजना का संचालन वैधानिक राष्ट्रीय बाघ संरक्षण प्राधिकरण (NTCA) करता है, और टाइगर रिज़र्वों की संख्या बढ़कर 50 से अधिक हो गई है।"},{"id":"c24s1-27","p":"c24s1","n":27,"s":"cur","t":"Static GK & Culture","q":"Lathmar Holi is primarily celebrated in the state of:","w":"Lathmar Holi is played in the Braj region of Uttar Pradesh, at Barsana (Radha's village) and Nandgaon (Krishna's village) in Mathura district, a few days before the main Holi festival. Recalling the legend of Krishna and his friends teasing Radha and the gopis, the women of Barsana playfully beat the visiting men of Nandgaon with lathis (sticks) while the men protect themselves with shields; the next day the roles are repeated at Nandgaon. Songs, colours and sweets accompany the festivities.","o":["Karnataka","Himachal Pradesh","Arunachal Pradesh","Uttar Pradesh"],"a":[3],"qt":"लठमार होली मुख्य रूप से किस राज्य में खेली जाती है?","ot":["कर्नाटक","हिमाचल प्रदेश","अरुणाचल प्रदेश","उत्तर प्रदेश"],"wt":"लठमार होली उत्तर प्रदेश के ब्रज क्षेत्र में, मथुरा ज़िले के बरसाना (राधा का गाँव) और नंदगाँव (कृष्ण का गाँव) में, मुख्य होली से कुछ दिन पहले खेली जाती है। कृष्ण और उनके सखाओं द्वारा राधा और गोपियों को छेड़ने की कथा की याद में बरसाना की महिलाएँ नंदगाँव से आए पुरुषों पर खेल-खेल में लाठियाँ बरसाती हैं और पुरुष ढालों से अपना बचाव करते हैं; अगले दिन यही रस्म नंदगाँव में दोहराई जाती है। उत्सव में गीत, रंग और मिठाइयाँ भी होती हैं।"},{"id":"c24s1-28","p":"c24s1","n":28,"s":"cur","t":"Awards, Books & Persons","q":"Which of the following awards was won by Lata Mangeshkar in the year 2001?","w":"Lata Mangeshkar, the \"Nightingale of India\", received the Bharat Ratna, India's highest civilian honour, in 2001, the same year as shehnai maestro Ustad Bismillah Khan; she was the second singer to receive it after M.S. Subbulakshmi (1998). Her other honours came earlier: Padma Bhushan (1969), Dadasaheb Phalke Award (1989), Filmfare Lifetime Achievement Award (1993) and Padma Vibhushan (1999). She died in February 2022.","o":["Dadasaheb Phalke Award","Padma Vibhushan","Bharat Ratna","Filmfare Lifetime Achievement Award"],"a":[2],"qt":"लता मंगेशकर को वर्ष 2001 में निम्नलिखित में से किस पुरस्कार से सम्मानित किया गया था?","ot":["दादा साहेब फाल्के पुरस्कार","पद्म विभूषण","भारत रत्न","फिल्मफेयर लाइफटाइम अचीवमेंट अवार्ड"],"wt":"'भारत की स्वर कोकिला' लता मंगेशकर को 2001 में भारत का सर्वोच्च नागरिक सम्मान भारत रत्न मिला; उसी वर्ष शहनाई वादक उस्ताद बिस्मिल्लाह खान को भी यह सम्मान मिला। एम.एस. सुब्बुलक्ष्मी (1998) के बाद यह सम्मान पाने वाली वे दूसरी गायिका थीं। उनके अन्य सम्मान इससे पहले मिले थे: पद्म भूषण (1969), दादा साहेब फाल्के पुरस्कार (1989), फिल्मफेयर लाइफटाइम अचीवमेंट अवार्ड (1993) और पद्म विभूषण (1999)। फरवरी 2022 में उनका निधन हुआ।"},{"id":"c24s1-29","p":"c24s1","n":29,"s":"ih","t":"Ancient India","q":"Details about Sudarshana lake is given in a rock inscription at Girnar (Junagarh), which was composed to record the achievements of the Shaka ruler ______.","w":"The Junagadh (Girnar) rock inscription of Rudradaman I, the Western Kshatrapa (Shaka) ruler, is dated Saka year 72 (150 CE) and is the earliest long inscription in chaste Sanskrit. It records that the Sudarshana lake, built by Chandragupta Maurya's governor Pushyagupta and provided with conduits under Ashoka, was breached in a storm and repaired by Rudradaman's governor Suvishakha. Chashtana, his grandfather, founded this Kshatrapa line, and Maues was an Indo-Scythian king of the north-west.","o":["Chashtana","Rudradaman I","Rudrasimha III","Maues"],"a":[1],"qt":"सुदर्शन झील का विवरण गिरनार (जूनागढ़) के एक शिलालेख में उल्लिखित हैं जिसकी रचना शक शासक ______की उपलब्धियों को दर्ज करने के लिए की गई थी।","ot":["चश्ताना","रुद्रदामन प्रथम","रुद्रसिम्हा तृतीय","माउज़"],"wt":"पश्चिमी क्षत्रप (शक) शासक रुद्रदामन प्रथम का जूनागढ़ (गिरनार) शिलालेख शक संवत 72 (150 ई.) का है और यह विशुद्ध संस्कृत में लिखा गया सबसे पहला लंबा अभिलेख है। इसमें उल्लेख है कि चंद्रगुप्त मौर्य के राज्यपाल पुष्यगुप्त द्वारा बनवाई गई और अशोक के समय नहरों से युक्त की गई सुदर्शन झील एक तूफ़ान में टूट गई थी, जिसकी मरम्मत रुद्रदामन के राज्यपाल सुविशाख ने कराई। उसके दादा चष्टन (चश्ताना) ने इस क्षत्रप वंश की स्थापना की थी, और माउज़ उत्तर-पश्चिम भारत का एक हिंद-शक (Indo-Scythian) राजा था।"},{"id":"c24s1-30","p":"c24s1","n":30,"s":"eco","t":"Money, Banking & Finance","q":"______ is an industry association and self-regulatory organisation (SRO) whose primary objective is to work towards the robust development of the microfinance sector.","w":"The Microfinance Institutions Network (MFIN), set up in 2009 as the association of NBFC-MFIs, became in June 2014 the first industry association recognised by the Reserve Bank of India as a self-regulatory organisation (SRO) for the microfinance sector; Sa-Dhan was also recognised in 2015. MFIN frames a code of conduct, monitors members' compliance, handles grievances and works with regulators for responsible growth of microfinance. NABARD is a statutory development bank for agriculture and rural development, not an industry SRO.","o":["NABARD","Self-help Group Association","Microfinance and Investments Regulatory Authority","Microfinance Institutions Network"],"a":[3],"qt":"______ एक उद्योग संघ और स्व-विनियामक संगठन (SRO) है जिसका प्राथमिक उद्देश्य सूक्ष्मवित्त क्षेत्र के सुदृढ़ विकास की दिशा में काम करना है।","ot":["नाबार्ड (NABARD)","स्वयं सहायता समूह संघ","सूक्ष्म वित्त एवं निवेश विनियामक प्राधिकरण","सूक्ष्म वित्त संस्था नेटवर्क"],"wt":"सूक्ष्म वित्त संस्था नेटवर्क (MFIN), जो 2009 में NBFC-MFI संस्थाओं के संघ के रूप में स्थापित हुआ, जून 2014 में भारतीय रिज़र्व बैंक द्वारा सूक्ष्मवित्त क्षेत्र के स्व-विनियामक संगठन (SRO) के रूप में मान्यता पाने वाला पहला उद्योग संघ बना; सा-धन (Sa-Dhan) को भी 2015 में यह मान्यता मिली। MFIN आचार संहिता बनाता है, सदस्यों द्वारा उसके पालन की निगरानी करता है, शिकायतों का निपटारा करता है और सूक्ष्मवित्त के ज़िम्मेदार विकास के लिए नियामकों के साथ काम करता है। नाबार्ड कृषि और ग्रामीण विकास के लिए एक वैधानिक विकास बैंक है, कोई उद्योग SRO नहीं।"},{"id":"c24s1-31","p":"c24s1","n":31,"s":"pol","t":"Judiciary & Constitutional Bodies","q":"Which article has a similar provision to that of Article 32 and deals with writ jurisdiction?","w":"Article 32 lets a person move the Supreme Court to enforce Fundamental Rights through writs such as habeas corpus, mandamus, prohibition, certiorari and quo warranto. Article 226 gives every High Court a similar power to issue these writs, and it is wider, since High Courts can issue them for Fundamental Rights and \"for any other purpose\", that is, other legal rights. Article 227 gives High Courts superintendence over subordinate courts, Article 228 lets them withdraw cases involving substantial constitutional questions, and Article 225 continues their existing jurisdiction.","o":["Article 228","Article 227","Article 226","Article 225"],"a":[2],"qt":"निम्नलिखित में से कौन-सा अनुच्छेद रिट अधिकारिता से संबंधित है और अनुच्छेद 32 के समान प्रावधान रखता है?","ot":["अनुच्छेद 228","अनुच्छेद 227","अनुच्छेद 226","अनुच्छेद 225"],"wt":"अनुच्छेद 32 के तहत कोई व्यक्ति मौलिक अधिकारों को लागू कराने के लिए सर्वोच्च न्यायालय जा सकता है, जो बंदी प्रत्यक्षीकरण, परमादेश, प्रतिषेध, उत्प्रेषण और अधिकार-पृच्छा जैसी रिट जारी करता है। अनुच्छेद 226 प्रत्येक उच्च न्यायालय को ऐसी रिट जारी करने की समान शक्ति देता है, और यह अधिक व्यापक है, क्योंकि उच्च न्यायालय मौलिक अधिकारों के साथ 'किसी अन्य प्रयोजन' के लिए, अर्थात अन्य विधिक अधिकारों के लिए भी रिट जारी कर सकते हैं। अनुच्छेद 227 उच्च न्यायालयों को अधीनस्थ न्यायालयों पर अधीक्षण की शक्ति देता है, अनुच्छेद 228 उन्हें संविधान के सारवान प्रश्न वाले मामले अपने पास मँगाने की शक्ति देता है, और अनुच्छेद 225 उनकी विद्यमान अधिकारिता को बनाए रखता है।"},{"id":"c24s1-32","p":"c24s1","n":32,"s":"pol","t":"Government & Parliament","q":"Which of the following is NOT a condition for the President’s office in India?","w":"Article 59 lays down the conditions of the President's office: he shall not be a member of either House of Parliament or of a State Legislature, shall not hold any other office of profit, shall be entitled without payment of rent to the use of his official residences along with emoluments and allowances fixed by Parliament, and these emoluments and allowances shall not be diminished during his term of office. Option 3 reverses the rent-free residence provision, so it is not a condition.","o":["He shall not hold any office of profit.","The allowances shall not be diminished during his term of office.","He shall not be entitled, without payment of rent, to use his official residence.","He shall not be a member of either House of the Parliament."],"a":[2],"qt":"निम्नलिखित में से कौन-सी भारत में राष्ट्रपति के पद के लिए एक शर्त नहीं है?","ot":["वह किसी लाभ के पद पर नहीं होगा।","उनके कार्यकाल के दौरान भत्तों में कमी नहीं की जाएगी।","वह किराए के भुगतान के बिना अपने आधिकारिक निवास का उपयोग करने का हकदार नहीं होगा।","वह संसद के किसी भी सदन का सदस्य नहीं होगा।"],"wt":"अनुच्छेद 59 राष्ट्रपति के पद की शर्तें निर्धारित करता है: वह संसद के किसी सदन या किसी राज्य के विधानमंडल का सदस्य नहीं होगा, कोई अन्य लाभ का पद धारण नहीं करेगा, बिना किराया दिए अपने शासकीय निवासों के उपयोग का तथा संसद द्वारा निर्धारित उपलब्धियों और भत्तों का हकदार होगा, और उसके कार्यकाल के दौरान इन उपलब्धियों और भत्तों में कमी नहीं की जाएगी। विकल्प 3 किराया-मुक्त निवास वाले प्रावधान को उलट देता है, इसलिए यह शर्त नहीं है।"},{"id":"c24s1-33","p":"c24s1","n":33,"s":"sci","t":"Biology","q":"Which of the following statements best defines the monoecious?","w":"Monoecious (\"one house\") means that male and female reproductive organs are borne on the same individual; NCERT equates it with the bisexual condition, and option 3, a flower with both androecium (stamens) and gynoecium (carpels), is the only choice showing both. Strictly, botanists call such a flower bisexual or perfect and use \"monoecious\" for a plant bearing separate male and female flowers, as in maize, cucurbits and coconut. Options 1 and 2 are unisexual (pistillate, staminate) flowers, and \"dithecous\" describes a typical angiosperm anther (with two thecae), not a type of flower.","o":["A flower with gynoecium only","A flower with androecium only","A flower with both androecium and gynoecium","A flower with dithecous"],"a":[2],"qt":"निम्नलिखित में से कौन सा कथन उभयलिंगाश्रयी (monoecious) को सर्वोत्तम रूप से परिभाषित करता है?","ot":["केवल जायांग वाला फूल","केवल पुमंग वाला फूल","पुमंग और जायांग दोनों से युक्त फूल","द्विकोष्ठी फूल"],"wt":"उभयलिंगाश्रयी (monoecious, शाब्दिक अर्थ 'एक घर') का अर्थ है कि नर और मादा जनन अंग एक ही जीव पर पाए जाते हैं; NCERT इसे द्विलिंगी अवस्था के समान मानता है, और विकल्प 3, यानी पुमंग (पुंकेसर) और जायांग (अंडप) दोनों से युक्त फूल, ही ऐसा विकल्प है जिसमें दोनों अंग हैं। वनस्पति विज्ञान की सख्त भाषा में ऐसे फूल को द्विलिंगी या पूर्ण फूल कहते हैं और 'monoecious' उस पौधे के लिए प्रयुक्त होता है जिस पर अलग-अलग नर और मादा फूल लगते हैं, जैसे मक्का, कुकरबिट और नारियल। विकल्प 1 और 2 एकलिंगी (स्त्रीकेसरी, पुंकेसरी) फूल हैं, और 'द्विकोष्ठी' (dithecous) एक सामान्य आवृतबीजी परागकोश (दो कोष्ठों वाला) का वर्णन है, फूल के किसी प्रकार का नहीं।"},{"id":"c24s1-34","p":"c24s1","n":34,"s":"cur","t":"Awards, Books & Persons","q":"Mohan Veena player, Pandit Vishwa Mohan Bhatt won the ______ Award in the year 1994.","w":"Pandit Vishwa Mohan Bhatt, a disciple of Pandit Ravi Shankar, created the Mohan veena, a modified slide guitar with added sympathetic and drone strings, played in the Hindustani style. In 1994 he won the Grammy Award for Best World Music Album for \"A Meeting by the River\", recorded with the American guitarist Ry Cooder. He later received the Padma Shri (2002) and the Padma Bhushan (2017). Sangita Kalanidhi is the Madras Music Academy's title for Carnatic musicians.","o":["Grammy","Sangita Kalanidhi","Oscar","Sangeet Natak Akademi"],"a":[0],"qt":"मोहन वीणा वादक, पंडित विश्व मोहन भट्ट ने वर्ष 1994 में ______ पुरस्कार जीता।","ot":["ग्रैमी","संगीत कलानिधि","ऑस्कर","संगीत नाटक अकादमी"],"wt":"पंडित रविशंकर के शिष्य पंडित विश्व मोहन भट्ट ने मोहन वीणा बनाई, जो अतिरिक्त तरब (सहायक अनुनादी) और चिकारी (ड्रोन) तारों वाला एक संशोधित स्लाइड गिटार है और हिंदुस्तानी शैली में बजाया जाता है। 1994 में उन्होंने अमेरिकी गिटार वादक राई कूडर के साथ रिकॉर्ड किए गए एल्बम 'ए मीटिंग बाय द रिवर' के लिए सर्वश्रेष्ठ विश्व संगीत एल्बम का ग्रैमी पुरस्कार जीता। बाद में उन्हें पद्म श्री (2002) और पद्म भूषण (2017) मिले। संगीत कलानिधि मद्रास म्यूज़िक अकादमी द्वारा कर्नाटक संगीतकारों को दी जाने वाली उपाधि है।"},{"id":"c24s1-35","p":"c24s1","n":35,"s":"cur","t":"National","q":"Who is Union Minister of State (Independent Charge) for Science and Technology as of July 2023?","w":"Dr Jitendra Singh has been Minister of State (Independent Charge) for Science and Technology and for Earth Sciences since the July 2021 reshuffle, and is also Minister of State in the PMO and for Personnel, Atomic Energy and Space; he kept these posts in the government formed in June 2024. In July 2023 Dharmendra Pradhan was Education Minister, Ashwini Vaishnaw held Railways and Electronics & IT, and Ramesh Pokhriyal 'Nishank' was a former Education Minister.","o":["Dharmendra Pradhan","Jitendra Singh","Ashwini Vaishnaw","Ramesh Pokhriyal"],"a":[1],"qt":"जुलाई 2023 तक की स्थिति के अनुसार, केंद्रीय विज्ञान एवं प्रौद्योगिकी राज्य मंत्री (स्वतंत्र प्रभार) कौन हैं?","ot":["धर्मेन्द्र प्रधान","जितेंद्र सिंह","अश्विनी वैष्णव","रमेश पोखरियाल"],"wt":"डॉ. जितेंद्र सिंह जुलाई 2021 के मंत्रिमंडल फेरबदल से विज्ञान एवं प्रौद्योगिकी तथा पृथ्वी विज्ञान के राज्य मंत्री (स्वतंत्र प्रभार) हैं, और वे प्रधानमंत्री कार्यालय, कार्मिक, परमाणु ऊर्जा तथा अंतरिक्ष के राज्य मंत्री भी हैं; जून 2024 में बनी सरकार में भी उन्होंने ये पद बनाए रखे। जुलाई 2023 में धर्मेन्द्र प्रधान शिक्षा मंत्री थे, अश्विनी वैष्णव के पास रेल तथा इलेक्ट्रॉनिकी एवं सूचना प्रौद्योगिकी मंत्रालय थे, और रमेश पोखरियाल 'निशंक' पूर्व शिक्षा मंत्री थे।"},{"id":"c24s1-36","p":"c24s1","n":36,"s":"sci","t":"Chemistry","q":"Which of the following decomposition reactions is NOT a redox reaction?","w":"A reaction is redox only if oxidation numbers change. In CaCO₃ → CaO + CO₂, calcium stays +2, carbon +4 and oxygen −2, so nothing is oxidised or reduced; NCERT cites it as a decomposition that is not a redox reaction. The others are redox: 2NaH → 2Na + H₂ (Na +1 to 0, H −1 to 0), 2KClO₃ → 2KCl + 3O₂ (Cl +5 to −1, O −2 to 0) and 2H₂O → 2H₂ + O₂ (H +1 to 0, O −2 to 0); dihydrogen monoxide is water.","o":["Decomposition of sodium hydride","Decomposition of calcium carbonate","Decomposition of potassium chlorate","Decomposition of dihydrogen monoxide"],"a":[1],"qt":"निम्नलिखित में से कौन-सी अपघटन अभिक्रिया रेडॉक्स अभिक्रिया नहीं है?","ot":["सोडियम हाइड्राइड का अपघटन","कैल्शियम कार्बोनेट का अपघटन","पोटैशियम क्लोरेट का अपघटन","डाइहाइड्रोजन मोनोऑक्साइड का अपघटन"],"wt":"कोई अभिक्रिया रेडॉक्स तभी होती है जब ऑक्सीकरण संख्याएँ बदलती हैं। CaCO₃ → CaO + CO₂ में कैल्शियम +2, कार्बन +4 और ऑक्सीजन −2 ही रहते हैं, अतः न कुछ ऑक्सीकृत होता है, न अपचित; NCERT इसे ऐसे अपघटन के उदाहरण के रूप में देता है जो रेडॉक्स अभिक्रिया नहीं है। अन्य सभी रेडॉक्स हैं: 2NaH → 2Na + H₂ (Na +1 से 0, H −1 से 0), 2KClO₃ → 2KCl + 3O₂ (Cl +5 से −1, O −2 से 0) और 2H₂O → 2H₂ + O₂ (H +1 से 0, O −2 से 0); डाइहाइड्रोजन मोनोऑक्साइड जल ही है।"},{"id":"c24s1-37","p":"c24s1","n":37,"s":"ih","t":"Modern India","q":"Who among the following has authored the play ‘Nil Darpan’?","w":"Nil Darpan (\"The Mirror of Indigo\"), a Bengali play by Dinabandhu Mitra published in 1860, portrayed the oppression of indigo cultivators by European planters in Bengal and won wide sympathy for the Indigo Revolt of 1859–60. Its English translation, attributed to Michael Madhusudan Dutt, was published by Rev. James Long, who was tried and punished for it. Chittaranjan Das and Motilal Nehru founded the Swaraj Party in 1923, and Sarojini Naidu was a poet and Congress leader.","o":["Chittaranjan Das","Motilal Nehru","Dinabandhu Mitra","Sarojini Naidu"],"a":[2],"qt":"निम्नलिखित में से किसने 'नील दर्पण' नाटक लिखा है?","ot":["चितरंजन दास","मोतीलाल नेहरू","दीनबंधु मित्र","सरोजिनी नायडू"],"wt":"दीनबंधु मित्र द्वारा रचित और 1860 में प्रकाशित बांग्ला नाटक नील दर्पण ('नील का दर्पण') में बंगाल के यूरोपीय बागान मालिकों द्वारा नील उगाने वाले किसानों पर किए गए अत्याचारों का चित्रण था, और इसने 1859–60 के नील विद्रोह के प्रति व्यापक सहानुभूति जगाई। इसका अंग्रेज़ी अनुवाद, जिसका श्रेय माइकल मधुसूदन दत्त को दिया जाता है, रेव. जेम्स लॉन्ग ने प्रकाशित किया, जिन पर इसके लिए मुकदमा चला और उन्हें दंड मिला। चितरंजन दास और मोतीलाल नेहरू ने 1923 में स्वराज पार्टी की स्थापना की थी, और सरोजिनी नायडू कवयित्री तथा कांग्रेस नेता थीं।"},{"id":"c24s1-38","p":"c24s1","n":38,"s":"ih","t":"Modern India","q":"Who among the following formed the Bihar Provincial Kisan Sabha in 1929?","w":"Swami Sahajanand Saraswati founded the Bihar Provincial Kisan Sabha in 1929 to mobilise peasants against zamindari oppression and to protect tenants' occupancy rights. He later became the first President of the All India Kisan Sabha, formed at Lucknow in 1936 with N.G. Ranga as general secretary. Kunwar Singh led the 1857 revolt in Bihar, J.M. Sengupta was a Bengal Congress leader, and Jayaprakash Narayan was a founder of the Congress Socialist Party (1934).","o":["Jayprakash Narayan","JM Sengupta","Kunwar Singh","Swami Sahajanand Saraswati"],"a":[3],"qt":"निम्नलिखित में से किसके द्वारा 1929 में बिहार प्रांतीय किसान सभा का गठन किया गया था?","ot":["जयप्रकाश नारायण","जे.एम. सेनगुप्ता","कुँवर सिंह","स्वामी सहजानंद सरस्वती"],"wt":"स्वामी सहजानंद सरस्वती ने 1929 में बिहार प्रांतीय किसान सभा की स्थापना की, ताकि ज़मींदारी अत्याचार के विरुद्ध किसानों को संगठित किया जा सके और काश्तकारों के दखलकारी अधिकारों की रक्षा हो सके। बाद में वे 1936 में लखनऊ में गठित अखिल भारतीय किसान सभा के पहले अध्यक्ष बने, जिसके महासचिव एन.जी. रंगा थे। कुँवर सिंह ने बिहार में 1857 के विद्रोह का नेतृत्व किया, जे.एम. सेनगुप्ता बंगाल के कांग्रेस नेता थे, और जयप्रकाश नारायण कांग्रेस सोशलिस्ट पार्टी (1934) के संस्थापकों में थे।"},{"id":"c24s1-39","p":"c24s1","n":39,"s":"geo","t":"Indian Geography","q":"Which plateaus are very fertile because they are rich in black soil that is very good for farming?","w":"The Deccan lava plateau of north-western peninsular India, spread over Maharashtra and parts of Gujarat, Madhya Pradesh and neighbouring states, was built by fissure eruptions of basalt lava, the Deccan Traps. Weathering of this basalt produced black soil, or regur, which is clayey, rich in lime, iron, magnesia and potash and holds moisture well, so it is ideal for cotton and is called black cotton soil. NCERT cites lava plateaus as rich in fertile black soil, whereas the African plateau is known mainly for gold and diamonds and the Katanga plateau for copper.","o":["Deccan lava plateau","African plateau","Ethiopian plateau","Katanga plateau"],"a":[0],"qt":"कौन-से पठार बहुत उपजाऊ होते हैं क्योंकि वे काली मृदा में समृद्ध होते हैं जो खेती के लिए बहुत अच्छी है?","ot":["दक्कन लावा पठार","अफ्रीकी पठार","इथियोपिया का पठार","कटंगा पठार"],"wt":"उत्तर-पश्चिमी प्रायद्वीपीय भारत का दक्कन लावा पठार, जो महाराष्ट्र तथा गुजरात, मध्य प्रदेश और पड़ोसी राज्यों के कुछ भागों में फैला है, बेसाल्ट लावा के दरारी उद्भेदन से बना है, जिसे दक्कन ट्रैप कहते हैं। इस बेसाल्ट के अपक्षय से काली मृदा या रेगुर बनी, जो चिकनी, चूना, लौह, मैग्नीशिया और पोटाश से समृद्ध होती है और नमी अच्छी तरह रोके रखती है; इसलिए यह कपास के लिए आदर्श है और काली कपास मृदा कहलाती है। NCERT लावा पठारों को उपजाऊ काली मृदा से समृद्ध बताता है, जबकि अफ्रीकी पठार मुख्यतः सोने और हीरे के लिए और कटंगा पठार ताँबे के लिए जाना जाता है।"},{"id":"c24s1-40","p":"c24s1","n":40,"s":"sci","t":"Chemistry","q":"Which of the following is a correct order of basicity?","w":"Alkali metal hydroxides are strong bases, and their basic strength increases down group 1: LiOH < NaOH < KOH < RbOH < CsOH. Going down the group, the atomic size increases and the ionisation enthalpy decreases, so the M–OH bond becomes more ionic and weaker and releases OH⁻ ions more readily in water. Hence CsOH is the strongest base and LiOH, with the small, highly polarising Li⁺ ion, is the weakest. Option 1 gives the exact reverse order.","o":["LiOH>NaOH>KOH>CsOH","KOH>CsOH>NaOH>LiOH","LiOH>KOH>CsOH>NaOH","CsOH>KOH>NaOH>LiOH"],"a":[3],"qt":"निम्नलिखित में से कौन-सा क्षारकता का सही क्रम है?","ot":["LiOH>NaOH>KOH>CsOH","KOH>CsOH>NaOH>LiOH","LiOH>KOH>CsOH>NaOH","CsOH>KOH>NaOH>LiOH"],"wt":"क्षार धातुओं के हाइड्रॉक्साइड प्रबल क्षारक हैं, और समूह 1 में नीचे जाने पर उनकी क्षारकता बढ़ती है: LiOH < NaOH < KOH < RbOH < CsOH। समूह में नीचे जाने पर परमाणु आकार बढ़ता है और आयनन एन्थैल्पी घटती है, जिससे M–OH बंध अधिक आयनिक और दुर्बल हो जाता है और जल में OH⁻ आयन अधिक आसानी से मुक्त करता है। अतः CsOH सबसे प्रबल क्षारक है और छोटे, अत्यधिक ध्रुवणकारी Li⁺ आयन वाला LiOH सबसे दुर्बल। विकल्प 1 ठीक उलटा क्रम देता है।"},{"id":"c24s1-41","p":"c24s1","n":41,"s":"sci","t":"Biology","q":"Which of the following pairs is INCORRECT regarding the grade of organisation and its example?","w":"Animals are grouped by grade of organisation: protoplasmic grade in protozoans such as Paramecium and Amoeba, where a single cell does all functions; cellular grade in sponges (Porifera) such as Sycon, with loose aggregates of cells; cell-tissue grade in cnidarians such as Hydra and jellyfish; tissue-organ grade in flatworms such as Planaria and tapeworm; and organ-system grade in higher animals. Euplectella (Venus's flower basket) is a glass sponge, so it belongs to the cellular grade, not the tissue-organ grade.","o":["Cell-tissue grade organisation - Jellyfish","Cellular grade organisation - Sycon","Protoplasmic grade organisation - Paramecium","Tissue-organ grade organisation - Euplectella"],"a":[3],"qt":"संगठन के ग्रेड और उसके उदाहरण के संबंध में निम्नलिखित में से कौन सी जोड़ी गलत है?","ot":["कोशिका-ऊतक ग्रेड संगठन - जेलीफ़िश","कोशिकीय ग्रेड संगठन - साइकोन","प्रोटोप्लाज्मिक ग्रेड संगठन - पैरामीशियम","ऊतक-अंग ग्रेड संगठन - यूप्लेक्टेला"],"wt":"जंतुओं को संगठन के ग्रेड के आधार पर बाँटा जाता है: प्रोटोप्लाज्मिक ग्रेड पैरामीशियम और अमीबा जैसे प्रोटोज़ोआ में, जहाँ एक ही कोशिका सारे कार्य करती है; कोशिकीय ग्रेड साइकोन जैसे स्पंजों (पोरिफेरा) में, जिनमें कोशिकाओं के ढीले समूह होते हैं; कोशिका-ऊतक ग्रेड हाइड्रा और जेलीफ़िश जैसे निडेरिया में; ऊतक-अंग ग्रेड प्लेनेरिया और फीताकृमि जैसे चपटे कृमियों में; और अंग-तंत्र ग्रेड उच्च जंतुओं में। यूप्लेक्टेला (वीनस का फूलदान) एक काँच स्पंज है, इसलिए यह ऊतक-अंग ग्रेड का नहीं, बल्कि कोशिकीय ग्रेड का है।"},{"id":"c24s1-42","p":"c24s1","n":42,"s":"cur","t":"Sports","q":"The head office of Board of Control for Cricket in India (BCCI) is located in ______.","w":"The Board of Control for Cricket in India (BCCI), formed in December 1928, has its headquarters at the Cricket Centre, Wankhede Stadium, Churchgate, in Mumbai. It is registered as a society under the Tamil Nadu Societies Registration Act, which makes Chennai a tempting option, and it is a full member of the International Cricket Council. Kolkata's Eden Gardens is the home of the Cricket Association of Bengal, not the BCCI's head office.","o":["Kolkata","Chennai","Mumbai","New Delhi"],"a":[2],"qt":"भारतीय क्रिकेट कंट्रोल बोर्ड (BCCI) का मुख्यालय ______ में स्थित है।","ot":["कोलकाता","चेन्नई","मुंबई","नई दिल्ली"],"wt":"दिसंबर 1928 में गठित भारतीय क्रिकेट कंट्रोल बोर्ड (BCCI) का मुख्यालय मुंबई में चर्चगेट स्थित वानखेड़े स्टेडियम के क्रिकेट सेंटर में है। यह तमिलनाडु सोसाइटी पंजीकरण अधिनियम के तहत एक सोसाइटी के रूप में पंजीकृत है, इसलिए चेन्नई एक भ्रामक विकल्प है, और यह अंतरराष्ट्रीय क्रिकेट परिषद (ICC) का पूर्ण सदस्य है। कोलकाता का ईडन गार्डन्स क्रिकेट एसोसिएशन ऑफ बंगाल का घरेलू मैदान है, BCCI का मुख्यालय नहीं।"},{"id":"c24s1-43","p":"c24s1","n":43,"s":"geo","t":"Indian Geography","q":"When the analysis of population density is done by calculating it through net cultivated area, then the measure is termed as:","w":"NCERT (India: People and Economy) defines physiological density as total population divided by net cultivated area; it shows the pressure of population on the land actually under crops. Agricultural density is different: it divides only the agricultural population (cultivators, agricultural labourers and their families) by net cultivable area. Arithmetic or gross density is total population per unit of total area, so only physiological density uses total population over net cultivated area.","o":["Net density","Gross density","Agricultural density","Physiological density"],"a":[3],"qt":"जब जनसंख्या घनत्व का विश्लेषण निवल खेती योग्य क्षेत्र के माध्यम से गणना करके किया जाता है, तो उस माप को क्या कहा जाता है?","ot":["निवल घनत्व (Net density)","सकल घनत्व (Gross density)","कृषि घनत्व (Agricultural density)","कार्यिकीय घनत्व (Physiological density)"],"wt":"NCERT (भारत: लोग और अर्थव्यवस्था) के अनुसार कार्यिकीय घनत्व = कुल जनसंख्या ÷ निवल कृषित क्षेत्र; यह वास्तव में फसलों के अंतर्गत भूमि पर जनसंख्या के दबाव को दर्शाता है। कृषि घनत्व इससे भिन्न है: इसमें केवल कृषि जनसंख्या (कृषक, खेतिहर मज़दूर और उनके परिवार) को निवल कृषि योग्य क्षेत्र से भाग दिया जाता है। गणितीय या सकल घनत्व कुल क्षेत्रफल की प्रति इकाई कुल जनसंख्या है, इसलिए केवल कार्यिकीय घनत्व ही कुल जनसंख्या को निवल कृषित क्षेत्र पर मापता है।"},{"id":"c24s1-44","p":"c24s1","n":44,"s":"ih","t":"Ancient India","q":"Mahendravarman I was the ruler of which of the following dynasties?","w":"Mahendravarman I (c. 600–630 CE), son of Simhavishnu, was a Pallava king of Kanchipuram. A patron of art and letters, he wrote the Sanskrit satirical play Mattavilasa Prahasana, introduced rock-cut temples in the Tamil region, such as the one at Mandagapattu, and bore titles like Vichitrachitta. Under the influence of the saint Appar he turned from Jainism to Shaivism. He fought the Chalukya king Pulakeshin II, a rivalry continued by his son Narasimhavarman I.","o":["Pallava","Pandya","Chalukya","Chola"],"a":[0],"qt":"महेंद्रवर्मन प्रथम, निम्नलिखित में से किस राजवंश का शासक था?","ot":["पल्लव","पंड्या","चालुक्य","चोल"],"wt":"सिंहविष्णु का पुत्र महेंद्रवर्मन प्रथम (लगभग 600–630 ई.) कांचीपुरम का पल्लव राजा था। कला और साहित्य के संरक्षक के रूप में उसने संस्कृत व्यंग्य नाटक मत्तविलास प्रहसन लिखा, तमिल क्षेत्र में मंडगपट्टु जैसे शैलकृत (चट्टान काटकर बने) मंदिरों की शुरुआत की, और विचित्रचित्त जैसी उपाधियाँ धारण कीं। संत अप्पर के प्रभाव में वह जैन धर्म छोड़कर शैव बना। उसने चालुक्य राजा पुलकेशिन द्वितीय से युद्ध किया, और यह प्रतिद्वंद्विता उसके पुत्र नरसिंहवर्मन प्रथम ने जारी रखी।"},{"id":"c24s1-45","p":"c24s1","n":45,"s":"eco","t":"Agriculture, Industry & Trade","q":"What challenge does foreign investment often face in India?","w":"Foreign investors in India often cite an inconsistent or unpredictable regulatory environment: frequent changes in rules, differing Central and state requirements, complex approvals and slow contract enforcement. A well-known example is the 2012 retrospective tax amendment that followed the Vodafone case, withdrawn only in 2021. India's large consumer market and big pool of workers attract investors rather than deter them, and foreign competition is not the main hurdle, so option 4 fits.","o":["Excessive foreign competition","Lack of skilled labour","Lack of consumer base","Inconsistent regulatory environment"],"a":[3],"qt":"भारत में विदेशी निवेश को अधिकतर किस चुनौती का सामना करना पड़ता है?","ot":["अत्यधिक विदेशी प्रतिस्पर्धा","कुशल श्रमिक अभाव","उपभोक्ता आधार अभाव","अस्थिर विनियामक परिवेश"],"wt":"भारत में विदेशी निवेशक प्रायः अस्थिर या अनिश्चित विनियामक परिवेश की शिकायत करते हैं: नियमों में बार-बार बदलाव, केंद्र और राज्यों की अलग-अलग आवश्यकताएँ, जटिल अनुमोदन प्रक्रिया और अनुबंधों का धीमा प्रवर्तन। इसका एक प्रसिद्ध उदाहरण वोडाफ़ोन मामले के बाद 2012 का पूर्वव्यापी कर संशोधन है, जिसे 2021 में जाकर वापस लिया गया। भारत का विशाल उपभोक्ता बाज़ार और बड़ी श्रमशक्ति निवेशकों को आकर्षित करते हैं, रोकते नहीं, और विदेशी प्रतिस्पर्धा मुख्य बाधा नहीं है, इसलिए विकल्प 4 उपयुक्त है।"},{"id":"c24s1-46","p":"c24s1","n":46,"s":"eco","t":"Agriculture, Industry & Trade","q":"Which of the following states is the biggest producer of Pulses?","w":"Madhya Pradesh is India's largest producer of pulses: in 2023-24 it produced about 6.2 million tonnes, roughly a quarter (25%) of national output, followed by Maharashtra (16%) and Rajasthan (15%). It leads in gram (chickpea), the most important pulse crop, and is also a leading producer of urad and masoor. Pulses are mostly rainfed crops grown on drylands in both the kharif and rabi seasons; Punjab and Haryana mainly grow irrigated wheat and rice, and Bihar produces far less.","o":["Bihar","Madhya Pradesh","Punjab","Haryana"],"a":[1],"qt":"निम्नलिखित में से कौन-सा राज्य दालों का सबसे बड़ा उत्पादक है?","ot":["बिहार","मध्य प्रदेश","पंजाब","हरियाणा"],"wt":"मध्य प्रदेश भारत का सबसे बड़ा दाल उत्पादक राज्य है: 2023-24 में इसने लगभग 6.2 मिलियन टन दालों का उत्पादन किया, जो राष्ट्रीय उत्पादन का लगभग एक-चौथाई (25%) है; इसके बाद महाराष्ट्र (16%) और राजस्थान (15%) आते हैं। यह सबसे महत्वपूर्ण दलहन फसल चना में अग्रणी है और उड़द तथा मसूर का भी प्रमुख उत्पादक है। दालें अधिकतर वर्षा-आधारित फसलें हैं जो शुष्क भूमि पर खरीफ और रबी दोनों मौसमों में उगाई जाती हैं; पंजाब और हरियाणा मुख्यतः सिंचित गेहूँ और चावल उगाते हैं, और बिहार का उत्पादन बहुत कम है।"},{"id":"c24s1-47","p":"c24s1","n":47,"s":"ih","t":"Modern India","q":"Who founded the Prarthana Samaj in Mumbai in 1867?","w":"The Prarthana Samaj (\"prayer society\") was founded in Bombay in 1867 by Dr Atmaram Pandurang, inspired by Keshab Chandra Sen of the Brahmo Samaj. It preached worship of one God and worked for social reform: inter-caste dining and marriage, widow remarriage, women's education and an end to child marriage. M.G. Ranade and R.G. Bhandarkar later became its leading figures. Raja Ram Mohan Roy founded the Brahmo Sabha (1828) in Calcutta, and Gokhale founded the Servants of India Society (1905).","o":["Gopal Krishna Gokhale","Shri Ram Bajpai","Atmaram Pandurang","Ram Mohan Roy"],"a":[2],"qt":"1867 में मुंबई में प्रार्थना-समाज की स्थापना किसने की थी?","ot":["गोपाल कृष्ण गोखले","श्री राम बाजपेयी","आत्माराम पांडुरंग","राम मोहन राय"],"wt":"प्रार्थना समाज ('प्रार्थना सभा') की स्थापना 1867 में बंबई में डॉ. आत्माराम पांडुरंग ने ब्रह्म समाज के केशवचंद्र सेन की प्रेरणा से की थी। इसने एक ईश्वर की उपासना का प्रचार किया और सामाजिक सुधार के लिए काम किया: अंतर्जातीय भोजन और विवाह, विधवा पुनर्विवाह, स्त्री शिक्षा और बाल विवाह की समाप्ति। बाद में एम.जी. रानाडे और आर.जी. भंडारकर इसके प्रमुख नेता बने। राजा राम मोहन राय ने कलकत्ता में ब्रह्म सभा (1828) की और गोखले ने सर्वेंट्स ऑफ इंडिया सोसाइटी (1905) की स्थापना की थी।"},{"id":"c24s1-48","p":"c24s1","n":48,"s":"cur","t":"National","q":"Who is the Chief Minister of Tamil Nadu as of July 2023?","w":"M.K. Stalin, president of the Dravida Munnetra Kazhagam (DMK) and son of former Chief Minister M. Karunanidhi, has been Chief Minister of Tamil Nadu since 7 May 2021, after the DMK-led alliance won the 2021 Assembly election, and he was still in office in September 2024. K.N. Nehru is a DMK minister in his cabinet, Pinarayi Vijayan is Chief Minister of Kerala, and B.S. Yediyurappa (\"M Yedurappa\" as printed) is a former Chief Minister of Karnataka.","o":["KN Nehru","Pinarayi Vijayan","M Yedurappa","MK Stalin"],"a":[3],"qt":"जुलाई 2023 तक की स्थिति के अनुसार, तमिलनाडु के मुख्यमंत्री कौन हैं?","ot":["के.एन. नेहरू","पिनाराई विजयन","एम. येदुरप्पा","एम.के. स्टालिन"],"wt":"द्रविड़ मुन्नेत्र कड़गम (DMK) के अध्यक्ष और पूर्व मुख्यमंत्री एम. करुणानिधि के पुत्र एम.के. स्टालिन, 2021 के विधानसभा चुनाव में DMK के नेतृत्व वाले गठबंधन की जीत के बाद 7 मई 2021 से तमिलनाडु के मुख्यमंत्री हैं, और सितंबर 2024 में भी वे इस पद पर थे। के.एन. नेहरू उनके मंत्रिमंडल में DMK के मंत्री हैं, पिनाराई विजयन केरल के मुख्यमंत्री हैं, और बी.एस. येदियुरप्पा (प्रश्न में 'एम. येदुरप्पा' छपा है) कर्नाटक के पूर्व मुख्यमंत्री हैं।"},{"id":"c24s1-49","p":"c24s1","n":49,"s":"cur","t":"Sports","q":"In which city was the first golf club of India situated?","w":"India's first golf club, the Royal Calcutta Golf Club, was founded in 1829 at Dum Dum in Calcutta (Kolkata), and it is regarded as the first golf club established outside the British Isles. It later moved to its present course at Tollygunge in south Kolkata. Hill-station courses such as Naldehra near Shimla and Gulmarg in Kashmir are famous, but they were laid out decades later, and Mysore's course is also a later one.","o":["Kolkata","Mysore","Shimla","Gulmarg"],"a":[0],"qt":"भारत का पहला गोल्फ क्लब किस शहर में स्थित था?","ot":["कोलकाता","मैसूर","शिमला","गुलमर्ग"],"wt":"भारत का पहला गोल्फ क्लब, रॉयल कलकत्ता गोल्फ क्लब, 1829 में कलकत्ता (कोलकाता) के दम दम में स्थापित हुआ था, और इसे ब्रिटिश द्वीपों के बाहर स्थापित पहला गोल्फ क्लब माना जाता है। बाद में यह दक्षिण कोलकाता के टॉलीगंज स्थित अपने वर्तमान मैदान पर चला गया। शिमला के पास नालदेहरा और कश्मीर में गुलमर्ग जैसे पर्वतीय गोल्फ मैदान प्रसिद्ध हैं, पर वे दशकों बाद बने, और मैसूर का गोल्फ मैदान भी बाद का है।"},{"id":"c24s1-50","p":"c24s1","n":50,"s":"cur","t":"Awards, Books & Persons","q":"Which Indian among the following has his name in Time Magazine’s list of ‘100 most influential people of 2021’?","w":"TIME magazine's list of the 100 most influential people of 2021, released in September 2021, named three Indians: Prime Minister Narendra Modi, West Bengal Chief Minister Mamata Banerjee and Serum Institute of India CEO Adar Poonawalla. Modi has featured on the list several times. Neeraj Chopra won India's first Olympic gold in athletics at Tokyo in August 2021 but was not on that list, and neither were Amit Shah nor Virat Kohli.","o":["Amit Shah","Narendra Modi","Neeraj Chopra","Virat Kohli"],"a":[1],"qt":"टाइम मैगज़ीन की '2021 के 100 सबसे प्रभावशाली लोगों' की सूची में निम्नलिखित में से किस भारतीय का नाम है?","ot":["अमित शाह","नरेंद्र मोदी","नीरज चोपड़ा","विराट कोहली"],"wt":"सितंबर 2021 में जारी टाइम पत्रिका की '2021 के 100 सबसे प्रभावशाली लोगों' की सूची में तीन भारतीय थे: प्रधानमंत्री नरेंद्र मोदी, पश्चिम बंगाल की मुख्यमंत्री ममता बनर्जी और सीरम इंस्टीट्यूट ऑफ इंडिया के CEO अदार पूनावाला। मोदी कई बार इस सूची में आ चुके हैं। नीरज चोपड़ा ने अगस्त 2021 में टोक्यो में एथलेटिक्स में भारत का पहला ओलंपिक स्वर्ण पदक जीता, पर वे उस सूची में नहीं थे, और न ही अमित शाह या विराट कोहली।"},{"id":"c24s1-51","p":"c24s1","n":51,"s":"qa","t":"Percentage, Profit & Interest","q":"A grocer professes to sell rice at the cost price, but uses a fake weight of 870 g for 1 kg. Find his profit percentage (correct to two decimal places).","w":"A dealer who sells at cost price but uses a false weight gains the weight he holds back. He hands over 870 g but charges for 1000 g, so he gains 130 g on goods that cost him 870 g. Profit % = 130/870 × 100 = 14.942… ≈ 14.94%. The base is the weight actually given (870 g); dividing by 1000 g would give only 13%.","o":["11.11%","14.94%","15.11%","18.21%"],"a":[1],"qt":"एक पंसारी लागत मूल्य पर चावल बेचने का दावा करता है, लेकिन 1 kg के लिए 870 g के नकली वजन का उपयोग करता है। उसका लाभ प्रतिशत (दो दशमलव स्थानों तक सही) ज्ञात कीजिए।","ot":["11.11%","14.94%","15.11%","18.21%"],"wt":"लागत मूल्य पर बेचने का दावा करने वाला पर नकली बाट प्रयोग करने वाला विक्रेता उतना ही वजन लाभ में पाता है जितना वह कम तौलता है। वह 870 g देता है पर 1000 g का मूल्य लेता है, अतः 870 g लागत वाले माल पर उसे 130 g का लाभ होता है। लाभ % = 130/870 × 100 = 14.942… ≈ 14.94%। आधार वास्तव में दिया गया वजन (870 g) है; 1000 g से भाग देने पर केवल 13% आएगा।"},{"id":"c24s1-52","p":"c24s1","n":52,"s":"qa","t":"Trigonometry & Heights","q":"The value of cos²29° + cos²61° is:","w":"The angles are complementary: 29° + 61° = 90°, so cos 61° = cos(90° − 29°) = sin 29°. The expression becomes cos²29° + sin²29°, which equals 1 by the identity sin²θ + cos²θ = 1. The same idea works for any pair of angles adding up to 90°, for example sin²20° + sin²70° = 1.","o":["√3/2","2","0","1"],"a":[3],"qt":"cos²29° + cos²61° का मान ज्ञात कीजिए।","ot":["√3/2","2","0","1"],"wt":"कोण पूरक हैं: 29° + 61° = 90°, अतः cos 61° = cos(90° − 29°) = sin 29°। व्यंजक cos²29° + sin²29° बन जाता है, जो सर्वसमिका sin²θ + cos²θ = 1 के अनुसार 1 के बराबर है। यही विधि उन सभी कोण-युग्मों पर लागू होती है जिनका योग 90° हो, जैसे sin²20° + sin²70° = 1।"},{"id":"c24s1-53","p":"c24s1","n":53,"s":"qa","t":"Time, Work, Speed & Distance","q":"In a circular race of 840 m, A and B start running in the same direction at the same time from the same point at the speeds of 6 m/s and 12 m/s, respectively. After how much time will they meet next?","w":"Running in the same direction, B gains on A at the relative speed 12 − 6 = 6 m/s. They meet again when B has gained one full lap of 840 m, which takes 840/6 = 140 s. Check: in 140 s A runs 840 m (1 lap) and B runs 1680 m (2 laps), so both are together again at the start. 70 s is only the time B needs for one lap.","o":["140 s","40 s","70 s","20 s"],"a":[0],"qt":"840 m की एक वृत्ताकार दौड़ में A और B समान समय पर समान दिशा में समान बिंदु से क्रमशः 6 m/s और 12 m/s की चाल से दौड़ना आरम्भ करते हैं। वे अगली बार कितने समय बाद मिलेंगे?","ot":["140 s","40 s","70 s","20 s"],"wt":"एक ही दिशा में दौड़ते हुए B, A से सापेक्ष चाल 12 − 6 = 6 m/s से आगे बढ़ता है। वे फिर तब मिलेंगे जब B, A से 840 m का एक पूरा चक्कर अधिक लगा ले, जिसमें 840/6 = 140 s लगते हैं। जाँच: 140 s में A 840 m (1 चक्कर) और B 1680 m (2 चक्कर) दौड़ता है, अतः दोनों फिर आरंभ बिंदु पर साथ होते हैं। 70 s तो केवल B के एक चक्कर का समय है।"},{"id":"c24s1-54","p":"c24s1","n":54,"s":"qa","t":"Geometry","q":"Let O be the centre of the circle and AB and CD are two parallel chords on the same side of the radius. OP is perpendicular to AB and OQ is perpendicular to CD. If AB = 10 cm, CD = 24 cm and PQ = 7 cm, then the diameter (in cm) of the circle is equal to:","w":"The perpendicular from the centre bisects a chord, so AP = 5 cm and CQ = 12 cm. \"Same side of the radius\" here means the same side of the centre; the longer chord is nearer the centre, so if OP = x then OQ = x − 7. Then r² = 5² + x² = 12² + (x − 7)², so 25 + x² = 144 + x² − 14x + 49, which gives x = 12. Radius = √(25 + 144) = 13 cm, so the diameter = 26 cm (13, the radius, is the trap).","o":["24","13","12","26"],"a":[3],"qt":"मान लीजिए कि, O वृत्त का केंद्र है और AB और CD, त्रिज्या की समान भुजा पर दो समानांतर जीवाएं हैं। OP, AB के लंबवत है और OQ, CD के लंबवत है। यदि AB = 10 cm है, CD = 24 cm और PQ = 7 cm है, तो वृत्त का व्यास (cm में) ______ होगा।","ot":["24","13","12","26"],"wt":"केंद्र से जीवा पर डाला गया लंब जीवा को समद्विभाजित करता है, अतः AP = 5 cm और CQ = 12 cm। \"त्रिज्या की समान भुजा पर\" का यहाँ अर्थ है केंद्र के एक ही ओर; बड़ी जीवा केंद्र के अधिक निकट होती है, अतः यदि OP = x तो OQ = x − 7। तब r² = 5² + x² = 12² + (x − 7)², अर्थात 25 + x² = 144 + x² − 14x + 49, जिससे x = 12 मिलता है। त्रिज्या = √(25 + 144) = 13 cm, अतः व्यास = 26 cm (13 त्रिज्या है, जो भ्रामक विकल्प है)।"},{"id":"c24s1-55","p":"c24s1","n":55,"s":"qa","t":"Geometry","q":"Which of the following statements is sufficient to conclude that two triangles are congruent?","w":"Congruence needs one of the standard tests: SSS, SAS, ASA/AAS or RHS. If two sides of one triangle equal two sides of the other and the perimeters are equal, the third sides are also equal (perimeter minus the two equal sides), so the triangles are congruent by SSS. One side and one angle are not enough. The same base with the same area, or the same base and height, only gives triangles of equal area, which can have different shapes.","o":["One side and one angle of both triangles are equal.","These have two equal sides and the same perimeter.","These have the same area and the same base.","These have the same base and the same height."],"a":[1],"qt":"निम्नलिखित में से कौन-सा कथन यह निष्कर्ष निकालने के लिए पर्याप्त है कि दो त्रिभुज सर्वांगसम हैं?","ot":["दोनों त्रिभुजों की एक भुजा और एक कोण बराबर हैं।","इनकी दो भुजाएँ बराबर हैं और परिमाप समान है।","इनके क्षेत्रफल और आधार समान हैं।","इनके आधार और ऊँचाई समान हैं।"],"wt":"सर्वांगसमता के लिए कोई एक मानक कसौटी चाहिए: SSS, SAS, ASA/AAS या RHS। यदि एक त्रिभुज की दो भुजाएँ दूसरे की दो भुजाओं के बराबर हों और परिमाप भी समान हो, तो तीसरी भुजाएँ भी बराबर होंगी (परिमाप में से दो बराबर भुजाएँ घटाने पर), अतः त्रिभुज SSS से सर्वांगसम हैं। केवल एक भुजा और एक कोण पर्याप्त नहीं हैं। समान आधार और समान क्षेत्रफल, या समान आधार और ऊँचाई से केवल बराबर क्षेत्रफल वाले त्रिभुज मिलते हैं, जिनके आकार भिन्न हो सकते हैं।"},{"id":"c24s1-56","p":"c24s1","n":56,"s":"qa","t":"Data Interpretation & Statistics","q":"The given table shows the percentage of marks obtained by three students in three different subjects in an institute.\n(maximum marks are given in brackets)\nStudent/Subject | History (175) | Geography (200) | Botany (125)\nRam | 54 | 87 | 71\nMohan | 51 | 79 | 78\nShyam | 75 | 49 | 76\nIf in order to pass the exam, a minimum of 105 marks are needed in History, how many students pass in the exam?","w":"The table gives percentages, so convert the pass mark into a percentage: 105 out of 175 = 105/175 × 100 = 60%. In History, Ram has 54%, Mohan 51% and Shyam 75%. Only Shyam reaches 60% (75% of 175 = 131.25 marks), while Ram gets 94.5 and Mohan 89.25 marks. So only 1 student passes. The Geography and Botany columns are not needed for this condition.","o":["2","3","1","0"],"a":[2],"qt":"दी गई तालिका में एक संस्थान में तीन अलग-अलग विषयों में तीन विद्यार्थियों द्वारा प्राप्त अंकों का प्रतिशत दर्शाया गया है।\nविद्यार्थी/विषय | इतिहास (175) | भूगोल (200) | वनस्पति विज्ञान (125)\nराम | 54 | 87 | 71\nमोहन | 51 | 79 | 78\nश्याम | 75 | 49 | 76\nयदि परीक्षा उत्तीर्ण करने के लिए इतिहास में न्यूनतम 105 अंक चाहिए, तो कितने विद्यार्थी परीक्षा में उत्तीर्ण हुए हैं?","ot":["2","3","1","0"],"wt":"तालिका में प्रतिशत दिए हैं, अतः उत्तीर्णांक को प्रतिशत में बदलें: 175 में से 105 = 105/175 × 100 = 60%। इतिहास में राम के 54%, मोहन के 51% और श्याम के 75% अंक हैं। केवल श्याम 60% तक पहुँचता है (175 का 75% = 131.25 अंक), जबकि राम को 94.5 और मोहन को 89.25 अंक मिले। अतः केवल 1 विद्यार्थी उत्तीर्ण होता है। इस शर्त के लिए भूगोल और वनस्पति विज्ञान के स्तंभों की आवश्यकता नहीं है।"},{"id":"c24s1-57","p":"c24s1","n":57,"s":"qa","t":"Time, Work, Speed & Distance","q":"Fill pipe P is 21 times faster than fill pipe Q. If Q can fill a cistern in 110 minutes, find the time it takes to fill the cistern when both fill pipes are opened together.","w":"Here \"21 times faster\" is taken, as SSC intends, to mean that P's rate of filling is 21 times Q's rate. Q fills 1/110 of the cistern per minute, so P fills 21/110 per minute. Together they fill 1/110 + 21/110 = 22/110 = 1/5 of the cistern per minute, so the cistern is full in 5 minutes. Reading \"21 times faster\" strictly as 22 times as fast would give 110/23 ≈ 4.8 minutes, which is not an option.","o":["3 minutes","5 minutes","4 minutes","6 minutes"],"a":[1],"qt":"भरण पाइप P, भरण पाइप Q से 21 गुना तेज है। यदि Q एक टंकी को 110 मिनट में भर सकता है, तो दोनों भरण पाइपों को एक साथ खोलने पर टंकी को भरने में कितना समय लगेगा?","ot":["3 मिनट","5 मिनट","4 मिनट","6 मिनट"],"wt":"यहाँ \"21 गुना तेज\" का अर्थ, जैसा SSC का आशय है, यह लिया गया है कि P के भरने की दर Q की दर की 21 गुनी है। Q प्रति मिनट टंकी का 1/110 भाग भरता है, अतः P प्रति मिनट 21/110 भाग भरता है। दोनों मिलकर प्रति मिनट 1/110 + 21/110 = 22/110 = 1/5 भाग भरते हैं, अतः टंकी 5 मिनट में भर जाती है। \"21 गुना तेज\" को कड़ाई से 22 गुनी चाल मानने पर 110/23 ≈ 4.8 मिनट आता, जो विकल्पों में नहीं है।"},{"id":"c24s1-58","p":"c24s1","n":58,"s":"qa","t":"Data Interpretation & Statistics","q":"The following table shows the marks (out of 100) obtained by five students in five different subjects.\nStudent/Subject | Maths | Physics | Chemistry | English | Physical Education\nTarun | 65 | 80 | 75 | 85 | 90\nRohit | 69 | 76 | 80 | 88 | 94\nMohit | 73 | 84 | 77 | 90 | 95\nShobhit | 76 | 85 | 76 | 86 | 78\nSumit | 90 | 88 | 78 | 82 | 68\nWho obtained 79% marks in all the subjects taken together?","w":"Each subject is out of 100, so the overall percentage is the total of the five marks out of 500. Tarun: 65 + 80 + 75 + 85 + 90 = 395, and 395/500 × 100 = 79%. The others score more: Rohit 407 (81.4%), Mohit 419 (83.8%), Sumit 406 (81.2%) and Shobhit 401 (80.2%). Hence Tarun is the student with 79%.","o":["Rohit","Tarun","Mohit","Sumit"],"a":[1],"qt":"निम्नलिखित तालिका पांच अलग-अलग विषयों में पांच छात्रों द्वारा प्राप्त अंक (100 में से) दर्शाती है।\nछात्र/विषय | गणित | भौतिकी | रसायन विज्ञान | अंग्रेजी | शारीरिक शिक्षा\nतरुण | 65 | 80 | 75 | 85 | 90\nरोहित | 69 | 76 | 80 | 88 | 94\nमोहित | 73 | 84 | 77 | 90 | 95\nशोभित | 76 | 85 | 76 | 86 | 78\nसुमित | 90 | 88 | 78 | 82 | 68\nसभी विषयों को मिलाकर 79% अंक किसने प्राप्त किए?","ot":["रोहित","तरुण","मोहित","सुमित"],"wt":"प्रत्येक विषय 100 अंकों का है, अतः कुल प्रतिशत पाँचों अंकों के योग को 500 में से लेकर निकलेगा। तरुण: 65 + 80 + 75 + 85 + 90 = 395, और 395/500 × 100 = 79%। अन्य छात्रों के अंक अधिक हैं: रोहित 407 (81.4%), मोहित 419 (83.8%), सुमित 406 (81.2%) और शोभित 401 (80.2%)। अतः 79% अंक तरुण ने प्राप्त किए।"},{"id":"c24s1-59","p":"c24s1","n":59,"s":"qa","t":"Algebra","q":"R pays ₹100 to P with ₹5, ₹2 and ₹1 coins. The total number of coins used for paying are 40. What is the number of coins of denomination ₹5 in the payment?","w":"Let the numbers of ₹5, ₹2 and ₹1 coins be a, b and c. Then a + b + c = 40 and 5a + 2b + c = 100. Subtracting gives 4a + b = 60, so b = 60 − 4a and c = 3a − 20. Neither can be negative, so 7 ≤ a ≤ 15. For 16, 17 or 18, b would be negative, so 13 is the only possible option: b = 8, c = 19 (65 + 16 + 19 = ₹100). The data also allow values not offered, such as 10.","o":["13","17","16","18"],"a":[0],"qt":"R, ₹5, ₹2 और ₹1 के सिक्कों में P को ₹100 का भुगतान करता है। भुगतान के लिए उपयोग किए गए सिक्कों की संख्या 40 है। भुगतान में ₹5 मूल्य-वर्ग के सिक्कों की संख्या कितनी है?","ot":["13","17","16","18"],"wt":"माना ₹5, ₹2 और ₹1 के सिक्कों की संख्या a, b और c है। तब a + b + c = 40 और 5a + 2b + c = 100। घटाने पर 4a + b = 60, अतः b = 60 − 4a और c = 3a − 20। इनमें से कोई ऋणात्मक नहीं हो सकता, अतः 7 ≤ a ≤ 15। 16, 17 या 18 पर b ऋणात्मक हो जाएगा, इसलिए केवल 13 संभव विकल्प है: b = 8, c = 19 (65 + 16 + 19 = ₹100)। आँकड़ों से ऐसे मान भी संभव हैं जो विकल्पों में नहीं हैं, जैसे 10।"},{"id":"c24s1-60","p":"c24s1","n":60,"s":"qa","t":"Mensuration","q":"The radii of the two cones are in the ratio of 2 : 5 and their volumes are in the ratio of 3 : 5. What is the ratio of their heights?","w":"Volume of a cone = (1/3)πr²h, so h is proportional to V/r². Hence h₁ : h₂ = (V₁/V₂) ÷ (r₁/r₂)² = (3/5) ÷ (2/5)² = (3/5) ÷ (4/25) = (3/5) × (25/4) = 15/4. The heights are in the ratio 15 : 4. A common slip is to divide by the ratio of the radii without squaring it, which gives 3 : 2.","o":["13 : 11","4 : 11","11 : 15","15 : 4"],"a":[3],"qt":"दो शंकुओं की त्रिज्याओं का अनुपात 2 : 5 और उनके आयतन का अनुपात 3 : 5 है। इनकी ऊंचाइयों का अनुपात क्या है?","ot":["13 : 11","4 : 11","11 : 15","15 : 4"],"wt":"शंकु का आयतन = (1/3)πr²h, अतः h, V/r² के समानुपाती है। इसलिए h₁ : h₂ = (V₁/V₂) ÷ (r₁/r₂)² = (3/5) ÷ (2/5)² = (3/5) ÷ (4/25) = (3/5) × (25/4) = 15/4। ऊँचाइयों का अनुपात 15 : 4 है। एक आम भूल त्रिज्याओं के अनुपात का वर्ग किए बिना भाग देना है, जिससे 3 : 2 आता है।"},{"id":"c24s1-61","p":"c24s1","n":61,"s":"qa","t":"Number System & Simplification","q":"Which of the following can be the value of ‘k’ so that the number 217924k is divisible by 6?","w":"A number is divisible by 6 when it is divisible by both 2 and 3. For 2, the last digit k must be even. For 3, the digit sum 2 + 1 + 7 + 9 + 2 + 4 + k = 25 + k must be a multiple of 3, so k = 2, 5 or 8. The even values are 2 and 8, and only 2 is offered (2179242 = 6 × 363207). For k = 6, 0 and 4 the digit sums 31, 25 and 29 are not multiples of 3.","o":["2","6","0","4"],"a":[0],"qt":"निम्नलिखित में से कौन-सा 'k' का मान हो सकता है जिससे कि संख्या 217924k, 6 से विभाज्य हो?","ot":["2","6","0","4"],"wt":"कोई संख्या 6 से तभी विभाज्य है जब वह 2 और 3 दोनों से विभाज्य हो। 2 के लिए अंतिम अंक k सम होना चाहिए। 3 के लिए अंकों का योग 2 + 1 + 7 + 9 + 2 + 4 + k = 25 + k, 3 का गुणज होना चाहिए, अतः k = 2, 5 या 8। इनमें सम मान 2 और 8 हैं, और विकल्पों में केवल 2 है (2179242 = 6 × 363207)। k = 6, 0 और 4 पर अंकों का योग 31, 25 और 29 है, जो 3 के गुणज नहीं हैं।"},{"id":"c24s1-62","p":"c24s1","n":62,"s":"qa","t":"Percentage, Profit & Interest","q":"In an election between two candidates, y% of the voters did not vote. 10% of the votes cast were declared invalid, while all the valid votes were cast in favour of either of the two candidates. The candidate who got 59.375% of the valid votes cast was declared elected by 2484 votes. If the number of people eligible to vote in that election was 16,000, what is the value of y?","w":"The winner got 59.375% of the valid votes and the loser 100 − 59.375 = 40.625%, so the margin is 18.75% of the valid votes = 2484. Valid votes = 2484/0.1875 = 13,248. These are 90% of the votes cast, so votes cast = 13,248/0.9 = 14,720. People who did not vote = 16,000 − 14,720 = 1,280, which is 1,280/16,000 × 100 = 8% of those eligible. Hence y = 8.","o":["8","8.4","7.5","7.2"],"a":[0],"qt":"दो उम्मीदवारों के बीच हुए एक चुनाव में, y% मतदाताओं ने मत नहीं डाला। डाले गए मतों में से 10% मत अवैध घोषित कर दिए गए, जबकि सभी वैध मत दोनों उम्मीदवारों में से किसी एक के पक्ष में पड़े। जिस उम्मीदवार को कुल वैध मतों में से 59.375% मत मिले, उसे 2484 मतों से निर्वाचित घोषित किया गया। यदि उस चुनाव में मतदान करने के पात्र लोगों की संख्या 16,000 थी, तो y का मान ज्ञात करें।","ot":["8","8.4","7.5","7.2"],"wt":"विजेता को वैध मतों का 59.375% और हारने वाले को 100 − 59.375 = 40.625% मिला, अतः अंतर वैध मतों का 18.75% = 2484 है। वैध मत = 2484/0.1875 = 13,248। ये डाले गए मतों का 90% हैं, अतः डाले गए मत = 13,248/0.9 = 14,720। मत न डालने वाले = 16,000 − 14,720 = 1,280, जो पात्र लोगों का 1,280/16,000 × 100 = 8% है। अतः y = 8।"},{"id":"c24s1-63","p":"c24s1","n":63,"s":"qa","t":"Percentage, Profit & Interest","q":"An article is marked at ₹550. If it is sold at a discount of 40%, then the selling price becomes 10% more than its cost price. What is the cost price (in ₹)?","w":"Selling price after a 40% discount = 60% of ₹550 = ₹330. This is 10% more than the cost price, so SP = 110% of CP and CP = 330/1.1 = ₹300. Check: 300 + 10% of 300 = 300 + 30 = ₹330. The option 330 is the selling price, not the cost price; 220 is only the amount of the discount.","o":["330","220","300","200"],"a":[2],"qt":"एक वस्तु पर ₹550 अंकित है। यदि इसे 40% की छूट पर बेचा जाता है, तो विक्रय मूल्य इसके क्रय मूल्य से 10% अधिक हो जाता है। क्रय मूल्य (₹ में) ज्ञात करें।","ot":["330","220","300","200"],"wt":"40% छूट के बाद विक्रय मूल्य = ₹550 का 60% = ₹330। यह क्रय मूल्य से 10% अधिक है, अतः विक्रय मूल्य = क्रय मूल्य का 110% और क्रय मूल्य = 330/1.1 = ₹300। जाँच: 300 + 300 का 10% = 300 + 30 = ₹330। विकल्प 330 विक्रय मूल्य है, क्रय मूल्य नहीं; 220 केवल छूट की राशि है।"},{"id":"c24s1-64","p":"c24s1","n":64,"s":"qa","t":"Geometry","q":"If the sum of two sides of an equilateral triangle is 16 cm, then find the third side.","w":"All three sides of an equilateral triangle are equal. If two sides together measure 16 cm, each side is 16/2 = 8 cm, so the third side is also 8 cm (perimeter 24 cm). \"Cannot be found\" would be right for a general triangle, where the third side can only be bounded between the difference and the sum of the other two, but not for an equilateral one.","o":["Cannot be found","16 cm","4 cm","8 cm"],"a":[3],"qt":"यदि एक समबाहु त्रिभुज की दो भुजाओं का योग 16 cm है, तो तीसरी भुजा ज्ञात कीजिए।","ot":["ज्ञात नहीं किया जा सकता है","16 cm","4 cm","8 cm"],"wt":"समबाहु त्रिभुज की तीनों भुजाएँ बराबर होती हैं। यदि दो भुजाओं का योग 16 cm है, तो प्रत्येक भुजा 16/2 = 8 cm है, अतः तीसरी भुजा भी 8 cm है (परिमाप 24 cm)। \"ज्ञात नहीं किया जा सकता है\" किसी सामान्य त्रिभुज के लिए सही होता, जहाँ तीसरी भुजा को केवल अन्य दो भुजाओं के अंतर और योग के बीच सीमित किया जा सकता है, पर समबाहु त्रिभुज के लिए नहीं।"},{"id":"c24s1-65","p":"c24s1","n":65,"s":"qa","t":"Algebra","q":"Simplify (x² − 9)/(x + 3)","w":"Factorise the numerator as a difference of squares: x² − 9 = x² − 3² = (x − 3)(x + 3). Then (x² − 9)/(x + 3) = (x − 3)(x + 3)/(x + 3) = x − 3, for x ≠ −3. Only common factors can be cancelled; dividing the terms separately or taking a square root, as in the other options, is not a valid step.","o":["x − 9","x + 3","x − 3","√(x² − 9)"],"a":[2],"qt":"(x² − 9)/(x + 3) का मान क्या होगा?","ot":["x − 9","x + 3","x − 3","√(x² − 9)"],"wt":"अंश का गुणनखंड वर्गों के अंतर के रूप में करें: x² − 9 = x² − 3² = (x − 3)(x + 3)। तब (x² − 9)/(x + 3) = (x − 3)(x + 3)/(x + 3) = x − 3, जहाँ x ≠ −3। केवल उभयनिष्ठ गुणनखंड ही काटे जा सकते हैं; पदों को अलग-अलग भाग देना या वर्गमूल लेना, जैसा अन्य विकल्पों में है, सही चरण नहीं है।"},{"id":"c24s1-66","p":"c24s1","n":66,"s":"qa","t":"Data Interpretation & Statistics","q":"The following table shows the total candidates appeared and number of candidates present, in different exam centres – P, Q and R.\nStudy the table and answer the question that follows.\nYear | P Total | P Present | Q Total | Q Present | R Total | R Present\n2016 | 45 | 42 | 56 | 45 | 55 | 50\n2017 | 50 | 45 | 75 | 55 | 45 | 40\n2018 | 64 | 60 | 65 | 45 | 65 | 55\n2019 | 80 | 69 | 84 | 72 | 70 | 62\n2020 | 55 | 44 | 80 | 66 | 90 | 85\n‘Total’ denotes total candidates applied for the centre, ‘Present’ denotes the candidates appeared.\nIn which year was the number of absentees the second highest in total of all centres?","w":"Absentees = Total − Present at each centre, added over P, Q and R. 2016: 3 + 11 + 5 = 19; 2017: 5 + 20 + 5 = 30; 2018: 4 + 20 + 10 = 34; 2019: 11 + 12 + 8 = 31; 2020: 11 + 14 + 5 = 30. The highest is 2018 (34) and the second highest is 2019 (31). Option 2018 is the trap for anyone who answers \"highest\" instead of \"second highest\".","o":["2018","2019","2020","2017"],"a":[1],"qt":"निम्नलिखित तालिका विभिन्न परीक्षा केंद्रों - P, Q और R में कुल उपस्थित उम्मीदवारों और उपस्थित उम्मीदवारों की संख्या को दर्शाती है।\nतालिका का अध्ययन कीजिए और निम्नलिखित प्रश्न का उत्तर दीजिए।\nवर्ष | P कुल | P उपस्थित | Q कुल | Q उपस्थित | R कुल | R उपस्थित\n2016 | 45 | 42 | 56 | 45 | 55 | 50\n2017 | 50 | 45 | 75 | 55 | 45 | 40\n2018 | 64 | 60 | 65 | 45 | 65 | 55\n2019 | 80 | 69 | 84 | 72 | 70 | 62\n2020 | 55 | 44 | 80 | 66 | 90 | 85\n'कुल' केंद्र के लिए आवेदन करने वाले कुल उम्मीदवारों को दर्शाता है, 'उपस्थित' उपस्थित उम्मीदवारों को दर्शाता है।\nकिस वर्ष में सभी केन्द्रों में अनुपस्थित रहने वालों की संख्या दूसरी सबसे अधिक थी?","ot":["2018","2019","2020","2017"],"wt":"प्रत्येक केंद्र पर अनुपस्थित = कुल − उपस्थित, फिर P, Q और R का योग करें। 2016: 3 + 11 + 5 = 19; 2017: 5 + 20 + 5 = 30; 2018: 4 + 20 + 10 = 34; 2019: 11 + 12 + 8 = 31; 2020: 11 + 14 + 5 = 30। सबसे अधिक संख्या 2018 (34) में और दूसरी सबसे अधिक 2019 (31) में है। \"दूसरी सबसे अधिक\" के स्थान पर \"सबसे अधिक\" का उत्तर देने वालों के लिए 2018 भ्रामक विकल्प है।"},{"id":"c24s1-67","p":"c24s1","n":67,"s":"qa","t":"Geometry","q":"The distance between the centres of two circles of radii 22 cm and 10 cm is 37 cm. If the points of contact of a direct common tangent to these circles are M and Q, then find the length of the line segment MQ.","w":"Length of a direct common tangent = √(d² − (r₁ − r₂)²), where d is the distance between the centres. Here d = 37 cm and r₁ − r₂ = 22 − 10 = 12 cm, so MQ = √(37² − 12²) = √(1369 − 144) = √1225 = 35 cm. A transverse common tangent would use (r₁ + r₂)² instead, giving √(1369 − 1024) = √345 ≈ 18.6 cm, which is not what is asked.","o":["39 cm","29 cm","35 cm","25 cm"],"a":[2],"qt":"22 cm और 10 cm त्रिज्या वाले दो वृत्तों के केंद्रों के बीच की दूरी 37 cm है। यदि इन वृत्तों की सीधी उभयनिष्ठ अनुस्पर्श रेखा के स्पर्श बिंदु (points of contact) M और Q हैं, तो रेखाखंड MQ की लंबाई ज्ञात कीजिए।","ot":["39 cm","29 cm","35 cm","25 cm"],"wt":"सीधी उभयनिष्ठ स्पर्श रेखा की लंबाई = √(d² − (r₁ − r₂)²), जहाँ d केंद्रों के बीच की दूरी है। यहाँ d = 37 cm और r₁ − r₂ = 22 − 10 = 12 cm, अतः MQ = √(37² − 12²) = √(1369 − 144) = √1225 = 35 cm। अनुप्रस्थ उभयनिष्ठ स्पर्श रेखा के लिए (r₁ + r₂)² का प्रयोग होता, जिससे √(1369 − 1024) = √345 ≈ 18.6 cm आता; वह यहाँ नहीं पूछा गया है।"},{"id":"c24s1-68","p":"c24s1","n":68,"s":"qa","t":"Trigonometry & Heights","q":"The value of sin²30 − sin²40 + sin²45 − sin²55 − sin²35 + sin²45 − sin²50 + sin²60 is:","w":"The angles are in degrees. Use sin²θ + sin²(90° − θ) = sin²θ + cos²θ = 1 and regroup the terms into complementary pairs: (sin²30 + sin²60) + (sin²45 + sin²45) − (sin²40 + sin²50) − (sin²55 + sin²35). Each bracket equals 1 (sin²45 = 1/2, taken twice, also gives 1). So the value is 1 + 1 − 1 − 1 = 0.","o":["4","0","1","2"],"a":[1],"qt":"sin²30 − sin²40 + sin²45 − sin²55 − sin²35 + sin²45 − sin²50 + sin²60 का मान ज्ञात कीजिए।","ot":["4","0","1","2"],"wt":"कोण अंश (डिग्री) में हैं। sin²θ + sin²(90° − θ) = sin²θ + cos²θ = 1 का प्रयोग करें और पदों को पूरक युग्मों में समूहित करें: (sin²30 + sin²60) + (sin²45 + sin²45) − (sin²40 + sin²50) − (sin²55 + sin²35)। प्रत्येक कोष्ठक का मान 1 है (sin²45 = 1/2, दो बार लेने पर भी 1)। अतः मान = 1 + 1 − 1 − 1 = 0।"},{"id":"c24s1-69","p":"c24s1","n":69,"s":"qa","t":"Ratio, Average & Mixtures","q":"The average marks (out of 100) of boys and girls in an examination are 75 and 80, respectively. If the average marks of all the students in that examination are 78. Find the ratio of the number of boys to the number of girls.","w":"Use alligation. Boys average 75, girls 80 and all students 78, so boys : girls = (80 − 78) : (78 − 75) = 2 : 3. Check: with 2 boys and 3 girls the total is 2 × 75 + 3 × 80 = 150 + 240 = 390, and 390/5 = 78. The overall average lies nearer the girls' 80, so there are more girls than boys; the other ratios fail the check.","o":["1 : 3","2 : 3","1 : 2","3 : 4"],"a":[1],"qt":"एक परीक्षा में लड़कों और लड़कियों के औसत अंक (100 में से) क्रमशः 75 और 80 हैं। यदि उस परीक्षा में सभी विद्यार्थियों के औसत अंक 78 हों तो लड़कों की संख्या और लड़कियों की संख्या का अनुपात ज्ञात कीजिए।","ot":["1 : 3","2 : 3","1 : 2","3 : 4"],"wt":"एलीगेशन (मिश्रण नियम) का प्रयोग करें। लड़कों का औसत 75, लड़कियों का 80 और सभी विद्यार्थियों का 78 है, अतः लड़के : लड़कियाँ = (80 − 78) : (78 − 75) = 2 : 3। जाँच: 2 लड़कों और 3 लड़कियों के कुल अंक = 2 × 75 + 3 × 80 = 150 + 240 = 390, और 390/5 = 78। समग्र औसत लड़कियों के 80 के अधिक निकट है, अतः लड़कियाँ लड़कों से अधिक हैं; अन्य अनुपात जाँच में खरे नहीं उतरते।"},{"id":"c24s1-70","p":"c24s1","n":70,"s":"qa","t":"Time, Work, Speed & Distance","q":"Rajesh, in his printing press, got an order to print some books, out of which he completed 17/27 of the order in 34 days. In how many days did he complete the entire order of printing?","w":"At a constant rate of work, 17/27 of the order takes 34 days, so 1/27 of the order takes 34/17 = 2 days. The whole order (27/27) therefore takes 27 × 2 = 54 days. Equivalently, total time = 34 ÷ (17/27) = 34 × 27/17 = 54 days. The remaining 10/27 of the order took 20 days, which is why 20 appears as a distractor.","o":["54","60","56","20"],"a":[0],"qt":"राजेश को उसके प्रिंटिग प्रेस में कुछ किताबें छापने का ऑर्डर मिला, जिसमें से उसने ऑर्डर के 17/27 को 34 दिनों में पूरा किया। उसने छपाई का पूरा ऑर्डर कितने दिनों में पूरा किया?","ot":["54","60","56","20"],"wt":"कार्य की दर स्थिर मानने पर ऑर्डर का 17/27 भाग 34 दिनों में पूरा होता है, अतः 1/27 भाग 34/17 = 2 दिनों में। पूरा ऑर्डर (27/27) 27 × 2 = 54 दिनों में पूरा होता है। अथवा, कुल समय = 34 ÷ (17/27) = 34 × 27/17 = 54 दिन। शेष 10/27 भाग में 20 दिन लगे, इसीलिए 20 भ्रामक विकल्प के रूप में दिया गया है।"},{"id":"c24s1-71","p":"c24s1","n":71,"s":"qa","t":"Algebra","q":"Simplify (x³ + 15x² + 75x + 125)/(x² − 25) × (x − 5).","w":"The numerator is a perfect cube: x³ + 15x² + 75x + 125 = x³ + 3·x²·5 + 3·x·5² + 5³ = (x + 5)³. The denominator is x² − 25 = (x − 5)(x + 5). So the expression = (x + 5)³/[(x − 5)(x + 5)] × (x − 5) = (x + 5)² = x² + 10x + 25. Option x² + 25 forgets the middle term 2 × x × 5 = 10x.","o":["x² + 5x + 25","x² − 25","x² + 10x + 25","x² + 25"],"a":[2],"qt":"सरल कीजिए : (x³ + 15x² + 75x + 125)/(x² − 25) × (x − 5)","ot":["x² + 5x + 25","x² − 25","x² + 10x + 25","x² + 25"],"wt":"अंश एक पूर्ण घन है: x³ + 15x² + 75x + 125 = x³ + 3·x²·5 + 3·x·5² + 5³ = (x + 5)³। हर x² − 25 = (x − 5)(x + 5) है। अतः व्यंजक = (x + 5)³/[(x − 5)(x + 5)] × (x − 5) = (x + 5)² = x² + 10x + 25। विकल्प x² + 25 में मध्य पद 2 × x × 5 = 10x छूट गया है।"},{"id":"c24s1-72","p":"c24s1","n":72,"s":"qa","t":"Trigonometry & Heights","q":"If cosec θ = 5/3, then evaluate (sec²θ − 1) × cot²θ × (1 + cot²θ).","w":"Use the identities sec²θ − 1 = tan²θ and 1 + cot²θ = cosec²θ. The expression becomes tan²θ × cot²θ × cosec²θ, and since tan θ × cot θ = 1 it reduces to cosec²θ = (5/3)² = 25/9. Check with sin θ = 3/5: tan²θ = 9/16, cot²θ = 16/9 and cosec²θ = 25/9, whose product is 25/9.","o":["9/16","25/9","25/16","4/5"],"a":[1],"qt":"यदि cosec θ = 5/3 है, तो (sec²θ − 1) × cot²θ × (1 + cot²θ) का मान ज्ञात कीजिए।","ot":["9/16","25/9","25/16","4/5"],"wt":"सर्वसमिकाओं sec²θ − 1 = tan²θ और 1 + cot²θ = cosec²θ का प्रयोग करें। व्यंजक tan²θ × cot²θ × cosec²θ बन जाता है, और tan θ × cot θ = 1 होने से यह cosec²θ = (5/3)² = 25/9 रह जाता है। sin θ = 3/5 से जाँच: tan²θ = 9/16, cot²θ = 16/9 और cosec²θ = 25/9, जिनका गुणनफल 25/9 है।"},{"id":"c24s1-73","p":"c24s1","n":73,"s":"qa","t":"Algebra","q":"Which of the following can be the value of k, if (88 ÷ 8 × k − 3 × 3)/(6² − 7 × 5 + k²) = 1?","w":"Apply BODMAS (÷ and × from left to right before − and +). Numerator: 88 ÷ 8 × k − 3 × 3 = 11k − 9. Denominator: 6² − 7 × 5 + k² = 36 − 35 + k² = 1 + k². Setting the fraction equal to 1 gives 11k − 9 = 1 + k², i.e. k² − 11k + 10 = 0, so (k − 1)(k − 10) = 0 and k = 1 or 10. Check k = 10: (110 − 9)/(1 + 100) = 101/101 = 1.","o":["2,7","4,7","3,10","1,10"],"a":[3],"qt":"यदि (88 ÷ 8 × k − 3 × 3)/(6² − 7 × 5 + k²) = 1 है तो निम्नलिखित में से k का मान क्या हो सकता है?","ot":["2,7","4,7","3,10","1,10"],"wt":"BODMAS लागू करें (− और + से पहले ÷ और × बाएँ से दाएँ)। अंश: 88 ÷ 8 × k − 3 × 3 = 11k − 9। हर: 6² − 7 × 5 + k² = 36 − 35 + k² = 1 + k²। भिन्न को 1 के बराबर रखने पर 11k − 9 = 1 + k², अर्थात k² − 11k + 10 = 0, अतः (k − 1)(k − 10) = 0 और k = 1 या 10। k = 10 की जाँच: (110 − 9)/(1 + 100) = 101/101 = 1।"},{"id":"c24s1-74","p":"c24s1","n":74,"s":"qa","t":"Data Interpretation & Statistics","q":"Read the given information and answer the question that follows.\nThe following table gives the percentage of marks obtained by seven students in six different subjects in an examination.\nThe number in the brackets give the maximum marks in each subject.\nStudent | Maths (150) | Chemistry (130) | Physics (120) | Geography (100) | History (60) | Computer Science (40)\nAyush | 90 | 50 | 90 | 60 | 70 | 80\nAman | 100 | 80 | 80 | 40 | 80 | 70\nSajal | 90 | 60 | 70 | 70 | 90 | 70\nRohit | 80 | 65 | 80 | 80 | 60 | 60\nMuskan | 80 | 65 | 85 | 95 | 50 | 90\nTanvi | 70 | 75 | 65 | 85 | 40 | 60\nTarun | 65 | 35 | 50 | 77 | 80 | 80\nIf someone secured all the highest scores that have been obtained by some student or the other in the six subjects [rest of the question cut off on the SSC sheet; editorial completion: as given in the table above, what would be the exact overall percentage score obtained by that student?]","w":"The last line of the question is cut off on SSC's sheet; the bracketed words complete it. Convert the highest percentage in each subject into marks: Maths 100% of 150 = 150; Chemistry 80% of 130 = 104; Physics 90% of 120 = 108; Geography 95% of 100 = 95; History 90% of 60 = 54; Computer Science 90% of 40 = 36. Total = 547 out of 600, so the percentage = 547/600 × 100 = 91.166…% = 91 1/6%. Simply averaging the six percentages (545/6 = 90 5/6%) ignores the different maximum marks.","o":["90 5/6%","91 1/6%","95.16%","91%"],"a":[1],"qt":"दी गई जानकारी को ध्यानपूर्वक पढ़ें और आगे दिए गए प्रश्न का उत्तर दें।\nनीचे दी गई तालिका में एक परीक्षा के छह अलग-अलग विषयों में सात विद्यार्थियों द्वारा प्राप्त अंकों का प्रतिशत दर्शाया गया है।\nकोष्ठक में दी गई संख्या प्रत्येक विषय के अधिकतम अंक को दर्शाती है।\nविद्यार्थी | गणित (150) | रसायन विज्ञान (130) | भौतिकी (120) | भूगोल (100) | इतिहास (60) | कंप्यूटर विज्ञान (40)\nआयुष | 90 | 50 | 90 | 60 | 70 | 80\nअमन | 100 | 80 | 80 | 40 | 80 | 70\nसजल | 90 | 60 | 70 | 70 | 90 | 70\nरोहित | 80 | 65 | 80 | 80 | 60 | 60\nमुस्कान | 80 | 65 | 85 | 95 | 50 | 90\nतान्वी | 70 | 75 | 65 | 85 | 40 | 60\nतरुण | 65 | 35 | 50 | 77 | 80 | 80\nयदि किसी ने उपरोक्त तालिका में दिए गए छह विषयों में किसी भी विद्यार्थी या अन्य को प्राप्त अंकों की [प्रश्न का शेष भाग SSC की शीट पर कटा हुआ है; संपादकीय पूर्ति: सूची में से प्रत्येक विषय के सर्वोच्च अंक प्राप्त किए हों, तो उसका ठीक-ठीक कुल प्रतिशत कितना होगा?]","ot":["90 5/6%","91 1/6%","95.16%","91%"],"wt":"SSC की शीट पर प्रश्न की अंतिम पंक्ति कटी हुई है; कोष्ठक के शब्द उसे पूरा करते हैं। प्रत्येक विषय के सर्वोच्च प्रतिशत को अंकों में बदलें: गणित 150 का 100% = 150; रसायन विज्ञान 130 का 80% = 104; भौतिकी 120 का 90% = 108; भूगोल 100 का 95% = 95; इतिहास 60 का 90% = 54; कंप्यूटर विज्ञान 40 का 90% = 36। कुल = 600 में से 547, अतः प्रतिशत = 547/600 × 100 = 91.166…% = 91 1/6%। छह प्रतिशतों का सीधा औसत (545/6 = 90 5/6%) विषयों के अलग-अलग अधिकतम अंकों की उपेक्षा करता है।"},{"id":"c24s1-75","p":"c24s1","n":75,"s":"qa","t":"Percentage, Profit & Interest","q":"Mohan borrows a sum of ₹4,22,092 at the rate of 20% per annum simple interest. At the end of the first year, he repays ₹21,679 towards return of principal amount borrowed. If Mohan clears all pending dues at the end of the second year, including interest payment that accrued during the first year, how much does he pay (in ₹) at the end of the second year?","w":"Interest for year 1 = 20% of ₹4,22,092 = ₹84,418.40. After the repayment of ₹21,679, all of it towards principal, the principal is 4,22,092 − 21,679 = ₹4,00,413. Interest for year 2 = 20% of 4,00,413 = ₹80,082.60. At the end of year 2 he pays the remaining principal plus both years' interest: 4,00,413 + 84,418.40 + 80,082.60 = ₹5,64,914.","o":["561347","564914","558380","556367"],"a":[1],"qt":"मोहन ने 20% वार्षिक साधारण ब्याज की दर से ₹4,22,092 की राशि उधार ली। प्रथम वर्ष की समाप्ति पर, वह उधार ली गई मूल राशि की वापसी के लिए ₹21,679 चुकाता है। यदि मोहन दूसरे वर्ष की समाप्ति पर सभी लंबित बकाया राशि का भुगतान करता है, जिसमें प्रथम वर्ष के दौरान अर्जित ब्याज भुगतान भी शामिल है, तो वह दूसरे वर्ष की समाप्ति पर कितना भुगतान (₹ में) करेगा?","ot":["5,61,347","5,64,914","5,58,380","5,56,367"],"wt":"प्रथम वर्ष का ब्याज = ₹4,22,092 का 20% = ₹84,418.40। ₹21,679 पूरी तरह मूलधन की वापसी में चुकाने के बाद मूलधन = 4,22,092 − 21,679 = ₹4,00,413। दूसरे वर्ष का ब्याज = 4,00,413 का 20% = ₹80,082.60। दूसरे वर्ष के अंत में वह शेष मूलधन और दोनों वर्षों का ब्याज चुकाता है: 4,00,413 + 84,418.40 + 80,082.60 = ₹5,64,914।"},{"id":"c24s1-76","p":"c24s1","n":76,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nFatal","w":"'Fatal' means causing death or capable of causing death, as in 'a fatal accident' or 'a fatal disease'; it can also describe something that leads to failure or disaster, as in 'a fatal mistake'. Its synonym is 'deadly'. 'Additional' means extra, 'easy' means not difficult, and 'jovial' means cheerful and friendly, so none of them is related in meaning to fatal.","o":["Additional","Easy","Deadly","Jovial"],"a":[2]},{"id":"c24s1-77","p":"c24s1","n":77,"s":"eng","t":"Voice & Narration","q":"Select the option that expresses the given sentence in active voice.\nLovely tunes are composed by Domnica.","w":"In the passive sentence 'Lovely tunes' is the subject that receives the action and 'Domnica' (after 'by') is the doer. The verb 'are composed' is simple present passive, so the active form keeps the simple present: 'Domnica composes lovely tunes.' Option 1 misplaces the adjective ('tunes lovely'), option 2 changes the tense to simple future (will compose), and option 4 changes it to simple past (composed).","o":["Domnica composes tunes lovely.","Domnica will compose lovely tunes.","Domnica composes lovely tunes.","Domnica composed lovely tunes."],"a":[2]},{"id":"c24s1-78","p":"c24s1","n":78,"s":"eng","t":"Vocabulary","q":"Select the option that expresses the opposite meaning of the underlined word.\nThe explosive used is of my own formulation, and I can \"vouch\" for its efficiency.","w":"To 'vouch for' something is to confirm or guarantee its truth or quality from one's own knowledge, as the speaker does for an explosive he made himself. The opposite is 'invalidate', which means to show something to be unsound or false, or to deprive it of legal force. 'Certify' and 'witness' (attest) are close to vouch in meaning, and 'maintain' (assert or keep up) is not an opposite either.","o":["Invalidate","Maintain","Witness","Certify"],"a":[0]},{"id":"c24s1-79","p":"c24s1","n":79,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"The following sentence has been divided into four segments. Identify the segment that contains an error.\nMr. Abhilash and his family / have received / no informations / about the incident.","w":"'Information' is an uncountable (mass) noun, so it has no plural form and cannot take -s. The segment 'no informations' should read 'no information' (or 'no pieces of information'). Other uncountable nouns that behave the same way include advice, furniture, luggage, equipment and news. 'Mr. Abhilash and his family' is a compound subject that correctly takes 'have received', and 'about the incident' is correct.","o":["about the incident.","Mr. Abhilash and his family","have received","no informations"],"a":[3]},{"id":"c24s1-80","p":"c24s1","n":80,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nToxic","w":"'Toxic' means poisonous, capable of causing serious harm or death, as in 'toxic fumes' or 'toxic waste'. Its closest synonym here is 'lethal', meaning sufficient to cause death. 'Licit' means lawful or permitted, 'laudatory' means expressing praise, and 'lanky' means tall, thin and awkward-looking. All four options begin with L, but only lethal shares the meaning of toxic.","o":["Lethal","Licit","Laudatory","Lanky"],"a":[0]},{"id":"c24s1-81","p":"c24s1","n":81,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the word which means the same as the group of words given.\nUnit of weight for precious stones","w":"A 'carat' is the unit of weight for precious stones and pearls; one metric carat equals 200 milligrams (0.2 gram), so a 2-carat diamond weighs 0.4 gram. The same word (spelt karat in American English) also measures the purity of gold, 24 carats being pure gold. 'Pure', 'accurate' and 'reliable' are adjectives describing quality, not units of weight.","o":["Pure","Accurate","Reliable","Carat"],"a":[3]},{"id":"c24s1-82","p":"c24s1","n":82,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the option that can be used as a one-word substitute for the underlined group of words.\nShe is \"proficient in speaking many languages\".","w":"A person who is proficient in speaking many languages is 'multilingual' (multi = many, lingua = tongue or language); such a person is also called a polyglot. 'Bilingual' means able to speak two languages only, and 'monolithic' means formed of a single large block of stone, or uniform and rigid, which has nothing to do with language. 'Heterolinguistic' is not the standard word for such a person.","o":["Heterolinguistic","Bilingual","Multilingual","Monolithic"],"a":[2]},{"id":"c24s1-83","p":"c24s1","n":83,"s":"eng","t":"Voice & Narration","q":"Select the option that expresses the given sentence in passive voice.\nIshika saw the tiger in the forest.","w":"In the active sentence 'Ishika' is the subject, 'saw' is simple past and 'the tiger' is the object. In the passive the object becomes the subject and the simple past becomes was/were + past participle: 'The tiger was seen by Ishika in the forest.' Option 1 lacks 'was' and uses 'saw' instead of the participle 'seen', option 2 changes both meaning and tense, and option 4 swaps 'the forest' and 'Ishika'.","o":["The tiger saw by Ishika in the forest.","The tiger sees Ishika in the forest.","The tiger was seen by Ishika in the forest.","The tiger was seen by the forest in Ishika."],"a":[2]},{"id":"c24s1-84","p":"c24s1","n":84,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the option that can be used as a one-word substitute for the given group of words.\nA person who likes to argue about anything","w":"'Contentious' describes a person who is fond of arguing and likely to cause disputes, or an issue that causes heated disagreement (Latin contentio, a struggle). So a person who likes to argue about anything is contentious, that is, quarrelsome or argumentative. 'Veracious' means truthful, 'reticent' means reserved and unwilling to speak, nearly the opposite, and a 'coward' is a person who lacks courage.","o":["Veracious","Reticent","Contentious","Coward"],"a":[2]},{"id":"c24s1-85","p":"c24s1","n":85,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Select the most appropriate option that can substitute the underlined segment in the given sentence.\n‘Spy Family’ is a graphic novel that is a narrative work in which the story is conveyed to the reader using \"uninterrupted art in a traditional\" comics format.","w":"A graphic novel tells its story through 'sequential art', a series of images (panels) arranged in order so that, read one after another, they narrate a story; the term was popularised by the cartoonist Will Eisner. The underlined 'uninterrupted art' does not express this. 'Sedimental' (a rare form of sedimentary) relates to sediment, 'longitudinal' means running lengthwise or over a long period, and 'existential' relates to existence.","o":["sedimental art in a traditional","longitudinal art in a traditional","existential art in a traditional","sequential art in a traditional"],"a":[3]},{"id":"c24s1-86","p":"c24s1","n":86,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"The following sentence has been split into four segments. Identify the segment that contains a grammatical error.\nMy brother performed / extremely good / in the class test / held yesterday.","w":"The verb 'performed' must be modified by an adverb, not an adjective. 'Good' is an adjective; the matching adverb is 'well'. So the segment 'extremely good' should read 'extremely well': 'My brother performed extremely well in the class test held yesterday.' 'Extremely' is correctly an adverb qualifying 'well'. The other segments, 'My brother performed', 'in the class test' and 'held yesterday', are correct.","o":["held yesterday","extremely good","in the class test","My brother performed"],"a":[1]},{"id":"c24s1-87","p":"c24s1","n":87,"s":"eng","t":"Spelling","q":"Select the INCORRECTLY spelt word.","w":"The incorrectly spelt word is 'Relevent'; the correct spelling is 'relevant' (r-e-l-e-v-a-n-t), ending in -ant, as in 'relevance'. The other words are spelt correctly: 'bureaucracy' (b-u-r-e-a-u-c-r-a-c-y), 'embarrass' (double r and double s) and 'connoisseur' (double n, double s and the ending -eur), which means an expert judge in matters of taste.","o":["Bureaucracy","Embarrass","Connoisseur","Relevent"],"a":[3]},{"id":"c24s1-88","p":"c24s1","n":88,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym to replace the underlined word in the given sentence.\nNo \"altruistic\" act is truly sincere.","w":"'Altruistic' means showing unselfish concern for the welfare of others (altruism is the opposite of selfishness). Its closest synonym among the options is 'philanthropic', which means seeking to promote the welfare of others, especially through generous help or donations. 'Phenomenal' means remarkable or extraordinary, 'phantasmal' means ghostly or illusory, and 'phonotypical' relates to phonotypy, a phonetic system of printing, so none of them fits.","o":["phenomenal","phonotypical","philanthropic","phantasmal"],"a":[2]},{"id":"c24s1-89","p":"c24s1","n":89,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nInnuendo","w":"An 'innuendo' is an indirect or subtle remark that hints at something, usually unpleasant or critical, without saying it openly, as in 'a campaign of rumour and innuendo'. Its synonym is 'insinuation', a sly suggestion of something bad. 'Crude' means rough or vulgar, 'prose' is ordinary written language as opposed to verse, and 'ragged' means torn or worn out, so none of them fits.","o":["Crude","Prose","Ragged","Insinuation"],"a":[3]},{"id":"c24s1-90","p":"c24s1","n":90,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Select the most appropriate option to fill in the blank.\nVinod had a ______ escape in the car accident.","w":"'A narrow escape' is a fixed expression (collocation) for a situation in which one only just avoids danger, injury or death; it is also called a close shave. So 'Vinod had a narrow escape in the car accident' means he was very nearly hurt but survived. 'Comfortable', 'full' and 'wide' do not collocate with 'escape' in this sense, and English never speaks of 'a wide escape'.","o":["comfortable","full","narrow","wide"],"a":[2]},{"id":"c24s1-91","p":"c24s1","n":91,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the option that can be used as a one-word substitute for the given phrase.\nA short interesting story about a real person or event","w":"An 'anecdote' is a short, interesting or amusing story about a real person or incident, often told to illustrate a point. A 'sketch' is a brief description or a short comic scene, a 'poem' is a piece of writing in verse, and a 'narrative' is any spoken or written account of connected events, real or imagined, without the sense of being short and about a real incident.","o":["Anecdote","Sketch","Poem","Narrative"],"a":[0]},{"id":"c24s1-92","p":"c24s1","n":92,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the word in bold.\nWe’d better watch our step and not give him any excuse to \"harass\" us further.","w":"The sheet prints the whole sentence in bold, so the tested word is not marked; it can only be 'harass', since no other word in the sentence has a synonym among the options. 'Harass' means to trouble, pressure or torment someone repeatedly, as in 'harassed by creditors'; its closest synonym here is 'intimidate', to frighten or threaten someone, especially to make them do or not do something. 'Betray' means to be disloyal, 'relish' means to enjoy greatly, and 'soothe' means to calm or comfort, almost the opposite of harass.","o":["betray","intimidate","relish","soothe"],"a":[1]},{"id":"c24s1-93","p":"c24s1","n":93,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the most appropriate meaning of the given idiom.\nTo have bigger fish to fry","w":"'To have bigger fish to fry' means to have more important matters to deal with than the trivial one at hand, as in 'I cannot worry about a parking ticket; I have bigger fish to fry.' It is used to dismiss something as not worth one's time. The idiom has nothing to do with taking calculated risks, fishing techniques or cooking; those options read the words literally.","o":["To have bigger things to take care of than the menial task at hand","To take calculated risks","To know different kinds of fishing techniques","To have an interest in cooking"],"a":[0]},{"id":"c24s1-94","p":"c24s1","n":94,"s":"eng","t":"Spelling","q":"In the following sentence, four words are underlined out of which one word is misspelt. Identify the INCORRECTLY spelt word.\nAfter the \"recapture\" (A) of Tololing and the adjacent features, \"evacting\" (B) the enemy from this \"well-fortified\" (C) position became a \"priority\".(D)","w":"Underlined word B, 'evacting', is misspelt; the intended word is 'evicting' (e-v-i-c-t-i-n-g), meaning forcing the enemy out of the position. The other underlined words are spelt correctly: 'recapture' (A), meaning capturing again, 'well-fortified' (C), meaning strongly defended, and 'priority' (D). Tololing is a ridge in the Dras sector of Kargil that the Indian Army recaptured in June 1999 during the Kargil War.","o":["B","D","C","A"],"a":[0]},{"id":"c24s1-95","p":"c24s1","n":95,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Select the most appropriate option to substitute the underlined segment in the given sentence.\nShe has been \"studying for two o’clock\".","w":"'Since' is used with a point of time (since two o'clock, since Monday, since 2020), while 'for' is used with a period of time (for two hours, for three days). 'Two o'clock' is a point of time, so the present perfect continuous 'has been studying' needs 'since': 'She has been studying since two o'clock.' Options 1 and 4 wrongly change 'studying' to 'study' after 'has been', and option 3 drops the preposition.","o":["study from two o’clock","studying since two o’clock","studying two o’clock","study for two o’clock"],"a":[1]},{"id":"c24s1-96","p":"c24s1","n":96,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nThere is a saying that coming events cast their shadows before. (1)______, it is not universally true. Something can happen within a second, and one may not (2)______ it. (3)______, some instances show that predictions based on certain signs have gone wrong. People generally say that natural calamities can be predicted by observing the animals. But what if animals are suffering from some disease and don’t show any signs before the event appears? They may fail to make peculiar sounds or actions about the events which are going to take place. (4)______, some unnatural calamities that are likely to appear may forecast their shadows by some bad omens. (5)______, we should not completely cancel out the possibilities that animals can sense certain unnatural happenings.\nSelect the most appropriate option to fill in blank number 1.","w":"The first sentence states the saying that coming events cast their shadows before, and the clause after the blank, 'it is not universally true', contradicts it. A contrast between two ideas is introduced by 'However'. 'Therefore' would introduce a result, while 'Furthermore' and 'Moreover' add a point in the same direction, so none of them can introduce a statement that limits or opposes the saying.","o":["Therefore","Furthermore","Moreover","However"],"a":[3]},{"id":"c24s1-97","p":"c24s1","n":97,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nThere is a saying that coming events cast their shadows before. (1)______, it is not universally true. Something can happen within a second, and one may not (2)______ it. (3)______, some instances show that predictions based on certain signs have gone wrong. People generally say that natural calamities can be predicted by observing the animals. But what if animals are suffering from some disease and don’t show any signs before the event appears? They may fail to make peculiar sounds or actions about the events which are going to take place. (4)______, some unnatural calamities that are likely to appear may forecast their shadows by some bad omens. (5)______, we should not completely cancel out the possibilities that animals can sense certain unnatural happenings.\nSelect the most appropriate option to fill in blank number 2.","w":"The writer argues that the saying is not always true because 'something can happen within a second', that is, without any warning, so one may not be able to 'foresee' it, meaning to know beforehand that it will happen. This fits the passage's theme of predicting events. 'Rescind' means to cancel a law or order, 'legalise' means to make lawful, and 'affect' means to influence, none of which suits an unexpected event.","o":["rescind","foresee","legalise","affect"],"a":[1]},{"id":"c24s1-98","p":"c24s1","n":98,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nThere is a saying that coming events cast their shadows before. (1)______, it is not universally true. Something can happen within a second, and one may not (2)______ it. (3)______, some instances show that predictions based on certain signs have gone wrong. People generally say that natural calamities can be predicted by observing the animals. But what if animals are suffering from some disease and don’t show any signs before the event appears? They may fail to make peculiar sounds or actions about the events which are going to take place. (4)______, some unnatural calamities that are likely to appear may forecast their shadows by some bad omens. (5)______, we should not completely cancel out the possibilities that animals can sense certain unnatural happenings.\nSelect the most appropriate option to fill in blank number 3.","w":"The sentence 'some instances show that predictions based on certain signs have gone wrong' adds a further reason in support of the same point, that the saying is not universally true. An additional supporting point is introduced by 'Moreover'. 'However' and 'Nevertheless' signal a contrast, which is not needed here, and 'Therefore' would wrongly present the sentence as a result of the one before it.","o":["Therefore","Moreover","However","Nevertheless"],"a":[1]},{"id":"c24s1-99","p":"c24s1","n":99,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nThere is a saying that coming events cast their shadows before. (1)______, it is not universally true. Something can happen within a second, and one may not (2)______ it. (3)______, some instances show that predictions based on certain signs have gone wrong. People generally say that natural calamities can be predicted by observing the animals. But what if animals are suffering from some disease and don’t show any signs before the event appears? They may fail to make peculiar sounds or actions about the events which are going to take place. (4)______, some unnatural calamities that are likely to appear may forecast their shadows by some bad omens. (5)______, we should not completely cancel out the possibilities that animals can sense certain unnatural happenings.\nSelect the most appropriate option to fill in blank number 4.","w":"After saying that sick animals may fail to give signs of coming events, the writer adds a separate idea: some unnatural calamities may forecast their shadows through bad omens. An additional point is introduced by 'Besides', meaning 'in addition'. 'Despite' is a preposition and must be followed by a noun or pronoun ('despite this'), 'Secondly' needs a 'firstly' before it, and 'Therefore' would wrongly show a result.","o":["Therefore","Secondly","Besides","Despite"],"a":[2]},{"id":"c24s1-100","p":"c24s1","n":100,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nThere is a saying that coming events cast their shadows before. (1)______, it is not universally true. Something can happen within a second, and one may not (2)______ it. (3)______, some instances show that predictions based on certain signs have gone wrong. People generally say that natural calamities can be predicted by observing the animals. But what if animals are suffering from some disease and don’t show any signs before the event appears? They may fail to make peculiar sounds or actions about the events which are going to take place. (4)______, some unnatural calamities that are likely to appear may forecast their shadows by some bad omens. (5)______, we should not completely cancel out the possibilities that animals can sense certain unnatural happenings.\nSelect the most appropriate option to fill in blank number 5.","w":"The last sentence draws a conclusion from what precedes it: since some calamities may announce themselves through omens, we should not completely rule out the possibility that animals sense unusual happenings. A conclusion or result is introduced by 'Therefore'. 'However' and 'Nevertheless' express contrast, and 'Moreover' merely adds another point instead of concluding the argument.","o":["Therefore","However","Nevertheless","Moreover"],"a":[0]},{"id":"c23s1-1","p":"c23s1","n":1,"s":"rea","t":"Non-verbal Reasoning","q":"Select the option figure which is embedded in the given figure. (Rotation is NOT allowed).","w":"Look for the option whose every line and arc can be traced in the given figure without turning it. Option 2 is the right-hand part of the figure cut along a slanting line: the top and right edges of the outer hexagon with its slanting lines, arcs of the big and the small circle, and between them part of the inner hexagon. Option 1 has the two arcs with no hexagon edge between them, option 4 shows three concentric arcs though the figure has only two circles, and option 3's lines around its arc match no part.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"उस विकल्प आकृति का चयन करें जो दी गई आकृति में सन्निहित है। (आकृति को घुमाने की अनुमति नहीं है)।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"घुमाए बिना उस विकल्प को खोजिए जिसकी हर रेखा और चाप दी गई आकृति में दिखाई दे। विकल्प 2 आकृति का दाहिना भाग है जिसे एक तिरछी रेखा से काटा गया है: बाहरी षट्भुज की ऊपरी और दाहिनी भुजाएँ उनकी तिरछी रेखाओं सहित, बड़े और छोटे वृत्त के चाप, और उनके बीच भीतरी षट्भुज का भाग। विकल्प 1 में दोनों चापों के बीच षट्भुज की भुजा नहीं है, विकल्प 4 में तीन संकेंद्री चाप हैं जबकि आकृति में केवल दो वृत्त हैं, और विकल्प 3 में चाप के आसपास की रेखाएँ आकृति के किसी भाग से मेल नहीं खातीं।"},{"id":"c23s1-2","p":"c23s1","n":2,"s":"rea","t":"Arrangement & Puzzles","q":"Select the option that represents the correct order of the given words as they would appear in an English dictionary.\n1. Warriors\n2. Warehouse\n3. Warcraft\n4. Warranty\n5. Wardrobe\n6. Wardenship","w":"All six words begin with \"War\", so compare the fourth letter: c (Warcraft) comes before d (Wardenship, Wardrobe), then e (Warehouse), then r (Warranty, Warriors). Wardenship comes before Wardrobe because e comes before r in the fifth place, and Warranty comes before Warriors because a comes before i. The order is Warcraft, Wardenship, Wardrobe, Warehouse, Warranty, Warriors = 3, 6, 5, 2, 4, 1. Option 1 wrongly puts Warriors before Warranty.","o":["3, 6, 5, 2, 1, 4","3, 5, 6, 2, 1, 4","3, 5, 6, 2, 4, 1","3, 6, 5, 2, 4, 1"],"a":[3],"qt":"उस विकल्प का चयन कीजिए, जो दिए गए शब्दों के ऐसे सही क्रम का निरूपण करता है, जैसे वे अँग्रेजी शब्दकोश में दिखेंगे।\n1. Warriors\n2. Warehouse\n3. Warcraft\n4. Warranty\n5. Wardrobe\n6. Wardenship","ot":["3, 6, 5, 2, 1, 4","3, 5, 6, 2, 1, 4","3, 5, 6, 2, 4, 1","3, 6, 5, 2, 4, 1"],"wt":"सभी छह शब्द \"War\" से शुरू होते हैं, इसलिए चौथा अक्षर देखिए: c (Warcraft) सबसे पहले, फिर d (Wardenship, Wardrobe), फिर e (Warehouse), फिर r (Warranty, Warriors)। पाँचवें स्थान पर e, r से पहले आता है, इसलिए Wardenship, Wardrobe से पहले है; और a, i से पहले आता है, इसलिए Warranty, Warriors से पहले है। सही क्रम: Warcraft, Wardenship, Wardrobe, Warehouse, Warranty, Warriors = 3, 6, 5, 2, 4, 1। विकल्प 1 में Warriors गलती से Warranty से पहले रखा गया है।"},{"id":"c23s1-3","p":"c23s1","n":3,"s":"rea","t":"Syllogism & Statements","q":"Three statements are given, followed by four conclusions numbered I, II, III and IV. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements.\nStatements:\nSome desks are trays.\nSome trays are plates.\nSome plates are desks.\nConclusions:\nI. All desks are plates.\nII. All plates are desks.\nIII. Some plates are trays.\nIV. All trays are desks.","w":"A \"some\" statement can be reversed: \"Some trays are plates\" gives \"Some plates are trays\", so conclusion III follows. All three statements are particular (\"some\"), and particular statements can never prove a universal (\"all\") conclusion. So \"All desks are plates\", \"All plates are desks\" and \"All trays are desks\" are only possibilities, not certainties. Hence only conclusion III follows.","o":["Only conclusion III follows","Only conclusion IV follows","Only conclusion II follows","Only conclusion I follows"],"a":[0],"qt":"तीन कथन दिए गए हैं, जिसके बाद चार निष्कर्ष I, II, III और IV दिए गए हैं। कथनों को सत्य मानते हुए, भले ही वे सामान्य रूप से ज्ञात तथ्यों से भिन्न प्रतीत होते हों, निर्णय लीजिए कि कौन-से निष्कर्ष कथनों का तार्किक रूप से अनुसरण करते हैं।\nकथन:\nकुछ डेस्क ट्रे हैं।\nकुछ ट्रे प्लेट हैं।\nकुछ प्लेट डेस्क हैं।\nनिष्कर्ष:\nI. सभी डेस्क प्लेट हैं।\nII. सभी प्लेट डेस्क हैं।\nIII. कुछ प्लेट ट्रे हैं।\nIV. सभी ट्रे डेस्क हैं।","ot":["केवल निष्कर्ष III अनुसरण करता है।","केवल निष्कर्ष IV अनुसरण करता है।","केवल निष्कर्ष II अनुसरण करता है।","केवल निष्कर्ष I अनुसरण करता है।"],"wt":"'कुछ' वाले कथन को उलटा जा सकता है: \"कुछ ट्रे प्लेट हैं\" से \"कुछ प्लेट ट्रे हैं\" प्राप्त होता है, इसलिए निष्कर्ष III अनुसरण करता है। तीनों कथन विशेष ('कुछ' वाले) कथन हैं, और विशेष कथनों से कभी कोई सार्वभौमिक ('सभी' वाला) निष्कर्ष सिद्ध नहीं होता। अतः \"सभी डेस्क प्लेट हैं\", \"सभी प्लेट डेस्क हैं\" और \"सभी ट्रे डेस्क हैं\" केवल संभावनाएँ हैं, निश्चित नहीं। इसलिए केवल निष्कर्ष III अनुसरण करता है।"},{"id":"c23s1-4","p":"c23s1","n":4,"s":"rea","t":"Analogy & Classification","q":"Select the option that is related to the third word in the same way as the second word is related to the first word.\n(The words must be considered as meaningful English words and must not be related to each other based on the number of letters/number of consonants/vowels in the word.)\nSkin : Touch :: Nose : ?","w":"The skin is the sense organ through which we feel touch. In the same way, the nose is the sense organ through which we smell, so Nose : Smell. Taste is the sense of the tongue, not the nose. A nose ring is only an ornament worn on the nose, and sweat is given out by the skin, so neither keeps the organ-and-sense relation of the first pair.","o":["Smell","Taste","Nose ring","Sweat"],"a":[0],"qt":"उस विकल्प का चयन करें जो तीसरे शब्द से उसी प्रकार संबंधित है जिस प्रकार दूसरा शब्द पहले शब्द से संबंधित है। (शब्दों को अर्थपूर्ण अंग्रेजी/हिन्दी शब्दों के रूप में माना जाना चाहिए और इन्हें शब्द में अक्षरों की संख्या/व्यंजनों की संख्या/स्वरों की संख्या के आधार पर एक-दूसरे से संबद्ध नहीं किया जाना चाहिए।)\nत्वचा : स्पर्श :: नाक : ?","ot":["गंध","स्वाद","नथ","पसीना"],"wt":"त्वचा वह ज्ञानेंद्रिय है जिससे हम स्पर्श का अनुभव करते हैं। इसी प्रकार नाक वह ज्ञानेंद्रिय है जिससे हम गंध का अनुभव करते हैं, इसलिए नाक : गंध। स्वाद जीभ की इंद्रिय है, नाक की नहीं। नथ नाक में पहना जाने वाला आभूषण मात्र है और पसीना त्वचा से निकलता है, इसलिए इनमें से कोई भी पहले युग्म जैसा 'अंग और उसकी इंद्रिय' वाला संबंध नहीं रखता।"},{"id":"c23s1-5","p":"c23s1","n":5,"s":"rea","t":"Blood Relations & Directions","q":"Ganesh was taking a walk with his mother’s brother’s father’s granddaughter. Who was he walking with?","w":"Ganesh's mother's brother's father is his mother's father, that is, Ganesh's maternal grandfather. A granddaughter of this grandfather is a daughter of one of his children, for example of Ganesh's maternal uncle, which makes her Ganesh's cousin. (She could also be Ganesh's own sister, but Sister is not an option.) Daughter and Granddaughter belong to younger generations than Ganesh, and Mother is the grandfather's daughter, not his granddaughter, so Cousin is the answer.","o":["Daughter","Mother","Cousin","Granddaughter"],"a":[2],"qt":"गणेश अपनी माता के भाई के पिता की पोती के साथ टहल रहा था। वह किसके साथ टहल रहा था?","ot":["पुत्री","माता","चचेरी/ममेरी/फुफेरी बहन","पोती/नतिनी"],"wt":"गणेश की माता के भाई के पिता उसकी माता के पिता, अर्थात् गणेश के नाना हैं। नाना की पोती उनकी किसी संतान की पुत्री है, जैसे गणेश के मामा की पुत्री, जो गणेश की ममेरी बहन है। (अंग्रेज़ी के 'granddaughter' में नातिनी भी आती है, जो गणेश की सगी बहन हो सकती है, पर 'बहन' कोई विकल्प नहीं है।) पुत्री और पोती/नतिनी गणेश से नीचे की पीढ़ियाँ हैं, और माता नाना की पुत्री है, पोती नहीं; इसलिए उत्तर चचेरी/ममेरी/फुफेरी बहन है।"},{"id":"c23s1-6","p":"c23s1","n":6,"s":"rea","t":"Non-verbal Reasoning","q":"Select the correct mirror image of the given figure when the mirror is placed at MN as shown below.","w":"The mirror MN is horizontal and lies below the figure, so the image is a top-to-bottom reflection: the characters keep their left-to-right order T, e, 2, 9, E, K, P, and each one is turned upside down without being reversed sideways. Option 4 shows exactly this. Option 3 is the image in a vertical mirror (order reversed), option 2 reverses K sideways, and option 1 turns the 2 half a turn instead of flipping it.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[3],"qt":"दी गई आकृति के सही दर्पण के प्रतिबिंब का चयन करें, जब दर्पण को MN पर रखा जाए, जैसा कि नीचे दर्शाया गया है।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"दर्पण MN क्षैतिज है और आकृति के नीचे रखा है, इसलिए प्रतिबिंब ऊपर से नीचे पलटता है: अक्षरों का बाएँ से दाएँ क्रम T, e, 2, 9, E, K, P वही रहता है, और हर अक्षर बाएँ-दाएँ उलटे बिना केवल ऊपर-नीचे उलट जाता है। विकल्प 4 ठीक यही दर्शाता है। विकल्प 3 ऊर्ध्वाधर दर्पण का प्रतिबिंब है (क्रम उलटा), विकल्प 2 में K बाएँ-दाएँ उलटा है, और विकल्प 1 में 2 को पलटने के बजाय आधा चक्कर घुमा दिया गया है।"},{"id":"c23s1-7","p":"c23s1","n":7,"s":"rea","t":"Series","q":"Which of the following letter-clusters will replace the question mark (?) in the given series?\nUV, OY, IB, EE, ?","w":"First letters: U, O, I, E are the vowels taken in reverse order (U, O, I, E, A), so the next first letter is A. Second letters move 3 places forward each time: V + 3 = Y, Y + 3 = B (counting on past Z), B + 3 = E, so the next is E + 3 = H. The missing cluster is AH. BH and BI have the wrong first letter, and ZK fits neither pattern.","o":["ZK","AH","BI","BH"],"a":[1],"qt":"निम्नलिखित में से कौन सा अक्षर-समूह दी गई शृंखला में प्रश्नचिह्न (?) के स्थान पर आएगा?\nUV, OY, IB, EE, ?","ot":["ZK","AH","BI","BH"],"wt":"पहले अक्षर: U, O, I, E स्वर उलटे क्रम में हैं (U, O, I, E, A), इसलिए अगला पहला अक्षर A है। दूसरे अक्षर हर बार 3 स्थान आगे बढ़ते हैं: V + 3 = Y, Y + 3 = B (Z के बाद फिर A से गिनकर), B + 3 = E, इसलिए अगला E + 3 = H है। लुप्त अक्षर-समूह AH है। BH और BI का पहला अक्षर गलत है, और ZK किसी भी पैटर्न में नहीं बैठता।"},{"id":"c23s1-8","p":"c23s1","n":8,"s":"rea","t":"Analogy & Classification","q":"The second number in the given number-pairs is obtained by performing certain mathematical operation(s) on the first number. The same operation(s) is/are followed in all the number-pairs except one. Find that odd number-pair.","w":"The rule is: second number = first number ÷ 2 + 1. Check: 20 ÷ 2 + 1 = 11, 6 ÷ 2 + 1 = 4 and 12 ÷ 2 + 1 = 7. For 15, the rule gives 15 ÷ 2 + 1 = 8.5, not 9, so the pair 15 : 9 does not follow the pattern. It is also the only pair whose first number is odd.","o":["20 : 11","6 : 4","15 : 9","12 : 7"],"a":[2],"qt":"दिए गए संख्या-युग्मों में दूसरी संख्या पहली संख्या पर कुछ गणितीय संक्रिया(एं) करके प्राप्त की जाती है। एक संख्या-युग्म को छोड़कर शेष सभी संख्या-युग्मों में समान संक्रिया(ओं) का पालन किया जाता है। विषम संख्या-युग्म ज्ञात करें।","ot":["20 : 11","6 : 4","15 : 9","12 : 7"],"wt":"नियम है: दूसरी संख्या = पहली संख्या ÷ 2 + 1। जाँच: 20 ÷ 2 + 1 = 11, 6 ÷ 2 + 1 = 4 और 12 ÷ 2 + 1 = 7। 15 के लिए यह नियम 15 ÷ 2 + 1 = 8.5 देता है, 9 नहीं, इसलिए युग्म 15 : 9 पैटर्न का पालन नहीं करता। यही एकमात्र युग्म है जिसकी पहली संख्या विषम है।"},{"id":"c23s1-9","p":"c23s1","n":9,"s":"rea","t":"Non-verbal Reasoning","q":"Select the figure that will replace the question mark (?) in the following figure series.","w":"Two moves alternate. Figure 1 to 2 (and 3 to 4): top-left → top-right → centre → bottom-left → middle-left → top-left, while middle-right and bottom-right swap. Figure 2 to 3: top-left → bottom-left → middle-left → top-left and top-right → middle-right → bottom-right → top-right, and the centre symbol is replaced by a new one (the circle became a star). This second move on figure 4 gives = top-left, ▽ top-right, star middle-left, □ middle-right, 3 bottom-left, 9 bottom-right and a new centre symbol in place of D: option 3 (C). Option 4 wrongly keeps D.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[2],"qt":"उस आकृति का चयन कीजिए, जो नीचे दी गई आकृति शृंखला में प्रश्न-चिह्न (?) को प्रतिस्थापित करेगी।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"दो चालें बारी-बारी से होती हैं। आकृति 1 से 2 (और 3 से 4): ऊपर-बाएँ → ऊपर-दाएँ → केंद्र → नीचे-बाएँ → मध्य-बाएँ → ऊपर-बाएँ, तथा मध्य-दाएँ और नीचे-दाएँ आपस में बदलते हैं। आकृति 2 से 3: ऊपर-बाएँ → नीचे-बाएँ → मध्य-बाएँ → ऊपर-बाएँ और ऊपर-दाएँ → मध्य-दाएँ → नीचे-दाएँ → ऊपर-दाएँ, तथा केंद्र का चिह्न नए चिह्न से बदल जाता है (वृत्त की जगह तारा)। आकृति 4 पर यही दूसरी चाल लगाने से = ऊपर-बाएँ, ▽ ऊपर-दाएँ, तारा मध्य-बाएँ, □ मध्य-दाएँ, 3 नीचे-बाएँ, 9 नीचे-दाएँ और केंद्र में D की जगह नया चिह्न आता है: विकल्प 3 (C)। विकल्प 4 गलती से D को बनाए रखता है।"},{"id":"c23s1-10","p":"c23s1","n":10,"s":"rea","t":"Non-verbal Reasoning","q":"Three different positions of the same dice are shown. Find the number on the face opposite the face showing ‘1’.","w":"The face showing 1 is on top in all three positions, and the side faces seen next to it are 2 and 6, then 6 and 5, then 5 and 4. So 1 is adjacent to 2, 4, 5 and 6. A face can never be seen next to its opposite face, so the only number left, 3, must be on the face opposite 1.","img":"data:image/png;base64,","o":["6","2","3","4"],"a":[2],"qt":"एक ही पासे की तीन विभिन्न स्थितियाँ प्रदर्शित हैं। ‘1’ प्रदर्शित करने वाले फलक के विपरीत फलक पर कौन-सी संख्या है?","ot":["6","2","3","4"],"wt":"तीनों स्थितियों में 1 ऊपर वाले फलक पर है, और उसके साथ दिखने वाले पार्श्व फलक क्रमशः 2 और 6, फिर 6 और 5, फिर 5 और 4 हैं। अतः 1 के आसन्न फलक 2, 4, 5 और 6 हैं। कोई फलक अपने विपरीत फलक के साथ कभी नहीं दिख सकता, इसलिए बची हुई संख्या 3 ही 1 के विपरीत फलक पर होगी।"},{"id":"c23s1-11","p":"c23s1","n":11,"s":"rea","t":"Analogy & Classification","q":"Select the set in which the numbers are related in the same way as are the numbers of the following sets.\n(55, 11, 25)\n(64,16, 16)\n(NOTE : Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding /subtracting /multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is NOT allowed)","w":"In each set, divide the first number by the second and square the result to get the third: (55 ÷ 11)² = 5² = 25 and (64 ÷ 16)² = 4² = 16. For the options, 33 ÷ 11 = 3 and 3² = 9, so (33, 11, 9) follows the same rule. 22 is 33 − 11, 3 is only the quotient without squaring, and 10 fits no rule.","o":["(33, 11, 9)","(33, 11, 22)","(33, 11, 3)","(33, 11, 10)"],"a":[0],"qt":"उस समुच्चय का चयन करें जिसमें संख्याएँ उसी प्रकार संबंधित हैं जिस प्रकार निम्नलिखित समुच्चयों की संख्याएँ संबंधित हैं।\n(55, 11, 25)\n(64,16, 16)\n(ध्यान दें: गणितीय संक्रियाएं संख्याओं को उनके घटक अंकों में विभाजित किए बिना पूर्ण संख्याओं पर की जानी चाहिए। उदाहरण के लिए 13 के मामले में - 13 पर विभिन्न गणितीय संक्रियाएं, जैसे कि 13 में जोड़ना / घटाना / गुणा करना आदि की जा सकती हैं। लेकिन 13 को अंक 1 और 3 में विभाजित करने और फिर 1 और 3 पर गणितीय संक्रियाएं करने की अनुमति नहीं है।)","ot":["(33, 11, 9)","(33, 11, 22)","(33, 11, 3)","(33, 11, 10)"],"wt":"प्रत्येक समुच्चय में पहली संख्या को दूसरी से भाग देकर परिणाम का वर्ग करने पर तीसरी संख्या मिलती है: (55 ÷ 11)² = 5² = 25 और (64 ÷ 16)² = 4² = 16। विकल्पों में 33 ÷ 11 = 3 और 3² = 9, इसलिए (33, 11, 9) इसी नियम का पालन करता है। 22 केवल 33 − 11 है, 3 बिना वर्ग किया भागफल है, और 10 किसी नियम में नहीं बैठता।"},{"id":"c23s1-12","p":"c23s1","n":12,"s":"rea","t":"Analogy & Classification","q":"Select the option that is related to the sixth letter-cluster in the same way as the first letter-cluster is related to the second letter-cluster and the third letter-cluster is related to the fourth letter-cluster.\nHMD : KOE : : BNQ : EPR :: ? : FLV","w":"From the first cluster to the second, the letters move +3, +2, +1: H + 3 = K, M + 2 = O, D + 1 = E; likewise B + 3 = E, N + 2 = P, Q + 1 = R. So the fifth cluster becomes FLV in the same way. Working back from FLV: F − 3 = C, L − 2 = J, V − 1 = U, giving CJU. UJC is CJU reversed, and SJE and EJS do not fit.","o":["SJE","UJC","EJS","CJU"],"a":[3],"qt":"उस विकल्प का चयन कीजिए जो छठे अक्षर-समूह से उसी प्रकार संबंधित है जिस प्रकार पहला अक्षर-समूह दूसरे अक्षर-समूह से संबंधित है और तीसरा अक्षर-समूह चौथे अक्षर-समूह से संबंधित है।\nHMD : KOE : : BNQ : EPR :: ? : FLV","ot":["SJE","UJC","EJS","CJU"],"wt":"पहले अक्षर-समूह से दूसरे में अक्षर क्रमशः +3, +2, +1 आगे बढ़ते हैं: H + 3 = K, M + 2 = O, D + 1 = E; इसी प्रकार B + 3 = E, N + 2 = P, Q + 1 = R। अतः पाँचवाँ अक्षर-समूह इसी तरह FLV बनता है। FLV से पीछे की ओर चलने पर: F − 3 = C, L − 2 = J, V − 1 = U, यानी CJU। UJC, CJU का उलटा है, और SJE तथा EJS नियम में नहीं बैठते।"},{"id":"c23s1-13","p":"c23s1","n":13,"s":"rea","t":"Non-verbal Reasoning","q":"Select the figure from the options that can replace the question mark (?) and complete the given pattern.","w":"Each figure has four corner places and two inner places on the diagonal from top-left to bottom-right. Two moves alternate. From figure 1 to 2 (and 3 to 4) the corner symbols move one corner anticlockwise and the two inner symbols swap. From figure 2 to 3, top-left swaps with the upper inner place, bottom-right with the lower inner place, and top-right with bottom-left. Applying this to figure 4 gives ↑ top-left, △ top-right, D upper inner, Z lower inner, E bottom-left and S bottom-right, which is option 4.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[3],"qt":"निम्नलिखित विकल्पों में से उस आकृति का चयन कीजिए जो प्रश्नवाचक चिह्न (?) को प्रतिस्थापित करते हुए दिए गए पैटर्न को पूरा करेगी।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"प्रत्येक आकृति में चार कोनों के स्थान और ऊपर-बाएँ से नीचे-दाएँ वाले विकर्ण पर दो भीतरी स्थान हैं। दो चालें बारी-बारी से होती हैं। आकृति 1 से 2 (और 3 से 4) में कोनों के चिह्न एक कोना वामावर्त खिसकते हैं और दोनों भीतरी चिह्न आपस में बदलते हैं। आकृति 2 से 3 में ऊपर-बाएँ और ऊपरी भीतरी, नीचे-दाएँ और निचला भीतरी, तथा ऊपर-दाएँ और नीचे-बाएँ आपस में बदलते हैं। आकृति 4 पर यह लगाने से ↑ ऊपर-बाएँ, △ ऊपर-दाएँ, D ऊपरी भीतरी, Z निचला भीतरी, E नीचे-बाएँ और S नीचे-दाएँ आते हैं, जो विकल्प 4 है।"},{"id":"c23s1-14","p":"c23s1","n":14,"s":"rea","t":"Miscellaneous Reasoning","q":"Select the Venn diagram that best illustrates the relationship between the following classes.\nTicket, Aeroplane, Rail","w":"Some tickets are aeroplane tickets and some are rail tickets, so the Ticket circle overlaps both the Aeroplane circle and the Rail circle. Nothing is both an aeroplane and a rail, so those two circles do not overlap each other. Three circles in a chain with Ticket in the middle, option 1, show this. Option 4 would wrongly give aeroplane and rail a common part, and option 2 leaves one class unconnected to tickets.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[0],"qt":"उस वेन आरेख का चयन कीजिए जो निम्नलिखित वर्गों के बीच संबंध को सर्वोत्तम रूप से दर्शाता है।\nटिकट, हवाई जहाज, रेल","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"कुछ टिकट हवाई जहाज के टिकट होते हैं और कुछ रेल के, इसलिए टिकट का वृत्त हवाई जहाज और रेल दोनों के वृत्तों को काटता है। कोई वस्तु एक साथ हवाई जहाज और रेल नहीं हो सकती, इसलिए ये दोनों वृत्त एक-दूसरे को नहीं काटते। तीन वृत्तों की कड़ी, जिसके बीच में टिकट है, अर्थात् विकल्प 1, यही दर्शाती है। विकल्प 4 हवाई जहाज और रेल को गलत रूप से उभयनिष्ठ भाग देगा, और विकल्प 2 एक वर्ग को टिकट से अलग छोड़ देता है।"},{"id":"c23s1-15","p":"c23s1","n":15,"s":"rea","t":"Analogy & Classification","q":"Four letter-clusters have been given, out of which three are alike in some manner and one is different. Select the odd letter-cluster.","w":"Use letter positions. BFJN = 2, 6, 10, 14; DHLP = 4, 8, 12, 16; JNRV = 10, 14, 18, 22. In each of these the letters go up by 4 every time (+4, +4, +4). HJKP = 8, 10, 11, 16 goes up by 2, 1 and 5, so it does not follow the pattern and is the odd letter-cluster.","o":["BFJN","DHLP","HJKP","JNRV"],"a":[2],"qt":"चार अक्षर-समूह दिए गए हैं, जिनमें से तीन अक्षर-समूह किसी न किसी रूप में एक जैसे हैं और एक भिन्न है। उस भिन्न अक्षर-समूह का चयन कीजिए।","ot":["BFJN","DHLP","HJKP","JNRV"],"wt":"अक्षरों के स्थानीय मान लीजिए। BFJN = 2, 6, 10, 14; DHLP = 4, 8, 12, 16; JNRV = 10, 14, 18, 22। इन तीनों में अक्षर हर बार 4 बढ़ते हैं (+4, +4, +4)। HJKP = 8, 10, 11, 16 में वृद्धि 2, 1 और 5 है, इसलिए यह पैटर्न का पालन नहीं करता और यही भिन्न अक्षर-समूह है।"},{"id":"c23s1-16","p":"c23s1","n":16,"s":"rea","t":"Analogy & Classification","q":"Select the option that is related to the fifth number in the same way as the second number is related to the first number and the fourth number is related to the third number.\n5 : 45::3 : 3::6 : ?","w":"The second number = first number × (first number − 2)². Check: 5 × (5 − 2)² = 5 × 9 = 45 and 3 × (3 − 2)² = 3 × 1 = 3. So for 6: 6 × (6 − 2)² = 6 × 16 = 96. Simple rules such as multiplying by a fixed number fail, since 5 gives 45 (× 9) while 3 gives 3 (× 1); 90, 106 and 110 do not fit the rule.","o":["90","106","110","96"],"a":[3],"qt":"दिए गए विकल्पों में उस विकल्प का चयन कीजिए जो पांचवीं संख्या से उसी प्रकार संबंधित है जिस प्रकार दूसरी संख्या पहली संख्या से संबंधित है और चौथी संख्या तीसरी संख्या से संबंधित है।\n5 : 45::3 : 3::6 : ?","ot":["90","106","110","96"],"wt":"दूसरी संख्या = पहली संख्या × (पहली संख्या − 2)²। जाँच: 5 × (5 − 2)² = 5 × 9 = 45 और 3 × (3 − 2)² = 3 × 1 = 3। अतः 6 के लिए: 6 × (6 − 2)² = 6 × 16 = 96। किसी निश्चित संख्या से गुणा करने जैसे सरल नियम नहीं चलते, क्योंकि 5 से 45 (× 9) मिलता है जबकि 3 से 3 (× 1); 90, 106 और 110 इस नियम में नहीं बैठते।"},{"id":"c23s1-17","p":"c23s1","n":17,"s":"rea","t":"Series","q":"Which of the following numbers will replace the question mark (?) in the given series?\n8, 15, 26, ? , 56, 75","w":"The differences between terms are consecutive prime numbers: 15 − 8 = 7 and 26 − 15 = 11, so the next differences are 13, 17 and 19. Then 26 + 13 = 39, 39 + 17 = 56 and 56 + 19 = 75, which matches the last two terms. With 41 the differences would be 15 and 15, which breaks the pattern.","o":["39","41","35","43"],"a":[0],"qt":"निम्नलिखित में से कौन-सी संख्या दी गई श्रृंखला में प्रश्न चिह्न (?) के स्थान पर आएगी?\n8, 15, 26, ? , 56, 75","ot":["39","41","35","43"],"wt":"पदों के बीच के अंतर क्रमागत अभाज्य संख्याएँ हैं: 15 − 8 = 7 और 26 − 15 = 11, इसलिए अगले अंतर 13, 17 और 19 होंगे। तब 26 + 13 = 39, 39 + 17 = 56 और 56 + 19 = 75, जो अंतिम दो पदों से मेल खाता है। 41 लेने पर अंतर 15 और 15 होंगे, जिससे पैटर्न टूट जाता है।"},{"id":"c23s1-18","p":"c23s1","n":18,"s":"rea","t":"Analogy & Classification","q":"Select the option that is related to the third term in the same way as the second term is related to the first term and the sixth term is related to the fifth term.\n7183 : 3850 :: 6957 : ? :: 8972 : 5639","w":"In each pair the second number is 3333 less than the first: 7183 − 3850 = 3333 and 8972 − 5639 = 3333. So the missing term is 6957 − 3333 = 3624. The other options use the same digits in a different order: 6957 − 3426 = 3531, 6957 − 3246 = 3711 and 6957 − 3642 = 3315, none of which is 3333.","o":["3426","3624","3246","3642"],"a":[1],"qt":"उस विकल्प का चयन कीजिए, जो तीसरे पद से उसी प्रकार संबंधित है, जिस प्रकार दूसरा पद पहले पद से और छठा पद पाँचवें पद से संबंधित है।\n7183 : 3850 :: 6957 : ? :: 8972 : 5639","ot":["3426","3624","3246","3642"],"wt":"प्रत्येक युग्म में दूसरी संख्या पहली से 3333 कम है: 7183 − 3850 = 3333 और 8972 − 5639 = 3333। अतः लुप्त पद 6957 − 3333 = 3624 है। अन्य विकल्पों में वही अंक दूसरे क्रम में हैं: 6957 − 3426 = 3531, 6957 − 3246 = 3711 और 6957 − 3642 = 3315, इनमें से कोई भी 3333 नहीं है।"},{"id":"c23s1-19","p":"c23s1","n":19,"s":"rea","t":"Non-verbal Reasoning","q":"Three different positions of the same dice are shown. Find the number on the face opposite the face showing ‘4’.","w":"6 is seen next to 4 and 5 (figure 1), 3 and 2 (figure 2), and 5 and 3 (figure 3), so 6 touches 2, 3, 4 and 5 and is opposite 1. 5 is seen next to 4, 6 and 3, so its opposite must be 1 or 2; 1 is already opposite 6, so 5 is opposite 2. The remaining pair is 3 and 4, so 3 is on the face opposite 4.","img":"data:image/png;base64,","o":["5","6","2","3"],"a":[3],"qt":"एक ही पासे की तीन विभिन्न स्थितियाँ प्रदर्शित हैं। ‘4’ प्रदर्शित करने वाले फलक के विपरीत फलक पर कौन-सी संख्या है?","ot":["5","6","2","3"],"wt":"6 के साथ 4 और 5 (चित्र 1), 3 और 2 (चित्र 2), तथा 5 और 3 (चित्र 3) दिखते हैं, इसलिए 6 के आसन्न 2, 3, 4 और 5 हैं और 6 के विपरीत 1 है। 5 के साथ 4, 6 और 3 दिखते हैं, इसलिए उसके विपरीत 1 या 2 होगा; 1 पहले से 6 के विपरीत है, अतः 5 के विपरीत 2 है। बची हुई जोड़ी 3 और 4 है, इसलिए 4 के विपरीत फलक पर 3 है।"},{"id":"c23s1-20","p":"c23s1","n":20,"s":"rea","t":"Analogy & Classification","q":"Select the option that is related to the fifth number in the same way as the second number is related to the first number and the fourth number is related to the third number.\n625 : 5 :: 2560 : 8 :: 5000 : ?","w":"The first number = 5 × (second number)³. Check: 5 × 5³ = 5 × 125 = 625 and 5 × 8³ = 5 × 512 = 2560. For 5000: 5000 ÷ 5 = 1000 = 10³, so the missing number is 10. The other options fail: 5 × 9³ = 3645, 5 × 12³ = 8640 and 5 × 15³ = 16875.","o":["9","12","10","15"],"a":[2],"qt":"उस विकल्प का चयन कीजिए जो पाँचवीं संख्या से उसी प्रकार संबंधित है जिस प्रकार दूसरी संख्या पहली संख्या से संबंधित है और चौथी संख्या तीसरी संख्या से संबंधित है।\n625 : 5 :: 2560 : 8 :: 5000 : ?","ot":["9","12","10","15"],"wt":"पहली संख्या = 5 × (दूसरी संख्या)³। जाँच: 5 × 5³ = 5 × 125 = 625 और 5 × 8³ = 5 × 512 = 2560। 5000 के लिए: 5000 ÷ 5 = 1000 = 10³, इसलिए लुप्त संख्या 10 है। अन्य विकल्प सही नहीं बैठते: 5 × 9³ = 3645, 5 × 12³ = 8640 और 5 × 15³ = 16875।"},{"id":"c23s1-21","p":"c23s1","n":21,"s":"rea","t":"Coding-Decoding","q":"In a certain code language, ‘ASK’ is written as ‘62’ and ‘BYE’ is written as ‘64’. How will ‘CRY’ be written in that language?","w":"The code is twice the sum of the letter positions. ASK: A (1) + S (19) + K (11) = 31, and 31 × 2 = 62. BYE: B (2) + Y (25) + E (5) = 32, and 32 × 2 = 64. CRY: C (3) + R (18) + Y (25) = 46, and 46 × 2 = 92. So CRY is written as 92.","o":["68","72","86","92"],"a":[3],"qt":"एक निश्चित कूट भाषा में, 'ASK' को '62' और 'BYE' को '64' के रूप में लिखा जाता है। उसी भाषा में 'CRY' को कैसे लिखा जाएगा?","ot":["68","72","86","92"],"wt":"कूट अक्षरों के स्थानीय मानों के योग का दोगुना है। ASK: A (1) + S (19) + K (11) = 31, और 31 × 2 = 62। BYE: B (2) + Y (25) + E (5) = 32, और 32 × 2 = 64। CRY: C (3) + R (18) + Y (25) = 46, और 46 × 2 = 92। अतः CRY को 92 लिखा जाएगा।"},{"id":"c23s1-22","p":"c23s1","n":22,"s":"rea","t":"Mathematical Operations","q":"Select the correct combination of mathematical signs that can sequentially replace the * signs and balance the given equation.\n256 * 4 * 9 * 3 * 14 = 51","w":"Put each set of signs in order and solve using BODMAS. Option 4: 256 ÷ 4 − 9 × 3 + 14 = 64 − 27 + 14 = 51, which balances the equation. Option 2 gives 256 ÷ 4 × 9 − 3 + 14 = 576 − 3 + 14 = 587. Options 1 and 3 begin with 256 × 4 = 1024 and cannot come down to 51 (they give about 1032.8 and 102.8).","o":["× + − ÷","÷ × − +","× ÷ + −","÷ − × +"],"a":[3],"qt":"गणितीय चिह्नों के उस सही संयोजन का चयन कीजिए जो क्रमिक रूप से * चिह्नों को प्रतिस्थापित कर सकता है और दिए गए समीकरण को संतुलित कर सकता है।\n256 * 4 * 9 * 3 * 14 = 51","ot":["× + − ÷","÷ × − +","× ÷ + −","÷ − × +"],"wt":"चिह्नों के प्रत्येक समूह को क्रम से रखकर BODMAS के अनुसार हल कीजिए। विकल्प 4: 256 ÷ 4 − 9 × 3 + 14 = 64 − 27 + 14 = 51, जिससे समीकरण संतुलित हो जाता है। विकल्प 2 से 256 ÷ 4 × 9 − 3 + 14 = 576 − 3 + 14 = 587 मिलता है। विकल्प 1 और 3, 256 × 4 = 1024 से शुरू होते हैं और 51 तक नहीं आ सकते (इनसे लगभग 1032.8 और 102.8 मिलते हैं)।"},{"id":"c23s1-23","p":"c23s1","n":23,"s":"rea","t":"Series","q":"Select the option that represents the letters that, when placed from left to right in the following blanks, will complete the letter-series.\nC L _ V E C _ _ W E C L O _ _ C _ O _ E","w":"The series is made of five-letter groups of the form C L O _ E, with the fourth letter moving one step forward each time. Filling O, L, O, X, E, L, Y gives CLOVE, CLOWE, CLOXE, CLOYE: the fourth letters V, W, X, Y are consecutive. Option 2 would give CLOVE, CLOWE, CLOYE, CLOZE, skipping X, while options 1 and 3 break the C L O _ E frame.","o":["O L P X E L Y","O L O Y E L Z","O L O X F M Y","O L O X E L Y"],"a":[3],"qt":"उस विकल्प का चयन करें जो उन अक्षरों का प्रतिनिधित्व करता है, जिन्हें निम्नलिखित रिक्त स्थानों में बाएं से दाएं रखे जाने पर अक्षर-श्रृंखला पूरी हो जाएगी।\nC L _ V E C _ _ W E C L O _ _ C _ O _ E","ot":["O L P X E L Y","O L O Y E L Z","O L O X F M Y","O L O X E L Y"],"wt":"शृंखला C L O _ E रूप के पाँच-अक्षरी समूहों से बनी है, जिनमें चौथा अक्षर हर बार एक स्थान आगे बढ़ता है। O, L, O, X, E, L, Y भरने पर CLOVE, CLOWE, CLOXE, CLOYE बनते हैं: चौथे अक्षर V, W, X, Y क्रमागत हैं। विकल्प 2 से CLOVE, CLOWE, CLOYE, CLOZE बनेंगे, जिसमें X छूट जाता है, जबकि विकल्प 1 और 3, C L O _ E ढाँचे को तोड़ देते हैं।"},{"id":"c23s1-24","p":"c23s1","n":24,"s":"rea","t":"Coding-Decoding","q":"In a certain code language, ‘TABLE’ is coded as ELEAT and ‘SWING’ is coded as GNLWS. How will ‘FRAME’ be coded in the same language?","w":"The word is written in reverse order and then the middle letter is moved 3 places forward. TABLE reversed is ELBAT, and B + 3 = E gives ELEAT. SWING reversed is GNIWS, and I + 3 = L gives GNLWS. FRAME reversed is EMARF, and A + 3 = D gives EMDRF. EMERF moves the middle letter 4 places, and ERMDF and MEDFR change the letter order.","o":["EMERF","EMDRF","ERMDF","MEDFR"],"a":[1],"qt":"एक निश्चित कूट-भाषा में 'TABLE' को ELEAT के रूप में कूटबद्ध किया गया है और 'SWING' को GNLWS के रूप में कूटबद्ध किया गया है। उसी भाषा में 'FRAME' को किस प्रकार कूटबद्ध किया जाएगा?","ot":["EMERF","EMDRF","ERMDF","MEDFR"],"wt":"शब्द को उलटे क्रम में लिखकर बीच वाले अक्षर को 3 स्थान आगे बढ़ाया जाता है। TABLE का उलटा ELBAT है, और B + 3 = E से ELEAT बनता है। SWING का उलटा GNIWS है, और I + 3 = L से GNLWS बनता है। FRAME का उलटा EMARF है, और A + 3 = D से EMDRF बनता है। EMERF में बीच का अक्षर 4 स्थान बढ़ाया गया है, तथा ERMDF और MEDFR में अक्षरों का क्रम बदल गया है।"},{"id":"c23s1-25","p":"c23s1","n":25,"s":"rea","t":"Mathematical Operations","q":"Which two signs should be interchanged to make the given equation correct?\n588 ÷ 28 × 32 + 72 − 160 = 760","w":"As given, 588 ÷ 28 × 32 + 72 − 160 = 21 × 32 + 72 − 160 = 672 + 72 − 160 = 584, not 760. Interchange − and +: 588 ÷ 28 × 32 − 72 + 160 = 672 − 72 + 160 = 760, which is correct. The other swaps do not work; for example, interchanging ÷ and + gives 588 + 28 × 32 ÷ 72 − 160, which is not even a whole number.","o":["− and +","÷ and −","+ and ×","÷ and +"],"a":[0],"qt":"दिए गए समीकरण को संतुलित करने के लिए किन दो चिह्नों को आपस में बदला जाना चाहिए?\n588 ÷ 28 × 32 + 72 − 160 = 760","ot":["− और +","÷ और −","+ और ×","÷ और +"],"wt":"दिए गए रूप में 588 ÷ 28 × 32 + 72 − 160 = 21 × 32 + 72 − 160 = 672 + 72 − 160 = 584, जो 760 नहीं है। − और + को आपस में बदलने पर: 588 ÷ 28 × 32 − 72 + 160 = 672 − 72 + 160 = 760, जो सही है। अन्य अदला-बदली काम नहीं करतीं; उदाहरण के लिए ÷ और + को बदलने पर 588 + 28 × 32 ÷ 72 − 160 मिलता है, जो पूर्ण संख्या भी नहीं है।"},{"id":"c23s1-26","p":"c23s1","n":26,"s":"cur","t":"Sports","q":"The length of the badminton court for singles is:","w":"Under the Badminton World Federation's Laws of Badminton, the court is 13.40 m (44 feet) long for both singles and doubles; only the width differs, 5.18 m for singles and 6.10 m for doubles. The net is 1.524 m high at the centre and 1.55 m at the posts. In singles the long service line is the back boundary line, while in doubles it is 0.76 m inside it. The other options are distractors close to 13.40 m.","o":["13.44 m","13.55 m","14 m","13.40 m"],"a":[3],"qt":"एकल के लिए बैडमिंटन कोर्ट की लंबाई कितनी होती है?","ot":["13.44 m","13.55 m","14 m","13.40 m"],"wt":"बैडमिंटन विश्व महासंघ (BWF) के बैडमिंटन नियमों के अनुसार कोर्ट की लंबाई एकल और युगल दोनों के लिए 13.40 मीटर (44 फुट) होती है; केवल चौड़ाई अलग होती है: एकल के लिए 5.18 मीटर और युगल के लिए 6.10 मीटर। नेट की ऊँचाई बीच में 1.524 मीटर और खंभों पर 1.55 मीटर होती है। एकल में लंबी सर्विस रेखा ही पीछे की सीमा रेखा होती है, जबकि युगल में यह उससे 0.76 मीटर अंदर होती है। अन्य विकल्प 13.40 मीटर के निकट के भ्रामक मान हैं।"},{"id":"c23s1-27","p":"c23s1","n":27,"s":"pol","t":"Judiciary & Constitutional Bodies","q":"Who is the Administrative Head of the Indian Audit and Accounts Department?","w":"The Comptroller and Auditor General of India (CAG), a constitutional authority under Article 148, heads the Indian Audit and Accounts Department. Appointed by the President by warrant under his hand and seal, the CAG holds office for six years or until the age of 65, whichever is earlier, and can be removed only in the manner of a Supreme Court judge. Accountants General, Principal Accountants General and Directors General head the department's field offices and work under the CAG, who audits the accounts of the Union and the states.","o":["Accountant General","Principal Accountant General","Director General","The Comptroller and Auditor General"],"a":[3],"qt":"भारतीय लेखापरीक्षा और लेखा विभाग का प्रशासनिक प्रमुख कौन होता है?","ot":["महालेखाकार","प्रधान महालेखाकार","महानिदेशक","नियंत्रक एवं महालेखापरीक्षक"],"wt":"भारत के नियंत्रक एवं महालेखापरीक्षक (CAG), जो अनुच्छेद 148 के अंतर्गत एक संवैधानिक प्राधिकारी हैं, भारतीय लेखापरीक्षा और लेखा विभाग के प्रमुख होते हैं। राष्ट्रपति उन्हें अपने हस्ताक्षर और मुद्रा सहित अधिपत्र द्वारा नियुक्त करते हैं; उनका कार्यकाल छह वर्ष या 65 वर्ष की आयु तक, जो भी पहले हो, होता है, और उन्हें केवल सर्वोच्च न्यायालय के न्यायाधीश की भाँति ही हटाया जा सकता है। महालेखाकार, प्रधान महालेखाकार और महानिदेशक विभाग के क्षेत्रीय कार्यालयों के प्रमुख होते हैं और CAG के अधीन काम करते हैं, जो संघ और राज्यों के लेखाओं की लेखापरीक्षा करते हैं।"},{"id":"c23s1-28","p":"c23s1","n":28,"s":"eco","t":"Schemes & Welfare","q":"Which of the following is the largest pan-India scheme to strengthen health care infrastructure across the country with focus on primary, secondary and tertiary care services?","w":"The Pradhan Mantri Ayushman Bharat Health Infrastructure Mission (PM-ABHIM), announced in the Union Budget 2021-22 and launched by the Prime Minister at Varanasi on 25 October 2021 with an outlay of about ₹64,180 crore, is described by the government as the largest pan-India scheme for health infrastructure. It strengthens primary, secondary and tertiary care, critical care blocks, public health laboratories and disease surveillance. AB-PMJAY is a health assurance scheme (cover of ₹5 lakh per family a year), and LaQshya improves the quality of care in labour rooms.","o":["LaQshya","AB-PMJAY","PM-ABHIM","PM-MI"],"a":[2],"qt":"प्राथमिक, माध्यमिक और तृतीयक देखभाल सेवाओं पर ध्यान देने के साथ देश भर में स्वास्थ्य देखभाल के बुनियादी ढांचे को मजबूत करने के लिए शुरू की गई सबसे बड़ी अखिल भारतीय योजना निम्नलिखित में से कौन-सी है?","ot":["LaQshya","AB-PMJAY","PM-ABHIM","PM-MI"],"wt":"प्रधानमंत्री आयुष्मान भारत स्वास्थ्य अवसंरचना मिशन (PM-ABHIM), जिसकी घोषणा केंद्रीय बजट 2021-22 में हुई और जिसे प्रधानमंत्री ने 25 अक्टूबर 2021 को वाराणसी में लगभग ₹64,180 करोड़ के परिव्यय के साथ शुरू किया, को सरकार स्वास्थ्य अवसंरचना की सबसे बड़ी अखिल भारतीय योजना बताती है। यह प्राथमिक, माध्यमिक और तृतीयक देखभाल, क्रिटिकल केयर ब्लॉकों, सार्वजनिक स्वास्थ्य प्रयोगशालाओं और रोग निगरानी को मजबूत करता है। AB-PMJAY एक स्वास्थ्य आश्वासन योजना है (प्रति परिवार प्रति वर्ष ₹5 लाख का कवर), और LaQshya प्रसव कक्षों (लेबर रूम) में देखभाल की गुणवत्ता सुधारता है।"},{"id":"c23s1-29","p":"c23s1","n":29,"s":"cur","t":"Static GK & Culture","q":"Which of the following festivals is associated with the term ‘ties of protection’?","w":"Raksha Bandhan literally means \"the tie (bond) of protection\" (raksha = protection, bandhan = tie). Celebrated on the full-moon day (Purnima) of the month of Shravan, it marks the bond between brothers and sisters: the sister ties a rakhi, a sacred thread, on her brother's wrist and he promises to protect her. Baisakhi is the spring harvest festival of Punjab, Karwa Chauth is a fast kept by married women for their husbands, and Chhath Puja is devoted to the Sun god, mainly in Bihar and eastern Uttar Pradesh.","o":["Baisakhi","Karwa Chauth","Chhath Pooja","Raksha Bandhan"],"a":[3],"qt":"निम्नलिखित में से कौन-सा त्योहार 'टाई ऑफ प्रोटेक्शन' शब्द से जुड़ा है?","ot":["बैसाखी","करवा चौथ","छठ पूजा","रक्षाबंधन"],"wt":"रक्षाबंधन का शाब्दिक अर्थ है 'सुरक्षा का बंधन' (रक्षा = सुरक्षा, बंधन = डोर या बंधन)। श्रावण मास की पूर्णिमा को मनाया जाने वाला यह त्योहार भाई-बहन के संबंध का प्रतीक है: बहन भाई की कलाई पर पवित्र धागा, राखी, बाँधती है और भाई उसकी रक्षा का वचन देता है। बैसाखी पंजाब का वसंतकालीन फसल उत्सव है, करवा चौथ का व्रत विवाहित महिलाएँ अपने पतियों के लिए रखती हैं, और छठ पूजा सूर्य देव को समर्पित है, जो मुख्यतः बिहार और पूर्वी उत्तर प्रदेश में मनाई जाती है।"},{"id":"c23s1-30","p":"c23s1","n":30,"s":"cur","t":"Sports","q":"In October 2021, 19-year-old ________ won the silver medal at the World Wrestling Championship.","w":"Anshu Malik of Haryana won silver in the women's 57 kg freestyle category at the 2021 World Wrestling Championships in Oslo, Norway (October 2021), losing the final to Helen Maroulis of the USA, the 2016 Olympic champion. She became the first Indian woman wrestler to reach a World Championship final and win silver; earlier Indian women had won only bronze medals. At the same championships Sarita Mor won bronze in the 59 kg category. Sonam Malik and Seema Bisla are also Indian women wrestlers.","o":["Anshu Malik","Seema Bisla","Sanju Devi","Sonam Malik"],"a":[0],"qt":"अक्टूबर 2021 में, 19 वर्षीया ________ ने विश्व कुश्ती चैम्पियनशिप में रजत पदक जीता।","ot":["अंशु मलिक","सीमा बिसला","संजू देवी","सोनम मलिक"],"wt":"हरियाणा की अंशु मलिक ने अक्टूबर 2021 में ओस्लो (नॉर्वे) में हुई विश्व कुश्ती चैम्पियनशिप में महिलाओं की 57 किग्रा फ्रीस्टाइल श्रेणी में रजत पदक जीता; फाइनल में वे 2016 की ओलंपिक चैंपियन अमेरिका की हेलेन मारूलिस से हारीं। वे विश्व चैम्पियनशिप के फाइनल में पहुँचने और रजत जीतने वाली पहली भारतीय महिला पहलवान बनीं; इससे पहले भारतीय महिलाओं ने केवल कांस्य पदक जीते थे। इसी चैम्पियनशिप में सरिता मोर ने 59 किग्रा श्रेणी में कांस्य जीता। सोनम मलिक और सीमा बिसला भी भारतीय महिला पहलवान हैं।"},{"id":"c23s1-31","p":"c23s1","n":31,"s":"eco","t":"Planning, Growth & Budget","q":"________ emerged as the poorest state as per the first-ever Multi-dimensional Poverty Index (MPI) prepared by Niti Aayog and launched in November 2021.","w":"NITI Aayog's National Multidimensional Poverty Index: Baseline Report (November 2021), based on NFHS-4 (2015-16) data, found 51.91% of Bihar's population multidimensionally poor, the highest of any state, followed by Jharkhand (42.16%), Uttar Pradesh (37.79%) and Madhya Pradesh (36.65%); Kerala had the lowest share (0.71%). The index follows the global Alkire-Foster method and covers three equally weighted dimensions, health, education and standard of living, through 12 indicators such as nutrition, years of schooling, cooking fuel, sanitation, housing and bank accounts.","o":["Bihar","Madhya Pradesh","Uttar Pradesh","Mizoram"],"a":[0],"qt":"नीति आयोग द्वारा तैयार किए गए और नवंबर 2021 में जारी किए गए पहले बहुआयामी गरीबी सूचकांक (MPI) के अनुसार, निम्नलिखित में से कौन-सा राज्य सबसे गरीब राज्य के रूप में उभरा?","ot":["बिहार","मध्य प्रदेश","उत्तर प्रदेश","मिज़ोरम"],"wt":"नीति आयोग की राष्ट्रीय बहुआयामी गरीबी सूचकांक: बेसलाइन रिपोर्ट (नवंबर 2021), जो NFHS-4 (2015-16) के आँकड़ों पर आधारित है, के अनुसार बिहार की 51.91% जनसंख्या बहुआयामी रूप से गरीब थी, जो किसी भी राज्य में सर्वाधिक है; इसके बाद झारखंड (42.16%), उत्तर प्रदेश (37.79%) और मध्य प्रदेश (36.65%) थे; केरल में यह हिस्सा सबसे कम (0.71%) था। यह सूचकांक वैश्विक एल्किरे-फोस्टर पद्धति पर आधारित है और समान भार वाले तीन आयामों, स्वास्थ्य, शिक्षा और जीवन स्तर, को पोषण, स्कूली शिक्षा के वर्ष, खाना पकाने का ईंधन, स्वच्छता, आवास और बैंक खाते जैसे 12 संकेतकों से मापता है।"},{"id":"c23s1-32","p":"c23s1","n":32,"s":"eco","t":"Planning, Growth & Budget","q":"The consumption of fixed capital is also known as _________.","w":"Fixed capital such as machinery and buildings wears out through use and age; the value of this wear and tear during a year is called depreciation, which national income accounting (NCERT Macroeconomics) also calls consumption of fixed capital. It links gross and net measures: net investment = gross investment − depreciation, and NDP = GDP − depreciation. Appreciation is a rise in an asset's value, the opposite idea, while gross investment is the total addition to the capital stock before depreciation is deducted.","o":["depreciation","net investment","appreciation","gross investment"],"a":[0],"qt":"अचल पूंजी के उपभोग को _________ के रूप में भी जाना जाता है।","ot":["मूल्यह्रास","निवल निवेश","मूल्यवृद्धि","सकल निवेश"],"wt":"मशीनरी और भवन जैसी अचल पूंजी उपयोग और समय के साथ घिसती है; एक वर्ष में इस टूट-फूट (घिसावट) के मूल्य को मूल्यह्रास कहते हैं, जिसे राष्ट्रीय आय लेखांकन (NCERT समष्टि अर्थशास्त्र) में अचल पूंजी का उपभोग भी कहा जाता है। यह सकल और निवल मापों को जोड़ता है: निवल निवेश = सकल निवेश − मूल्यह्रास, और NDP = GDP − मूल्यह्रास। मूल्यवृद्धि किसी परिसंपत्ति के मूल्य में वृद्धि है, यानी इसका उलटा विचार, जबकि सकल निवेश मूल्यह्रास घटाने से पहले पूंजी स्टॉक में हुई कुल वृद्धि है।"},{"id":"c23s1-33","p":"c23s1","n":33,"s":"ih","t":"Ancient India","q":"The Vedic Aryans lived in the area called Sapt-Sindhu, which means area drained by seven rivers. One of the rivers among the seven is Jhelum. What was its ancient name?","w":"In the Rig Veda the Jhelum is called Vitasta. The other rivers of the Sapta Sindhu region carry similar Vedic names: Sindhu (Indus), Askini or Asikni (Chenab), Parushni (Ravi), Vipash or Vipasha (Beas), Shutudri (Sutlej) and Saraswati. The Parushni (Ravi) is remembered as the scene of the Battle of Ten Kings (Dasharajna), in which Sudas of the Bharata tribe defeated a confederacy of ten tribes. The Jhelum rises in Kashmir and joins the Chenab in Pakistan.","o":["Askini","Parushni","Vipash","Vitasta"],"a":[3],"qt":"वैदिक आर्य सप्त-सिंधु नामक क्षेत्र में रहते थे, जिसका अर्थ सात नदियों द्वारा अपवाहित क्षेत्र है। सात नदियों में से एक झेलम नदी है। इसका प्राचीन नाम क्या था ?","ot":["अस्किनी","परुष्णि","विपाश","वितस्ता"],"wt":"ऋग्वेद में झेलम को वितस्ता कहा गया है। सप्त सिंधु क्षेत्र की अन्य नदियों के भी वैदिक नाम हैं: सिंधु, अस्किनी या असिक्नी (चिनाब), परुष्णि (रावी), विपाश या विपाशा (ब्यास), शुतुद्री (सतलज) और सरस्वती। परुष्णि (रावी) दशराज्ञ युद्ध (दस राजाओं का युद्ध) के स्थल के रूप में प्रसिद्ध है, जिसमें भरत जन के राजा सुदास ने दस जनों के संघ को हराया था। झेलम कश्मीर से निकलती है और पाकिस्तान में चिनाब से मिलती है।"},{"id":"c23s1-34","p":"c23s1","n":34,"s":"ih","t":"Medieval India","q":"In Chola administration, ________ was the assembly in the villages which were inhabited predominantly by the Brahmanas.","w":"Under the Cholas, brahmadeya villages, granted to and settled mainly by Brahmanas, were run by an assembly called the sabha (or mahasabha) of prominent Brahmana landholders, which worked through committees for irrigation tanks, gardens, temples and justice; the Uttaramerur inscriptions of Parantaka I describe how committee members were chosen by drawing palm-leaf tickets from a pot. The ur was the assembly of ordinary peasant villages, and the nagaram was an association of traders that managed affairs in towns. \"Khilya\" is not a Chola assembly.","o":["Ur","Khilya","Nagaram","Sabha"],"a":[3],"qt":"चोल प्रशासन में, ________ गांवों में सदन होती थी जो मुख्य रूप से ब्राह्मणों द्वारा बसाई गई थी।","ot":["उर","खिल्य","नागराम","सभा"],"wt":"चोलों के अधीन ब्रह्मदेय गाँवों, जो ब्राह्मणों को दान में दिए गए थे और मुख्यतः उन्हीं द्वारा बसाए गए थे, का प्रबंधन प्रमुख ब्राह्मण भूस्वामियों की सभा (या महासभा) करती थी, जो सिंचाई के तालाबों, बगीचों, मंदिरों और न्याय के लिए समितियों के माध्यम से काम करती थी; परांतक प्रथम के उत्तरमेरूर अभिलेखों में बताया गया है कि समिति के सदस्यों का चयन घड़े से ताड़पत्र की पर्चियाँ निकालकर किया जाता था। उर सामान्य किसानों के गाँवों की सभा थी, और नगरम् व्यापारियों का संघ था जो नगरों के मामलों का प्रबंधन करता था। 'खिल्य' कोई चोल सभा नहीं है।"},{"id":"c23s1-35","p":"c23s1","n":35,"s":"geo","t":"Indian Geography","q":"Which of the following states is NOT a part of the Tapi Basin?","w":"The Tapi (Tapti) rises at Multai in Betul district of Madhya Pradesh and flows west for about 724 km, between the Satpura range and the Satmala-Ajanta hills, to the Gulf of Khambhat near Surat. According to the Central Water Commission, its basin of about 65,145 sq km lies in Maharashtra (about 79%), Madhya Pradesh (15%) and Gujarat (6%); the Purna is its main tributary. Rajasthan has no part of the basin: its rivers drain to the Chambal (Ganga system), the Luni, or the Mahi and Sabarmati.","o":["Rajasthan","Maharashtra","Madhya Pradesh","Gujarat"],"a":[0],"qt":"निम्नलिखित में से कौन-सा राज्य तापी बेसिन का हिस्सा नहीं है?","ot":["राजस्थान","महाराष्ट्र","मध्य प्रदेश","गुजरात"],"wt":"तापी (ताप्ती) नदी मध्य प्रदेश के बैतूल ज़िले में मुलताई से निकलती है और लगभग 724 किमी पश्चिम की ओर, सतपुड़ा पर्वतमाला और सतमाला-अजंता पहाड़ियों के बीच बहकर सूरत के निकट खंभात की खाड़ी में गिरती है। केंद्रीय जल आयोग के अनुसार इसका लगभग 65,145 वर्ग किमी का बेसिन महाराष्ट्र (लगभग 79%), मध्य प्रदेश (15%) और गुजरात (6%) में फैला है; पूर्णा इसकी मुख्य सहायक नदी है। राजस्थान का कोई भाग इस बेसिन में नहीं है: वहाँ की नदियाँ चंबल (गंगा तंत्र), लूनी, या माही और साबरमती में जल पहुँचाती हैं।"},{"id":"c23s1-36","p":"c23s1","n":36,"s":"sci","t":"Chemistry","q":"Which of the following is used as a cooling medium for the Large Hadron Collider (LHC) and the superconducting magnets in MRI scanners and NMR spectrometers?","w":"Liquid helium, which boils at about 4.2 K (−269 °C), is used to keep the superconducting magnets of MRI scanners and NMR spectrometers below the temperature at which they lose all electrical resistance. CERN's Large Hadron Collider cools its superconducting magnets to 1.9 K (−271.3 °C) with superfluid helium, colder than outer space. Helium is an inert noble gas that does not solidify at normal pressure. Neon and argon are also noble gases but liquefy at much higher temperatures (about 27 K and 87 K), and chlorine is a reactive, toxic halogen.","o":["Neon","Chlorine","Argon","Helium"],"a":[3],"qt":"निम्नलिखित में से किसका उपयोग लार्ज हैड्रोन कोलाइडर (LHC) और MRI स्कैनर तथा NMR स्पेक्ट्रोमीटर में अतिचालक चुम्बकों के लिए शीतलन माध्यम के रूप में किया जाता है?","ot":["नियॉन","क्लोरीन","आर्गन","हीलियम"],"wt":"तरल हीलियम, जो लगभग 4.2 K (−269 °C) पर उबलती है, MRI स्कैनर और NMR स्पेक्ट्रोमीटर के अतिचालक चुम्बकों को उस तापमान से नीचे रखने में प्रयुक्त होती है जिस पर उनका विद्युत प्रतिरोध पूरी तरह समाप्त हो जाता है। CERN का लार्ज हैड्रोन कोलाइडर अपने अतिचालक चुम्बकों को अतितरल (सुपरफ्लूइड) हीलियम से 1.9 K (−271.3 °C) तक ठंडा करता है, जो बाहरी अंतरिक्ष से भी ठंडा है। हीलियम एक अक्रिय उत्कृष्ट गैस है जो सामान्य दाब पर ठोस नहीं बनती। नियॉन और आर्गन भी उत्कृष्ट गैसें हैं परंतु बहुत ऊँचे तापमान (लगभग 27 K और 87 K) पर द्रवित हो जाती हैं, और क्लोरीन एक अभिक्रियाशील, विषैला हैलोजन है।"},{"id":"c23s1-37","p":"c23s1","n":37,"s":"cur","t":"Awards, Books & Persons","q":"In 2018, Google Doodle celebrated the 100th birthday of Mrinalini Sarabhai. She is an exponent of which of the following dance forms?","w":"Mrinalini Sarabhai (11 May 1918 – 21 January 2016), dancer, choreographer and wife of space scientist Vikram Sarabhai, trained in Bharatanatyam under Meenakshisundaram Pillai and in Kathakali under Thakazhi Kunchu Kurup, and was an exponent of both. She founded the Darpana Academy of Performing Arts in Ahmedabad and received the Padma Shri (1965) and Padma Bhushan (1992). Google marked her 100th birth anniversary with a Doodle on 11 May 2018. Her daughter Mallika Sarabhai is also a noted dancer.","o":["Bharatanatyam and Kathakali","Odissi and Kathak","Kuchipudi and Bharatanatyam","Yakshagana"],"a":[0],"qt":"2018 में गूगल डूडल ने मृणालिनी साराभाई का 100वाँ जन्मदिन मनाया। वह निम्नलिखित में से किस नृत्य शैली की प्रतिपादक हैं?","ot":["भरतनाट्यम और कथकली","ओडिसी और कथक","कुचिपुड़ी और भरतनाट्यम","यक्षगान"],"wt":"नर्तकी, नृत्य-निर्देशिका और अंतरिक्ष वैज्ञानिक विक्रम साराभाई की पत्नी मृणालिनी साराभाई (11 मई 1918 – 21 जनवरी 2016) ने मीनाक्षीसुंदरम पिल्लै से भरतनाट्यम और तकषि कुंचु कुरुप से कथकली सीखी और वे दोनों की प्रतिपादक थीं। उन्होंने अहमदाबाद में दर्पण अकादमी ऑफ परफॉर्मिंग आर्ट्स की स्थापना की और उन्हें पद्म श्री (1965) और पद्म भूषण (1992) मिले। गूगल ने 11 मई 2018 को डूडल बनाकर उनकी 100वीं जयंती मनाई। उनकी पुत्री मल्लिका साराभाई भी प्रसिद्ध नर्तकी हैं।"},{"id":"c23s1-38","p":"c23s1","n":38,"s":"cur","t":"Static GK & Culture","q":"Bharatanatyam expresses South Indian religious themes and spiritual ideas of _______.","w":"Bharatanatyam, the classical dance of Tamil Nadu that grew out of the temple dance (Sadir) of the devadasis, expresses South Indian religious themes and spiritual ideas, particularly of Shaivism, along with Vaishnavism and Shaktism. Shiva as Nataraja, the cosmic dancer, is its presiding image, and its technique follows Bharata's Natyashastra and Nandikeshvara's Abhinaya Darpana. It was revived and renamed in the 20th century by E. Krishna Iyer and Rukmini Devi Arundale, who founded Kalakshetra in Chennai in 1936.","o":["Sufism","Shaivism","Buddhism","Jainism"],"a":[1],"qt":"भरतनाट्यम दक्षिण भारत के धार्मिक विषयों और _______ के आध्यात्मिक विचारों को व्यक्त करता है।","ot":["सूफीवाद","शैव धर्म","बुद्ध धर्म","जैन धर्म"],"wt":"भरतनाट्यम, तमिलनाडु का शास्त्रीय नृत्य जो देवदासियों के मंदिर नृत्य (सादिर) से विकसित हुआ, दक्षिण भारत के धार्मिक विषयों और आध्यात्मिक विचारों, विशेषकर शैव धर्म के, साथ ही वैष्णव और शाक्त परंपराओं के विचारों को व्यक्त करता है। ब्रह्मांडीय नर्तक नटराज के रूप में शिव इसकी प्रमुख छवि हैं, और इसकी तकनीक भरत के नाट्यशास्त्र और नंदिकेश्वर के अभिनय दर्पण पर आधारित है। 20वीं सदी में ई. कृष्ण अय्यर और रुक्मिणी देवी अरुंडेल ने इसे पुनर्जीवित किया और यह नाम दिया; रुक्मिणी देवी ने 1936 में चेन्नई में कलाक्षेत्र की स्थापना की।"},{"id":"c23s1-39","p":"c23s1","n":39,"s":"cur","t":"Awards, Books & Persons","q":"Who among the following musicians is popular for his mastery over the musical instrument Sitar?","w":"Ustad Vilayat Khan (1928–2004) of the Imdadkhani (Etawah) gharana is regarded as one of the greatest sitar players; he developed the gayaki ang, a style that imitates the human voice on the sitar. He famously declined the Padma Shri, Padma Bhushan and Padma Vibhushan. The other three were sarod players: Ali Akbar Khan, son of Allauddin Khan of the Maihar gharana; Bahadur Khan, Allauddin Khan's nephew and Ali Akbar Khan's cousin; and Amjad Ali Khan of the Senia Bangash gharana.","o":["Ali Akbar Khan","Vilayat Khan","Bahadur Khan","Amjad Ali Khan"],"a":[1],"qt":"निम्नलिखित में से कौन-सा संगीतकार संगीत वाद्य यंत्र सितार पर अपनी महारत के लिए लोकप्रिय है?","ot":["अली अकबर खाँ","विलायत खाँ","बहादुर खान","अमजद अली खान"],"wt":"इमदादखानी (इटावा) घराने के उस्ताद विलायत खाँ (1928–2004) को महानतम सितार वादकों में गिना जाता है; उन्होंने गायकी अंग विकसित किया, जिसमें सितार पर मानव स्वर की नकल की जाती है। उन्होंने पद्म श्री, पद्म भूषण और पद्म विभूषण लेने से इनकार कर दिया था। अन्य तीनों सरोद वादक थे: अली अकबर खाँ, मैहर घराने के अलाउद्दीन खाँ के पुत्र; बहादुर खान, अलाउद्दीन खाँ के भतीजे और अली अकबर खाँ के चचेरे भाई; और सेनिया बंगश घराने के अमजद अली खान।"},{"id":"c23s1-40","p":"c23s1","n":40,"s":"cur","t":"Sports","q":"Which of the following countries was the host of AFC Women's Asia Cup Football–2022?","w":"India hosted the 2022 AFC Women's Asian Cup from 20 January to 6 February 2022, with matches in Mumbai, Navi Mumbai and Pune in Maharashtra; the tournament was also the final Asian qualifying stage for the 2023 FIFA Women's World Cup. China won a record ninth title by beating South Korea 3–2 in the final. The hosts had to withdraw during the group stage after a COVID-19 outbreak left the Indian team without the minimum number of players.","o":["Japan","Bangladesh","India","China"],"a":[2],"qt":"निम्नलिखित में से कौन-सा देश एएफसी महिला एशिया कप फुटबॉल-2022 का आयोजक था?","ot":["जापान","बांग्लादेश","भारत","चीन"],"wt":"भारत ने 20 जनवरी से 6 फरवरी 2022 तक AFC महिला एशियाई कप 2022 की मेज़बानी की, जिसके मैच महाराष्ट्र के मुंबई, नवी मुंबई और पुणे में हुए; यह प्रतियोगिता 2023 फीफा महिला विश्व कप के लिए एशिया का अंतिम क्वालीफाइंग चरण भी थी। चीन ने फाइनल में दक्षिण कोरिया को 3–2 से हराकर रिकॉर्ड नौवाँ खिताब जीता। मेज़बान भारत को ग्रुप चरण के दौरान हटना पड़ा, क्योंकि कोविड-19 के प्रकोप के कारण भारतीय टीम के पास न्यूनतम आवश्यक संख्या में खिलाड़ी नहीं बचे थे।"},{"id":"c23s1-41","p":"c23s1","n":41,"s":"cur","t":"Sports","q":"Ms Bhakti Pradip Kulkarni was conferred with the Arjuna Award 2022 for her outstanding contribution in which of the following sports?","w":"Bhakti Kulkarni of Goa, a Woman Grandmaster and International Master and a former Asian women's champion, received the Arjuna Award 2022 for chess along with Grandmaster R. Praggnanandhaa. The National Sports Awards 2022 were presented by President Droupadi Murmu at Rashtrapati Bhavan on 30 November 2022, when table tennis player Achanta Sharath Kamal received the Major Dhyan Chand Khel Ratna. She was also part of India's bronze-winning women's team at the 44th Chess Olympiad (Chennai, 2022).","o":["Table Tennis","Chess","Badminton","Wrestling"],"a":[1],"qt":"सुश्री भक्ति प्रदीप कुलकर्णी को निम्नलिखित में से किस खेल में उत्कृष्ट योगदान के लिए अर्जुन पुरस्कार 2022 से सम्मानित किया गया?","ot":["टेबल टेनिस","शतरंज","बैडमिंटन","कुश्ती"],"wt":"गोवा की भक्ति कुलकर्णी, जो वुमन ग्रैंडमास्टर और इंटरनेशनल मास्टर तथा पूर्व एशियाई महिला चैंपियन हैं, को ग्रैंडमास्टर आर. प्रज्ञानानंदा के साथ शतरंज के लिए अर्जुन पुरस्कार 2022 मिला। राष्ट्रीय खेल पुरस्कार 2022 राष्ट्रपति द्रौपदी मुर्मू ने 30 नवंबर 2022 को राष्ट्रपति भवन में प्रदान किए, जब टेबल टेनिस खिलाड़ी अचंता शरत कमल को मेजर ध्यानचंद खेल रत्न मिला। वे 44वें शतरंज ओलंपियाड (चेन्नई, 2022) में कांस्य जीतने वाली भारतीय महिला टीम की सदस्य भी थीं।"},{"id":"c23s1-42","p":"c23s1","n":42,"s":"ih","t":"Modern India","q":"Who among the following was the founder of ‘Tiger Legion' or ‘Free India Legion'?","w":"After escaping from house arrest in Calcutta in January 1941, Subhas Chandra Bose reached Berlin and, with German support, raised the Indian Legion or Free India Legion (Legion Freies Indien), mainly from Indian prisoners of war captured in North Africa. Its badge showed a springing tiger on a tricolour, giving it the name Tiger Legion. In Germany Bose also set up the Free India Centre and Azad Hind Radio, and was first hailed as \"Netaji\" there. Sohan Singh Bhakna and Lala Har Dayal founded the Ghadar Party (1913).","o":["Vinayak Damodar Savarkar","Subhas Chandra Bose","Sohan Singh Bhakhna","Lala Hardayal"],"a":[1],"qt":"टाइगर लीजन' या 'फ्री इंडिया लीजन' के संस्थापक कौन थे?","ot":["विनायक दामोदर सावरकर","सुभाष चंद्र बोस","सोहन सिंह भखना","लाला हरदयाल"],"wt":"जनवरी 1941 में कलकत्ता में नज़रबंदी से निकलकर सुभाष चंद्र बोस बर्लिन पहुँचे और जर्मनी की सहायता से इंडियन लीजन या फ्री इंडिया लीजन (Legion Freies Indien) का गठन किया, जिसमें मुख्यतः उत्तर अफ्रीका में पकड़े गए भारतीय युद्धबंदी थे। इसके बैज पर तिरंगे पर छलाँग लगाता बाघ अंकित था, जिससे इसे टाइगर लीजन कहा गया। जर्मनी में बोस ने फ्री इंडिया सेंटर और आज़ाद हिंद रेडियो भी स्थापित किए, और वहीं उन्हें पहली बार 'नेताजी' कहा गया। सोहन सिंह भकना और लाला हरदयाल ने ग़दर पार्टी (1913) की स्थापना की थी।"},{"id":"c23s1-43","p":"c23s1","n":43,"s":"sci","t":"Biology","q":"Name a reproductive strategy in which parasites take advantage of the care of other individuals of the same species or different species to raise their young.","w":"In brood parasitism the parasite leaves the rearing of its young to a host. NCERT Class 12 Biology's example is the cuckoo (koel), which lays its eggs in a crow's nest and lets the crow incubate them and feed the chicks; the parasite's eggs have evolved to resemble the host's in size and colour. Brood parasites may exploit other species or members of their own species. Kleptoparasitism is stealing food caught by another animal, and sexual parasitism is the fusion of dwarf males with females, as in some anglerfish.","o":["Brood parasitism","Sexual parasitism","Klepto parasitism","Competitive parasitism"],"a":[0],"qt":"एक प्रजनन रणनीति का नाम बताइए जिसमें परजीवी एक ही प्रजाति या विभिन्न प्रजातियों के अन्य जीवों की देखभाल का लाभ उठाते हैं जिससे वे अपने बच्चों को पाल सकें।","ot":["शाव परजीविता","लैंगिक परजीविता","क्लैप्टो परजीविता","प्रतिस्पर्धी परजीविता"],"wt":"शाव परजीविता (ब्रूड पैरासिटिज़्म) में परजीवी अपने बच्चों के पालन-पोषण का काम पोषक (होस्ट) पर छोड़ देता है। NCERT कक्षा 12 जीवविज्ञान का उदाहरण कोयल है, जो कौए के घोंसले में अंडे देती है और कौआ उन्हें सेता है तथा चूज़ों को खिलाता है; परजीवी के अंडे आकार और रंग में पोषक के अंडों जैसे विकसित हो गए हैं। शाव परजीवी दूसरी प्रजातियों या अपनी ही प्रजाति के सदस्यों का लाभ उठा सकते हैं। क्लैप्टो परजीविता किसी अन्य जीव द्वारा पकड़ा गया भोजन चुराना है, और लैंगिक परजीविता में बौने नर मादाओं से जुड़ जाते हैं, जैसे कुछ एंगलरफिश में।"},{"id":"c23s1-44","p":"c23s1","n":44,"s":"geo","t":"Indian Geography","q":"On the basis of tribal population (2011), identify the option that arranges the following states in ascending order.\nA. Madhya Pradesh\nB. Maharashtra\nC. Odisha","w":"Census 2011 counted about 10.43 crore Scheduled Tribe people (8.6% of India's population). Madhya Pradesh has the largest ST population (about 1.53 crore, 14.7% of India's tribals), followed by Maharashtra (about 1.05 crore) and Odisha (about 95.9 lakh), with Rajasthan and Gujarat next. In ascending order this gives Odisha (C) < Maharashtra (B) < Madhya Pradesh (A). By share of the state's own population, however, Odisha (22.8%) is well ahead of Maharashtra (9.4%).","o":["(C), (B), (A)","(B), (A), (C),","(C), (A), (B)","(B), (C), (A)"],"a":[0],"qt":"जनजातीय जनसंख्या (2011) के आधार पर, उस विकल्प की पहचान कीजिए जो निम्नलिखित राज्यों को आरोही क्रम में व्यवस्थित करता है।\nA. मध्य प्रदेश\nB. महाराष्ट्र\nC. ओडिशा","ot":["(C), (B), (A)","(B), (A), (C),","(C), (A), (B)","(B), (C), (A)"],"wt":"जनगणना 2011 में लगभग 10.43 करोड़ अनुसूचित जनजाति के लोग गिने गए (भारत की जनसंख्या का 8.6%)। मध्य प्रदेश की जनजातीय जनसंख्या सबसे अधिक है (लगभग 1.53 करोड़, भारत की कुल जनजातीय जनसंख्या का 14.7%), इसके बाद महाराष्ट्र (लगभग 1.05 करोड़) और ओडिशा (लगभग 95.9 लाख) हैं, फिर राजस्थान और गुजरात। आरोही क्रम में यह ओडिशा (C) < महाराष्ट्र (B) < मध्य प्रदेश (A) होता है। किंतु राज्य की अपनी जनसंख्या में हिस्से के आधार पर ओडिशा (22.8%) महाराष्ट्र (9.4%) से काफी आगे है।"},{"id":"c23s1-45","p":"c23s1","n":45,"s":"eco","t":"Agriculture, Industry & Trade","q":"In which industrial policy was the investment limit for tiny industry/unit increased to ₹2 lakh?","w":"The Industrial Policy of 1977 first defined the tiny sector as units with investment in machinery and equipment up to ₹1 lakh located in towns with a population below 50,000, and set up District Industries Centres. The Industrial Policy Statement of 1980 raised the limits: tiny units from ₹1 lakh to ₹2 lakh, small-scale units from ₹10 lakh to ₹20 lakh and ancillary units from ₹15 lakh to ₹25 lakh. The 1991 small-sector policy raised the tiny-unit limit to ₹5 lakh, and 1956 is the year of the second Industrial Policy Resolution.","o":["1977","1991","1980","1956"],"a":[2],"qt":"किस औद्योगिक नीति में अति लघु उद्योग/इकाई के लिए निवेश सीमा बढ़ाकर ₹2 लाख की गई?","ot":["1977","1991","1980","1956"],"wt":"1977 की औद्योगिक नीति ने पहली बार अति लघु क्षेत्र को ऐसी इकाइयों के रूप में परिभाषित किया जिनका मशीनरी और उपकरणों में निवेश ₹1 लाख तक हो और जो 50,000 से कम जनसंख्या वाले कस्बों में स्थित हों, तथा ज़िला उद्योग केंद्र स्थापित किए। 1980 के औद्योगिक नीति वक्तव्य ने सीमाएँ बढ़ाईं: अति लघु इकाइयों के लिए ₹1 लाख से ₹2 लाख, लघु उद्योगों के लिए ₹10 लाख से ₹20 लाख और सहायक (एंसिलरी) इकाइयों के लिए ₹15 लाख से ₹25 लाख। 1991 की लघु क्षेत्र नीति ने अति लघु इकाई की सीमा ₹5 लाख की, और 1956 दूसरे औद्योगिक नीति प्रस्ताव का वर्ष है।"},{"id":"c23s1-46","p":"c23s1","n":46,"s":"geo","t":"World & Physical Geography","q":"Which scientist thought of the concept of steady state of the universe?","w":"The steady state theory was put forward in 1948 by Fred Hoyle with Hermann Bondi and Thomas Gold; NCERT's Fundamentals of Physical Geography calls it \"Hoyle's concept of steady state\". It held that the universe is roughly the same at any point of time, new matter being created continuously as it expands. The Big Bang theory, backed by Edwin Hubble's evidence (1920s) that the universe is expanding, has replaced it. Laplace gave the nebular hypothesis (1796) of the solar system's origin, and Sir Harold Jeffreys (spelt Jeffrey in NCERT) supported the binary (tidal) theories.","o":["Harold Jeffrey","Edwin Hubble","Fred Hoyle","Pierre-Simon Laplace"],"a":[2],"qt":"ब्रह्मांड की स्थिर अवस्था की संकल्पना के बारे में किस वैज्ञानिक ने विचार किया था?","ot":["हेरोल्ड जेफरी (Harold Jeffrey)","ऍडविन हबल (Edwin Hubble)","फ़्रेड हॉयल (Fred Hoyle)","पियरे साइमन लाप्लास (Pierre-Simon Laplace)"],"wt":"स्थिर अवस्था सिद्धांत 1948 में फ्रेड हॉयल ने हरमन बॉन्डी और थॉमस गोल्ड के साथ प्रस्तुत किया; NCERT की 'भौतिक भूगोल के मूल सिद्धांत' इसे हॉयल की स्थिर अवस्था संकल्पना कहती है। इसके अनुसार ब्रह्मांड किसी भी समय लगभग एक जैसा रहता है, क्योंकि फैलने के साथ-साथ उसमें निरंतर नया पदार्थ बनता रहता है। बिग बैंग सिद्धांत ने, जिसे एडविन हबल के इस साक्ष्य (1920 का दशक) से समर्थन मिला कि ब्रह्मांड फैल रहा है, इसका स्थान ले लिया है। लाप्लास ने सौरमंडल की उत्पत्ति की निहारिका परिकल्पना (1796) दी, और सर हैरोल्ड जेफ्रीज़ (NCERT में जेफरी) ने द्वैतारक (ज्वारीय) सिद्धांतों का समर्थन किया।"},{"id":"c23s1-47","p":"c23s1","n":47,"s":"sci","t":"Biology","q":"Match the columns.\nColum-A (Class) | Column-B (Common name)\ni. Chlorophyceae | a. Brown algae\nii. Phaeophyceae | b. Green algae\niii. Rhodophyceae | c. Blue-green algae\niv. Cyanophyceae | d. Red algae","w":"Algae are classified mainly by their pigments (NCERT Class 11, Plant Kingdom). Chlorophyceae are green algae, coloured by chlorophyll a and b (Chlamydomonas, Spirogyra); Phaeophyceae are brown algae, with fucoxanthin (Ectocarpus, Laminaria, Sargassum); Rhodophyceae are red algae, with r-phycoerythrin (Polysiphonia, Gelidium, Gracilaria); and Cyanophyceae are blue-green algae (Nostoc, Anabaena), now treated as cyanobacteria in kingdom Monera. So the match is i-b, ii-a, iii-d, iv-c.","o":["i-b, ii-c, iii-a, iv-d","i-b, ii-a, iii-d, iv-c","i-d, ii-c, iii-b, iv-a","i-a, ii-b, iii-c, iv-d"],"a":[1],"qt":"स्तंभों का मिलान कीजिए।\nस्तंभ-A (वर्ग) | स्तंभ-B (सामान्य नाम)\ni. क्लोरोफाइसी | a. भूरा शैवाल\nii. फियोफाइसी | b. हरी शैवाल\niii. रोडोफाइसी | c. नीले-हरे शैवाल\niv. सायनोफाइसी | d. लाल शैवाल","ot":["i-b, ii-c, iii-a, iv-d","i-b, ii-a, iii-d, iv-c","i-d, ii-c, iii-b, iv-a","i-a, ii-b, iii-c, iv-d"],"wt":"शैवालों का वर्गीकरण मुख्यतः उनके वर्णकों के आधार पर होता है (NCERT कक्षा 11, वनस्पति जगत)। क्लोरोफाइसी हरे शैवाल हैं, जिनका रंग क्लोरोफिल a और b से होता है (क्लैमाइडोमोनास, स्पाइरोगाइरा); फियोफाइसी भूरे शैवाल हैं, जिनमें फ्यूकोज़ैन्थिन होता है (एक्टोकार्पस, लैमिनेरिया, सरगासम); रोडोफाइसी लाल शैवाल हैं, जिनमें r-फाइकोइरिथ्रिन होता है (पॉलीसाइफोनिया, जेलिडियम, ग्रेसिलेरिया); और सायनोफाइसी नीले-हरे शैवाल हैं (नॉस्टॉक, एनाबीना), जिन्हें अब मोनेरा जगत में सायनोबैक्टीरिया माना जाता है। अतः मिलान i-b, ii-a, iii-d, iv-c है।"},{"id":"c23s1-48","p":"c23s1","n":48,"s":"ih","t":"Modern India","q":"Ryotwari system of revenue collection in India, introduced by the British, was based on the _______.","w":"The Ryotwari system, begun by Alexander Read and Thomas Munro in Baramahal (1792), extended over Madras Presidency from 1820 and later to Bombay, settled revenue directly with each cultivator (ryot) without intermediaries. It was justified by David Ricardo's theory of rent (1817), popularised by Utilitarians such as James Mill: the state, as the ultimate landlord, could claim the \"rent\", the surplus left after the costs of cultivation and normal profit. R.K. Pringle's Bombay survey of the 1820s explicitly tried to assess this net produce field by field.","o":["Smith’s theory of rent","Ricardian theory of rent","Malthusian theory of rent","Marx’s theory of rent"],"a":[1],"qt":"भारत में अंग्रेजों द्वारा शुरू की गई राजस्व संग्रह की रैयतवाड़ी व्यवस्था _______ पर आधारित थी।","ot":["स्मिथ के लगान सिद्धांत (Smith’s theory of rent)","रिकार्ड के लगान सिद्धांत (Ricardian theory of rent)","माल्थस के लगान सिद्धांत (Malthusian theory of rent)","मार्क्स के लगान सिद्धांत (Marx’s theory of rent)"],"wt":"रैयतवाड़ी व्यवस्था, जो अलेक्ज़ेंडर रीड और थॉमस मुनरो ने बारामहल में (1792) शुरू की, 1820 से पूरे मद्रास प्रेसीडेंसी में और बाद में बंबई में फैली, बिना बिचौलियों के प्रत्येक कृषक (रैयत) से सीधे राजस्व तय करती थी। इसका औचित्य डेविड रिकार्डो के लगान सिद्धांत (1817) से दिया गया, जिसे जेम्स मिल जैसे उपयोगितावादियों ने लोकप्रिय बनाया: राज्य, अंतिम भूस्वामी के रूप में, 'लगान' का दावा कर सकता था, यानी खेती की लागत और सामान्य लाभ के बाद बचा अधिशेष। आर.के. प्रिंगल के 1820 के दशक के बंबई सर्वेक्षण ने स्पष्ट रूप से प्रत्येक खेत की इसी शुद्ध उपज का आकलन करने का प्रयास किया।"},{"id":"c23s1-49","p":"c23s1","n":49,"s":"sci","t":"Chemistry","q":"Who received the Nobel Prize in 1901 for ‘recognition of the extraordinary services rendered by the discovery of the laws of chemical dynamics and osmotic pressure in solutions’?","w":"The Dutch chemist Jacobus Henricus van 't Hoff received the first Nobel Prize in Chemistry (1901) \"in recognition of the extraordinary services he has rendered by the discovery of the laws of chemical dynamics and osmotic pressure in solutions\". His osmotic pressure equation, π = iCRT (with the van 't Hoff factor i), is studied under colligative properties. The other options won soon after: Emil Fischer (1902, sugar and purine syntheses), Svante Arrhenius (1903, electrolytic dissociation) and Henri Moissan (1906, isolation of fluorine).","o":["Hermann Emil Fischer","Jacobus Henricus van 't Hoff","Svante August Arrhenius","Henri Moissan"],"a":[1],"qt":"1901 में 'विलयनों में रासायनिक गतिकी और परासरणी दाब के नियमों की खोज द्वारा प्रदान की गई असाधारण सेवाओं की पहचान' के लिए नोबेल पुरस्कार किसे दिया गया था?","ot":["हरमन एमिल फिशर (Hermann Emil Fischer)","जैकब्स हेनरिक्स वैन'टी हॉफ (Jacobus Henricus van 't Hoff)","स्वांते ऑगस्ट अरहेनियस (Svante August Arrhenius)","हेनरी मोइसान (Henri Moissan)"],"wt":"डच रसायनज्ञ जैकोबस हेनरिकस वैन 'ट हॉफ को 1901 में पहला रसायन नोबेल पुरस्कार 'विलयनों में रासायनिक गतिकी और परासरण दाब के नियमों की खोज द्वारा प्रदान की गई असाधारण सेवाओं की मान्यता में' मिला। उनका परासरण दाब समीकरण, π = iCRT (वान्ट हॉफ गुणांक i के साथ), अणुसंख्य गुणधर्मों के अंतर्गत पढ़ा जाता है। अन्य विकल्पों को इसके कुछ ही बाद पुरस्कार मिला: एमिल फिशर (1902, शर्करा और प्यूरीन संश्लेषण), स्वांते अरहेनियस (1903, विद्युत-अपघटनी वियोजन) और हेनरी मोइसान (1906, फ्लोरीन का पृथक्करण)।"},{"id":"c23s1-50","p":"c23s1","n":50,"s":"pol","t":"Constitution & Rights","q":"Which of the following Articles of the Indian Constitution are related to citizenship?","w":"Part II of the Constitution, Articles 5 to 11, deals with citizenship: it identifies who became citizens at the commencement of the Constitution, including migrants from and to Pakistan (Articles 6 and 7) and persons of Indian origin living abroad (Article 8), denies citizenship to those who voluntarily acquire a foreign one (Article 9), and lets Parliament regulate citizenship by law (Article 11), under which the Citizenship Act, 1955 was passed. Articles 2 to 4 concern new states, while 15 to 21 and 25 to 31 are Fundamental Rights in Part III.","o":["Articles 15 to 21","Articles 5 to 11","Articles 2 to 4","Articles 25 to 31"],"a":[1],"qt":"भारतीय संविधान के निम्नलिखित में से कौन-से अनुच्छेद नागरिकता से संबंधित हैं?","ot":["अनुच्छेद 15 से 21","अनुच्छेद 5 से 11","अनुच्छेद 2 से 4","अनुच्छेद 25 से 31"],"wt":"संविधान का भाग II, अनुच्छेद 5 से 11, नागरिकता से संबंधित है: यह बताता है कि संविधान के प्रारंभ पर कौन नागरिक बने, जिनमें पाकिस्तान से और पाकिस्तान को प्रवास करने वाले (अनुच्छेद 6 और 7) तथा विदेश में रहने वाले भारतीय मूल के व्यक्ति (अनुच्छेद 8) शामिल हैं; स्वेच्छा से विदेशी नागरिकता लेने वालों को नागरिकता से वंचित करता है (अनुच्छेद 9); और संसद को कानून द्वारा नागरिकता का विनियमन करने की शक्ति देता है (अनुच्छेद 11), जिसके अंतर्गत नागरिकता अधिनियम, 1955 पारित हुआ। अनुच्छेद 2 से 4 नए राज्यों से संबंधित हैं, जबकि 15 से 21 और 25 से 31 भाग III के मौलिक अधिकार हैं।"},{"id":"c23s1-51","p":"c23s1","n":51,"s":"qa","t":"Percentage, Profit & Interest","q":"If A is 95% of B, then what per cent of A is B?","w":"Take B = 100, so A = 95. B as a percentage of A = 100/95 × 100 = 2000/19 = 105 5/19%. Check: 105 5/19% of 95 = (2000/19) × 95/100 = 100 = B. The base of the new percentage is A (95), not B, so B exceeds A by 5/95 × 100 = 5 5/19%, not by 5%. Simply reversing \"95%\" into 105% is the usual trap.","o":["110 3/19%","104 7/19%","108 17/19%","105 5/19%"],"a":[3],"qt":"यदि A, B का 95% है, तो A का कितना प्रतिशत B है?","ot":["110 3/19%","104 7/19%","108 17/19%","105 5/19%"],"wt":"B = 100 मानें, तो A = 95। A के प्रतिशत के रूप में B = 100/95 × 100 = 2000/19 = 105 5/19%। जाँच: 95 का 105 5/19% = (2000/19) × 95/100 = 100 = B। नए प्रतिशत का आधार A (95) है, B नहीं, इसलिए B, A से 5/95 × 100 = 5 5/19% अधिक है, 5% नहीं। \"95%\" को उलटकर सीधे 105% मान लेना सामान्य भूल है।"},{"id":"c23s1-52","p":"c23s1","n":52,"s":"qa","t":"Percentage, Profit & Interest","q":"The marked price of mustard oil is 25% more than its cost price. At what percentage less than the marked price should it be sold to have no profit and no loss?","w":"Let CP = 100, so MP = 125. For no profit and no loss the selling price must equal the cost price, 100, so the reduction is 125 − 100 = 25 on a marked price of 125. Discount % = 25/125 × 100 = 20%. Shortcut: an increase of r% is cancelled by a decrease of r/(100 + r) × 100 = 25/125 × 100 = 20%. A 25% discount would cause a loss, because the base is now the larger marked price.","o":["15%","20%","18%","22%"],"a":[1],"qt":"सरसों के तेल का अंकित मूल्य उसके क्रय मूल्य से 25% अधिक है। यदि इसे बिना किसी लाभ या हानि के बेचा जाना है, तो इसे अंकित मूल्य से कितने प्रतिशत कम पर बेचा जाना चाहिए?","ot":["15%","20%","18%","22%"],"wt":"क्रय मूल्य = 100 मानें, तो अंकित मूल्य = 125। न लाभ न हानि के लिए विक्रय मूल्य, क्रय मूल्य 100 के बराबर होना चाहिए, अतः 125 के अंकित मूल्य पर कमी = 125 − 100 = 25। छूट % = 25/125 × 100 = 20%। शॉर्टकट: r% की वृद्धि को r/(100 + r) × 100 = 25/125 × 100 = 20% की कमी निरस्त करती है। 25% छूट देने पर हानि होगी, क्योंकि अब आधार बड़ा अंकित मूल्य है।"},{"id":"c23s1-53","p":"c23s1","n":53,"s":"qa","t":"Time, Work, Speed & Distance","q":"A can complete a piece of work in 25 days while B can complete the same work in 30 days. They work on alternate basis, starting with A. Both A and B follow this pattern for 5 days and then A leaves the work. In how many days will B finish the remaining work?","w":"Take total work = LCM(25, 30) = 150 units: A does 6 units a day and B 5 units a day. In the first 5 days the order is A, B, A, B, A, so A works 3 days and B 2 days: 3 × 6 + 2 × 5 = 28 units. Remaining work = 150 − 28 = 122 units, which B alone finishes in 122/5 = 24 2/5 days. The 5-day options forget that B still has most of the work left.","o":["24 2/5","5 2/5","5 3/5","24 3/5"],"a":[0],"qt":"A एक काम को 25 दिन में पूरा कर सकता है जबकि B उसी काम को 30 दिन में पूरा कर सकता है। वे एकांतर दिन के आधार पर काम करते हैं, A से शुरू करते हैं। A और B दोनों 5 दिन के लिए इस तरीके का पालन करते हैं और फिर A काम छोड़ देता है। B शेष कार्य को कितने दिन में पूरा करेगा?","ot":["24 2/5","5 2/5","5 3/5","24 3/5"],"wt":"कुल कार्य = LCM(25, 30) = 150 इकाई लें: A प्रतिदिन 6 इकाई और B प्रतिदिन 5 इकाई कार्य करता है। पहले 5 दिनों में क्रम A, B, A, B, A है, अतः A 3 दिन और B 2 दिन काम करता है: 3 × 6 + 2 × 5 = 28 इकाई। शेष कार्य = 150 − 28 = 122 इकाई, जिसे B अकेला 122/5 = 24 2/5 दिन में पूरा करता है। 5 दिन वाले विकल्प यह भूल जाते हैं कि अधिकांश कार्य अभी B के लिए शेष है।"},{"id":"c23s1-54","p":"c23s1","n":54,"s":"qa","t":"Time, Work, Speed & Distance","q":"As part of his journey, a person travels 120 km at 80 km/h, the next 100 km at 40 km/h, and comes back to the starting point at 75 km/h. The average speed of the person throughout the journey (approximately) is:","w":"Average speed = total distance ÷ total time. Going out he covers 120 + 100 = 220 km and comes back the same 220 km, so the distance is 440 km. Time = 120/80 + 100/40 + 220/75 = 1.5 + 2.5 + 2.933 = 6.933 h (exactly 104/15 h). Average speed = 440 ÷ 104/15 = 6600/104 ≈ 63.46 km/h. Averaging the three speeds is wrong because different times are spent at each speed.","o":["63.46 km/h","58.74 km/h","68.15 km/h","49.58 km/h"],"a":[0],"qt":"अपनी यात्रा के एक भाग के रूप में, एक व्यक्ति 80 km/h की चाल से 120 km की यात्रा करता है, अगले 100 km की यात्रा 40 km/h की चाल से करता है, और 75 km/h की चाल से प्रारंभिक स्थान पर वापस आता है। पूरी यात्रा में व्यक्ति की औसत चाल (लगभग) ______ है।","ot":["63.46 km/h","58.74 km/h","68.15 km/h","49.58 km/h"],"wt":"औसत चाल = कुल दूरी ÷ कुल समय। जाते समय वह 120 + 100 = 220 km चलता है और लौटते समय भी वही 220 km, अतः कुल दूरी 440 km है। समय = 120/80 + 100/40 + 220/75 = 1.5 + 2.5 + 2.933 = 6.933 घंटे (ठीक 104/15 घंटे)। औसत चाल = 440 ÷ 104/15 = 6600/104 ≈ 63.46 km/h। तीनों चालों का सीधा औसत लेना गलत है, क्योंकि प्रत्येक चाल पर अलग-अलग समय लगता है।"},{"id":"c23s1-55","p":"c23s1","n":55,"s":"qa","t":"Time, Work, Speed & Distance","q":"8 men can complete a work in 45 days. 8 women can complete the same work in 18 days. In how many days will 5 men and 8 women, together, complete the same work?","w":"Total work = 8 × 45 = 360 man-days, so one man does 1/360 of the work a day; likewise 8 × 18 = 144 woman-days, so one woman does 1/144 a day. Together 5 men and 8 women do 5/360 + 8/144 = 1/72 + 4/72 = 5/72 of the work a day. Time = 72/5 = 14 2/5 days. Sense check: 8 women alone need 18 days, so adding 5 men must bring the time below 18 days.","o":["13 1/5","12 4/5","14 2/5","15 3/5"],"a":[2],"qt":"8 पुरुष एक कार्य को 45 दिन में पूरा कर सकते हैं। 8 महिलाएं उसी कार्य को 18 दिन में पूरा कर सकती हैं। 5 पुरुष और 8 महिलाएं मिलकर उसी कार्य को कितने दिन में पूरा करेंगे?","ot":["13 1/5","12 4/5","14 2/5","15 3/5"],"wt":"कुल कार्य = 8 × 45 = 360 पुरुष-दिवस, अतः एक पुरुष प्रतिदिन कार्य का 1/360 भाग करता है; इसी प्रकार 8 × 18 = 144 महिला-दिवस, अतः एक महिला प्रतिदिन 1/144 भाग करती है। 5 पुरुष और 8 महिलाएं मिलकर प्रतिदिन 5/360 + 8/144 = 1/72 + 4/72 = 5/72 भाग करते हैं। समय = 72/5 = 14 2/5 दिन। जाँच: केवल 8 महिलाओं को 18 दिन लगते हैं, अतः 5 पुरुष जुड़ने पर समय 18 दिन से कम होना चाहिए।"},{"id":"c23s1-56","p":"c23s1","n":56,"s":"qa","t":"Number System & Simplification","q":"6²⁵ + 6²⁶ + 6²⁷ + 6²⁸ is divisible by:","w":"Take out the smallest power: 6²⁵ + 6²⁶ + 6²⁷ + 6²⁸ = 6²⁵(1 + 6 + 6² + 6³) = 6²⁵(1 + 6 + 36 + 216) = 6²⁵ × 259, so the sum is divisible by 259, the intended answer. Strictly, 6²⁵ = 2²⁵ × 3²⁵ also contains 2⁸ = 256, so 256 divides the sum as well, while 254 and 255 do not. The question therefore has two correct options and SSC keyed 259. (SSC key; some sources differ.)","o":["256","254","255","259"],"a":[3],"qt":"6²⁵ + 6²⁶ + 6²⁷ + 6²⁸ निम्न से किस संख्या से विभाज्य है?","ot":["256","254","255","259"],"wt":"सबसे छोटी घात को बाहर निकालें: 6²⁵ + 6²⁶ + 6²⁷ + 6²⁸ = 6²⁵(1 + 6 + 6² + 6³) = 6²⁵(1 + 6 + 36 + 216) = 6²⁵ × 259, अतः योग 259 से विभाज्य है, जो अपेक्षित उत्तर है। वस्तुतः 6²⁵ = 2²⁵ × 3²⁵ में 2⁸ = 256 भी समाहित है, इसलिए योग 256 से भी विभाज्य है, जबकि 254 और 255 से नहीं। अतः प्रश्न के दो विकल्प सही हैं और SSC ने 259 को उत्तर माना है। (SSC कुंजी; कुछ स्रोत भिन्न हैं।)"},{"id":"c23s1-57","p":"c23s1","n":57,"s":"qa","t":"Data Interpretation & Statistics","q":"Study the given table and answer the question that follows.\nThe table shows the classification of 100 students based on the marks obtained by them in History and Geography in an examination.\nMarks out of 50\nSubject | 40 and above | 30 and above | 20 and above | 10 and above | 0 and above\nHistory | 9 | 32 | 80 | 92 | 100\nGeography | 4 | 21 | 66 | 81 | 100\nAverage (Aggregate) | 7 | 27 | 73 | 87 | 100\nBased on the table, what is the number of students scoring less than 20% marks in aggregate?","w":"The marks are out of 50, so 20% marks = 20% of 50 = 10 marks. The table is cumulative: in the Average (Aggregate) row, 87 students scored 10 and above, and all 100 scored 0 and above. So the students scoring less than 10 marks (less than 20%) in aggregate = 100 − 87 = 13. Reading the History row (100 − 92 = 8) or the Geography row (100 − 81 = 19) answers a different question.","o":["13","11","10","12"],"a":[0],"qt":"निम्नांकित तालिका का अध्ययन करें और नीचे दिए गए प्रश्न का उत्तर दें।\nयह तालिका एक परीक्षा में इतिहास और भूगोल में छात्रों को प्राप्त अंकों के आधार पर 100 छात्रों का वर्गीकरण दर्शाती है।\n50 में से अंक\nविषय | 40 और उससे अधिक | 30 और उससे अधिक | 20 और उससे अधिक | 10 और उससे अधिक | 0 और उससे अधिक\nइतिहास | 9 | 32 | 80 | 92 | 100\nभूगोल | 4 | 21 | 66 | 81 | 100\nऔसत (कुल) | 7 | 27 | 73 | 87 | 100\nतालिका के आधार पर कुल 20% से कम अंक प्राप्त करने वाले छात्रों की कुल संख्या कितनी है?","ot":["13","11","10","12"],"wt":"अंक 50 में से हैं, अतः 20% अंक = 50 का 20% = 10 अंक। तालिका संचयी है: औसत (कुल) वाली पंक्ति में 87 छात्रों ने 10 और उससे अधिक अंक प्राप्त किए, और सभी 100 छात्रों ने 0 और उससे अधिक। अतः कुल में 10 से कम (20% से कम) अंक पाने वाले छात्र = 100 − 87 = 13। इतिहास की पंक्ति (100 − 92 = 8) या भूगोल की पंक्ति (100 − 81 = 19) पढ़ना किसी दूसरे प्रश्न का उत्तर है।"},{"id":"c23s1-58","p":"c23s1","n":58,"s":"qa","t":"Geometry","q":"Two concentric circles are of radii 10 cm and 6 cm. Find the length of the chord of the larger circle which touches the smaller circle.","w":"The chord touches the smaller circle, so it is a tangent to it: the smaller radius (6 cm) meets the chord at right angles at its midpoint. In the right triangle formed by the centre, this midpoint and one end of the chord, the hypotenuse is the larger radius, 10 cm. Half-chord = √(10² − 6²) = √64 = 8 cm, so the chord = 2 × 8 = 16 cm. 8 cm is only half the chord.","o":["8 cm","16 cm","12 cm","9 cm"],"a":[1],"qt":"दो संकेंद्रित वृत्तों की त्रिज्याएँ 10 cm और 6 cm हैं। बड़े वृत्त की उस जीवा की लंबाई ज्ञात कीजिए जो छोटे वृत्त को स्पर्श करती है।","ot":["8 cm","16 cm","12 cm","9 cm"],"wt":"जीवा छोटे वृत्त को स्पर्श करती है, अतः वह छोटे वृत्त की स्पर्श रेखा है: छोटी त्रिज्या (6 cm) जीवा से उसके मध्य-बिंदु पर समकोण बनाती है। केंद्र, इस मध्य-बिंदु और जीवा के एक सिरे से बने समकोण त्रिभुज का कर्ण बड़ी त्रिज्या 10 cm है। आधी जीवा = √(10² − 6²) = √64 = 8 cm, अतः जीवा = 2 × 8 = 16 cm। 8 cm केवल आधी जीवा है।"},{"id":"c23s1-59","p":"c23s1","n":59,"s":"qa","t":"Trigonometry & Heights","q":"If sin (a + b) = 1 and cos (a − b) = 1/2, then find a.","w":"sin 90° = 1, so a + b = 90°. cos 60° = 1/2, so a − b = 60° (taking acute angles). Adding the two equations gives 2a = 150°, so a = 75°; subtracting gives b = 15°. Check: sin (75° + 15°) = sin 90° = 1 and cos (75° − 15°) = cos 60° = 1/2. Option 15° is the value of b, not a.","o":["75°","30°","15°","45°"],"a":[0],"qt":"यदि sin (a + b) = 1 और cos (a − b) = 1/2 है, तो a का मान ज्ञात करें।","ot":["75°","30°","15°","45°"],"wt":"sin 90° = 1, अतः a + b = 90°। cos 60° = 1/2, अतः a − b = 60° (न्यून कोण लेते हुए)। दोनों समीकरणों को जोड़ने पर 2a = 150°, अतः a = 75°; घटाने पर b = 15°। जाँच: sin (75° + 15°) = sin 90° = 1 और cos (75° − 15°) = cos 60° = 1/2। विकल्प 15° का मान b है, a नहीं।"},{"id":"c23s1-60","p":"c23s1","n":60,"s":"qa","t":"Time, Work, Speed & Distance","q":"A train 900 m long is running at 108 km/h. How long will it take to clear a 900 m long platform completely?","w":"To clear a platform completely the train must cover its own length plus the platform's length: 900 + 900 = 1800 m. Speed = 108 km/h = 108 × 5/18 = 30 m/s. Time = 1800/30 = 60 s. Using only one length (900/30 = 30 s) is the common mistake; that is only the time for the engine to reach the far end of the platform.","o":["60 s","45 s","30 s","18 s"],"a":[0],"qt":"900 m लंबी एक ट्रेन 108 km/h की चाल से चल रही है। 900 m लंबे प्लेटफॉर्म को पूरी तरह से पार करने में इस ट्रेन को कितना समय लगेगा?","ot":["60 s","45 s","30 s","18 s"],"wt":"प्लेटफॉर्म को पूरी तरह पार करने के लिए ट्रेन को अपनी लंबाई और प्लेटफॉर्म की लंबाई का योग तय करना होता है: 900 + 900 = 1800 m। चाल = 108 km/h = 108 × 5/18 = 30 m/s। समय = 1800/30 = 60 s। केवल एक लंबाई लेना (900/30 = 30 s) सामान्य भूल है; यह केवल इंजन के प्लेटफॉर्म के दूसरे सिरे तक पहुँचने का समय है।"},{"id":"c23s1-61","p":"c23s1","n":61,"s":"qa","t":"Algebra","q":"If 7b − 1/(4b) = 7, then what is the value of 16b² + 1/(49b²)?","w":"Multiply the given equation by 4/7 to get the pair of terms needed: 4b − 1/(7b) = 4. Square both sides: 16b² − 2 × 4b × 1/(7b) + 1/(49b²) = 16, i.e. 16b² − 8/7 + 1/(49b²) = 16. So 16b² + 1/(49b²) = 16 + 8/7 = 120/7. Check: b ≈ 1.0345 satisfies 7b − 1/(4b) = 7 and gives 16b² + 1/(49b²) ≈ 17.143 = 120/7. 104/7 comes from subtracting 8/7 instead of adding it.","o":["80/49","104/7","120/7","7/2"],"a":[2],"qt":"यदि 7b − 1/(4b) = 7 है, तो 16b² + 1/(49b²) का मान ज्ञात कीजिए।","ot":["80/49","104/7","120/7","7/2"],"wt":"आवश्यक पद-युग्म पाने के लिए दिए गए समीकरण को 4/7 से गुणा करें: 4b − 1/(7b) = 4। दोनों पक्षों का वर्ग करें: 16b² − 2 × 4b × 1/(7b) + 1/(49b²) = 16, अर्थात् 16b² − 8/7 + 1/(49b²) = 16। अतः 16b² + 1/(49b²) = 16 + 8/7 = 120/7। जाँच: b ≈ 1.0345 से 7b − 1/(4b) = 7 संतुष्ट होता है और 16b² + 1/(49b²) ≈ 17.143 = 120/7 मिलता है। 8/7 को जोड़ने के बजाय घटाने से 104/7 आता है।"},{"id":"c23s1-62","p":"c23s1","n":62,"s":"qa","t":"Geometry","q":"If m∠C=m∠Z and AC=XZ, then which of the following conditions is necessary for ΔABC and ΔXYZ to be congruent?","w":"One angle and one side are already equal: ∠C = ∠Z and AC = XZ. For SAS congruence the equal angle must lie between the two pairs of equal sides. ∠C is formed by CA and CB, and ∠Z by ZX and ZY, so the second pair needed is BC = YZ; then ΔABC ≅ ΔXYZ by SAS. AB = XY would give two sides and a non-included angle (SSA), which does not guarantee congruence, and AB = AC or BC = AB concern only one triangle.","o":["AB=AC","BC=YZ","AB=XY","BC=AB"],"a":[1],"qt":"यदि m∠C=m∠Z और AC=XZ है, तो ΔABC और ΔXYZ के सर्वांगसम होने के लिए निम्नलिखित में से कौन सी शर्तें आवश्यक हैं?","ot":["AB=AC","BC=YZ","AB=XY","BC=AB"],"wt":"एक कोण और एक भुजा पहले से बराबर हैं: ∠C = ∠Z और AC = XZ। SAS सर्वांगसमता के लिए बराबर कोण दोनों बराबर भुजा-युग्मों के बीच होना चाहिए। ∠C भुजाओं CA और CB से बनता है, और ∠Z भुजाओं ZX और ZY से, अतः दूसरा आवश्यक युग्म BC = YZ है; तब SAS से ΔABC ≅ ΔXYZ। AB = XY से दो भुजाएँ और एक गैर-अंतर्गत कोण (SSA) मिलते हैं, जो सर्वांगसमता सुनिश्चित नहीं करते, और AB = AC या BC = AB केवल एक ही त्रिभुज से संबंधित हैं।"},{"id":"c23s1-63","p":"c23s1","n":63,"s":"qa","t":"Geometry","q":"In the given figure, PAB is a secant and PT is a tangent to the circle from P. If PT = 8 cm, PA = 6 cm and AB = x cm, then the value of x is:","w":"By the tangent–secant theorem, the square of the tangent from an external point equals the product of the whole secant and its external part: PT² = PA × PB. Here PB = PA + AB = 6 + x, so 8² = 6(6 + x), i.e. 64 = 36 + 6x, which gives 6x = 28 and x = 14/3 cm. Check: 6 × (6 + 14/3) = 6 × 32/3 = 64 = 8². Using PT² = PA × AB would wrongly give 32/3.","img":"data:image/png;base64,","o":["14/9","1/3","14/3","4/3"],"a":[2],"qt":"दी गई आकृति में, PAB एक छेदक (सीकेंट) है और PT, P से वृत्त की स्पर्श रेखा है। यदि PT = 8 cm, PA = 6 cm और AB = x cm है, तो x का मान ज्ञात कीजिए।","ot":["14/9","1/3","14/3","4/3"],"wt":"स्पर्श रेखा-छेदक प्रमेय के अनुसार बाहरी बिंदु से खींची गई स्पर्श रेखा का वर्ग, पूरे छेदक और उसके बाहरी भाग के गुणनफल के बराबर होता है: PT² = PA × PB। यहाँ PB = PA + AB = 6 + x, अतः 8² = 6(6 + x), अर्थात् 64 = 36 + 6x, जिससे 6x = 28 और x = 14/3 cm। जाँच: 6 × (6 + 14/3) = 6 × 32/3 = 64 = 8²। PT² = PA × AB लेने पर गलत उत्तर 32/3 आएगा।"},{"id":"c23s1-64","p":"c23s1","n":64,"s":"qa","t":"Percentage, Profit & Interest","q":"A shopkeeper offers the following two discount schemes.\nA) Buy 3 get 4 free\nB) Buy 5 get 6 free\nWhich scheme has the maximum discount percentage?","w":"In \"buy x get y free\" the customer pays for x items but receives x + y, so the discount % = y/(x + y) × 100. Scheme A: pay for 3, get 7, discount = 4/7 × 100 ≈ 57.14%. Scheme B: pay for 5, get 11, discount = 6/11 × 100 ≈ 54.55%. So scheme A gives the bigger discount. Note that B gives more free items (6) but also needs more items to be bought, so its percentage is lower.","o":["A","A does not give any discount","A and B both have the same discount percentage","B"],"a":[0],"qt":"एक दुकानदार नीचे दी गई दो छूट संबंधी योजनाओं की पेशकश करता है।\nA) 3 वस्तुओं की खरीद पर 4 वस्तु मुफ्त पाएं।\nB) 5 वस्तुओं की खरीद पर 6 वस्तु मुफ्त पाएं।\nकिस योजना में छूट प्रतिशत अधिकतम है?","ot":["A","योजना A में कोई छूट नहीं दी गई है","A और B दोनों योजनाओं में छूट प्रतिशत समान है","B"],"wt":"\"x खरीदें, y मुफ्त पाएं\" में ग्राहक x वस्तुओं का मूल्य चुकाता है पर x + y वस्तुएँ पाता है, अतः छूट % = y/(x + y) × 100। योजना A: 3 का मूल्य, 7 वस्तुएँ, छूट = 4/7 × 100 ≈ 57.14%। योजना B: 5 का मूल्य, 11 वस्तुएँ, छूट = 6/11 × 100 ≈ 54.55%। अतः योजना A में छूट अधिक है। ध्यान दें कि B में मुफ्त वस्तुएँ (6) अधिक हैं, पर खरीदनी भी अधिक पड़ती हैं, इसलिए उसका प्रतिशत कम है।"},{"id":"c23s1-65","p":"c23s1","n":65,"s":"qa","t":"Data Interpretation & Statistics","q":"The following bar chart represents the gross amount (in ₹ lakhs) and total cost (in ₹ lakhs) of a firm.\nIn order to make a profit of 25%, what should the gross amount have been (in ₹ [rest of the question cut off on the SSC sheet; editorial completion from the Hindi version: crores) in 2019-2020?]","w":"The end of the question is cut off on SSC's sheet; the bracketed words complete it. In the chart the hatched bars (\"Total\") show the total cost and the plain bars the gross amount. Profit is reckoned on cost, so for a 25% profit the gross amount must be 125% of the total cost. In 2019-20 the total cost is 6500, so the required gross amount = 6500 × 125/100 = 8125. The actual gross amount that year was 7500, a profit of only about 15.4%; 7800 would give 20%.","img":"data:image/png;base64,","o":["7800","8000","8250","8125"],"a":[3],"qt":"निम्नलिखित बार चार्ट एक फर्म की सकल राशि (₹ लाख में) और कुल लागत (₹ लाख में) दर्शाता है।\nRupees in crores - रूपए करोड़ में Total - कुल Gross amount-सकल राशि\n25% का लाभ अर्जित करने के लिए, 2019-2020 में सकल राशि (₹ करोड़ में) [प्रश्न का शेष भाग SSC की शीट पर कटा हुआ है; संपादकीय पूर्ति: कितनी होनी चाहिए थी?]","ot":["7800","8000","8250","8125"],"wt":"SSC की शीट पर प्रश्न का अंतिम भाग कटा हुआ है; कोष्ठक के शब्द उसे पूरा करते हैं। चार्ट में धारीदार स्तंभ (\"Total\") कुल लागत और सादे स्तंभ सकल राशि दर्शाते हैं। लाभ लागत पर गिना जाता है, अतः 25% लाभ के लिए सकल राशि कुल लागत का 125% होनी चाहिए। 2019-20 में कुल लागत 6500 है, अतः आवश्यक सकल राशि = 6500 × 125/100 = 8125। उस वर्ष वास्तविक सकल राशि 7500 थी, यानी लाभ केवल लगभग 15.4%; 7800 से 20% लाभ होगा।"},{"id":"c23s1-66","p":"c23s1","n":66,"s":"qa","t":"Percentage, Profit & Interest","q":"In what time will ₹10,000 at 4% per annum, produce the same interest as ₹8,000 does in 4 years at 5% simple interest?","w":"Simple interest = P × R × T/100. Interest on ₹8,000 at 5% for 4 years = 8000 × 5 × 4/100 = ₹1,600. ₹10,000 at 4% per annum earns 10000 × 4/100 = ₹400 a year, so the time needed = 1600/400 = 4 years. Shortcut: P₁R₁T₁ = P₂R₂T₂ gives 10000 × 4 × T = 8000 × 5 × 4, so T = 160000/40000 = 4 years.","o":["5 years","3 years","4 years","6 years"],"a":[2],"qt":"कितने समय में 4% वार्षिक दर से ₹10,000 पर उतना ही ब्याज प्राप्त होगा, जितना 5% साधारण ब्याज दर पर 4 वर्ष में ₹8,000 पर प्राप्त होता है?","ot":["5 वर्ष","3 वर्ष","4 वर्ष","6 वर्ष"],"wt":"साधारण ब्याज = P × R × T/100। ₹8,000 पर 5% की दर से 4 वर्ष का ब्याज = 8000 × 5 × 4/100 = ₹1,600। ₹10,000 पर 4% वार्षिक दर से प्रति वर्ष 10000 × 4/100 = ₹400 ब्याज मिलता है, अतः आवश्यक समय = 1600/400 = 4 वर्ष। शॉर्टकट: P₁R₁T₁ = P₂R₂T₂ से 10000 × 4 × T = 8000 × 5 × 4, अतः T = 160000/40000 = 4 वर्ष।"},{"id":"c23s1-67","p":"c23s1","n":67,"s":"qa","t":"Time, Work, Speed & Distance","q":"A man, a boy and a woman can finish a work in 10 days, 15 days and 30 days, respectively. In how many days can the work be finished by a man, a woman and a boy when all of them work together?","w":"One day's work: man 1/10, boy 1/15, woman 1/30. Together they do 1/10 + 1/15 + 1/30 = (3 + 2 + 1)/30 = 6/30 = 1/5 of the work a day, so they finish it in 5 days. With LCM units: total work = 30 units, combined rate = 3 + 2 + 1 = 6 units a day, time = 30/6 = 5 days. The answer must be less than 10 days, the time of the fastest worker alone.","o":["10","5","8","6"],"a":[1],"qt":"एक पुरुष, एक लड़का और एक महिला किसी कार्य को क्रमशः 10 दिन, 15 दिन और 30 दिन में पूरा कर सकते हैं। मिलकर कार्य करने पर एक पुरुष, एक महिला और एक लड़का उस कार्य को कितने दिनों में पूरा कर सकते हैं?","ot":["10","5","8","6"],"wt":"एक दिन का कार्य: पुरुष 1/10, लड़का 1/15, महिला 1/30। तीनों मिलकर प्रतिदिन 1/10 + 1/15 + 1/30 = (3 + 2 + 1)/30 = 6/30 = 1/5 भाग कार्य करते हैं, अतः वे इसे 5 दिन में पूरा करते हैं। LCM इकाइयों से: कुल कार्य = 30 इकाई, संयुक्त दर = 3 + 2 + 1 = 6 इकाई प्रतिदिन, समय = 30/6 = 5 दिन। उत्तर 10 दिन से कम होना चाहिए, जो अकेले सबसे तेज़ कार्यकर्ता का समय है।"},{"id":"c23s1-68","p":"c23s1","n":68,"s":"qa","t":"Trigonometry & Heights","q":"If cos θ = √3/2, then tan²θ cos²θ =?","w":"Since tan θ = sin θ/cos θ, tan²θ cos²θ = sin²θ. With cos θ = √3/2, sin²θ = 1 − cos²θ = 1 − 3/4 = 1/4. Equivalently θ = 30°, and tan²30° × cos²30° = 1/3 × 3/4 = 1/4. Option 1/2 is sin θ itself, not sin²θ, and 1/√3 is tan 30°.","o":["1/√3","1/4","1/2","√3"],"a":[1],"qt":"यदि cos θ = √3/2 है, तो tan²θ cos²θ = ?","ot":["1/√3","1/4","1/2","√3"],"wt":"चूँकि tan θ = sin θ/cos θ, इसलिए tan²θ cos²θ = sin²θ। cos θ = √3/2 होने पर sin²θ = 1 − cos²θ = 1 − 3/4 = 1/4। दूसरे ढंग से θ = 30°, और tan²30° × cos²30° = 1/3 × 3/4 = 1/4। विकल्प 1/2 स्वयं sin θ है, sin²θ नहीं, और 1/√3, tan 30° है।"},{"id":"c23s1-69","p":"c23s1","n":69,"s":"qa","t":"Algebra","q":"What is the value of (3x³ + 5x²y + 12xy² + 7y³), when x = −4 and y = −1?","w":"Substitute term by term, minding the signs: 3x³ = 3 × (−64) = −192; 5x²y = 5 × 16 × (−1) = −80; 12xy² = 12 × (−4) × 1 = −48; 7y³ = 7 × (−1) = −7. Sum = −192 − 80 − 48 − 7 = −327. Even powers of a negative number are positive (x² = 16, y² = 1) and odd powers stay negative (x³ = −64, y³ = −1).","o":["−329","−359","−361","−327"],"a":[3],"qt":"x = −4 और y = −1 होने पर (3x³ + 5x²y + 12xy² + 7y³) का मान ज्ञात कीजिए।","ot":["−329","−359","−361","−327"],"wt":"चिह्नों का ध्यान रखते हुए प्रत्येक पद में मान रखें: 3x³ = 3 × (−64) = −192; 5x²y = 5 × 16 × (−1) = −80; 12xy² = 12 × (−4) × 1 = −48; 7y³ = 7 × (−1) = −7। योग = −192 − 80 − 48 − 7 = −327। ऋणात्मक संख्या की सम घातें धनात्मक होती हैं (x² = 16, y² = 1) और विषम घातें ऋणात्मक रहती हैं (x³ = −64, y³ = −1)।"},{"id":"c23s1-70","p":"c23s1","n":70,"s":"qa","t":"Ratio, Average & Mixtures","q":"If the four numbers, 39, 117, 17 and y are in proportion, then find the value of y.","w":"Four numbers a, b, c, d are in proportion when a : b = c : d, i.e. a × d = b × c (product of extremes = product of means). So 39 : 117 = 17 : y gives 39y = 117 × 17 = 1989, and y = 1989/39 = 51. Faster: 39 : 117 = 1 : 3, so y = 3 × 17 = 51. Here y is the fourth proportional to 39, 117 and 17.","o":["49","51","57","85"],"a":[1],"qt":"यदि चार संख्याएँ, 39, 117, 17 और y समानुपात में हैं, तो y का मान ज्ञात कीजिए।","ot":["49","51","57","85"],"wt":"चार संख्याएँ a, b, c, d समानुपात में तब होती हैं जब a : b = c : d, अर्थात् a × d = b × c (बाह्य पदों का गुणनफल = मध्य पदों का गुणनफल)। अतः 39 : 117 = 17 : y से 39y = 117 × 17 = 1989, और y = 1989/39 = 51। तेज़ विधि: 39 : 117 = 1 : 3, अतः y = 3 × 17 = 51। यहाँ y, 39, 117 और 17 का चतुर्थानुपाती है।"},{"id":"c23s1-71","p":"c23s1","n":71,"s":"qa","t":"Mensuration","q":"The volume of a sphere of radius 4.2 cm is: (Use π = 22/7)","w":"Volume of a sphere = (4/3)πr³. With r = 4.2 cm, r³ = 4.2 × 4.2 × 4.2 = 17.64 × 4.2 = 74.088 cm³. Volume = 4/3 × 22/7 × 74.088 = 88 × 74.088/21 = 88 × 3.528 = 310.464 cm³. Since 4.2 = 6 × 0.7, the factor 7 cancels neatly with π = 22/7, so the answer comes out exact. The other options are close distractors, so the cube must be worked out carefully.","o":["278.234 cm³","312.725 cm³","297.824 cm³","310.464 cm³"],"a":[3],"qt":"4.2 cm त्रिज्या वाले एक गोले का आयतन ______ होता है। (π = 22/7 का प्रयोग करें)","ot":["278.234 cm³","312.725 cm³","297.824 cm³","310.464 cm³"],"wt":"गोले का आयतन = (4/3)πr³। r = 4.2 cm लेने पर r³ = 4.2 × 4.2 × 4.2 = 17.64 × 4.2 = 74.088 cm³। आयतन = 4/3 × 22/7 × 74.088 = 88 × 74.088/21 = 88 × 3.528 = 310.464 cm³। चूँकि 4.2 = 6 × 0.7, इसलिए गुणनखंड 7, π = 22/7 के साथ सरलता से कट जाता है और उत्तर ठीक-ठीक आता है। अन्य विकल्प निकटवर्ती भ्रामक मान हैं, इसलिए घन सावधानी से निकालना चाहिए।"},{"id":"c23s1-72","p":"c23s1","n":72,"s":"qa","t":"Algebra","q":"If (a + b + c) = 16, and (a² + b² + c²) = 90, find the value of (ab + bc + ca).","w":"Use the identity (a + b + c)² = a² + b² + c² + 2(ab + bc + ca). So 16² = 90 + 2(ab + bc + ca), i.e. 256 = 90 + 2(ab + bc + ca). Then 2(ab + bc + ca) = 256 − 90 = 166, and ab + bc + ca = 83. Remember to halve the difference: 166 is the value of 2(ab + bc + ca), not of ab + bc + ca.","o":["84","83","82","81"],"a":[1],"qt":"यदि (a + b + c) = 16 और (a² + b² + c²) = 90 है, तो (ab + bc + ca) का मान ज्ञात कीजिए।","ot":["84","83","82","81"],"wt":"सर्वसमिका (a + b + c)² = a² + b² + c² + 2(ab + bc + ca) का प्रयोग करें। अतः 16² = 90 + 2(ab + bc + ca), अर्थात् 256 = 90 + 2(ab + bc + ca)। तब 2(ab + bc + ca) = 256 − 90 = 166, और ab + bc + ca = 83। अंतर को आधा करना याद रखें: 166, 2(ab + bc + ca) का मान है, ab + bc + ca का नहीं।"},{"id":"c23s1-73","p":"c23s1","n":73,"s":"qa","t":"Trigonometry & Heights","q":"If {(3 sin θ − cos θ) / (cos θ + sin θ)} = 1, then the value of cot θ is:","w":"Cross-multiply: 3 sin θ − cos θ = cos θ + sin θ, so 2 sin θ = 2 cos θ, i.e. sin θ = cos θ. Hence cot θ = cos θ/sin θ = 1 (θ = 45°). Another way: divide the numerator and denominator by sin θ to get (3 − cot θ)/(cot θ + 1) = 1, so 3 − cot θ = cot θ + 1 and cot θ = 1. Check with θ = 45°: (3 − 1)/(1 + 1) = 1.","o":["3","0","1","2"],"a":[2],"qt":"{(3 sin θ − cos θ) / (cos θ + sin θ)} = 1 है, तो cot θ का मान ज्ञात कीजिए।","ot":["3","0","1","2"],"wt":"वज्र-गुणन करें: 3 sin θ − cos θ = cos θ + sin θ, अतः 2 sin θ = 2 cos θ, अर्थात् sin θ = cos θ। इसलिए cot θ = cos θ/sin θ = 1 (θ = 45°)। दूसरी विधि: अंश और हर को sin θ से भाग देने पर (3 − cot θ)/(cot θ + 1) = 1, अतः 3 − cot θ = cot θ + 1 और cot θ = 1। θ = 45° से जाँच: (3 − 1)/(1 + 1) = 1।"},{"id":"c23s1-74","p":"c23s1","n":74,"s":"qa","t":"Time, Work, Speed & Distance","q":"Two runners, Sony and Mony, start running on a circular track of length 200 m at speeds of 18 and 24 km/h, respectively, in the same direction. After how much time from the start will they meet again at the starting point?","w":"They are together at the starting point when each has completed a whole number of laps, i.e. after the LCM of their lap times. Speeds: 18 km/h = 18 × 5/18 = 5 m/s and 24 km/h = 24 × 5/18 = 20/3 m/s. Lap times: 200/5 = 40 s and 200 ÷ 20/3 = 30 s. LCM(40, 30) = 120 s. In 120 s Sony runs 3 laps and Mony 4 laps.","o":["120 sec","110 sec","100 sec","90 sec"],"a":[0],"qt":"दो धाविकाएं, सोनी और मोनी, एक ही दिशा में क्रमशः 18 और 24 km/h की चाल से 200 m लंबाई के एक वृत्ताकार ट्रैक पर दौड़ना शुरू करती हैं। आरंभ से कितने समय बाद वे फिर से शुरुआती बिंदु पर मिलेंगी?","ot":["120 sec","110 sec","100 sec","90 sec"],"wt":"दोनों प्रारंभिक बिंदु पर तब साथ होंगी जब प्रत्येक ने पूर्ण संख्या में चक्कर पूरे कर लिए हों, अर्थात् उनके एक चक्कर के समयों के LCM के बाद। चाल: 18 km/h = 18 × 5/18 = 5 m/s और 24 km/h = 24 × 5/18 = 20/3 m/s। एक चक्कर का समय: 200/5 = 40 s और 200 ÷ 20/3 = 30 s। LCM(40, 30) = 120 s। 120 s में सोनी 3 चक्कर और मोनी 4 चक्कर लगाती है।"},{"id":"c23s1-75","p":"c23s1","n":75,"s":"qa","t":"Number System & Simplification","q":"What will be the remainder when (265)⁴⁰⁸¹+9 is divided by 266?","w":"265 = 266 − 1, so 265 leaves a remainder of −1 when divided by 266. Hence 265⁴⁰⁸¹ leaves (−1)⁴⁰⁸¹ = −1, because 4081 is odd; in positive terms the remainder is 265. Then 265⁴⁰⁸¹ + 9 leaves −1 + 9 = 8 (or 265 + 9 = 274 = 266 + 8). Option 9 ignores the power, and an even power would have given 1 + 9 = 10.","o":["8","6","1","9"],"a":[0],"qt":"(265)⁴⁰⁸¹+9 को 266 से विभाजित करने पर प्राप्त शेषफल ज्ञात कीजिए।","ot":["8","6","1","9"],"wt":"265 = 266 − 1, अतः 265 को 266 से भाग देने पर शेषफल −1 है। इसलिए 265⁴⁰⁸¹ का शेषफल (−1)⁴⁰⁸¹ = −1 है, क्योंकि 4081 विषम है; धनात्मक रूप में शेषफल 265 है। तब 265⁴⁰⁸¹ + 9 का शेषफल −1 + 9 = 8 है (या 265 + 9 = 274 = 266 + 8)। विकल्प 9 घात को अनदेखा करता है, और सम घात होने पर 1 + 9 = 10 आता।"},{"id":"c23s1-76","p":"c23s1","n":76,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"The following sentence has been split into four segments. Identify the segment that contains an error.\nNeetu have been / waiting for me / since 10 o’clock / in the morning.","w":"In the present perfect continuous tense the auxiliary must agree with the subject. 'Neetu' is a singular proper noun (third person singular), so it takes 'has been', not 'have been': 'Neetu has been waiting for me since 10 o'clock in the morning.' The other segments are correct: 'since' is rightly used with a point of time (10 o'clock), and 'waiting for me' and 'in the morning' need no change.","o":["Neetu have been","in the morning","since 10 o’clock","waiting for me"],"a":[0]},{"id":"c23s1-77","p":"c23s1","n":77,"s":"eng","t":"Vocabulary","q":"Select the most appropriate ANTONYM of the underlined word.\nHer dog can climb \"under\" the fence.","w":"'Under' means in or to a position below something, so 'climb under the fence' means to get past it by going below it. Its opposite is 'over', meaning above or across the top of something: the dog could climb over the fence. 'Beneath' is a synonym of under, 'behind' means at the back of, and 'sink' is a verb meaning to go down below a surface, so none of them is the opposite.","o":["Over","Sink","Behind","Beneath"],"a":[0]},{"id":"c23s1-78","p":"c23s1","n":78,"s":"eng","t":"Spelling","q":"Select the INCORRECTLY spelt word in the given sentence.\nThe village beggars, no longer ill at ease in the gathering of gliterring dignitaries, sat in their assigned rows and joked with vegetarian Brahmin apprentices.","w":"The misspelt word is 'gliterring'; the correct spelling is 'glittering' (g-l-i-t-t-e-r-i-n-g), from the verb glitter, to shine with a bright, shimmering light. It has a double t in the middle and a single r: the stress in 'glitter' falls on the first syllable, so the final r is not doubled before -ing, as in 'offering' and 'entering'. 'Assigned', 'apprentices' and 'beggars' are spelt correctly.","o":["assigned","apprentices","beggars","gliterring"],"a":[3]},{"id":"c23s1-79","p":"c23s1","n":79,"s":"eng","t":"Voice & Narration","q":"Select the option that expresses the given sentence in passive voice.\nThe company's board of directors will announce the financial results at the annual meeting tomorrow.","w":"The active sentence is in the simple future tense (will announce). In the passive, the object 'the financial results' becomes the subject and the verb becomes will be + past participle: 'The financial results will be announced by the company's board of directors at the annual meeting tomorrow.' Option 1 uses the future perfect (will have been announced), option 2 the present continuous (are being announced), and option 3 is still in active voice and wrongly in the past tense.","o":["The financial results will have been announced by the company's board of directors at the annual meeting tomorrow.","The financial results are being announced by the company's board of directors at the annual meeting tomorrow.","The company's board of directors announced the financial results at the annual meeting tomorrow.","The financial results will be announced by the company's board of directors at the annual meeting tomorrow."],"a":[3]},{"id":"c23s1-80","p":"c23s1","n":80,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Select the grammatically correct sentence.","w":"A plural subject takes a plural verb. In 'The participants of the competition' the head noun is 'participants' (plural); the phrase 'of the competition' does not change its number. So the verb must be 'are waiting', and 'their turn' agrees with it. Option 2 uses singular 'has been' with a plural subject, option 3 puts the singular article 'A' before the plural noun 'participants', and option 4 uses singular 'is' with a plural subject.","o":["The participants of the competition are waiting for their turn curiously.","The participants of the competition has been waiting for their turn curiously.","A participants of the competition is waiting for their turn curiously.","The participants of the competition is waiting for their turn curiously."],"a":[0]},{"id":"c23s1-81","p":"c23s1","n":81,"s":"eng","t":"Vocabulary","q":"Select the most appropriate ANTONYM of the underlined word in the given sentence.\nHenry is so \"servile\" that other people take advantage of him.","w":"'Servile' means excessively eager to serve or please others, slavishly submissive and lacking self-respect, which is why people take advantage of Henry. Its opposite is 'arrogant', meaning having an exaggerated sense of one's own importance and behaving in a proud, overbearing way. 'Sheepish' means embarrassed or meek, which is close to servile, 'bickering' means quarrelling over petty things, and 'cunning' means clever in a deceitful way.","o":["Arrogant","Sheepish","Bickering","Cunning"],"a":[0]},{"id":"c23s1-82","p":"c23s1","n":82,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the option that can be used as a one-word substitute for the given group of words.\nA thing fit to eat.","w":"'Edible' means fit or safe to be eaten (Latin edere, to eat), as in 'edible mushrooms'; its opposite is inedible. 'Eligible' means qualified or entitled to be chosen, 'digestible' means easily broken down by the body (a food may be edible yet hard to digest), and 'curable' means able to be cured. So a thing fit to eat is edible.","o":["Eligible","Digestible","Curable","Edible"],"a":[3]},{"id":"c23s1-83","p":"c23s1","n":83,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the most appropriate meaning of the given idiom.\nLily-livered","w":"'Lily-livered' means cowardly, lacking courage. The expression comes from the old belief that the liver was the seat of courage: a pale, bloodless liver, white as a lily, was thought to show a lack of courage. So the meaning is 'not brave'. 'Brave' is the exact opposite, while 'comical' (funny) and 'naughty' (badly behaved) are unrelated. Similar expressions are chicken-hearted and faint-hearted.","o":["Brave","Comical","Not brave","Naughty"],"a":[2]},{"id":"c23s1-84","p":"c23s1","n":84,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nZealous","w":"'Zealous' means full of zeal, that is, showing great energy and enthusiasm in pursuit of a cause or objective, as in 'a zealous supporter of reform'. Its synonym is 'enthusiastic'. 'Detached', 'apathetic' and 'indifferent' all mean showing little or no interest or concern, so they are opposites of zealous rather than synonyms.","o":["Enthusiastic","Detached","Apathetic","Indifferent"],"a":[0]},{"id":"c23s1-85","p":"c23s1","n":85,"s":"eng","t":"Vocabulary","q":"Select the most appropriate option that can substitute the underlined word in the given sentence.\nShe had an ability to \"persuade\" others.","w":"To 'persuade' is to make someone believe or do something by reasoning or appeal. None of the options is an exact synonym, but 'impress' comes closest: to impress others is to influence them by winning their admiration and respect, and to impress an idea on someone is to fix it firmly in their mind. 'Halt' means to stop, 'suppress' means to put down by force or hold back, and 'outrage' means to make very angry, none of which carries the sense of influencing others.","o":["halt","suppress","outrage","impress"],"a":[3]},{"id":"c23s1-86","p":"c23s1","n":86,"s":"eng","t":"Vocabulary","q":"Select the most appropriate option that can substitute the underlined segment in the given sentence.\nWe must remember that what we teach our children is what we \"inculcate\" in them.","w":"To 'inculcate' is to fix an idea, attitude or habit in someone's mind by persistent instruction or repetition, as parents and teachers do with children. Its exact substitute is 'instil' (instill in American English), meaning to establish an idea or feeling gradually but firmly in a person's mind. 'Inspire' means to fill someone with the urge or ability to do something, 'endanger' means to put at risk, and 'import' means to bring goods in from another country.","o":["endanger","inspire","instil","import"],"a":[2]},{"id":"c23s1-87","p":"c23s1","n":87,"s":"eng","t":"Voice & Narration","q":"Select the option that expresses the given sentence in passive voice.\nHe won’t receive any better choice than this from anywhere.","w":"The active sentence is a negative in the simple future (won't = will not + receive) with the object 'any better choice'. In the passive the object becomes the subject and the verb becomes will not be + past participle: 'Any better choice won't be received by him than this from anywhere.' Option 2 uses 'wouldn't have received', which lacks 'been' and is not passive, option 3 changes the modal to 'shouldn't', and option 4 has the ungrammatical 'have been be received'.","o":["Any better choice won’t be received by him than this from anywhere.","Any better choice wouldn’t have received by him than this from anywhere.","Any better choice shouldn’t be received by him than this from anywhere.","Any better choice won’t have been be received by him than this from anywhere."],"a":[0]},{"id":"c23s1-88","p":"c23s1","n":88,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nFeeble","w":"'Feeble' means lacking physical strength, especially through age or illness, or lacking force and effectiveness, as in 'a feeble excuse'. Its synonym is 'weak'. 'Strong' is its opposite, 'unheedful' means careless or not paying attention (heedless), and 'baneful' means harmful or destructive, so neither of the last two is related in meaning to feeble.","o":["Unheedful","Strong","Weak","Baneful"],"a":[2]},{"id":"c23s1-89","p":"c23s1","n":89,"s":"eng","t":"Spelling","q":"Select the correct spelling of the underline word.\nThey denied having any \"associasion\" with the terrorists.","w":"The correct spelling is 'association' (a-s-s-o-c-i-a-t-i-o-n), the noun from the verb 'associate', meaning a connection or link with someone. It has a double s after the first a, a c (not s) in the third syllable, and the ending -tion. The printed 'associasion' wrongly ends in -sion, 'asociation' has a single s, 'asocciation' has a single s and a double c, and 'assosiation' replaces the c with s.","o":["asociation","asocciation","assosiation","association"],"a":[3]},{"id":"c23s1-90","p":"c23s1","n":90,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the most appropriate meaning of the underlined idiom in the given sentence.\nPooja tried to explain the problem, but soon she \"tied herself up in knots\".","w":"To 'tie oneself (up) in knots' means to become very confused and muddled while trying to explain or deal with something, as Pooja did when her explanation of the problem only made things more confusing. Option 1 is the sense of being called to account, option 3 is the sense of going round in circles in a discussion, and option 4 is the sense of refusing to budge an inch, so they are meanings of other idioms.","o":["Be forced to explain your actions and (probably) punished","Become very confused when you are trying to explain something","Make no progress in an argument or discussion","Won’t modify an opinion or agree to even small changes that another person wants"],"a":[1]},{"id":"c23s1-91","p":"c23s1","n":91,"s":"eng","t":"Sentence Arrangement","q":"Sentences of a paragraph are given below in jumbled order. Arrange the sentences in the correct order to form a meaningful and coherent paragraph.\nA. In Bihar and Central India, in particular, every district had smelters that used local deposits of ore to produce iron which was widely used for the manufacture of implements and tools of daily use.\nB. The smelting was done by men while women worked on the bellows, pumping air that kept the charcoal burning.\nC. But iron smelting in India was extremely common till the end of the nineteenth century.\nD. Production of Wootz steel required a highly specialised technique of refining iron.","w":"D opens with the highly specialised technique needed to produce Wootz steel. C, beginning with 'But', contrasts this with ordinary iron smelting, which was extremely common in India till the end of the nineteenth century. A gives the example of Bihar and Central India, where every district had smelters, and B, with 'The smelting', describes how that smelting was done, men at the furnace and women at the bellows. So the order is DCAB.","o":["ACDB","DCAB","BCDA","CBDA"],"a":[1]},{"id":"c23s1-92","p":"c23s1","n":92,"s":"eng","t":"Sentence Arrangement","q":"Sentences of a paragraph are given below in jumbled order. Arrange the sentences in the correct order to form a meaningful and coherent paragraph.\nA. He repeated the experiment, increasing the amount until he had weighed up to a thousand pounds.\nB. During the spring of 1717, the iron foundries in a remote district were often visited by a thin, middle-aged man with a notebook.\nC. Three cauldrons were next prepared under his directions.\nD. He would weigh out two pounds of iron, have them heated till they were red-hot and then weigh them again.","w":"B opens the paragraph by setting the time and place and introducing the person, a thin, middle-aged man visiting iron foundries in the spring of 1717. D tells what he did (weighed two pounds of iron, heated it red-hot and weighed it again). A follows because 'He repeated the experiment' refers to D, now with larger amounts up to a thousand pounds. C ends with the next step, signalled by 'next': three cauldrons were prepared. So the order is BDAC.","o":["BDAC","ABDC","BCAD","CABD"],"a":[0]},{"id":"c23s1-93","p":"c23s1","n":93,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Select the most appropriate option to fill in the blank.\nShe is ______ a peacock in the blue satin saree.","w":"A comparison of equality uses the pattern as + adjective + as: 'She is as beautiful as a peacock in the blue satin saree.' Similes such as 'as brave as a lion' follow the same pattern. 'So ... as' is used mainly in negative comparisons (not so beautiful as), 'very beautiful as' is ungrammatical, and 'beautiful like' drops the first 'as' and is not the standard form of the comparison.","o":["very beautiful as","so beautiful as","as beautiful as","beautiful like"],"a":[2]},{"id":"c23s1-94","p":"c23s1","n":94,"s":"eng","t":"Sentence Arrangement","q":"Sentences of a paragraph are given below in jumbled order. Arrange the sentences in the correct order to form a meaningful and coherent paragraph.\nA. The top band is made of saffron, which symbolises power and courage.\nB. The constituent assembly adopted our national flag, Tiranga, which means tricolour, on 22 July 1947.\nC. As a symbol of nationalism and freedom, it is fashioned from khadi, which is domestically spun Indian cotton.\nD. It features three horizontal stripes that are all the same width.","w":"B introduces the topic: the Constituent Assembly adopted the national flag, the Tiranga, on 22 July 1947. C refers to the flag as 'it' and describes the material, khadi, as a symbol of nationalism and freedom. D then describes the design, three horizontal stripes of equal width, and A picks out the first of these stripes, the top saffron band. So the order is BCDA. CBAD and CBDA fail because the 'it' in C needs the flag to be named first, and BDCA fails because A, on the top band, must directly follow D's three stripes.","o":["CBAD","CBDA","BCDA","BDCA"],"a":[2]},{"id":"c23s1-95","p":"c23s1","n":95,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"Select the most appropriate homonym to fill in the blank.\nThe hunter dogs followed the hyena’s ______.","w":"'Scent' is the characteristic smell of an animal, or the trail of smell it leaves behind, which hunting dogs track: 'The hunter dogs followed the hyena's scent.' Sense, scent, cense and cents sound alike or nearly alike but differ in spelling and meaning. 'Sense' is a faculty such as sight or hearing, or good judgement, 'cense' means to perfume with burning incense, and 'cents' are coins worth one-hundredth of a dollar.","o":["sense","scent","cense","cents"],"a":[1]},{"id":"c23s1-96","p":"c23s1","n":96,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage some words have been deleted. Fill in the blanks with the help of the alternatives given. Select the most appropriate option for each number.\nHuman life is (1) ______ a unique blessing, which in turn depends on the (2) ______ of the Self. He who is not aware of the Self can neither have peace nor can he foster peaceful co-existence. We have to link our soul with God and body with the physical world for substance. (3) ______ the formless God is invisible to the naked eye, our mind often wanders wherever it goes. (4) ______, we are unable to develop any love for the Divine. And religion like the white light of heavens (5) ______ multi-coloured fragmentations by the prisms of men and loses its gravity. Instead of uniting, it becomes a major dividing force. French philosopher Tail hard de Chardin, thinking deeply on meaning of our existence and relationship with the Divine, expounds, “we are not human beings having a spiritual experience, we are spiritual beings having a human experience”.\nSelect the most appropriate option to fill in blank no. 1.","w":"The blank needs a passive form after 'is': 'Human life is considered a unique blessing', meaning that human life is regarded as a unique blessing. 'Is considered' is the simple present passive (is + past participle). 'Considering' and 'to consider' are active forms that would make human life the one doing the considering (the passive infinitive would be 'is to be considered'), and the base form 'consider' cannot follow 'is'.","o":["considering","to consider","considered","consider"],"a":[2]},{"id":"c23s1-97","p":"c23s1","n":97,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage some words have been deleted. Fill in the blanks with the help of the alternatives given. Select the most appropriate option for each number.\nHuman life is (1) ______ a unique blessing, which in turn depends on the (2) ______ of the Self. He who is not aware of the Self can neither have peace nor can he foster peaceful co-existence. We have to link our soul with God and body with the physical world for substance. (3) ______ the formless God is invisible to the naked eye, our mind often wanders wherever it goes. (4) ______, we are unable to develop any love for the Divine. And religion like the white light of heavens (5) ______ multi-coloured fragmentations by the prisms of men and loses its gravity. Instead of uniting, it becomes a major dividing force. French philosopher Tail hard de Chardin, thinking deeply on meaning of our existence and relationship with the Divine, expounds, “we are not human beings having a spiritual experience, we are spiritual beings having a human experience”.\nSelect the most appropriate option to fill in blank no. 2.","w":"After the article 'the' and before 'of the Self' the blank needs a noun. 'Awareness', meaning knowledge or consciousness of something, fits, and the next sentence confirms it: 'He who is not aware of the Self can neither have peace...'. 'Aware' is an adjective, 'known' is a past participle, and 'witness' is a noun but means a person who sees an event, which makes no sense with 'of the Self'.","o":["witness","known","awareness","aware"],"a":[2]},{"id":"c23s1-98","p":"c23s1","n":98,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage some words have been deleted. Fill in the blanks with the help of the alternatives given. Select the most appropriate option for each number.\nHuman life is (1) ______ a unique blessing, which in turn depends on the (2) ______ of the Self. He who is not aware of the Self can neither have peace nor can he foster peaceful co-existence. We have to link our soul with God and body with the physical world for substance. (3) ______ the formless God is invisible to the naked eye, our mind often wanders wherever it goes. (4) ______, we are unable to develop any love for the Divine. And religion like the white light of heavens (5) ______ multi-coloured fragmentations by the prisms of men and loses its gravity. Instead of uniting, it becomes a major dividing force. French philosopher Tail hard de Chardin, thinking deeply on meaning of our existence and relationship with the Divine, expounds, “we are not human beings having a spiritual experience, we are spiritual beings having a human experience”.\nSelect the most appropriate option to fill in blank no. 3.","w":"The clause after the blank gives the reason for the main clause: because the formless God cannot be seen with the naked eye, our mind wanders wherever it goes. 'Since', used as a conjunction meaning 'because', introduces such a reason clause at the start of a sentence. 'From' and 'As per' (according to) are prepositions and cannot introduce a clause, and 'For' meaning 'because' cannot begin a sentence with the reason placed before the main clause.","o":["Since","From","As per","For"],"a":[0]},{"id":"c23s1-99","p":"c23s1","n":99,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage some words have been deleted. Fill in the blanks with the help of the alternatives given. Select the most appropriate option for each number.\nHuman life is (1) ______ a unique blessing, which in turn depends on the (2) ______ of the Self. He who is not aware of the Self can neither have peace nor can he foster peaceful co-existence. We have to link our soul with God and body with the physical world for substance. (3) ______ the formless God is invisible to the naked eye, our mind often wanders wherever it goes. (4) ______, we are unable to develop any love for the Divine. And religion like the white light of heavens (5) ______ multi-coloured fragmentations by the prisms of men and loses its gravity. Instead of uniting, it becomes a major dividing force. French philosopher Tail hard de Chardin, thinking deeply on meaning of our existence and relationship with the Divine, expounds, “we are not human beings having a spiritual experience, we are spiritual beings having a human experience”.\nSelect the most appropriate option to fill in blank no. 4.","w":"The blank links a cause and its effect: our mind wanders because God is invisible, and as a consequence we are unable to develop any love for the Divine. 'As a result' introduces such a consequence. 'As a reason' would wrongly present the sentence as the cause, 'As a reaction' suggests a response to someone's action, and 'Causing' is a participle that cannot be used to open the sentence followed by a comma and a new clause.","o":["As a result","As a reaction","Causing","As a reason"],"a":[0]},{"id":"c23s1-100","p":"c23s1","n":100,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage some words have been deleted. Fill in the blanks with the help of the alternatives given. Select the most appropriate option for each number.\nHuman life is (1) ______ a unique blessing, which in turn depends on the (2) ______ of the Self. He who is not aware of the Self can neither have peace nor can he foster peaceful co-existence. We have to link our soul with God and body with the physical world for substance. (3) ______ the formless God is invisible to the naked eye, our mind often wanders wherever it goes. (4) ______, we are unable to develop any love for the Divine. And religion like the white light of heavens (5) ______ multi-coloured fragmentations by the prisms of men and loses its gravity. Instead of uniting, it becomes a major dividing force. French philosopher Tail hard de Chardin, thinking deeply on meaning of our existence and relationship with the Divine, expounds, “we are not human beings having a spiritual experience, we are spiritual beings having a human experience”.\nSelect the most appropriate option to fill in blank no. 5.","w":"The subject 'religion' is singular, so the verb must be singular, 'breaks', just like 'loses' later in the same sentence. 'Break into' means to split into parts, as white light breaks into the colours of the spectrum when it passes through a prism; likewise religion 'breaks into multi-coloured fragmentations by the prisms of men'. 'Break into' and 'break from' lack the singular -s, and 'breaks to' uses the wrong preposition.","o":["break into","breaks to","break from","breaks into"],"a":[3]},{"id":"c24s2-1","p":"c24s2","n":1,"s":"rea","t":"Non-verbal Reasoning","q":"How many triangles are there in the given figure?","w":"Name the square's corners top T, left L, bottom B and right R. The line TB splits the square into two triangles, TLB and TBR. The short vertical line inside TLB cuts off a small triangle at corner L. Below B, side LB is extended and a vertical line drops from side BR, forming one more small triangle. The semicircle on TR and the strip between the two vertical lines are not triangles, and no other three lines meet to close a triangle. Total = 4.","img":"data:image/png;base64,","o":["4","6","3","5"],"a":[0],"qt":"दी गई आकृति में कितने त्रिभुज हैं?","ot":["4","6","3","5"],"wt":"वर्ग के शीर्षों को ऊपर T, बाएँ L, नीचे B और दाएँ R नाम दें। रेखा TB वर्ग को दो त्रिभुजों TLB और TBR में बाँटती है। त्रिभुज TLB के अंदर की छोटी ऊर्ध्वाधर रेखा कोने L पर एक छोटा त्रिभुज काटती है। B के नीचे भुजा LB को आगे बढ़ाया गया है और भुजा BR से एक ऊर्ध्वाधर रेखा नीचे आती है, जिससे एक और छोटा त्रिभुज बनता है। TR पर बना अर्धवृत्त और दोनों ऊर्ध्वाधर रेखाओं के बीच की पट्टी त्रिभुज नहीं हैं, और कोई अन्य तीन रेखाएँ मिलकर त्रिभुज नहीं बनातीं। कुल = 4।"},{"id":"c24s2-2","p":"c24s2","n":2,"s":"rea","t":"Non-verbal Reasoning","q":"Select the correct mirror image of the given figure when the mirror is placed at MN as shown.","w":"The mirror MN stands vertically to the right, so the image is a left-right reversal: the letters appear in reverse order and each letter is flipped sideways. MJXWU therefore becomes U W X J M. U, W, X and M are symmetrical about a vertical axis and look unchanged, but J turns into a back-to-front J (hook opening to the right). Option 4 shows exactly this. The other options put M in place of W, distort the M, or leave the J unreversed.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[3],"qt":"जब दर्पण को दर्शाए गए अनुसार MN पर रखा जाता है, तो दी गई आकृति के सही दर्पण प्रतिबिंब का चयन करें।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"दर्पण MN दाईं ओर ऊर्ध्वाधर रखा है, इसलिए प्रतिबिंब में बाएँ-दाएँ उलटाव होता है: अक्षरों का क्रम उलट जाता है और प्रत्येक अक्षर पार्श्व रूप से पलट जाता है। इस प्रकार MJXWU का प्रतिबिंब U W X J M बनता है। U, W, X और M ऊर्ध्वाधर अक्ष के सापेक्ष सममित हैं, इसलिए अपरिवर्तित दिखते हैं, परंतु J उलटा J बन जाता है (हुक दाईं ओर खुलता है)। विकल्प 4 ठीक यही दर्शाता है। अन्य विकल्प W के स्थान पर M रखते हैं, M को विकृत करते हैं, या J को उलटा नहीं करते।"},{"id":"c24s2-3","p":"c24s2","n":3,"s":"rea","t":"Non-verbal Reasoning","q":"Select the correct mirror image of the given figure when the mirror is placed at MN as shown below.","w":"With a vertical mirror on the right, the order of the characters is reversed and each one is laterally inverted. 9 / 3 > 4 2 is seen as 2 4 > 3 / 9 written back to front: the 2 and 4 are reversed, '>' becomes '<', the 3 opens to the left, '/' becomes '\\' and the 9 is reversed. Option 2 shows all of these. Options 1 and 4 keep '/' unchanged (option 1 also keeps the 3; option 4 has a 6 for the reversed 9), and option 3 turns 2 and 4 upside down.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"दर्पण को MN पर रखे जाने पर दी गई आकृति के सही दर्पण प्रतिबिंब का चयन कीजिए।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"दाईं ओर ऊर्ध्वाधर दर्पण होने पर वर्णों का क्रम उलट जाता है और प्रत्येक वर्ण पार्श्व रूप से उलट जाता है। 9 / 3 > 4 2 का प्रतिबिंब 2 4 > 3 / 9 का उलटा रूप दिखता है: 2 और 4 उलट जाते हैं, '>' बदलकर '<' हो जाता है, 3 बाईं ओर खुलता है, '/' बदलकर '\\' हो जाता है और 9 उलट जाता है। विकल्प 2 में ये सभी परिवर्तन हैं। विकल्प 1 और 4 में '/' अपरिवर्तित है (विकल्प 1 में 3 भी अपरिवर्तित है; विकल्प 4 में उलटे 9 के स्थान पर 6 है), और विकल्प 3 में 2 और 4 ऊपर-नीचे उलटे हैं।"},{"id":"c24s2-4","p":"c24s2","n":4,"s":"rea","t":"Analogy & Classification","q":"Select the triad in which the numbers are related in the same way as are the numbers of the following triads.\n(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g., 13 – Operations on 13 such as adding/deleting/multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.)\n(2, 3, 17)\n(5, 2, 21)","w":"The rule is (first number × second number) + 11 = third number. Check: 2 × 3 + 11 = 17 and 5 × 2 + 11 = 21. Apply it to the options: 3 × 4 + 11 = 23, which matches (3, 4, 23). For the others, 5 × 6 + 11 = 41 (not 72), 2 × 5 + 11 = 21 (not 42) and 1 × 4 + 11 = 15 (not 17). So only (3, 4, 23) follows the same rule.","o":["(3, 4, 23)","(5, 6, 72)","(2, 5, 42)","(1, 4, 17)"],"a":[0],"qt":"उस त्रिक का चयन कीजिए, जिसमें संख्याएँ उसी प्रकार संबंधित हैं, जिस प्रकार निम्नलिखित त्रिकों की संख्याएँ संबंधित हैं।\n(नोट: संख्याओं को उनके घटक अंकों में विभक्त किए बिना, पूर्ण संख्याओं पर संक्रिया किया जाना चाहिए। उदाहरण के लिए 13 :- 13 पर संक्रिया जैसे 13 में जोड़/घटाव/गुणा आदि किया जा सकता है। 13 को 1 और 3 में विभक्त कर और फिर 1 और 3 पर गणितीय संक्रियाएँ करने की अनुमति नहीं है)।\n(2, 3, 17)\n(5, 2, 21)","ot":["(3, 4, 23)","(5, 6, 72)","(2, 5, 42)","(1, 4, 17)"],"wt":"नियम है: (पहली संख्या × दूसरी संख्या) + 11 = तीसरी संख्या। जाँच: 2 × 3 + 11 = 17 और 5 × 2 + 11 = 21। विकल्पों पर लागू करें: 3 × 4 + 11 = 23, जो (3, 4, 23) से मेल खाता है। अन्य के लिए, 5 × 6 + 11 = 41 (72 नहीं), 2 × 5 + 11 = 21 (42 नहीं) और 1 × 4 + 11 = 15 (17 नहीं)। अतः केवल (3, 4, 23) इसी नियम का पालन करता है।"},{"id":"c24s2-5","p":"c24s2","n":5,"s":"rea","t":"Series","q":"Select the option that represents the letters that when placed from left to right in the blanks below will complete the given letter series.\nN _ B A N A _ A _ A N A N A B _ N A N A B A _ A N A","w":"Putting A, N, B, A, N in the blanks gives NABANA NABANA NABANA NABANA NA, i.e. the block \"NABANA\" repeated. The blanks fall at the 2nd letter of the first block (A), the 1st and 3rd letters of the second block (N, B), the 4th letter of the third block (A) and the 5th letter of the fourth block (N). Any other option breaks the repeating block, for example ANANB puts A where B is needed.","o":["ANANB","NANAB","ANABN","ANBAN"],"a":[3],"qt":"उस विकल्प का चयन करें जो उन अक्षरों को निरूपित करता है जिन्हें नीचे दिए गए रिक्त स्थानों में बाएँ से दाएँ रखे जाने पर दी गई अक्षर श्रृंखला पूरी हो जाएगी।\nN _ B A N A _ A _ A N A N A B _ N A N A B A _ A N A","ot":["ANANB","NANAB","ANABN","ANBAN"],"wt":"रिक्त स्थानों में A, N, B, A, N रखने पर NABANA NABANA NABANA NABANA NA प्राप्त होता है, अर्थात् समूह \"NABANA\" की पुनरावृत्ति। रिक्त स्थान पहले समूह के दूसरे अक्षर (A), दूसरे समूह के पहले और तीसरे अक्षर (N, B), तीसरे समूह के चौथे अक्षर (A) और चौथे समूह के पाँचवें अक्षर (N) पर आते हैं। कोई अन्य विकल्प इस दोहराए जाने वाले समूह को तोड़ देता है, उदाहरण के लिए ANANB वहाँ A रखता है जहाँ B चाहिए।"},{"id":"c24s2-6","p":"c24s2","n":6,"s":"rea","t":"Coding-Decoding","q":"In a certain code language, ‘let it go’ is coded as ‘vc nt ap’ and ‘this is it’ is coded as ‘mq vc lh’. What is the code for ‘it’ in that language?","w":"Compare the two sentences. The only word common to 'let it go' and 'this is it' is 'it', and the only code common to 'vc nt ap' and 'mq vc lh' is 'vc'. So 'it' is coded as 'vc'; the position of a code need not match the position of its word. The codes 'nt' and 'ap' stand for 'let' and 'go', while 'mq' and 'lh' stand for 'this' and 'is'.","o":["nt","lh","vc","mq"],"a":[2],"qt":"एक निश्चित कूट भाषा में 'let it go' को 'vc nt ap' के रूप में कूटबद्ध किया जाता है और 'this is it' को 'mq vc lh' के रूप में कूटबद्ध किया जाता है। उस भाषा में 'it' के लिए कूट क्या है?","ot":["nt","lh","vc","mq"],"wt":"दोनों वाक्यों की तुलना करें। 'let it go' और 'this is it' में एकमात्र उभयनिष्ठ शब्द 'it' है, और 'vc nt ap' तथा 'mq vc lh' में एकमात्र उभयनिष्ठ कूट 'vc' है। अतः 'it' का कूट 'vc' है; कूट का स्थान उसके शब्द के स्थान से मेल खाना आवश्यक नहीं है। कूट 'nt' और 'ap' शब्दों 'let' और 'go' के लिए हैं, जबकि 'mq' और 'lh' शब्दों 'this' और 'is' के लिए हैं।"},{"id":"c24s2-7","p":"c24s2","n":7,"s":"rea","t":"Syllogism & Statements","q":"In this question, three statements are given, followed by three conclusions numbered I, II and III. Assuming the statements to be true, even if they seem to be at variance with commonly known facts, decide which of the conclusions logically follow(s) from the statements.\nStatements:\nAll fans are brown.\nSome brown are chairs.\nSome chairs are plastic.\nConclusions:\nI. Some brown are fans.\nII. Some chairs are brown.\nIII. No chair is plastic.","w":"Conclusion I: \"All fans are brown\" can be converted to \"Some brown are fans\", so I follows. Conclusion II: \"Some brown are chairs\" converts directly to \"Some chairs are brown\", so II follows. Conclusion III, \"No chair is plastic\", contradicts the statement \"Some chairs are plastic\", so it cannot follow. Hence only conclusions I and II follow.","o":["Only conclusions II and III follow.","Only conclusion III follows.","None of the conclusions follows.","Only conclusions I and II follow."],"a":[3],"qt":"इस प्रश्न में, तीन कथन और उसके बाद तीन निष्कर्ष क्रमांक I, II और III दिए गए हैं। कथनों को सत्य मानते हुए, भले ही वे सामान्य रूप से ज्ञात तथ्यों से भिन्न प्रतीत होते हों, तय कीजिए कि कौन सा/से निष्कर्ष कथनों का तार्किक रूप से अनुसरण करता/करते है/हैं।\nकथन:\nसभी पंखे, ब्राउन हैं।\nकुछ ब्राउन, कुर्सियां हैं।\nकुछ कुर्सियां, प्लास्टिक हैं।\nनिष्कर्ष:\nI. कुछ ब्राउन, पंखे हैं।\nII. कुछ कुर्सियां, ब्राउन हैं।\nIII. कोई कुर्सी, प्लास्टिक नहीं है।","ot":["केवल निष्कर्ष II और III अनुसरण करते हैं।","केवल निष्कर्ष III अनुसरण करता है।","कोई भी निष्कर्ष अनुसरण नहीं करता है।","केवल निष्कर्ष I और II अनुसरण करते हैं।"],"wt":"निष्कर्ष I: \"सभी पंखे ब्राउन हैं\" का रूपांतरण \"कुछ ब्राउन पंखे हैं\" होता है, इसलिए I अनुसरण करता है। निष्कर्ष II: \"कुछ ब्राउन कुर्सियाँ हैं\" का सीधा रूपांतरण \"कुछ कुर्सियाँ ब्राउन हैं\" है, इसलिए II अनुसरण करता है। निष्कर्ष III, \"कोई कुर्सी प्लास्टिक नहीं है\", कथन \"कुछ कुर्सियाँ प्लास्टिक हैं\" का खंडन करता है, इसलिए यह अनुसरण नहीं कर सकता। अतः केवल निष्कर्ष I और II अनुसरण करते हैं।"},{"id":"c24s2-8","p":"c24s2","n":8,"s":"rea","t":"Non-verbal Reasoning","q":"Select the figure from among the given options that can replace the question mark (?) and logically complete the series.","w":"At each step the four corner symbols move one corner clockwise, and the symbol that reaches the top-left corner is turned upside down (arrow up to down, P to b, ▽ to △). The central symbol is alternately upright and inverted. So in the fifth figure A moves to the top-left and becomes ∀, △ goes to the top-right, b to the bottom-right, the down-arrow to the bottom-left, and the central symbol is upright. Option 1 matches; option 4 has an up-arrow, and options 2 and 3 keep A upright.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[0],"qt":"दिए गए विकल्पों में से उस आकृति का चयन कीजिए जो प्रश्न चिह्न (?) को प्रतिस्थापित कर सकती है और शृंखला को तार्किक रूप से पूरा कर सकती है।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"प्रत्येक चरण में चारों कोनों के चिह्न एक कोना दक्षिणावर्त खिसकते हैं, और जो चिह्न ऊपरी-बाएँ कोने पर पहुँचता है वह ऊपर-नीचे उलट जाता है (तीर ऊपर से नीचे, P से b, ▽ से △)। बीच का चिह्न बारी-बारी से सीधा और उलटा होता है। अतः पाँचवीं आकृति में A ऊपरी-बाएँ कोने पर पहुँचकर ∀ बन जाता है, △ ऊपरी-दाएँ कोने पर, b निचले-दाएँ कोने पर और नीचे की ओर का तीर निचले-बाएँ कोने पर जाता है, तथा बीच का चिह्न सीधा होता है। विकल्प 1 मेल खाता है; विकल्प 4 में ऊपर की ओर तीर है, और विकल्प 2 तथा 3 में A सीधा है।"},{"id":"c24s2-9","p":"c24s2","n":9,"s":"rea","t":"Blood Relations & Directions","q":"In a certain code language,\nR + T means ‘R is the sister of T’.\nR − T means ‘R is the father of T’.\nR * T means ‘R is the wife of T’.\nR ÷ T means ‘R is the mother of T’.\nBased on the above, how is F related to C if ‘A + B − C ÷ D * E − F ÷ G’?","w":"Decode step by step: B is the father of C; C is the mother of D; D is the wife of E; E is the father of F; F is the mother of G. Since D is E's wife and E is F's father, D is F's mother. F is the mother of G, so F is female, a daughter of D. D (a wife, hence female) is C's daughter. So F is C's daughter's daughter, i.e. C's granddaughter.","o":["Wife","Daughter","Daughter’s daughter","Mother"],"a":[2],"qt":"एक निश्चित कूट भाषा में,\nR + T का अर्थ है कि 'R, T की बहन है'।\nR − T का अर्थ है कि 'R, T का पिता है'।\nR * T का अर्थ है कि 'R, T की पत्नी है'।\nR ÷ T का अर्थ है कि 'R, T की माता है'।\nउपरोक्त के आधार पर, यदि 'A + B − C ÷ D * E − F ÷ G' है, तो F का C से क्या संबंध है?","ot":["पत्नी","पुत्री","नातिन/नतिनी","माता"],"wt":"क्रम से कूट खोलें: B, C का पिता है; C, D की माता है; D, E की पत्नी है; E, F का पिता है; F, G की माता है। चूँकि D, E की पत्नी है और E, F का पिता है, इसलिए D, F की माता है। F, G की माता है, अतः F स्त्री है, यानी D की पुत्री है। D (पत्नी होने के कारण स्त्री) C की पुत्री है। अतः F, C की पुत्री की पुत्री, अर्थात् C की नातिन है।"},{"id":"c24s2-10","p":"c24s2","n":10,"s":"rea","t":"Analogy & Classification","q":"Select the word-pair that best represents a similar relationship to the one expressed in the pair of words given below.\n(The words must be considered as meaningful English words and must NOT be related to each other based on the number of letters/number of consonants/vowels in the word)\nEgypt : Nile","w":"The Nile is the principal river of Egypt, flowing through the length of the country. In the same way, the Irrawaddy is Myanmar's main river, flowing from north to south through the country into the Andaman Sea. The other pairs are wrong: the Mekong flows through China, Myanmar, Laos, Thailand, Cambodia and Vietnam, not South Korea; the Colorado flows through the USA and Mexico, not Brazil; and the Mississippi is in the USA, not Russia.","o":["South Korea : Mekong","Brazil : Colorado","Russia : Mississippi","Myanmar : Irrawaddy"],"a":[3],"qt":"उस शब्द-युग्म का चयन करें, जो नीचे दिए गए शब्दों के युग्म में व्यक्त किए गए संबंध के समान संबंधों का सबसे बेहतर ढंग से प्रतिनिधित्व करता है।\n(शब्दों को अर्थपूर्ण हिंदी शब्द माना जाना चाहिए और शब्द में अक्षरों की संख्या/व्यंजनों/स्वरों की संख्या के आधार पर एक दूसरे से संबंधित नहीं होना चाहिए)\nEgypt : Nile (मिस्र : नील)","ot":["South Korea : Mekong (दक्षिण कोरिया : मेकोंग)","Brazil : Colorado (ब्राजील : कोलोराडो)","Russia : Mississippi (रूस : मिसीसिप्पी)","Myanmar : Irrawaddy (म्यांमार : इरावदी)"],"wt":"नील नदी मिस्र की प्रमुख नदी है, जो पूरे देश में बहती है। इसी प्रकार इरावदी म्यांमार की मुख्य नदी है, जो देश में उत्तर से दक्षिण बहकर अंडमान सागर में गिरती है। अन्य युग्म गलत हैं: मेकोंग चीन, म्यांमार, लाओस, थाईलैंड, कंबोडिया और वियतनाम से होकर बहती है, दक्षिण कोरिया से नहीं; कोलोराडो संयुक्त राज्य अमेरिका और मैक्सिको में बहती है, ब्राज़ील में नहीं; और मिसीसिप्पी संयुक्त राज्य अमेरिका में है, रूस में नहीं।"},{"id":"c24s2-11","p":"c24s2","n":11,"s":"rea","t":"Coding-Decoding","q":"In a certain code language, ‘It’s your life’ is written as ‘Ao Bo Co’ and ‘It’s your food’ is written as ‘Ba Co Bo’. How will ‘food’ be written in that language?","w":"The words 'It’s' and 'your' occur in both sentences, and the codes common to both are 'Bo' and 'Co', so these two words take Bo and Co (in some order). The remaining word of the first sentence, 'life', must be 'Ao'. The remaining word of the second sentence, 'food', must therefore be 'Ba'. Bo and Co cannot be 'food' because they appear in both sentences.","o":["Ba","Bo","Ao","Co"],"a":[0],"qt":"एक निश्चित कूट भाषा में, ‘It’s your life’ को ‘Ao Bo Co’ के रूप में लिखा जाता है और ‘It’s your food’ को ‘Ba Co Bo’ के रूप में लिखा जाता है। उसी भाषा में ‘food’ को किस प्रकार लिखा जाएगा?","ot":["Ba","Bo","Ao","Co"],"wt":"शब्द 'It’s' और 'your' दोनों वाक्यों में आते हैं, और दोनों वाक्यों में उभयनिष्ठ कूट 'Bo' और 'Co' हैं, इसलिए इन दोनों शब्दों के कूट Bo और Co हैं (किसी भी क्रम में)। पहले वाक्य का शेष शब्द 'life' अवश्य 'Ao' होगा। अतः दूसरे वाक्य का शेष शब्द 'food' अवश्य 'Ba' होगा। Bo और Co 'food' के कूट नहीं हो सकते, क्योंकि वे दोनों वाक्यों में आते हैं।"},{"id":"c24s2-12","p":"c24s2","n":12,"s":"rea","t":"Miscellaneous Reasoning","q":"The position of how many letters will change, if each of the letters in the word ‘SYSTEM’ is arranged in the English alphabetical order?","w":"Arrange the letters of SYSTEM alphabetically: E, M, S, S, T, Y. Compare position by position with S, Y, S, T, E, M: 1st S becomes E (changes), 2nd Y becomes M (changes), 3rd S stays S (no change), 4th T becomes S (changes), 5th E becomes T (changes), 6th M becomes Y (changes). Only the third position keeps the same letter, so the positions of five letters change.","o":["Three","Five","Four","Six"],"a":[1],"qt":"यदि शब्द 'SYSTEM' के प्रत्येक अक्षर को अँग्रेजी वर्णमाला के क्रम में व्यवस्थित किया जाए, तो कितने अक्षरों की स्थिति बदल जाएगी?","ot":["तीन","पाँच","चार","छः"],"wt":"SYSTEM के अक्षरों को वर्णमाला क्रम में व्यवस्थित करें: E, M, S, S, T, Y। मूल शब्द S, Y, S, T, E, M से स्थान-दर-स्थान तुलना करें: पहला S बदलकर E (बदला), दूसरा Y बदलकर M (बदला), तीसरा S, S ही रहता है (कोई बदलाव नहीं), चौथा T बदलकर S (बदला), पाँचवाँ E बदलकर T (बदला), छठा M बदलकर Y (बदला)। केवल तीसरे स्थान पर वही अक्षर रहता है, अतः पाँच अक्षरों की स्थिति बदलती है।"},{"id":"c24s2-13","p":"c24s2","n":13,"s":"rea","t":"Non-verbal Reasoning","q":"Identify the figure given in the options which when put in place of the question mark (?) will logically complete the series.","w":"The arrow, with a double bar at its tail, turns 45° anticlockwise at every step: it points up, then up-left, then left, then down-left. One more 45° anticlockwise turn makes it point straight down, with the double bar at the top. Option 2 shows this. Option 4 simply repeats the first figure (pointing up), while option 1 (pointing right) and option 3 (pointing down-right) would need turns of 135° and 90° instead of 45°.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"विकल्पों में दी गई उस आकृति की पहचान कीजिए, जिसे प्रश्न चिह्न (?) के स्थान पर रखने पर श्रृंखला तार्किक रूप से पूरी हो जाएगी।","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"पूँछ पर दोहरी पट्टी वाला तीर प्रत्येक चरण में 45° वामावर्त घूमता है: यह ऊपर, फिर ऊपर-बाएँ, फिर बाएँ, फिर नीचे-बाएँ की ओर इंगित करता है। एक और 45° वामावर्त घुमाव से यह सीधे नीचे की ओर इंगित करेगा और दोहरी पट्टी ऊपर होगी। विकल्प 2 यही दर्शाता है। विकल्प 4 केवल पहली आकृति को दोहराता है (ऊपर की ओर), जबकि विकल्प 1 (दाईं ओर) और विकल्प 3 (नीचे-दाईं ओर) के लिए 45° के स्थान पर क्रमशः 135° और 90° का घुमाव चाहिए।"},{"id":"c24s2-14","p":"c24s2","n":14,"s":"rea","t":"Series","q":"Select the number from among the given options that can replace the question mark (?) in the following series.\n99, 123, 150, 180, 213, ?","w":"Find the differences between consecutive terms: 123 − 99 = 24, 150 − 123 = 27, 180 − 150 = 30 and 213 − 180 = 33. The difference increases by 3 each time, so the next difference is 36. The missing term is 213 + 36 = 249. 248 is one short, and 258 or 259 would need a jump of 45 or 46, which does not fit the pattern.","o":["248","258","259","249"],"a":[3],"qt":"दिए गए विकल्पों में से उस संख्या का चयन कीजिए, जो निम्नलिखित शृंखला में प्रश्न-चिह्न (?) को प्रतिस्थापित कर सकती है।\n99, 123, 150, 180, 213, ?","ot":["248","258","259","249"],"wt":"क्रमागत पदों के अंतर ज्ञात करें: 123 − 99 = 24, 150 − 123 = 27, 180 − 150 = 30 और 213 − 180 = 33। अंतर हर बार 3 बढ़ता है, इसलिए अगला अंतर 36 है। लुप्त पद 213 + 36 = 249 है। 248 एक कम है, और 258 या 259 के लिए 45 या 46 की वृद्धि चाहिए, जो पैटर्न में नहीं बैठती।"},{"id":"c24s2-15","p":"c24s2","n":15,"s":"rea","t":"Syllogism & Statements","q":"Read the given statements and conclusions carefully. You have to take the given statements to be true even if they seem to be at variance from commonly known facts. You have to decide which conclusion(s) logically follow(s) from the given statements\nStatements:\nNo river is a mountain.\nSome rivers are animals.\nSome birds are mountains.\nConclusions:\nI: No animal is a mountain.\nII: No river is a bird.","w":"Only the animals that are rivers are known not to be mountains; other animals may or may not be mountains, so \"No animal is a mountain\" is not certain and I does not follow. Likewise, only the birds that are mountains are known not to be rivers; other birds may be rivers, so \"No river is a bird\" is not certain and II does not follow. Hence neither conclusion follows.","o":["Both conclusions (I) and (II) follow","Neither conclusion (I) nor (II) follows","Only conclusion (I) follows","Only conclusion (II) follows"],"a":[1],"qt":"दिए गए कथनों और निष्कर्षों को ध्यानपूर्वक पढ़ें। आपको दिए गए कथनों को सत्य मानना है, भले ही वे सामान्यतः ज्ञात तथ्यों से भिन्न प्रतीत होते हों। आपको तय करना है कि कौन-सा/कौन-से निष्कर्ष दिए गए कथनों का तार्किक रूप से अनुसरण करता है/करते हैं।\nकथन:\nकोई भी नदी, पहाड़ नहीं है।\nकुछ नदियाँ, जानवर हैं।\nकुछ पक्षी, पर्वत हैं।\nनिष्कर्ष:\nI: कोई भी जानवर, पहाड़ नहीं है।\nII: कोई भी नदी, पक्षी नहीं है।","ot":["दोनों निष्कर्ष (I) और (II) अनुसरण करते हैं।","न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।","केवल निष्कर्ष (I) अनुसरण करता है।","केवल निष्कर्ष (II) अनुसरण करता है।"],"wt":"केवल वे जानवर जो नदियाँ भी हैं, निश्चित रूप से पहाड़ नहीं हैं; अन्य जानवर पहाड़ हो भी सकते हैं, इसलिए \"कोई भी जानवर पहाड़ नहीं है\" निश्चित नहीं है और I अनुसरण नहीं करता। इसी प्रकार, केवल वे पक्षी जो पर्वत हैं, निश्चित रूप से नदी नहीं हैं; अन्य पक्षी नदियाँ हो सकते हैं, इसलिए \"कोई भी नदी पक्षी नहीं है\" निश्चित नहीं है और II भी अनुसरण नहीं करता। अतः न तो निष्कर्ष I और न ही II अनुसरण करता है।"},{"id":"c24s2-16","p":"c24s2","n":16,"s":"rea","t":"Analogy & Classification","q":"Select the set in which the numbers are related in the same way as are the numbers of the following sets.\n(NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding /deleting /multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.)\n(18, 378, 7)\n(14, 210, 5)","w":"The middle number equals first × third × 3: 18 × 7 × 3 = 378 and 14 × 5 × 3 = 210. Check the options: 15 × 9 × 3 = 405, which matches (15, 405, 9). The others use × 2 instead: 17 × 8 × 2 = 272, 17 × 6 × 2 = 204 and 23 × 5 × 2 = 230, while the rule would give 408, 306 and 345. So (15, 405, 9) is related in the same way.","o":["(17, 272, 8)","(17, 204, 6)","(23, 230, 5)","(15, 405, 9)"],"a":[3],"qt":"उस समुच्चय का चयन करें जिसमें दी गई संख्याएँ आपस में उसी प्रकार संबंधित हैं, जिस प्रकार प्रश्न में दिए गए समुच्चय की संख्याएँ आपस में संबंधित हैं।\n(ध्यान दें: संख्याओं को उनके घटक अंकों में तोड़े बिना, पूर्ण संख्याओं पर गणितीय संक्रियाएँ की जानी चाहिए। जैसे, 13 के मामले में - 13 पर की जाने वाली विभिन्न गणितीय संक्रियाएँ जैसे जोड़ना / घटाना / गुणा करना आदि केवल 13 के साथ की जा सकती हैं। लेकिन 13 को 1 और 3 में तोड़ने और फिर 1 और 3 पर गणितीय संक्रियाएँ करने की अनुमति नहीं है।)\n(18, 378, 7)\n(14, 210, 5)","ot":["(17, 272, 8)","(17, 204, 6)","(23, 230, 5)","(15, 405, 9)"],"wt":"मध्य संख्या = पहली × तीसरी × 3: 18 × 7 × 3 = 378 और 14 × 5 × 3 = 210। विकल्पों की जाँच करें: 15 × 9 × 3 = 405, जो (15, 405, 9) से मेल खाता है। अन्य विकल्पों में × 2 का प्रयोग है: 17 × 8 × 2 = 272, 17 × 6 × 2 = 204 और 23 × 5 × 2 = 230, जबकि नियम से 408, 306 और 345 आने चाहिए। अतः (15, 405, 9) उसी प्रकार संबंधित है।"},{"id":"c24s2-17","p":"c24s2","n":17,"s":"rea","t":"Analogy & Classification","q":"Select the triad in which the numbers are related in the same way as are the numbers of the given triads.\n(16, 33, 67), (19, 39, 79)\n(NOTE : Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding /deleting /multiplying etc. to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed)","w":"Each number is twice the previous one plus 1: 16 × 2 + 1 = 33 and 33 × 2 + 1 = 67; 19 × 2 + 1 = 39 and 39 × 2 + 1 = 79. In (22, 45, 91): 22 × 2 + 1 = 45 and 45 × 2 + 1 = 91, so it fits. (14, 27, 53) follows \"× 2 − 1\" instead, and (18, 36, 80) and (21, 45, 90) follow neither pattern.","o":["(22, 45, 91)","(14, 27, 53)","(18, 36, 80)","(21, 45, 90)"],"a":[0],"qt":"उस त्रिक का चयन कीजिए, जिसमें संख्याएँ एक-दूसरे से उसी तरह संबंधित हैं, जैसे दिए गए त्रिकों की संख्याएँ हैं।\n(16, 33, 67), (19, 39, 79)\n(ध्यान दीजिए: संख्याओं को उनके घटक अंकों में विभाजित किए बिना, पूर्ण संख्याओं पर संक्रियाएँ की जानी चाहिए। उदाहरण के लिए 13 - 13 पर संक्रिया जैसे जोड़ना / हटाना / गुणा करना आदि 13 पर किया जा सकता है। 13 को 1 और 3 में तोड़ना और फिर 1 और 3 पर गणितीय संक्रियाएँ करने की अनुमति नहीं है)","ot":["(22, 45, 91)","(14, 27, 53)","(18, 36, 80)","(21, 45, 90)"],"wt":"प्रत्येक संख्या पिछली संख्या के दोगुने से 1 अधिक है: 16 × 2 + 1 = 33 और 33 × 2 + 1 = 67; 19 × 2 + 1 = 39 और 39 × 2 + 1 = 79। (22, 45, 91) में: 22 × 2 + 1 = 45 और 45 × 2 + 1 = 91, अतः यह मेल खाता है। (14, 27, 53) इसके स्थान पर \"× 2 − 1\" का पालन करता है, और (18, 36, 80) तथा (21, 45, 90) किसी भी पैटर्न का पालन नहीं करते।"},{"id":"c24s2-18","p":"c24s2","n":18,"s":"rea","t":"Analogy & Classification","q":"The same operation(s) are followed in all the given number pairs except one. Find that odd number pair.\n(NOTE : Operations should be performed on the whole numbers, without breaking down the numbers into its constituent digits. E.g. 13 – Operations on 13 such as adding /deleting /multiplying etc., to 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.)","w":"In the regular pairs the second number is the first × 3 + 3, i.e. 3 × (first + 1): 15 × 3 + 3 = 48, 12 × 3 + 3 = 39 and 13 × 3 + 3 = 42. For 11 the rule gives 11 × 3 + 3 = 36, but the pair shows 35. So 11 : 35 does not follow the common operation and is the odd number pair.","o":["15 : 48","12 : 39","13 : 42","11 : 35"],"a":[3],"qt":"दिए गए संख्या युग्मों में से एक को छोड़कर अन्य सभी में समान संक्रिया/संक्रियाओं का अनुसरण किया गया है। वह असंगत संख्या युग्म ज्ञात कीजिए।\n(नोट : संख्याओं को उसके संघटक अंकों में खंडित किए बिना संक्रियाएँ पूर्णांकों पर की जानी चाहिए। उदाहरण के लिए 13- 13 पर की जाने वाली संक्रियाएं जैसे जोड़ना/घटाना/गुणा इत्यादि 13 पर ही की जानी चाहिए। 13 को 1 और 3 में खंडित करना और फिर 1 और 3 पर गणितीय संक्रियाएँ करना वर्जित है।)","ot":["15 : 48","12 : 39","13 : 42","11 : 35"],"wt":"सामान्य युग्मों में दूसरी संख्या = पहली संख्या × 3 + 3, अर्थात् 3 × (पहली संख्या + 1): 15 × 3 + 3 = 48, 12 × 3 + 3 = 39 और 13 × 3 + 3 = 42। 11 के लिए नियम से 11 × 3 + 3 = 36 आता है, परंतु युग्म में 35 है। अतः 11 : 35 सामान्य संक्रिया का पालन नहीं करता और यही असंगत संख्या युग्म है।"},{"id":"c24s2-19","p":"c24s2","n":19,"s":"rea","t":"Non-verbal Reasoning","q":"A paper is folded and cut as shown below. How will it appear when unfolded?","w":"The sheet is folded right to left and then top to bottom, so unfold in reverse. The small square cut at the corner where both folds meet (the centre of the sheet) opens into one square in the middle. The rectangle at the bottom edge touching the vertical fold opens into one long rectangle at the bottom, and opening the other fold copies it to the top. The oval near the outer edge appears near all four corners. Option 4 shows a central square, long rectangles at top and bottom and four ovals.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[3],"qt":"एक कागज को नीचे दिए गए चित्र के अनुसार मोड़ा और काटा जाता है। यह कागज खोलने पर कैसा दिखाई देगा?","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"कागज को पहले दाएँ से बाएँ और फिर ऊपर से नीचे मोड़ा गया है, इसलिए उलटे क्रम में खोलें। जिस कोने पर दोनों मोड़ मिलते हैं (कागज का केंद्र), वहाँ काटा गया छोटा वर्ग खुलकर बीच में एक वर्ग बनाता है। ऊर्ध्वाधर मोड़ को छूता निचले किनारे का आयत खुलकर नीचे एक लंबा आयत बनाता है, और दूसरा मोड़ खोलने पर इसकी प्रति ऊपर भी बनती है। बाहरी किनारे के पास का अंडाकार चारों कोनों के पास दिखाई देता है। विकल्प 4 में बीच में वर्ग, ऊपर और नीचे लंबे आयत और चार अंडाकार हैं।"},{"id":"c24s2-20","p":"c24s2","n":20,"s":"rea","t":"Non-verbal Reasoning","q":"A square sheet of paper is folded along the dotted lines successively in the directions shown and is then punched in the last. How would the paper look when unfolded?","w":"The sheet is folded top half down, then left half over to the right, leaving the bottom-right quarter with four layers. One hole is punched near the centre of the sheet and one near the bottom-right corner. Each hole passes through all four layers, so unfolding gives 2 × 4 = 8 holes, symmetrical about both fold lines: four around the centre and one near each corner. Only option 2 shows this pattern; the others have too few holes or holes only along a diagonal.","img":"data:image/png;base64,","o":["Figure 1","Figure 2","Figure 3","Figure 4"],"a":[1],"qt":"कागज की एक वर्गाकार शीट को बिंदीदार रेखाओं के अनुदिश दिखाई गई दिशाओं में क्रमिक रूप से मोड़ा जाता है और फिर अंत में पंच किया जाता है। कागज को खोलने पर यह कैसा दिखाई देगा?","ot":["Figure 1","Figure 2","Figure 3","Figure 4"],"wt":"कागज का ऊपरी आधा भाग नीचे और फिर बायाँ आधा भाग दाईं ओर मोड़ा गया है, जिससे निचले-दाएँ चौथाई भाग में चार परतें बनती हैं। एक छेद कागज के केंद्र के पास और एक निचले-दाएँ कोने के पास किया गया है। प्रत्येक छेद चारों परतों से होकर जाता है, इसलिए खोलने पर 2 × 4 = 8 छेद बनते हैं, जो दोनों मोड़ रेखाओं के सापेक्ष सममित हैं: चार केंद्र के चारों ओर और एक-एक प्रत्येक कोने के पास। केवल विकल्प 2 यह पैटर्न दर्शाता है; अन्य में छेद कम हैं या केवल एक विकर्ण पर हैं।"},{"id":"c24s2-21","p":"c24s2","n":21,"s":"rea","t":"Analogy & Classification","q":"Three of the following four letter-cluster pairs are alike in a certain way and thus form a group. Which is the letter-cluster pair that does NOT belong to that group?\n(Note: The odd one out is not based on the number of consonants/vowels or their positions in the letter-cluster.)","w":"Use alphabet positions. EJ - OT: E(5), J(10), O(15), T(20); KP - UZ: K(11), P(16), U(21), Z(26); CH - MR: C(3), H(8), M(13), R(18). In each, every letter is 5 places after the one before it. In PF - OI: P(16), F(6), O(15), I(9), so the +5 pattern breaks completely. Hence PF - OI is the pair that does not belong to the group.","o":["EJ - OT","KP - UZ","PF - OI","CH - MR"],"a":[2],"qt":"निम्नलिखित चार अक्षर-समूह युग्मों में से तीन अक्षर-समूह युग्म एक निश्चित तरीके से समान हैं और इस प्रकार एक समूह बनाते हैं। इनमें से वह अक्षर-समूह युग्म कौन-सा है जो इस समूह से संबंधित नहीं है?\n(ध्यान दें: असंगतअक्षर-समूह युग्म, अक्षर-समूह में व्यंजनों/स्वरों की संख्या या इस उनकी स्थिति पर आधारित नहीं है।)","ot":["EJ - OT","KP - UZ","PF - OI","CH - MR"],"wt":"वर्णमाला में अक्षरों के स्थान लें। EJ - OT: E(5), J(10), O(15), T(20); KP - UZ: K(11), P(16), U(21), Z(26); CH - MR: C(3), H(8), M(13), R(18)। प्रत्येक में हर अक्षर अपने पिछले अक्षर से 5 स्थान आगे है। PF - OI में: P(16), F(6), O(15), I(9), अतः +5 का पैटर्न पूरी तरह टूट जाता है। अतः PF - OI वह युग्म है जो इस समूह से संबंधित नहीं है।"},{"id":"c24s2-22","p":"c24s2","n":22,"s":"rea","t":"Mathematical Operations","q":"What will come in place of the question mark (?) in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged?\n1604 × 4 − 525 ÷ 5 + 73 = ?","w":"After interchanging the signs the expression becomes 1604 ÷ 4 + 525 × 5 − 73. By BODMAS, do the division and multiplication first: 1604 ÷ 4 = 401 and 525 × 5 = 2625. Then 401 + 2625 − 73 = 3026 − 73 = 2953. The other options use the same digits in a different order, so careful arithmetic is what decides the answer.","o":["2953","2935","2539","2395"],"a":[0],"qt":"यदि ‘+’ और ‘−’ को आपस में बदल दिया जाए और ‘×’ और ‘÷’ को आपस में बदल दिया जाए, तो निम्नलिखित समीकरण में प्रश्न चिह्न (?) के स्थान पर क्या आएगा?\n1604 × 4 − 525 ÷ 5 + 73 = ?","ot":["2953","2935","2539","2395"],"wt":"चिह्नों को आपस में बदलने पर व्यंजक 1604 ÷ 4 + 525 × 5 − 73 बन जाता है। BODMAS के अनुसार पहले भाग और गुणा करें: 1604 ÷ 4 = 401 और 525 × 5 = 2625। फिर 401 + 2625 − 73 = 3026 − 73 = 2953। अन्य विकल्पों में यही अंक अलग क्रम में हैं, इसलिए सावधानीपूर्वक गणना से ही सही उत्तर तय होता है।"},{"id":"c24s2-23","p":"c24s2","n":23,"s":"rea","t":"Series","q":"Select the letter-cluster from among the given options that can replace the question mark (?) to complete the given series.\nBVTO, DTVM, ?, HPZI, JNBG","w":"Take each letter position separately. First letters B, D, _, H, J go up by 2, so the missing one is F. Second letters V, T, _, P, N go down by 2, giving R. Third letters T, V, _, Z, B go up by 2 (Z + 2 wraps round to B), giving X. Fourth letters O, M, _, I, G go down by 2, giving K. So the missing cluster is FRXK.","o":["RFXK","RXFK","FKXR","FRXK"],"a":[3],"qt":"दिए गए विकल्पों में से उस अक्षर-समूह का चयन कीजिए, जो निम्नलिखित शृंखला को पूरा करने के लिए प्रश्न-चिह्न (?) को प्रतिस्थापित कर सकता है।\nBVTO, DTVM, ?, HPZI, JNBG","ot":["RFXK","RXFK","FKXR","FRXK"],"wt":"प्रत्येक अक्षर-स्थान को अलग-अलग देखें। पहले अक्षर B, D, _, H, J में 2 की वृद्धि होती है, अतः लुप्त अक्षर F है। दूसरे अक्षर V, T, _, P, N में 2 की कमी होती है, जिससे R मिलता है। तीसरे अक्षर T, V, _, Z, B में 2 की वृद्धि होती है (Z + 2 घूमकर B बनता है), जिससे X मिलता है। चौथे अक्षर O, M, _, I, G में 2 की कमी होती है, जिससे K मिलता है। अतः लुप्त अक्षर-समूह FRXK है।"},{"id":"c24s2-24","p":"c24s2","n":24,"s":"rea","t":"Series","q":"Select the option that can replace the question mark (?) in the following series.\nVO39, TM35, RK31, PI27, ?","w":"The first letters V, T, R, P move back 2 places each time, so the next is N. The second letters O, M, K, I also move back 2 places, giving G. The numbers 39, 35, 31, 27 decrease by 4, giving 23. So the next term is NG23. MG22 has the wrong first letter and number, while MH24 and OH24 fit none of the three patterns.","o":["OH24","MG22","NG23","MH24"],"a":[2],"qt":"उस विकल्प का चयन करें जो निम्नलिखित श्रृंखला में प्रश्न चिह्न (?) के स्थान पर आ सकता है।\nVO39, TM35, RK31, PI27, ?","ot":["OH24","MG22","NG23","MH24"],"wt":"पहले अक्षर V, T, R, P हर बार 2 स्थान पीछे जाते हैं, अतः अगला N है। दूसरे अक्षर O, M, K, I भी 2 स्थान पीछे जाते हैं, जिससे G मिलता है। संख्याएँ 39, 35, 31, 27 में 4 की कमी होती है, जिससे 23 मिलता है। अतः अगला पद NG23 है। MG22 में पहला अक्षर और संख्या गलत हैं, जबकि MH24 और OH24 तीनों में से किसी भी पैटर्न में नहीं बैठते।"},{"id":"c24s2-25","p":"c24s2","n":25,"s":"rea","t":"Mathematical Operations","q":"What will come in the place of ‘?’ in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged?\n4 ÷ 6 + 91 × 7 − 5 = ?","w":"Interchanging the signs gives 4 × 6 − 91 ÷ 7 + 5. Apply BODMAS: first 4 × 6 = 24 and 91 ÷ 7 = 13, then work left to right with subtraction and addition: 24 − 13 + 5 = 11 + 5 = 16. Swapping only one pair of signs, or adding before subtracting, gives a wrong value, so both interchanges and the order of operations matter.","o":["12","21","16","17"],"a":[2],"qt":"निम्नलिखित समीकरण में, यदि '+' और '−' को आपस में बदल दिया जाए तथा '×' और '÷' को आपस में बदल दिया जाए, तो '?' के स्थान पर क्या आएगा?\n4 ÷ 6 + 91 × 7 − 5 = ?","ot":["12","21","16","17"],"wt":"चिह्नों को आपस में बदलने पर 4 × 6 − 91 ÷ 7 + 5 प्राप्त होता है। BODMAS लागू करें: पहले 4 × 6 = 24 और 91 ÷ 7 = 13, फिर बाएँ से दाएँ घटाव और जोड़ करें: 24 − 13 + 5 = 11 + 5 = 16। केवल एक जोड़ी चिह्न बदलने पर, या घटाने से पहले जोड़ने पर, गलत मान प्राप्त होता है, इसलिए दोनों अदला-बदली और संक्रियाओं का क्रम महत्वपूर्ण हैं।"},{"id":"c24s2-26","p":"c24s2","n":26,"s":"geo","t":"Indian Geography","q":"In which part of India does the hot wind ‘Loo’ blow?","w":"The loo is a strong, gusty, hot and dry wind that blows during the day over north and north-western India (Punjab, Haryana, Rajasthan, Delhi, Uttar Pradesh and Bihar) in May and June, before the monsoon arrives. It raises day temperatures to 45°C or more and can cause heat stroke. Evening dust storms in the north-west and the kalbaisakhi thunderstorms of West Bengal are other features of India's hot weather season, while the south and east stay more humid.","o":["South and Southwestern","East and Northeastern","West and Southwestern","North and Northwestern"],"a":[3],"qt":"भारत के किस भाग में गर्म हवा 'लू' चलती है?","ot":["दक्षिण और दक्षिण-पश्चिम","पूर्व और पूर्वोत्तर","पश्चिम और दक्षिण-पश्चिम","उत्तर और उत्तर-पश्चिम"],"wt":"लू एक तेज़, झोंकेदार, गर्म और शुष्क पवन है जो मई और जून में, मानसून आने से पहले, दिन के समय उत्तर और उत्तर-पश्चिमी भारत (पंजाब, हरियाणा, राजस्थान, दिल्ली, उत्तर प्रदेश और बिहार) में चलती है। इससे दिन का तापमान 45°C या उससे अधिक हो जाता है और लू लगने (हीट स्ट्रोक) का खतरा रहता है। उत्तर-पश्चिम में शाम की धूल भरी आँधियाँ और पश्चिम बंगाल के काल बैसाखी तूफ़ान भी भारत की ग्रीष्म ऋतु की विशेषताएँ हैं, जबकि दक्षिण और पूर्व अधिक आर्द्र रहते हैं।"},{"id":"c24s2-27","p":"c24s2","n":27,"s":"ih","t":"Medieval India","q":"The first southern campaign of Alauddin Khilji in 1307-08 AD was led to which of the following regions?","w":"Alauddin Khalji's southern campaigns were led by his general Malik Kafur. The first, in 1307–08, was against the Yadava king Ramachandra Deva of Devagiri, who had stopped paying tribute; he submitted, was taken to Delhi and sent back as a vassal. Kafur then attacked Warangal of the Kakatiyas (1309–10), Dwarasamudra of the Hoysalas (1310–11) and the Pandya lands around Madurai (1311). Alauddin himself had raided Devagiri earlier, in 1296, before becoming sultan.","o":["Madura","Warangal","Dwar Samudra","Devagiri"],"a":[3],"qt":"1307-08 ई. में अलाउद्दीन खिलजी का पहला दक्षिणी अभियान निम्नलिखित में से किस क्षेत्र में हुआ था?","ot":["मदुरा","वारंगल","द्वार समुद्र","देवगिरी"],"wt":"अलाउद्दीन खिलजी के दक्षिणी अभियानों का नेतृत्व उसके सेनापति मलिक काफ़ूर ने किया। पहला अभियान (1307–08) देवगिरि के यादव राजा रामचंद्र देव के विरुद्ध था, जिसने कर देना बंद कर दिया था; उसने अधीनता स्वीकार की, उसे दिल्ली ले जाया गया और फिर अधीनस्थ शासक के रूप में लौटा दिया गया। इसके बाद काफ़ूर ने काकतीयों के वारंगल (1309–10), होयसलों के द्वारसमुद्र (1310–11) और मदुरै के आसपास के पांड्य क्षेत्रों (1311) पर आक्रमण किया। अलाउद्दीन ने स्वयं सुल्तान बनने से पहले, 1296 में, देवगिरि पर धावा बोला था।"},{"id":"c24s2-28","p":"c24s2","n":28,"s":"geo","t":"Environment & Ecology","q":"Which of the following can be represented as a functional unit of nature?","w":"NCERT describes an ecosystem as a functional unit of nature, where living organisms interact among themselves and with the surrounding physical environment. Its biotic parts (producers, consumers, decomposers) and abiotic parts work together through productivity, decomposition, energy flow and nutrient cycling. The term was coined by A.G. Tansley in 1935. Humans and plants are only components of an ecosystem, and vehicles are not natural units at all.","o":["Ecosystem","Humans","Vehicles","Plants"],"a":[0],"qt":"निम्नलिखित में से किसे प्रकृति की कार्यात्मक इकाई के रूप में दर्शाया जा सकता है?","ot":["पारिस्थितिकी तंत्र","मनुष्य","वाहन","वनस्पति"],"wt":"NCERT के अनुसार पारिस्थितिकी तंत्र प्रकृति की एक कार्यात्मक इकाई है, जिसमें जीव आपस में और अपने आसपास के भौतिक पर्यावरण के साथ अन्योन्यक्रिया करते हैं। इसके जैविक घटक (उत्पादक, उपभोक्ता, अपघटक) और अजैविक घटक उत्पादकता, अपघटन, ऊर्जा प्रवाह और पोषक चक्रण के माध्यम से मिलकर कार्य करते हैं। यह शब्द ए.जी. टैन्सले ने 1935 में दिया था। मनुष्य और वनस्पति केवल पारिस्थितिकी तंत्र के घटक हैं, और वाहन तो प्राकृतिक इकाई ही नहीं हैं।"},{"id":"c24s2-29","p":"c24s2","n":29,"s":"geo","t":"Indian Geography","q":"At what latitude does the easterly jet stream blow over peninsular India during the summer months?","w":"In summer the subtropical westerly jet stream shifts north of the Himalayas with the apparent movement of the sun. An easterly jet stream, the tropical easterly jet, then blows over peninsular India at about 14°N, as the NCERT geography textbook states, and it is linked to the onset and strength of the south-west monsoon. In winter the westerly jet lies south of the Himalayas and steers western disturbances into north-western India.","o":["30°N","24°N","28°N","14°N"],"a":[3],"qt":"गर्मियों के महीनों में पूर्वी जेट धारा प्रायद्वीपीय भारत के ऊपर किस अक्षांश पर बहती है?","ot":["30°N","24°N","28°N","14°N"],"wt":"गर्मियों में सूर्य की आभासी गति के साथ उपोष्ण पश्चिमी जेट धारा हिमालय के उत्तर में खिसक जाती है। तब एक पूर्वी जेट धारा, उष्णकटिबंधीय पूर्वी जेट, प्रायद्वीपीय भारत के ऊपर लगभग 14°N अक्षांश पर बहती है, जैसा कि NCERT की भूगोल पाठ्यपुस्तक में बताया गया है; इसका संबंध दक्षिण-पश्चिम मानसून के आगमन और उसकी प्रबलता से है। सर्दियों में पश्चिमी जेट धारा हिमालय के दक्षिण में रहती है और पश्चिमी विक्षोभों को उत्तर-पश्चिमी भारत की ओर ले आती है।"},{"id":"c24s2-30","p":"c24s2","n":30,"s":"cur","t":"Sports","q":"The inaugural match of the Women Premier League 2023 cricket was played in which of the following venues?","w":"The first season of the BCCI's Women's Premier League (WPL) in 2023 was played entirely in Mumbai, at the DY Patil Stadium in Navi Mumbai and the Brabourne Stadium. In the opening match on 4 March 2023 at the DY Patil Stadium, Mumbai Indians, captained by Harmanpreet Kaur, beat Gujarat Giants by 143 runs. Mumbai Indians went on to win the first title by beating Delhi Capitals in the final at the Brabourne Stadium.","o":["Chennai","Kolkata","Delhi","Mumbai"],"a":[3],"qt":"महिला प्रीमियर लीग 2023 क्रिकेट का उद्घाटन मैच निम्नलिखित में से किस स्थान पर खेला गया था?","ot":["चेन्नई","कोलकाता","दिल्ली","मुंबई"],"wt":"BCCI की महिला प्रीमियर लीग (WPL) का पहला सत्र 2023 में पूरी तरह मुंबई में, नवी मुंबई के डी.वाई. पाटिल स्टेडियम और ब्रेबोर्न स्टेडियम में खेला गया। 4 मार्च 2023 को डी.वाई. पाटिल स्टेडियम में हुए उद्घाटन मैच में हरमनप्रीत कौर की कप्तानी वाली मुंबई इंडियंस ने गुजरात जायंट्स को 143 रन से हराया। मुंबई इंडियंस ने ब्रेबोर्न स्टेडियम में फ़ाइनल में दिल्ली कैपिटल्स को हराकर पहला खिताब भी जीता।"},{"id":"c24s2-31","p":"c24s2","n":31,"s":"sci","t":"Chemistry","q":"When electricity is passed through water, what kind of chemical reaction occurs?","w":"An electric current passed through water (with a little acid or salt added so that it conducts) splits it into its elements: 2H₂O → 2H₂ + O₂. One substance breaking into simpler substances is a decomposition reaction; when electricity supplies the energy it is called electrolytic decomposition or electrolysis. Hydrogen collects at the cathode and oxygen at the anode in a 2 : 1 ratio by volume, as shown in the NCERT Class 10 activity.","o":["Decomposition","Double displacement","Combination","Displacement"],"a":[0],"qt":"जब जल में विद्युत धारा प्रवाहित की जाती है, तो किस प्रकार की रासायनिक अभिक्रिया होती है?","ot":["अपघटन","दोहरा विस्थापन","संयोजन","विस्थापन"],"wt":"जल में (थोड़ा अम्ल या लवण मिलाकर, ताकि वह विद्युत का चालक बने) विद्युत धारा प्रवाहित करने पर वह अपने तत्वों में टूट जाता है: 2H₂O → 2H₂ + O₂। एक पदार्थ का सरल पदार्थों में टूटना अपघटन अभिक्रिया है; जब ऊर्जा विद्युत से मिलती है तो इसे विद्युत अपघटन (इलेक्ट्रोलिसिस) कहते हैं। NCERT कक्षा 10 के क्रियाकलाप के अनुसार, हाइड्रोजन कैथोड पर और ऑक्सीजन ऐनोड पर आयतन के अनुसार 2 : 1 के अनुपात में एकत्र होती हैं।"},{"id":"c24s2-32","p":"c24s2","n":32,"s":"cur","t":"Awards, Books & Persons","q":"Which music-composer duo was honoured with the National Lata Mangeshkar Award for the year 2020?","w":"The National Lata Mangeshkar Award is given every year by the Madhya Pradesh government's culture department for excellence in light music, with ₹2 lakh and a citation. In September 2022 the department named the composer duo Anand-Milind (brothers Anand and Milind Shrivastav, sons of composer Chitragupt) for the 2020 award and singer Shailendra Singh for 2019. Both awards were presented in Indore on 28 September 2022, Lata Mangeshkar's birth anniversary.","o":["Jatin-Lalit","Anand-Milind","Salim–Sulaiman","Sachin–Jigar"],"a":[1],"qt":"किस संगीत-रचयिता जोड़ी को वर्ष 2020 के राष्ट्रीय लता मंगेशकर पुरस्कार से सम्मानित किया गया था?","ot":["जतिन-ललित","आनंद-मिलिंद","सलीम-सुलेमान","सचिन-जिगर"],"wt":"राष्ट्रीय लता मंगेशकर पुरस्कार मध्य प्रदेश सरकार का संस्कृति विभाग हर वर्ष सुगम संगीत में उत्कृष्टता के लिए देता है, जिसमें ₹2 लाख और प्रशस्ति पत्र शामिल हैं। सितंबर 2022 में विभाग ने वर्ष 2020 के पुरस्कार के लिए संगीतकार जोड़ी आनंद-मिलिंद (संगीतकार चित्रगुप्त के पुत्र, भाई आनंद और मिलिंद श्रीवास्तव) और वर्ष 2019 के लिए गायक शैलेंद्र सिंह को चुना। दोनों पुरस्कार 28 सितंबर 2022 को, लता मंगेशकर की जयंती पर, इंदौर में प्रदान किए गए।"},{"id":"c24s2-33","p":"c24s2","n":33,"s":"cur","t":"Static GK & Culture","q":"In which of the following states is Govindji Nartanalaya located?","w":"Govindji Nartanalaya is a Manipuri dance institution in Imphal, Manipur, founded by Guru Bipin Singh, the dancer, choreographer and scholar who did much to revive and spread Manipuri dance; he later set up the Manipuri Nartanalaya in Kolkata in 1972. Its name recalls Shri Govindajee, the Vaishnava deity of the royal temple at Imphal, where Ras Lila is performed. Manipuri is one of India's classical dance forms.","o":["Assam","Nagaland","Tripura","Manipur"],"a":[3],"qt":"गोविंदजी नर्तनालय निम्नलिखित में से किस राज्य में स्थित है?","ot":["असम","नागालैंड","त्रिपुरा","मणिपुर"],"wt":"गोविंदजी नर्तनालय इंफाल, मणिपुर में स्थित एक मणिपुरी नृत्य संस्थान है, जिसकी स्थापना गुरु बिपिन सिंह ने की थी। वे नर्तक, नृत्य-निर्देशक और विद्वान थे जिन्होंने मणिपुरी नृत्य के पुनरुद्धार और प्रसार में बड़ा योगदान दिया; बाद में उन्होंने 1972 में कोलकाता में मणिपुरी नर्तनालय की स्थापना की। इसका नाम इंफाल के राजकीय मंदिर के वैष्णव देवता श्री गोविंदजी की याद दिलाता है, जहाँ रास लीला होती है। मणिपुरी भारत के शास्त्रीय नृत्यों में से एक है।"},{"id":"c24s2-34","p":"c24s2","n":34,"s":"geo","t":"Indian Geography","q":"In which state of India is Kund or Tanka used for water harvesting?","w":"In the dry Thar region of western Rajasthan, rainwater is stored for drinking in kunds or kundis (a saucer-shaped catchment draining into a covered underground pit) and tankas (underground tanks, often inside houses or courtyards, fed by pipes from the rooftop). NCERT mentions tankas in Bikaner, Phalodi and Barmer; this 'palar pani' stays cool and lasts through the dry months. Johads, khadins and baoris are other traditional systems of the state.","o":["Uttar Pradesh","Punjab","Rajasthan","Andhra Pradesh"],"a":[2],"qt":"भारत के किस राज्य में जल संचयन के लिए कुंड या टांका का उपयोग किया जाता है?","ot":["उत्तर प्रदेश","पंजाब","राजस्थान","आंध्र प्रदेश"],"wt":"शुष्क थार क्षेत्र वाले पश्चिमी राजस्थान में पीने के लिए वर्षा जल कुंड या कुंडी (तश्तरी के आकार का जलग्रहण क्षेत्र, जिसका पानी ढके हुए भूमिगत गड्ढे में जाता है) और टांकों (भूमिगत टंकियाँ, प्रायः घरों या आँगनों के भीतर, जिनमें छत से पाइपों द्वारा पानी आता है) में संग्रहित किया जाता है। NCERT बीकानेर, फलोदी और बाड़मेर के टांकों का उल्लेख करती है; यह 'पालर पानी' ठंडा रहता है और सूखे महीनों तक चलता है। जोहड़, खडीन और बावड़ी राज्य की अन्य पारंपरिक प्रणालियाँ हैं।"},{"id":"c24s2-35","p":"c24s2","n":35,"s":"pol","t":"Judiciary & Constitutional Bodies","q":"When was the High Court and Supreme Court Judges (Salaries and Conditions of Service) Amendment Bill, 2021 introduced in Lok Sabha?","w":"Law Minister Kiren Rijiju introduced the Bill in Lok Sabha on 30 November 2021, early in the Winter Session. It amended the High Court Judges Act of 1954 and the Supreme Court Judges Act of 1958 to make clear that the additional pension due to retired judges on reaching ages such as 80, 85, 90, 95 and 100 starts from the first day of the month in which they complete that age. Lok Sabha passed it on 8 December and Rajya Sabha on 13 December 2021.","o":["30 November 2021","27 September 2021","29 March 2021","28 April 2021"],"a":[0],"qt":"उच्च न्यायालय और सर्वोच्च न्यायालय न्यायाधीश (वेतन और सेवा की शर्तें) संशोधन विधेयक, 2021 लोकसभा में कब पेश किया गया था?","ot":["30 नवंबर 2021 को","27 सितंबर 2021 को","29 मार्च 2021 को","28 अप्रैल 2021 को"],"wt":"विधि मंत्री किरेन रिजिजू ने यह विधेयक 30 नवंबर 2021 को, शीतकालीन सत्र के आरंभ में, लोकसभा में पेश किया। इसने उच्च न्यायालय न्यायाधीश अधिनियम, 1954 और सर्वोच्च न्यायालय न्यायाधीश अधिनियम, 1958 में संशोधन करके स्पष्ट किया कि सेवानिवृत्त न्यायाधीशों को 80, 85, 90, 95 और 100 वर्ष जैसी आयु पूरी करने पर मिलने वाली अतिरिक्त पेंशन उस महीने के पहले दिन से मिलेगी जिसमें वे वह आयु पूरी करते हैं। लोकसभा ने इसे 8 दिसंबर और राज्यसभा ने 13 दिसंबर 2021 को पारित किया।"},{"id":"c24s2-36","p":"c24s2","n":36,"s":"sci","t":"Biology","q":"Which condition, also known as icterus, causes a yellowing of your skin and the whites of your eyes?","w":"Jaundice (icterus) is the yellow colour of the skin, the whites of the eyes and mucous membranes caused by excess bilirubin, a yellow pigment formed when old red blood cells are broken down. It appears when the liver cannot process or excrete bilirubin (as in hepatitis), when bile flow is blocked, or when red cells break down too fast. Pemphigus is an autoimmune blistering disease, ichthyosis causes dry scaly skin, and eczema is itchy, inflamed skin.","o":["Pemphigus","Ichthyosis","Eczema","Jaundice"],"a":[3],"qt":"कौन सी स्थिति, जिसे पीलिया (इक्टेरस) के रूप में भी जाना जाता है, आपकी त्वचा के पीलेपन और आपकी आंखों के सफेद होने का कारण बनती है?","ot":["पेम्फीगस","इक्थियोसिस","एक्जिमा","जॉन्डिस"],"wt":"पीलिया (इक्टेरस) में त्वचा, आँखों के सफेद भाग और श्लेष्म झिल्लियों का रंग पीला हो जाता है। इसका कारण बिलीरुबिन की अधिकता है, जो पुरानी लाल रक्त कोशिकाओं के टूटने से बनने वाला पीला वर्णक है। यह तब होता है जब यकृत बिलीरुबिन को संसाधित या उत्सर्जित नहीं कर पाता (जैसे हेपेटाइटिस में), पित्त का प्रवाह रुक जाता है, या लाल रक्त कोशिकाएँ बहुत तेज़ी से टूटती हैं। पेम्फीगस एक स्वप्रतिरक्षी फफोलेदार रोग है, इक्थियोसिस में त्वचा सूखी और पपड़ीदार हो जाती है, और एक्जिमा में त्वचा में खुजली और सूजन होती है।"},{"id":"c24s2-37","p":"c24s2","n":37,"s":"ih","t":"Ancient India","q":"Which of the following inscriptions of Rudradaman happened to be the first royal inscription of early India composed in chaste Sanskrit?","w":"The Junagadh (Girnar) rock inscription of the Shaka (Western Kshatrapa) ruler Rudradaman I, of about 150 CE, is the first long royal inscription of early India in chaste Sanskrit. It records his repair of the Sudarshana lake, first built under Chandragupta Maurya and improved under Ashoka, after a storm breached its dam. The same rock carries Ashoka's major rock edicts. The Prayag pillar inscription is Samudragupta's, and the Mehrauli iron pillar inscription names a king Chandra.","o":["Mehrauli","Prayag","Chirand","Girnar"],"a":[3],"qt":"रुद्रदामन के निम्नलिखित शिलालेखों में से कौन-सा शुद्ध संस्कृत में रचित प्रारंभिक भारत का पहला राजकीय शिलालेख है?","ot":["महरौली","प्रयाग","चिरांद","गिरनार"],"wt":"शक (पश्चिमी क्षत्रप) शासक रुद्रदामन प्रथम का जूनागढ़ (गिरनार) शिलालेख, लगभग 150 ई., प्रारंभिक भारत का शुद्ध संस्कृत में रचित पहला लंबा राजकीय अभिलेख है। इसमें तूफ़ान से बाँध टूटने के बाद सुदर्शन झील की मरम्मत का वर्णन है; यह झील चंद्रगुप्त मौर्य के समय बनी थी और अशोक के समय इसमें सुधार हुआ था। इसी शिला पर अशोक के प्रमुख शिलालेख भी हैं। प्रयाग स्तंभ अभिलेख समुद्रगुप्त का है, और महरौली लौह स्तंभ अभिलेख में 'चंद्र' नामक राजा का उल्लेख है।"},{"id":"c24s2-38","p":"c24s2","n":38,"s":"geo","t":"Indian Geography","q":"According to Census of India 2011, in rural India, which state has the maximum female workforce participation rate?","w":"The work participation rate is the share of people who are workers (main or marginal). Census 2011 figures compiled by MoSPI give a rural female rate of 47.4% for Himachal Pradesh, against 44.6% for Andhra Pradesh, 39.5% for Arunachal Pradesh, 18.3% for Uttar Pradesh and 30.0% for rural India as a whole, so Himachal is highest among the options. Its overall female rate (44.8%) was the highest of any state; in rural areas alone Nagaland (52.3%) was higher still, but it is not an option.","o":["Andhra Pradesh","Arunachal Pradesh","Uttar Pradesh","Himachal Pradesh"],"a":[3],"qt":"भारत की जनगणना 2011 के अनुसार ग्रामीण भारत में, निम्नलिखित में से कौन-से राज्य में, महिला कार्यबल भागीदारी दर सर्वाधिक है?","ot":["आंध्र प्रदेश","अरुणाचल प्रदेश","उत्तर प्रदेश","हिमाचल प्रदेश"],"wt":"कार्य सहभागिता दर जनसंख्या में श्रमिकों (मुख्य या सीमांत) का प्रतिशत है। MoSPI द्वारा संकलित जनगणना 2011 के आँकड़ों के अनुसार ग्रामीण महिला दर हिमाचल प्रदेश में 47.4% थी, जबकि आंध्र प्रदेश में 44.6%, अरुणाचल प्रदेश में 39.5%, उत्तर प्रदेश में 18.3% और पूरे ग्रामीण भारत में 30.0% थी; इसलिए विकल्पों में हिमाचल सबसे आगे है। हिमाचल की कुल महिला दर (44.8%) सभी राज्यों में सर्वाधिक थी; केवल ग्रामीण क्षेत्रों में नागालैंड (52.3%) इससे भी आगे था, पर वह विकल्पों में नहीं है।"},{"id":"c24s2-39","p":"c24s2","n":39,"s":"cur","t":"Static GK & Culture","q":"Which of the following celebrations is dedicated to Sun God and his wife Usha to thank them for sustaining life on earth and for granting wishes?","w":"Chhath Puja, celebrated mainly in Bihar, Jharkhand, eastern Uttar Pradesh and the Terai of Nepal, honours the Sun God (Surya) and his consort Usha. Devotees fast, bathe in rivers and offer arghya to the setting and the rising sun; the main day is the sixth day of the bright half of Kartik, six days after Diwali. Madai is a tribal festival of Chhattisgarh, Sorath Sabha is the Maithil marriage gathering at Saurath in Bihar, and Vishwakarma Puja honours the divine architect.","o":["Vishwakarma Puja","Madai Festival","Sorath Sabha","Chhath Puja"],"a":[3],"qt":"निम्नलिखित में से कौन-सा उत्सव सूर्य देव और उनकी पत्नी उषा को पृथ्वी पर जीवन बनाए रखने और इच्छाएँ प्रदान करने के लिए धन्यवाद देने के लिए समर्पित है?","ot":["विश्वकर्मा पूजा","मड़ई महोत्सव","सौराठ सभा","छठ पूजा"],"wt":"छठ पूजा, जो मुख्यतः बिहार, झारखंड, पूर्वी उत्तर प्रदेश और नेपाल के तराई क्षेत्र में मनाई जाती है, सूर्य देव और उनकी पत्नी उषा को समर्पित है। श्रद्धालु उपवास रखते हैं, नदियों में स्नान करते हैं और डूबते तथा उगते सूर्य को अर्घ्य देते हैं; मुख्य दिन कार्तिक शुक्ल षष्ठी है, जो दीवाली के छह दिन बाद पड़ता है। मड़ई छत्तीसगढ़ का एक जनजातीय उत्सव है, सौराठ सभा बिहार के सौराठ में लगने वाली मैथिल विवाह-सभा है, और विश्वकर्मा पूजा दिव्य वास्तुकार विश्वकर्मा को समर्पित है।"},{"id":"c24s2-40","p":"c24s2","n":40,"s":"cur","t":"Sports","q":"At which Olympics did Gagan Narang win a bronze medal?","w":"Gagan Narang won bronze in the men's 10 m air rifle at the London 2012 Olympics, India's first medal of those Games. He also competed at Athens 2004, Beijing 2008 and Rio 2016 but did not win a medal there. A multiple Commonwealth Games gold medallist, he received the Rajiv Gandhi Khel Ratna in 2011. India's only other Olympic shooting medals before Paris 2024 were Rajyavardhan Rathore's silver (2004), Abhinav Bindra's gold (2008) and Vijay Kumar's silver (2012).","o":["Beijing 2008","London 2012","Athens 2004","Rio 2016"],"a":[1],"qt":"गगन नारंग ने किस ओलंपिक में कांस्य पदक जीता था?","ot":["बीजिंग 2008","लंदन 2012","एथेंस 2004","रियो 2016"],"wt":"गगन नारंग ने लंदन 2012 ओलंपिक में पुरुषों की 10 मीटर एयर राइफल स्पर्धा में कांस्य पदक जीता, जो उन खेलों में भारत का पहला पदक था। उन्होंने एथेंस 2004, बीजिंग 2008 और रियो 2016 में भी भाग लिया, पर वहाँ पदक नहीं जीता। राष्ट्रमंडल खेलों में कई स्वर्ण पदक जीतने वाले नारंग को 2011 में राजीव गांधी खेल रत्न मिला। पेरिस 2024 से पहले भारत के अन्य ओलंपिक निशानेबाज़ी पदक केवल राज्यवर्धन राठौड़ का रजत (2004), अभिनव बिंद्रा का स्वर्ण (2008) और विजय कुमार का रजत (2012) थे।"},{"id":"c24s2-41","p":"c24s2","n":41,"s":"ih","t":"Modern India","q":"When was a Madrasa opened in Kolkata to promote the study of Arabic, Persian and Islamic law?","w":"Warren Hastings set up the Calcutta Madrasa (Madrasa Aliya) in 1781 to promote the study of Arabic, Persian and Islamic law, which the Company needed in its courts. It reflected the early Orientalist policy of patronising Indian learning, like the Asiatic Society of Bengal founded by William Jones in 1784 and the Sanskrit College set up at Benaras in 1791. The years 1772 and 1774 are when Hastings became Governor of Bengal and then Governor-General.","o":["1772 C.E.","1783 C.E.","1781 C.E.","1774 C.E."],"a":[2],"qt":"अरबी, फ़ारसी और इस्लामी कानूनों के अध्ययन को बढ़ावा देने के लिए कोलकाता में मदरसा कब खोला गया था?","ot":["1772 ईस्वी में","1783 ईस्वी में","1781 ईस्वी में","1774 ईस्वी में"],"wt":"वारेन हेस्टिंग्स ने 1781 में अरबी, फ़ारसी और इस्लामी कानून के अध्ययन को बढ़ावा देने के लिए कलकत्ता मदरसा (मदरसा आलिया) की स्थापना की, क्योंकि कंपनी को अपनी अदालतों में इस ज्ञान की आवश्यकता थी। यह भारतीय विद्या को संरक्षण देने की आरंभिक प्राच्यवादी नीति का हिस्सा था, जैसे 1784 में विलियम जोन्स द्वारा स्थापित एशियाटिक सोसाइटी ऑफ़ बंगाल और 1791 में बनारस में स्थापित संस्कृत कॉलेज। 1772 और 1774 वे वर्ष हैं जब हेस्टिंग्स क्रमशः बंगाल के गवर्नर और फिर गवर्नर-जनरल बने।"},{"id":"c24s2-42","p":"c24s2","n":42,"s":"sci","t":"Chemistry","q":"What is the IUPAC name of tertiarybutyl alcohol?","w":"tert-Butyl alcohol is (CH₃)₃C–OH: one carbon carrying the –OH group and three methyl groups. The longest chain containing the –OH carbon has three carbons (propane), with the –OH and a methyl group both on carbon 2, so the name is 2-methylpropan-2-ol, a tertiary alcohol. The other names are invalid, because an alkyl group on carbon 1 only lengthens the chain: \"1-methylpropan-3-ol\" is really butan-1-ol and \"1-ethylpropan-3-ol\" is pentan-1-ol.","o":["1-propylpropan-3-ol","1-ethylpropan-3-ol","1-Methylpropan-3-ol","2-Methylpropan-2-ol"],"a":[3],"qt":"टर्शियरी ब्यूटाईल ऐल्कोहॉल (Tertiarybutyl alcohol) का IUPAC नाम क्या है?","ot":["1-प्रोपाइलप्रोपेन-3-ol (1-propylpropan-3-ol)","1-एथाइलप्रोपेन-3-ol (1-ethylpropan-3-ol)","1-मेथाइलप्रोपेन-3-ol (1-Methylpropan-3-ol)","2-मेथाइलप्रोपेन-2-ol (2-Methylpropan-2-ol)"],"wt":"टर्शियरी ब्यूटाइल ऐल्कोहॉल (CH₃)₃C–OH है: एक कार्बन पर –OH समूह और तीन मेथिल समूह। –OH वाले कार्बन सहित सबसे लंबी शृंखला में तीन कार्बन (प्रोपेन) हैं, और –OH तथा एक मेथिल समूह दोनों कार्बन 2 पर हैं, इसलिए नाम 2-मेथाइलप्रोपेन-2-ol (2-methylpropan-2-ol) है, जो एक तृतीयक ऐल्कोहॉल है। अन्य नाम अमान्य हैं, क्योंकि कार्बन 1 पर लगा ऐल्किल समूह केवल शृंखला को लंबा करता है: '1-मेथाइलप्रोपेन-3-ol' वास्तव में ब्यूटेन-1-ol है और '1-एथाइलप्रोपेन-3-ol' पेन्टेन-1-ol है।"},{"id":"c24s2-43","p":"c24s2","n":43,"s":"pol","t":"Constitution & Rights","q":"Which Article of the Constitution explains that the executive power of every state shall be so exercised as not to impede or prejudice the exercise of the executive power of the Union, and the executive power of the union shall extend to the giving of such directions to a state as may appear to the Government of India to be necessary for that purpose?","w":"Article 257(1), \"Control of the Union over States in certain cases\", says exactly this: a State's executive power must not impede or prejudice the Union's, and the Union may give the State such directions as the Government of India finds necessary. It belongs to the administrative relations in Part XI, along with Article 256 on the States' duty to comply with Union laws. Article 123 covers ordinances, Article 247 additional courts and Article 261 full faith and credit.","o":["Article 123","Article 261","Article 257","Article 247"],"a":[2],"qt":"संविधान का कौन-सा अनुच्छेद स्पष्ट करता है कि प्रत्येक राज्य की कार्यकारी शक्ति का प्रयोग इस प्रकार किया जाएगा कि संघ की कार्यकारी शक्ति के प्रयोग में बाधा या प्रतिकूल प्रभाव न पड़े, और संघ की कार्यकारी शक्ति किसी राज्य को ऐसे निर्देश देने तक विस्तारित होगी जो भारत सरकार को उस उद्देश्य के लिए आवश्यक प्रतीत होता हो?","ot":["अनुच्छेद 123","अनुच्छेद 261","अनुच्छेद 257","अनुच्छेद 247"],"wt":"अनुच्छेद 257(1), 'कुछ दशाओं में राज्यों पर संघ का नियंत्रण', ठीक यही कहता है: राज्य की कार्यपालिका शक्ति का प्रयोग संघ की कार्यपालिका शक्ति के प्रयोग में बाधा या प्रतिकूल प्रभाव न डाले, और संघ राज्य को ऐसे निर्देश दे सकता है जो भारत सरकार को आवश्यक प्रतीत हों। यह भाग XI के प्रशासनिक संबंधों का हिस्सा है, जिसमें अनुच्छेद 256 (संघ के कानूनों का पालन करने का राज्यों का दायित्व) भी है। अनुच्छेद 123 अध्यादेशों से, अनुच्छेद 247 अतिरिक्त न्यायालयों से और अनुच्छेद 261 पूर्ण विश्वास और साख से संबंधित है।"},{"id":"c24s2-44","p":"c24s2","n":44,"s":"ih","t":"Modern India","q":"Under the leadership of which of the following revolutionaries was Chittagong Armoury Raid conducted?","w":"On 18 April 1930, members of the Indian Republican Army led by Surya Sen (\"Masterda\") raided the police and auxiliary force armouries at Chittagong (now in Bangladesh), cut communications and proclaimed a provisional revolutionary government. Women such as Pritilata Waddedar and Kalpana Dutt later joined his group. Surya Sen was captured in 1933 and hanged in January 1934. Badal Gupta took part in the Writers' Building attack in Calcutta (1930), and Hemu Kalani was a young Sindhi revolutionary.","o":["Rash Behari Bose","Surya Sen","Hemu Kalani","Badal Gupta"],"a":[1],"qt":"निम्नलिखित में से किस क्रांतिकारी के नेतृत्व में चटगांव शस्त्रागार पर छापा मारा गया था?","ot":["रास बिहारी बोस","सूर्य सेन","हेमू कालानी","बादल गुप्ता"],"wt":"18 अप्रैल 1930 को सूर्य सेन ('मास्टरदा') के नेतृत्व में इंडियन रिपब्लिकन आर्मी के सदस्यों ने चटगांव (अब बांग्लादेश में) में पुलिस और सहायक बल के शस्त्रागारों पर छापा मारा, संचार व्यवस्था काट दी और एक अस्थायी क्रांतिकारी सरकार की घोषणा की। बाद में प्रीतिलता वादेदार और कल्पना दत्त जैसी महिलाएँ भी उनके दल में शामिल हुईं। सूर्य सेन 1933 में पकड़े गए और जनवरी 1934 में उन्हें फाँसी दी गई। बादल गुप्ता ने कलकत्ता में राइटर्स बिल्डिंग पर हमले (1930) में भाग लिया था, और हेमू कालानी एक युवा सिंधी क्रांतिकारी थे।"},{"id":"c24s2-45","p":"c24s2","n":45,"s":"eco","t":"Money, Banking & Finance","q":"What is the relationship between interest rate and demand for money?","w":"The rate of interest is the opportunity cost of holding money, because cash earns nothing while bonds and deposits earn interest. When the interest rate rises, people hold less money and more interest-earning assets, so the (speculative) demand for money falls; when it falls, they hold more money. The demand for money curve therefore slopes downward against the interest rate. The transaction demand for money, by contrast, depends mainly on income and rises with it.","o":["Inverse","Direct","No relationship exists","Proportionate"],"a":[0],"qt":"ब्याज दर और मुद्रा की मांग के बीच क्या संबंध है?","ot":["प्रतिलोम","प्रत्यक्ष","कोई संबंध नहीं है","समानुपातिक"],"wt":"ब्याज दर मुद्रा रखने की अवसर लागत है, क्योंकि नकदी पर कुछ नहीं मिलता जबकि बॉन्ड और जमाओं पर ब्याज मिलता है। ब्याज दर बढ़ने पर लोग कम मुद्रा और अधिक ब्याज देने वाली परिसंपत्तियाँ रखते हैं, इसलिए मुद्रा की (सट्टा) माँग घटती है; ब्याज दर घटने पर वे अधिक मुद्रा रखते हैं। इसलिए ब्याज दर के सापेक्ष मुद्रा की माँग का वक्र नीचे की ओर ढलान वाला होता है। इसके विपरीत, मुद्रा की लेन-देन माँग मुख्यतः आय पर निर्भर करती है और आय के साथ बढ़ती है।"},{"id":"c24s2-46","p":"c24s2","n":46,"s":"eco","t":"Schemes & Welfare","q":"The government of which of the following states created a draft policy in 2022 for senior citizens on the basis of article 41, which aims to form a directorate for the welfare of senior citizens?","w":"Tamil Nadu's Department of Social Welfare and Women Empowerment released a draft State Policy for Senior Citizens in 2022. The draft states that it is based on Article 41 of the Constitution, the Directive Principle asking the State to make effective provision for public assistance in old age, sickness, disablement and unemployment, and it proposes a separate Directorate for the Welfare of Senior Citizens to implement and monitor the policy. Nationally, the Maintenance and Welfare of Parents and Senior Citizens Act, 2007 protects the elderly.","o":["Karnataka","Kerala","Telangana","Tamil Nadu"],"a":[3],"qt":"वरिष्ठ नागरिकों के कल्याण के लिए एक निदेशालय बनाने के उद्देश्य से, निम्नलिखित में से किस राज्य की सरकार ने अनुच्छेद 41 के आधार पर वरिष्ठ नागरिकों के लिए 2022 में एक मसौदा नीति बनाई?","ot":["कर्नाटक","केरल","तेलंगाना","तमिलनाडु"],"wt":"तमिलनाडु के समाज कल्याण और महिला अधिकारिता विभाग ने 2022 में वरिष्ठ नागरिकों के लिए राज्य नीति का मसौदा जारी किया। मसौदे में कहा गया है कि यह संविधान के अनुच्छेद 41 पर आधारित है, जो राज्य नीति का निर्देशक सिद्धांत है और राज्य से वृद्धावस्था, बीमारी, निःशक्तता और बेरोज़गारी में लोक सहायता की प्रभावी व्यवस्था करने को कहता है; मसौदा नीति को लागू करने और उसकी निगरानी के लिए एक अलग 'वरिष्ठ नागरिक कल्याण निदेशालय' बनाने का प्रस्ताव करता है। राष्ट्रीय स्तर पर माता-पिता और वरिष्ठ नागरिकों का भरण-पोषण तथा कल्याण अधिनियम, 2007 बुज़ुर्गों की रक्षा करता है।"},{"id":"c24s2-47","p":"c24s2","n":47,"s":"cur","t":"Awards, Books & Persons","q":"In the year 1952, who among the following lent his voice for the film ‘Amar Bhupali’, which was being produced in two languages simultaneously and he sang in both Bengali and Marathi?","w":"Manna Dey (Prabodh Chandra Dey) sang in 1952 for Amar Bhupali, a film made in both Bengali and Marathi with the same name and story, and this established him as a leading playback singer in Bengali films. Known for classically based songs such as \"Laga chunari mein daag\", he sang in many languages and received the Padma Shri (1971), the Padma Bhushan (2005) and the Dadasaheb Phalke Award (2007). He died in 2013.","o":["Hemanta Mukherjee","Debabrata Biswas","Kishore Kumar","Manna Dey"],"a":[3],"qt":"वर्ष 1952 में, निम्नलिखित में से किसने फिल्म अमर भूपाली, जो एक साथ दो भाषाओं में निर्मित की जा रही थी, के लिए अपनी आवाज दी और उन्होंने बंगाली और मराठी दोनों में गीत गाए?","ot":["हेमंत मुखर्जी","देवव्रत बिस्वास","किशोर कुमार","मन्ना डे"],"wt":"मन्ना डे (प्रबोध चंद्र डे) ने 1952 में अमर भूपाली के लिए गीत गाए, जो एक ही नाम और कहानी के साथ बंगाली और मराठी दोनों भाषाओं में बनी फ़िल्म थी; इससे वे बंगाली फ़िल्मों के प्रमुख पार्श्वगायक के रूप में स्थापित हुए। 'लागा चुनरी में दाग' जैसे शास्त्रीय संगीत पर आधारित गीतों के लिए प्रसिद्ध मन्ना डे ने कई भाषाओं में गाया और उन्हें पद्म श्री (1971), पद्म भूषण (2005) और दादासाहेब फाल्के पुरस्कार (2007) मिले। उनका निधन 2013 में हुआ।"},{"id":"c24s2-48","p":"c24s2","n":48,"s":"eco","t":"Agriculture, Industry & Trade","q":"Which of the following statements correctly defines the green revolution?","w":"The Green Revolution was the new agricultural strategy of the mid-1960s that combined high-yielding variety (HYV) seeds with chemical fertilisers, pesticides and assured irrigation to raise food-grain output, especially of wheat and later rice. Led in India by scientists such as M.S. Swaminathan using Norman Borlaug's dwarf wheat, it spread first in Punjab, Haryana and western Uttar Pradesh and made India self-sufficient in food grains. It has nothing to do with colour, forests or herbal products.","o":["It is a new strategy to use green colour for all purposes.","It is a new strategy to increase the share of the forest.","It is a new strategy in agriculture to produce food grains, especially wheat and rice.","It is a new strategy to use only herbal products."],"a":[2],"qt":"निम्न में से कौन-सा कथन हरित क्रांति को सही ढंग से परिभाषित करता है?","ot":["यह सभी उद्देश्यों के लिए हरे रंग का उपयोग करने की एक नई रणनीति है।","यह वन के योगदान में वृद्धि करने की एक नई रणनीति है।","यह कृषि में खाद्यान्न, विशेषकर गेहूं और चावल का उत्पादन करने की एक नई रणनीति है।","यह केवल हर्बल उत्पादों का उपयोग करने की एक नई रणनीति है।"],"wt":"हरित क्रांति 1960 के दशक के मध्य की नई कृषि रणनीति थी, जिसमें खाद्यान्न, विशेषकर गेहूँ और बाद में चावल, का उत्पादन बढ़ाने के लिए अधिक उपज देने वाली किस्मों (HYV) के बीजों के साथ रासायनिक उर्वरक, कीटनाशक और सुनिश्चित सिंचाई का प्रयोग किया गया। भारत में एम.एस. स्वामीनाथन जैसे वैज्ञानिकों ने नॉर्मन बोरलॉग के बौने गेहूँ की सहायता से इसका नेतृत्व किया; यह पहले पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में फैली और इसने भारत को खाद्यान्न में आत्मनिर्भर बनाया। इसका रंग, वनों या हर्बल उत्पादों से कोई संबंध नहीं है।"},{"id":"c24s2-49","p":"c24s2","n":49,"s":"cur","t":"National","q":"In 2021, in which of the following states did the Prime Minister lay the foundation stone for the Raja Mahendra Pratap Singh State University?","w":"Prime Minister Narendra Modi laid the foundation stone of the Raja Mahendra Pratap Singh State University at Aligarh, Uttar Pradesh, on 14 September 2021. The State Government is building it on over 92 acres in Lodha and Musepur Kareem Jarauli villages, and it will affiliate 395 colleges of the Aligarh Division. Raja Mahendra Pratap Singh was a freedom fighter, educationist and social reformer who headed the Provisional Government of India set up in Kabul in 1915.","o":["Gujarat","Himachal Pradesh","Nagaland","Uttar Pradesh"],"a":[3],"qt":"2021 में, निम्नलिखित में से किस राज्य में प्रधानमंत्री ने राजा महेंद्र प्रताप सिंह राज्य विश्वविद्यालय की आधारशिला रखी?","ot":["गुजरात","हिमाचल प्रदेश","नागालैंड","उत्तर प्रदेश"],"wt":"प्रधानमंत्री नरेंद्र मोदी ने 14 सितंबर 2021 को अलीगढ़, उत्तर प्रदेश में राजा महेंद्र प्रताप सिंह राज्य विश्वविद्यालय की आधारशिला रखी। राज्य सरकार इसे लोढ़ा और मुसेपुर करीम जरौली गाँवों में 92 एकड़ से अधिक भूमि पर बना रही है, और इससे अलीगढ़ मंडल के 395 कॉलेज संबद्ध होंगे। राजा महेंद्र प्रताप सिंह एक स्वतंत्रता सेनानी, शिक्षाविद और समाज सुधारक थे, जो 1915 में काबुल में स्थापित भारत की अस्थायी सरकार के प्रमुख थे।"},{"id":"c24s2-50","p":"c24s2","n":50,"s":"pol","t":"Constitution & Rights","q":"Which of the following is NOT correct about Directive Principles of State Policy?","w":"Directive Principles of State Policy (Part IV, Articles 36–51) are non-justiciable: Article 37 says they shall not be enforceable by any court, yet they are fundamental in the governance of the country and the State must apply them in making laws. So statement 2 is the incorrect one. They guide governance, bind governments morally rather than legally, and aim at social and economic democracy and a welfare state. Fundamental Rights in Part III, by contrast, are justiciable.","o":["They provide guidelines for the governance of the country.","They are justiciable in nature.","They are morally binding on the government.","They ensure social and economic development."],"a":[1],"qt":"राज्य नीति के निर्देशक सिद्धांतों के संदर्भ में निम्नलिखित में से कौन-सा कथन सही नहीं है?","ot":["ये देश के शासन के लिए दिशानिर्देश प्रदान करते हैं।","ये न्यायोचित प्रकृति के होते हैं।","ये सरकार पर नैतिक रूप से बाध्यकारी होते हैं।","ये सामाजिक और आर्थिक विकास सुनिश्चित करते हैं।"],"wt":"राज्य नीति के निर्देशक सिद्धांत (भाग IV, अनुच्छेद 36–51) न्यायोचित नहीं हैं: अनुच्छेद 37 कहता है कि इन्हें किसी न्यायालय द्वारा लागू नहीं कराया जा सकेगा, फिर भी ये देश के शासन में मूलभूत हैं और कानून बनाने में इन्हें लागू करना राज्य का कर्तव्य है। इसलिए कथन 2 सही नहीं है। ये शासन का मार्गदर्शन करते हैं, सरकारों पर कानूनी रूप से नहीं बल्कि नैतिक रूप से बाध्यकारी हैं, और सामाजिक व आर्थिक लोकतंत्र तथा कल्याणकारी राज्य का लक्ष्य रखते हैं। इसके विपरीत, भाग III के मौलिक अधिकार न्यायोचित हैं।"},{"id":"c24s2-51","p":"c24s2","n":51,"s":"qa","t":"Trigonometry & Heights","q":"What is the value of sec (t), if tan(t) = 1/3?","w":"Use the identity sec²t = 1 + tan²t = 1 + (1/3)² = 1 + 1/9 = 10/9, so sec t = √10/3 (taking t acute, where sec t is positive). Check with a right triangle: opposite side 1, adjacent side 3, hypotenuse √(1 + 9) = √10, so sec t = hypotenuse/adjacent = √10/3. Option √10/9 forgets to take the square root of the 9 in the denominator.","o":["√3/3","2√2/3","√10/3","√10/9"],"a":[2],"qt":"यदि tan(t) = 1/3 है, तो sec (t) का मान कितना है?","ot":["√3/3","2√2/3","√10/3","√10/9"],"wt":"सर्वसमिका sec²t = 1 + tan²t का प्रयोग करें: sec²t = 1 + (1/3)² = 1 + 1/9 = 10/9, अतः sec t = √10/3 (t को न्यून कोण मानकर, जहाँ sec t धनात्मक होता है)। समकोण त्रिभुज से जाँच: लंब 1, आधार 3, कर्ण √(1 + 9) = √10, अतः sec t = कर्ण/आधार = √10/3। विकल्प √10/9 में हर के 9 का वर्गमूल लेना भूल गए हैं।"},{"id":"c24s2-52","p":"c24s2","n":52,"s":"qa","t":"Geometry","q":"The points P and S are on the same side of the line segment QR, such that ∠PQR = 90°, ∠SRQ = 90° and PQ = SR. Select the correct statement.","w":"Compare triangles PQR and SRQ: PQ = SR (given), ∠PQR = ∠SRQ = 90° (given) and QR = RQ (common side). The equal angles lie between the equal sides, so ΔPQR ≅ ΔSRQ by SAS, with P↔S, Q↔R and R↔Q; writing ΔSQR breaks this correspondence. RHS would need the hypotenuses PR and SQ to be given equal, which they are not; they become equal only as a result of the congruence.","o":["ΔPQR ≅ ΔSRQ by RHS","ΔPQR ≅ ΔSRQ by SAS","ΔPQR ≅ ΔSQR by SAS","ΔPQR ≅ ΔSQR by RHS"],"a":[1],"qt":"बिंदु P और S रेखा खंड QR के एक ही ओर इस प्रकार हैं कि ∠PQR = 90°, ∠SRQ = 90° और PQ = SR है। सही कथन का चयन कीजिए।","ot":["ΔPQR ≅ ΔSRQ RHS द्वारा","ΔPQR ≅ ΔSRQ SAS द्वारा","ΔPQR ≅ ΔSQR SAS द्वारा","ΔPQR ≅ ΔSQR RHS द्वारा"],"wt":"त्रिभुज PQR और SRQ की तुलना करें: PQ = SR (दिया है), ∠PQR = ∠SRQ = 90° (दिया है) और QR = RQ (उभयनिष्ठ भुजा)। बराबर कोण बराबर भुजाओं के बीच स्थित है, अतः SAS से ΔPQR ≅ ΔSRQ, जिसमें P↔S, Q↔R और R↔Q; ΔSQR लिखने से यह संगति टूट जाती है। RHS के लिए कर्ण PR और SQ का बराबर दिया होना आवश्यक है, जो नहीं दिया है; वे सर्वांगसमता के परिणामस्वरूप ही बराबर होते हैं।"},{"id":"c24s2-53","p":"c24s2","n":53,"s":"qa","t":"Algebra","q":"Simplify\n[(8.3)³ + (9.2)³ + (6.1)³ − 3 × 8.3 × 9.2 × 6.1]/[(8.3)² + (9.2)² + (6.1)² − 8.3 × 9.2 − 9.2 × 6.1 − 6.1 × 8.3]","w":"Use the identity a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca). With a = 8.3, b = 9.2 and c = 6.1, the numerator is exactly (a + b + c) times the denominator, and the denominator is not zero because a, b and c are not all equal. So the expression equals a + b + c = 8.3 + 9.2 + 6.1 = 23.6, with no need to work out any cubes or squares.","o":["30.2","25.5","28.7","23.6"],"a":[3],"qt":"निम्नलिखित को सरल कीजिए।\n[(8.3)³ + (9.2)³ + (6.1)³ − 3 × 8.3 × 9.2 × 6.1]/[(8.3)² + (9.2)² + (6.1)² − 8.3 × 9.2 − 9.2 × 6.1 − 6.1 × 8.3]","ot":["30.2","25.5","28.7","23.6"],"wt":"सर्वसमिका a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) का प्रयोग करें। a = 8.3, b = 9.2 और c = 6.1 लेने पर अंश ठीक-ठीक हर का (a + b + c) गुना है, और हर शून्य नहीं है क्योंकि a, b और c तीनों बराबर नहीं हैं। अतः व्यंजक का मान a + b + c = 8.3 + 9.2 + 6.1 = 23.6 है; किसी भी घन या वर्ग की गणना करने की आवश्यकता नहीं है।"},{"id":"c24s2-54","p":"c24s2","n":54,"s":"qa","t":"Data Interpretation & Statistics","q":"The pie chart given below shows the expenditure (in percentage) of Aditya. The monthly income of Aditya is ₹54,000.\nHow much does he spend (in ₹) on Food?","w":"The pie chart splits the spending as Rent 27%, Transport 15%, Food 23%, Fuel 15% and Miscellaneous 20% (total 100%), and the whole monthly income of ₹54,000 is taken as the amount spent. Food = 23% of 54,000 = 0.23 × 54,000 = ₹12,420. Quick check: 20% of 54,000 = 10,800 and 3% = 1,620, which add up to 12,420. Option 12,240 merely swaps two digits.","img":"data:image/png;base64,","o":["12,420","13,420","12,240","11,240"],"a":[0],"qt":"नीचे दिया गया पाई चार्ट आदित्य द्वारा किए जाने वाले खर्च (प्रतिशत में) को दर्शाता है। आदित्य की मासिक आय ₹54,000 है।\nवह भोजन पर कितना (₹ में) खर्च करता है?","ot":["12,420","13,420","12,240","11,240"],"wt":"पाई चार्ट में खर्च का बँटवारा है: किराया (Rent) 27%, परिवहन (Transport) 15%, भोजन (Food) 23%, ईंधन (Fuel) 15% और विविध (Miscellaneous) 20% (कुल 100%), और पूरी मासिक आय ₹54,000 को खर्च की गई राशि माना गया है। भोजन = 54,000 का 23% = 0.23 × 54,000 = ₹12,420। त्वरित जाँच: 54,000 का 20% = 10,800 और 3% = 1,620, जिनका योग 12,420 है। विकल्प 12,240 में केवल दो अंकों का स्थान बदला गया है।"},{"id":"c24s2-55","p":"c24s2","n":55,"s":"qa","t":"Percentage, Profit & Interest","q":"Madhav purchased an item for ₹42,000 and sold it at a loss of 20%. With that amount, he purchased another item and sold it at a gain of 30%. What is the overall gain (in ₹)?","w":"First item: SP = 80% of ₹42,000 = ₹33,600 (loss ₹8,400). He buys the second item for ₹33,600 and sells it at a 30% gain: SP = 1.3 × 33,600 = ₹43,680 (gain ₹10,080). He began with ₹42,000 and ends with ₹43,680, so the overall gain = ₹1,680 (= 10,080 − 8,400). In one step: 42,000 × 0.8 × 1.3 = 42,000 × 1.04, a 4% gain. Option 4200 wrongly takes a net 30 − 20 = 10%.","o":["6720","4200","2520","1680"],"a":[3],"qt":"माधव ने ₹42,000 में एक वस्तु खरीदी और उसे 20% की हानि पर बेच दिया। उस राशि से उसने एक और वस्तु खरीदी और उसे 30% के लाभ पर बेच दिया। कुल लाभ (₹ में) कितना है?","ot":["6720","4200","2520","1680"],"wt":"पहली वस्तु: विक्रय मूल्य = ₹42,000 का 80% = ₹33,600 (हानि ₹8,400)। वह दूसरी वस्तु ₹33,600 में खरीदता है और 30% लाभ पर बेचता है: विक्रय मूल्य = 1.3 × 33,600 = ₹43,680 (लाभ ₹10,080)। उसने ₹42,000 से शुरुआत की और अंत में उसके पास ₹43,680 हैं, अतः कुल लाभ = ₹1,680 (= 10,080 − 8,400)। एक चरण में: 42,000 × 0.8 × 1.3 = 42,000 × 1.04, अर्थात 4% लाभ। विकल्प 4200 गलती से शुद्ध 30 − 20 = 10% लाभ मान लेता है।"},{"id":"c24s2-56","p":"c24s2","n":56,"s":"qa","t":"Ratio, Average & Mixtures","q":"Seven years ago, Prachi was four times as old as her daughter was at that time. Four years from now, Prachi will be two-and-a-half times as old as her daughter would then be. Find the sum of the present ages (in years) of Prachi and her daughter.","w":"Let the present ages of Prachi and her daughter be p and d. Seven years ago: p − 7 = 4(d − 7), so p = 4d − 21. Four years from now: p + 4 = 2.5(d + 4). Substituting, 4d − 17 = 2.5d + 10, so 1.5d = 27 and d = 18; then p = 51. Check: seven years ago 44 = 4 × 11; four years on 55 = 2.5 × 22. Sum of present ages = 51 + 18 = 69 years.","o":["77","49","72","69"],"a":[3],"qt":"सात वर्ष पूर्व, प्राची की आयु, उस समय उसकी पुत्री की आयु की चार गुनी थी। अब से चार वर्ष बाद प्राची अपनी पुत्री की आयु की ढाई गुनी हो जाएगी। प्राची और उसकी पुत्री की वर्तमान आयु (वर्ष में) का योग ज्ञात करें।","ot":["77","49","72","69"],"wt":"मान लीजिए प्राची और उसकी पुत्री की वर्तमान आयु p और d है। सात वर्ष पूर्व: p − 7 = 4(d − 7), अतः p = 4d − 21। चार वर्ष बाद: p + 4 = 2.5(d + 4)। प्रतिस्थापित करने पर 4d − 17 = 2.5d + 10, अतः 1.5d = 27 और d = 18; तब p = 51। जाँच: सात वर्ष पूर्व 44 = 4 × 11; चार वर्ष बाद 55 = 2.5 × 22। वर्तमान आयु का योग = 51 + 18 = 69 वर्ष।"},{"id":"c24s2-57","p":"c24s2","n":57,"s":"qa","t":"Percentage, Profit & Interest","q":"If a sum of ₹5,000 is taken at a simple rate of interest of 15% per annum for 3 years and another sum of ₹8,000 is taken at a simple interest of 12% per annum for 4 years, the positive difference of the interests paid is:","w":"Simple interest = P × R × T/100. First sum: 5,000 × 15 × 3/100 = ₹2,250. Second sum: 8,000 × 12 × 4/100 = ₹3,840. Positive difference = 3,840 − 2,250 = ₹1,590. Comparing only one year's interest (₹750 and ₹960, a difference of ₹210) is a common slip; the question asks for the total interest paid over each loan's full period.","o":["₹1,286","₹1,378","₹1,643","₹1,590"],"a":[3],"qt":"यदि ₹5,000 की राशि 3 वर्षों के लिए 15% वार्षिक साधारण ब्याज दर पर ली जाती है और ₹8,000 की अन्य राशि 4 वर्षों के लिए 12% वार्षिक साधारण ब्याज पर ली जाती है, तो भुगतान किए गए ब्याज का धनात्मक अंतर ज्ञात करें।","ot":["₹1,286","₹1,378","₹1,643","₹1,590"],"wt":"साधारण ब्याज = P × R × T/100। पहली राशि: 5,000 × 15 × 3/100 = ₹2,250। दूसरी राशि: 8,000 × 12 × 4/100 = ₹3,840। धनात्मक अंतर = 3,840 − 2,250 = ₹1,590। केवल एक वर्ष के ब्याज (₹750 और ₹960, अंतर ₹210) की तुलना करना एक आम भूल है; प्रश्न प्रत्येक ऋण की पूरी अवधि में चुकाया गया कुल ब्याज पूछता है।"},{"id":"c24s2-58","p":"c24s2","n":58,"s":"qa","t":"Geometry","q":"Let C be a circle with centre O and P be an external point to C. Let PA and PB be two tangents to C with A and B being the points of tangency, respectively. If PA and PB are inclined to each other at an angle of 60°, then find ∠POA.","w":"The line OP joining the centre to the external point bisects the angle between the two tangents, so ∠APO = 60°/2 = 30°. The radius is perpendicular to the tangent at the point of contact, so ∠OAP = 90°. In triangle OAP, ∠POA = 180° − 90° − 30° = 60°. Equivalently, ∠AOB = 180° − 60° = 120° and OP bisects it. The option 30° is ∠APO, not ∠POA.","o":["80°","30°","40°","60°"],"a":[3],"qt":"मान लीजिए C एक वृत्त है जिसका केंद्र O है और P, C का एक बाह्य बिंदु है। मान लीजिए PA और PB, C की दो स्पशरिखाएं हैं तथा A और B क्रमशः स्पर्शिता बिंदु (points of tangency) हैं। यदि PA और PB एक दूसरे से 60° के कोण पर आनत हैं, तो ∠POA ज्ञात कीजिए।","ot":["80°","30°","40°","60°"],"wt":"केंद्र को बाह्य बिंदु से मिलाने वाली रेखा OP दोनों स्पर्शरेखाओं के बीच के कोण को समद्विभाजित करती है, अतः ∠APO = 60°/2 = 30°। स्पर्श बिंदु पर त्रिज्या स्पर्शरेखा पर लंब होती है, अतः ∠OAP = 90°। त्रिभुज OAP में ∠POA = 180° − 90° − 30° = 60°। इसी प्रकार, ∠AOB = 180° − 60° = 120° और OP इसे समद्विभाजित करती है। विकल्प 30° तो ∠APO है, ∠POA नहीं।"},{"id":"c24s2-59","p":"c24s2","n":59,"s":"qa","t":"Ratio, Average & Mixtures","q":"The average temperature of a city for the first sixteen days of January is 22°C, and the average temperature for the last sixteen days of the same month is 26°C. If the average temperature for the entire month is 24°C, what is the temperature on the sixteenth day?","w":"January has 31 days, so the first sixteen days (1–16) and the last sixteen days (16–31) overlap on day 16. Sum for days 1–16 = 16 × 22 = 352; sum for days 16–31 = 16 × 26 = 416; sum for the month = 31 × 24 = 744. Adding the two parts counts day 16 twice, so the temperature on the 16th = 352 + 416 − 744 = 24°C.","o":["23°C","24°C","25°C","22°C"],"a":[1],"qt":"जनवरी के पहले सोलह दिनों के लिए एक शहर का औसत तापमान 22°C रहा, और उसी महीने के अंतिम सोलह दिनों का औसत तापमान 26°C रहा। यदि पूरे महीने का औसत तापमान 24°C रहा, तो सोलहवें दिन का तापमान कितना रहा?","ot":["23°C","24°C","25°C","22°C"],"wt":"जनवरी में 31 दिन होते हैं, अतः पहले सोलह दिन (1–16) और अंतिम सोलह दिन (16–31) में दिन 16 दोनों में शामिल है। दिन 1–16 का योग = 16 × 22 = 352; दिन 16–31 का योग = 16 × 26 = 416; पूरे महीने का योग = 31 × 24 = 744। दोनों भागों को जोड़ने पर दिन 16 दो बार गिना जाता है, अतः सोलहवें दिन का तापमान = 352 + 416 − 744 = 24°C।"},{"id":"c24s2-60","p":"c24s2","n":60,"s":"qa","t":"Data Interpretation & Statistics","q":"The monthly wages (in ₹) of three mess workers, Rahul, Sunil and Vipin, of a boy’s hostel for three months are given in the following table. Study the table carefully and answer the question given below.\nMess workers/Month | October | November | December\nRahul | 10800 | 11500 | 12000\nSunil | 10000 | 10500 | 11500\nVipin | 10400 | 11600 | 12200\nIn November, the wages of Sunil is what percentage of the wages of Rahul? (Correct up to two decimal places.)","w":"In November Sunil earns ₹10,500 and Rahul ₹11,500. Sunil's wages as a percentage of Rahul's = 10,500/11,500 × 100 = 2100/23 = 91.304…% ≈ 91.30%. The base is Rahul's wage, because the question asks for a percentage \"of the wages of Rahul\". Reversing the ratio (11,500/10,500 × 100 ≈ 109.52%) is a common slip. The October and December columns are not needed.","o":["91.30%","90.23%","89.30%","88.23%"],"a":[0],"qt":"निम्नलिखित तालिका में, लड़कों के एक छात्रावास के भोजनालय के तीन कर्मचारियों, राहुल, सुनील और विपिन का तीन महीने का मासिक वेतन (₹ में) दिया गया है। तालिका का ध्यानपूर्वक अध्ययन कीजिए और नीचे दिए गए प्रश्न का उत्तर दीजिए।\nभोजनालय कर्मचारी/माह | अक्तूबर | नवंबर | दिसंबर\nराहुल | 10800 | 11500 | 12000\nसुनील | 10000 | 10500 | 11500\nविपिन | 10400 | 11600 | 12200\nनवंबर में सुनील का वेतन, राहुल के वेतन का कितने प्रतिशत है? (दो दशमलव स्थान तक पूर्णांकित)","ot":["91.30%","90.23%","89.30%","88.23%"],"wt":"नवंबर में सुनील का वेतन ₹10,500 और राहुल का ₹11,500 है। राहुल के वेतन के प्रतिशत के रूप में सुनील का वेतन = 10,500/11,500 × 100 = 2100/23 = 91.304…% ≈ 91.30%। आधार राहुल का वेतन है, क्योंकि प्रश्न 'राहुल के वेतन का' प्रतिशत पूछता है। अनुपात उलट देना (11,500/10,500 × 100 ≈ 109.52%) एक आम भूल है। अक्तूबर और दिसंबर के स्तंभों की आवश्यकता नहीं है।"},{"id":"c24s2-61","p":"c24s2","n":61,"s":"qa","t":"Ratio, Average & Mixtures","q":"At present, A is thrice as old as B. C is 5 years elder than B. The sum of the ages of A, B, C is 75 years. The ratio of the age of B five years ago to the age of A three years from now is:","w":"Let B's present age be x years. Then A = 3x and C = x + 5. Sum: 3x + x + (x + 5) = 75, so 5x = 70 and x = 14. Hence B = 14, A = 42 and C = 19 years. B's age five years ago = 14 − 5 = 9 years; A's age three years from now = 42 + 3 = 45 years. Required ratio = 9 : 45 = 1 : 5.","o":["1 : 4","2 : 3","1 : 5","4 : 7"],"a":[2],"qt":"वर्तमान में, A की आयु B की आयु की तीन गुना है। C, B से 5 वर्ष बड़ा है। A, B, C की आयु का योग 75 वर्ष है। पाँच वर्ष पहले B की आयु का, अब से तीन वर्ष बाद A की आयु से अनुपात क्या होगा?","ot":["1 : 4","2 : 3","1 : 5","4 : 7"],"wt":"मान लीजिए B की वर्तमान आयु x वर्ष है। तब A = 3x और C = x + 5। योग: 3x + x + (x + 5) = 75, अतः 5x = 70 और x = 14। इसलिए B = 14, A = 42 और C = 19 वर्ष। पाँच वर्ष पहले B की आयु = 14 − 5 = 9 वर्ष; अब से तीन वर्ष बाद A की आयु = 42 + 3 = 45 वर्ष। अभीष्ट अनुपात = 9 : 45 = 1 : 5।"},{"id":"c24s2-62","p":"c24s2","n":62,"s":"qa","t":"Trigonometry & Heights","q":"Simplify the following. (sin³A − cos³A)/(sin A − cos A), where A is an acute angle.","w":"Use a³ − b³ = (a − b)(a² + ab + b²) with a = sin A and b = cos A. Cancelling sin A − cos A (valid for A ≠ 45°) leaves sin²A + sin A cos A + cos²A = 1 + sin A cos A, since sin²A + cos²A = 1. Check with A = 30°: the given expression and 1 + sin 30° cos 30° = 1 + √3/4 both equal about 1.433. Option sinA + cosA would come from a difference of squares, not cubes.","o":["3 cosA − 1","1 − 3 sinA","sinA + cosA","1 + sinA cosA"],"a":[3],"qt":"निम्न का मान ज्ञात करें। (sin³A − cos³A)/(sin A − cos A), जहां A एक न्यून कोण है।","ot":["3 cosA − 1","1 − 3 sinA","sinA + cosA","1 + sinA cosA"],"wt":"a = sin A और b = cos A लेकर a³ − b³ = (a − b)(a² + ab + b²) का प्रयोग करें। sin A − cos A को काटने पर (A ≠ 45° के लिए मान्य) sin²A + sin A cos A + cos²A = 1 + sin A cos A बचता है, क्योंकि sin²A + cos²A = 1। A = 30° से जाँच: दिया गया व्यंजक और 1 + sin 30° cos 30° = 1 + √3/4, दोनों लगभग 1.433 हैं। विकल्प sinA + cosA घनों के अंतर से नहीं, बल्कि वर्गों के अंतर से आता।"},{"id":"c24s2-63","p":"c24s2","n":63,"s":"qa","t":"Geometry","q":"A right-angled isosceles triangle has an area of 50 square units. Its hypotenuse is (in units):","w":"In a right-angled isosceles triangle the two sides containing the right angle are equal, say a. Area = ½ × a × a = 50, so a² = 100 and a = 10 units. By Pythagoras, hypotenuse = √(a² + a²) = a√2 = 10√2 units (about 14.14). The option 5√2 is what one gets for a side by forgetting the ½ in the area formula (a² = 50), and it is a side, not the hypotenuse.","o":["5√5","10√3","5√2","10√2"],"a":[3],"qt":"एक समकोण समद्विबाहु त्रिभुज का क्षेत्रफल 50 वर्ग इकाई है। इसके कर्ण की लंबाई (इकाई में) कितनी है?","ot":["5√5","10√3","5√2","10√2"],"wt":"समकोण समद्विबाहु त्रिभुज में समकोण बनाने वाली दोनों भुजाएँ बराबर होती हैं, मान लीजिए a। क्षेत्रफल = ½ × a × a = 50, अतः a² = 100 और a = 10 इकाई। पाइथागोरस प्रमेय से कर्ण = √(a² + a²) = a√2 = 10√2 इकाई (लगभग 14.14)। विकल्प 5√2 क्षेत्रफल के सूत्र में ½ भूल जाने (a² = 50) पर भुजा का मान आता है, और वह भुजा है, कर्ण नहीं।"},{"id":"c24s2-64","p":"c24s2","n":64,"s":"qa","t":"Mensuration","q":"What is the volume (in cm³) of a cylinder if the radius of the cylinder is 8 cm and the height is 14 cm? (Take π = 22/7)","w":"Volume of a cylinder = πr²h. With r = 8 cm and h = 14 cm: V = (22/7) × 8² × 14 = (22/7) × 64 × 14. Since 14/7 = 2, this is 22 × 64 × 2 = 44 × 64 = 2816 cm³. Cancelling the 7 against the 14 first keeps the arithmetic simple. Do not confuse the volume with the curved surface area 2πrh, which here is 704 cm².","o":["2816","2686","2784","2456"],"a":[0],"qt":"यदि एक बेलन की त्रिज्या 8 cm और ऊँचाई 14 cm है, तो उस बेलन का आयतन (cm³ में) क्या होगा? (π = 22/7 लीजिए)","ot":["2816","2686","2784","2456"],"wt":"बेलन का आयतन = πr²h। r = 8 cm और h = 14 cm लेने पर: V = (22/7) × 8² × 14 = (22/7) × 64 × 14। चूँकि 14/7 = 2, यह 22 × 64 × 2 = 44 × 64 = 2816 cm³ है। पहले 7 को 14 से काट देने पर गणना सरल रहती है। आयतन को वक्र पृष्ठीय क्षेत्रफल 2πrh से न मिलाएँ, जो यहाँ 704 cm² है।"},{"id":"c24s2-65","p":"c24s2","n":65,"s":"qa","t":"Percentage, Profit & Interest","q":"A person earns ₹16,000 per month and spends 80% of his income and saves the remaining amount. If his income increases by 20% and expenditure by 10%, find the percentage of increase in his savings.","w":"Income ₹16,000; expenditure 80% = ₹12,800; savings = ₹3,200. New income = 1.2 × 16,000 = ₹19,200; new expenditure = 1.1 × 12,800 = ₹14,080; new savings = 19,200 − 14,080 = ₹5,120. Increase = 5,120 − 3,200 = ₹1,920, which is 1,920/3,200 × 100 = 60% of the old savings. With income taken as 100: savings rise from 20 to 120 − 88 = 32, again a 60% rise.","o":["90%","120%","140%","60%"],"a":[3],"qt":"एक व्यक्ति प्रति माह ₹16,000 कमाता है और अपनी आय का 80% खर्च करता है और शेष राशि की बचत करता है। यदि उसकी आय में 20% और खर्च में 10% की वृद्धि हो जाती है, तो उसकी बचत में प्रतिशत वृद्धि की गणना करें।","ot":["90%","120%","140%","60%"],"wt":"आय ₹16,000; खर्च 80% = ₹12,800; बचत = ₹3,200। नई आय = 1.2 × 16,000 = ₹19,200; नया खर्च = 1.1 × 12,800 = ₹14,080; नई बचत = 19,200 − 14,080 = ₹5,120। वृद्धि = 5,120 − 3,200 = ₹1,920, जो पुरानी बचत का 1,920/3,200 × 100 = 60% है। आय को 100 मानने पर: बचत 20 से बढ़कर 120 − 88 = 32 हो जाती है, यानी फिर से 60% वृद्धि।"},{"id":"c24s2-66","p":"c24s2","n":66,"s":"qa","t":"Percentage, Profit & Interest","q":"The marked price of an article is 26% more than its cost price. If a discount of 32% is given, what will be the loss percentage?","w":"Let the cost price be 100. Marked price = 126. After a 32% discount the selling price = 68% of 126 = 85.68. Loss = 100 − 85.68 = 14.32 on a cost price of 100, i.e. 14.32%. By the successive-change formula: 26 − 32 + (26 × −32)/100 = −6 − 8.32 = −14.32%. Simply subtracting (32 − 26 = 6%) ignores that the discount is taken on the higher marked price.","o":["12.26%","15.25%","18.64%","14.32%"],"a":[3],"qt":"एक वस्तु का अंकित मूल्य उसके क्रय मूल्य से 26% अधिक है। यदि 32% की छूट दी जाती है, तो हानि प्रतिशत क्या होगा?","ot":["12.26%","15.25%","18.64%","14.32%"],"wt":"मान लीजिए क्रय मूल्य 100 है। अंकित मूल्य = 126। 32% छूट के बाद विक्रय मूल्य = 126 का 68% = 85.68। हानि = 100 − 85.68 = 14.32, क्रय मूल्य 100 पर, अर्थात 14.32%। क्रमागत परिवर्तन सूत्र से: 26 − 32 + (26 × −32)/100 = −6 − 8.32 = −14.32%। केवल घटा देना (32 − 26 = 6%) इस बात की उपेक्षा करता है कि छूट बढ़े हुए अंकित मूल्य पर दी जाती है।"},{"id":"c24s2-67","p":"c24s2","n":67,"s":"qa","t":"Time, Work, Speed & Distance","q":"Varun and Sandeep started for a car race from the same point, in the same direction and at the same time on a circular track of length 1635 m with the speeds of 90 km/h and 108 km/h, respectively. After how much time (in s) will they meet again for the first time?","w":"Convert to m/s: 90 km/h = 90 × 5/18 = 25 m/s and 108 km/h = 108 × 5/18 = 30 m/s. Moving in the same direction, Sandeep gains 30 − 25 = 5 m/s on Varun. They meet again when he has gained one full lap of 1635 m, which takes 1635/5 = 327 s. Check: in 327 s Varun covers 8175 m (5 laps) and Sandeep 9810 m (6 laps).","o":["327","325","324","326"],"a":[0],"qt":"वरुण और संदीप ने एक कार रेस के लिए एक ही बिंदु से, एक ही दिशा में और एक ही समय में 1635 m लंबाई के एक वृत्ताकार ट्रैक पर क्रमशः 90 km/h और 108 km/h की चाल से शुरुआत की। कितने समय बाद (s में) वे पहली बार फिर से मिलेंगे?","ot":["327","325","324","326"],"wt":"m/s में बदलें: 90 km/h = 90 × 5/18 = 25 m/s और 108 km/h = 108 × 5/18 = 30 m/s। एक ही दिशा में चलते हुए संदीप, वरुण से हर सेकंड 30 − 25 = 5 m आगे निकलता है। वे फिर तब मिलेंगे जब संदीप वरुण से 1635 m का एक पूरा चक्कर अधिक लगा ले, जिसमें 1635/5 = 327 s लगते हैं। जाँच: 327 s में वरुण 8175 m (5 चक्कर) और संदीप 9810 m (6 चक्कर) चलता है।"},{"id":"c24s2-68","p":"c24s2","n":68,"s":"qa","t":"Geometry","q":"The angles of triangle are such that one is average of other two, then the angles are:\n1) π/6, π/3, π/2\n2) π/3, π/3, π/2\n3) π/6, π/3, π/4\n4) π/2, π/2, π/3","w":"If one angle is the average of the other two, those two add up to twice it, so the three angles total three times it; as the angles of a triangle add up to π, that angle must be π/3 (60°). Set 1 fits: π/6 + π/3 + π/2 = π and π/3 = (π/6 + π/2)/2, i.e. 30°, 60° and 90°. Set 2 adds up to 7π/6, set 3 to 3π/4 and set 4 to 4π/3, so none of them can be the angles of a triangle. Hence the answer is 1 (set 1).","o":["3","1","4","2"],"a":[1],"qt":"त्रिभुज के कोण इस प्रकार हैं कि एक कोण अन्य दो कोणों का औसत है, तो कोण निम्नलिखित में से कौन-से होंगे?\n1) π/6, π/3, π/2\n2) π/3, π/3, π/2\n3) π/6, π/3, π/4\n4) π/2, π/2, π/3","ot":["3","1","4","2"],"wt":"यदि एक कोण अन्य दो कोणों का औसत है, तो उन दोनों का योग उस कोण का दोगुना होता है, अतः तीनों कोणों का योग उसका तीन गुना है; त्रिभुज के कोणों का योग π है, इसलिए वह कोण π/3 (60°) होना चाहिए। समूह 1 सही बैठता है: π/6 + π/3 + π/2 = π और π/3 = (π/6 + π/2)/2, अर्थात 30°, 60° और 90°। समूह 2 का योग 7π/6, समूह 3 का 3π/4 और समूह 4 का 4π/3 है, अतः इनमें से कोई भी त्रिभुज के कोण नहीं हो सकते। अतः उत्तर 1 (समूह 1) है।"},{"id":"c24s2-69","p":"c24s2","n":69,"s":"qa","t":"Mensuration","q":"From a circle with the radius of 15.75 cm, a sector with the arc length of 11 cm is cut off. Find the area (in cm²) of this sector.","w":"Area of a sector = ½ × arc length × radius, because the area is (θ/2)r² and the arc length is l = rθ (θ in radians). Here area = ½ × 11 × 15.75 = 5.5 × 15.75 = 86.625 cm². Neither the central angle nor a value of π is needed. Check: θ = 11/15.75 radian, and (θ/2) × 15.75² = 5.5 × 15.75 = 86.625 cm².","o":["86.625","86.875","86.525","86.125"],"a":[0],"qt":"15.75 cm त्रिज्या वाले एक वृत्त से 11 cm की चाप लंबाई वाला त्रिज्यखंड काटा जाता है। इस त्रिज्यखंड का क्षेत्रफल (cm² में) ज्ञात कीजिए।","ot":["86.625","86.875","86.525","86.125"],"wt":"त्रिज्यखंड का क्षेत्रफल = ½ × चाप की लंबाई × त्रिज्या, क्योंकि क्षेत्रफल (θ/2)r² है और चाप की लंबाई l = rθ है (θ रेडियन में)। यहाँ क्षेत्रफल = ½ × 11 × 15.75 = 5.5 × 15.75 = 86.625 cm²। न केंद्रीय कोण की आवश्यकता है, न π के मान की। जाँच: θ = 11/15.75 रेडियन, और (θ/2) × 15.75² = 5.5 × 15.75 = 86.625 cm²।"},{"id":"c24s2-70","p":"c24s2","n":70,"s":"qa","t":"Data Interpretation & Statistics","q":"The given bar graph shows the number of students enrolled in Institutes A and B during 5 years (2018 to 2022).\nWhat is the ratio of the total students enrolled in Institute B in 2019, 2020 and 2022 to that of the total students enrolled in Institute A in 2018, 2020 and 2021?","w":"Read the bars: Institute A has 150, 275, 300, 250 and 225 students and Institute B has 210, 350, 375, 300 and 200 students in 2018–2022. B in 2019, 2020 and 2022 = 350 + 375 + 200 = 925. A in 2018, 2020 and 2021 = 150 + 300 + 250 = 700. Ratio = 925 : 700 = 37 : 28 (dividing by 25). The order matters: B's total comes first, so the reverse 28 : 37 is the trap.","img":"data:image/png;base64,","o":["11 : 28","28 : 37","37 : 28","28 : 11"],"a":[2],"qt":"दिया गया बार ग्राफ 5 वर्षों (2018 से 2022) के दौरान संस्थान A और B में नामांकित छात्रों की संख्या को दर्शाता है।\n2019, 2020 और 2022 में संस्थान B में नामांकित छात्रों की कुल संख्या और 2018, 2020 और 2021 में संस्थान A में नामांकित छात्रों की कुल संख्या का अनुपात ज्ञात करें।","ot":["11 : 28","28 : 37","37 : 28","28 : 11"],"wt":"बार पढ़ें: 2018–2022 में संस्थान A में 150, 275, 300, 250 और 225 छात्र हैं तथा संस्थान B में 210, 350, 375, 300 और 200 छात्र। 2019, 2020 और 2022 में B = 350 + 375 + 200 = 925। 2018, 2020 और 2021 में A = 150 + 300 + 250 = 700। अनुपात = 925 : 700 = 37 : 28 (25 से भाग देकर)। क्रम महत्त्वपूर्ण है: B का योग पहले आता है, इसलिए उलटा अनुपात 28 : 37 एक जाल है।"},{"id":"c24s2-71","p":"c24s2","n":71,"s":"qa","t":"Data Interpretation & Statistics","q":"The given chart shows the production of different types of cars in the year 2021. Study the given chart and answer the question that follows.\nIf the total production in the year 2021 was 2,00,00,000, then what will be the central angle of the sector representing the production of type D cars in 2021?","w":"The pie chart gives the shares A 10%, B 20%, C 10%, D 20% and E 40%. In a pie chart the central angle of a sector = (percentage/100) × 360°. Type D has 20%, so its angle = 20/100 × 360° = 72°. The total production of 2,00,00,000 is not needed, because the angle depends only on the share (D = 40,00,000 cars). 36° would be the angle for a 10% type such as A or C.","img":"data:image/png;base64,","o":["50°","42°","36°","72°"],"a":[3],"qt":"दिया गया चार्ट वर्ष 2021 में विभिन्न प्रकार की कारों के उत्पादन को दर्शाता है। दिए गए चार्ट का अध्ययन कीजिए और दिए गए प्रश्न का उत्तर दीजिए।\nDistribution of production of cars = कारों के उत्पादन का बंटन\nयदि वर्ष 2021 में कुल उत्पादन 2,00,00,000 था, तो 2021 में D किस्म की कारों के उत्पादन को निरूपित करने वाले क्षेत्र का केंद्रीय कोण क्या होगा?","ot":["50°","42°","36°","72°"],"wt":"पाई चार्ट के अनुसार हिस्से हैं: A 10%, B 20%, C 10%, D 20% और E 40%। पाई चार्ट में किसी क्षेत्र का केंद्रीय कोण = (प्रतिशत/100) × 360°। D का हिस्सा 20% है, अतः उसका कोण = 20/100 × 360° = 72°। कुल उत्पादन 2,00,00,000 की आवश्यकता नहीं है, क्योंकि कोण केवल हिस्से पर निर्भर करता है (D = 40,00,000 कारें)। 36° किसी 10% वाले प्रकार, जैसे A या C, का कोण होता।"},{"id":"c24s2-72","p":"c24s2","n":72,"s":"qa","t":"Ratio, Average & Mixtures","q":"If x varies inversely as y and x = 2 when y = 6, then the value of y when x = 3 is:","w":"If x varies inversely as y, their product is constant: xy = k. From x = 2 and y = 6, k = 12. When x = 3, y = 12/3 = 4. Check: x grows from 2 to 3 (× 1.5) while y falls from 6 to 4 (÷ 1.5), as inverse variation requires. Direct variation (y/x constant) would instead give y = 9, which is not among the options.","o":["3","4","2","6"],"a":[1],"qt":"यदि x, y के व्युत्क्रमानुपाती है और y = 6 होने पर x = 2 है, तो x = 3 होने पर y का मान क्या होगा?","ot":["3","4","2","6"],"wt":"यदि x, y के व्युत्क्रमानुपाती है, तो उनका गुणनफल स्थिर रहता है: xy = k। x = 2 और y = 6 से k = 12। x = 3 होने पर y = 12/3 = 4। जाँच: x, 2 से बढ़कर 3 होता है (× 1.5) जबकि y, 6 से घटकर 4 होता है (÷ 1.5), जैसा व्युत्क्रम अनुपात में होना चाहिए। अनुक्रमानुपात (y/x स्थिर) से y = 9 आता, जो विकल्पों में नहीं है।"},{"id":"c24s2-73","p":"c24s2","n":73,"s":"qa","t":"Number System & Simplification","q":"Without doing the actual division, find the remainder when 28735429 is divided by 9.","w":"A number leaves the same remainder on division by 9 as the sum of its digits. Digit sum of 28735429 = 2 + 8 + 7 + 3 + 5 + 4 + 2 + 9 = 40, and 40 = 4 × 9 + 4, so the remainder is 4 (again, 4 + 0 = 4). Check: 9 × 3192825 = 28735425, and 28735429 − 28735425 = 4. Option 9 is impossible, since a remainder on division by 9 must be less than 9.","o":["4","8","2","9"],"a":[0],"qt":"जब 28735429 को 9 से विभाजित किया जाता है, तो वास्तविक विभाजन किए बिना शेषफल ज्ञात कीजिए।","ot":["4","8","2","9"],"wt":"किसी संख्या को 9 से भाग देने पर वही शेषफल बचता है जो उसके अंकों के योग को 9 से भाग देने पर बचता है। 28735429 के अंकों का योग = 2 + 8 + 7 + 3 + 5 + 4 + 2 + 9 = 40, और 40 = 4 × 9 + 4, अतः शेषफल 4 है (फिर से अंकों का योग, 4 + 0 = 4)। जाँच: 9 × 3192825 = 28735425, और 28735429 − 28735425 = 4। विकल्प 9 असंभव है, क्योंकि 9 से भाग देने पर शेषफल 9 से कम होना चाहिए।"},{"id":"c24s2-74","p":"c24s2","n":74,"s":"qa","t":"Number System & Simplification","q":"Simplify the following:\n21 − 4.9 ÷ 7 + 3.9 × 0.4 + 0.9","w":"Follow BODMAS: division and multiplication come before addition and subtraction. 4.9 ÷ 7 = 0.7 and 3.9 × 0.4 = 1.56. The expression becomes 21 − 0.7 + 1.56 + 0.9 = 20.3 + 1.56 + 0.9 = 22.76. Working strictly from left to right, for example (21 − 4.9) ÷ 7, ignores the order of operations and gives a wrong value.","o":["26.32","18.23","22.76","24.12"],"a":[2],"qt":"निम्नलिखित का सरलीकरण करें:\n21 − 4.9 ÷ 7 + 3.9 × 0.4 + 0.9","ot":["26.32","18.23","22.76","24.12"],"wt":"BODMAS का पालन करें: भाग और गुणा, जोड़ और घटाव से पहले किए जाते हैं। 4.9 ÷ 7 = 0.7 और 3.9 × 0.4 = 1.56। व्यंजक बन जाता है 21 − 0.7 + 1.56 + 0.9 = 20.3 + 1.56 + 0.9 = 22.76। केवल बाएँ से दाएँ हल करना, जैसे (21 − 4.9) ÷ 7, संक्रियाओं के क्रम की उपेक्षा करता है और गलत मान देता है।"},{"id":"c24s2-75","p":"c24s2","n":75,"s":"qa","t":"Time, Work, Speed & Distance","q":"Pipes M, N and S can fill a tank in 25, 50 and 100 minutes, respectively. Initially, pipes N and S are kept open for 10 minutes, and then pipe N is shut while pipe M is opened. Pipe S is closed 15 minutes before the tank overflows. How much time (in minutes) will it take to fill the tank if the three pipes work in this pattern?","w":"Take the tank as 100 units (LCM of 25, 50 and 100): M fills 4, N 2 and S 1 unit per minute. First 10 minutes, N + S: 10 × 3 = 30 units. Last 15 minutes, M alone: 15 × 4 = 60 units. In between, M + S fill the remaining 100 − 30 − 60 = 10 units at 5 units per minute, which takes 2 minutes. Total time = 10 + 2 + 15 = 27 minutes.","o":["27","42","30","33"],"a":[0],"qt":"पाइप M, N और S एक टैंक को क्रमशः 25, 50 और 100 मिनट में भर सकते हैं। प्रारंभ में, पाइप N और S को 10 मिनट के लिए खुला रखा जाता है, और फिर पाइप N को बंद कर दिया जाता है जबकि पाइप M को खोल दिया जाता है। टैंक में अतिप्रवाह होने से 15 मिनट पहले पाइप S को बंद कर दिया जाता है। यदि तीनों पाइप इस पैटर्न में कार्य करें तो टैंक को भरने में कितना समय (मिनट में) लगेगा?","ot":["27","42","30","33"],"wt":"टैंक की क्षमता 100 इकाई मानें (25, 50 और 100 का LCM): M प्रति मिनट 4, N 2 और S 1 इकाई भरता है। पहले 10 मिनट, N + S: 10 × 3 = 30 इकाई। अंतिम 15 मिनट, केवल M: 15 × 4 = 60 इकाई। बीच में M + S शेष 100 − 30 − 60 = 10 इकाई 5 इकाई प्रति मिनट की दर से भरते हैं, जिसमें 2 मिनट लगते हैं। कुल समय = 10 + 2 + 15 = 27 मिनट।"},{"id":"c24s2-76","p":"c24s2","n":76,"s":"eng","t":"Voice & Narration","q":"Select the option that expresses the given sentence in active voice.\nThe homework must be done by you.","w":"In the passive sentence 'The homework' receives the action and 'you' (after 'by') is the doer. The verb 'must be done' is a modal passive (modal + be + past participle), so the active form keeps the same modal with the base form of the verb: 'You must do the homework.' Option 1 changes the modal to 'will', option 2 changes it to 'should have done', and option 4 drops the modal altogether, so all three alter the meaning of obligation.","o":["You will do the homework.","You should have done the homework.","You must do the homework.","You do the homework."],"a":[2]},{"id":"c24s2-77","p":"c24s2","n":77,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Select the most appropriate option to substitute the underlined word in the given sentence.\nPollution levels have increased so \"largely\" that they are almost killing us.","w":"'Largely' means mainly or for the most part, as in 'The audience was largely young'; it does not describe how much something has risen. The sentence needs an adverb of degree with 'so ... that', and 'highly' (to a high degree) gives this sense: 'Pollution levels have increased so highly that they are almost killing us.' 'Primarily' and 'chiefly' also mean mainly, the same flaw as largely, and 'slowly' contradicts the idea of a rise that is almost killing us.","o":["primarily","slowly","highly","chiefly"],"a":[2]},{"id":"c24s2-78","p":"c24s2","n":78,"s":"eng","t":"Sentence Arrangement","q":"Parts of a sentence are given below in jumbled order. Arrange the parts in the correct order to form a meaningful sentence.\n(a) the use of animal research\n(b) throughout the past century\n(c) and it continues to be used to understand many diseases\n(d) has been of considerable importance\n(e) in the field of scientific and medical advancements","w":"The subject is (a) 'the use of animal research', followed by its verb (d) 'has been of considerable importance'. (e) 'in the field of scientific and medical advancements' says where, and (b) 'throughout the past century' says when. (c) 'and it continues to be used to understand many diseases' adds a second clause in which 'it' refers back to the use of animal research, so it comes last: adebc. Options 1 and 3 begin with (e), which cannot be a subject, and option 2 puts (c) before the main verb (d).","o":["edcba","aecdb","ecdba","adebc"],"a":[3]},{"id":"c24s2-79","p":"c24s2","n":79,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the most appropriate meaning of the given idiom.\nBreak a leg","w":"'Break a leg' is an informal expression used to wish someone good luck, especially a performer about to go on stage, as in 'Break a leg tonight!' It comes from the theatre, where wishing 'good luck' directly was traditionally thought to bring bad luck, so performers wished each other the opposite. It has nothing to do with physical health, taking a break from work or encouraging risky activities; those options read the words literally.","o":["Give advice on maintaining physical health.","Wish someone good luck before a performance.","Suggest taking a short break during work.","Encourage someone to engage in risky activities."],"a":[1]},{"id":"c24s2-80","p":"c24s2","n":80,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Select the most appropriate option that can substitute the underlined segment in the given sentence. If there is no need to substitute it, select ‘No substitution’.\nSpreading awareness about the rights of the consumers and the relief open to them in case they \"did not get their money’s worth\" of goods and service has rightly been identified as the first priority.","w":"The underlined part describes the situation in which relief is open to consumers: when they fail to receive full value for what they paid. 'Were unable to get their money's worth' states this failure most clearly, stressing that the consumers could not obtain the value they paid for. Option 2 is ungrammatical, since 'did' must be followed by the base form 'get', and option 3 is wrong because a clause with 'in case' does not take 'will'. The printed 'did not get' is itself grammatical, which is why 'No substitution' is also argued. (SSC key; some sources differ.)","o":["were unable to get their money’s worth","did not getting their money’s worth","will not get their money’s worth","No substitution"],"a":[0]},{"id":"c24s2-81","p":"c24s2","n":81,"s":"eng","t":"Spelling","q":"Select the INCORRECTLY spelt word.","w":"The incorrectly spelt word is 'Abismal'; the correct spelling is 'abysmal' (a-b-y-s-m-a-l), with a y, as in 'abyss', a very deep chasm. It means extremely bad or appalling, as in 'an abysmal performance'. The other words are spelt correctly: 'allocation' (double l, the distribution of resources), 'aversion' (a strong dislike) and 'allegation' (double l, a claim of wrongdoing made without proof).","o":["Allocation","Abismal","Aversion","Allegation"],"a":[1]},{"id":"c24s2-82","p":"c24s2","n":82,"s":"eng","t":"Vocabulary","q":"Select the most appropriate ANTONYM of the underlined word.\nIf you want to be a good detective, it helps to have an \"inquisitive\" nature.","w":"'Inquisitive' means curious, eager to know or learn, and fond of asking questions, a useful quality in a detective. Its antonym here is 'disinterested', used in the sense of not interested or indifferent (in careful usage this sense is expressed by 'uninterested', while disinterested means impartial). 'Intrusive' (prying, unwelcomely interfering) is close to inquisitive rather than opposite, 'comprehensive' means complete or including everything, and 'itemised' means listed item by item.","o":["Comprehensive","Itemised","Intrusive","Disinterested"],"a":[3]},{"id":"c24s2-83","p":"c24s2","n":83,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the option that can be used as a one-word substitute for the given group of words.\nOne who does not show response to good or bad","w":"A 'stoic' is a person who endures pain, hardship, good fortune or bad fortune calmly, without showing feelings or complaining. The word comes from the Stoic philosophers of ancient Greece, who taught that one should be free from passion and unmoved by pleasure or pain. A 'cynic' believes that people act only out of self-interest, a 'phobic' person has an irrational fear of something, and a 'sceptic' doubts accepted opinions or claims.","o":["Cynic","Phobic","Sceptic","Stoic"],"a":[3]},{"id":"c24s2-84","p":"c24s2","n":84,"s":"eng","t":"Sentence Arrangement","q":"Given below are four jumbled sentences. Select the option that gives their correct logical sequence.\nA. These can turn around to track stars with the rotation of Earth.\nB. Observatories are places to study place.\nC. They are mostly built on the mountain tops.\nD. Telescopes are placed in the dome-shaped roof of the building.","w":"B introduces the topic, observatories, so it comes first (the sheet prints 'study place', evidently for 'study space'). C follows, its 'They' standing for observatories. D then describes the building, saying telescopes are placed in its dome-shaped roof, and A comes last because 'These' refers to the telescopes, which turn to track stars as the Earth rotates. So the order is BCDA. The other options begin with C, D or A, each of which depends on an earlier sentence.","o":["DCBA","CBDA","BCDA","ACDB"],"a":[2]},{"id":"c24s2-85","p":"c24s2","n":85,"s":"eng","t":"Spelling","q":"Select the correctly spelled sentence.","w":"The correct spelling is 'definitely' (d-e-f-i-n-i-t-e-l-y), formed from 'definite' + -ly; it means without doubt or certainly. A useful tip is that the word contains 'finite'. 'Definetely' wrongly uses e in place of the second i, 'definately' wrongly uses a, which is the most common misspelling of the word, and 'definitly' drops the e of 'definite' before -ly.","o":["I will definitely attend the conference.","I will definetely attend the conference.","I will definately attend the conference.","I will definitly attend the conference."],"a":[0]},{"id":"c24s2-86","p":"c24s2","n":86,"s":"eng","t":"Sentence Arrangement","q":"Parts of a sentence are given below in jumbled order. Arrange the parts in the correct order to form a meaningful sentence.\n(O) as it was the last one of the evening\n(P) the city bus was overcrowded\n(Q) and this gave an opportunity\n(R) to the pickpockets\n(S) to try their skill","w":"The main clause is (P) 'the city bus was overcrowded'; (O) 'as it was the last one of the evening' gives the reason. (Q) 'and this gave an opportunity' adds the result, (R) 'to the pickpockets' says who got the opportunity, and (S) 'to try their skill' says what it was for. The sentence reads: 'The city bus was overcrowded as it was the last one of the evening and this gave an opportunity to the pickpockets to try their skill.' Options beginning with S cannot start the sentence, and PSORQ separates 'to try their skill' from 'opportunity'.","o":["PSORQ","SRPOQ","SROPQ","POQRS"],"a":[3]},{"id":"c24s2-87","p":"c24s2","n":87,"s":"eng","t":"Idioms & One-word Substitution","q":"Select the most appropriate option to substitute the underlined segment in the given sentence.\nRaju’s job as a clerk seemed to be \"bad at first because of the low salary, but resulted in something good happening later\" because it saved him from being unemployed.","w":"'A blessing in disguise' is an idiom for something that seems bad or unlucky at first but later turns out to be good. Raju's clerk job looked bad because of the low salary but proved good because it saved him from unemployment, so the idiom replaces the underlined description: 'Raju's job as a clerk seemed to be a blessing in disguise because it saved him from being unemployed.' Idioms have a fixed form, so 'boon', 'jolt' or 'gift' cannot take the place of 'blessing'.","o":["a blessing in disguise","a boon in disguise","a jolt in disguise","a gift in disguise"],"a":[0]},{"id":"c24s2-88","p":"c24s2","n":88,"s":"eng","t":"Vocabulary","q":"Identify the most appropriate antonym of the given word.\nScary","w":"'Scary' means frightening, causing fear or alarm, as in 'a scary film'. Its antonym among the options is 'comforting', meaning soothing, giving a feeling of ease, reassurance and safety. 'Awful' (very bad or unpleasant) is close to scary in tone rather than opposite, 'bright' (shining, or cheerful) is not a direct opposite, and 'pristine' means in its original, unspoiled condition, which is unrelated to fear.","o":["awful","bright","comforting","Pristine"],"a":[2]},{"id":"c24s2-89","p":"c24s2","n":89,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nAbundant","w":"'Abundant' means existing or available in large quantities, more than enough, as in 'abundant rainfall' or 'abundant natural resources'. Its synonym is 'ample', meaning enough or more than enough, plentiful. 'Scarce' (in short supply) is its antonym, 'barren' (unable to produce crops or fruit, bare) is opposite in sense, and 'difficult' (not easy) is unrelated in meaning.","o":["Ample","Difficult","Scarce","Barren"],"a":[0]},{"id":"c24s2-90","p":"c24s2","n":90,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the underlined word.\nI would love to \"organise\" the farewell party at my house.","w":"To 'organise' an event means to plan it and make the necessary preparations so that it takes place, as in organising a farewell party. Its synonym is 'arrange', which means to plan or put things in order in advance. 'Derange' means to throw into disorder or make insane, 'disorder' means a lack of order or confusion, and 'confuse' means to bewilder or mix up; all three are closer to the opposite of organise.","o":["Arrange","Derange","Disorder","Confuse"],"a":[0]},{"id":"c24s2-91","p":"c24s2","n":91,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"Parts of the following sentence have been given as options. Select the option that contains an error.\nEvery students in the hostel decided to travel to Delhi to witness the Republic Day parade.","w":"'Every' is followed by a singular countable noun, as in 'every student', 'every day' or 'every book', and it takes a singular verb. So 'Every students in the hostel' is wrong and should read 'Every student in the hostel': 'Every student in the hostel decided to travel to Delhi to witness the Republic Day parade.' 'All the students' or 'Each of the students' would also be correct. The other parts, 'decided to travel to Delhi', 'to witness the' and 'Republic Day Parade', contain no error.","o":["Republic Day Parade.","to witness the","Every students in the hostel","decided to travel to Delhi"],"a":[2]},{"id":"c24s2-92","p":"c24s2","n":92,"s":"eng","t":"Voice & Narration","q":"Select the option that expresses the given sentence in active voice.\nThe meal was not prepared by us.","w":"The passive 'The meal was not prepared by us' is in the simple past negative (was not + past participle). In the active voice the doer 'us' becomes the subject 'We', the object 'the meal' follows the verb, and the negative simple past is did not + base form: 'We did not prepare the meal.' Option 1 wrongly uses 'preparing' after 'did', option 2 drops 'not' and reverses the meaning, and option 4 uses 'had not prepare', where 'had' needs the participle 'prepared'.","o":["We did not preparing the meal.","We did prepare the meal.","We did not prepare the meal.","We had not prepare the meal."],"a":[2]},{"id":"c24s2-93","p":"c24s2","n":93,"s":"eng","t":"Vocabulary","q":"Select the most appropriate synonym of the given word.\nBerserk","w":"'Berserk' means wild, frenzied or out of control, especially with anger or excitement; to 'go berserk' is to become violently uncontrollable. The word comes from the berserkers, Norse warriors said to fight in a wild frenzy. Its closest synonym here is 'demented', meaning behaving irrationally or wildly, as if mad. 'Stubborn' means obstinate, 'absurd' means ridiculous or unreasonable, and 'lazy' means unwilling to work, so none of them fits.","o":["Stubborn","Demented","Absurd","Lazy"],"a":[1]},{"id":"c24s2-94","p":"c24s2","n":94,"s":"eng","t":"Error Spotting & Sentence Improvement","q":"The following sentence has been split into four segments. Identify the segment that contains a grammatical error.\nBy this time next year / I will had graduated from college / and starting my first job / in the field of marketing.","w":"'By this time next year' refers to an action that will be completed before a point in the future, which needs the future perfect tense: will + have + past participle. 'Will had graduated' is wrong because a modal such as 'will' must be followed by the base form 'have', never by 'had'. Corrected: 'By this time next year I will have graduated from college and (will be) starting my first job in the field of marketing.' 'And starting my first job' is only loosely parallel, but the clear error is 'will had'.","o":["in the field of marketing","By this time next year","I will had graduated from college","and starting my first job"],"a":[2]},{"id":"c24s2-95","p":"c24s2","n":95,"s":"eng","t":"Vocabulary","q":"Select the most appropriate ANTONYM of the word in bold.\nElisabeth stood at the piano, which did nothing to \"allay\" his anxiety.","w":"The sheet prints the whole sentence in bold, so the tested word is not marked; it can only be 'allay', the word whose synonyms and antonym appear in the options. 'Allay' means to reduce or put to rest a fear, worry or suspicion, as in 'to allay his anxiety'. Its antonym is 'aggravate', meaning to make a problem or feeling worse or more serious. 'Mitigate' (make less severe) and 'mollify' (calm or soothe) are synonyms of allay, and 'simplify' (make easier) is unrelated.","o":["aggravate","mitigate","simplify","mollify"],"a":[0]},{"id":"c24s2-96","p":"c24s2","n":96,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nFrom the beginning (1)______ the eighteenth century, the ladies of European cities covered (2)______ faces in layers of paint and powder. This particular fashion was largely brought (3) ______ by the urgent need to disguise the ravages of smallpox, (4)______ left their faces pitted and scarred. During this same period, the ‘beauty spot’ was introduced to cover (5) ______ a facial defect.\nSelect the most appropriate option to fill in blank number 1.","w":"'The beginning of the eighteenth century' uses 'of' to link the beginning to the period it belongs to, just as in 'the end of the year' or 'the start of the war'. So 'From the beginning of the eighteenth century' means from the early 1700s onwards. 'About' (concerning or approximately), 'in' and 'on' cannot link 'beginning' to the century: 'the beginning about, in or on the eighteenth century' is not idiomatic English.","o":["about","in","on","of"],"a":[3]},{"id":"c24s2-97","p":"c24s2","n":97,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nFrom the beginning (1)______ the eighteenth century, the ladies of European cities covered (2)______ faces in layers of paint and powder. This particular fashion was largely brought (3) ______ by the urgent need to disguise the ravages of smallpox, (4)______ left their faces pitted and scarred. During this same period, the ‘beauty spot’ was introduced to cover (5) ______ a facial defect.\nSelect the most appropriate option to fill in blank number 2.","w":"The blank stands before the noun 'faces', so it needs a possessive determiner; the ladies covered their own faces, so 'their' (belonging to them) is correct: 'the ladies of European cities covered their faces in layers of paint and powder.' 'They're' is the contraction of 'they are', 'there' is an adverb of place or an introductory word (there is), and 'them' is an object pronoun that cannot qualify a noun. Their, they're and there sound alike and are often confused.","o":["they’re","their","there","them"],"a":[1]},{"id":"c24s2-98","p":"c24s2","n":98,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nFrom the beginning (1)______ the eighteenth century, the ladies of European cities covered (2)______ faces in layers of paint and powder. This particular fashion was largely brought (3) ______ by the urgent need to disguise the ravages of smallpox, (4)______ left their faces pitted and scarred. During this same period, the ‘beauty spot’ was introduced to cover (5) ______ a facial defect.\nSelect the most appropriate option to fill in blank number 3.","w":"'Bring about' is a phrasal verb meaning to cause something to happen. In the passive, 'This particular fashion was largely brought about by the urgent need to disguise the ravages of smallpox' means the fashion of painted faces was caused mainly by the need to hide smallpox scars. 'Brought within' and 'brought to' make no sense here, and 'bring around' means to persuade someone or to revive a person who has fainted, which does not fit a fashion.","o":["within","about","around","to"],"a":[1]},{"id":"c24s2-99","p":"c24s2","n":99,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nFrom the beginning (1)______ the eighteenth century, the ladies of European cities covered (2)______ faces in layers of paint and powder. This particular fashion was largely brought (3) ______ by the urgent need to disguise the ravages of smallpox, (4)______ left their faces pitted and scarred. During this same period, the ‘beauty spot’ was introduced to cover (5) ______ a facial defect.\nSelect the most appropriate option to fill in blank number 4.","w":"The blank begins a relative clause about 'smallpox', the disease that left the ladies' faces pitted and scarred. Because the clause follows a comma and only adds information (a non-defining relative clause), and smallpox is a thing, the relative pronoun must be 'which': '...the ravages of smallpox, which left their faces pitted and scarred.' 'That' is not used after a comma in a non-defining clause, 'who' is used for people, and 'when' refers to time.","o":["which","that","when","who"],"a":[0]},{"id":"c24s2-100","p":"c24s2","n":100,"s":"eng","t":"Fill in the Blanks & Cloze Test","q":"In the following passage, some words have been deleted. Read the passage carefully and select the most appropriate option to fill in each blank.\nFrom the beginning (1)______ the eighteenth century, the ladies of European cities covered (2)______ faces in layers of paint and powder. This particular fashion was largely brought (3) ______ by the urgent need to disguise the ravages of smallpox, (4)______ left their faces pitted and scarred. During this same period, the ‘beauty spot’ was introduced to cover (5) ______ a facial defect.\nSelect the most appropriate option to fill in blank number 5.","w":"'Cover up' is a phrasal verb meaning to hide or conceal something completely, especially a fault, mark or mistake. The 'beauty spot', a small dark patch worn on the face, was introduced to cover up a facial defect such as a smallpox scar, in keeping with the passage's theme of disguising the ravages of smallpox. 'Cover for' means to stand in for someone or to make excuses for them, while 'cover to' and 'cover on' are not used in this sense.","o":["to","for","up","on"],"a":[2]}],"instagram":"learn_with_anil06","site":"https://learnwithanil.in","notes":[],"wa":"919494792739","key":"ssc-cgl","exam":"SSC CGL","bahubali":"","examShort":"SSC CGL","papersNote":"Every paper is SSC's own question paper as candidates print it from SSC's portal (the response sheet), with the answer SSC marked as correct. The Tier-I sheets are from the answer-key stage, so SSC's final key may differ for a few questions. Each shift had a different paper. English Comprehension is in English only; every other question is in English and Hindi, as printed.","hub":false,"board":"SSC","l2":{"code":"hi","label":"हिंदी","name":"Hindi","font":"Noto Sans Devanagari"},"base":"ssc-cgl/","qotd":[],"pay":{"on":true,"api":"https://script.google.com/macros/s/AKfycbxgNi2CfnbaEsVpA1Ghgy0AdYdUG7eYBkol5zqcbMgA2Q4D0Pvy0rndLxeyE7MlPy_3Rg/exec","exam":"ssc-cgl","pyq":{"price":45,"valid":"valid for 12 months from the day you pay, on every exam","exams":"APPSC Group 2, APPSC Group 1, UPSC CAPF AC, UPSC EPFO, SSC CGL, TS Police SI, TS Police Constable, TGPSC HMWSSB Manager","trial":0},"mock":{"id":"mk-cgl","name":"Mission CGL","title":"Mission CGL – SSC CGL Mock Test Series (Tier-I & Tier-II)","price":149,"n":13,"live":2,"valid":"Valid for 12 months","mocks":[{"id":"mk-cgl-t1-1","name":"Tier-I Mock 1","mins":60,"live":true,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-2","name":"Tier-I Mock 2","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-3","name":"Tier-I Mock 3","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-4","name":"Tier-I Mock 4","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-5","name":"Tier-I Mock 5","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-6","name":"Tier-I Mock 6","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-7","name":"Tier-I Mock 7","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-8","name":"Tier-I Mock 8","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-9","name":"Tier-I Mock 9","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t1-10","name":"Tier-I Mock 10","mins":60,"live":false,"parts":[["rea","Reasoning",["rea"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["qa","Quantitative Aptitude",["qa"]],["eng","English",["eng"]]]},{"id":"mk-cgl-t2-1","name":"Tier-II Mock 1","mins":135,"live":true,"parts":[["qa","Mathematical Abilities",["qa"]],["rea","Reasoning",["rea"]],["eng","English",["eng"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["comp","Computer Knowledge",["comp"]]]},{"id":"mk-cgl-t2-2","name":"Tier-II Mock 2","mins":135,"live":false,"parts":[["qa","Mathematical Abilities",["qa"]],["rea","Reasoning",["rea"]],["eng","English",["eng"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["comp","Computer Knowledge",["comp"]]]},{"id":"mk-cgl-t2-3","name":"Tier-II Mock 3","mins":135,"live":false,"parts":[["qa","Mathematical Abilities",["qa"]],["rea","Reasoning",["rea"]],["eng","English",["eng"]],["ga","General Awareness",["ih","pol","geo","eco","sci","cur"]],["comp","Computer Knowledge",["comp"]]]}]},"pages":{"pyq":"/ssc-cgl/pyqs.html","mock":"/ssc-cgl/mock-test.html","sec":"/ssc-cgl/sectional-tests.html"},"sample":10},"exams":[],"cats":[],"timers":[],"pb":"/ssc-cgl/","qpages":true,"examSeo":"SSC CGL","homeTitle":"SSC CGL Previous Year Question Papers with Answers – Tier 1 & Tier 2 2023–2025, English & Hindi | Learn with Anil","hubTitle":"PYQs with Answers – APPSC Group 1 & 2, TS Police SI & Constable, UPSC CAPF & EPFO Previous Papers | Learn with Anil"};
